(function(){"use strict";var w=window.ScripturaJosephusTexts||(window.ScripturaJosephusTexts={});var a=w.antiguidades||(w.antiguidades={});a[1]={"book":1,"title":"Τάδε ἔνεστιν ἐν τῇ πρώτῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"Προοίμιον περὶ τῆς ὅλης πραγματείας.","text":"α. ἡ τοῦ κόσμου σύστασις καὶ διάταξις τῶν στοιχείων.\n\nβ. περὶ τοῦ γένους Ἀδάμου καὶ τῶν ἀπ' αὐτοῦ δέκα γενεῶν τῶν μέχρι τοῦ κατακλυσμοῦ.\n\nγ. ὡς ὁ κατακλυσμὸς ἐγένετο καὶ ὃν τρόπον Νῶχος σωθεὶς ἐν λάρνακι μετὰ τῶν συγγενῶν κατῴκησεν ἐν τῷ Σινάρῳ πεδίῳ.\n\nδ. ὡς πύργος, ὃν οἱ παῖδες αὐτοῦ ἐφ' ὕβρει τοῦ θεοῦ ᾠκοδόμησαν, καὶ ὡς τὰς φωνὰς αὐτῶν μετέβαλε καὶ ὁ τόπος, ἐν ᾧ τοῦτο γέγονε, Βαβυλὼν ἐκλήθη.\n\nε. ὡς οἱ Νώχου ἔγγονοι πᾶσαν τὴν οἰκουμένην ἐπῴκησαν.\n\nϛ. ὅτι τῶν ἐθνῶν ἕκαστον ἀπὸ τῶν οἰκισάντων προσηγορεύθη.\n\nζ. ὅπως Ἅβραμος ὁ πρόγονος ἡμῶν ἐξελθὼν ἐκ τῆς Χαλδαίων γῆς κατέσχε τὴν τότε μὲν Χαναναίαν νῦν δὲ Ἰουδαίαν λεγομένην.\n\nη. ὅτι λιμοῦ τὴν Χαναναίαν καταλαβόντος εἰς Αἴγυπτον ἀπῆρε καὶ διατρίψας ἐν αὐτῇ τινα χρόνον ὑπέστρεψεν ὀπίσω.\n\nθ. ἧττα Σοδομιτῶν Ἀσσυρίων αὐτοῖς ἐπιστρατευσάντων.\n\nι. ὡς Ἅβραμος ἐπὶ τοὺς Ἀσσυρίους ἐκστρατεύσας ἐνίκησε καὶ τοὺς αἰχμαλώτους τῶν Σοδομιτῶν ἔσωσε καὶ τὴν λείαν ἣν ἔλαβον ἀφείλετο.\n\nια. πῶς τὸ Σοδομιτῶν ἔθνος θεὸς κατεστρέψατο χολωθεὶς αὐτοῖς ἐφ' οἷς ἡμάρτανον.\n\nιβ. περὶ Ἰσμαήλου τοῦ Ἁβράμου καὶ τῶν ἐγγόνων αὐτοῦ Ἀράβων.\n\nιγ. περὶ Ἰσάκου, ὃς ἦν γνήσιος παῖς Ἁβράμου.\n\nιδ. περὶ Σάρρας τῆς Ἁβράμου γυναικός, καὶ πῶς τὸν βίον κατέστρεψεν.\n\nιε. ὡς ἐκ Κατούρης Ἁβράμῳ γαμηθείσης τὸ τῶν Τρωγλοδυτῶν Ἀράβων ἔθνος ἐγεννήθη.\n\nιϛ. περὶ τῆς Ἁβράμῳ τελευτῆς.\n\nιζ . περὶ τῆς Ἰσάκου παίδων Ἡσαῦ καὶ Ἰακώβου γενέσεως καὶ διατροφῆς.\n\nιη. Ἰακώβου φυγὴ εἰς τὴν Μεσοποταμίαν καὶ τὸν ἐκ τἀδελφοῦ φόβον, καὶ ὡς γήμας ἐκεῖ καὶ δώδεκα γεννήσας παῖδας πάλιν εἰς τὴν Χαναναίαν ἐπανῆλθεν.\n\nιθ. ὡς Ἴσακος τελευτήσας ἐτάφη ἐν Νεβρῶνι.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν ὡς Ἰώσηπος ͵γη, Ἑβραῖοι ͵αωοβ, Εὐσέβιος ͵γυνθ."},"chapters":{"0":[{"number":1,"text":"Τοῖς τὰς ἱστορίας συγγράφειν βουλομένοις οὐ μίαν οὐδὲ τὴν αὐτὴν ὁρῶ τῆς σπουδῆς γινομένην αἰτίαν, ἀλλὰ πολλὰς καὶ πλεῖστον ἀλλήλων διαφερούσας."},{"number":2,"text":"τινὲς μὲν γὰρ ἐπιδεικνύμενοι λόγων δεινότητα καὶ τὴν ἀπʼ αὐτῆς θηρευόμενοι δόξαν ἐπὶ τοῦτο τῆς παιδείας τὸ μέρος ὁρμῶσιν, ἄλλοι δὲ χάριν ἐκείνοις φέροντες, περὶ ὧν τὴν ἀναγραφὴν εἶναι συμβέβηκε, τὸν εἰς αὐτὴν πόνον καὶ παρὰ δύναμιν ὑπέστησαν·"},{"number":3,"text":"εἰσὶ δʼ οἵτινες ἐβιάσθησαν ὑπʼ αὐτῆς τῆς τῶν πραγμάτων ἀνάγκης οἷς πραττομένοις παρέτυχον ταῦτα γραφῇ δηλούσῃ περιλαβεῖν· πολλοὺς δὲ χρησίμων μέγεθος πραγμάτων ἐν ἀγνοίᾳ κειμένων προύτρεψε τὴν περὶ αὐτῶν ἱστορίαν εἰς κοινὴν ὠφέλειαν ἐξενεγκεῖν."},{"number":4,"text":"τούτων δὴ τῶν προειρημένων αἰτιῶν αἱ τελευταῖαι δύο κἀμοὶ συμβεβήκασι· τὸν μὲν γὰρ πρὸς τοὺς Ῥωμαίους πόλεμον ἡμῖν τοῖς Ἰουδαίοις γενόμενον καὶ τὰς ἐν αὐτῷ πράξεις καὶ τὸ τέλος οἷον ἀπέβη πείρᾳ μαθὼν ἐβιάσθην ἐκδιηγήσασθαι διὰ τοὺς ἐν τῷ γράφειν λυμαινομένους τὴν ἀλήθειαν,"},{"number":5,"text":"ταύτην δὲ τὴν ἐνεστῶσαν ἐγκεχείρισμαι πραγματείαν νομίζων ἅπασι φανεῖσθαι τοῖς Ἕλλησιν ἀξίαν σπουδῆς· μέλλει γὰρ περιέξειν ἅπασαν τὴν παρʼ ἡμῖν ἀρχαιολογίαν καὶ διάταξιν τοῦ πολιτεύματος ἐκ τῶν Ἑβραϊκῶν μεθηρμηνευμένην γραμμάτων."},{"number":6,"text":"ἤδη μὲν οὖν καὶ πρότερον διενοήθην, ὅτε τὸν πόλεμον συνέγραφον, δηλῶσαι τίνες ὄντες ἐξ ἀρχῆς Ἰουδαῖοι καὶ τίσι χρησάμενοι τύχαις ὑφʼ οἵῳ τε παιδευθέντες νομοθέτῃ τὰ πρὸς εὐσέβειαν καὶ τὴν ἄλλην ἄσκησιν ἀρετῆς πόσους τε πολέμους ἐν μακροῖς πολεμήσαντες χρόνοις εἰς τὸν τελευταῖον ἄκοντες πρὸς Ῥωμαίους κατέστησαν."},{"number":7,"text":"ἀλλʼ ἐπειδὴ μείζων ἦν ἡ τοῦδε τοῦ λόγου περιβολή, κατʼ αὐτὸν ἐκεῖνον χωρίσας ταῖς ἰδίαις ἀρχαῖς αὐτοῦ καὶ τῷ τέλει τὴν γραφὴν συνεμέτρησα· χρόνου δὲ προϊόντος, ὅπερ φιλεῖ τοῖς μεγάλων ἅπτεσθαι διανοουμένοις, ὄκνος μοι καὶ μέλλησις ἐγίνετο τηλικαύτην μετενεγκεῖν ὑπόθεσιν εἰς ἀλλοδαπὴν ἡμῖν καὶ ξένην διαλέκτου συνήθειαν."},{"number":8,"text":"ἦσαν δέ τινες, οἳ πόθῳ τῆς ἱστορίας ἐπʼ αὐτήν με προύτρεπον, καὶ μάλιστα δὴ πάντων Ἐπαφρόδιτος ἀνὴρ ἅπασαν μὲν ἰδέαν παιδείας ἠγαπηκώς, διαφερόντως δὲ χαίρων ἐμπειρίαις πραγμάτων, ἅτε δὴ μεγάλοις μὲν αὐτὸς ὁμιλήσας πράγμασι καὶ τύχαις πολυτρόποις, ἐν ἅπασι δὲ θαυμαστὴν φύσεως ἐπιδειξάμενος ἰσχὺν καὶ προαίρεσιν ἀρετῆς ἀμετακίνητον."},{"number":9,"text":"τούτῳ δὴ πειθόμενος ὡς αἰεὶ τοῖς χρήσιμον ἢ καλόν τι πράττειν δυναμένοις συμφιλοκαλοῦντι καὶ ἐμαυτὸν αἰσχυνόμενος, εἰ δόξαιμι ῥαθυμίᾳ πλέον ἢ τῷ περὶ τὰ κάλλιστα χαίρειν πόνῳ, προθυμότερον ἐπερρώσθην, ἔτι κἀκεῖνα πρὸς τοῖς εἰρημένοις λογισάμενος οὐ παρέργως, περί τε τῶν ἡμετέρων προγόνων εἰ μεταδιδόναι τῶν τοιούτων ἤθελον, καὶ περὶ τῶν Ἑλλήνων εἴ τινες αὐτῶν γνῶναι τὰ παρʼ ἡμῖν ἐσπούδασαν."},{"number":10,"text":"Εὗρον τοίνυν, ὅτι Πτολεμαίων μὲν ὁ δεύτερος μάλιστα δὴ βασιλεὺς περὶ παιδείαν καὶ βιβλίων συναγωγὴν σπουδάσας ἐξαιρέτως ἐφιλοτιμήθη τὸν ἡμέτερον νόμον καὶ τὴν κατʼ αὐτὸν διάταξιν τῆς πολιτείας εἰς τὴν Ἑλλάδα φωνὴν μεταβαλεῖν,"},{"number":11,"text":"ὁ δὲ τῶν παρʼ ἡμῖν ἀρχιερέων οὐδενὸς ἀρετῇ δεύτερος Ἐλεάζαρος τῷ προειρημένῳ βασιλεῖ ταύτης ἀπολαῦσαι τῆς ὠφελείας οὐκ ἐφθόνησε πάντως ἀντειπὼν ἄν, εἰ μὴ πάτριον ἦν ἡμῖν τὸ μηδὲν ἔχειν τῶν καλῶν ἀπόρρητον."},{"number":12,"text":"κἀμαυτῷ δὴ πρέπειν ἐνόμισα τὸ μὲν τοῦ ἀρχιερέως μιμήσασθαι μεγαλόψυχον, τῷ βασιλεῖ δὲ πολλοὺς ὁμοίως ὑπολαβεῖν καὶ νῦν εἶναι φιλομαθεῖς· οὐδὲ γὰρ πᾶσαν ἐκεῖνος ἔφθη λαβεῖν τὴν ἀναγραφήν, ἀλλὰ μόνα τὰ τοῦ νόμου παρέδοσαν οἱ πεμφθέντες ἐπὶ τὴν ἐξήγησιν εἰς τὴν Ἀλεξάνδρειαν·"},{"number":13,"text":"μυρία δʼ ἐστὶ τὰ δηλούμενα διὰ τῶν ἱερῶν γραμμάτων, ἅτε δὴ πεντακισχιλίων ἐτῶν ἱστορίας ἐν αὐτοῖς ἐμπεριειλημμένης, καὶ παντοῖαι μέν εἰσι παράλογοι περιπέτειαι, πολλαὶ δὲ τύχαι πολέμων καὶ στρατηγῶν ἀνδραγαθίαι καὶ πολιτευμάτων μεταβολαί."},{"number":14,"text":"τὸ σύνολον δὲ μάλιστά τις ἂν ἐκ ταύτης μάθοι τῆς ἱστορίας ἐθελήσας αὐτὴν διελθεῖν, ὅτι τοῖς μὲν θεοῦ γνώμῃ κατακολουθοῦσι καὶ τὰ καλῶς νομοθετηθέντα μὴ τολμῶσι παραβαίνειν πάντα κατορθοῦται πέρα πίστεως καὶ γέρας εὐδαιμονία πρόκειται παρὰ θεοῦ· καθʼ ὅσον δʼ ἂν ἀποστῶσι τῆς τούτων ἀκριβοῦς ἐπιμελείας, ἄπορα μὲν γίνεται τὰ πόριμα, τρέπεται δὲ εἰς συμφορὰς ἀνηκέστους ὅ τι ποτʼ ἂν ὡς ἀγαθὸν δρᾶν σπουδάσωσιν,"},{"number":15,"text":"ἤδη τοίνυν τοὺς ἐντευξομένους τοῖς βιβλίοις παρακαλῶ τὴν γνώμην θεῷ προσανέχειν καὶ δοκιμάζειν τὸν ἡμέτερον νομοθέτην, εἰ τήν τε φύσιν ἀξίως αὐτοῦ κατενόησε καὶ τῇ δυνάμει πρεπούσας ἀεὶ τὰς πράξεις ἀνατέθεικε πάσης καθαρὸν τὸν περὶ αὐτοῦ φυλάξας λόγον τῆς παρʼ ἄλλοις ἀσχήμονος μυθολογίας·"},{"number":16,"text":"καίτοι γε ὅσον ἐπὶ μήκει χρόνου καὶ παλαιότητι πολλὴν εἶχεν ἄδειαν ψευδῶν πλασμάτων· γέγονε γὰρ πρὸ ἐτῶν δισχιλίων, ἐφʼ ὅσον πλῆθος αἰῶνος οὐδʼ αὐτῶν οἱ ποιηταὶ τὰς γενέσεις τῶν θεῶν, μήτι γε τὰς τῶν ἀνθρώπων πράξεις ἢ τοὺς νόμους ἀνενεγκεῖν ἐτόλμησαν."},{"number":17,"text":"τὰ μὲν οὖν ἀκριβῆ τῶν ἐν ταῖς ἀναγραφαῖς προϊὼν ὁ λόγος κατὰ τὴν οἰκείαν τάξιν σημανεῖ· τοῦτο γὰρ διὰ ταύτης ποιήσειν τῆς πραγματείας ἐπηγγειλάμην οὐδὲν προσθεὶς οὐδʼ αὖ παραλιπών."},{"number":18,"text":"Ἐπειδὴ δὲ πάντα σχεδὸν ἐκ τῆς τοῦ νομοθέτου σοφίας ἡμῖν ἀνήρτηται Μωυσέος, ἀνάγκη μοι βραχέα περὶ ἐκείνου προειπεῖν, ὅπως μή τινες τῶν ἀναγνωσομένων διαπορῶσι, πόθεν ἡμῖν ὁ λόγος περὶ νόμων καὶ πράξεων ἔχων τὴν ἀναγραφὴν ἐπὶ τοσοῦτον φυσιολογίας κεκοινώνηκεν."},{"number":19,"text":"ἰστέον οὖν, ὅτι πάντων ἐκεῖνος ἀναγκαιότατον ἡγήσατο τῷ καὶ τὸν ἑαυτοῦ μέλλοντι βίον οἰκονομήσειν καλῶς καὶ τοῖς ἄλλοις νομοθετεῖν θεοῦ πρῶτον φύσιν κατανοῆσαι καὶ τῶν ἔργων τῶν ἐκείνου θεατὴν τῷ νῷ γενόμενον οὕτως παράδειγμα τὸ πάντων ἄριστον μιμεῖσθαι καθʼ ὅσον οἷόν τε καὶ πειρᾶσθαι κατακολουθεῖν."},{"number":20,"text":"οὔτε γὰρ αὐτῷ ποτʼ ἂν γενέσθαι νοῦν ἀγαθὸν τῷ νομοθέτῃ ταύτης ἀπολειπομένῳ τῆς θέας, οὔτε τῶν γραφησομένων εἰς ἀρετῆς λόγον οὐδὲν ἀποβήσεσθαι τοῖς λαβοῦσιν, εἰ μὴ πρὸ παντὸς ἄλλου διδαχθεῖεν, ὅτι πάντων πατήρ τε καὶ δεσπότης ὁ θεὸς ὢν καὶ πάντα ἐπιβλέπων τοῖς μὲν ἑπομένοις αὐτῷ δίδωσιν εὐδαίμονα βίον, τοὺς ἔξω δὲ βαίνοντας ἀρετῆς μεγάλαις περιβάλλει συμφοραῖς."},{"number":21,"text":"τοῦτο δὴ παιδεῦσαι βουληθεὶς Μωυσῆς τὸ παίδευμα τοὺς ἑαυτοῦ πολίτας τῆς τῶν νόμων θέσεως οὐκ ἀπὸ συμβολαίων καὶ τῶν πρὸς ἀλλήλους δικαίων ἤρξατο τοῖς ἄλλοις παραπλησίως, ἀλλʼ ἐπὶ τὸν θεὸν καὶ τὴν τοῦ κόσμου κατασκευὴν τὰς γνώμας αὐτῶν ἀναγαγὼν καὶ πείσας, ὅτι τῶν ἐπὶ γῆς ἔργων τοῦ θεοῦ κάλλιστόν ἐσμεν ἄνθρωποι, ὅτε πρὸς τὴν εὐσέβειαν ἔσχεν ὑπακούοντας, ῥᾳδίως ἤδη περὶ πάντων ἔπειθεν."},{"number":22,"text":"οἱ μὲν γὰρ ἄλλοι νομοθέται τοῖς μύθοις ἐξακολουθήσαντες τῶν ἀνθρωπίνων ἁμαρτημάτων εἰς τοὺς θεοὺς τῷ λόγῳ τὴν αἰσχύνην μετέθεσαν καὶ πολλὴν ὑποτίμησιν τοῖς πονηροῖς ἔδωκαν·"},{"number":23,"text":"ὁ δʼ ἡμέτερος νομοθέτης ἀκραιφνῆ τὴν ἀρετὴν ἔχοντα τὸν θεὸν ἀποφήνας ᾠήθη δεῖν τοὺς ἀνθρώπους ἐκείνης πειρᾶσθαι μεταλαμβάνειν καὶ τοὺς μὴ ταῦτα φρονοῦντας μηδὲ μὴν πιστεύοντας ἀπαραιτήτως ἐκόλασε."},{"number":24,"text":"πρὸς ταύτην οὖν τὴν ὑπόθεσιν ποιεῖσθαι τὴν ἐξέτασιν τοὺς ἀναγνωσομένους παρακαλῶ· φανεῖται γὰρ σκοπουμένοις οὕτως οὐδὲν οὔτʼ ἄλογον αὐτοῖς οὔτε πρὸς τὴν μεγαλειότητα τοῦ θεοῦ καὶ τὴν φιλανθρωπίαν ἀνάρμοστον· πάντα γὰρ τῇ τῶν ὅλων φύσει σύμφωνον ἔχει τὴν διάθεσιν, τὰ μὲν αἰνιττομένου τοῦ νομοθέτου δεξιῶς, τὰ δʼ ἀλληγοροῦντος μετὰ σεμνότητος, ὅσα δʼ ἐξ εὐθείας λέγεσθαι συνέφερε, ταῦτα ῥητῶς ἐμφανίζοντος."},{"number":25,"text":"τοῖς μέντοι βουλομένοις καὶ τὰς αἰτίας ἑκάστου σκοπεῖν πολλὴ γένοιτʼ ἂν ἡ θεωρία καὶ λίαν φιλόσοφος, ἣν ἐγὼ νῦν μὲν ὑπερβάλλομαι, θεοῦ δὲ διδόντος ἡμῖν χρόνον πειράσομαι μετὰ ταύτην γράψαι τὴν πραγματείαν."},{"number":26,"text":"τρέψομαι δὲ ἐπὶ τὴν ἀφήγησιν ἤδη τῶν πραγμάτων μνησθεὶς πρότερον ὧν περὶ τῆς τοῦ κόσμου κατασκευῆς εἶπε Μωυσῆς· ταῦτα δʼ ἐν ταῖς ἱεραῖς βίβλοις εὗρον ἀναγεγραμμένα. ἔχει δὲ οὕτως·"}],"1":[{"number":27,"text":"Ἐν ἀρχῇ ἔκτισεν ὁ θεὸς τὸν οὐρανὸν καὶ τὴν γῆν. ταύτης δʼ ὑπʼ ὄψιν οὐκ ἐρχομένης, ἀλλὰ βαθεῖ μὲν κρυπτομένης σκότει, πνεύματος δʼ αὐτὴν ἄνωθεν ἐπιθέοντος, γενέσθαι φῶς ἐκέλευσεν ὁ θεός."},{"number":28,"text":"καὶ γενομένου τούτου κατανοήσας τὴν ὅλην ὕλην διεχώρισε τό τε φῶς καὶ τὸ σκότος καὶ τῷ μὲν ὄνομα ἔθετο νύκτα, τὸ δὲ ἡμέραν ἐκάλεσεν ἑσπέραν τε καὶ ὄρθρον τὴν ἀρχὴν τοῦ φωτὸς καὶ τὴν ἀνάπαυσιν προσαγορεύσας."},{"number":29,"text":"καὶ αὕτη μὲν ἂν εἴη πρώτη ἡμέρα, Μωυσῆς δʼ αὐτὴν μίαν εἶπε· τὴν δὲ αἰτίαν ἱκανὸς μέν εἰμι ἀποδοῦναι καὶ νῦν, ἐπεὶ δʼ ὑπέσχημαι τὴν αἰτιολογίαν πάντων ἰδίᾳ συγγραψάμενος παραδώσειν, εἰς τότε καὶ τὴν περὶ αὐτῆς ἑρμηνείαν ἀναβάλλομαι."},{"number":30,"text":"μετὰ δὴ τοῦτο τῇ δευτέρᾳ τῶν ἡμερῶν τὸν οὐρανὸν τοῖς ὅλοις ἐπιτίθησιν, ὅτʼ αὐτὸν ἀπὸ τῶν ἄλλων διακρίνας κατʼ αὐτὸν ἠξίωσε τετάχθαι, κρύσταλλόν τε περιπήξας αὐτῷ καὶ νότιον αὐτὸν καὶ ὑετώδη πρὸς τὴν ἀπὸ τῶν δρόσων ὠφέλειαν ἁρμοδίως τῇ γῇ μηχανησάμενος."},{"number":31,"text":"τῇ δὲ τρίτῃ ἵστησι τὴν γῆν ἀναχέας περὶ αὐτὴν τὴν θάλασσαν· κατʼ αὐτὴν δὲ ταύτην τὴν ἡμέραν εὐθὺς φυτά τε καὶ σπέρματα γῆθεν ἀνέτειλε. τῇ τετάρτῃ δὲ διακοσμεῖ τὸν οὐρανὸν ἡλίῳ καὶ σελήνῃ καὶ τοῖς ἄλλοις ἄστροις κινήσεις αὐτοῖς ἐπιστείλας καὶ δρόμους, οἷς ἂν αἱ τῶν ὡρῶν περιφοραὶ σημαίνοιντο."},{"number":32,"text":"πέμπτῃ ἡμέρᾳ ζῷά τε κατʼ αὐτὴν νηκτὰ καὶ μετάρσια τὰ μὲν κατὰ βάθους τὰ δὲ διʼ ἀέρος ἀνῆκε συνδησάμενος αὐτὰ κοινωνίᾳ καὶ μίξει γονῆς ἕνεκα καὶ τοῦ συναύξεσθαι καὶ πλεονάζειν αὐτῶν τὴν φύσιν. τῇ δὲ ἕκτῃ ἡμέρᾳ δημιουργεῖ τὸ τῶν τετραπόδων γένος ἄρρεν τε καὶ θῆλυ ποιήσας· ἐν ταύτῃ δὲ καὶ τὸν ἄνθρωπον ἔπλασε."},{"number":33,"text":"καὶ τὸν κόσμον ἓξ ταῖς πάσαις ἡμέραις Μωυσῆς καὶ πάντα τὰ ἐν αὐτῷ φησὶ γενέσθαι, τῇ δὲ ἑβδόμῃ ἀναπαύσασθαι καὶ λαβεῖν ἀπὸ τῶν ἔργων ἐκεχειρίαν, ὅθεν καὶ ἡμεῖς σχολὴν ἀπὸ τῶν πόνων κατὰ ταύτην ἄγομεν τὴν ἡμέραν προσαγορεύοντες αὐτὴν σάββατα· δηλοῖ δὲ ἀνάπαυσιν κατὰ τὴν Ἑβραίων διάλεκτον τοὔνομα."},{"number":34,"text":"Καὶ δὴ καὶ φυσιολογεῖν Μωυσῆς μετὰ τὴν ἑβδόμην ἤρξατο περὶ τῆς τἀνθρώπου κατασκευῆς λέγων οὕτως· ἔπλασεν ὁ θεὸς τὸν ἄνθρωπον χοῦν ἀπὸ τῆς γῆς λαβών, καὶ πνεῦμα ἐνῆκεν αὐτῷ καὶ ψυχήν. ὁ δʼ ἄνθρωπος οὗτος Ἄδαμος ἐκλήθη· σημαίνει δὲ τοῦτο κατὰ γλῶτταν τὴν Ἑβραίων πυρρόν, ἐπειδήπερ ἀπὸ τῆς πυρρᾶς γῆς φυραθείσης ἐγεγόνει· τοιαύτη γάρ ἐστιν ἡ παρθένος γῆ καὶ ἀληθινή."},{"number":35,"text":"παρίστησι δὲ ὁ θεὸς τῷ Ἀδάμῳ κατὰ γένη τὰ ζῷα θῆλύ τε καὶ ἄρρεν ἀποδειξάμενος καὶ τούτοις ὀνόματα τίθησιν, οἷς ἔτι καὶ νῦν καλοῦνται. βλέπων δὲ τὸν Ἄδαμον οὐκ ἔχοντα κοινωνίαν πρὸς τὸ θῆλυ καὶ συνδιαίτησιν, οὐδὲ γὰρ ἦν, ξενιζόμενον δʼ ἐπὶ τοῖς ἄλλοις ζῴοις οὕτως ἔχουσι, μίαν αὐτοῦ κοιμωμένου πλευρὰν ἐξελὼν ἐξ αὐτῆς ἔπλασε γυναῖκα."},{"number":36,"text":"καὶ ὁ Ἄδαμος προσαχθεῖσαν αὐτὴν ἐγνώρισεν ἐξ αὑτοῦ γενομένην. ἔσσα δὲ καθʼ Ἑβραίων διάλεκτον καλεῖται γυνή, τὸ δʼ ἐκείνης ὄνομα τῆς γυναικὸς Εὔα ἦν· σημαίνει δὲ τοῦτο πάντων μητέρα."},{"number":37,"text":"Φησὶ δὲ τὸν θεὸν καὶ παράδεισον πρὸς τὴν ἀνατολὴν καταφυτεῦσαι παντοίῳ τεθηλότα φυτῷ· ἐν τούτοις δʼ εἶναι καὶ τῆς ζωῆς τὸ φυτὸν καὶ ἄλλο τὸ τῆς φρονήσεως, ᾗ διεγινώσκετο τί εἴη τὸ ἀγαθὸν καὶ τί τὸ κακόν."},{"number":38,"text":"εἰς τοῦτον δὲ τὸν κῆπον εἰσαγαγόντα τόν τε Ἄδαμον καὶ τὴν γυναῖκα κελεῦσαι τῶν φυτῶν ἐπιμελεῖσθαι. ἄρδεται δʼ οὗτος ὁ κῆπος ὑπὸ ἑνὸς ποταμοῦ πᾶσαν ἐν κύκλῳ τὴν γῆν περιρρέοντος, ὃς εἰς τέσσαρα μέρη σχίζεται. καὶ Φεισὼν μέν, σημαίνει δὲ πληθὺν τοὔνομα, ἐπὶ τὴν Ἰνδικὴν φερόμενος ἐκδίδωσιν εἰς τὸ πέλαγος ὑφʼ Ἑλλήνων Γάγγης λεγόμενος,"},{"number":39,"text":"Εὐφράτης δὲ καὶ Τίγρις ἐπὶ τὴν Ἐρυθρὰν ἀπίασι θάλασσαν· καλεῖται δὲ ὁ μὲν Εὐφράτης Φοράς, σημαίνει δὲ ἤτοι σκεδασμὸν ἢ ἄνθος, Τίγρις δὲ Διγλάθ, ἐξ οὗ φράζεται τὸ μετὰ στενότητος ὀξύ· Γηὼν δὲ διὰ τῆς Αἰγύπτου ῥέων δηλοῖ τὸν ἀπὸ τῆς ἐναντίας ἀναδιδόμενον ἡμῖν, ὃν δὴ Νεῖλον Ἕλληνες προσαγορεύουσιν."},{"number":40,"text":"Ὁ δὴ τοίνυν θεὸς τὸν Ἄδαμον καὶ τὴν γυναῖκα τῶν μὲν ἄλλων φυτῶν ἐκέλευε γεύεσθαι, τοῦ δὲ τῆς φρονήσεως ἀπέχεσθαι, προειπὼν ἁψαμένοις ἀπʼ αὐτοῦ ὄλεθρον γενησόμενον."},{"number":41,"text":"ὁμοφωνούντων δὲ κατʼ ἐκεῖνο καιροῦ τῶν ζῴων ἁπάντων ὄφις συνδιαιτώμενος τῷ τε Ἀδάμῳ καὶ τῇ γυναικὶ φθονερῶς μὲν εἶχεν ἐφʼ οἷς αὐτοὺς εὐδαιμονήσειν ᾤετο πεπεισμένους τοῖς τοῦ θεοῦ παραγγέλμασιν,"},{"number":42,"text":"οἰόμενος δὲ συμφορᾷ περιπεσεῖσθαι παρακούσαντας ἀναπείθει κακοήθως τὴν γυναῖκα γεύσασθαι τοῦ φυτοῦ τῆς φρονήσεως ἐν αὐτῷ λέγων εἶναι τήν τε τἀγαθοῦ καὶ τοῦ κακοῦ διάγνωσιν, ἧς γενομένης αὐτοῖς μακάριον καὶ μηδὲν ἀπολείποντα τοῦ θείου διάξειν βίον."},{"number":43,"text":"καὶ παρακρούεται μὲν οὕτω τὴν γυναῖκα τῆς ἐντολῆς τοῦ θεοῦ καταφρονῆσαι· γευσαμένη δὲ τοῦ φυτοῦ καὶ ἡσθεῖσα τῷ ἐδέσματι καὶ τὸν Ἄδαμον ἀνέπεισεν αὐτῷ χρήσασθαι."},{"number":44,"text":"καὶ συνίεσάν τε αὑτῶν ἤδη γεγυμνωμένων καὶ τὴν αἰσχύνην ὕπαιθρον ἔχοντες σκέπην αὑτοῖς ἐπενόουν· τὸ γὰρ φυτὸν ὀξύτητος καὶ διανοίας ὑπῆρχε. φύλλοις οὖν ἑαυτοὺς συκῆς ἐσκέπασαν καὶ ταῦτα πρὸ τῆς αἰδοῦς προβαλόμενοι μᾶλλον ἐδόκουν εὐδαιμονεῖν ὡς ὧν πρότερον ἐσπάνιζον εὑρόντες."},{"number":45,"text":"τοῦ θεοῦ δʼ εἰς τὸν κῆπον ἐλθόντος ὁ μὲν Ἄδαμος πρότερον εἰς ὁμιλίαν αὐτῷ φοιτῶν συνειδὼς αὑτῷ τὴν ἀδικίαν ὑπεχώρει, τὸν δὲ θεὸν ἐξένιζε τὸ πραττόμενον καὶ τὴν αἰτίαν ἐπυνθάνετο, διʼ ἣν πρότερον ἡδόμενος τῇ πρὸς αὐτὸν ὁμιλίᾳ νῦν φεύγει ταύτην καὶ περιίσταται."},{"number":46,"text":"τοῦ δὲ μηδὲν φθεγγομένου διὰ τὸ συγγινώσκειν ἑαυτῷ παραβάντι τὴν τοῦ θεοῦ πρόσταξιν ἀλλʼ ἐμοὶ μέν, εἶπεν ὁ θεός, ἔγνωστο περὶ ὑμῶν, ὅπως βίον εὐδαίμονα καὶ κακοῦ παντὸς ἀπαθῆ βιώσετε μηδεμιᾷ ξαινόμενοι τὴν ψυχὴν φροντίδι, πάντων δʼ ὑμῖν αὐτομάτων ὅσα πρὸς ἀπόλαυσιν καὶ ἡδονὴν συντελεῖ κατὰ τὴν ἐμὴν ἀνιόντων πρόνοιαν χωρὶς ὑμετέρου πόνου καὶ ταλαιπωρίας, ὧν παρόντων γῆράς τε θᾶττον οὐκ ἂν ἐπέλθοι καὶ τὸ ζῆν ὑμῖν μακρὸν γένοιτο."},{"number":47,"text":"νῦν δʼ εἰς ταύτην μου τὴν γνώμην ἐνύβρισας παρακούσας τῶν ἐμῶν ἐντολῶν· οὐ γὰρ ἐπʼ ἀρετῇ τὴν σιωπὴν ἄγεις, ἀλλʼ ἐπὶ συνειδότι πονηρῷ."},{"number":48,"text":"Ἄδαμος δὲ παρῃτεῖτο τῆς ἁμαρτίας αὑτὸν καὶ παρεκάλει τὸν θεὸν μὴ χαλεπαίνειν αὐτῷ τὴν γυναῖκα τοῦ γεγονότος αἰτιώμενος καὶ λέγων ὑπʼ αὐτῆς ἐξαπατηθεὶς ἁμαρτεῖν, ἡ δʼ αὖ κατηγόρει τοῦ ὄφεως."},{"number":49,"text":"ὁ δὲ θεὸς ἥττονα γυναικείας συμβουλίας αὐτὸν γενόμενον ὑπετίθει τιμωρίᾳ, τὴν γῆν οὐκέτι μὲν οὐδὲν αὐτοῖς ἀναδώσειν αὐτομάτως εἰπών, πονοῦσι δὲ καὶ τοῖς ἔργοις τριβομένοις τὰ μὲν παρέξειν, τῶν δʼ οὐκ ἀξιώσειν. Εὔαν δὲ τοκετοῖς καὶ ταῖς ἐξ ὠδίνων ἀλγηδόσιν ἐκόλαζεν, ὅτι τὸν Ἄδαμον οἷς αὐτὴν ὁ ὄφις ἐξηπάτησε τούτοις παρακρουσαμένη συμφοραῖς περιέβαλεν."},{"number":50,"text":"ἀφείλετο δὲ καὶ τὸν ὄφιν τὴν φωνὴν ὀργισθεὶς ἐπὶ τῇ κακοηθείᾳ τῇ πρὸς τὸν Ἄδαμον καὶ ἰὸν ἐντίθησιν ὑπὸ τὴν γλῶτταν αὐτῷ πολέμιον ἀποδείξας ἀνθρώποις καὶ ὑποθέμενος κατὰ τῆς κεφαλῆς φέρειν τὰς πληγάς, ὡς ἐν ἐκείνῃ τοῦ τε κακοῦ τοῦ πρὸς ἀνθρώπους κειμένου καὶ τῆς τελευτῆς ῥᾴστης τοῖς ἀμυνομένοις ἐσομένης, ποδῶν τε αὐτὸν ἀποστερήσας σύρεσθαι κατὰ τῆς γῆς ἰλυσπώμενον ἐποίησε."},{"number":51,"text":"καὶ ὁ μὲν θεὸς ταῦτα προστάξας αὐτοῖς πάσχειν μετοικίζει τὸν Ἄδαμον καὶ τὴν Εὔαν ἐκ τοῦ κήπου εἰς ἕτερον χωρίον."}],"2":[{"number":52,"text":"Γίνονται δὲ αὐτοῖς παῖδες ἄρρενες δύο· προσηγορεύετο δὲ αὐτῶν ὁ μὲν πρῶτος Κάις, κτίσιν δὲ σημαίνει τοῦτο μεθερμηνευόμενον τοὔνομα, Ἄβελος δὲ ὁ δεύτερος, σημαίνει δὲ οὐθὲν τοῦτο·"},{"number":53,"text":"γίνονται δὲ αὐτοῖς καὶ θυγατέρες. οἱ μὲν οὖν ἀδελφοὶ διαφόροις ἔχαιρον ἐπιτηδεύμασιν· Ἄβελος μὲν γὰρ ὁ νεώτερος δικαιοσύνης ἐπεμελεῖτο καὶ πᾶσι τοῖς ὑπʼ αὐτοῦ πραττομένοις παρεῖναι τὸν θεὸν νομίζων ἀρετῆς προενόει, ποιμενικὸς δʼ ἦν ὁ βίος αὐτῷ· Κάις δὲ τά τε ἄλλα πονηρότατος ἦν καὶ πρὸς τὸ κερδαίνειν μόνον ἀποβλέπων γῆν τε ἀροῦν ἐπενόησε πρῶτος καὶ κτείνει δὲ τὸν ἀδελφὸν ἐκ τοιαύτης αἰτίας·"},{"number":54,"text":"θῦσαι τῷ θεῷ δόξαν αὐτοῖς ὁ μὲν Κάις τοὺς ἀπὸ τῆς γεωργίας καὶ φυτῶν καρποὺς ἐπήνεγκεν, Ἄβελος δὲ γάλα καὶ τὰ πρωτότοκα τῶν βοσκημάτων. ὁ δὲ θεὸς ταύτῃ μᾶλλον ἥδεται τῇ θυσίᾳ τοῖς αὐτομάτοις καὶ κατὰ φύσιν γεγονόσι τιμώμενος, ἀλλʼ οὐχὶ τοῖς κατʼ ἐπίνοιαν ἀνθρώπου πλεονέκτου βίᾳ πεφυκόσιν."},{"number":55,"text":"ἔνθεν ὁ Κάις παροξυνθεὶς ἐπὶ τῷ προτετιμῆσθαι τὸν Ἄβελον ὑπὸ τοῦ θεοῦ κτείνει τὸν ἀδελφὸν καὶ τὸν νεκρὸν αὐτοῦ ποιήσας ἀφανῆ λήσειν ὑπέλαβεν. ὁ δὲ θεὸς συνεὶς τὸ ἔργον ἧκε πρὸς τὸν Κάιν περὶ τἀδελφοῦ πυνθανόμενος, ποῖ ποτʼ εἴη· πολλῶν γὰρ αὐτὸν οὐκ ἰδεῖν ἡμερῶν τὸν ἄλλον χρόνον πάντα μετʼ αὐτοῦ βλέπων αὐτὸν ἀναστρεφόμενον."},{"number":56,"text":"ὁ δὲ Κάις ἀπορούμενος καὶ οὐκ ἔχων ὅ τι λέγοι πρὸς τὸν θεὸν ἀμηχανεῖν μὲν καὶ αὐτὸς ἔφασκε τὸ πρῶτον ἐπὶ τἀδελφῷ μὴ βλεπομένῳ, παροξυνθεὶς δὲ τοῦ θεοῦ λιπαρῶς ἐγκειμένου καὶ πολυπραγμονοῦντος οὐκ εἶναι παιδαγωγὸς καὶ φύλαξ αὐτοῦ καὶ τῶν ὑπʼ αὐτοῦ πραττομένων ἔλεγεν."},{"number":57,"text":"ὁ δὲ θεὸς τοὐντεῦθεν ἤλεγχεν ἤδη τὸν Κάιν φονέα τἀδελφοῦ γενόμενον καί θαυμάζω, φησίν, εἰ περὶ ἀνδρὸς ἀγνοεῖς εἰπεῖν τί γέγονεν, ὃν αὐτὸς ἀπολώλεκας."},{"number":58,"text":"τῆς μὲν οὖν ἐπὶ τῷ φόνῳ τιμωρίας αὐτὸν ἠφίει θυσίαν ἐπιτελέσαντα καὶ διʼ αὐτῆς ἱκετεύσαντα μὴ λαβεῖν ὀργὴν αὐτῷ χαλεπωτέραν, ἐπάρατον δʼ αὐτὸν ἐτίθει καὶ τοὺς ἐγγόνους αὐτοῦ τιμωρήσεσθαι κατὰ τὴν ἑβδόμην ἠπείλησε γενεάν, καὶ τῆς γῆς αὐτὸν ἐκείνης ἐκβάλλει σὺν τῇ γυναικί."},{"number":59,"text":"τοῦ δὲ μὴ θηρίοις ἀλώμενος περιπέσῃ δεδιότος καὶ τοῦτον ἀπόληται τὸν τρόπον, ἐκέλευε μηδὲν ὑφορᾶσθαι σκυθρωπὸν ἀπὸ τοιαύτης αἰτίας, ἀλλʼ ἕνεκα τοῦ μηδὲν αὐτῷ ἐκ θηρίων γενέσθαι δεινὸν διὰ πάσης ἀδεῶς χωρεῖν γῆς· καὶ σημεῖον ἐπιβαλών, ᾧ γνώριμος ἂν εἴη, προσέταξεν ἀπιέναι."},{"number":60,"text":"Πολλὴν δʼ ἐπελθὼν γῆν ἱδρύεται μετὰ τῆς γυναικὸς Κάις Ναΐδα τόπον οὕτω καλούμενον καὶ αὐτόθι ποιεῖται τὴν κατοίκησιν, ἔνθʼ αὐτῷ καὶ παῖδες ἐγένοντο· οὐκ ἐπὶ νουθεσίᾳ δὲ τὴν κόλασιν ἔλαβεν, ἀλλʼ ἐπʼ αὐξήσει τῆς κακίας, ἡδονὴν μὲν πᾶσαν ἐκπορίζων αὐτοῦ τῷ σώματι, κἂν μεθʼ ὕβρεως τῶν συνόντων δέῃ ταύτην ἔχειν·"},{"number":61,"text":"αὔξων δὲ τὸν οἶκον πλήθει χρημάτων ἐξ ἁρπαγῆς καὶ βίας πρὸς ἡδονὴν καὶ λῃστείαν τοὺς ἐντυγχάνοντας παρακαλῶν διδάσκαλος αὐτοῖς ὑπῆρχε πονηρῶν ἐπιτηδευμάτων, καὶ τὴν ἀπραγμοσύνην, ᾗ πρότερον συνέζων οἱ ἄνθρωποι, μέτρων ἐπινοίᾳ καὶ σταθμῶν μετεστήσατο ἀκέραιον αὐτοῖς ὄντα τὸν βίον ἐκ τῆς τούτων ἀμαθίας καὶ μεγαλόψυχον εἰς πανουργίαν περιαγαγών,"},{"number":62,"text":"ὅρους τε γῆς πρῶτος ἔθετο καὶ πόλιν ἐδείματο καὶ τείχεσιν ὠχύρωσεν εἰς ταὐτὸν συνελθεῖν τοὺς οἰκείους καταναγκάσας. καὶ τὴν πόλιν δὲ ταύτην ἀπὸ Ἀνώχου τοῦ πρεσβυτάτου παιδὸς Ἄνωχαν ἐκάλεσεν."},{"number":63,"text":"Ἀνώχου δὲ Ἰαράδης υἱὸς ἦν, ἐκ δὲ τούτου Μαρουῆλος, οὗ γίνεται παῖς Μαθουσάλας, τοῦ δὲ Λάμεχος, ᾧ παῖδες ὑπῆρξαν ἑπτὰ καὶ ἑβδομήκοντα ἐκ δύο γυναικῶν αὐτῷ φύντες Σελλᾶς καὶ Ἄδας."},{"number":64,"text":"τούτων Ἰώβηλος μὲν ἐξ Ἄδας γεγονὼς σκηνὰς ἐπήξατο καὶ προβατείαν ἠγάπησεν, Ἰούβαλος δέ, ὁμομήτριος δʼ ἦν αὐτῷ, μουσικὴν ἤσκησε καὶ ψαλτήρια καὶ κιθάρας ἐπενόησεν, Ἰουβῆλος δὲ τῶν ἐκ τῆς ἑτέρας γεγονότων ἰσχύι πάντας ὑπερβαλὼν τὰ πολεμικὰ διαπρεπῶς μετῆλθεν ἐκ τούτων καὶ τὰ πρὸς ἡδονὴν τοῦ σώματος ἐκπορίζων, χαλκείαν τε πρῶτος ἐπενόησεν."},{"number":65,"text":"πατὴρ δὲ θυγατρὸς γενόμενος ὁ Λάμεχος Νοεμᾶς ὄνομα, ἐπεὶ τὰ θεῖα σαφῶς ἐξεπιστάμενος ἑώρα δίκην αὑτὸν ὑφέξοντα τῆς Κάιος ἀδελφοκτονίας μείζονα, τοῦτο ταῖς ἑαυτοῦ γυναιξὶν ἐποίησε φανερόν."},{"number":66,"text":"ἔτι δὲ ζῶντος Ἀδάμου Κάιος τοὺς ἐγγόνους πονηροτάτους συνέβη γενέσθαι κατὰ διαδοχὴν καὶ μίμησιν ἄλλον ἄλλου χείρονα τελευτῶντα· πρός τε γὰρ πολέμους εἶχον ἀκρατῶς καὶ πρὸς λῃστείαν ὡρμήκεσαν, ἄλλος δʼ εἴ τις ὀκνηρὸς ἦν πρὸς τὸ φονεύειν, ἄλλην ἀπόνοιαν ἦν θράσους ὑβρίζων καὶ πλεονεκτῶν."},{"number":67,"text":"Ἄδαμος δὲ ὁ πρῶτος ἐκ γῆς γενόμενος, ἀπαιτεῖ γὰρ ἡ διήγησις τὸν περὶ αὐτοῦ λόγον, Ἀβέλου μὲν ἐσφαγμένου, Κάιος δὲ διὰ τὸν ἐκείνου φόνον πεφευγότος, παιδοποιίας ἐφρόντιζε, καὶ δεινὸς εἶχεν αὐτὸν γενέσεως ἔρως ἔτη τριάκοντʼ ἤδη καὶ διακόσια ἠνυκότα τοῦ βίου, πρὸς οἷς ἕτερα ζήσας ἑπτακόσια τελευτᾷ."},{"number":68,"text":"γίνονται μὲν οὖν αὐτῷ παῖδες ἄλλοι τε πλείους καὶ Σῆθος· ἀλλὰ περὶ μὲν τῶν ἄλλων μακρὸν ἂν εἴη λέγειν, πειράσομαι δὲ μόνα τὰ τῶν ἀπὸ Σήθου διελθεῖν· τραφεὶς γὰρ οὗτος καὶ παρελθὼν εἰς ἡλικίαν ἤδη καλὰ κρίνειν δυναμένην καὶ γενόμενος αὐτὸς ἄριστος μιμητὰς τῶν αὐτῶν τοὺς ἀπογόνους κατέλιπεν."},{"number":69,"text":"οἱ δὲ πάντες ἀγαθοὶ φύντες γῆν τε τὴν αὐτὴν ἀστασίαστοι κατῴκησαν εὐδαιμονήσαντες μηδενὸς αὐτοῖς ἄχρι καὶ τελευτῆς δυσκόλου προσπεσόντος, σοφίαν τε τὴν περὶ τὰ οὐράνια καὶ τὴν τούτων διακόσμησιν ἐπενόησαν."},{"number":70,"text":"ὑπὲρ δὲ τοῦ μὴ διαφυγεῖν τοὺς ἀνθρώπους τὰ ηὑρημένα μηδὲ πρὶν εἰς γνῶσιν ἐλθεῖν φθαρῆναι, προειρηκότος ἀφανισμὸν Ἀδάμου τῶν ὅλων ἔσεσθαι τὸν μὲν κατʼ ἰσχὺν πυρὸς τὸν ἕτερον δὲ κατὰ βίαν καὶ πλῆθος ὕδατος, στήλας δύο ποιησάμενοι τὴν μὲν ἐκ πλίνθου τὴν ἑτέραν δὲ ἐκ λίθων ἀμφοτέραις ἐνέγραψαν τὰ εὑρημένα,"},{"number":71,"text":"ἵνα καὶ τῆς πλινθίνης ἀφανισθείσης ὑπὸ τῆς ἐπομβρίας ἡ λιθίνη μείνασα παράσχῃ μαθεῖν τοῖς ἀνθρώποις τὰ ἐγγεγραμμένα δηλοῦσα καὶ πλινθίνην ὑπʼ αὐτῶν ἀνατεθῆναι. μένει δʼ ἄχρι δεῦρο κατὰ γῆν τὴν Σειρίδα."}],"3":[{"number":72,"text":"Καὶ οὗτοι μὲν ἑπτὰ γενεὰς διέμειναν θεὸν ἡγούμενοι δεσπότην εἶναι τῶν ὅλων καὶ πάντα πρὸς ἀρετὴν ἀποβλέποντες, εἶτα προϊόντος χρόνου μεταβάλλονται πρὸς τὸ χεῖρον ἐκ τῶν πατρίων ἐθισμῶν μήτε τὰς νενομισμένας τιμὰς ἔτι τῷ θεῷ παρέχοντες μήτε τοῦ πρὸς ἀνθρώπους δικαίου ποιούμενοι λόγον, ἀλλʼ ἣν πρότερον εἶχον τῆς ἀρετῆς ζήλωσιν διπλασίονα τῆς κακίας τότʼ ἐπιδεικνύμενοι διʼ ὧν ἔπραττον· ἔνθεν ἑαυτοῖς τὸν θεὸν ἐξεπολέμωσαν."},{"number":73,"text":"πολλοὶ γὰρ ἄγγελοι θεοῦ γυναιξὶ συνιόντες ὑβριστὰς ἐγέννησαν παῖδας καὶ παντὸς ὑπερόπτας καλοῦ διὰ τὴν ἐπὶ τῇ δυνάμει πεποίθησιν· ὅμοια τοῖς ὑπὸ γιγάντων τετολμῆσθαι λεγομένοις ὑφʼ Ἑλλήνων καὶ οὗτοι δράσαι παραδίδονται."},{"number":74,"text":"Νῶχος δὲ τοῖς πραττομένοις ὑπʼ αὐτῶν δυσχεραίνων καὶ τοῖς βουλεύμασιν ἀηδῶς ἔχων ἔπειθεν ἐπὶ τὸ κρεῖττον τὴν διάνοιαν αὐτοὺς καὶ τὰς πράξεις μεταφέρειν, ὁρῶν δʼ οὐκ ἐνδιδόντας, ἀλλʼ ἰσχυρῶς ὑπὸ τῆς ἡδονῆς τῶν κακῶν κεκρατημένους, δείσας μὴ καὶ φονεύσωσιν αὐτὸν μετὰ γυναικῶν καὶ τέκνων καὶ τῶν τούτοις συνοικουσῶν ἐξεχώρησε τῆς γῆς."},{"number":75,"text":"Ὁ δὲ θεὸς τοῦτον μὲν τῆς δικαιοσύνης ἠγάπησε, κατεδίκαζε δʼ οὐκ ἐκείνων μόνων τῆς κακίας, ἀλλὰ καὶ πᾶν ὅσον ἦν ἀνθρώπινον τότε δόξαν αὐτῷ διαφθεῖραι καὶ ποιῆσαι γένος ἕτερον πονηρίας καθαρόν, ἐπιτεμόμενος αὐτῶν τὸν βίον καὶ ποιήσας ἐτῶν οὐχ ὅσα πρότερον ἔζων, ἀλλʼ ἑκατὸν εἴκοσιν, εἰς θάλασσαν τὴν ἤπειρον μετέβαλε."},{"number":76,"text":"καὶ οἱ μὲν οὕτως ἀφανίζονται πάντες, Νῶχος δὲ σώζεται μόνος ὑποθεμένου μηχανὴν αὐτῷ καὶ πόρον πρὸς σωτηρίαν τοῦ θεοῦ τοιαύτην·"},{"number":77,"text":"λάρνακα τετράστεγον κατασκευάσας πηχῶν τὸ μῆκος τριακοσίων πεντήκοντα δὲ τὸ πλάτος καὶ τριάκοντα τὸ βάθος, εἰς ταύτην σὺν τῇ μητρὶ τῶν παίδων καὶ ταῖς τούτων γυναιξὶν ἀνέβη, τά τε ἄλλα ὅσα πρὸς τὰς χρείας ἐπικουρήσειν αὐτοῖς ἔμελλεν ἐνθέμενος, ζῷά τε παντοῖα πρὸς διατήρησιν τοῦ γένους αὐτῶν ἄρρενάς τε καὶ θηλείας συνεισβαλόμενος ἄλλα τε τούτων ἑπταπλασίονα τὸν ἀριθμόν."},{"number":78,"text":"ἦν δʼ ἡ λάρναξ τούς τε τοίχους καρτερὰ καὶ τὸν ὄροφον, ὡς μηδαμόθεν ἐπικλύζεσθαι μηδʼ ἡττᾶσθαι τῆς τοῦ ὕδατος βίας. καὶ Νῶχος μὲν οὕτως μετὰ τῶν οἰκείων διασώζεται."},{"number":79,"text":"ἦν δʼ αὐτὸς μὲν ἀπὸ Ἀδάμου δέκατος· Λαμέχου γάρ ἐστιν υἱός, οὗ πατὴρ ἦν Μαθουσάλας, οὗτος δὲ ἦν τοῦ Ἀνώχου τοῦ Ἰαρέδου, Μαλαήλου δὲ Ἰάρεδος ἐγεγόνει, ὃς ἐκ Καϊνᾶ τεκνοῦται τοῦ Ἀνώσου σὺν ἀδελφαῖς πλείοσιν, Ἄνωσος δὲ Σήθου υἱὸς ἦν τοῦ Ἀδάμου·"},{"number":80,"text":"Συνέβη δὲ τοῦτο τὸ πάθος κατὰ τὸ ἑξακοσιοστὸν ἔτος ἤδη Νώχου τῆς ἀρχῆς, ἐν μηνὶ δευτέρῳ Δίῳ μὲν ὑπὸ Μακεδόνων λεγομένῳ, Μαρσουάνῃ δʼ ὑπὸ Ἑβραίων· οὕτω γὰρ ἐν Αἰγύπτῳ τὸν ἐνιαυτὸν ἦσαν διατεταχότες."},{"number":81,"text":"Μωυσῆς δὲ τὸν Νισᾶν, ὅς ἐστι Ξανθικός, μῆνα πρῶτον ἐπὶ ταῖς ἑορταῖς ὥρισε κατὰ τοῦτον ἐξ Αἰγύπτου τοὺς Ἑβραίους προαγαγών· οὗτος δʼ αὐτῷ καὶ πρὸς ἁπάσας τὰς εἰς τὸ θεῖον τιμὰς ἦρχεν, ἐπὶ μέντοι γε πράσεις καὶ ὠνὰς καὶ τὴν ἄλλην διοίκησιν τὸν πρῶτον κόσμον διεφύλαξε· τὴν δʼ ἐπομβρίαν ἄρξασθαί φησιν ἑβδόμῃ τοῦ προειρημένου μηνὸς καὶ εἰκάδι."},{"number":82,"text":"χρόνος δὲ οὗτος ἀπὸ Ἀδάμου τοῦ πρώτου γεγονότος ἐτῶν ὑπῆρχε δισχιλίων διακοσίων ἑξηκονταδύο. ἀναγέγραπται δὲ ὁ χρόνος ἐν ταῖς ἱεραῖς βίβλοις σημειουμένων μετὰ πολλῆς ἀκριβείας τῶν τότε καὶ τὰς γενέσεις τῶν ἐπιφανῶν ἀνδρῶν καὶ τὰς τελευτάς."},{"number":83,"text":"Ἀδάμῳ μὲν τριακοστῷ ἤδη καὶ διακοσιοστῷ ἔτει γεγονότι παῖς Σῆθος γίνεται, ὃς ἐνακόσια καὶ τριάκοντα ἔτη ἐβίωσε. Σῆθος δὲ κατὰ πέμπτον καὶ διακοσιοστὸν ἔτος ἐγέννησεν Ἄνωσον, ὃς πέντε ζήσας ἔτη καὶ ἐνακόσια Καϊνᾷ τῷ παιδὶ τὴν τῶν πραγμάτων ἐπιμέλειαν δίδωσι τεκνώσας αὐτὸν περὶ ἐνενηκοστὸν καὶ ἑκατοστὸν ἔτος· οὗτος ἐβίωσεν ἔτη δώδεκα πρὸς τοῖς ἐνακοσίοις."},{"number":84,"text":"Καϊνᾶς δὲ βιοὺς δέκα καὶ ἐνακόσια Μαλαῆλον υἱὸν ἔσχεν ἔτει γενόμενον ἑβδομηκοστῷ καὶ ἑκατοστῷ. οὗτος ὁ Μαλαῆλος ζήσας πέντε καὶ ἐνενήκοντα καὶ ὀκτακόσια ἔτη ἐτελεύτησεν Ἰάρεδον καταλιπὼν υἱόν, ὃν ἔτος πέμπτον ἑξηκοστὸν καὶ ἑκατοστὸν γενόμενος ἐγέννησε."},{"number":85,"text":"τοῦτον εἰς ἐννέα καὶ ἑξήκοντα πρὸς τοῖς ἐνακοσίοις βιώσαντα Ἄνωχος υἱὸς διαδέχεται γεννηθεὶς περὶ ἔτη δύο καὶ ἑξήκοντα καὶ ἑκατὸν τοῦ πατρὸς αὐτῷ τυγχάνοντος. οὗτος ζήσας πέντε καὶ ἑξήκοντα πρὸς τοῖς τριακοσίοις ἀνεχώρησε πρὸς τὸ θεῖον, ὅθεν οὐδὲ τελευτὴν αὐτοῦ ἀναγεγράφασι."},{"number":86,"text":"Μαθουσάλας δὲ Ἀνώχου παῖς κατὰ ἔτος αὐτῷ γεγονὼς πέμπτον καὶ ἑξηκοστὸν καὶ ἑκατοστὸν Λάμεχον υἱὸν ἔσχε περὶ ἔτη γεγονὼς ἑπτὰ καὶ ὀγδοήκοντα καὶ ἑκατόν, ᾧ τὴν ἀρχὴν παρέδωκεν αὐτὸς αὐτὴν κατασχὼν ἐννέα καὶ ἑξήκοντα καὶ ἐνακοσίοις."},{"number":87,"text":"Λάμεχος δὲ ἄρξας ἑπτὰ καὶ ἑπτακοσίοις ἔτεσι Νῶχον τῶν πραγμάτων ἀποδείκνυσι προστάτην υἱόν, ὃς Λαμέχῳ γενόμενος ὄγδοον καὶ ὀγδοηκοστὸν καὶ ἑκατοστὸν ἔτος ἠνυκότι πεντήκοντα καὶ ἐνακοσίοις ἔτεσιν ἦρξε τῶν πραγμάτων."},{"number":88,"text":"ταῦτα συναγόμενα τὰ ἔτη τὸν προαναγεγραμμένον πληροῖ χρόνον. ἐξεταζέτω δὲ μηδεὶς τὰς τελευτὰς τῶν ἀνδρῶν, τοῖς γὰρ αὐτῶν παισὶ καὶ τοῖς ἐκείνων ἀπογόνοις παρεξέτεινον τὸν βίον, ἀλλὰ τὰς γενέσεις αὐτῶν μόνον ὁράτω."},{"number":89,"text":"Ἐπισημήναντος δὲ τοῦ θεοῦ καὶ ὕειν ἀρξαμένου τὸ ὕδωρ ἡμέραις τεσσαράκοντα ὅλαις κατεφέρετο, ὡς ἐπὶ πήχεις πεντεκαίδεκα τὴν γῆν ὑπερέχειν. καὶ τοῦτο ἦν τὸ αἴτιον τοῦ μὴ διασωθῆναι πλείονας φυγῆς ἀφορμὴν οὐκ ἔχοντας."},{"number":90,"text":"παυσαμένου δὲ τοῦ ὑετοῦ μόλις ἤρξατο ὑποβαίνειν τὸ ὕδωρ ἐφʼ ἡμέρας ἑκατὸν καὶ πεντήκοντα, ὡς μηνὶ ἑβδόμῳ, ἱσταμένου δὲ ἦν ἑβδόμη, κατʼ ὀλίγον ὑπονοστεῖν ἀπολήγοντος. ἔπειτα τῆς λάρνακος περὶ ἄκραν τινὰ ὄρους σταθείσης κατὰ τὴν Ἀρμενίαν συνεὶς ὁ Νῶχος ἀνοίγει τʼ αὐτὴν καὶ θεασάμενος γῆν βραχεῖαν περὶ αὐτὴν ἐπὶ χρηστοτέρας ἤδη γεγονὼς ἐλπίδος ἠρέμει."},{"number":91,"text":"ὀλίγαις δʼ ὕστερον ἡμέραις μᾶλλον ὑποχωροῦντος τοῦ ὕδατος μεθίησι κόρακα βουλόμενος μαθεῖν, εἴ τι καὶ ἄλλο τῆς γῆς ἐκλελειμμένον ὑπὸ τοῦ ὕδατος ἀσφαλές ἐστιν ἤδη πρὸς ἔκβασιν· ὁ δὲ πᾶσαν εὑρὼν ἔτι λιμναζομένην πρὸς Νῶχον ἐπανῆλθε. μετὰ δὲ ἡμέρας ἑπτὰ περιστερὰν ἐπὶ τῷ γνῶναι τὰ περὶ τὴν γῆν προύπεμψεν·"},{"number":92,"text":"ἐπανελθούσης δὲ πεπηλωμένης ἅμα καὶ θαλλὸν ἐλαίας κομιζούσης, μαθὼν τὴν γῆν ἀπηλλαγμένην τοῦ κατακλυσμοῦ μείνας ἄλλας ἑπτὰ ἡμέρας τά τε ζῷα τῆς λάρνακος ἐξαφίησιν αὐτός τε μετὰ τῆς γενεᾶς προελθὼν καὶ θύσας τῷ θεῷ συνευωχεῖτο τοῖς οἰκείοις. ἀποβατήριον μέντοι τὸν τόπον τοῦτον Ἀρμένιοι καλοῦσιν· ἐκεῖ γὰρ ἀνασωθείσης τῆς λάρνακος ἔτι νῦν αὐτῆς τὰ λείψανα ἐπιδεικνύουσι."},{"number":93,"text":"Τοῦ δὲ κατακλυσμοῦ τούτου καὶ τῆς λάρνακος μέμνηνται πάντες οἱ τὰς βαρβαρικὰς ἱστορίας ἀναγεγραφότες, ὧν ἐστι Βηρωσὸς ὁ Χαλδαῖος· διηγούμενος γὰρ τὰ περὶ τὸν κατακλυσμὸν οὕτως που διέξεισι· λέγεται δὲ καὶ τοῦ πλοίου ἐν τῇ Ἀρμενίᾳ πρὸς τῷ ὄρει τῶν Κορδυαίων ἔτι μέρος τι εἶναι καὶ κομίζειν τινὰς τῆς ἀσφάλτου ἀφαιροῦντας· χρῶνται δʼ οἱ ἄνθρωποι τῷ κομιζομένῳ πρὸς τοὺς ἀποτροπιασμούς."},{"number":94,"text":"μέμνηται δὲ τούτων καὶ Ἱερώνυμος ὁ Αἰγύπτιος ὁ τὴν ἀρχαιολογίαν τὴν Φοινικικὴν συγγραψάμενος καὶ Μνασέας δὲ καὶ ἄλλοι πλείους, καὶ Νικόλαος δὲ ὁ Δαμασκηνὸς ἐν τῇ ἐνενηκοστῇ καὶ ἕκτῃ βίβλῳ ἱστορεῖ περὶ αὐτῶν λέγων οὕτως·"},{"number":95,"text":"ἔστιν ὑπὲρ τὴν Μινυάδα μέγα ὄρος κατὰ τὴν Ἀρμενίαν Βάρις λεγόμενον, εἰς ὃ πολλοὺς συμφυγόντας ἐπὶ τοῦ κατακλυσμοῦ λόγος ἔχει περισωθῆναι καί τινα ἐπὶ λάρνακος ὀχούμενον ἐπὶ τὴν ἀκρώρειαν ὀκεῖλαι καὶ τὰ λείψανα τῶν ξύλων ἐπὶ πολὺ σωθῆναι. γένοιτο δʼ ἂν οὗτος, ὅντινα καὶ Μωυσῆς ἀνέγραψεν ὁ Ἰουδαίων νομοθέτης."},{"number":96,"text":"Νῶχος δὲ φοβούμενος, μὴ καθʼ ἕκαστον ἔτος ἐπικλύζῃ τὴν γῆν ὁ θεὸς φθορὰν ἀνθρώπων καταψηφισάμενος, ἱερὰ καύσας ἐδεῖτο τὸν θεὸν τοῦ λοιποῦ ἐπὶ τῆς πρώτης μένειν εὐταξίας καὶ μηδὲν ἔτι τοιοῦτον ἐπενεγκεῖν πάθος, ὑφʼ οὗ κινδυνεύσει πᾶν ἀπολέσθαι τὸ τῶν ζῴων γένος, ἀλλὰ τετιμωρημένον τοὺς πονηροὺς φειδὼ ποιεῖσθαι τῶν διὰ χρηστότητα περιλειφθέντων καὶ τὸ δεινὸν διαφυγεῖν κεκριμένων·"},{"number":97,"text":"κακοδαιμονεστέρους γὰρ ἐκείνων ἔσεσθαι καὶ χείρω κακίαν καταδικασθέντας, εἰ μὴ πρὸς τὸ παντελὲς εἶεν σεσωσμένοι, τηρηθεῖεν δʼ ἑτέρῳ κατακλυσμῷ, τοῦ μὲν πρώτου τὸν φόβον καὶ τὴν ἱστορίαν μαθόντες τοῦ δευτέρου δὲ τὴν ἀπώλειαν."},{"number":98,"text":"εὐμενῶς τε οὖν αὐτὸν προσδέχεσθαι τὴν θυσίαν παρεκάλει καὶ μηδεμίαν ὀργὴν ἐπὶ τὴν γῆν ὁμοίαν βαλεῖν, ὅπως ἔργοις τε τοῖς ταύτης προσλιπαροῦντες καὶ πόλεις ἀναστήσαντες εὐδαιμόνως ζῆν ἔχοιεν καὶ μηδενὸς ὧν καὶ πρὸ τῆς ἐπομβρίας ἀπέλαυον ὑστερῶσιν ἀγαθῶν, εἰς μακρὸν αὐτῶν γῆρας καὶ βίου μῆκος ὅμοιον τοῖς τάχιον ἐπερχομένων."},{"number":99,"text":"Νώχου δὲ ταύτας ποιησαμένου τὰς ἱκετείας ὁ θεὸς ἐπὶ δικαιοσύνῃ τὸν ἄνδρα ἀγαπῶν ἐπένευεν αὐτῷ τὰς εὐχὰς εἰς τέλος ἄξειν, οὔτε τοὺς διεφθαρμένους λέγων αὐτὸς ἀπολέσαι, κακίᾳ δὲ τῇ οἰκείᾳ ταύτην αὐτοὺς ὑποσχεῖν τὴν δίκην, οὔτʼ ἄν, εἰ γενομένους ἀνθρώπους ἀφανίσαι διεγνώκει, παραγαγεῖν αὐτοὺς εἰς τὸν βίον,"},{"number":100,"text":"σῶφρον γὰρ εἶναι τὴν ἀρχὴν αὐτοῖς μηδὲ χαρίσασθαι τὸ ζῆν ἢ δόντα τοῦτο διαφθείρειν· ἀλλʼ οἷς ἐξύβριζον εἰς τὴν ἐμὴν εὐσέβειαν καὶ ἀρετήν, τούτοις ἐξεβιάσαντό με ταύτην αὐτοῖς ἐπιθεῖναι τὴν δίκην."},{"number":101,"text":"παύσομαι δὲ τοῦ λοιποῦ μετὰ τοσαύτης ὀργῆς τὰς τιμωρίας ἐπὶ τοῖς ἀδικήμασιν εἰσπραττόμενος καὶ πολὺ μᾶλλον σοῦ παρακαλοῦντος. εἰ δʼ ἐπὶ πλέον ποτὲ χειμάσαιμι, μὴ δείσητε τῶν ὄμβρων τὸ μέγεθος· οὐ γὰρ ἔτι τὴν γῆν ἐπικλύσει τὸ ὕδωρ."},{"number":102,"text":"παραινῶ μέντοι σφαγῆς ἀνθρωπίνης ἀπέχεσθαι καὶ καθαρεύειν φόνου τοὺς δράσαντάς τι τοιοῦτον κολάζοντας, χρῆσθαι δὲ τοῖς ἄλλοις ζῴοις ἅπασι πρὸς ἃ βούλεσθε καὶ τὰς ὀρέξεις ἔχετε. δεσπότας γὰρ ἁπάντων ὑμᾶς εἶναι πεποίηκα τῶν τε χερσαίων καὶ νηκτῶν καὶ ὅσα τὴν μετάρσιον αἰώραν ἔχει καὶ φοράν, χωρὶς αἵματος· ἐν τούτῳ γάρ ἐστιν ἡ ψυχή."},{"number":103,"text":"σημανῶ δὲ ὑμῖν παῦλαν ἐσομένην τοξείᾳ τῇ ἐμῇ τὴν ἶριν ἀποσημαίνων· τόξον γὰρ εἶναι τοῦ θεοῦ παρὰ τοῖς ἐκεῖ νενόμισται. καὶ ὁ μὲν θεὸς ταῦτʼ εἰπὼν καὶ ὑποσχόμενος ἀπαλλάσσεται."},{"number":104,"text":"Νῶχος δὲ βιοὺς μετὰ τὴν ἐπομβρίαν πεντήκοντα καὶ τριακόσια ἔτη καὶ πάντα τὸν χρόνον τοῦτον εὐδαιμόνως διαγαγὼν τελευτᾷ ζήσας ἐτῶν ἀριθμὸν ἐνακοσίων καὶ πεντήκοντα."},{"number":105,"text":"μηδεὶς δὲ πρὸς τὸν νῦν βίον καὶ τὴν βραχύτητα τῶν ἐτῶν ἃ ζῶμεν συμβαλὼν τὸν τῶν παλαιῶν ψευδῆ νομιζέτω τὰ περὶ ἐκείνων λεγόμενα τῷ μηδένα νῦν τοσοῦτον ἐν τῷ βίῳ παρατείνειν χρόνον τεκμαιρόμενος μηδʼ ἐκείνους εἰς ἐκεῖνο τὸ μῆκος τῆς ζωῆς ἀφῖχθαι."},{"number":106,"text":"οἱ μὲν γὰρ θεοφιλεῖς ὄντες καὶ ὑπʼ αὐτοῦ τοῦ θεοῦ γενόμενοι καὶ διὰ τὰς τροφὰς ἐπιτηδειοτέρας πρὸς πλείονα χρόνον οὔσας εἰκότως ἔζων πλῆθος τοσοῦτον ἐτῶν· ἔπειτα καὶ διʼ ἀρετὴν καὶ τὴν εὐχρηστίαν ὧν ἐπενόουν ἀστρονομίας καὶ γεωμετρίας πλεῖον ζῆν τὸν θεὸν αὐτοῖς παρασχεῖν, ἅπερ οὐκ ἦν ἀσφαλῶς αὐτοῖς προειπεῖν μὴ ζήσασιν ἑξακοσίους ἐνιαυτούς· διὰ τοσούτων γὰρ ὁ μέγας ἐνιαυτὸς πληροῦται."},{"number":107,"text":"μαρτυροῦσι δέ μου τῷ λόγῳ πάντες οἱ παρʼ Ἕλλησι καὶ βαρβάροις συγγραψάμενοι τὰς ἀρχαιολογίας· καὶ γὰρ καὶ Μανέθων ὁ τὴν Αἰγυπτίων ποιησάμενος ἀναγραφὴν καὶ Βηρωσὸς ὁ τὰ Χαλδαϊκὰ συναγαγὼν καὶ Μῶχός τε καὶ Ἑστιαῖος καὶ πρὸς τούτοις ὁ Αἰγύπτιος Ἱερώνυμος οἱ τὰ Φοινικικὰ συγγραψάμενοι συμφωνοῦσι τοῖς ὑπʼ ἐμοῦ λεγομένοις,"},{"number":108,"text":"Ἡσίοδός τε καὶ Ἑκαταῖος καὶ Ἑλλάνικος καὶ Ἀκουσίλαος καὶ πρὸς τούτοις Ἔφορος καὶ Νικόλαος ἱστοροῦσι τοὺς ἀρχαίους ζήσαντας ἔτη χίλια. περὶ μὲν τούτων, ὡς ἂν ἑκάστοις ᾖ φίλον, οὕτω σκοπείτωσαν."}],"4":[{"number":109,"text":"Οἱ δὲ Νώχου παῖδες τρεῖς ὄντες Σημᾶς καὶ Ἰαφθᾶς καὶ Χαμᾶς ἔτεσιν ἑκατὸν ἔμπροσθεν τῆς ἐπομβρίας γεγονότες, πρῶτοι κατελθόντες ἀπὸ τῶν ὀρῶν εἰς τὰ πεδία τὴν ἐν τούτοις οἴκησιν ἐποιήσαντο, καὶ τοὺς ἄλλους σφόδρα δεδιότας διὰ τὸν κατακλυσμὸν τὰ πεδία καὶ ὀκνηρῶς ἔχοντας πρὸς τὴν ἀπὸ τῶν ὑψηλῶν τόπων κατάβασιν ἔπεισαν θαρσήσαντας μιμητὰς αὐτῶν γενέσθαι."},{"number":110,"text":"καὶ τὸ μὲν πεδίον, εἰς ὃ πρῶτον αὐτοὺς κατῴκισαν, καλεῖται Σεναάρ· τοῦ δὲ θεοῦ κελεύσαντος αὐτοὺς διὰ πολυανθρωπίαν στέλλειν ἀποικίας, ἵνα μὴ στασιάζοιεν πρὸς ἀλλήλους, ἀλλὰ γῆν πολλὴν γεωργοῦντες ἀφθονίας ἀπολαύοιεν τῶν καρπῶν, ὑπὸ ἀμαθίας παρήκουσαν τοῦ θεοῦ καὶ διὰ τοῦτο συμφοραῖς περιπεσόντες ᾔσθοντο τῆς ἁμαρτίας·"},{"number":111,"text":"ἐπεὶ γὰρ ἤνθουν νεότητος πλήθει, πάλιν ὁ θεὸς αὐτοῖς συνεβούλευσε ποιεῖσθαι τὴν ἀποικίαν· οἱ δὲ οὐ κατὰ τὴν εὐμένειαν τὴν ἐκείνου νομίζοντες ἔχειν τὰ ἀγαθά, τὴν δʼ ἰσχὺν αὐτοῖς τὴν οἰκείαν αἰτίαν τῆς εὐπορίας ὑπολαμβάνοντες οὐκ ἐπείθοντο."},{"number":112,"text":"προσετίθεσαν δὲ τῷ παρακούειν τῆς τοῦ θεοῦ γνώμης καὶ τὸ κατʼ ἐπιβουλὴν ὑπονοεῖν εἰς ἀποικίαν αὐτοὺς παρορμᾶν, ἵνα διαιρεθέντες εὐεπιχειρητότεροι γένωνται."},{"number":113,"text":"Ἐξῆρέ τε αὐτοὺς πρός τε ὕβριν τοῦ θεοῦ καὶ καταφρόνησιν Ναβρώδης, ὃς υἱωνὸς μὲν ἦν Χάμου τοῦ Νώχου, τολμηρὸς δὲ καὶ κατὰ χεῖρα γενναῖος· ἔπειθεν οὖν αὐτοὺς μὴ τῷ θεῷ διδόναι τὸ διʼ ἐκεῖνον εὐδαιμονεῖν, ἀλλὰ τὴν ἰδίαν ἀρετὴν ταῦτα παρέχειν αὐτοῖς ἡγεῖσθαι,"},{"number":114,"text":"καὶ περιίστα δὲ κατʼ ὀλίγον εἰς τυραννίδα τὰ πράγματα μόνως οὕτως νομίζων ἀποστήσειν τοὺς ἀνθρώπους τοῦ φόβου τοῦ παρὰ τοῦ θεοῦ, εἰ χρώμενοι τῇ αὐτοῦ δυνάμει διατελοῖεν, ἀμυνεῖσθαί τε τὸν θεὸν πάλιν ἠπείλει τὴν γῆν ἐπικλύσαι θελήσαντα· πύργον γὰρ οἰκοδομήσειν ὑψηλότερον ἢ τὸ ὕδωρ ἀναβῆναι δυνηθείη, μετελεύσεσθαι δὲ καὶ τῆς τῶν προγόνων ἀπωλείας."},{"number":115,"text":"Τὸ δὲ πλῆθος πρόθυμον ἦν τοῖς Ναβρώδου ἕπεσθαι δόγμασι δουλείαν ἡγούμενοι τὸ εἴκειν τῷ θεῷ, καὶ τὸν πύργον ᾠκοδόμουν οὐδὲν ἀπολείποντες σπουδῆς οὐδὲ πρὸς τὸ ἔργον ὀκνηρῶς ἔχοντες· ἐλάμβανε δὲ θᾶττον ὕψος ἢ προσεδόκησεν ἄν τις ὑπὸ πολυχειρίας."},{"number":116,"text":"τὸ μέντοι πάχος ἦν ἰσχυρὸν τοσοῦτον, ὥσθʼ ὑπʼ αὐτοῦ μειοῦσθαι τοῖς ὁρῶσι τὸ μῆκος. ᾠκοδομεῖτο δὲ ἐκ πλίνθου ὀπτῆς ἀσφάλτῳ συνδεδεμένης, ὡς ἂν μὴ περιρρέοι. οὕτως δὲ μεμηνότας αὐτοὺς ὁρῶν ὁ θεὸς ἀφανίσαι μὲν ἐκ παντὸς οὐκ ἔκρινεν, ὅτι μηδʼ ὑπὸ τῶν πρώτων ἀπολωλότων σωφρονισθεῖεν,"},{"number":117,"text":"εἰς στάσιν δὲ αὐτοὺς ἐνέβαλεν ἀλλογλώσσους ἀπεργασάμενος καὶ ὑπὸ πολυφωνίας ποιήσας ἑαυτῶν ἀσυνέτους εἶναι. ὁ δὲ τόπος ἐν ᾧ τὸν πύργον ᾠκοδόμησαν νῦν Βαβυλὼν καλεῖται διὰ τὴν σύγχυσιν τοῦ περὶ τὴν διάλεκτον πρῶτον ἐναργοῦς· Ἑβραῖοι γὰρ τὴν σύγχυσιν βαβὲλ καλοῦσι."},{"number":118,"text":"περὶ δὲ τοῦ πύργου τούτου καὶ τῆς ἀλλοφωνίας τῶν ἀνθρώπων μέμνηται καὶ Σίβυλλα λέγουσα οὕτως· πάντων ὁμοφώνων ὄντων τῶν ἀνθρώπων πύργον ᾠκοδόμησάν τινες ὑψηλότατον ὡς ἐπὶ τὸν οὐρανὸν ἀναβησόμενοι διʼ αὐτοῦ. οἱ δὲ θεοὶ ἀνέμους ἐπιπέμψαντες ἀνέτρεψαν τὸν πύργον καὶ ἰδίαν ἑκάστῳ φωνὴν ἔδωκαν· καὶ διὰ τοῦτο Βαβυλῶνα συνέβη κληθῆναι τὴν πόλιν."},{"number":119,"text":"περὶ δὲ τοῦ πεδίου τοῦ λεγομένου Σεναὰρ ἐν τῇ Βαβυλωνίᾳ χώρᾳ μνημονεύει Ἑστιαῖος λέγων οὕτως· τῶν δὲ ἱερέων τοὺς διασωθέντας τὰ τοῦ Ἐνυαλίου Διὸς ἱερώματα λαβόντας εἰς Σεναὰρ τῆς Βαβυλωνίας ἐλθεῖν."}],"5":[{"number":120,"text":"Σκίδνανται δὴ τὸ λοιπὸν ἐντεῦθεν ὑπὸ τῆς ἀλλογλωσσίας τὰς ἀποικίας ποιησάμενοι πανταχοῦ, καὶ γῆν ἕκαστοι κατελάμβανον τὴν ἐντυχοῦσαν καὶ εἰς ἣν αὐτοὺς ἦγεν ὁ θεός, ὡς πληρωθῆναι πᾶσαν αὐτῶν ἤπειρον μεσόγεών τε καὶ παράλιον· εἰσὶ δʼ οἳ καὶ περαιωσάμενοι ναυσὶ τὰς νήσους κατῴκησαν."},{"number":121,"text":"καὶ τῶν ἐθνῶν ἔνια μὲν διασώζει τὰς ὑπὸ τῶν κτισάντων κειμένας προσηγορίας, ἔνια δὲ καὶ μετέβαλεν, οἱ δὲ καὶ πρὸς τὸ σαφέστερον εἶναι δοκοῦν τοῖς παροικοῦσι τροπὴν ἔλαβον. Ἕλληνες δʼ εἰσὶν οἱ τούτου καταστάντες αἴτιοι· ἰσχύσαντες γὰρ ἐν τοῖς ὕστερον ἰδίαν ἐποιήσαντο καὶ τὴν πάλαι δόξαν καλλωπίσαντες τὰ ἔθνη τοῖς ὀνόμασι πρὸς τὸ συνετὸν αὐτοῖς καὶ κόσμον θέμενοι πολιτείας ὡς ἀφʼ αὑτῶν γεγονόσιν."}],"6":[{"number":122,"text":"Ἦσαν δὲ τῶν Νώχου παίδων υἱοί, ὧν ἐπὶ τιμῇ τοῖς ἔθνεσι τὰ ὀνόματα ἐπετίθεσαν οἱ γῆν τινα καταλαβόντες. Ἰαφθᾶ μὲν οὖν τοῦ Νώχου παιδὸς ἦσαν ἑπτὰ υἱοί. κατοικοῦσι δὲ οὗτοι ἀπὸ Ταύρου καὶ Ἀμάνου τῶν ὀρῶν ἀρξάμενοι καὶ προῆλθον ἐπὶ μὲν τῆς Ἀσίας ἄχρι ποταμοῦ Τανάιδος, ἐπὶ δὲ τῆς Εὐρώπης ἕως Γαδείρων γῆν ἣν ἔτυχον καταλαμβάνοντες, καὶ μηδενὸς προκατῳκηκότος τὰ ἔθνη τοῖς αὑτῶν ἐκάλουν ὀνόμασιν."},{"number":123,"text":"τοὺς γὰρ νῦν ὑφʼ Ἑλλήνων Γαλάτας καλουμένους, Γομαρεῖς δὲ λεγομένους, Γόμαρος ἔκτισε. Μαγώγης δὲ τοὺς ἀπʼ αὐτοῦ Μαγώγας ὀνομασθέντας ᾤκισεν, Σκύθας δὲ ὑπʼ αὐτῶν προσαγορευομένους."},{"number":124,"text":"τῶν δὲ Ἰαφθᾶ παίδων Ἰαυάνου καὶ Μάδου ἀπὸ μὲν τούτου Μαδαῖοι γίνονται ἔθνος, οἳ πρὸς Ἑλλήνων Μῆδοι κέκληνται, ἀπὸ δὲ Ἰαυάνου Ἰωνία καὶ πάντες Ἕλληνες γεγόνασι. κατοικίζει δὲ καὶ Θεοβήλους Θεόβηλος, οἵτινες ἐν τοῖς νῦν Ἴβηρες καλοῦνται."},{"number":125,"text":"καὶ Μεσχῆνοι δὲ ὑπὸ Μέσχου κτισθέντες Καππάδοκες μὲν ἄρτι κέκληνται, τῆς δὲ ἀρχαίας αὐτῶν προσηγορίας σημεῖον δείκνυται· πόλις γάρ ἐστι παρʼ αὐτοῖς ἔτι καὶ νῦν Μάζακα, δηλοῦσα τοῖς συνιέναι δυναμένοις οὕτως ποτὲ προσαγορευθὲν πᾶν τὸ ἔθνος. Θείρης δὲ Θείρας μὲν ἐκάλεσεν ὧν ἦρξεν, Ἕλληνες δὲ Θρᾷκας αὐτοὺς μετωνόμασαν."},{"number":126,"text":"καὶ τοσαῦτα μὲν ἔθνη ὑπὸ τῶν Ἰαφέθου παίδων κατοικεῖται· Γομάρου δὲ τριῶν υἱῶν γενομένων Ἀσχανάξης μὲν Ἀσχανάξους ᾤκισεν, οἳ νῦν Ῥήγινες ὑπὸ τῶν Ἑλλήνων καλοῦνται, Ῥιφάθης δὲ Ῥιφαθαίους τοὺς Παφλαγόνας λεγομένους, Θυγράμης δὲ Θυγραμαίους, οἳ δόξαν Ἕλλησι Φρύγες ὠνομάσθησαν."},{"number":127,"text":"Ἰαυάνου δὲ τοῦ Ἰάφθου τριῶν καὶ αὐτοῦ παίδων γενομένων Ἁλισᾶς μὲν Ἁλισαίους ἐκάλεσεν ὧν ἦρχεν, Αἰολεῖς δὲ νῦν εἰσι, Θάρσος δὲ Θαρσεῖς· οὕτως γὰρ ἐκαλεῖτο τὸ παλαιὸν ἡ Κιλικία. σημεῖον δέ· Ταρσὸς γὰρ παρʼ αὐτοῖς τῶν πόλεων ἡ ἀξιολογωτάτη καλεῖται μητρόπολις οὖσα τὸ ταῦ πρὸς τὴν κλῆσιν ἀντὶ τοῦ θῆτα μεταβαλόντων."},{"number":128,"text":"Χέθιμος δὲ Χέθιμα τὴν νῆσον ἔσχε, Κύπρος αὕτη νῦν καλεῖται, καὶ ἀπʼ αὐτῆς νῆσοί τε πᾶσαι καὶ τὰ πλείω τῶν παρὰ θάλατταν Χέθη ὑπὸ Ἑβραίων ὀνομάζεται· μάρτυς δέ μου τῷ λόγῳ μία τῶν ἐν Κύπρῳ πόλεων ἰσχύσασα τὴν προσηγορίαν φυλάξαι· Κίτιον γὰρ ὑπὸ τῶν ἐξελληνισάντων αὐτὴν καλεῖται μηδʼ οὕτως διαφυγοῦσα τοῦ Χεθίμου τὸ ὄνομα. Ἰαφθᾶ μὲν δὴ παῖδές τε καὶ υἱωνοὶ τοσαῦτα ἔσχον ἔθνη."},{"number":129,"text":"ὃ δʼ ἴσως ὑφʼ Ἑλλήνων ἀγνοεῖται, τοῦτο προειπὼν τρέψομαι πρὸς τὴν ἀφήγησιν ὧν κατέλιπον. τὰ γὰρ ὀνόματα διὰ τὸ τῆς γραφῆς εὐπρεπὲς ἡλλήνισται πρὸς ἡδονὴν τῶν ἐντευξομένων· οὐ γὰρ ἐπιχώριος ἡμῖν ὁ τοιοῦτος αὐτῶν τύπος, ἀλλʼ ἕν τε αὐτῶν σχῆμα καὶ τελευτὴ μία, Νῶχός τέ τοι Νῶε καλεῖται καὶ τοῦτον τὸν τύπον ἐπὶ παντὸς τηρεῖ σχήματος."},{"number":130,"text":"Οἱ δὲ Χάμου παῖδες τὴν ἀπὸ Συρίας καὶ Ἀμάνου καὶ Λιβάνου τῶν ὀρῶν γῆν κατέσχον, ὅσα πρὸς θάλασσαν αὐτῆς ἐτέτραπτο καταλαβόντες καὶ τὰ μέχρι τοῦ ὠκεανοῦ ἐξιδιωσάμενοι· αἱ μέντοι προσηγορίαι τῶν μὲν καὶ παντελῶς ἐξίτηλοι γεγόνασιν, ἐνίων δὲ μεταβαλοῦσαι καὶ μεταρρυθμισθεῖσαι πρὸς ἑτέρας δύσγνωστοι τυγχάνουσιν, ὀλίγοι δὲ οἱ φυλάξαντες ἀκεραίους τὰς προσηγορίας ὑπάρχουσι."},{"number":131,"text":"τεσσάρων γὰρ Χάμου παίδων γενομένων Χουσαῖον μὲν οὐδὲν ἔβλαψεν ὁ χρόνος· Αἰθίοπες γὰρ ὧν ἦρξεν ἔτι καὶ νῦν ὑπὸ ἑαυτῶν τε καὶ τῶν ἐν τῇ Ἀσίᾳ πάντων Χουσαῖοι καλοῦνται."},{"number":132,"text":"ἐτηρήθη δὲ καὶ Μερσαίοις ἡ κατὰ τὴν προσηγορίαν μνήμη· τὴν γὰρ Αἴγυπτον Μέρσην καὶ Μερσαίους τοὺς Αἰγυπτίους ἅπαντες οἱ ταύτῃ καλοῦμεν. ἔκτισε δὲ καὶ Φούδης τὴν Λιβύην Φούτους ἀπʼ αὐτοῦ καλέσας τοὺς ἐπιχωρίους."},{"number":133,"text":"ἔστι δὲ καὶ ποταμὸς ἐν τῇ Μαύρων χώρᾳ τοῦτο ἔχων τὸ ὄνομα, ὅθεν καὶ τοὺς πλείστους τῶν Ἑλληνικῶν ἱστοριογράφων ἔστιν ἰδεῖν μεμνημένους τοῦ ποταμοῦ καὶ τῆς παρακειμένης αὐτῷ χώρας Φούτης λεγομένης. μετέβαλε δὲ ὃ νῦν αὐτῇ ἐστιν ὄνομα ἀπὸ τῶν Μεσράμου υἱῶν Λίβυος λεγομένου· μετʼ οὐ πολὺ δʼ ἐροῦμεν τὴν αἰτίαν, διʼ ἣν αὐτὴν καὶ Ἀφρικὴν προσαγορεύεσθαι συμβέβηκε."},{"number":134,"text":"Χαναναῖος δὲ τέταρτος ὢν Χάμου παῖς τὴν νῦν Ἰουδαίαν καλουμένην οἰκίσας ἀπʼ αὐτοῦ Χαναναίαν προσηγόρευσεν. γίνονται δὲ παῖδες ἐξ αὐτῶν Χούσου μὲν ἕξ, ὧν Σάβας μὲν Σαβαίους, Εὐίλας δὲ Εὐιλαίους ἔκτισεν, οἳ νῦν Γαιτοῦλοι λέγονται, Σαβάθης δὲ Σαβαθηνούς, ὀνομάζονται δὲ Ἀστάβαροι παρʼ Ἕλλησιν·"},{"number":135,"text":"οἰκίζει δὲ καὶ Σαβάκτας Σαβακτηνούς· Ῥάμος δὲ Ῥαμαίους ᾤκισε καὶ δύο παῖδας ἔσχεν, ὧν Ἰουδάδας μὲν Ἰουδαδαίους Αἰθιοπικὸν ἔθνος τῶν ἑσπερίων οἰκίσας ἐπωνύμους αὐτῷ κατέλιπε, Σαβαίους δὲ Σαβαῖος· Ναβρώδης δὲ Χούσου υἱὸς ὑπομείνας παρὰ Βαβυλωνίοις ἐτυράννησεν, ὡς καὶ πρότερόν μοι δεδήλωται."},{"number":136,"text":"τῶν δὲ Μεσραίου παίδων ὀκτὼ γενομένων οἱ πάντες τὴν ἀπὸ Γάζης ἕως Αἰγύπτου γῆν κατέσχον, μόνου δὲ Φυλιστίνου τὴν ἐπωνυμίαν ἡ χώρα διεφύλαξε· Παλαιστίνην γὰρ οἱ Ἕλληνες αὐτοῦ τὴν μοῖραν καλοῦσι."},{"number":137,"text":"τῶν δὲ ἄλλων, Λουμαίου καὶ Ἀναμία καὶ Λαβίμου τοῦ μόνου κατοικήσαντος ἐν Λιβύῃ καὶ ὧδε τὴν χώραν ἀπʼ αὐτοῦ καλέσαντος, Νεδέμου τε καὶ Πεθρωσίμου καὶ Χεσλοίμου καὶ Χεφθώμου πέρα τῶν ὀνομάτων οὐδὲν ἴσμεν· ὁ γὰρ Αἰθιοπικὸς πόλεμος, περὶ οὗ δηλώσομεν ὕστερον, ἀναστάτους αὐτῶν τὰς πόλεις ἐποίησεν."},{"number":138,"text":"ἐγένοντο δὲ καὶ Χαναναίου παῖδες, Σιδώνιος, ὃς καὶ πόλιν ἐπώνυμον ἔκτισεν ἐν τῇ Φοινίκῃ, Σιδὼν δʼ ὑφʼ Ἑλλήνων καλεῖται· Ἀμαθοῦς δὲ Ἀμάθουν κατῴκισεν, ἥτις ἔστι καὶ νῦν ὑπὸ μὲν τῶν ἐπιχωρίων Ἀμάθη καλουμένη, Μακεδόνες δʼ αὐτὴν Ἐπιφάνειαν ἀφʼ ἑνὸς τῶν ἐπιγόνων ἐπωνόμασαν· Ἀρουδαῖος δὲ Ἄραδον τὴν νῆσον ἔσχεν· Ἀρουκαῖος δὲ Ἄρκην τὴν ἐν τῷ Λιβάνῳ."},{"number":139,"text":"τῶν δὲ ἄλλων ἑπτά, Εὐαίου Χετταίου Ἰεβουσαίου Ἀμορραίου Γεργεσαίου Σειναίου Σαμαραίου, πλὴν τῶν ὀνομάτων ἐν ταῖς ἱεραῖς βίβλοις οὐδὲν ἔχομεν· Ἑβραῖοι γὰρ αὐτῶν ἀνέστησαν τὰς πόλεις ἐκ τοιαύτης αἰτίας ἐν συμφορᾷ γενομένας·"},{"number":140,"text":"Νῶχος μετὰ τὴν ἐπομβρίαν τῆς γῆς κατασταθείσης εἰς τὴν αὐτῆς φύσιν ἐπʼ ἔργα χωρεῖ καὶ καταφυτεύσας αὐτὴν ἀμπέλοις, ἡνίκα τοῦ καρποῦ τελεσφορηθέντος καθʼ ὥραν ἐτρύγησε καὶ παρῆν εἰς χρῆσιν ὁ οἶνος, θύσας ἐν εὐωχίαις ἦν."},{"number":141,"text":"μεθυσθεὶς δὲ εἰς ὕπνον καταφέρεται καὶ γεγυμνωμένος παρακόσμως ἔκειτο. θεασάμενος δὲ αὐτὸν ὁ νεώτατος τῶν παίδων τοῖς ἀδελφοῖς ἐπιγελῶν δείκνυσιν· οἱ δὲ περιστέλλουσι τὸν πατέρα."},{"number":142,"text":"καὶ Νῶχος αἰσθόμενος τοῖς μὲν ἄλλοις παισὶν εὐδαιμονίαν εὔχεται, τῷ δὲ Χαμᾷ διὰ τὴν συγγένειαν αὐτῷ μὲν οὐ κατηράσατο, τοῖς δʼ ἐγγόνοις αὐτοῦ· καὶ τῶν ἄλλων διαπεφευγότων τὴν ἀρὰν τοὺς Χαναναίου παῖδας μέτεισιν ὁ θεός. καὶ περὶ μὲν τούτων ἐν τοῖς ἑξῆς ἐροῦμεν."},{"number":143,"text":"Σημᾷ δὲ τῷ τρίτῳ τῶν Νώχου υἱῶν πέντε γίνονται παῖδες, οἳ τὴν μέχρι τοῦ κατʼ Ἰνδίαν ὠκεανοῦ κατοικοῦσιν Ἀσίαν ἀπʼ Εὐφράτου τὴν ἀρχὴν πεποιημένοι. Ἔλυμος μὲν γὰρ Ἐλυμαίους Περσῶν ὄντας ἀρχηγέτας κατέλιπεν· Ἀσσούρας δὲ Νίνον οἰκίζει πόλιν καὶ τοὺς ὑπηκόους Ἀσσυρίους ἐπωνόμασεν, οἳ μάλιστα εὐδαιμόνησαν·"},{"number":144,"text":"Ἀρφαξάδης δὲ τοὺς νῦν Χαλδαίους καλουμένους Ἀρφαξαδαίους ὠνόμασεν ἄρξας αὐτῶν· Ἀραμαίους δὲ Ἄραμος ἔσχεν, οὓς Ἕλληνες Σύρους προσαγορεύουσιν· οὓς δὲ Λυδοὺς νῦν καλοῦσι, Λούδους δὲ τότε, Λούδας ἔκτισε."},{"number":145,"text":"τῶν δὲ Ἀράμου παίδων τεσσάρων ὄντων Οὔσης μὲν κτίζει τὴν Τραχωνῖτιν καὶ Δαμασκόν, μέση δʼ ἐστὶ τῆς Παλαιστίνης καὶ κοίλης Συρίας· Ἀρμενίαν δὲ Ὄτρος, καὶ Γεθέρης Βακτριανούς, Μήσας δὲ Μησαναίους, Σπασίνου Χάραξ ἐν τοῖς νῦν καλεῖται."},{"number":146,"text":"Ἀρφαξάδου δὲ παῖς γίνεται Σάλης, τοῦ δὲ Ἕβερος, ἀφʼ οὗ τοὺς Ἰουδαίους Ἑβραίους ἀρχῆθεν ἐκάλουν· Ἕβερος δὲ Ἰούκταν καὶ Φάλεγον ἐγέννησεν· ἐκλήθη δὲ Φάλεγος, ἐπειδὴ κατὰ τὸν ἀποδασμὸν τῶν οἰκήσεων τίκτεται· φαλὲκ γὰρ τὸν μερισμὸν Ἑβραῖοι καλοῦσιν."},{"number":147,"text":"Ἰούκτᾳ δὲ τῶν Ἑβέρου παίδων ἦσαν υἱοὶ Ἐλμόδαδος Σάλεφος Ἀζερμώθης Εἰράης Ἐδώραμος Οὐζάλης Δαήλης Ἤβαλος Ἀβιμάηλος Σάφας Ὀφίρης Εὐίλης Ἰόβηλος. οὗτοι ἀπὸ Κωφῆνος ποταμοῦ τῆς Ἰνδικῆς καὶ τῆς πρὸς αὐτῇ Σηρίας τινὰ κατοικοῦσι. ταῦτα μὲν περὶ τῶν Σημᾶ παίδων ἱστορήσθω."},{"number":148,"text":"Ποιήσομαι δὲ περὶ Ἑβραίων τὸν λόγον· Φαλέγου γὰρ τοῦ Ἑβέρου γίνεται παῖς Ῥεούς· τούτου δὲ Σεροῦγος, ᾧ Ναχώρης υἱὸς τίκτεται· τούτου δὲ Θέρρος· πατὴρ δὲ οὗτος Ἁβράμου γίνεται, ὃς δέκατος μέν ἐστιν ἀπὸ Νώχου, δευτέρῳ δʼ ἔτει καὶ ἐνενηκοστῷ πρὸς ἐνακοσίοις μετὰ τὴν ἐπομβρίαν ἐγένετο."},{"number":149,"text":"Θέρρος μὲν γὰρ ἑβδομηκοστῷ ποιεῖται τὸν Ἅβραμον· Ναχώρης δὲ Θέρρον εἰκοστὸν αὐτὸς ἔτος καὶ ἑκατοστὸν ἤδη γεγονὼς ἐγέννησε· Σερούγῳ δὲ Ναχώρης τίκτεται περὶ ἔτος δεύτερον καὶ τριακοστὸν καὶ ἑκατοστόν· Ῥοῦμος δὲ Σεροῦγον ἔτη τριάκοντα γεγονὼς πρὸς τοῖς ἑκατόν· ἐν δὲ τοῖς αὐτοῖς ἔτεσι καὶ Ῥοῦμον Φάλεγος ἔσχεν·"},{"number":150,"text":"Ἕβερος δὲ τετάρτῳ καὶ τριακοστῷ πρὸς τοῖς ἑκατὸν γεννᾷ Φάλεγον γεννηθεὶς αὐτὸς ὑπὸ Σέλου τριακοστὸν ἔτος ἔχοντος καὶ ἑκατοστόν, ὃν Ἀρφάξαδος ἐτέκνωσε κατὰ πέμπτον καὶ τριακοστὸν ἔτος πρὸς τοῖς ἑκατόν· Σημᾷ δὲ υἱὸς Ἀρφαξάδης ἦν μετὰ ἔτη δώδεκα τῆς ἐπομβρίας γενόμενος."},{"number":151,"text":"Ἅβραμος δὲ εἶχεν ἀδελφοὺς Ναχώρην καὶ Ἀράνην· τούτων Ἀράνης μὲν υἱὸν καταλιπὼν Λῶτον καὶ Σάρραν καὶ Μελχὰν θυγατέρας ἐν Χαλδαίοις ἀπέθανεν ἐν πόλει Οὐρῆ λεγομένῃ τῶν Χαλδαίων, καὶ τάφος αὐτοῦ μέχρι νῦν δείκνυται. γαμοῦσι δὲ τὰς ἀδελφιδὰς Μελχὰν μὲν Ναχώρης Σάρραν δὲ Ἅβραμος."},{"number":152,"text":"Θέρρου δὲ μισήσαντος τὴν Χαλδαίαν διὰ τὸ Ἀράνου πένθος μετοικίζονται πάντες εἰς Χαρρὰν τῆς Μεσοποταμίας, ὅπου καὶ Θέρρον τελευτήσαντα θάπτουσιν ἔτη βιώσαντα πέντε καὶ διακόσια· συνετέμνετο γὰρ ἤδη τοῖς ἀνθρώποις τὸ ζῆν καὶ βραχύτερον ἐγίνετο μέχρι τῆς Μωυσέος γενέσεως, μεθʼ ὃν ὅρος ἦν τοῦ ζῆν ἑκατὸν ἔτη πρὸς τοῖς εἴκοσι τοσαῦθʼ ὁρίσαντος τοῦ θεοῦ, ὅσα καὶ Μωυσεῖ συνέβη βιῶναι."},{"number":153,"text":"Ναχώρῃ μὲν οὖν ἐκ τῆς Μελχᾶς ὀκτὼ παῖδες ἐγένοντο, Οὖξος Βαοῦξος Μαουῆλος Ζάχαμος Ἀζαοῦος Ἰαδελφᾶς Ἰαδαφᾶς Βαθουῆλος· οὗτοι μὲν Ναχώρου παῖδες γνήσιοι· Ταβαῖος γὰρ καὶ Γάδαμος καὶ Τααῦος καὶ Μαχᾶς ἐκ Ῥούμας παλλακῆς αὐτῷ γεγόνασι. Βαθουήλῳ δὲ τῶν Ναχώρου γνησίων παίδων γίνεται Ῥεβέκκα θυγάτηρ καὶ Λάβανος υἱός."}],"7":[{"number":154,"text":"Ἅβραμος δὲ Λῶτον τὸν Ἀράνου τοῦ ἀδελφοῦ υἱὸν τῆς δὲ γυναικὸς αὐτοῦ Σάρρας ἀδελφὸν εἰσεποιήσατο γνησίου παιδὸς ἀπορῶν καὶ καταλείπει τὴν Χαλδαίαν ἑβδομήκοντα καὶ πέντε γεγονὼς ἔτη τοῦ θεοῦ κελεύσαντος εἰς τὴν Χαναναίαν μετελθεῖν, ἐν ᾗ κατῴκησε καὶ τοῖς ἀπογόνοις κατέλιπε δεινὸς ὢν συνεῖναί τε περὶ πάντων καὶ πιθανὸς τοῖς ἀκροωμένοις περί τε ὧν εἰκάσειεν οὐ διαμαρτάνων."},{"number":155,"text":"διὰ τοῦτο καὶ φρονεῖν μεῖζον ἐπʼ ἀρετῇ τῶν ἄλλων ἠργμένος καὶ τὴν περὶ τοῦ θεοῦ δόξαν, ἣν ἅπασι συνέβαινεν εἶναι, καινίσαι καὶ μεταβαλεῖν ἔγνω. πρῶτος οὖν τολμᾷ θεὸν ἀποφήνασθαι δημιουργὸν τῶν ὅλων ἕνα, τῶν δὲ λοιπῶν εἰ καί τι πρὸς εὐδαιμονίαν συντελεῖ κατὰ προσταγὴν τὴν τούτου παρέχειν ἕκαστον καὶ οὐ κατʼ οἰκείαν ἰσχύν."},{"number":156,"text":"εἰκάζεται δὲ ταῦτα τοῖς γῆς καὶ θαλάσσης παθήμασι τοῖς τε περὶ τὸν ἥλιον καὶ τὴν σελήνην καὶ πᾶσι τοῖς κατʼ οὐρανὸν συμβαίνουσι· δυνάμεως γὰρ αὐτοῖς παρούσης καὶ προνοῆσαι τῆς κατʼ αὐτοὺς εὐταξίας, ταύτης δʼ ὑστεροῦντας φανεροὺς γίνεσθαι μηδʼ ὅσα πρὸς τὸ χρησιμώτερον ἡμῖν συνεργοῦσι κατὰ τὴν αὐτῶν ἐξουσίαν, ἀλλὰ κατὰ τὴν τοῦ κελεύοντος ἰσχὺν ὑπουργεῖν, ᾧ καλῶς ἔχει μόνῳ τὴν τιμὴν καὶ τὴν εὐχαριστίαν ἀπονέμειν."},{"number":157,"text":"διʼ ἅπερ Χαλδαίων τε καὶ τῶν ἄλλων Μεσοποταμιτῶν στασιασάντων πρὸς αὐτὸν μετοικεῖν δοκιμάσας κατὰ βούλησιν καὶ βοήθειαν τοῦ θεοῦ τὴν Χαναναίαν ἔσχε γῆν, ἱδρυθείς τε αὐτόθι βωμὸν ᾠκοδόμησε καὶ θυσίαν ἐτέλεσε τῷ θεῷ."},{"number":158,"text":"Μνημονεύει δὲ τοῦ πατρὸς ἡμῶν Ἁβράμου Βηρωσός, οὐκ ὀνομάζων, λέγων δʼ οὕτως· μετὰ δὲ τὸν κατακλυσμὸν δεκάτῃ γενεᾷ παρὰ Χαλδαίοις τις ἦν δίκαιος ἀνὴρ καὶ μέγας καὶ τὰ οὐράνια ἔμπειρος."},{"number":159,"text":"Ἑκαταῖος δὲ καὶ τοῦ μνησθῆναι πλέον τι πεποίηκε· βιβλίον γὰρ περὶ αὐτοῦ συνταξάμενος κατέλιπε. Νικόλαος δὲ ὁ Δαμασκηνὸς ἐν τῇ τετάρτῃ τῶν ἱστοριῶν λέγει οὕτως· Ἁβράμης ἐβασίλευσεν ἔπηλυς σὺν στρατῷ ἀφιγμένος ἐκ τῆς γῆς τῆς ὑπὲρ Βαβυλῶνος Χαλδαίων λεγομένης."},{"number":160,"text":"μετʼ οὐ πολὺν δὲ χρόνον μεταναστὰς καὶ ἀπὸ ταύτης τῆς χώρας σὺν τῷ σφετέρῳ λαῷ εἰς τὴν τότε μὲν Χαναναίαν λεγομένην νῦν δὲ Ἰουδαίαν μετῴκησε καὶ οἱ ἀπʼ ἐκείνου πληθύσαντες, περὶ ὧν ἐν ἑτέρῳ λόγῳ διέξειμι τὰ ἱστορούμενα. τοῦ δὲ Ἁβράμου ἔτι καὶ νῦν ἐν τῇ Δαμασκηνῇ τὸ ὄνομα δοξάζεται καὶ κώμη δείκνυται ἀπʼ αὐτοῦ Ἁβράμου οἴκησις λεγομένη."}],"8":[{"number":161,"text":"Λιμοῦ δὲ χρόνοις ὕστερον τὴν Ἰουδαίαν καταλαβόντος Ἅβραμος Αἰγυπτίους εὐδαιμονεῖν πυθόμενος μεταίρειν πρὸς αὐτοὺς ἦν πρόθυμος τῆς τε ἀφθονίας τῆς ἐκείνων μεθέξων καὶ τῶν ἱερέων ἀκροατὴς ἐσόμενος ὧν λέγοιεν περὶ θεῶν· ἢ γὰρ κρείσσοσιν εὑρεθεῖσι κατακολουθήσειν ἢ μετακοσμήσειν αὐτοὺς ἐπὶ τὸ βέλτιον αὐτὸς ἄμεινον φρονῶν."},{"number":162,"text":"ἐπαγόμενος δὲ καὶ τὴν Σάρραν καὶ φοβούμενος τὸ πρὸς τὰς γυναῖκας τῶν Αἰγυπτίων ἐπιμανές, μὴ διὰ τὴν εὐμορφίαν τῆς γυναικὸς ὁ βασιλεὺς αὐτὸν ἀνέλῃ, τέχνην ἐπενόησε τοιαύτην· ἀδελφὸς αὐτῆς εἶναι προσεποιήσατο κἀκείνην τοῦθʼ ὑποκρίνασθαι, συμφέρειν γὰρ αὐτοῖς, ἐδίδαξεν."},{"number":163,"text":"ὡς δʼ ἧκον εἰς τὴν Αἴγυπτον, ἀπέβαινε τῷ Ἁβράμῳ καθὼς ὑπενόησε· τὸ γὰρ κάλλος ἐξεβοήθη τῆς γυναικὸς αὐτοῦ· διὸ καὶ Φαραώθης ὁ βασιλεὺς τῶν Αἰγυπτίων οὐ τοῖς περὶ αὐτῆς λεγομένοις ἀρκεσθεὶς ἀλλὰ καὶ θεάσασθαι σπουδάσας οἷός τε ἦν ἅψασθαι τῆς Σάρρας."},{"number":164,"text":"ἐμποδίζει δὲ αὐτοῦ ὁ θεὸς τὴν ἄδικον ἐπιθυμίαν νόσῳ τε καὶ στάσει τῶν πραγμάτων· καὶ θυομένῳ περὶ ἀπαλλαγῆς κατὰ μῆνιν θεοῦ τὸ δεινὸν αὐτῷ παρεῖναι ἀπεσήμαινον οἱ ἱερεῖς, ἐφʼ οἷς ἠθέλησεν ὑβρίσαι τοῦ ξένου τὴν γυναῖκα."},{"number":165,"text":"ὁ δὲ φοβηθεὶς ἠρώτα τὴν Σάρραν, τίς τε εἴη καὶ τίνα τοῦτον ἐπάγοιτο, πυθόμενός τε τὴν ἀλήθειαν Ἅβραμον παρῃτεῖτο· νομίζων γὰρ ἀδελφὴν ἀλλʼ οὐ γυναῖκα αὐτοῦ σπουδάσαι περὶ αὐτὴν συγγένειαν ποιήσασθαι βουλόμενος, ἀλλʼ οὐκ ἐνυβρίσαι κατʼ ἐπιθυμίαν ὡρμημένος· δωρεῖταί τε αὐτὸν πολλοῖς χρήμασι, καὶ συνῆν Αἰγυπτίων τοῖς λογιωτάτοις τήν τε ἀρετὴν αὐτῷ καὶ τὴν ἐπʼ αὐτῇ δόξαν ἐντεῦθεν ἐπιφανεστέραν συνέβη γενέσθαι."},{"number":166,"text":"Τῶν γὰρ Αἰγυπτίων διαφόροις ἀρεσκομένων ἔθεσι καὶ τὰ παρʼ ἀλλήλοις ἐκφαυλιζόντων νόμιμα καὶ διὰ τοῦτο δυσμενῶς ἐχόντων πρὸς ἀλλήλους, συμβαλὼν αὐτῶν ἑκάστοις καὶ διαπτύων τοὺς λόγους οὓς ἐποιοῦντο περὶ τῶν ἰδίων κενοὺς καὶ μηδὲν ἔχοντας ἀληθὲς ἀπέφαινε."},{"number":167,"text":"θαυμασθεὶς οὖν ὑπʼ αὐτῶν ἐν ταῖς συνουσίαις ὡς συνετώτατος καὶ δεινὸς ἀνὴρ οὐ νοῆσαι μόνον ἀλλὰ καὶ πεῖσαι λέγων περὶ ὧν ἐπιχειρήσειε διδάσκειν, τήν τε ἀριθμητικὴν αὐτοῖς χαρίζεται καὶ τὰ περὶ ἀστρονομίαν παραδίδωσι."},{"number":168,"text":"πρὸ γὰρ τῆς Ἁβράμου παρουσίας Αἰγύπτιοι τούτων εἶχον ἀμαθῶς· ἐκ Χαλδαίων γὰρ ταῦτʼ ἐφοίτησεν εἰς Αἴγυπτον, ὅθεν ἦλθε καὶ εἰς τοὺς Ἕλληνας."},{"number":169,"text":"Ὡς δʼ εἰς τὴν Χαναναίαν ἀφίκετο, μερίζεται πρὸς Λῶτον τὴν γῆν τῶν ποιμένων αὐτοῖς στασιαζόντων περὶ τῆς χώρας ἐν ᾗ νέμοιεν· τὴν ἐκλογὴν μέντοι καὶ τὴν αἵρεσιν ἐπιτρέπει τῷ Λώτῳ·"},{"number":170,"text":"λαβὼν δʼ αὐτὸς τὴν ὑπʼ ἐκείνου καταλελειμμένην ὑπώρειαν ᾤκει ἐν τῇ Ναβρῶ πόλει· παλαιοτέρα δέ ἐστιν ἔτεσιν ἑπτὰ πρὸ Τάνιδος τῆς Αἰγύπτου. Λῶτος δὲ τὴν πρὸς τὸ πεδίον κειμένην καὶ ποταμὸν Ἰορδάνην εἶχεν οὐκ ἄπωθεν τῆς Σοδομιτῶν πόλεως, ἣ τότε μὲν ἦν ἀγαθή, νῦν δὲ ἠφάνισται κατὰ βούλησιν θεοῦ. τὴν δὲ αἰτίαν κατὰ χώραν σημανῶ."}],"9":[{"number":171,"text":"Κατʼ ἐκεῖνον δὲ τὸν καιρὸν Ἀσσυρίων κρατούντων τῆς Ἀσίας Σοδομίταις ἤνθει τὰ πράγματα εἴς τε πλοῦτον αὐτῶν ἐπιδεδωκότων καὶ νεότητα πολλήν· βασιλεῖς δὲ αὐτοῖς πέντε διεῖπον τὴν χώραν, Βάλας Βαλαίας Συναβάνης καὶ Συμμόβορος ὅ τε Βαλήνων βασιλεύς· μοίρας δʼ ἦρχον ἕκαστος ἰδίας."},{"number":172,"text":"ἐπὶ τούτους στρατεύσαντες Ἀσσύριοι καὶ μέρη τέσσαρα ποιήσαντες τῆς στρατιᾶς ἐπολιόρκουν αὐτούς· στρατηγὸς δʼ ἑκάστοις ἦν εἷς ἐπιτεταγμένος. γενομένης δὲ μάχης νικήσαντες οἱ Ἀσσύριοι φόρον ἐπιτάσσουσι τοῖς Σοδομιτῶν βασιλεῦσι."},{"number":173,"text":"δώδεκα μὲν οὖν ἔτη δουλεύοντες καὶ τοὺς ἐπιταχθέντας αὐτοῖς φόρους τελοῦντες ὑπέμειναν, τῷ δὲ τρισκαιδεκάτῳ ἀπέστησαν, καὶ διαβαίνει στρατὸς Ἀσσυρίων ἐπʼ αὐτοὺς στρατηγούντων Ἀμαραψίδου Ἀριόχου Χοδολαμόρου Θαδάλου."},{"number":174,"text":"οὗτοι τήν τε Συρίαν ἅπασαν διηρπάσαντο καὶ τοὺς τῶν Γιγάντων ἀπογόνους κατεστρέψαντο, γενόμενοι δὲ κατὰ τὰ Σόδομα στρατοπεδεύουσι κατὰ τὴν κοιλάδα τὴν λεγομένην φρέατα ἀσφάλτου· κατʼ ἐκεῖνον γὰρ τὸν καιρὸν φρέατα ἦν ἐν τῷ τόπῳ, νῦν μέντοι τῆς Σοδομιτῶν πόλεως ἀφανισθείσης ἡ κοιλὰς ἐκείνη λίμνη γέγονεν ἡ Ἀσφαλτῖτις λεγομένη."},{"number":175,"text":"περὶ μὲν οὖν τῆς λίμνης ταύτης αὖθις μετʼ οὐ πολὺ δηλώσομεν, τῶν δὲ Σοδομιτῶν συμβαλόντων τοῖς Ἀσσυρίοις καὶ καρτερᾶς τῆς μάχης γενομένης, πολλοὶ μὲν αὐτῶν ἀπέθανον, οἱ λοιποὶ δὲ ᾐχμαλωτίσθησαν, σὺν οἷς καὶ Λῶτος ἤγετο τοῖς Σοδομίταις σύμμαχος ἐληλυθώς."}],"10":[{"number":176,"text":"Ἁβράμῳ δὲ ἀκούσαντι τὴν συμφορὰν αὐτῶν φόβος τε ἅμα περὶ Λώτου τοῦ συγγενοῦς εἰσῆλθε καὶ οἶκτος περὶ τῶν Σοδομιτῶν φίλων ὄντων καὶ γειτνιώντων."},{"number":177,"text":"καὶ βοηθεῖν αὐτοῖς δοκιμάσας οὐκ ἀνέμεινεν, ἀλλʼ ἐπειχθεὶς καὶ κατὰ πέμπτην ἐπιπεσὼν νύκτα τοῖς Ἀσσυρίοις περὶ Δάνον, οὕτως γὰρ ἡ ἑτέρα τοῦ Ἰορδάνου προσαγορεύεται πηγή, καὶ φθάσας πρὶν ἐν ὅπλοις γενέσθαι τοὺς μὲν ἐν ταῖς κοίταις ὄντας ἀπέκτεινε μηδʼ ἐπίνοιαν τῆς συμφορᾶς ἔχοντας, οἱ δὲ μήπω πρὸς ὕπνον τετραμμένοι μάχεσθαι δʼ ὑπὸ μέθης ἀδύνατοι ἔφυγον."},{"number":178,"text":"Ἅβραμος δὲ διώκων εἵπετο μέχρι καὶ δευτεραίους συνήλασεν αὐτοὺς εἰς Ὠβὰ τῆς Δαμασκηνῶν γῆς, ἐπιδείξας ὅτι τὸ νικᾶν οὐκ ἐν τῷ πλήθει καὶ τῇ πολυχειρίᾳ κεῖσθαι συμβέβηκεν, ἀλλὰ προθυμία τῶν μαχομένων καὶ τὸ γενναῖον κρατεῖ παντὸς ἀριθμοῦ, τριακοσίοις καὶ δεκαοκτὼ οἰκέταις αὐτοῦ καὶ τρισὶ φίλοις τοσούτου στρατοῦ περιγενόμενος. ὁπόσοι δὲ αὐτῶν καὶ διέφυγον ἀδόξως ἀνέστρεψαν."},{"number":179,"text":"Ἅβραμος δὲ τοὺς τῶν Σοδομιτῶν σώσας αἰχμαλώτους, οἳ ληφθέντες ἔφθησαν ὑπὸ τῶν Ἀσσυρίων, καὶ τὸν συγγενῆ Λῶτον ἀνέζευξεν μετὰ εἰρήνης. ἀπήντησε δὲ αὐτῷ ὁ τῶν Σοδομιτῶν βασιλεὺς εἰς τόπον τινά, ὃν καλοῦσι πεδίον βασιλικόν."},{"number":180,"text":"ἔνθα ὁ τῆς Σολυμᾶ ὑποδέχεται βασιλεὺς αὐτὸν Μελχισεδέκ· σημαίνει δὲ τοῦτο βασιλεὺς δίκαιος· καὶ ἦν δὲ τοιοῦτος ὁμολογουμένως, ὡς διὰ ταύτην αὐτὸν τὴν αἰτίαν καὶ ἱερέα γενέσθαι τοῦ θεοῦ· τὴν μέντοι Σολυμᾶ ὕστερον ἐκάλεσεν Ἱεροσόλυμα."},{"number":181,"text":"ἐχορήγησε δὲ οὗτος ὁ Μελχισεδὲκ τῷ Ἁβράμου στρατῷ ξένια καὶ πολλὴν ἀφθονίαν τῶν ἐπιτηδείων παρέσχε καὶ παρὰ τὴν εὐωχίαν αὐτόν τε ἐπαινεῖν ἤρξατο καὶ τὸν θεὸν εὐλογεῖν ὑποχειρίους αὐτῷ ποιήσαντα τοὺς ἐχθρούς. Ἁβράμου δὲ διδόντος καὶ τὴν δεκάτην τῆς λείας αὐτῷ προσδέχεται τὴν δόσιν."},{"number":182,"text":"ὁ δὲ τῶν Σοδομιτῶν βασιλεὺς τὴν μὲν λείαν ἔχειν Ἅβραμον παρεκάλει, τοὺς δʼ ἀνθρώπους ἀπολαβεῖν ἠξίου, οὓς παρὰ τῶν Ἀσσυρίων ἔσωσεν οἰκείους ὄντας. Ἅβραμος δὲ οὐκ ἔφη τοῦτο ποιήσειν, οὐδʼ ἂν ἄλλην ὠφέλειαν ἐκ τῆς λείας ἐκείνης εἰς αὐτὸν ἥξειν πλὴν ὅσα τροφὴ τοῖς οἰκέταις αὐτοῦ γένοιτο· μοῖραν μέντοι τινὰ τοῖς φίλοις αὐτοῦ παρέσχε τοῖς συστρατευομένοις. Ἔσχων δʼ ὁ πρῶτος ἐκαλεῖτο καὶ Ἔννηρος καὶ Μαμβρῆς."},{"number":183,"text":"Ἐπαινέσας δὲ αὐτοῦ τὴν ἀρετὴν ὁ θεός, ἀλλʼ οὐκ ἀπολεῖς, φησί, μισθοὺς οὓς ἄξιόν ἐστίν σε ἐπὶ τοιαύταις εὐπραγίαις κομίζεσθαι. τοῦ δʼ ὑπολαβόντος καὶ τίς ἂν εἴη χάρις τούτων τῶν μισθῶν, οὐκ ὄντων οἳ διαδέξονται μετʼ αὐτόν, ἔτι γὰρ ἦν ἄπαις, ὁ θεὸς καὶ παῖδα αὐτῷ γενήσεσθαι καταγγέλλει καὶ πολλὴν ἐκείνου γενεάν, ὡς παραπλησίως αὐτῇ τοῖς ἄστροις ἔσεσθαι τὸν ἀριθμόν."},{"number":184,"text":"καὶ ὁ μὲν ταῦτʼ ἀκούσας θυσίαν προσφέρει τῷ θεῷ κελευσθεὶς ὑπʼ αὐτοῦ. ἦν δὲ ὁ τρόπος τῆς θυσίας τοιοῦτος· δάμαλιν τριετίζουσαν καὶ αἶγα τριετίζουσαν καὶ κριὸν ὁμοίως τριετῆ καὶ τρυγόνα καὶ περιστερὰν κελεύσαντος διεῖλε, τῶν ὀρνέων οὐδὲν διελών."},{"number":185,"text":"εἶτα πρὶν στῆναι τὸν βωμὸν οἰωνῶν ἐφιπταμένων ἐπιθυμίᾳ τοῦ αἵματος φωνὴ θεία παρῆν ἀποσημαίνουσα πονηροὺς αὐτοῦ τοῖς ἐγγόνοις γείτονας ἐπὶ ἔτη τετρακόσια γενησομένους κατὰ τὴν Αἴγυπτον· ἐν οἷς κακοπαθήσαντας περιέσεσθαι τῶν ἐχθρῶν καὶ κρατήσαντας πολέμῳ Χαναναίων ἕξειν αὐτῶν τὴν γῆν καὶ τὰς πόλεις."},{"number":186,"text":"Ἅβραμος δὲ κατῴκει μὲν περὶ τὴν Ὠγύγην καλουμένην δρῦν, ἔστι δὲ τῆς Χαναναίας τὸ χωρίον οὐ πόρρω τῆς Ἑβρωνίων πόλεως, δυσφορῶν δὲ ἐπὶ γυναικὶ μὴ κυούσῃ ἱκετεύει τὸν θεὸν γονὴν αὐτῷ παιδὸς ἄρσενος παρασχεῖν."},{"number":187,"text":"τοῦ δὲ θεοῦ θαρσεῖν αὐτὸν παρακελευομένου τοῖς τε ἄλλοις ἅπασιν ὡς ἐπʼ ἀγαθοῖς αὐτὸν ἀπὸ τῆς Μεσοποταμίας ἠγμένον καὶ παίδων ἐσομένων, Σάρρα τοῦ θεοῦ κελεύσαντος ἐπικλίνει μίαν τῶν θεραπαινίδων Ἀγάρην ὄνομα γένος οὖσαν Αἰγυπτίαν ὡς ἐξ αὐτῆς παιδοποιησομένῳ."},{"number":188,"text":"καὶ γενομένη ἐγκύμων ἡ θεραπαινὶς ἐξυβρίζειν εἰς τὴν Σάρραν ἐτόλμησε βασιλίζουσα, ὡς τῆς ἡγεμονίας περιστησομένης εἰς τὸν ὑπʼ αὐτῆς τεχθησόμενον. Ἁβράμου δὲ αὐτὴν πρὸς αἰκίαν παραδιδόντος τῇ Σάρρᾳ δρασμὸν ἐπεβούλευσεν οὐχ ὑπομένουσα τὰς ταλαιπωρίας καὶ τὸν θεὸν ἱκέτευεν οἶκτον αὐτῆς λαβεῖν."},{"number":189,"text":"ὑπαντιάζει δὲ διὰ τῆς ἐρήμου προϊοῦσαν αὐτὴν ἄγγελος θεῖος κελεύων πρὸς τοὺς δεσπότας ἐπανιέναι· βίου γὰρ μείζονος τεύξεσθαι σωφρονοῦσαν· καὶ γὰρ νῦν εἰς τὴν δέσποιναν ἀγνώμονα καὶ αὐθάδη γενομένην ἐν τούτοις εἶναι τοῖς κακοῖς·"},{"number":190,"text":"παρακούουσαν μὲν τοῦ θεοῦ καὶ προσωτέρω χωροῦσαν ἔλεγεν ἀπολεῖσθαι, νοστήσασαν δὲ αὐτὴν ὀπίσω γενήσεσθαι μητέρα παιδὸς τῆς γῆς ἐκείνης βασιλεύσοντος. τούτοις πείθεται καὶ ἐπανελθοῦσα πρὸς τοὺς δεσπότας συγγνώμης ἔτυχε· τίκτει δὲ μετʼ οὐ πολὺ Ἰσμαῆλον, θεόκλυτον ἄν τις εἴποι, διὰ τὸ εἰσακοῦσαι τὸν θεὸν τῆς ἱκεσίας."},{"number":191,"text":"Ἁβράμῳ μὲν οὖν ἕκτον ἤδη καὶ ὀγδοηκοστὸν ἔτος γεγονότι ὁ προειρημένος ἐγεννήθη, εἰς ἔνατον δʼ αὐτῷ καὶ ἐνενηκοστὸν παρελθόντι ἐπιφανεὶς ὁ θεὸς ἀπήγγειλεν, ὡς παῖς αὐτῷ ἐκ Σάρρας ἔσοιτο· κελεύει δʼ αὐτὸν καλέσαι Ἴσακον δηλῶν ἐσόμενα ἔθνη μεγάλα ἀπʼ αὐτοῦ καὶ βασιλεῖς, καὶ ὅτι πολεμήσαντες καθέξουσι τὴν Χαναναίαν ἅπασαν ἀπὸ Σιδῶνος μέχρι Αἰγύπτου,"},{"number":192,"text":"προσέταξέ τε βουλόμενος τὸ ἀπʼ αὐτοῦ γένος μένειν τοῖς ἄλλοις οὐ συμφυρόμενον περιτέμνεσθαι τὰ αἰδοῖα καὶ τοῦτο ποιεῖν ὀγδόῃ ἡμέρᾳ μετὰ τὸ γεννηθῆναι. τὴν αἰτίαν δὲ τῆς περιτομῆς ἡμῶν ἐν ἄλλοις δηλώσω."},{"number":193,"text":"πυθομένῳ δὲ Ἁβράμῳ καὶ περὶ τοῦ Ἰσμαήλου, εἰ ζήσεται, πολυχρόνιόν τε ἀπεσήμαινεν ὁ θεὸς καὶ μεγάλων ἐθνῶν πατέρα. καὶ Ἅβραμος μὲν ἐπὶ τούτοις εὐχαριστήσας τῷ θεῷ περιτέμνεται παραχρῆμα καὶ πάντες οἱ παρʼ αὐτοῦ καὶ ὁ παῖς Ἰσμαῆλος, οὗ κατʼ ἐκείνην τὴν ἡμέραν τρισκαιδέκατον ἔτος ἔχοντος αὐτὸς ἐνενηκοστὸν πρὸς τοῖς ἐννέα διῆγεν."}],"11":[{"number":194,"text":"Ὑπὸ δὴ τοῦτον τὸν καιρὸν οἱ Σοδομῖται πλήθει καὶ μεγέθει χρημάτων ὑπερφρονοῦντες εἴς τε ἀνθρώπους ἦσαν ὑβρισταὶ καὶ πρὸς τὸ θεῖον ἀσεβεῖς, ὡς μηκέτι μεμνῆσθαι τῶν παρʼ αὐτοῦ γενομένων ὠφελειῶν, εἶναί τε μισόξενοι καὶ τὰς πρὸς ἄλλους ὁμιλίας ἐκτρέπεσθαι."},{"number":195,"text":"χαλεπήνας οὖν ἐπὶ τούτοις ὁ θεὸς ἔγνω τιμωρήσασθαι τῆς ὑπερηφανίας αὐτοὺς καὶ τήν τε πόλιν αὐτὴν κατασκάψασθαι καὶ τὴν χώραν οὕτως ἀφανίσαι, ὡς μήτε φυτὸν ἔτι μήτε καρπὸν ἕτερον ἐξ αὐτῆς ἀναδοθῆναι."},{"number":196,"text":"Ταῦτα τοῦ θεοῦ κρίναντος περὶ τῶν Σοδομιτῶν Ἅβραμος θεασάμενος τρεῖς ἀγγέλους, ἐκαθέζετο δὲ πρὸς τῇ δρυῒ τῇ Μαμβρῆ παρὰ τῇ θύρᾳ τῆς αὑτοῦ αὐλῆς, καὶ νομίσας εἶναι ξένους ἀναστὰς ἠσπάσατό τε καὶ παρʼ αὐτῷ καταχθέντας παρεκάλει ξενίας μεταλαβεῖν."},{"number":197,"text":"ἐπινευσάντων δὲ ἄρτους τε προσέταξεν εὐθὺς ἐκ σεμιδάλεως γενέσθαι, καὶ μόσχον θύσας καὶ ὀπτήσας ἐκόμισεν αὐτοῖς ὑπὸ τῇ δρυῒ κατακειμένοις· οἱ δὲ δόξαν αὐτῷ παρέσχον ἐσθιόντων, ἔτι δὲ καὶ περὶ τῆς γυναικὸς ἐπυνθάνοντο, ποῖ ποτʼ εἴη Σάρρα. τοῦ δʼ εἰπόντος ἔνδον εἶναι, ἥξειν ἔφασαν εἰς τὸ μέλλον καὶ εὑρήσειν αὐτὴν ἤδη μητέρα γεγενημένην."},{"number":198,"text":"τῆς δὲ γυναικὸς ἐπὶ τούτῳ μειδιασάσης καὶ ἀδύνατον εἶναι τὴν τεκνοποιίαν εἰπούσης αὐτῆς μὲν ἐνενήκοντα ἔτη ἐχούσης τοῦ δʼ ἀνδρὸς ἑκατόν, οὐκέτι κατέσχον λανθάνοντες ἀλλʼ ἐμήνυσαν ἑαυτοὺς ὄντας ἀγγέλους τοῦ θεοῦ, καὶ ὅτι πεμφθείη μὲν ὁ εἷς σημανῶν περὶ τοῦ παιδός, οἱ δύο δὲ Σοδομίτας καταστρεψόμενοι."},{"number":199,"text":"Ταῦτʼ ἀκούσας Ἅβραμος ἤλγησεν ἐπὶ τοῖς Σοδομίταις καὶ τὸν θεὸν ἀναστὰς ἱκέτευσε παρακαλῶν, μὴ τοὺς δικαίους καὶ ἀγαθοὺς συναπολλύναι τοῖς πονηροῖς. τοῦ δὲ θεοῦ φήσαντος μηδένα εἶναι τῶν Σοδομιτῶν ἀγαθόν, εἰ γὰρ ἐν αὐτοῖς δέκα εἶεν συγχωρεῖν ἅπασι τὴν ἐπὶ τοῖς ἁμαρτήμασι τιμωρίαν, ὁ μὲν Ἅβραμος ἡσύχασεν·"},{"number":200,"text":"οἱ δὲ ἄγγελοι παρεγένοντο εἰς τὴν τῶν Σοδομιτῶν πόλιν, καὶ ὁ Λῶτος αὐτοὺς ἐπὶ ξενίαν παρεκάλει· λίαν γὰρ ἦν περὶ τοὺς ξένους φιλάνθρωπος καὶ μαθητὴς τῆς Ἁβράμου χρηστότητος. οἱ δὲ Σοδομῖται θεασάμενοι τοὺς νεανίσκους εὐπρεπεστάτους τῇ ὄψει διαφέροντας καὶ παρὰ Λώτῳ καταχθέντας ἐπὶ βίαν καὶ ὕβριν αὐτῶν τῆς ὥρας ἐτράπησαν."},{"number":201,"text":"τοῦ δὲ Λώτου παραινοῦντος σωφρονεῖν καὶ μὴ χωρεῖν ἐπʼ αἰσχύνῃ τῶν ξένων, ἀλλʼ ἔχειν αἰδῶ τῆς παρʼ αὐτῷ καταγωγῆς, εἰ δὲ ἔχουσιν ἀκρατῶς, τὰς θυγατέρας αὐτοῦ ὑπὲρ ἐκείνων ταῖς ἐπιθυμίαις αὐτῶν λέγοντος παρέξειν, οὐδʼ οὕτως ἐπείσθησαν."},{"number":202,"text":"Ὁ θεὸς οὖν ἀγανακτήσας αὐτῶν ἐπὶ τοῖς τολμήμασι τοὺς μὲν ἠμαύρωσεν, ὡς μὴ δυνηθῆναι τὴν εἴσοδον τὴν εἰς τὴν οἰκίαν εὑρεῖν, Σοδομιτῶν δὲ κατέκρινε πάνδημον ὄλεθρον. Λῶτος δὲ τοῦ θεοῦ τὴν μέλλουσαν ἀπώλειαν τῶν Σοδομιτῶν αὐτῷ φράσαντος ἀπαλλάσσεται τήν τε γυναῖκα καὶ τὰς θυγατέρας, δύο δὲ ἦσαν ἔτι παρθένοι, ἀναλαβών· οἱ γὰρ μνηστῆρες περιεφρόνησαν τῆς ἐξόδου εὐήθειαν ἐπικαλοῦντες τοῖς ὑπὸ τοῦ Λώτου λεγομένοις."},{"number":203,"text":"καὶ ὁ θεὸς ἐνσκήπτει βέλος εἰς τὴν πόλιν καὶ σὺν τοῖς οἰκήτορσιν κατεπίμπρα τὴν γῆν ὁμοίᾳ πυρώσει ἀφανίζων, ὥς μοι καὶ πρότερον λέλεκται τὸν Ἰουδαϊκὸν ἀναγράφοντι πόλεμον. ἡ δὲ Λώτου γυνὴ παρὰ τὴν ἀναχώρησιν συνεχῶς εἰς τὴν πόλιν ἀναστρεφομένη καὶ πολυπραγμονοῦσα τὰ περὶ αὐτὴν ἀπηγορευκότος τοῦ θεοῦ τοῦτο μὴ ποιεῖν εἰς στήλην ἁλῶν μετέβαλεν· ἱστόρησα δʼ αὐτήν, ἔτι γὰρ καὶ νῦν διαμένει."},{"number":204,"text":"διαφεύγει δʼ αὐτὸς μετὰ τῶν θυγατέρων εἰς βραχύ τι χωρίον κατασχὼν περιγραφὲν ὑπὸ τοῦ πυρός· Ζωὼρ ἔτι καὶ νῦν λέγεται· καλοῦσι γὰρ οὕτως Ἑβραῖοι τὸ ὀλίγον. ἐνταῦθα τοίνυν ὑπό τε ἀνθρώπων ἐρημίας καὶ τροφῆς ἀπορίας ταλαιπώρως διῆγεν."},{"number":205,"text":"Αἱ δὲ παρθένοι πᾶν ἠφανίσθαι τὸ ἀνθρώπινον ὑπολαβοῦσαι τῷ πατρὶ πλησιάζουσι προνοήσασαι λαθεῖν· ἐποίουν δὲ τοῦτο ὑπὲρ τοῦ μὴ τὸ γένος ἐκλιπεῖν. γίνονται δὲ παῖδες ὑπὸ μὲν τῆς πρεσβυτέρας Μώαβος· εἴποι δʼ ἄν τις ἀπὸ πατρός. Ἄμμανον δʼ ἡ νεωτέρα ποιεῖται· γένους υἱὸν ἀποσημαίνει τὸ ὄνομα."},{"number":206,"text":"καὶ κτίζει δʼ αὐτῶν ὁ μὲν Μωαβίτας μέγιστον ὄντας καὶ νῦν ἔθνος, Ἀμμανίτας δὲ ὁ ἕτερος· Συρίας τῆς κοίλης ἐστὶν ἀμφότερα. καὶ Λώτῳ μὲν τοιαύτην συνέβη τὴν ἐκ Σοδομιτῶν ἀναχώρησιν γενέσθαι."}],"12":[{"number":207,"text":"Ἅβραμος δὲ μετῴκησεν εἰς Γέραρα τῆς Παλαιστίνης ἐν ἀδελφῆς ἐπαγόμενος σχήματι τὴν Σάρραν, ὅμοια τοῖς πρὶν ὑποκρινάμενος διὰ τὸν φόβον· ἐδεδίει γὰρ Ἀβιμέλεχον τὸν βασιλέα τῶν ἐπιχωρίων· ὃς καὶ αὐτὸς ἐρασθεὶς τῆς Σάρρας φθείρειν οἷός τε ἦν."},{"number":208,"text":"εἴργεται δὲ τῆς ἐπιθυμίας ὑπὸ νόσου χαλεπῆς αὐτῷ προσπεσούσης ἐκ θεοῦ καὶ τῶν ἰατρῶν αὐτὸν ἀπεγνωκότων ὑπνώσας ὄναρ ὁρᾷ μηδὲν ὑβρίζειν τὴν τοῦ ξένου γυναῖκα, καὶ ῥᾷον διατεθεὶς φράζει πρὸς τοὺς φίλους, ὡς ὁ θεὸς ταύτην αὐτῷ ἐπάγει τὴν νόσον ὑπὲρ ἐκδικίας τοῦ ξένου φυλάσσων ἀνύβριστον αὐτῷ τὴν γυναῖκα, μὴ γὰρ ἀδελφὴν οὖσαν ἐπάγεσθαι νόμῳ δʼ αὐτῷ συνοικοῦσαν, ἐπαγγέλλεταί τε παρέξειν αὑτὸν εὐμενῆ τὸ λοιπὸν ἀδεοῦς ἐκείνου περὶ τὴν γυναῖκα γενομένου."},{"number":209,"text":"ταῦτα εἰπὼν μεταπέμπεται τὸν Ἅβραμον συμβουλευσάντων τῶν φίλων καὶ μηδὲν ἔτι περὶ τῆς γυναικὸς αὐτὸν ὡς πεισομένης τι τῶν αἰσχρῶν ἐκέλευσε δεδιέναι, θεὸν γὰρ αὐτοῦ κήδεσθαι, καὶ κατὰ τὴν συμμαχίαν τὴν ἐκείνου μεμενηκυῖαν ἀνύβριστον κομίζεσθαι. τοῦ δὲ θεοῦ μάρτυρος ὄντος καὶ τοῦ τῆς γυναικὸς συνειδότος ἔλεγε μηδʼ ἂν ὀρεχθῆναι τὴν ἀρχήν, εἰ γαμετὴν οὖσαν ἠπίστατο, ὡς ἀδελφὴν δὲ ἀγόμενον ἣν οὐκ ἠδίκουν."},{"number":210,"text":"παρακαλεῖ τε πρᾴως ἔχειν πρὸς αὐτὸν καὶ τὸν θεὸν εὐμενῆ ποιεῖν, παρʼ αὐτῷ τε μένειν βουλομένῳ πᾶσαν ἀφθονίαν ὑπάρξειν ἀπιέναι τε προαιρούμενον τεύξεσθαι πομπῆς καὶ πάντων ὅσων καὶ χρῄζων πρὸς αὐτὸν ἀφίκοιτο."},{"number":211,"text":"ταῦτʼ εἰπόντος Ἅβραμος οὔτε τὴν συγγένειαν τῆς γυναικὸς ἐψεῦσθαι ἔλεγεν, ἀδελφοῦ γὰρ αὐτὴν εἶναι παῖδα, καὶ δίχα τοιαύτης ὑποκρίσεως οὐκ ἀσφαλῆ τὴν ἐπιδημίαν ὑπολαβεῖν. ὅσα τε ἐπὶ τῷ μηδὲν αἴτιος τῆς νόσου γεγονέναι προθυμηθῆναι δʼ αὐτοῦ περὶ τὴν σωτηρίαν, ἑτοίμως ἔφασκεν ἔχειν παρʼ αὐτῷ μένειν."},{"number":212,"text":"καὶ Ἀβιμέλεχος τήν τε γῆν πρὸς αὐτὸν νέμεται καὶ τὰ χρήματα, καὶ συντίθενται ἀδόλως πολιτεύσεσθαι ὑπέρ τινος φρέατος ποιούμενοι τὸν ὅρκον, ὃ Βηρσουβαὶ καλοῦσιν· ὅρκιον δὲ φρέαρ λέγοιτʼ ἄν. οὕτω δʼ ἔτι καὶ νῦν ὑπὸ τῶν ἐπιχωρίων ὠνόμασται."},{"number":213,"text":"Γίνεται δὲ Ἁβράμῳ μετʼ οὐ πολὺ καὶ παῖς ἐκ Σάρρας, ὡς αὐτῷ ὑπὸ τοῦ θεοῦ προείρητο, ὃν Ἴσακον ὠνόμασε· τοῦτο γέλωτα σημαίνει· διὰ μέντοι τὸ τὴν Σάρραν μειδιάσαι τέξεσθαι φήσαντος αὐτὴν τοῦ θεοῦ μὴ προσδοκῶσαν ἤδη τοκετοῦ πρεσβυτέραν οὖσαν τὸν υἱὸν οὕτως ἐκάλεσεν. αὐτὴ μὲν γὰρ ἐνενήκοντα εἶχεν ἔτη ἑκατὸν δὲ Ἅβραμος."},{"number":214,"text":"τίκτεται δὲ παῖς ἑκατέρων τῷ ὑστάτῳ ἔτει, ὃν εὐθὺς μετʼ ὀγδόην ἡμέραν περιτέμνουσι, κἀξ ἐκείνου μετὰ τοσαύτας ἔθος ἔχουσιν οἱ Ἰουδαῖοι ποιεῖσθαι τὰς περιτομάς, Ἄραβες δὲ μετὰ ἔτος τρισκαιδέκατον· Ἰσμαῆλος γὰρ ὁ κτίστης αὐτῶν τοῦ ἔθνους Ἁβράμῳ γενόμενος ἐκ τῆς παλλακῆς ἐν τούτῳ περιτέμνεται τῷ χρόνῳ· περὶ οὗ τὸν πάντα λόγον ἐκθήσομαι μετὰ πολλῆς ἀκριβείας."},{"number":215,"text":"Σάρρα δὲ γεννηθέντα τὸν Ἰσμαῆλον ἐκ τῆς δούλης αὐτῆς Ἀγάρης τὸ μὲν πρῶτον ἔστεργεν οὐδὲν ἀπολείπουσα τῆς πρὸς ἴδιον υἱὸν εὐνοίας, ἐτρέφετο γὰρ ἐπὶ τῇ τῆς ἡγεμονίας διαδοχῇ, τεκοῦσα δʼ αὐτὴ τὸν Ἴσακον οὐκ ἠξίου παρατρέφεσθαι τούτῳ τὸν Ἰσμαῆλον ὄντα πρεσβύτερον καὶ κακουργεῖν δυνάμενον τοῦ πατρὸς αὐτοῖς ἀποθανόντος."},{"number":216,"text":"ἔπειθεν οὖν τὸν Ἅβραμον εἰς ἀποικίαν ἐκπέμπειν αὐτὸν μετὰ τῆς μητρός. ὁ δὲ κατὰ μὲν ἀρχὰς οὐ προσετίθετο τὴν αὑτοῦ γνώμην οἷς ἡ Σάρρα ἐσπουδάκει πάντων ὠμότατον ἡγούμενος εἶναι παῖδα νήπιον καὶ γυναῖκα ἄπορον τῶν ἀναγκαίων ἐκπέμπειν."},{"number":217,"text":"ὕστερον δέ, καὶ γὰρ ὁ θεὸς ἠρέσκετο τοῖς ὑπὸ τῆς Σάρρας προσταττομένοις, πεισθεὶς παρεδίδου τὸν Ἰσμαῆλον τῇ μητρὶ μήπω διʼ αὐτοῦ χωρεῖν δυνάμενον, ὕδωρ τε ἐν ἀσκῷ καὶ ἄρτον φερομένην ἐκέλευεν ἀπιέναι ὁδηγῷ τῇ ἀνάγκῃ χρωμένην."},{"number":218,"text":"ὡς δʼ ἀπιοῦσαν ἐπιλελοίπει τὰ ἀναγκαῖα, ἐν κακοῖς ἦν, ὕδατος δὲ σπανίζοντος ὑπʼ ἐλάτῃ τινὶ θεῖσα τὸ παιδίον ψυχορραγοῦν, ὡς μὴ παρούσης τὴν ψυχὴν ἀφῇ, προῄει πορρωτέρω."},{"number":219,"text":"συντυχὼν δʼ αὐτῇ θεῖος ἄγγελος πηγήν τε φράζει παρακειμένην καὶ κελεύει προνοεῖν τῆς ἀνατροφῆς τοῦ παιδίου· μεγάλα γὰρ αὐτὴν ἀγαθὰ περιμένειν ἐκ τῆς Ἰσμαήλου σωτηρίας. ἡ δʼ ἐθάρσησε τοῖς προκατηγγελμένοις καὶ συμβαλοῦσα ποιμέσι διὰ τὴν ἐξ αὐτῶν ἐπιμέλειαν διαφεύγει τὰς ταλαιπωρίας."},{"number":220,"text":"Ἀνδρωθέντι δὲ τῷ παιδὶ γύναιον ἄγεται τὸ γένος Αἰγύπτιον, ἐνθένδε ἦν καὶ αὐτὴ τὸ ἀρχαῖον, ἐξ οὗ παῖδες Ἰσμαήλῳ γίνονται δώδεκα πάντες, Ναβαιώθης Κήδαρος Ἀβδεῆλος Μάσσαμος Μάσμασος Ἰδουμᾶς Μάσμησος Χόδαμος Θέμανος Ἰετοῦρος Νάφαισος Κάδμασος."},{"number":221,"text":"οὗτοι πᾶσαν τὴν ἀπʼ Εὐφράτου καθήκουσαν πρὸς τὴν Ἐρυθρὰν θάλασσαν κατοικοῦσι Ναβατηνὴν τὴν χώραν ὀνομάσαντες. εἰσὶ δὲ οὗτοι, οἳ τὸ τῶν Ἀράβων ἔθνος καὶ τὰς φυλὰς ἀπʼ αὐτῶν καλοῦσι διά τε τὴν ἀρετὴν αὐτῶν καὶ τὸ Ἁβράμου ἀξίωμα."}],"13":[{"number":222,"text":"Ἴσακον δὲ ὁ πατὴρ Ἅβραμος ὑπερηγάπα μονογενῆ ὄντα καὶ ἐπὶ γήρως οὐδῷ κατὰ δωρεὰν αὐτῷ τοῦ θεοῦ γενόμενον. προεκαλεῖτο δὲ εἰς εὔνοιαν καὶ τὸ φιλεῖσθαι μᾶλλον ὑπὸ τῶν γονέων καὶ αὐτὸς ὁ παῖς ἐπιτηδεύων πᾶσαν ἀρετὴν καὶ τῆς τε τῶν πατέρων θεραπείας ἐχόμενος καὶ περὶ τὴν τοῦ θεοῦ θρησκείαν ἐσπουδακώς."},{"number":223,"text":"Ἅβραμος δὲ τὴν ἰδίαν εὐδαιμονίαν ἐν μόνῳ τῷ τὸν υἱὸν ἀπαθῆ καταλιπὼν ἐξελθεῖν τοῦ ζῆν ἐτίθετο. τούτου μέντοι κατὰ τὴν τοῦ θεοῦ βούλησιν ἔτυχεν, ὃς διάπειραν αὐτοῦ βουλόμενος λαβεῖν τῆς περὶ αὐτὸν θρησκείας ἐμφανισθεὶς αὐτῷ καὶ πάντα ὅσα εἴη παρεσχημένος καταριθμησάμενος,"},{"number":224,"text":"ὡς πολεμίων τε κρείττονα ποιήσειε καὶ τὴν παροῦσαν εὐδαιμονίαν ἐκ τῆς αὐτοῦ σπουδῆς ἔχοι καὶ τὸν υἱὸν Ἴσακον, ᾔτει τοῦτον αὐτῷ θῦμα καὶ ἱερεῖον αὐτὸν παρασχεῖν ἐκέλευέ τε εἰς τὸ Μώριον ὄρος ἀναγαγόντα ὁλοκαυτῶσαι βωμὸν ἱδρυσάμενον· οὕτως γὰρ ἐμφανίσειν τὴν περὶ αὐτὸν θρησκείαν, εἰ καὶ τῆς τοῦ τέκνου σωτηρίας προτιμήσειε τὸ τῷ θεῷ κεχαρισμένον."},{"number":225,"text":"Ἅβραμος δὲ ἐπὶ μηδενὶ κρίνων παρακούειν τοῦ θεοῦ δίκαιον ἅπαντά θʼ ὑπουργεῖν ὡς ἐκ τῆς ἐκείνου προνοίας ἀπαντώντων οἷς ἂν εὐμενὴς ᾖ, ἐπικρυψάμενος πρὸς τὴν γυναῖκα τήν τε τοῦ θεοῦ πρόρρησιν καὶ ἣν εἶχεν αὐτὸς γνώμην περὶ τῆς τοῦ παιδὸς σφαγῆς, ἀλλὰ μηδὲ τῶν οἰκετῶν τινι δηλώσας, ἐκωλύετο γὰρ ἂν ὑπηρετῆσαι τῷ θεῷ, λαβὼν τὸν Ἴσακον μετὰ δύο οἰκετῶν καὶ τὰ πρὸς τὴν ἱερουργίαν ἐπισάξας ὄνῳ ἀπῄει πρὸς τὸ ὄρος."},{"number":226,"text":"καὶ δύο μὲν ἡμέρας αὐτῷ συνώδευσαν οἱ οἰκέται, τῇ τρίτῃ δὲ ὡς κάτοπτον ἦν αὐτῷ τὸ ὄρος, καταλιπὼν ἐν τῷ πεδίῳ τοὺς συνόντας μετὰ μόνου τοῦ παιδὸς παραγίνεται εἰς τὸ ὄρος, ἐφʼ οὗ τὸ ἱερὸν Δαβίδης ὁ βασιλεὺς ὕστερον ἱδρύεται."},{"number":227,"text":"ἔφερον δὲ σὺν αὐτοῖς ὅσα λοιπὰ πρὸς τὴν θυσίαν ἦν πλὴν ἱερείου. τοῦ δʼ Ἰσάκου πέμπτον τε καὶ εἰκοστὸν ἔτος ἔχοντος τὸν βωμὸν κατασκευάζοντος καὶ πυθομένου, τί καὶ μέλλοιεν θύειν ἱερείου μὴ παρόντος, τὸν θεὸν αὐτοῖς παρέξειν ἔλεγεν ὄντα ἱκανὸν καὶ τῶν οὐκ ὄντων εἰς εὐπορίαν ἀνθρώποις παραγαγεῖν καὶ τὰ ὄντα τῶν ἐπʼ αὐτοῖς θαρρούντων ἀφελέσθαι· δώσειν οὖν κἀκείνῳ ἱερεῖον, εἴπερ εὐμενὴς μέλλει τῇ θυσίᾳ παρατυγχάνειν αὐτοῦ."},{"number":228,"text":"Ὡς δʼ ὁ βωμὸς παρεσκεύαστο καὶ τὰς σχίζας ἐπενηνόχει καὶ ἦν εὐτρεπῆ, λέγει πρὸς τὸν υἱόν· ὦ παῖ, μυρίαις εὐχαῖς αἰτησάμενός σε γενέσθαι μοι παρὰ τοῦ θεοῦ, ἐπεὶ παρῆλθες εἰς τὸν βίον, οὐκ ἔστιν ὅ τι μὴ περὶ τὴν σὴν ἀνατροφὴν ἐφιλοτιμησάμην οὐδʼ ἐφʼ ᾧ μᾶλλον εὐδαιμονήσειν ᾤμην, ὡς εἰ σέ τʼ ἴδοιμι ἠνδρωμένον καὶ τελευτῶν διάδοχον τῆς ἀρχῆς τῆς ἐμαυτοῦ καταλίποιμι."},{"number":229,"text":"ἀλλʼ ἐπεὶ θεοῦ τε βουλομένου σὸς πατὴρ ἐγενόμην καὶ πάλιν τούτῳ δοκοῦν ἀποτίθεμαί σε, φέρε γενναίως τὴν καθιέρωσιν· τῷ θεῷ γάρ σε παραχωρῶ ταύτης ἀξιώσαντι παρʼ ἡμῶν τῆς τιμῆς ἀνθʼ ὧν εὐμενὴς γέγονέ μοι παραστάτης καὶ σύμμαχος νῦν ἐπιτυχεῖν."},{"number":230,"text":"ἐπεὶ δʼ ἐγεννήθης ἀποθάνῃς οὐ τὸν κοινὸν ἐκ τοῦ ζῆν τρόπον, ἀλλʼ ὑπὸ πατρὸς ἰδίου θεῷ τῷ πάντων πατρὶ νόμῳ θυσίας προπεμπόμενος, ἄξιον οἶμαί σε κρίναντος αὐτοῦ μήτε νόσῳ μήτε πολέμῳ μήτε ἄλλῳ τινὶ τῶν παθῶν, ἃ συμπίπτειν πέφυκεν ἀνθρώποις, ἀπαλλαγῆναι τοῦ βίου,"},{"number":231,"text":"μετʼ εὐχῶν τε καὶ ἱερουργίας ἐκείνου ψυχὴν τὴν σὴν προσδεξομένου καὶ παρʼ αὐτῷ καθέξοντος· ἔσῃ τʼ ἐμοὶ εἰς κηδεμόνα καὶ γηρωκόμον, διὸ καὶ σὲ μάλιστα ἀνετρεφόμην, τὸν θεὸν ἀντὶ σαυτοῦ παρεσχημένος."},{"number":232,"text":"Ἴσακος δέ, πατρὸς γὰρ ἦν οἵου τετυχηκότα γενναῖον ἔδει τὸ φρόνημα εἶναι, δέχεται πρὸς ἡδονὴν τοὺς λόγους καὶ φήσας, ὡς οὐδὲ γεγονέναι τὴν ἀρχὴν ἦν δίκαιος, εἰ θεοῦ καὶ πατρὸς μέλλει κρίσιν ἀπωθεῖσθαι καὶ μὴ παρέχειν αὑτὸν τοῖς ἀμφοτέρων βουλήμασιν ἑτοίμως, ὅτε καὶ μόνου τοῦ πατρὸς ταῦτα προαιρουμένου μὴ ὑπακούειν ἄδικον ἦν, ὥρμησεν ἐπὶ τὸν βωμὸν καὶ τὴν σφαγήν."},{"number":233,"text":"κἂν ἐπράχθη τὸ ἔργον μὴ στάντος ἐμποδὼν τοῦ θεοῦ· βοᾷ γὰρ ὀνομαστὶ τὸν Ἅβραμον εἴργων τῆς τοῦ παιδὸς σφαγῆς. οὐ γὰρ ἐπιθυμήσας αἵματος ἀνθρωπίνου τὴν σφαγὴν αὐτῷ προστάξαι τοῦ παιδὸς ἔλεγεν, οὐδὲ οὗ πατέρα ἐποίησεν αὐτὸς ἀφελέσθαι τούτου βουλόμενος μετὰ τοιαύτης ἀσεβείας, ἀλλὰ δοκιμάσαι θέλων αὐτοῦ τὴν διάνοιαν, εἰ καὶ τοιαῦτα προστασσόμενος ὑπακούοι."},{"number":234,"text":"μαθὼν δὲ αὐτοῦ τὸ πρόθυμον καὶ τὴν ὑπερβολὴν τῆς θρησκείας ἥδεσθαι μὲν οἷς αὐτῷ παρέσχεν, οὐχ ὑστερήσειν δὲ αὐτὸν ἀεὶ πάσης ἐπιμελείας καὶ τὸ γένος ἀξιοῦντα, ἔσεσθαί τε τὸν υἱὸν αὐτοῦ πολυχρονιώτατον καὶ βιώσαντα εὐδαιμόνως παισὶν ἀγαθοῖς καὶ γνησίοις παραδώσειν μεγάλην ἡγεμονίαν."},{"number":235,"text":"προεδήλου τε τὸ γένος τὸ αὐτῶν εἰς ἔθνη πολλὰ καὶ πλοῦτον ἐπιδώσειν, καὶ μνήμην αἰώνιον αὐτῶν ἔσεσθαι τοῖς γενάρχαις, τήν τε Χαναναίαν ὅπλοις κατακτησαμένους ζηλωτοὺς ἔσεσθαι πᾶσιν ἀνθρώποις."},{"number":236,"text":"ταῦτα ὁ θεὸς εἰπὼν κριὸν ἐκ τἀφανοῦς παρήγαγεν αὐτοῖς εἰς τὴν ἱερουργίαν. οἱ δὲ παρʼ ἐλπίδας αὐτοῦ κεκομισμένου καὶ τοιούτων ἀγαθῶν ἐπαγγελίας ἀκηκοότες ἠσπάζοντό τε ἀλλήλους καὶ θύσαντες ἀπενόστησαν πρὸς τὴν Σάρραν καὶ διῆγον εὐδαιμόνως ἐφʼ ἅπασιν οἷς ἐθελήσειαν τοῦ θεοῦ συλλαμβάνοντος αὐτοῖς."}],"14":[{"number":237,"text":"Καὶ Σάρρα μὲν οὐ πολὺ ὕστερον ἀποθνήσκει βιώσασα ἔτη ἑπτὰ καὶ εἴκοσι πρὸς τοῖς ἑκατόν. θάπτουσι δʼ αὐτὴν ἐν Νεβρῶνι συγχωρούντων μὲν τῶν Χαναναίων καὶ δημοσίᾳ χοῦν αὐτῆς τὸν τάφον, Ἁβράμου δὲ ὠνησαμένου τὸ χωρίον σίκλων τετρακοσίων παρʼ Ἐφραίμου τινὸς ἐκ τῆς Νεβρῶνος. καὶ τὰ μνημεῖα Ἅβραμός τε καὶ οἱ ἀπόγονοι αὐτοῦ ταύτῃ κατεσκευάσαντο."}],"15":[{"number":238,"text":"Γαμεῖ δʼ αὐτὸς Κατούραν ὕστερον, ἐξ ἧς αὐτῷ παῖδες ἓξ γίνονται πρός τε πόνους καρτεροὶ καὶ δεινοὶ συνιέναι, Ζεμβράνης Ἰαζάρης Μαδάνης Μαδιάνης Λουσούβακος Σοῦος. φύονται δὲ καὶ τούτοις παῖδες· καὶ Σούου μὲν Σαβακίνης γίνεται καὶ Δαδάνης, τούτου δὲ Λατούσιμος Ἄσσουρις Λούουρις· Μαδάνου δὲ Ἠφᾶς Ἑώφρην Ἄνωχος Ἐβιδᾶς Ἐλδᾶς."},{"number":239,"text":"τούτοις ἅπασι τοῖς παισὶ καὶ τοῖς υἱωνοῖς Ἅβραμος ἀποικιῶν στόλους μηχανᾶται, καὶ τήν τε Τρωγλοδῦτιν καταλαμβάνουσι καὶ τῆς εὐδαίμονος Ἀραβίας ὅσον ἐπὶ τὴν Ἐρυθρὰν καθήκει θάλασσαν. λέγεται δέ, ὡς οὗτος ὁ Ἑώφρην στρατεύσας ἐπὶ τὴν Λιβύην κατέσχεν αὐτὴν καὶ οἱ υἱωνοὶ αὐτοῦ κατοικήσαντες ἐν αὐτῇ τὴν γῆν ἀπὸ τοῦ ἐκείνου ὀνόματος Ἀφρικὰ προσηγόρευσαν."},{"number":240,"text":"μαρτυρεῖ δέ μου τῷ λόγῳ Ἀλέξανδρος ὁ πολυίστωρ λέγων οὕτως· Κλεόδημος δέ φησιν ὁ προφήτης ὁ καὶ Μάλχος ἱστορῶν τὰ περὶ Ἰουδαίων, καθὼς καὶ Μωυσῆς ἱστόρησεν ὁ νομοθέτης αὐτῶν, ὅτι ἐκ τῆς Κατούρας Ἁβράμῳ ἐγένοντο παῖδες ἱκανοί."},{"number":241,"text":"λέγει δὲ αὐτῶν καὶ τὰ ὀνόματα ὀνομάζων τρεῖς Ἰαφέραν Σούρην Ἰαφράν. ἀπὸ Σούρου μὲν τὴν Ἀσσυρίαν κεκλῆσθαι, ἀπὸ δὲ τῶν δύο Ἰαφρᾶ τε καὶ Ἰαφέρου, πόλιν τε Ἐφρᾶν καὶ τὴν χώραν Ἀφρικὰ ὀνομασθῆναι. τούτους γὰρ Ἡρακλεῖ συστρατεῦσαι ἐπὶ Λιβύην καὶ Ἀνταῖον· γήμαντά τε τὴν Ἀφράνου θυγατέρα Ἡρακλέα γεννῆσαι υἱὸν ἐξ αὐτῆς Δίδωρον· τούτου δὲ γενέσθαι Σόφωνα, ἀφʼ οὗ τοὺς βαρβάρους Σόφακας λέγεσθαι."}],"16":[{"number":242,"text":"Ἰσάκῳ δὲ περὶ τεσσαρακοστὸν ἔτος γεγονότι γυναῖκα γνοὺς ἀγαγέσθαι ὁ πατὴρ Ἅβραμος Ῥεβέκκαν Ναχώρου παιδὸς θυγατέρα τἀδελφοῦ τὸν πρεσβύτατον πέμπει τῶν οἰκετῶν ἐπὶ τὴν μνηστείαν ἐνδησάμενος μεγάλαις πίστεσι."},{"number":243,"text":"γίνονται δὲ αὗται τοῦτον τὸν τρόπον· ὑπὸ τοὺς μηροὺς ἀλλήλοις τὰς χεῖρας ἐπαγαγόντες ἔπειτα ἐπικαλοῦνται τὸν θεὸν μάρτυρα τῶν ἐσομένων. ἔπεμπε δὲ καὶ δῶρα τοῖς ἐκεῖ διὰ τὸ σπάνιον ἢ μηδʼ ὅλως ἐπιχωριάζειν ἐκτετιμημένα."},{"number":244,"text":"οὗτος ἀπερχόμενος χρόνῳ διὰ τὸ εἶναι χαλεπὴν ὁδεύεσθαι τὴν Μεσοποταμίαν, χειμῶνι μὲν ὑπὸ πηλῶν βάθους, θέρους δʼ ὑπὸ ἀνυδρίας, ἔτι δὲ καὶ λῃστηρίων ὄντων ἐν αὐτῇ, ἃ διαφυγεῖν οὐκ ἐνῆν μὴ προνοοῦσι τούτου τοῖς ὁδεύουσιν, εἰς πόλιν ἀφικνεῖται Κάρραν καὶ γενόμενος ἐν τοῖς προαστείοις παρθένοις ἐντυγχάνει πλείοσιν ἐφʼ ὕδωρ βαδιζούσαις·"},{"number":245,"text":"εὔχεται μὲν οὖν τῷ θεῷ Ῥεβέκκαν, ἣν τῷ παιδὶ Ἅβραμος μνηστευσόμενον ἐξαπέστειλεν, εἰ κατὰ νοῦν τὸν αὐτοῦ μέλλει ὁ γάμος οὗτος συντελεῖσθαι, ἐν ἐκείναις εὑρεθῆναι γνωρισθῆναι τε αὐτὴν τῶν μὲν ἄλλων αἰτοῦντι ποτὸν ἀρνουμένων ἐκείνης δὲ αὐτῷ παρασχούσης."},{"number":246,"text":"Καὶ ὁ μὲν ἐπὶ ταύτης ὢν τῆς διανοίας ἐπὶ τὸ φρέαρ παραγίνεται καὶ παρακαλεῖ τὰς παρθένους ποτὸν αὐτῷ παρασχεῖν· τῶν δʼ ἐκτρεπομένων ὡς χρῃζουσῶν οἴκαδε κομίζειν, ἀλλʼ οὐκ ἐκείνῳ παρασχεῖν, καὶ γὰρ οὐδʼ εὔληπτον εἶναι τὸ ὕδωρ, μία ἐξ ἁπασῶν ἐκείναις τε τῆς πρὸς τὸν ξένον ἐπιπλήττει δυσκολίας, τίνος ἄλλου κοινωνήσειν πρὸς ἀνθρώπους αὐτάς ποτε, αἳ μηδʼ ὕδατος μετέδοσαν λέγουσα, καὶ παρέχει αὐτῷ φιλοφρόνως."},{"number":247,"text":"ὁ δὲ ἐν ἐλπίδι μὲν τῶν ὅλων γενόμενος, βουλόμενος δὲ τὴν ἀλήθειαν μαθεῖν, ἐπῄνει τε τῆς εὐγενείας αὐτὴν καὶ τῆς χρηστότητος, ὅτι καὶ μετʼ οἰκείου πόνου τοῖς δεομένοις ἐπαρκεῖν οὐκ ἔφυγεν, ἐπυνθάνετό τε τίνων εἴη γονέων καὶ κατεύχεται αὐτοῖς ὄνησιν τοιαύτης παιδὸς καί νυμφεύσειαν, φησίν, ὡς αὐτοῖς ἐστι κεχαρισμένον, εἰς οἶκον ἀνδρὸς ἀγαθοῦ παῖδας αὐτῷ τεξομένην γνησίους."},{"number":248,"text":"ἡ δὲ οὐδὲ τούτων ἐφθόνησεν αὐτῷ βουλομένῳ μαθεῖν, ἀλλὰ καὶ τὸ γένος ἀπεσήμαινε καὶ Ῥεβέκκα μέν, φησίν, ἐγὼ καλοῦμαι, πατὴρ δέ μοι Βαθουῆλος ἦν· ἀλλʼ ὁ μὲν ἤδη τέθνηκε, Λάβανος δὲ ἀδελφός ἐστιν ἡμέτερος τοῦ τε οἴκου παντὸς σὺν τῇ μητρὶ προνοούμενος καὶ τῆς ἐμῆς παρθενίας ἐπιμελόμενος."},{"number":249,"text":"τούτων ἀκροασάμενος ἔχαιρέ τε τοῖς γεγονόσι καὶ τοῖς εἰρημένοις τὸν θεὸν οὕτως ὁρῶν αὐτῷ τῆς ὁδοῦ σαφῶς συλλαμβάνοντα, καὶ προκομίσας ὁρμίσκον τε καί τινας κόσμους, οὓς εὐπρεπὲς φορεῖν παρθένοις, ἀνεδίδου τῇ κόρῃ τῆς ἐπὶ τῷ πιεῖν χάριτος ἀμοιβὴν εἶναι καὶ γέρας, δίκαιον λέγων τοιούτων αὐτὴν τυγχάνειν ἀγαθὴν παρὰ τὰς τοσαύτας παρθένους γενομένην."},{"number":250,"text":"ἠξίου τε παρʼ αὐτοῖς καταχθῆναι τοῦ προσωτέρω χωρεῖν τῆς νυκτὸς αὐτὸν ἀφαιρουμένης, κόσμον τε φέρων γυναικεῖον πολυτελῆ πιστεύειν αὐτὸν οὐκ ἀσφαλεστέροις ἔφασκεν ἢ τούτοις, οἷς αὐτὸς ἐπειράθη. τεκμαίρεσθαι δὲ καὶ τὴν τῆς μητρὸς καὶ τἀδελφοῦ φιλανθρωπίαν αὐτῆς ἔλεγεν, ὡς οὐ δυσχερανοῦσιν, ἐκ τῆς περὶ αὐτὴν ἀρετῆς· οὐδὲ γὰρ ἔσεσθαι βαρὺς μισθόν τε τῆς φιλοξενίας τελέσας καὶ δαπάναις ἰδίαις χρησάμενος."},{"number":251,"text":"ἡ δὲ περὶ μὲν τῆς τῶν γονέων φιλανθρωπίας αὐτῆς ὀρθῶς εἰκάζειν αὐτὸν εἶπεν, ἐπεμέμφετο δὲ ὡς μικρολόγους ὑπειληφότα· πάντων γὰρ ἀμισθὶ μεθέξειν. δηλώσασα μέντοι Λαβάνῳ πρότερον τἀδελφῷ συγχωροῦντος ἄξειν αὐτὸν ἔλεγεν."},{"number":252,"text":"Ὡς οὖν τούτου γενομένου παρῆγε τὸν ξένον, τὰς μὲν καμήλους αὐτοῦ παραλαμβάνοντες οἱ Λαβάνου θεράποντες ἐτημέλουν, αὐτὸς δὲ δειπνήσων εἰσήγετο σὺν αὐτῷ καὶ μετὰ τὸ δεῖπνόν φησι πρός τε αὐτὸν καὶ τὴν μητέρα τῆς κόρης· Ἅβραμος Θέρρου μέν ἐστιν υἱός, συγγενὴς δʼ ὑμέτερος· Ναχώρης γὰρ ὁ τούτων, ὦ γύναι, τῶν παίδων πάππος ἀδελφὸς ἦν Ἁβράμου ὁμοπάτριός τε καὶ ὁμομήτριος."},{"number":253,"text":"πέμπει τοίνυν οὗτος πρὸς ὑμᾶς ἀξιῶν τὴν κόρην ταύτην παιδὶ τῷ ἑαυτοῦ λαβεῖν πρὸς γάμον, ὃς γνήσιός ἐστιν αὐτῷ καὶ μόνος ἐπὶ τοῖς πᾶσι τεθραμμένος. ᾧ τῶν μὲν ἐκεῖ γυναικῶν δυνατὸν αὐτῷ τὴν εὐδαιμονεστάτην λαβεῖν οὐκ ἠξίωσεν ἀγαγέσθαι, τιμῶν δὲ τὸ γένος τὸν γάμον πολιτεύει τοῦτον."},{"number":254,"text":"οὗ τὴν σπουδὴν καὶ τὴν προαίρεσιν μὴ ὑβρίσητε· κατὰ γὰρ θεοῦ βούλησιν τά τε ἄλλα μοι κατὰ τὴν ὁδὸν ἀπήντησε καὶ τὴν παῖδα καὶ τὸν ὑμέτερον οἶκον εὗρον. ἐπεὶ γὰρ πλησίον τῆς πόλεως ἐγενόμην, παρθένους ἰδὼν πολλὰς ἐπὶ τὸ φρέαρ παραγινομένας ηὐξάμην εἰς ταύτην ἐμπεσεῖν, ὃ δὴ γέγονε."},{"number":255,"text":"γάμον οὖν ὑπὸ θείας μνηστευόμενον ἐπιφανείας καὶ ὑμεῖς κυρώσατε καὶ Ἅβραμον τὸν μετὰ τοσαύτης ἀπεσταλκότα σπουδῆς τῷ κατανεῦσαι τὴν κόρην τιμήσατε. οἱ δὲ, καλὰ γὰρ ἦν αὐτοῖς καὶ κεχαρισμένα, τήν τε γνώμην τοῦ θεοῦ συνῆκαν καὶ πέμπουσιν ἐφʼ οἷς ἠξίου τὴν θυγατέρα. γαμεῖ δὲ ταύτην ὁ Ἴσακος τῶν πραγμάτων εἰς αὐτὸν ἀφικομένων· οἱ γὰρ ἐκ τῆς Κατούρας εἰς τὰς ἀποικίας ἐξεληλύθεισαν."}],"17":[{"number":256,"text":"Τελευτᾷ δὲ καὶ Ἅβραμος μετʼ ὀλίγον, ἀνὴρ πᾶσαν ἀρετὴν ἄκρος καὶ τῆς περὶ αὐτὸν σπουδῆς ἀξίως ὑπὸ τοῦ θεοῦ τετιμημένος. ἐβίωσε δὲ τὸν πάντα χρόνον ἐτῶν ἑβδομηκονταπέντε πρὸς τοῖς ἑκατὸν καὶ θάπτεται ἐν Νεβρῶνι μετὰ τῆς γυναικὸς Σάρρας ὑπὸ τῶν παίδων Ἰσάκου καὶ Ἰσμαήλου."}],"18":[{"number":257,"text":"Ἰσάκῳ δὲ μετὰ τὴν Ἁβράμου τελευτὴν ἐκύει τὸ γύναιον, καὶ τῆς γαστρὸς ἐπὶ μεῖζον ὀγκουμένης ἀγωνιάσας ἀνήρετο τὸν θεόν. φράζει δʼ αὐτῷ διδύμους τέξεσθαι τὴν Ῥεβέκκαν καὶ φερώνυμα ἔσεσθαι τοῖς παισὶν ἔθνη, τοῦ δὲ μείζονος προτερήσειν τὸ δοκοῦν ἔλασσον εἶναι."},{"number":258,"text":"τίκτεται δʼ αὐτῷ μετʼ ὀλίγον κατὰ πρόρρησιν τοῦ θεοῦ δίδυμα παιδία, ὧν τὸ μὲν πρεσβύτερον ἀπὸ κεφαλῆς ἐπὶ τοὺς πόδας περισσῶς ἦν δασύ, τὸ δὲ νεώτερον εἴχετο προϊόντος αὐτοῦ κατὰ πτέρναν. ἠγάπα δὲ ὁ μὲν πατὴρ τὸν πρεσβύτερον Ἠσαῦ λεγόμενον κατʼ ἐπωνυμίαν τῆς τριχώσεως· Ἑβραῖοι γὰρ τὸ ἤσαυρον τρίχωμα λέγουσιν· Ἰάκωβος δὲ ὁ νεώτερος τῇ μητρὶ προσφιλὴς ἦν."},{"number":259,"text":"Λιμοῦ δὲ τὴν γῆν καταλαβόντος Ἴσακος, δόξαν αὐτῷ χωρεῖν εἰς Αἴγυπτον τῆς χώρας ἀγαθῆς ὑπαρχούσης, ἐπὶ Γεράρων ἀπῄει τοῦ θεοῦ κελεύσαντος. ὑποδέχεται δʼ αὐτὸν ὁ βασιλεὺς Ἀβιμέλεχος κατὰ ξενίαν καὶ φιλίαν τὴν Ἁβράμου καὶ πολλῇ πάνυ πρὸς αὐτὸν εὐνοίᾳ χρησάμενος κατʼ ἀρχὰς ἐπὶ ταύτης ὑπὸ φθόνου μεῖναι πρὸς τὸ πᾶν ἐκωλύθη."},{"number":260,"text":"ὁρῶν γὰρ τὸν θεὸν τῷ Ἰσάκῳ συμπαρόντα καὶ τοσαύτῃ περὶ αὐτὸν σπουδῇ χρώμενον ἀπώσατο αὐτόν. ὁ δὲ τοιούτου πάλιν ἐκ μεταβολῆς τῆς ἀπὸ τοῦ βασκάνου πειραθεὶς Ἀβιμελέχου τότε μὲν ἀνεχώρησεν εἰς τὴν λεγομένην Φάραγγα χωρίον οὐ μακρὰν Γεράρων, ὀρύσσοντι δʼ αὐτῷ φρέαρ ποιμένες ἐπιπεσόντες εἰς μάχην ἐχώρησαν κωλύοντες τὸ ἔργον, καὶ μὴ βουληθέντος φιλονικεῖν ἔδοξαν κεκρατηκέναι."},{"number":261,"text":"ὑποχωρήσας δὲ ὤρυσσεν ἕτερον, καὶ βιασαμένων ἄλλων τινῶν Ἀβιμελέχου ποιμένων καὶ τοῦτο καταλιπὼν ἀπεχώρησεν εὐγνώμονι λογισμῷ κτώμενος αὑτῷ τὴν ἄδειαν."},{"number":262,"text":"εἶτα αὐτομάτου παρασχόντος αὐτῷ τὴν φρεωρυχίαν ἀνεπικώλυτον, Ῥοωβὼθ τὸ φρέαρ ὠνόμασεν· εὐρύχωρον ἀποσημαίνει τὸ ὄνομα. τῶν δὲ προτέρων τὸ μὲν Ἔσκον καλεῖται· μάχην ἄν τις αὐτὸ φήσειε· τὸ δʼ ἕτερον Σύαιναν· ἔχθραν ἀποσημαίνει τὸ ὄνομα."},{"number":263,"text":"Ἰσάκῳ μὲν οὖν ἀκμάζειν συνέβαινε τὴν ἰσχὺν ὑπὸ μεγέθους πραγμάτων, Ἀβιμέλεχος δὲ κατʼ αὐτοῦ φύεσθαι νομίζων τὸν Ἴσακον, ὑπόπτου μὲν αὐτοῖς καὶ τῆς συνδιαιτήσεως γενομένης, ἐπʼ οὐ φανερᾷ δὲ ἔχθρᾳ τοῦ Ἰσάκου ὑπεκστάντος, δείσας μὴ τῆς προτέρας αὐτῷ φιλίας οὐδὲν ὄφελος γένηται πρὸς ἄμυναν ὧν ἔπαθεν Ἰσάκου τραπέντος φιλίαν ἄνωθεν ποιεῖται πρὸς αὐτὸν ἕνα τῶν στρατηγῶν Φίλοχον ἐπαγόμενος."},{"number":264,"text":"πάντων δὲ τετυχηκὼς ὧν ἠξίου διὰ τὴν Ἰσάκου χρηστότητα ὀργῆς προσφάτου πρεσβυτέραν χάριν εἰς αὐτόν τε καὶ τὸν πατέρα γεγενημένην προτιμῶντος ἀπῆρεν εἰς τὴν ἑαυτοῦ."},{"number":265,"text":"Τῶν δὲ Ἰσάκου παίδων Ἡσαῦς, περὶ ὃν μάλιστα ὁ πατὴρ ἐσπουδάκει, τεσσαράκοντα γεγονὼς ἔτη γαμεῖ Ἄδαν τὴν Ἥλωνος καὶ Ἀλιβάμην τὴν Εὐσεβεῶνος δυναστευόντων ἐν Χαναναίοις ἀνδρῶν θυγατέρας, ἑαυτὸν ποιήσας τῆς περὶ τὸν γάμον ἐξουσίας κύριον καὶ μηδὲ τῷ πατρὶ συμβουλευσάμενος·"},{"number":266,"text":"οὐδὲ γὰρ ἂν ἐπέτρεψεν Ἴσακος ἐπʼ αὐτῷ τῆς γνώμης γενομένης· οὐ γὰρ ἦν αὐτῷ διʼ ἡδονῆς συνάψασθαι συγγένειαν πρὸς τοὺς ἐπιχωρίους. οὐ βουλόμενος δὲ ἀπεχθὴς εἶναι τῷ παιδὶ κελεύων ἀφίστασθαι τῶν γυναικῶν σιγᾶν ἔκρινε."},{"number":267,"text":"Γηραιὸς δὲ ὢν καὶ τὰς ὄψεις εἰς τὸ παντελὲς ἠφανισμένος προσκαλεσάμενος τὸν Ἡσαῦν καὶ τὸ γῆρας εἰπὼν ὡς καὶ δίχα τῆς πηρώσεως καὶ"},{"number":268,"text":"τοῦ κατὰ τὰς ὄψεις πάθους ἐμποδὼν ἦν αὐτῷ θεραπεύειν τὸν θεὸν ἐκέλευσεν ἐξελθεῖν ἐπὶ κυνηγέσιον καὶ θηρασάμενον ὅσα ἂν αὐτῷ δυνατὸν γίνηται παρασκευάσαι δεῖπνον, ἵνα μετὰ τοῦτο ἱκετεύσῃ τὸν θεὸν σύμμαχον αὐτῷ καὶ συνεργὸν εἰς ἅπαντα παρεῖναι τὸν βίον, ἄδηλον μὲν εἶναι λέγων, ὁπότε καὶ τελευτήσειε, πρὸ δὲ τούτου παρασχεῖν αὐτῷ βούλεσθαι τὸν θεὸν ταῖς εὐχαῖς ταῖς ὑπὲρ αὐτοῦ παρακεκλημένον."},{"number":269,"text":"Καὶ Ἡσαῦς μὲν ἐπὶ τὸ κυνηγέσιον ἐξώρμησεν· ἡ δὲ Ῥεβέκκα τὸν θεὸν εἰς τὴν εὔνοιαν ἀξιοῦσα τὴν Ἰακώβου παρακαλεῖν καὶ παρὰ τὴν Ἰσάκου γνώμην ἐκέλευσεν αὐτὸν ἐρίφους κατασφάξαντα δεῖπνον παρασκευάζειν. ὁ δὲ Ἰάκωβος ὑπηρέτει τῇ μητρὶ πάντα παρʼ αὐτῆς πεπυσμένος·"},{"number":270,"text":"ἐπεὶ δʼ εὐτρεπὲς ἦν τὸ δεῖπνον, ἐρίφου δέρματι τὸν βραχίονα περιβαλών, ἵνα πιστεύοιτο παρὰ τῷ πατρὶ διὰ τὴν δασύτητα Ἡσαῦς εἶναι, τὰ γὰρ ἄλλα πάντʼ ὢν ὅμοιος διὰ τὸ εἶναι δίδυμος τούτῳ μόνῳ διέφερε, καὶ φοβηθεὶς μὴ πρὶν γενέσθαι τὰς εὐχὰς εὑρεθεὶς κακουργῶν εἰς τοὐναντίον παροξύνῃ τὸν πατέρα ποιήσασθαι ταύτας, προσέφερε τῷ πατρὶ τὸ δεῖπνον."},{"number":271,"text":"καὶ ὁ Ἴσακος ἐπαισθόμενος τῷ κατὰ τὴν φωνὴν ἰδίῳ προσκαλεῖται τὸν υἱόν· τοῦ δὲ τὸν βραχίονα προτείναντος, ᾧ τὴν αἰγέαν περιβέβλητο, ταύτης ἐπαφώμενος φωνεῖς μέν, εἶπεν, Ἰακώβῳ παραπλήσιον, κατὰ δὲ τὸ τῆς τριχὸς βάθος Ἡσαῦς εἶναί μοι δοκεῖς."},{"number":272,"text":"καὶ μηδὲν ὑπολαβὼν κακοῦργον δειπνήσας τρέπεται πρὸς εὐχὰς καὶ παράκλησιν τοῦ θεοῦ δέσποτα, λέγων, παντὸς αἰῶνος καὶ δημιουργὲ τῆς ὅλης οὐσίας· σὺ γὰρ πατρὶ τῷ ἐμῷ μεγάλην ἰσχὺν προύθηκας ἀγαθῶν κἀμὲ τῶν παρόντων ἠξίωσας καὶ τοῖς ἐξ ἐμοῦ γενομένοις ὑπέσχου βοηθὸς εὐμενὴς καὶ δοτὴρ ἀεὶ τῶν κρειττόνων ἔσεσθαι·"},{"number":273,"text":"ταῦτʼ οὖν καὶ βεβαίωσον καὶ μὴ περιίδῃς με διὰ τὴν παροῦσαν ἀσθένειαν, διʼ ἣν καὶ μᾶλλόν σου δεόμενος τυγχάνω, καί μοι παῖδα τοῦτον εὐμενὴς σῶζε καὶ παντὸς ἀπαθῆ κακοῦ διαφύλαττε δοὺς αὐτῷ βίον εὐδαίμονα καὶ κτῆσιν ἀγαθῶν, ὅσων σοι δύναμις παρασχεῖν, ποιήσας δʼ αὐτὸν φοβερὸν μὲν ἐχθροῖς φίλοις δὲ τίμιον καὶ κεχαρισμένον."},{"number":274,"text":"Καὶ ὁ μὲν νομίζων εἰς Ἡσαῦν ποιεῖσθαι τὰς εὐχὰς παρεκάλει τὸν θεόν· ἄρτι δὲ πέπαυτο τούτων καὶ παρῆν Ἡσαῦς ἀπὸ τῆς θήρας. καὶ τῆς διαμαρτίας Ἴσακος αἰσθόμενος ἡσυχίαν ἄγει, Ἡσαῦς δὲ ἠξίου τῶν ὁμοίων τἀδελφῷ παρὰ τοῦ πατρὸς τυγχάνειν·"},{"number":275,"text":"τοῦ δὲ πατρὸς ἀρνουμένου διὰ τὸ πάσας εἰς Ἰάκωβον τὰς εὐχὰς ἀνηλωκέναι πένθος ἦγεν ἐπὶ τῇ διαμαρτίᾳ. καὶ αὐτοῦ τοῖς δάκρυσιν ἀχθόμενος ὁ πατὴρ τὰ μὲν περὶ τὸ κυνηγέσιον καὶ δύναμιν σώματος ἐν ὅπλοις καὶ πᾶσιν ἔργοις εὐδοκιμήσειν αὐτὸν ἔφασκε καὶ καρπώσεσθαι τὴν ἐπʼ αὐτοῖς δόξαν διʼ αἰῶνος καὶ τὸ ἀπʼ αὐτοῦ γένος, δουλεύσειν δὲ τἀδελφῷ."},{"number":276,"text":"Ἰάκωβον δὲ φοβούμενον τὸν ἀδελφὸν τιμωρίαν βουλόμενον λαβεῖν τῆς ἐπὶ ταῖς εὐχαῖς διαμαρτίας ἡ μήτηρ ῥύεται· πείθει γὰρ τὸν ἄνδρα Μεσοποταμίαν ἀγαγέσθαι τῷ Ἰακώβῳ γυναῖκα συγγενῆ."},{"number":277,"text":"ἤδη γὰρ τὴν Ἰσμαήλου παῖδα Ἡσαῦς παρειλήφει πρὸς γάμον Βασεμάθην· οὐ γὰρ εὐνόουν τοῖς Χαναναίοις οἱ περὶ τὸν Ἴσακον, ὥστε ἐπὶ τοῖς πρότερον αὐτοῦ γάμοις δυσχερῶς διακειμένων εἰς τὸ ἐκείνοις κεχαρισμένον τὴν Βασεμάθην παρέλαβεν μάλιστα περὶ αὐτὴν σπουδάσας."}],"19":[{"number":278,"text":"Ἰάκωβος δὲ εἰς τὴν Μεσοποταμίαν στελλόμενος ὑπὸ τῆς μητρὸς κατὰ γάμον τῆς Λαβάνου θυγατρὸς τοῦ ἐκείνης ἀδελφοῦ, ἐπιτρέψαντος Ἰσάκου τὸν γάμον διὰ τὸ πείθεσθαι τοῖς βουλήμασι τῆς γυναικὸς διὰ τῆς Χαναναίας ἐπορεύετο καὶ διὰ τὸ πρὸς τοὺς ἐπιχωρίους μῖσος παρʼ οὐδένα μὲν ἠξίου κατάγεσθαι,"},{"number":279,"text":"ὑπαίθριος δὲ ηὐλίζετο τὴν κεφαλὴν λίθοις ὑπʼ αὐτοῦ συμφορουμένοις ἐπιτιθεὶς καὶ τοιαύτην κατὰ τοὺς ὕπνους ὄψιν ὁρᾷ παραστᾶσαν αὐτῷ· κλίμακα γῆθεν ἔδοξεν ἐφικνουμένην τοῦ οὐρανοῦ βλέπειν καὶ διʼ αὐτῆς ὄψεις κατιούσας σεμνότερον ἢ κατὰ ἀνθρώπου φύσιν ἐχούσας, καὶ τελευταῖον ὑπὲρ αὐτῆς τὸν θεὸν ἐναργῶς αὐτῷ φαινόμενον ὀνομαστί τε καλέσαι καὶ ποιήσασθαι τοιούτους λόγους."},{"number":280,"text":"Ἰάκωβε, πατρὸς ὄντα σε ἀγαθοῦ καὶ πάππου δόξαν ἀρετῆς μεγάλης εὑραμένου κάμνειν ἐπὶ τοῖς παροῦσιν οὐ προσῆκεν, ἀλλʼ ἐλπίζειν τὰ κρείττονα·"},{"number":281,"text":"καὶ γὰρ ἄφθονος ἐκδέξεταί σε μεγάλων ἀγαθῶν παρουσία πρὸς τὸ πᾶν κατὰ τὴν ἐμὴν ἐπικουρίαν. Ἅβραμόν τε γὰρ ἐγὼ ἐκ τῆς Μεσοποταμίας δεῦρο ἤγαγον ἐλαυνόμενον ὑπὸ τῶν συγγενῶν, καὶ πατέρα τὸν σὸν εὐδαίμονα ἀπέφηνα· ὧν οὐχ ἥττω μοῖραν εἰς σὲ καταθήσομαι·"},{"number":282,"text":"θαρρῶν οὖν καὶ ταύτην πορεύου τὴν ὁδὸν ἐμοὶ προπομπῷ χρώμενος· ἀνυσθήσεται γάρ σοι γάμος, ἐφʼ ὃν ἐσπούδακας, καὶ γενήσονταί σοι παῖδες ἀγαθοί, τὸ δὲ πλῆθος αὐτῶν ἀριθμοῦ κρεῖττον ἔσται, μείζοσιν υἱοῖς αὐτῶν καταλιμπάνοντες· οἷς ἐγὼ τὸ ταύτης κράτος τῆς γῆς δίδωμι καὶ παισὶ τοῖς αὐτῶν, οἳ πληρώσουσιν ὅσην ἥλιος ὁρᾷ καὶ γῆν καὶ θάλασσαν."},{"number":283,"text":"ἀλλὰ μήτε κίνδυνον ὑφορῶ μηδένα μήτʼ εὐλαβοῦ τὸ πλῆθος τῶν πόνων ἐμοῦ ποιουμένου τῶν σοὶ πραχθησομένων πρόνοιαν ἔν τε τοῖς νῦν καὶ πολὺ πλέον ἐν τοῖς ὕστερον."},{"number":284,"text":"Ταῦτα μὲν οὖν ὁ θεὸς Ἰακώβῳ προαγορεύει· ὁ δὲ περιχαρὴς γενόμενος ἐπὶ τοῖς ἑωραμένοις καὶ κατηγγελμένοις φαιδρύνει τε τοὺς λίθους ὡς τηλικούτων ἀγαθῶν ἐπʼ αὐτοῖς προρρήσεως γεγενημένης καὶ εὐχὴν ποιεῖται θύσειν ἐπʼ αὐτῶν, εἰ κτησάμενος βίον ἀπαθὴς ἐπανίοι, τῷ θεῷ δεκάτην τῶν πεπορισμένων ποιεῖσθαι οὕτως ἀφικόμενος, τίμιόν τε κρίνει τὸ χωρίον ὄνομα αὐτῷ Βηθὴλ θέμενος, σημαίνει δὲ τοῦτο θείαν ἑστίαν κατὰ τὴν τῶν Ἑλλήνων γλῶτταν."},{"number":285,"text":"Προϊὼν δὲ ἐπὶ τῆς Μεσοποταμίας χρόνῳ παρῆν εἰς τὴν Χαρράν, καὶ ποιμένας ἐν τοῖς προαστείοις καταλαβὼν καὶ παῖδας ἐφήβους καὶ παρθένους ὑπέρ τινος ἱδρυμένους φρέατος συνδιέτριβεν αὐτοῖς χρῄζων ποτοῦ εἴς τε λόγους αὐτοῖς ἀφικνούμενος ἀνέκρινεν αὐτούς, εἰ τυγχάνουσι Λάβανόν τινα παρʼ αὐτοῖς εἰδότες ἔτι περιόντα."},{"number":286,"text":"οἱ δὲ πάντες ἐπίστασθαί τε ἔφασαν, οὐ γὰρ εἶναι τοιοῦτον ὥστε ἀγνοεῖσθαι, καὶ συμποιμαίνειν αὐτοῖς θυγατέρα αὐτοῦ, ἣν θαυμάζειν ὅτι μήπω παρείη· παρὰ γὰρ ταύτης μεμαθήκεις ἂν ἀκριβέστερον ὅσα περὶ αὐτῶν ἀκοῦσαι ποθεῖς. ταῦτα δʼ αὐτῶν ἔτι λεγόντων παρῆν ἡ παῖς σὺν τοῖς ἐπικατιοῦσι τῶν ποιμένων."},{"number":287,"text":"καὶ δεικνύουσι τὸν Ἰάκωβον αὐτῇ λέγοντες, ὡς ξένος οὗτος ἥκοι τὰ περὶ τοῦ πατρὸς αὐτῆς ἀναπυνθανόμενος. ἡ δὲ ἡσθεῖσα ὑπὸ νηπιότητος τῇ παρουσίᾳ τοῦ Ἰακώβου ἀνέκρινεν αὐτόν, τίς τε ὢν καὶ πόθεν ἥκοι πρὸς αὐτοὺς καὶ ὑπὸ τίνος χρείας ἠγμένος, ηὔχετο δὲ δυνατὸν εἶναι αὐτοῖς παρέχειν ὧν ἀφικνεῖται δεόμενος."},{"number":288,"text":"Ἰάκωβος δὲ οὐχ ὑπὸ τῆς συγγενείας οὐδὲ τῆς διὰ ταύτην εὐνοίας, ἀλλʼ ἔρωτι τῆς παιδὸς ἡττηθεὶς ἐκπέπληκτό τε τοῦ κάλλους ὁρῶν οὕτως ἔχουσαν, ὡς ὀλίγαι τῶν τότε γυναικῶν ἤνθουν, καὶ φησίν· ἀλλʼ ἐμοὶ πρὸς σὲ καὶ πατέρα τὸν σόν, εἴπερ Λαβάνου παῖς τυγχάνεις, οἰκειότης ἐστὶ πρεσβυτέρα τῆς τε σῆς καὶ ἐμῆς γενέσεως·"},{"number":289,"text":"ἐκ Θάρρου γὰρ Ἅβραμος καὶ Ἀρράνης καὶ Ναχώρης ἦσαν υἱοί, ὧν Βαθουῆλος ὁ σὸς πάππος Ναχώρου γίνεται παῖς, Ἁβράμου δὲ καὶ τῆς Ἀρράνου Σάρρας Ἴσακος ὁ ἐμὸς πατήρ. ἔγγιον δὲ καὶ νεώτερον τοῦθʼ ἡμεῖς τῆς συγγενείας ὁμήρευμα ἔχομεν πρὸς ἀλλήλους·"},{"number":290,"text":"Ῥεβέκκα γὰρ μήτηρ ἐμὴ Λαβάνου πατρὸς τοῦ σοῦ ἀδελφὴ πατρός τε τοῦ αὐτοῦ καὶ μητρός, ἀνεψιοὶ δʼ ἐσμὲν ἡμεῖς ἐγώ τε καὶ"},{"number":291,"text":"σύ. καὶ νῦν δεῦρο ἥκω ἀσπασόμενός τε ὑμᾶς καὶ τὴν προϋπάρχουσαν ἡμῖν συγγένειαν ἀνανεωσόμενος. ἡ δὲ ὑπὸ μνήμης, ὁποῖα φιλεῖ συντυγχάνειν τοῖς νέοις, προπεπυσμένη παρὰ τοῦ πατρὸς τὰ περὶ τῆς Ῥεβέκκας καὶ τοὺς γονεῖς εἰδυῖα ποθοῦντας αὐτῆς τὸ ὄνομα ὑπὸ τῆς περὶ τὸν πατέρα εὐνοίας ἔνδακρυς γενομένη περιβάλλει τὸν Ἰάκωβον,"},{"number":292,"text":"καὶ κατασπασαμένη τὴν εὐκταιοτάτην καὶ μεγίστην ἡδονὴν αὐτὸν κομίσαι τῷ πατρὶ καὶ τοῖς ἐπὶ τῆς οἰκίας ἅπασιν ἔλεγεν ἐπὶ τῇ μνήμῃ τῆς μητρὸς αὐτοῦ κειμένῳ καὶ πρὸς μόνῃ ταύτῃ τυγχάνοντι· φανεῖσθαι δʼ αὐτῷ παντὸς ἀντάξιον ἀγαθοῦ. χωρεῖν τε ἐκέλευεν ἤδη πρὸς τὸν πατέρα καὶ ἕπεσθαι πρὸς αὐτὸν ἡγουμένῃ καὶ τῆς ἡδονῆς μὴ ἀφαιρεῖσθαι τὸ πλέον αὐτὸν βραδύνοντα."},{"number":293,"text":"Ταῦτʼ εἰποῦσα παρῆγεν αὐτὸν πρὸς τὸν Λάβανον, καὶ γνωρισθεὶς ὑπὸ τοῦ μήτρωος αὐτός τε ἀδεὴς ἦν ἐν φίλοις γενόμενος κἀκείνοις πολλὴν ἡδονὴν παρεῖχεν ἀδοκήτως ἐπιφανείς."},{"number":294,"text":"μετὰ δὲ οὐ πολλὰς ἡμέρας ὁ Λάβανος χαίρειν μὲν ἐπʼ αὐτῷ παρόντι μειζόνως ἢ ὡς τῷ λόγῳ δηλώσειεν ἔλεγε, τὴν δʼ αἰτίαν διʼ ἣν ἀφῖκται μητέρα τε καὶ πατέρα πρεσβύτας καταλιπὼν καὶ θεραπείας τῆς παρʼ αὐτοῦ δεομένους ἀνεπυνθάνετο· παρέξειν γὰρ αὐτῷ καὶ πρὸς ἅπασαν ἐπαμύνειν χρείαν."},{"number":295,"text":"Ἰάκωβος δὲ πᾶσαν αὐτῷ τὴν αἰτίαν διηγεῖτο λέγων Ἰσάκῳ γενέσθαι παῖδας διδύμους αὐτόν τε καὶ Ἡσαῦν, ὃν ἐπεὶ τῶν τοῦ πατρὸς εὐχῶν διήμαρτε σοφίᾳ τῆς μητρὸς εἰς αὐτὸν γενομένων, ἀποκτεῖναι ζητεῖν αὐτὸν ὡς ἀφῃρημένον τῆς παρὰ τοῦ θεοῦ βασιλείας καὶ ἀγαθῶν ὧν ὁ πατὴρ ηὔξατο."},{"number":296,"text":"ταύτην τε εἶναι τὴν αἰτίαν τῆς ἐνθάδε παρουσίας κατὰ τὴν τῆς μητρὸς ἐντολήν· πᾶσί τε γὰρ ἡμῖν ἀδελφοὶ τυγχάνουσι καὶ πλέον τοῦ κατʼ ἐκείνους συγγενοῦς ἡ μήτηρ προσλαμβάνει. ἔρυμα δὲ τῆς ἐμῆς, φησίν, ἀποδημίας σέ τε καὶ τὸν θεὸν ποιούμενος θαρρῶ τοῖς παροῦσι."},{"number":297,"text":"Λάβανος δὲ καὶ διὰ τοὺς προγόνους ὑπισχνεῖται πάσης αὐτῷ μεταδώσειν φιλανθρωπίας καὶ διὰ τὴν μητέρα, πρὸς ἣν τὴν εὔνοιαν διὰ τῆς περὶ αὐτὸν σπουδῆς ἐνδείξεσθαι καὶ μὴ παρούσης· ποιμνίων τε γὰρ αὐτὸν ἐπιμελητὴν καταστήσειν ἔφασκε καὶ προνομῆς ἀντὶ τούτων ἀξιώσειν, καὶ πρὸς τοὺς ἰδίους ἀπαλλάττεσθαι γονεῖς βουλόμενον μετὰ δώρων ἐπανήξειν καὶ τιμῆς ὅσης εἰκὸς ἦν τυχεῖν τὸν οὕτω συγγενῆ."},{"number":298,"text":"Ἰακώβου δὲ ἀσμένως ταῦτα ἀκούσαντος καὶ φήσαντος ἡδέως πάντα μένων παρʼ αὐτῷ πόνον εἰς ἡδονὴν ὑπομενεῖν τὴν ἐκείνου, μισθὸν δὲ ὑπὲρ τούτου λαβεῖν ἀξιοῦντος τὸν Ῥαχήλας γάμον διά τε τὰ ἄλλα τιμῆς ἀξίας παρʼ αὐτοῦ τυγχάνειν οὔσης, καὶ ὅτι διάκονος τῆς πρὸς αὐτὸν ἀφίξεως γένοιτο· ὁ γὰρ τῆς παιδὸς ἔρως αὐτὸν ἠνάγκασε ποιήσασθαι τοὺς περὶ τούτου λόγους."},{"number":299,"text":"Λάβανος δὲ ἡσθεὶς τούτοις ἐπινεύει τὸν γάμον αὐτῷ τῆς παιδὸς οὐκ ἄλλον ἀμείνω γαμβρὸν εὐξάμενος ἐλθεῖν· εἰ μέντοι παρʼ αὐτῷ μένοι τινὰ χρόνον, τοῦτο ποιήσειν· εἰς γὰρ Χαναναίους οὐκ ἂν πέμψαι τὴν θυγατέρα· μεταμέλειν γὰρ αὐτῷ καὶ τοῦ τῆς ἀδελφῆς κήδους ἐκεῖ συναφθέντος."},{"number":300,"text":"τοῦ δʼ Ἰακώβου τούτοις συγχωροῦντος ἑπτὰ ἐτῶν χρόνον συντίθεται· τοσάδε γὰρ αὐτῷ κέκριται θητεῦσαι τῷ πενθερῷ, ἵνα τῆς ἀρετῆς πεῖραν δοὺς ἐπιγνωσθῇ μᾶλλον τίς εἴη. καὶ προσδεξάμενος τὸν λόγον Λάβανος τοῦ χρόνου διελθόντος προυτίθει τὴν εὐωχίαν τῶν γάμων."},{"number":301,"text":"νυκτὸς δʼ ἐπιγενομένης οὐδὲν προῃσθημένῳ τῷ Ἰακώβῳ παρακατακλίνει τὴν ἑτέραν τῶν θυγατέρων πρεσβυτέραν τε τῆς Ῥαχήλας καὶ τὴν ὄψιν οὐκ εὐπρεπῆ. συνελθὼν δʼ ἐκεῖνος ὑπὸ μέθης καὶ σκότους εἶτα μεθʼ ἡμέραν γνοὺς ἀδικίαν ἐπεκάλει Λαβάνῳ."},{"number":302,"text":"ὁ δὲ συγγνώμην ᾐτεῖτο τῆς ἀνάγκης, ὑφʼ ἧς ταῦτα πράξειεν· οὐ γὰρ κατὰ κακουργίαν αὐτῷ τὴν Λείαν παρασχεῖν, ἀλλʼ ὑφʼ ἑτέρου μείζονος νενικημένον. τοῦτο μέντοι γʼ οὐδὲν ἐμποδίζειν πρὸς τὸν Ῥαχήλας γάμον, ἀλλʼ ἐρῶντι δώσειν ταύτην μετʼ ἄλλην ἑπταετίαν. πείθεται δʼ ὁ Ἰάκωβος, οὐδὲν γὰρ ἕτερον αὐτῷ ποιεῖν ὁ τῆς κόρης ἔρως ἐπέτρεπε, καὶ διελθούσης ἄλλης ἑπταετίας τὴν Ῥαχήλαν παρέλαβεν."},{"number":303,"text":"Ἦσαν δʼ ἑκατέραις θεραπαινίδες τοῦ πατρὸς δόντος Ζελφὰ μὲν Λείας Ῥαχήλας δὲ Βάλλα, δοῦλαι μὲν οὐδαμῶς ὑποτεταγμέναι δέ. καὶ τῆς Λείας ἥπτετο δεινῶς ὁ πρὸς τὴν ἀδελφὴν ἔρως τοῦ ἀνδρὸς προσεδόκα τε παίδων γενομένων ἔσεσθαι τιμία ἱκέτευέ τε τὸν θεὸν διηνεκῶς."},{"number":304,"text":"καὶ γενομένου παιδὸς ἄρρενος καὶ διὰ τοῦτο πρὸς αὐτὴν ἐπεστραμμένου τοῦ ἀνδρὸς Ῥούβηλον ὀνομάζει τὸν υἱόν, διότι κατʼ ἔλεον αὐτῇ τοῦ θεοῦ γένοιτο· τοῦτο γὰρ σημαίνει τὸ ὄνομα. τεκνοῦνται δὲ αὐτοῖς καὶ τρεῖς ἕτεροι μετὰ χρόνον· Σεμεών, ἀποσημαίνει δὲ τὸ ὄνομα τὸ ἐπήκοον αὐτῇ τὸν θεὸν γεγονέναι, εἶτα Λευίς, κοινωνίας οἷον βεβαιωτής, μεθʼ ὃν Ἰούδας, εὐχαριστίαν τοῦτο δηλοῖ."},{"number":305,"text":"Ῥαχήλα δὲ φοβουμένη, μὴ διὰ τὴν εὐτεκνίαν τῆς ἀδελφῆς ἥττονος παρὰ τἀνδρὸς μοίρας τυγχάνῃ, παρακατακλίνει τῷ Ἰακώβῳ τὴν αὑτῆς θεραπαινίδα Βάλλαν. ἐγένετο δὲ παιδίον ἐξ αὐτῆς Δάν, θεόκριτον ἄν τινες εἴποιεν κατὰ τὴν Ἑλλήνων γλῶτταν· καὶ μετʼ αὐτὸν Νεφθάλεις, μηχανητὸς οἷον, διὰ τὸ ἀντιτεχνάσασθαι πρὸς τὴν εὐτεκνίαν τῆς ἀδελφῆς."},{"number":306,"text":"τὸ δʼ αὐτὸ καὶ Λεία ποιεῖ πρὸς τὸ τῆς ἀδελφῆς ἔργον ἀντιτεχνασαμένη· παρακατακλίνει γὰρ τὴν αὑτῆς θεράπαιναν γίνεταί τε καὶ ἐκ τῆς Ζελφῆς υἱὸς Γάδας, τυχαῖον ἄν τις καλέσειεν αὐτόν, καὶ μετʼ αὐτὸν Ἄσηρος, μακαριστὴς λέγοιτʼ ἂν ἐξ ὧν πρὸς εὔκλειαν προσελάμβανε."},{"number":307,"text":"Ῥουβήλου δὲ τοῦ πρεσβυτάτου τῶν υἱῶν Λείας μανδραγόρου μῆλα κομίζοντος τῇ μητρί, Ῥαχήλα θεασαμένη παρακαλεῖ μεταδοῦναι διʼ ἐπιθυμίας τοῦ βρώματος γενομένη. τῆς δʼ οὐ πειθομένης, ἀρκεῖσθαι δʼ αὐτὴν ἀξιούσης, ὅτι τῆς τιμῆς αὐτὴν ἀφέλοιτο τῆς παρὰ τοῦ ἀνδρός, Ῥαχήλα πεπαίνουσα τὸν θυμὸν τῆς ἀδελφῆς παραχωρήσειν αὐτῇ τἀνδρὸς ἔλεγε κοιμησομένου παρʼ αὐτῇ κατʼ ἐκείνην τὴν ἑσπέραν."},{"number":308,"text":"τῆς δὲ προσιεμένης τὴν χάριν Ἰάκωβος συγκαθεύδει τῇ Λείᾳ Ῥαχήλᾳ χαριζόμενος. πάλιν οὖν γίνονται παῖδες αὐτῇ, Ἰσσαχάρης μὲν σημαίνων τὸν ἐκ μισθοῦ γενόμενον, Ζαβουλὼν δὲ ἠνεχυρασμένον εὐνοίᾳ τῇ πρὸς αὐτήν, θυγάτηρ δὲ Δεῖνα. χρόνοις δʼ ὕστερον καὶ Ῥαχήλᾳ γίνεται Ἰώσηπος υἱός· προσθήκην γενησομένου τινὸς δηλοῖ."},{"number":309,"text":"Τοῦτον ἅπαντα τὸν χρόνον, ἔτη δʼ ἐστὶν εἴκοσιν, ἐποίμαινε τῷ πενθερῷ· μετὰ τὸν δʼ ἠξίου τὰς γυναῖκας ἀναλαβὼν ἀπαλλάττεσθαι πρὸς αὑτόν· τοῦ δὲ πενθεροῦ μὴ συγχωροῦντος κρύφα τοῦτο ποιεῖν ἐπενόει."},{"number":310,"text":"τῶν γυναικῶν οὖν ἀπεπειρᾶτο, πῶς ἔχοιεν πρὸς τὴν ἀποδημίαν, τῶν δʼ ἐχουσῶν ἡδέως Ῥαχήλα καὶ τοὺς τύπους τῶν θεῶν, οὓς σέβειν πατρίους ὄντας νόμιμον ἦν, συνανελομένη συναπεδίδρασκε μετὰ τῆς ἀδελφῆς οἵ τε ἑκατέρων παῖδες καὶ αἱ θεραπαινίδες σὺν τοῖς υἱοῖς εἴ τέ τις ἦν κτῆσις αὐταῖς."},{"number":311,"text":"ἐπήγετο δὲ Ἰάκωβος καὶ τῶν βοσκημάτων τὴν ἡμίσειαν Λαβάνου μὴ προεγνωκότος. τοὺς δὲ τύπους ἐπεφέρετο τῶν θεῶν ἡ Ῥαχήλα καταφρονεῖν μὲν τῆς τοιαύτης τιμῆς τῶν θεῶν διδάξαντος αὐτὴν Ἰακώβου, ἵνα δʼ εἰ καταληφθεῖεν ὑπὸ τοῦ πατρὸς αὐτῆς διωχθέντες ἔχοι τούτοις προσφυγοῦσα συγγνώμης τυγχάνειν."},{"number":312,"text":"Λάβανος δὲ μεθʼ ἡμέραν πρώτην γνοὺς τήν τε Ἰακώβου ἀναχώρησιν καὶ τῶν θυγατέρων δεινοπαθῶν ἤλαυνεν ἐπʼ αὐτὸν μετὰ δυνάμεως ἐπειγόμενος, καὶ καθʼ ἑβδόμην ἡμέραν ἐπί τινος λόφου λαμβάνει προκαθιδρυμένους."},{"number":313,"text":"καὶ τότε μέν, ἑσπέρα γὰρ ἦν, ἡσύχαζεν· ὄναρ δὲ ὁ θεὸς ἐπιστὰς αὐτῷ παρῄνεσε λαβόντι τὸν γαμβρὸν καὶ τὰς θυγατέρας ἠρεμεῖν καὶ μηδὲν εἰς αὐτοὺς ὑπὸ θυμοῦ τολμᾶν, σπονδὰς δὲ ποιεῖσθαι πρὸς Ἰάκωβον, αὐτὸς λέγων ἐκείνῳ συμμαχήσειν, εἰ καταφρονήσας αὐτοῦ τῆς ὀλιγότητος χωρήσειεν αὐτῷ διὰ μάχης."},{"number":314,"text":"Λάβανος δὲ τοιαύτης αὐτῷ προρρήσεως γεγενημένης μεθʼ ἡμέραν τὸν Ἰάκωβον εἰς λόγους προκαλεσάμενος καὶ δηλώσας αὐτῷ τὸ ὄναρ, ἐπεὶ πρὸς αὐτὸν ἦλθε πεισθείς, ἤρξατο κατηγορεῖν αὐτοῦ προφέρων, ὅτι καὶ πένητα αὐτὸν ἐλθόντα πρὸς αὐτὸν καὶ πάντων ἄπορον ὑπεδέξατο καὶ παράσχοι πᾶσαν ἀφθονίαν τῆς αὑτοῦ κτήσεως· καὶ γὰρ καὶ θυγατέρας ἐμὰς συνέζευξα τὴν εὔνοιάν σου τὴν πρὸς ἡμᾶς τούτοις αὐξήσεσθαι λογιζόμενος."},{"number":315,"text":"σὺ δὲ οὔτε τῆς μητρὸς τῆς σαυτοῦ καὶ ἧς ἔχεις πρὸς ἐμὲ συγγενείας οὔτε γυναικῶν ἃς ἔγημας αἰδῶ ποιησάμενος, οὐδὲ τέκνων ὧν εἰμι πάππος φροντίσας, ἐχρήσω μοι πολέμου νόμῳ, κτῆσιν μὲν ἄγων τὴν ἐμὴν θυγατέρας δὲ ἀναπείσας ἀποδρᾶναι τὸν γεγεννηκότα,"},{"number":316,"text":"ἱερά τε πάτρια βαστάσας οἴχῃ φερόμενος ὑπό τε τῶν ἐμῶν τιμηθέντα προγόνων καὶ ὑπʼ ἐμοῦ θρησκείας τῆς αὐτῆς ἐκείνοις ἀξιωθέντα· καὶ ταῦτα ἃ μηδὲ οἱ πολεμήσαντες τοὺς ἐχθροὺς ἔδρασαν ὁ συγγενὴς σὺ καὶ τῆς μὲν ἀδελφῆς τῆς ἐμῆς υἱός, θυγατέρων δὲ τῶν ἐμῶν ἀνήρ, ξένος δὲ καὶ ἐφέστιος τῆς ἐμῆς οἰκίας γεγενημένος ἔδρασας."},{"number":317,"text":"ταῦτα εἰπόντος Λαβάνου Ἰάκωβος ἀπελογεῖτο μὴ μόνῳ πατρίδος ἔρωτα τὸν θεόν, ἀλλὰ καὶ πᾶσιν ἐμφῦσαι, καὶ μετὰ τοσοῦτον χρόνον καλῶς ἔχειν αὐτὸν κατελθεῖν εἰς ταύτην."},{"number":318,"text":"ὑπὲρ δὲ τῆς λείας ἧς ἐγκαλεῖς, φησίν, ἀδικῶν αὐτὸς ἂν εὑρεθείης ἐπʼ ἄλλῳ κριτῇ· ὑπὲρ γὰρ ἧς ἐχρῆν σε χάριν ἡμῖν ἔχειν καὶ φυλαχθείσης ὑφʼ ἡμῶν καὶ πλείονος γεγενημένης, ὑπὲρ ταύτης πῶς οὐ διαμαρτάνεις τῶν δικαίων χαλεπαίνων ἐμοί, εἰ μοῖραν αὐτῆς ὀλίγην λαβόντες ἔχομεν. περὶ μέντοι γε τῶν θυγατέρων ἴσθι μὴ κατʼ ἐμὴν κακουργίαν ἀπαναστήσαντος ἀκολουθεῖν, ἀλλὰ κατʼ εὔνοιαν δικαίαν, ἣν γυναιξὶ γαμεταῖς πρὸς τοὺς συνοικοῦντας εἶναι συμβέβηκεν· ἕπονται τοίνυν οὐχ ὡς ἐμοὶ τοσοῦτον, ὅσον τοῖς παισὶν αὐτῶν."},{"number":319,"text":"καὶ ταῦτα μὲν ὑπὲρ τοῦ μηδὲν ἀδικεῖν αὐτὸς ἔλεγε, προσενεκάλει δὲ καὶ κατηγορίαν ἐποιεῖτο, ὅτι μητρὸς ὢν ἀδελφὸς τῆς αὐτοῦ καὶ συζεύξας αὐτῷ τὰς θυγατέρας ἐπιτάγμασιν ἐκτρυχώσειε χαλεποῖς, εἴκοσιν ἐτῶν ἀριθμὸν ἐν αὐτοῖς κατασχών. καὶ τὰ μὲν προφάσει τῶν γάμων ὑπʼ αὐτοῦ γενόμενα καίπερ ὄντα χαλεπὰ κουφότερα ἔφασκε, χείρω δὲ τὰ μετὰ τοὺς γάμους καὶ ἅ τις ἂν ἔπαθεν ἐχθρὸς ἔφυγε."},{"number":320,"text":"καὶ γὰρ σφόδρα κακούργως ὁ Λάβανος ἐχρήσατο τῷ Ἰακώβῳ· ὁρῶν γὰρ αὐτῷ τὸν θεὸν πρὸς ὅτι θελήσειε συλλαμβανόμενον ὑπισχνεῖτο τῶν τεχθησομένων αὐτῷ παρέξειν ἔσθʼ ὅτε μὲν ὅτι καὶ γένοιτο λευκόν, ποτὲ δʼ αὖ τὰ μέλανα τῶν γεννωμένων."},{"number":321,"text":"πληθυόντων δὲ τῶν ἐπʼ ὀνόματι τῷ Ἰακώβου τικτομένων, τὴν μὲν εἰς τὸ παρὸν οὐκ ἐφύλαττε πίστιν, εἰς ἔτος δὲ παρέξειν ἐπηγγέλλετο διὰ τὸ ἐποφθαλμιᾶν τῷ πλήθει τῆς κτήσεως, ἐπαγγελλόμενος μὲν διὰ τὸ δυσέλπιστον γενέσθαι τοσαῦτα, ψευδόμενος δὲ ἐπὶ γενομένοις."},{"number":322,"text":"Περὶ μέντοι τῶν ἱερωμάτων ἐκέλευεν ἔρευναν ποιεῖσθαι· δεξαμένου δὲ Λαβάνου τὴν ἔρευναν Ῥαχήλα πυνθανομένη κατατίθησι τοὺς τύπους εἰς τὴν σάγην τῆς φερούσης αὐτὴν καμήλου· ἐκαθέζετο δὲ φάσκουσα τὴν κατὰ φύσιν κάθαρσιν αὐτῇ ἐνοχλεῖν."},{"number":323,"text":"καὶ Λάβανος μὲν ἀφίσταται τῆς ἐπὶ πλεῖον ἐρεύνης οὐκ ἂν οἰηθεὶς τὴν θυγατέρα μετὰ τοιούτου πάθους τοῖς τύποις προσελθεῖν, ποιεῖται δʼ ὅρκους πρὸς Ἰάκωβον οὐδενὸς αὐτῷ μνησικακήσειν τῶν γενομένων, ἀλλὰ κἀκεῖνος ἀγαπήσειν αὐτοῦ τὰς θυγατέρας."},{"number":324,"text":"καὶ τὰς πίστεις τὰς ἐπὶ τούτοις ἐποιήσαντο ὑπὲρ ὀρῶν τινων, ἐφʼ οἷς στήλην ἀνέθεσαν κατὰ βωμοῦ σχῆμα, ὅθεν Γαλάδην λέγεται βουνός, ἀφʼ οὗ καὶ νῦν Γαλαδηνὴν καλοῦσι τὴν γῆν. ἑστιαθέντων δὲ ἐπὶ τοῖς ὅρκοις ὁ μὲν Λάβανος ἀνέζευξεν."}],"20":[{"number":325,"text":"Ἰακώβῳ δὲ εἰς τὴν Χαναναίαν προϊόντι φαντάσματα συνετύγχανεν ἀγαθὰς ἐλπίδας ὑπαγορεύοντα περὶ τῶν ἐς ὕστερον· καὶ τὸν μὲν τόπον ἐκεῖνον προσαγορεύει θεοῦ στρατόπεδον, βουλόμενος δὲ εἰδέναι, τί ὁ ἀδελφὸς αὐτοῦ φρονεῖ, τοὺς γνωσομένους ἕκαστα μετὰ ἀκριβείας προύπεμψε δεδιὼς αὐτὸν διὰ τὴν προτέραν ὑποψίαν."},{"number":326,"text":"ἐνετέλλετο δὲ τοῖς πεμπομένοις λέγειν πρὸς τὸν Ἡσαῦν, ὅτι νομίσας Ἰάκωβος ἄδικον συνδιαιτᾶσθαι αὐτοῦ τῇ ὀργῇ τῆς χώρας ἑκὼν ὑπεξέλθοι, καὶ νῦν τὸν χρόνον ἱκανὸν ἡγούμενος εἶναι διαλλάκτην ἐπανήκοι γυναῖκάς τε καὶ παῖδας ἐπαγόμενος μετὰ τοῦ πορισθέντος βίου, μετὰ τῶν τιμιωτάτων ἑαυτὸν ἐκείνῳ παραδιδούς, ὅτι κρίνοι μέγιστον ἀγαθὸν τὸ τῷ ἀδελφῷ συμμεταλαμβάνειν τῶν ὑπὸ τοῦ θεοῦ δεδομένων."},{"number":327,"text":"καὶ οἱ μὲν ταῦτα ἐδήλουν, Ἡσαῦς δὲ περιχαρὴς γίνεται καὶ τῷ ἀδελφῷ ὑπήντα σὺν ὁπλίταις τετρακοσίοις. καὶ Ἰάκωβος πυνθανόμενος ἥκειν αὐτὸν ὑπαντησόμενον μετὰ τοσούτων ἦν περίφοβος, τῷ μέντοι θεῷ τὴν ἐλπίδα τῆς σωτηρίας ἐπέτρεπε καὶ πρόνοιαν εἶχεν ἐκ τῶν παρόντων, ὅπως αὐτὸς ἀπαθὴς σώζοι τοὺς σὺν αὑτῷ κρατήσας τῶν ἐχθρῶν εἰ θέλοιεν ἀδικεῖν."},{"number":328,"text":"νείμας οὖν τοὺς σὺν αὑτῷ τοὺς μὲν προύπεμπε, τοὺς δὲ λειπομένους ἆσσον ἐκέλευσεν ἀκολουθεῖν, ὅπως εἰ βιασθεῖεν οἱ προπεμφθέντες ἐπιθεμένου τοῦ ἀδελφοῦ, καταφυγὴν ἔχοιεν τοὺς ἑπομένους."},{"number":329,"text":"καὶ τοῦτον διατάξας τοὺς σὺν αὑτῷ τὸν τρόπον πέμπει τινὰς δῶρα κομίζοντας τἀδελφῷ· ὑποζύγια δὲ ἦν τὰ πεμπόμενα καὶ πλῆθος τετραπόδων ποικίλων, ἃ δὴ τίμια τοῖς ληψομένοις ἔμελλεν ἔσεσθαι παρὰ τὸ σπανίζειν αὐτῶν."},{"number":330,"text":"ἦσαν δὲ οἱ πεμφθέντες ἐκ διαλειμμάτων, ἵνα συνεχέστερον ἐντυγχάνοντες πολλοὶ δοκῶσιν· ἀνήσειν γὰρ ὑπὸ τῶν δωρεῶν τῆς ὀργῆς, εἰ διαμένοι τεθυμωμένος· ἔτι μέντοι καὶ λόγοις χρηστοῖς ὁμιλεῖν πρὸς αὐτὸν εἴρητο τοῖς πεμπομένοις."},{"number":331,"text":"Ταῦτα συνθεὶς διὰ πάσης τῆς ἡμέρας νυκτὸς ἐπιγενομένης ἐκίνει τοὺς σὺν αὑτῷ· καὶ χειμάρρουν τινὰ Ἰάβακχον λεγόμενον διαβεβηκότων Ἰάκωβος ὑπολελειμμένος φαντάσματι συντυχὼν διεπάλαιεν ἐκείνου προκατάρχοντος τῆς μάχης ἐκράτει τε τοῦ φαντάσματος,"},{"number":332,"text":"ὃ δὴ καὶ φωνῇ χρῆται καὶ λόγοις πρὸς αὐτὸν χαίρειν τε τοῖς γεγενημένοις παραινοῦν καὶ μὴ μικρὸν κρατεῖν ὑπολαμβάνειν, ἀλλὰ θεῖον ἄγγελον νενικηκέναι καὶ σημεῖον ἡγεῖσθαι τοῦτο μεγάλων ἀγαθῶν ἐσομένων καὶ τοῦ μηδέποτε τὸ γένος ἐκλείψειν αὐτοῦ, μηδὲ ὑπέρτερον ἀνθρώπων τινὰ τῆς ἰσχύος ἔσεσθαι τῆς ἐκείνου."},{"number":333,"text":"ἐκέλευσέ τε καλεῖν αὐτὸν Ἰσραῆλον, σημαίνει δὲ τοῦτο κατὰ τὴν Ἑβραίων γλῶτταν τὸν ἀντιστάτην ἀγγέλῳ θεοῦ. ταῦτα μέντοι προύλεγεν Ἰακώβου δεηθέντος· αἰσθόμενος γὰρ ἄγγελον εἶναι θεοῦ, τίνα μοῖραν ἕξει σημαίνειν παρεκάλει. καὶ τὸ μὲν φάντασμα ταῦτʼ εἰπὸν ἀφανὲς γίνεται."},{"number":334,"text":"ἡσθεὶς δὲ τούτοις Ἰάκωβος Φανουῆλον ὀνομάζει τὸν τόπον, ὃ σημαίνει θεοῦ πρόσωπον. καὶ γενομένου διὰ τὴν μάχην ἀλγήματος αὐτῷ περὶ τὸ νεῦρον τὸ πλατὺ αὐτός τε ἀπέχεται τῆς τούτου βρώσεως καὶ διʼ ἐκεῖνον οὐδὲ ἡμῖν ἐστιν ἐδώδιμον."},{"number":335,"text":"Πλησίον δʼ ἤδη τὸν ἀδελφὸν πυνθανόμενος κελεύει προϊέναι τῶν γυναικῶν ἑκατέραν κατʼ αὐτὴν μετὰ τῶν θεραπαινίδων, ἵνα πόρρωθεν ἀφορῷεν τὰ ἔργα τῶν ἀνδρῶν μαχομένων, εἰ τοῦτο θελήσειεν Ἡσαῦς, προσεκύνει δʼ αὐτὸς τὸν ἀδελφὸν ἐγγὺς αὐτῷ γενόμενον οὐδὲν περὶ αὐτοῦ δόλιον φρονοῦντα."},{"number":336,"text":"καὶ ὁ Ἡσαῦς ἀσπασάμενος αὐτὸν ἀνήρετο τῶν παίδων τὸν ὄχλον καὶ τὰς γυναῖκας, ἠξίου τε τότε μαθὼν περὶ αὐτῶν τὸ πᾶν καὶ αὐτὸς συμβαδίζειν αὐτοῖς πρὸς τὸν πατέρα, Ἰακώβου δὲ προφασιζομένου τὸν κόπον τῶν ὑποζυγίων ὑπεχώρησεν εἰς Σάειραν· ἐνταῦθα γὰρ ἐποιεῖτο τὴν δίαιταν προσαγορεύσας τὸ χωρίον ἀπὸ τῆς αὑτοῦ τριχώσεως δασεῖαν."}],"21":[{"number":337,"text":"Ἰάκωβος δὲ ἀφίκετο εἰς τὰς ἔτι νῦν Σκηνὰς λεγομένας, ὅθεν εἰς Σίκιμον παρῆν· Χαναναίων δʼ ἐστὶν ἡ πόλις. τῶν δὲ Σικιμωτῶν ἑορτὴν ἀγόντων Δεῖνα, θυγάτηρ ἦν Ἰακώβου μόνη, παρῆλθεν εἰς τὴν πόλιν ὀψομένη τὸν κόσμον τῶν ἐπιχωρίων γυναικῶν. θεασάμενος δʼ αὐτὴν Συχέμμης ὁ Ἐμμώρου τοῦ βασιλέως υἱὸς φθείρει διʼ ἁρπαγῆς καὶ διατεθεὶς ἐρωτικῶς ἱκετεύει τὸν πατέρα λαβεῖν αὐτῷ πρὸς γάμον τὴν κόρην."},{"number":338,"text":"ὁ δὲ πεισθεὶς ἧκε πρὸς τὸν Ἰάκωβον δεόμενος τῷ παιδὶ αὐτοῦ Συχέμμῃ συζεῦξαι Δεῖναν κατὰ νόμον. Ἰάκωβος δὲ οὔτʼ ἀντιλέγειν ἔχων διὰ τὸ ἀξίωμα τοῦ παρακαλοῦντος οὔτε νόμιμον ἡγούμενος ἀλλοφύλῳ συνοικίζειν τὴν θυγατέρα ἠξίωσεν ἐπιτρέψαι αὐτῷ βουλὴν ἀγαγεῖν περὶ ὧν παρακαλεῖ."},{"number":339,"text":"ἀπῄει μὲν οὖν ὁ βασιλεὺς ἐλπίζων Ἰάκωβον παρέξειν τὸν γάμον, Ἰάκωβος δὲ τοῖς παισὶ δηλώσας τήν τε φθορὰν τῆς ἀδελφῆς καὶ τοῦ Ἐμμώρου τὴν δέησιν ἠξίου βουλεύεσθαι τί δεῖ ποιεῖν. οἱ μὲν οὖν πλείους ἡσύχαζον γνώμης ἀποροῦντες, Σεμεὼν δὲ καὶ Λευὶς ὁμομήτριοι τῆς κόρης ἀδελφοὶ συντίθενται πρὸς ἀλλήλους τοιάνδε τινὰ πρᾶξιν·"},{"number":340,"text":"οὔσης ἑορτῆς καὶ τῶν Σικιμιωτῶν εἰς ἄνεσιν καὶ εὐωχίαν τετραμμένων νύκτωρ πρώτοις ἐπιβαλόντες τοῖς φύλαξι κτείνουσι κοιμωμένους καὶ παρελθόντες εἰς τὴν πόλιν ἀναιροῦσι πᾶν ἄρρεν καὶ τὸν βασιλέα σὺν αὐτοῖς καὶ τὸν υἱὸν αὐτοῦ, φείδονται δὲ τῶν γυναικῶν. πράξαντες δὲ ταῦτα δίχα τῆς τοῦ πατρὸς γνώμης ἐπανάγουσι τὴν ἀδελφήν."},{"number":341,"text":"Ἰακώβῳ δὲ ἐκπλαγέντι πρὸς τὸ μέγεθος τῶν γεγονότων καὶ χαλεπαίνοντι πρὸς τοὺς υἱοὺς ὁ θεὸς παραστὰς ἐκέλευσε θαρρεῖν, ἁγνίσαντι δὲ τὰς σκηνὰς θυσίας ἐπιτελεῖν, ἃς τὸ πρῶτον ἀπιὼν εἰς τὴν Μεσοποταμίαν ἐπὶ τῇ ὄψει τοῦ ὀνείρου ηὔξατο."},{"number":342,"text":"ἁγνίζων οὖν τοὺς ἑπομένους ἐπιτυγχάνει τοῖς Λαβάνου θεοῖς, οὐ γὰρ ἠπίστατο ὑπὸ τῆς Ῥαχήλης κλαπέντας, καὶ αὐτοὺς ἔκρυψεν ἐν Σικίμοις εἰς γῆν ὑπό τινα δρῦν, ἀπάρας τε τοὐντεῦθεν ἐν Βαιθήλοις ἔθυεν, ὅπου τὸ ὄνειρον ἐθεάσατο χωρῶν πρότερον ἐπὶ τῆς Μεσοποταμίας."},{"number":343,"text":"Ἐντεῦθεν δὲ προϊὼν ἐπεὶ κατὰ τὴν Ἐφραθηνὴν γίνεται, ἐνθάδε Ῥαχήλαν ἐκ τοκετοῦ θανοῦσαν θάπτει μόνην τῶν συγγενῶν τῆς ἐν Νεβρῶνι τιμῆς οὐ τυχοῦσαν. πενθήσας δὲ μεγάλως τὸ ἐξ αὐτῆς παιδίον Βενιαμὶν ἐκάλεσε διὰ τὴν ἐπʼ αὐτῷ γενομένην ὀδύνην τῇ μητρί."},{"number":344,"text":"οὗτοι Ἰακώβου παῖδες οἱ πάντες, ἄρρενες μὲν δώδεκα θήλεια δὲ μία. τούτων ὀκτὼ γνήσιοι, ἐκ Λείας μὲν ἕξ, δύο δὲ ἐκ Ῥαχήλης, τέσσαρες δὲ ἐκ τῶν θεραπαινίδων δύο ἐξ ἑκατέρας, ὧν καὶ τὰ ὀνόματα πάντων προεῖπον."}],"22":[{"number":345,"text":"Παρῆν δʼ ἐντεῦθεν ἐπὶ Νεβρῶνα πόλιν ἐν Χαναναίοις κειμένην· ἐκεῖ δὲ Ἴσακος τὴν δίαιταν εἶχε· καὶ βραχέα μὲν ἀλλήλοις συνδιατρίβουσι· τὴν γὰρ Ῥεβέκκαν Ἰάκωβος οὐ κατέλαβε ζῶσαν. θνήσκει δὲ καὶ Ἴσακος οὐ μετὰ πολὺ τῆς ἀφίξεως τοῦ υἱοῦ καὶ ταφῆς ἔτυχεν ὑπὸ τῶν παίδων σὺν τῇ γυναικὶ ἐν Νεβρῶνι μνημείου προγονικοῦ ἐν αὐτῇ τυγχάνοντος αὐτοῖς."},{"number":346,"text":"ἐγένετο δὲ Ἴσακος ἀνὴρ θεοφιλὴς καὶ προνοίας πολλῆς ἠξιωμένος ὑπʼ αὐτοῦ μετὰ Ἅβραμον τὸν πατέρα, πολυχρονιώτατος δέ· βιώσας γὰρ ἔτη πέντε καὶ ὀγδοήκοντα πρὸς τοῖς ἑκατὸν μετὰ ἀρετῆς οὕτως ἀπέθανεν."}]},"count":346};a[2]={"book":2,"title":"Τάδε ἔνεστιν ἐν τῇ β τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"α. Ὡς Ἡσαῦς καὶ Ἰάκωβος Ἰσάκου παῖδες ὄντες, διείλοντο τὴν οἴκησιν καὶ Ἡσαῦς μὲν τὴν Ἰδουμαίαν κατέσχεν, Ἰάκωβος δὲ τὴν Χαναναίαν.\n\nβ. ὡς Ἰώσηπος ὁ νεώτατος τῶν Ἰακώβου παίδων ὀνειράτων αὐτῷ προδεικνύντων τὴν μέλλουσαν εὐδαιμονίαν ὑπὸ τῶν ἀδελφῶν ἐφθονήθη.\n\nγ. ὡς αὐτὸς οὗτος εἰς Αἴγυπτον πραθεὶς ὑπὸ τῶν ἀδελφῶν διὰ τὸ πρὸς αὐτὸν μῖσος καὶ γενόμενος ἐπίσημος ἐκεῖ καὶ λαμπρότατος τοὺς ἀδελφοὺς ἔσχεν ὑποχειρίους.\n\nδ. ἡ τοῦ πατρὸς αὐτοῦ μετὰ τῆς γενεᾶς πάσης πρὸς αὐτὸν μετάβασις διὰ τὸν γενόμενον λιμόν.\n\nε. ὅσα τοῖς Ἑβραίοις ἐν Αἰγύπτῳ συνέβη κακοπαθοῦσιν ἐπ' ἔτη τετρακόσια.\n\nϛ. ὡς Μωσέως ἡγουμένου τὴν Αἴγυπτον ἐξέλιπον.\n\nζ. ἡ Μωσέως γένεσις καὶ ἀνατροφή.\n\nη. ὡς ἡ θάλασσα τοῖς Ἑβραίοις διωκομένοις ὑπὸ τῶν Αἰγυπτίων ἀνακοπεῖσα φυγὴν δι' αὐτῆς παρέσχεν.\n\nπεριέχει δὲ ἡ βίβλος ἔτη διακόσια εἴκοσι."},"chapters":{"1":[{"number":1,"text":"Μετὰ δὲ τὴν Ἰσάκου τελευτὴν οἱ παῖδες αὐτοῦ μερισάμενοι τὴν οἴκησιν πρὸς ἀλλήλους οὐχ ἣν ἔλαβον ταύτην κατέσχον, ἀλλʼ Ἡσαῦς μὲν τῆς Νεβρωνίας πόλεως ἐκχωρήσας τῷ ἀδελφῷ ἐν Σαειρᾷ διητᾶτο καὶ τῆς Ἰδουμαίας ἦρχεν οὕτω καλέσας τὴν χώραν ἀπʼ αὐτοῦ· Ἄδωμος γὰρ ἐπωνομάζετο κατὰ τοιαύτην αἰτίαν τυχὼν τῆς ἐπικλήσεως."},{"number":2,"text":"ἀπὸ θήρας ποτὲ καὶ πόνου τοῦ περὶ τὸ κυνήγιον λιμώττων ἐπανῆκεν, ἔτι δὲ ἦν παῖς τὴν ἡλικίαν, ἐπιτυχὼν δὲ τἀδελφῷ φακῆν ἐσκευακότι πρὸς ἄριστον αὑτῷ ξανθὴν σφόδρα τὴν χροιὰν καὶ διὰ τοῦτʼ ἔτι μᾶλλον ὀρεχθεὶς ἠξίου παρασχεῖν αὐτῷ πρὸς τροφήν."},{"number":3,"text":"ὁ δὲ ἀποδόσθαι τὸ πρεσβεῖον αὐτῷ τοῦ φαγεῖν συνεργῷ χρησάμενος τῇ πείνῃ τὸν ἀδελφὸν ἠνάγκαζε, κἀκεῖνος ὑπὸ τοῦ λιμοῦ προαχθεὶς παραχωρεῖ τῶν πρεσβείων αὐτῷ μεθʼ ὅρκων. ἔνθεν διὰ τὴν ξανθότητα τοῦ βρώματος ὑπὸ τῶν ἡλικιωτῶν κατὰ παιδιὰν Ἄδωμος ἐπικληθείς, ἄδωμα γὰρ Ἑβραῖοι τὸ ἐρυθρὸν καλοῦσι, τὴν χώραν οὕτως προσηγόρευσεν· Ἕλληνες γὰρ αὐτὴν ἐπὶ τὸ σεμνότερον Ἰδουμαίαν ὠνόμασαν."},{"number":4,"text":"Γίνεται δὲ καὶ πατὴρ παίδων πέντε τὸν ἀριθμόν, ὧν Ἰάους μὲν καὶ Ἰόλαμος καὶ Κορῆος ἐκ γυναικὸς μιᾶς Ἀλιβάμης τοὔνομα, τῶν δὲ λοιπῶν Ἀλιφάζης μὲν ἐξ Ἀδάσης, Ῥαουῆλος δὲ ἐκ Βασαμάθης ὑπῆρξαν αὐτῷ γεγονότες."},{"number":5,"text":"καὶ Ἡσαῦ μὲν οὗτοι παῖδες ἦσαν· Ἀλιφάζῃ δὲ γίνονται γνήσιοι πέντε Θημανὸς Ὄμερος Ὄφους Ἰόθαμος Καναζός· Ἀμαλῆκος γὰρ νόθος ἦν ἐκ παλλακῆς αὐτῷ γεγονὼς Θαμνάης ὄνομα."},{"number":6,"text":"οὗτοι κατῴκησαν τῆς Ἰδουμαίας τὴν Γοβολῖτιν λεγομένην καὶ τὴν ἀπὸ Ἀμαλήκου κληθεῖσαν Ἀμαληκῖτιν· πολλὴ γὰρ γενομένη ποτὲ ἡ Ἰδουμαία τό τε πάσης αὐτῆς ἀπέσωζεν ὄνομα καὶ τοῖς μέρεσι τὰς ἀπὸ τῶν οἰκητόρων προσηγορίας διεφύλαξεν."}],"2":[{"number":7,"text":"Ἰακώβῳ δὲ συνέβη παρελθεῖν εἰς εὐδαιμονίας μέγεθος, οἷον οὐκ ἄλλῳ τινὶ ῥᾳδίως· πλούτῳ τε γὰρ ὑπερέβαλλε τοὺς ἐπιχωρίους καὶ παίδων ἀρεταῖς ζηλωτὸς καὶ περίβλεπτος ἦν· οὐδενὸς γὰρ ὅλως ὑστέρουν, ἀλλὰ καὶ πρὸς ἔργα χειρῶν καὶ πόνων ὑπομονὴν ἦσαν εὔψυχοι καὶ δεινοὶ συνιέναι."},{"number":8,"text":"τοσαύτην δʼ ἄρα τὸ θεῖον αὐτοῦ πρόνοιαν ἔσχε καὶ τῆς εὐδαιμονίας ἐπιμέλειαν, ὡς κἀκ τῶν λυπηρῶν αὐτῷ δοξάντων τὴν ὑπερβολὴν τῶν ἀγαθῶν παρασχεῖν καὶ ποιῆσαι τῆς ἀπʼ Αἰγύπτου τῶν ἡμετέρων προγόνων ἀναχωρήσεως αἴτιον αὐτόν τε καὶ τοὺς ἐξ αὐτοῦ γεγονότας ὑπὸ τοιαύτης αἰτίας·"},{"number":9,"text":"Ἰώσηπον ἐκ Ῥαχήλας πεπαιδοποιημένος Ἰάκωβος διά τε τὴν τοῦ σώματος εὐγένειαν καὶ διὰ ψυχῆς ἀρετήν, φρονήσει γὰρ διέφερε, τῶν ἄλλων πλέον υἱῶν ἠγάπα."},{"number":10,"text":"τούτῳ παρὰ τῶν ἀδελφῶν ἥ τε τοῦ πατρὸς στοργὴ φθόνον ἐκίνησε καὶ μῖσος ἥ τε ἐκ τῶν ὀνειράτων, ἃ θεασάμενος τῷ τε πατρὶ καὶ τούτοις ἐμήνυσεν, εὐδαιμονία καταγγελλομένη, ζηλοτυπούντων ἄρα τῶν ἀνθρώπων καὶ τὰς τῶν οἰκειοτάτων εὐπραγίας. αἱ δὲ ὄψεις, ἃς κατὰ τοὺς ὕπνους εἶδεν Ἰώσηπος, τοιαίδε ἦσαν."},{"number":11,"text":"Ἐκπεμφθεὶς μετὰ τῶν ἀδελφῶν παρὰ τοῦ πατρὸς ἐπὶ συλλογῇ τῶν καρπῶν θέρους ἀκμάζοντος ὁρᾷ πολὺ τῶν κατὰ συνήθειαν ἐπιφοιτώντων κατὰ τοὺς ὕπνους ὀνειράτων διαφέρουσαν ὄψιν, ἣν περιεγερθεὶς τοῖς ἀδελφοῖς ὡς κρινοῦσιν αὐτῷ τὸ σημαινόμενον ἐξέθετο, λέγων ἰδεῖν ἐπὶ τῆς παρελθούσης νυκτὸς τὸ μὲν αὐτοῦ δράγμα τῶν πυρῶν ἠρεμεῖν ἐφʼ οὗ κατέθηκε τόπου, τὰ δὲ ἐκείνων προστρέχοντα προσκυνεῖν αὐτὸ καθάπερ οἱ δοῦλοι τοὺς δεσπότας."},{"number":12,"text":"οἱ δὲ συνέντες ἰσχὺν αὐτῷ καὶ μέγεθος πραγμάτων τὴν ὄψιν προλέγουσαν καὶ κατʼ αὐτῶν τὴν ἐξουσίαν ἐσομένην τῷ μὲν Ἰωσήπῳ τούτων οὐδὲν ὡς οὐ γνώριμον αὐτοῖς τὸ ὄναρ ὂν διεσάφησαν, ἀρὰς δʼ ἐποιήσαντο μηδὲν εἰς τέλος αὐτῷ παρελθεῖν ὧν ὑπενόουν καὶ πρὸς αὐτὸν ἔτι μᾶλλον ἀπεχθῶς ἔχοντες διετέλουν."},{"number":13,"text":"Τῷ δὲ παρʼ αὐτῶν φθόνῳ προσφιλονικῆσαν τὸ θεῖον δευτέραν ὄψιν ἐπιπέμπει τῷ Ἰωσήπῳ πολὺ τῆς προτέρας θαυμασιωτέραν. τὸν ἥλιον γὰρ ἔδοξε τὴν σελήνην παραλαβόντα καὶ τοὺς λοιποὺς ἀστέρας ἐπὶ τὴν γῆν κατελθεῖν καὶ προσκυνεῖν αὐτόν."},{"number":14,"text":"ταύτην τὴν ὄψιν τῷ πατρὶ μηδὲν παρὰ τῶν ἀδελφῶν κακόηθες ὑφορώμενος καὶ τούτων παρατυγχανόντων διεσάφησε, τί καὶ βούλεται σημαίνειν φράσαι παρακαλῶν."},{"number":15,"text":"ὁ δὲ ἡσθεὶς τῷ ὀνείρατι, τὴν γὰρ πρόρρησιν αὐτοῦ τῇ διανοίᾳ συλλαβὼν καὶ μετὰ σοφίας οὐκ ἀσκόπως εἰκάσας ἔχαιρεν ἐπὶ μεγάλοις τοῖς σημαινομένοις, ἃ εὐδαιμονίαν τῷ παιδὶ κατήγγελλε καὶ καιρὸν ἥξειν θεοῦ δόντος, καθʼ ὃν αὐτὸν ὑπό τε τῶν γονέων καὶ τῶν ἀδελφῶν ἔσεσθαι τίμιον καὶ προσκυνήσεως ἄξιον,"},{"number":16,"text":"τὴν μὲν σελήνην καὶ τὸν ἥλιον μητρὶ καὶ πατρί, τῆς μὲν αὐξούσης ἅπαντα καὶ τρεφούσης τοῦ δʼ ἐκτυποῦντος καὶ τὴν ἄλλην ἰσχὺν ἐντιθέντος εἰκάζων, τοὺς δʼ ἀστέρας τοῖς ἀδελφοῖς· καὶ γὰρ τούτους ἕνδεκα εἶναι καθάπερ καὶ τοὺς ἀστέρας ἀπό τε ἡλίου καὶ σελήνης τὴν ἰσχὺν λαμβάνοντας."},{"number":17,"text":"Καὶ ὁ μὲν Ἰάκωβος τοιαύτην οὐκ ἀσυνέτως ἐποιήσατο τῆς ὄψεως τὴν κρίσιν, τοὺς δʼ ἀδελφοὺς τοῦ Ἰωσήπου σφόδρα ἐλύπησε τὰ προειρημένα καὶ διετέθησαν ὡς ἐπʼ ἀλλοτρίῳ τινὶ μέλλοντι τὰ σημαινόμενα διὰ τῶν ὀνειράτων ἀγαθὰ ἕξειν, ἀλλʼ οὐκ ἀδελφῷ καὶ ὧν συναπολαύσειν αὐτῷ εἰκὸς ἦν κοινωνοὺς ὡς τῆς γενέσεως οὕτως καὶ τῆς εὐδαιμονίας ἐσομένους·"},{"number":18,"text":"ἀνελεῖν τε ὡρμήκεσαν τὸ μειράκιον, καὶ ταύτην κυρώσαντες τὴν βουλήν, ἐπεὶ τὰ τῆς συγκομιδῆς αὐτοῖς πέρας εἶχεν, ἐπὶ Σικίμων τραπέντες, χώρα δʼ ἐστὶν αὕτη βόσκειν ἀγαθὴ θρέμματα καὶ νομὰς ἐκφέρειν, αὐτόθι τῶν ποιμνίων ἐπεμελοῦντο μὴ προδηλώσαντες τῷ πατρὶ τὴν ἐκεῖσε ἄφιξιν."},{"number":19,"text":"ὁ δὲ ὑπὸ τῆς ἀγνοίας καὶ τοῦ μηδὲ ἀπὸ τῶν ποιμνίων πρὸς αὐτὸν ἀφικέσθαι τινὰ τὸν περὶ τῶν παίδων αὐτῷ τἀληθὲς σημαίνειν δυνάμενον, σκυθρωπότερον τὴν περὶ αὐτῶν διάνοιαν λαμβάνων καὶ περιδεὴς ὢν πέμπει τὸν Ἰώσηπον εἰς τὰ ποίμνια μαθησόμενον τὰ περὶ τῶν ἀδελφῶν καὶ τί πράττοιεν σημανοῦντα."}],"3":[{"number":20,"text":"Οἱ δὲ τὸν ἀδελφὸν ὡς εἶδον πρὸς αὐτοὺς ἀφιγμένον, ἥσθησαν μέν, ἀλλʼ οὐχ ὡς ἐπʼ οἰκείου παρουσίᾳ καὶ πατρὸς ἀπεσταλκότος, ἀλλʼ ὡς ἐπʼ ἐχθροῦ καὶ ταῖς χερσὶν αὐτῶν κατὰ θείαν βούλησιν παραδοθέντος, ἀναιρεῖν τε ἤδη καὶ μὴ τὸν ἐν ποσὶν ὑπερβαλέσθαι καιρὸν ὡρμήκεσαν."},{"number":21,"text":"οὕτως δʼ αὐτοὺς Ῥουβῆλος ὁρῶν ἔχοντας ὁ πρεσβύτατος αὐτῶν καὶ πρὸς τὴν πρᾶξιν ὡμονοηκότας ἐπειρᾶτο κατέχειν ὑποδεικνὺς τὸ μέγεθος τοῦ τολμήματος καὶ τὸ ἐπʼ αὐτῷ μύσος,"},{"number":22,"text":"ὡς πονηρὸν μὲν καὶ θεῷ καὶ ἀνθρώποις ἀνόσιον δοκοῦν καὶ τὸ μὴ συγγενοῦς ἀνθρώπου χειρουργῆσαι φόνον, πολὺ μέντοι μιαρώτερον τὸ σφαγὴν ἀδελφοῦ δράσαντας ὀφθῆναι, ᾧ πατήρ τε ἀναιρουμένῳ συναδικεῖται καὶ μήτηρ εἰς πένθος καὶ παιδὸς ἀποστέρησιν οὐ κατʼ ἀνθρώπινον γενομένην νόμον συγκατασπᾶται."},{"number":23,"text":"τούτων οὖν αὐτῶν αἰδῶ λαβόντας καὶ τῷ λογισμῷ τί καὶ πείσονται τεθνηκότος αὐτοῖς παιδὸς ἀγαθοῦ καὶ νεωτάτου παραθεμένους ἀποσχέσθαι τοῦ τολμήματος παρεκάλει καὶ τὸν θεὸν δείσαντας, ὃς θεατὴς ἅμα καὶ μάρτυς ἤδη καὶ τῆς βουλῆς αὐτῶν τῆς ἐπὶ τὸν ἀδελφὸν γεγενημένος ἀποστάντας μὲν τῆς πράξεως ἀγαπήσει μετανοίᾳ καὶ τῷ σωφρονεῖν εἴξαντας,"},{"number":24,"text":"προελθόντας δʼ ἐπὶ τοὖργον οὐκ ἔστιν ἣν οὐκ εἰσπράξεται τῆς ἀδελφοκτονίας δίκην μιάναντας αὐτοῦ τὴν πανταχοῦ παροῦσαν πρόνοιαν καὶ μήτε τῶν ἐπʼ ἐρημίᾳ πραττομένων ὑστεροῦσαν μήτε τῶν κατὰ τὰς πόλεις· ὅπου γὰρ ἂν ἄνθρωπος ᾖ χρὴ δοκεῖν ἐνταῦθα παρεῖναι καὶ θεόν."},{"number":25,"text":"τό τε συνειδὸς αὐτοὺς τὸ ἴδιον ἕξειν ἐχθρὸν ἐπὶ τοῖς τολμηθεῖσιν ἔλεγεν, ὃ μήτε τοῖς ἀγαθὸν αὐτὸ ἔχουσι μήτε τοιοῦτον ὁποῖον αὐτοῖς συνοικήσει τὸν ἀδελφὸν ἀνελοῦσιν ἔστιν ἀποδράναι."},{"number":26,"text":"προσετίθει δὲ καὶ ταῦτα τοῖς προειρημένοις, ὡς ἀδελφὸν οὐδὲ ἀδικήσαντα κτείνειν ὅσιον, καλὸν δὲ καὶ τὸ μὴ μνησικακεῖν τοῖς οὕτω φίλοις ὑπὲρ ὧν ἁμαρτεῖν ἔδοξαν. Ἰώσηπον δὲ οὐδὲ πονηρὸν εἰς αὐτοὺς γεγενημένον διαφθεροῦσιν, ᾧ τὸ τῆς ἡλικίας ἀσθενὲς ἔλεον μᾶλλον καὶ τὴν παρʼ ἡμῶν ἐρανίζεται κηδεμονίαν·"},{"number":27,"text":"ἥ τε αἰτία τῆς ἀναιρέσεως πολὺ χείρω τὴν πρᾶξιν αὐτοῖς τίθησι, διὰ φθόνον τῶν ἐσομένων ἀγαθῶν αὐτῷ τοῦ ζῆν ἐξαγαγεῖν διεγνωκότων, ὧν τὸ ἴσον ἀπολαύσουσι κοινωνοῦντες αὐτῷ τῆς μετουσίας οὐκ ἀλλοτρίων ὄντων ἀλλʼ οἰκείων·"},{"number":28,"text":"ἴδια γὰρ αὐτῶν ὑπολαμβάνειν, ὅσα ὁ θεὸς Ἰωσήπῳ δώσει, προσεκίνουν τὴν ὀργὴν καὶ διὰ τοῦτο καλῶς ἔχειν χαλεπωτέραν ἔσεσθαι νομίζειν, εἰ τὸν ὑπʼ αὐτοῦ κεκριμένον τῶν ἐλπιζομένων ἀγαθῶν ἄξιον ἀποκτείναντες ἀφαιρήσονται τὸν θεὸν ᾧ ταῦτα χαρίσεται."},{"number":29,"text":"Καὶ ὁ μὲν Ῥουβῆλος ταῦτα λέγων καὶ πρὸς τούτοις ἔτι πλείω καὶ δεόμενος ἐπειρᾶτο τῆς ἀδελφοκτονίας αὐτοὺς ἀποτρέπειν, ἐπεὶ δὲ οὐδὲν μετριωτέρους ὑπὸ τῶν λόγων ἑώρα γεγενημένους, ἀλλὰ σπεύδοντας ἐπὶ τὴν ἀναίρεσιν, συνεβούλευε τὸ κακὸν αὐτοὺς ἐπιεικέστερον ποιῆσαι τῷ τρόπῳ τῆς ἀναιρέσεως·"},{"number":30,"text":"καὶ γὰρ ἄμεινον μὲν οἷς παρῄνεσε τὸ πρῶτον πεπεῖσθαι λέγων αὐτούς, ἐπεὶ δʼ ἐκράτησαν ὥστε ἀνελεῖν τὸν ἀδελφόν, οὐκ ἔσεσθαι σφόδρα κακοὺς οἷς νῦν παραινεῖ πεισθέντας· ἐν γὰρ τούτοις εἶναι καὶ τὸ ἔργον, ἐφʼ ᾧ σπεύδουσιν, οὐ μέντοι τοιοῦτον, ἀλλʼ ὡς ἐν ἀπόροις κουφότερον."},{"number":31,"text":"ἠξίου γὰρ αὐτοὺς αὐτόχειρας μὲν μὴ γενέσθαι τἀδελφοῦ, ῥίψαντας δὲ εἰς τὸν παρακείμενον λάκκον οὕτως ἀποθανεῖν ἐᾶσαι καὶ τό γε μὴ μιανθῆναι τὰς χεῖρας αὐτῶν κερδαίνειν. συναινεσάντων δὲ τούτοις τῶν νεανίσκων παραλαβὼν ὁ Ῥουβῆλος τὸ μειράκιον καὶ καλωδίου ἐκδήσας ἠρέμα καθίησιν εἰς τὸν λάκκον· καὶ γὰρ ἱκανῶς ἄνυδρος ἦν. καὶ ὁ μὲν τοῦτο ποιήσας ἀπαλλάσσεται κατὰ ζήτησιν χωρίων πρὸς νομὰς ἐπιτηδείων."},{"number":32,"text":"Ἰούδας δὲ καὶ αὐτὸς ὢν τῶν Ἰακώβου παίδων ἐμπόρους ἰδὼν Ἄραβας τοῦ Ἰσμαηλιτῶν γένους ἀρώματα καὶ Σύρα φορτία κομίζοντας Αἰγυπτίοις ἐκ τῆς Γαλαδηνῆς μετὰ τὴν ἀναχώρησιν τὴν Ῥουβήλου τοῖς ἀδελφοῖς συνεβούλευεν ἀνιμήσασι τὸν Ἰώσηπον ἀπεμπολῆσαι τοῖς Ἄραψιν·"},{"number":33,"text":"ἐκεῖνόν τε γὰρ ὅτι πορρωτάτω γενόμενον καὶ τεθνήξεσθαι παρὰ τοῖς ξένοις, αὐτούς τε τοῦ μιάσματος οὕτως ἀπαλλαγήσεσθαι. δόξαν οὖν τοῦτο, τοῖς ἐμπόροις ἀποδίδονται τὸν Ἰώσηπον ἀνελκύσαντες ἐκ τοῦ λάκκου μνῶν εἴκοσιν ἑπτακαίδεκα ἐτῶν γεγονότα."},{"number":34,"text":"Ῥουβῆλος δὲ νύκτωρ ἐπὶ τὸν λάκκον ἐλθὼν σῶσαι τοὺς ἀδελφοὺς λαθὼν τὸν Ἰώσηπον ἐγνώκει, καὶ ὡς ἀνακαλουμένῳ μὴ ὑπήκουσε, δείσας μὴ ἐφθάρκασιν αὐτὸν μετὰ τὴν ἀναχώρησιν αὐτοῦ κατεμέμφετο τοὺς ἀδελφούς. τῶν δὲ τὸ πραχθὲν αὐτῷ φρασάντων παύεται τοῦ πένθους Ῥουβῆλος."},{"number":35,"text":"Ὡς δὲ ταῦτα περὶ τὸν Ἰώσηπον τοῖς ἀδελφοῖς ἐπέπρακτο, τί ποιήσαντες ἂν ἔξω τῆς ὑπονοίας παρὰ τῷ πατρὶ γενηθεῖεν ἐζήτουν, καὶ δὴ τὸν χιτωνίσκον, ὃν ἀφῖκτο μὲν πρὸς αὐτοὺς ὁ Ἰώσηπος ἐνδεδυμένος, περιῃρήκεσαν δʼ αὐτὸν ὅτε καθίεσαν εἰς τὸν λάκκον, ἔδοξεν αὐτοῖς διασπαράξασιν αἵματι τράγου μολῦναι καὶ τῷ πατρὶ δεῖξαι φέροντας, ὡς ἂν ὑπὸ θηρίων αὐτῷ φανείη διεφθαρμένος."},{"number":36,"text":"καὶ τοῦτο ποιήσαντες ἧκον πρὸς τὸν πρεσβύτην ἤδη τῶν περὶ τὸν υἱὸν εἰς γνῶσιν ἀφιγμένον, ἔλεγον δὲ τὸν μὲν Ἰώσηπον οὔτʼ ἰδεῖν οὔθʼ ᾗ κέχρηται συμφορᾷ μεμαθηκέναι, χιτῶνα δὲ τοῦτον εὑρεῖν ᾑμαγμένον καὶ λελακισμένον, ὅθεν αὐτοῖς ὑπόνοιαν εἶναι περιπεσόντα θηρίοις αὐτὸν ἀπολωλέναι, εἴγε τοῦτον ἐνδεδυμένος οἴκοθεν ἐστάλη."},{"number":37,"text":"Ἰάκωβος δὲ ἐπὶ κουφοτέραις ὢν ἐλπίσιν ὡς ἠνδραποδισμένου δῆθεν αὐτῷ τοῦ παιδός, τοῦτον μὲν ἀφίησι τὸν λογισμόν, πίστιν δʼ αὐτοῦ τῆς τελευτῆς ἐναργῆ τὸν χιτῶνα ὑπολαβών, καὶ γὰρ ἐγνώρισεν ἐκεῖνον αὐτὸν ὃν ἐνδεδυμένον ἐκπέμποι πρὸς τοὺς ἀδελφούς, ὡς ἐπὶ νεκρῷ τὸ λοιπὸν οὕτω διέκειτο ἐπὶ τῷ μειρακίῳ πενθῶν."},{"number":38,"text":"καὶ ὡς ἑνὸς πατὴρ ὢν καὶ τῆς ἐξ ἄλλων παραμυθίας ἐστερημένος οὕτως ἦν παρὰ τῷ κακῷ, πρὶν ἢ τοῖς ἀδελφοῖς συμβαλεῖν εἰκάζων ὑπὸ θηρίων Ἰώσηπον ἀφανῆ γεγονέναι. ἐκαθέζετο δὲ σακκίον ἐξαψάμενος καὶ τῇ λύπῃ βαρύς, ὡς μήτε ὑπὸ παίδων παρηγορούντων αὐτὸν ῥᾴονα γενέσθαι μήτε κάμνοντα τοῖς πόνοις ἀπαγορεύειν."}],"4":[{"number":39,"text":"Ἰώσηπον δὲ πωλούμενον ὑπὸ τῶν ἐμπόρων ὠνησάμενος Πετεφρὴς ἀνὴρ Αἰγύπτιος ἐπὶ τῶν Φαραώθου μαγείρων τοῦ βασιλέως εἶχεν ἐν πάσῃ τιμῇ καὶ παιδείαν τε τὴν ἐλευθέριον ἐπαίδευε καὶ διαίτῃ χρῆσθαι κρείττονι τῆς ἐπὶ δούλῳ τύχης ἐπέτρεπεν ἐγχειρίζει τε τὴν τῶν κατὰ τὸν οἶκον αὐτῷ πρόνοιαν."},{"number":40,"text":"ὁ δὲ τούτων τε ἀπέλαυε καὶ τὴν ἀρετήν, ἥτις ἦν περὶ αὐτόν, οὐδʼ ὑπὸ τῆς μεταβολῆς ἐγκατέλιπεν, ἀλλὰ διέδειξε τὸ φρόνημα κρατεῖν τῶν ἐν τῷ βίῳ δυσκόλων δυνάμενον, οἷς ἂν παρῇ γνησίως καὶ μὴ πρὸς τὰς εὐπραγίας τὰς κατὰ καιρὸν μόνον ἡρμοσμένον."},{"number":41,"text":"Τῆς γὰρ τοῦ δεσπότου γυναικὸς διά τε τὴν εὐμορφίαν καὶ τὴν περὶ τὰς πράξεις αὐτοῦ δεξιότητα ἐρωτικῶς διατεθείσης καὶ νομιζούσης, εἰ ποιήσειεν αὐτῷ τοῦτο φανερόν, ῥᾳδίως πείσειν αὐτὸν εἰς ὁμιλίαν ἐλθεῖν εὐτύχημα ἡγησάμενον τὸ τὴν δέσποιναν αὐτοῦ δεηθῆναι,"},{"number":42,"text":"καὶ πρὸς τὸ σχῆμα τῆς τότε δουλείας ἀλλʼ οὐ πρὸς τὸν τρόπον ἀφορώσης τὸν καὶ παρὰ τὴν μεταβολὴν παραμένοντα τήν τε ἐπιθυμίαν αὐτῷ ποιησάσης καταφανῆ καὶ λόγους προσφερούσης περὶ μίξεως, παρέπεμπε τὴν ἀξίωσιν οὐ κρίνας ὅσιον εἶναι τοιαύτην αὐτῇ διδόναι χάριν, ἐν ᾗ τοῦ πριαμένου καὶ τοσαύτης ἠξιωκότος τιμῆς ἀδικίαν συνέβαινεν εἶναι καὶ ὕβριν,"},{"number":43,"text":"ἀλλὰ κρατεῖν τε τοῦ πάθους κἀκείνην παρεκάλει τὴν ἀπόγνωσιν τοῦ τεύξεσθαι τῆς ἐπιθυμίας προβαλλόμενος, σταλήσεσθαι γάρ τε αὐτῇ τοῦτο μὴ παρούσης ἐλπίδος, αὐτός τε πάντα μᾶλλον ὑπομενεῖν ἔλεγεν ἢ πρὸς τοῦτο καταπειθὴς ἔσεσθαι· καὶ γὰρ εἰ τῇ δεσποίνῃ δοῦλον ὄντα δεῖ ποιεῖν μηδὲν ἐναντίον, ἡ πρὸς τὰ τοιαῦτα τῶν προσταγμάτων ἀντιλογία πολλὴν ἂν ἔχοι παραίτησιν."},{"number":44,"text":"τῆς δʼ ἔτι μᾶλλον ἐπέτεινε τὸν ἔρωτα τὸ μὴ προσδοκώσῃ τὸν Ἰώσηπον ἀντισχεῖν καὶ δεινῶς ὑπὸ τοῦ κακοῦ πολιορκουμένη δευτέρᾳ πάλιν πείρᾳ προεθυμεῖτο κατεργάσασθαι."},{"number":45,"text":"Δημοτελοῦς οὖν ἑορτῆς ἐπιστάσης, καθʼ ἣν εἰς τὴν πανήγυριν καὶ γυναιξὶ φοιτᾶν νόμιμον ἦν, σκήπτεται νόσον πρὸς τὸν ἄνδρα θηρωμένη μόνωσιν καὶ σχολὴν εἰς τὸ δεηθῆναι τοῦ Ἰωσήπου, καὶ γενομένης αὐτῇ ταύτης λιπαρεστέρους ἔτι τῶν πρώτων αὐτῷ προσηνέγκατο λόγους,"},{"number":46,"text":"ὡς καλῶς μὲν εἶχεν αὐτὸν μετὰ τὴν ἐξ ἀρχῆς δέησιν εἶξαι καὶ μηδὲ ἀντειρηκέναι κατά τε τὴν τῆς παρακαλούσης ἐντροπὴν καὶ τὴν τοῦ πάθους ὑπερβολήν, ὑφʼ οὗ βιασθείη δέσποινα οὖσα τοῦ κατὰ ταύτην ἀξιώματος ταπεινοτέρα γενέσθαι, φρονήσει δὲ καὶ νῦν ἄμεινον ἐνδοὺς καὶ τὸ ἐπὶ τοῖς παρελθοῦσιν ἄγνωμον διορθώσεται·"},{"number":47,"text":"εἴτε γὰρ δευτέραν δέησιν ἐξεδέχετο, ταύτην γεγονέναι καὶ μετὰ πλείονος σπουδῆς· νόσον τε γὰρ προφασίσασθαι καὶ τῆς ἑορτῆς καὶ τῆς πανηγύρεως τὴν πρὸς αὐτὸν ὁμιλίαν προτιμῆσαι· εἴτε τοῖς πρώτοις ὑπὸ ἀπιστίας ἀντέκρουσε λογισμοῖς, τοῦ μηδεμίαν κακουργίαν εἶναι κρίνειν σύμβολον τὸ τοῖς αὐτοῖς ἐπιμένειν."},{"number":48,"text":"προσδοκᾶν τε τῶν παρόντων ἀγαθῶν ὄνησιν, ὧν ἤδη μετέχειν, προσθέμενον αὐτῆς τῷ ἔρωτι καὶ μειζόνων ἀπολαύσειν ὑπήκοον γενόμενον, ἄμυναν δὲ καὶ μῖσος παρʼ αὐτῆς ἀποστραφέντα τὴν ἀξίωσιν καὶ τοῦ χαρίσασθαι τῇ δεσποίνῃ τὴν τῆς σωφροσύνης δόκησιν ἐπίπροσθε θέμενον."},{"number":49,"text":"οὐ γὰρ αὐτὸν τοῦτο ὠφελήσειν τραπείσης εἰς κατηγορίαν αὐτοῦ καὶ καταψευσαμένης πεῖραν ἐπὶ τἀνδρί, προσέξειν δὲ μᾶλλον τοῖς αὐτῆς λόγοις Πετεφρὴν ἢ τοῖς ἐκείνου, κἂν ὅτι μάλιστα ἀπὸ τῆς ἀληθείας φέρωνται."},{"number":50,"text":"Ταῦτα λεγούσης τῆς γυναικὸς καὶ δακρυούσης οὔτε οἶκτος αὐτὸν μὴ σωφρονεῖν ἔπεισεν οὔτʼ ἠνάγκασε φόβος, ἀλλὰ ταῖς δεήσεσιν ἀντέσχε καὶ ταῖς ἀπειλαῖς οὐκ ἐνέδωκε καὶ παθεῖν ἀδίκως καὶ ὑπομένειν τι τῶν χαλεπωτέρων εἵλετο μᾶλλον ἢ τῶν παρόντων ἀπολαύειν χαρισάμενος ἐφʼ οἷς ἂν αὑτῷ συνειδῇ δικαίως ἀπολουμένῳ."},{"number":51,"text":"γάμου τε αὐτὴν ὑπεμίμνησκε καὶ τῆς πρὸς τὸν ἄνδρα συμβιώσεως καὶ τούτοις τὸ πλέον νέμειν ἢ προσκαίρῳ τῆς ἐπιθυμίας ἡδονῇ παρεκάλει, τῆς μὲν καὶ μετάνοιαν ἑξούσης αὖθις ἐπʼ ὀδύνῃ γενησομένην οὐκ ἐπὶ διορθώσει τῶν ἡμαρτημένων καὶ φόβον του μὴ κατάφωρον γενέσθαι καὶ χάριν τοῦ λαθεῖν ἀγνοουμένου τοῦ κακοῦ,"},{"number":52,"text":"τῆς δὲ πρὸς τὸν ἄνδρα κοινωνίας ἀπόλαυσιν ἐχούσης ἀκίνδυνον καὶ προσέτι πολλὴν τὴν ἀπὸ τοῦ συνειδότος καὶ πρὸς τὸν θεὸν παρρησίαν καὶ πρὸς τοὺς ἀνθρώπους· καὶ ὡς αὐτοῦ δεσπόσει μᾶλλον μείνασα καθαρὰ καὶ δεσποίνης ἐξουσίᾳ χρήσεται πρὸς αὐτόν, ἀλλʼ οὐ συνεξαμαρτάνοντος αἰδοῖ· πολὺ δὲ κρεῖττον εἶναι θαρρεῖν ἐπὶ γινωσκομένοις τοῖς εὖ βεβιωμένοις ἢ ἐπὶ λανθανούσῃ κακοπραγίᾳ."},{"number":53,"text":"Ταῦτα λέγων καὶ ἔτι πλείω τούτοις ὅμοια τὴν τῆς γυναικὸς ὁρμὴν ἐπέχειν ἐπειρᾶτο καὶ τὸ πάθος αὐτῆς εἰς λογισμὸν ἐπιστρέφειν, ἡ δὲ βιαιότερον ἐχρῆτο τῇ σπουδῇ καὶ ἐπιβαλοῦσα τὰς χεῖρας ἀναγκάζειν ἀπογνοῦσα τὸ πείθειν ἤθελεν."},{"number":54,"text":"ὡς δʼ ἐξέφυγεν ὑπὸ ὀργῆς ὁ Ἰώσηπος προσκαταλιπὼν καὶ τὸ ἱμάτιον, κατεχούσης καὶ γὰρ αὐτὸν ἐκ τούτου μεθεὶς ἐξεπήδησε τοῦ δωματίου, περιδεὴς γενομένη, μὴ κατείπῃ πρὸς τὸν ἄνδρα αὐτῆς, καὶ τῆς ὕβρεως περιαλγῶς ἔχουσα φθάσαι καταψεύσασθαι πρὸς τὸν Πετεφρὴν ἔγνω τοῦ Ἰωσήπου, καὶ τούτῳ τῷ τρόπῳ τιμωρῆσαι μὲν αὐτῇ δεινῶς ὑπερηφανημένῃ, προλαβεῖν δὲ τὴν διαβολὴν σοφὸν ἅμα καὶ γυναικεῖον ἡγήσατο."},{"number":55,"text":"καὶ καθῆστο μὲν κατηφὴς καὶ συγκεχυμένη τὴν ἐπὶ τῷ διαμαρτεῖν τῆς ἐπιθυμίας λύπην ὡς ἐπὶ πείρᾳ διαφθορᾶς πλασαμένη μετʼ ὀργῆς, ἐλθόντι δὲ τἀνδρὶ καὶ πρὸς τὴν ὄψιν ταραχθέντι καὶ πυνθανομένῳ τὴν αἰτίαν τῆς κατηγορίας τῆς Ἰωσήπου κατήρξατο καί τεθναίης, εἶπεν, ἄνερ, ἢ πονηρὸν δοῦλον κοίτην μιᾶναι τὴν σὴν θελήσαντα κόλασον,"},{"number":56,"text":"ὃς οὔθʼ οἷος ὢν εἰς τὸν ἡμέτερον οἶκον ἀφῖκται μνησθεὶς ἐσωφρόνησεν οὔθʼ ὧν ἐκ τῆς σῆς χρηστότητος ἔτυχεν, ἀλλʼ ἀχάριστος ὢν ἄν, εἰ μὴ πάντα παρεῖχεν αὑτὸν ἀγαθὸν εἰς ἡμᾶς, ἐπεβούλευσεν ὑβρίσαι γάμον τὸν σόν, καὶ ταῦτʼ ἐν ἑορτῇ τὴν σὴν ἀπουσίαν παραφυλάξας· ὡς ὅσα καὶ μέτριος ἐδόκει πρότερον διὰ τὸν ἐκ σοῦ φόβον ἠρέμει καὶ οὐχὶ φύσει χρηστὸς ἦν."},{"number":57,"text":"τοιοῦτον δʼ ἄρα τὸ παρʼ ἀξίαν αὐτὸν καὶ παρʼ ἐλπίδας εἰς τιμὴν παρελθεῖν ἐποίησεν, ὡς δέον ᾧ τὴν τῆς κτήσεως τῆς σῆς πίστιν καὶ τὴν οἰκονομίαν λαβεῖν ἐξεγένετο καὶ τῶν πρεσβυτέρων οἰκετῶν προτιμηθῆναι τούτῳ καὶ τῆς σῆς ψαύειν γυναικός."},{"number":58,"text":"παυσαμένη δὲ τῶν λόγων ἐπεδείκνυεν αὐτῷ τὸ ἱμάτιον, ὡς ὅτʼ ἐπεχείρει βιάσασθαι καταλιπόντος αὐτό. Πετεφρὴς δὲ μήτε δακρυούσῃ τῇ γυναικὶ μήθʼ οἷς ἔλεγε καὶ εἶδεν ἀπιστεῖν ἔχων τῷ τε πρὸς αὐτὴν ἔρωτι πλέον νέμων ἐπὶ μὲν τὴν τῆς ἀληθείας ἐξέτασιν οὐκ ἐτρέπετο,"},{"number":59,"text":"δοὺς δὲ σωφρονεῖν τῇ γυναικὶ πονηρὸν δʼ εἶναι κατακρίνας τὸν Ἰώσηπον τὸν μὲν εἰς τὴν τῶν κακούργων εἱρκτὴν ἐνέβαλεν, ἐπὶ δὲ τῇ γυναικὶ καὶ μᾶλλον ἐφρόνει κοσμιότητα καὶ σωφροσύνην αὐτῇ μαρτυρῶν."}],"5":[{"number":60,"text":"Ἰώσηπος μὲν οὖν πάντʼ ἐπὶ τῷ θεῷ ποιησάμενος τὰ περὶ αὐτὸν οὔτʼ εἰς ἀπολογίαν οὔτʼ ἐπʼ ἀκριβῆ τῶν γεγονότων δήλωσιν ἐτράπη, τὰ δεσμὰ δὲ καὶ τὴν ἀνάγκην σιγῶν ὑπῆλθεν ἀμείνονα ἔσεσθαι τῶν δεδεκότων θαρρῶν τὸν τὴν αἰτίαν τῆς συμφορᾶς καὶ τὴν ἀλήθειαν εἰδότα θεόν, οὗ πεῖραν τῆς προνοίας εὐθὺς ἐλάμβανεν·"},{"number":61,"text":"ὁ γὰρ δεσμοφύλαξ τήν τε ἐπιμέλειαν καὶ τὴν πίστιν αὐτοῦ κατανοήσας ἐν οἷς τάξειεν αὐτὸν καὶ τὸ ἀξίωμα τῆς μορφῆς ὑπανίει τε τῶν δεσμῶν καὶ τὸ δεινὸν ἐλαφρότερον αὐτῷ καὶ κοῦφον ἐποίει, διαίτῃ δὲ χρῆσθαι κρείττονι δεσμωτῶν ἐπέτρεπε."},{"number":62,"text":"τῶν δὲ ἐν τοῖς αὐτοῖς ὄντων εἴποτε παύσαιντο τῆς περὶ τὰ ἔργα ταλαιπωρίας εἰς ὁμιλίαν, οἷα φιλεῖ κατὰ κοινωνίαν τῆς ὁμοίας συμφορᾶς, τρεπομένων καὶ παρʼ ἀλλήλων τὰς αἰτίας ἐφʼ αἷς κατακριθεῖεν ἀναπυνθανομένων,"},{"number":63,"text":"οἰνοχόος τοῦ βασιλέως καὶ σφόδρα αὐτῷ τιμώμενος κατʼ ὀργὴν δεδεμένος καὶ συνδιαφέρων τῷ Ἰωσήπῳ τὰς πέδας συνηθέστερος αὐτῷ μᾶλλον ἐγένετο καί, συνέσει γὰρ ἐδόκει αὐτὸν προύχειν, ὄναρ ἰδὼν ἐξέθετο παρακαλῶν δηλοῦν εἴ τι σημαίνει, μεμφόμενος ὅτι τοῖς ἐκ τοῦ βασιλέως κακοῖς ἔτι τὸ θεῖον αὐτῷ καὶ τὰς ἐκ τῶν ὀνειράτων φροντίδας προστίθησιν."},{"number":64,"text":"Ἔλεγε δʼ οὖν ἰδεῖν κατὰ τοὺς ὕπνους τριῶν κλημάτων πεφυκυίας ἀμπέλου βότρυς ἐξ ἑκάστου ἀποκρέμασθαι μεγάλους ἤδη καὶ πρὸς τρύγητον ὡραίους, καὶ τούτους αὐτὸς ἀποθλίβειν εἰς φιάλην ὑπέχοντος τοῦ βασιλέως διηθήσας τε τὸ γλεῦκος δοῦναι τῷ βασιλεῖ πιεῖν, κἀκεῖνον δέξασθαι κεχαρισμένως."},{"number":65,"text":"τὸ μὲν οὖν ἑωραμένον ἐδήλου τοιοῦτον ὄν, ἠξίου δʼ εἴ τι μεμοίραται συνέσεως φράζειν αὐτῷ τὴν πρόρρησιν τῆς ὄψεως. ὁ δὲ θαρρεῖν τε παρεκάλει καὶ προσδοκᾶν ἐν τρισὶν ἡμέραις ἀπολυθήσεσθαι τῶν δεσμῶν τοῦ βασιλέως ποθήσαντος αὐτοῦ τὴν διακονίαν καὶ πάλιν εἰς ταύτην αὐτὸν ἐπανάξοντος·"},{"number":66,"text":"καρπὸν γὰρ ἐσήμαινεν ἀμπέλινον ἐπʼ ἀγαθῷ τὸν θεὸν ἀνθρώποις παρασχεῖν, ὃς αὐτῷ τε ἐκείνῳ σπένδεται καὶ πίστιν ἀνθρώποις καὶ φιλίαν ὁμηρεύει, διαλύων μὲν ἔχθρας τὰ πάθη δὲ καὶ τὰς λύπας ἐξαιρῶν τοῖς προσφερομένοις αὐτὸν καὶ πρὸς ἡδονὴν ὑποφέρων."},{"number":67,"text":"τοῦτον οὖν φῂς ἐκ τριῶν ἀποθλιβέντα βοτρύων χερσὶ ταῖς σαῖς προσέσθαι τὸν βασιλέα· καλὴν τοίνυν ἴσθι σοι τὴν ὄψιν γεγενημένην καὶ προμηνύουσαν ἄφεσιν τῆς παρούσης ἀνάγκης ἐν τοσαύταις ἡμέραις, ἐξ ὅσων κλημάτων τὸν καρπὸν ἐτρύγησας κατὰ τοὺς ὕπνους."},{"number":68,"text":"μέμνησο μέντοι τούτων πειραθεὶς τοῦ προκαταγγείλαντός σοι τὰ ἀγαθά, καὶ γενόμενος ἐν ἐξουσίᾳ μὴ περιίδῃς ἡμᾶς ἐν οἷς καταλείψεις πρὸς ἃ δεδηλώκαμεν ἀπερχόμενος· οὐδὲν γὰρ ἐξαμαρτόντες ἐν δεσμοῖς γεγόναμεν,"},{"number":69,"text":"ἀλλʼ ἀρετῆς ἕνεκα καὶ σωφροσύνης τὰ τῶν κακούργων ὑπομένειν κατεκρίθημεν οὐδέ γε μετʼ οἰκείας ἡδονῆς τὸν ταῦθʼ ἡμᾶς ἐργασάμενον ὑβρίσαι θελήσαντες. τῷ μὲν οὖν οἰνοχόῳ χαίρειν κατὰ τὸ εἰκὸς ἀκούσαντι τοιαύτης τῆς τοῦ ὀνείρατος ἐξηγήσεως ὑπῆρχε καὶ περιμένειν τῶν δεδηλωμένων τὴν τελευτήν."},{"number":70,"text":"Δοῦλος δέ τις ἐπὶ τῶν σιτοποιῶν τεταγμένος τοῦ βασιλέως συνδεδεμένος τῷ οἰνοχόῳ τοιαύτην ποιησαμένου τοῦ Ἰωσήπου περὶ τῆς ὄψεως ἐκείνῳ τὴν ἀπόφασιν εὔελπις ὤν, καὶ γὰρ καὐτὸς ὄναρ ἦν τεθεαμένος, ἠξίωσε τὸν Ἰώσηπον φράσαι, τί κἀκείνῳ δηλοῦν βούλεται τὰ διὰ τῆς παρελθούσης νυκτὸς ὀφθέντα."},{"number":71,"text":"ἦν δὲ τοιαῦτα· τρία, φησί, κανᾶ φέρειν ὑπὲρ τῆς κεφαλῆς ἔδοξα, δύο μὲν ἄρτων πλέα, τὸ δὲ τρίτον ὄψου τε καὶ ποικίλων βρωμάτων οἷα βασιλεῦσι σκευάζεται· καταπταμένους δʼ οἰωνοὺς ἅπαντα δαπανῆσαι μηδένα λόγον αὐτοῦ ποιουμένους ἀποσοβοῦντος."},{"number":72,"text":"καὶ ὁ μὲν ὁμοίαν τὴν πρόρρησιν ἔσεσθαι τῇ τοῦ οἰνοχόου προσεδόκα· ὁ δὲ Ἰώσηπος συμβαλὼν τῷ λογισμῷ τὸ ὄναρ καὶ πρὸς αὐτὸν εἰπών, ὡς ἐβούλετʼ ἂν ἀγαθῶν ἑρμηνευτὴς αὐτῷ γεγονέναι καὶ οὐχ οἵων τὸ ὄναρ αὐτῷ δηλοῖ, λέγει δύο τὰς πάσας ἔτι τοῦ ζῆν αὐτὸν ἔχειν ἡμέρας· τὰ γὰρ κανᾶ τοῦτο σημαίνειν·"},{"number":73,"text":"τῇ τρίτῃ δʼ αὐτὸν ἀνασταυρωθέντα βορὰν ἔσεσθαι πετεινοῖς οὐδὲν ἀμύνειν αὑτῷ δυνάμενον. καὶ δὴ ταῦτα τέλος ὅμοιον οἷς ὁ Ἰώσηπος εἶπεν ἀμφοτέροις ἔλαβε· τῇ γὰρ ἡμέρᾳ τῇ προειρημένῃ γενέθλιον τεθυκὼς ὁ βασιλεὺς τὸν μὲν ἐπὶ τῶν σιτοποιῶν ἀνεσταύρωσε, τὸν δὲ οἰνοχόον τῶν δεσμῶν ἀπολύσας ἐπὶ τῆς αὐτῆς ὑπηρεσίας κατέστησεν."},{"number":74,"text":"Ἰώσηπον δὲ διετῆ χρόνον τοῖς δεσμοῖς κακοπαθοῦντα καὶ μηδὲν ὑπὸ τοῦ οἰνοχόου κατὰ μνήμην τῶν προειρημένων ὠφελούμενον ὁ θεὸς ἀπέλυσε τῆς εἱρκτῆς τοιαύτην αὐτῷ τὴν ἀπαλλαγὴν μηχανησάμενος·"},{"number":75,"text":"Φαραώθης ὁ βασιλεὺς ὑπὸ τὴν αὐτὴν ἑσπέραν ὄψεις ἐνυπνίων θεασάμενος δύο καὶ μετʼ αὐτῶν τὴν ἑκατέρας ἐξήγησιν ταύτης μὲν ἠμνημόνησε, τῶν δὲ ὀνειράτων κατέσχεν. ἀχθόμενος οὖν ἐπὶ τοῖς ἑωραμένοις, καὶ γὰρ ἐδόκει σκυθρωπὰ ταῦτʼ αὐτῷ, συνεκάλει μεθʼ ἡμέραν Αἰγυπτίων τοὺς λογιωτάτους χρῄζων μαθεῖν τῶν ὀνειράτων τὴν κρίσιν."},{"number":76,"text":"ἀπορούντων δʼ ἐκείνων ἔτι μᾶλλον ὁ βασιλεὺς ἐταράττετο. τὸν δὲ οἰνοχόον ὁρῶντα τοῦ Φαραώθου τὴν σύγχυσιν ὑπέρχεται μνήμη τοῦ Ἰωσήπου καὶ τῆς περὶ τῶν ὀνειράτων συνέσεως,"},{"number":77,"text":"καὶ προσελθὼν ἐμήνυσεν αὐτῷ τὸν Ἰώσηπον τήν τε ὄψιν, ἣν αὐτὸς εἶδεν ἐν τῇ εἱρκτῇ, καὶ τὸ ἀποβὰν ἐκείνου φράσαντος, ὅτι τε σταυρωθείη κατὰ τὴν αὐτὴν ἡμέραν ὁ ἐπὶ τῶν σιτοποιῶν κἀκείνῳ τοῦτο συμβαίη κατὰ ἐξήγησιν ὀνείρατος Ἰωσήπου προειπόντος."},{"number":78,"text":"δεδέσθαι δὲ τοῦτον μὲν ὑπὸ Πετεφροῦ τοῦ ἐπὶ τῶν μαγείρων ὡς δοῦλον, λέγειν δʼ αὐτὸν Ἑβραίων ἐν ὀλίγοις εἶναι γένους ἅμα καὶ τῆς τοῦ πατρὸς δόξης. τοῦτον οὖν μεταπεμψάμενος καὶ μὴ διὰ τὴν ἄρτι κακοπραγίαν αὐτοῦ καταγνοὺς μαθήσῃ τὰ ὑπὸ τῶν ὀνειράτων σοι δηλούμενα."},{"number":79,"text":"κελεύσαντος οὖν τοῦ βασιλέως εἰς ὄψιν αὐτοῦ τὸν Ἰώσηπον παραγαγεῖν τὸν μὲν ἥκουσιν ἄγοντες οἱ κεκελευσμένοι τημελήσαντες κατὰ πρόσταγμα τοῦ βασιλέως."},{"number":80,"text":"Ὁ δὲ τῆς δεξιᾶς αὐτοῦ λαβόμενος ὦ νεανία, φησί, σὺ γάρ μοι νῦν ἄριστος καὶ συνίσειν ἱκανώτατος ὑπὸ οἰκέτου τοὐμοῦ μεμαρτύρησαι, τῶν αὐτῶν ἀγαθῶν, ὧν καὶ τούτῳ μετέδωκας ἀξίωσον κἀμὲ φράσας ὅσα μοι κατὰ τοὺς ὕπνους ὀνειράτων ὄψεις προδηλοῦσι· βούλομαι δέ σε μηδὲν ὑποστελλόμενον φόβῳ κολακεῦσαι ψευδεῖ λόγῳ καὶ τῷ πρὸς ἡδονήν, ἂν τἀληθὲς σκυθρωπότερον ᾖ."},{"number":81,"text":"ἔδοξα γὰρ παρὰ ποταμὸν βαδίζων βόας ἰδεῖν εὐτραφεῖς ἅμα καὶ μεγέθει διαφερούσας ἑπτὰ τὸν ἀριθμὸν ἀπὸ τοῦ νάματος χωρεῖν ἐπὶ τὸ ἕλος, ἄλλας δὲ ταύταις τὸν ἀριθμὸν παραπλησίας ἐκ τοῦ ἕλους ὑπαντῆσαι λίαν κατισχνωμένας καὶ δεινὰς ὁραθῆναι, αἳ κατεσθίουσαι τὰς εὐτραφεῖς καὶ μεγάλας οὐδὲν ὠφελοῦντο χαλεπῶς ὑπὸ τοῦ λιμοῦ τετρυχωμέναι."},{"number":82,"text":"μετὰ δὲ ταύτην τὴν ὄψιν διεγερθεὶς ἐκ τοῦ ὕπνου καὶ τεταραγμένος ὢν καὶ τί ποτʼ εἴη τὸ φάντασμα παρʼ ἐμαυτῷ σκοπῶν καταφέρομαι πάλιν εἰς ὕπνον καὶ δεύτερον ὄναρ ὁρῶ πολὺ τοῦ προτέρου θαυμασιώτερον, ὅ με καὶ μᾶλλον ἐκφοβεῖ καὶ ταράττει."},{"number":83,"text":"στάχυας ἑπτὰ ἑώρων ἀπὸ μιᾶς ῥίζης ἐκφυέντας καρηβαροῦντας ἤδη καὶ κεκλιμένους ὑπὸ τοῦ καρποῦ καὶ τῆς πρὸς ἄμητον ὥρας καὶ τούτοις ἑτέρους ἑπτὰ στάχυας πλησίον λιφερνοῦντας καὶ ἀσθενεῖς ὑπὸ ἀδροσίας, οἳ δαπανᾶν καὶ κατεσθίειν τοὺς ὡραίους τραπέντες ἔκπληξίν μοι παρέσχον."},{"number":84,"text":"Ἰώσηπος δὲ ὑπολαβών, ὄνειρος μὲν οὗτος, εἶπεν, ὦ βασιλεῦ, καίπερ ἐν δυσὶ μορφαῖς ὀφθεὶς μίαν καὶ τὴν αὐτὴν ἀποσημαίνει τελευτὴν τῶν ἐσομένων. τό τε γὰρ τὰς βοῦς ἰδεῖν ζῷον ἐπʼ ἀρότρῳ πονεῖν γεγενημένον ὑπὸ τῶν χειρόνων κατεσθιομένας,"},{"number":85,"text":"καὶ οἱ στάχυες ὑπὸ τῶν ἐλαττόνων δαπανώμενοι λιμὸν Αἰγύπτῳ καὶ ἀκαρπίαν ἐπὶ τοσαῦτα προκαταγγέλλουσιν ἔτη τοῖς ἴσοις πρότερον εὐδαιμονησάσῃ, ὡς τὴν τούτων εὐφορίαν τῶν ἐτῶν ὑπὸ τῆς τῶν μετὰ τοσοῦτον ἀριθμὸν ἴσων ἀφορίας ὑπαναλωθῆναι. γενήσεται δὴ σπάνις τῶν ἀναγκαίων σφόδρα δυσκατόρθωτος."},{"number":86,"text":"σημεῖον δέ· αἱ γὰρ κατισχνωμέναι βόες δαπανήσασαι τὰς κρείττονας οὐκ ἴσχυσαν κορεσθῆναι. ὁ μέντοι θεὸς οὐκ ἐπὶ τῷ λυπεῖν τὰ μέλλοντα τοῖς ἀνθρώποις προδείκνυσιν, ἀλλʼ ὅπως προυγνωκότες κουφοτέρας συνέσει ποιῶνται τὰς πείρας τῶν κατηγγελμένων. σὺ τοίνυν ταμιευσάμενος τἀγαθὰ τὰ κατὰ τὸν πρῶτον χρόνον γενησόμενα ποιήσεις ἀνεπαίσθητον Αἰγυπτίοις τὴν ἐπελευσομένην συμφοράν."},{"number":87,"text":"Θαυμάσαντος δὲ τοῦ βασιλέως τὴν φρόνησιν καὶ τὴν σοφίαν τοῦ Ἰωσήπου καὶ πυθομένου, τίνα καὶ τρόπον ἂν προοικονομήσειεν ἐν τοῖς τῆς εὐετηρίας καιροῖς τὰ περὶ τῶν μετὰ ταύτην, ὡς ἂν ἐλαφρότερα γένοιτο τὰ τῆς ἀφορίας,"},{"number":88,"text":"ὑπετίθετο καὶ συνεβούλευε φειδὼ τῶν ἀγαθῶν, καὶ μὴ κατὰ περιουσίαν αὐτοῖς χρῆσθαι τοῖς Αἰγυπτίοις ἐπιτρέπειν, ἀλλʼ ὅσα ἂν κατὰ τρυφὴν ἀναλώσωσιν ἐκ περισσοῦ, ταῦτα τηρεῖν εἰς τὸν τῆς ἐνδείας καιρόν, ἀποτίθεσθαί τε παρῄνει λαμβάνοντα τὸν σῖτον παρὰ τῶν γεωργῶν τὰ διαρκῆ μόνον εἰς διατροφὴν χορηγοῦντα."},{"number":89,"text":"Φαραώθης δʼ ἀμφοτέρων θαυμάσας Ἰώσηπον τῆς τε κρίσεως τοῦ ὀνείρατος καὶ τῆς συμβουλίας αὐτῷ τὴν οἰκονομίαν παραδίδωσιν, ὥστε πράττειν ἃ καὶ τῷ πλήθει τῶν Αἰγυπτίων καὶ τῷ βασιλεῖ συμφέροντα ὑπολαμβάνει, τὸν ἐξευρόντα τὴν τοῦ πράγματος ὁδὸν καὶ προστάτην ἄριστον αὐτῆς ὑπολαβὼν γενήσεσθαι."},{"number":90,"text":"ὁ δὲ ταύτης αὐτῷ τῆς ἐξουσίας ὑπὸ τοῦ βασιλέως δοθείσης σφραγῖδί τε χρῆσθαι τῇ αὐτοῦ καὶ πορφύραν ἐνδύσασθαι διὰ τῆς γῆς ἁπάσης ἐλαύνων ἐφʼ ἅρματος ἦγε τὸν σῖτον παρὰ τῶν γεωργῶν τὸν ἀρκοῦντα πρός τε σπόρον καὶ διατροφὴν ἑκάστοις ἀπομετρῶν, μηδενὶ σημαίνων τὴν αἰτίαν, ὑφʼ ἧς ταῦτα ἔπραττε."}],"6":[{"number":91,"text":"Τριακοστὸν δʼ ἔτος ἤδη τῆς ἡλικίας αὐτῷ διεληλύθει καὶ τιμῆς ἁπάσης ἀπέλαυε τοῦ βασιλέως καὶ προσηγόρευσεν αὐτὸν Ψονθονφάνηχον ἀπιδὼν αὐτοῦ πρὸς τὸ παράδοξον τῆς συνέσεως· σημαίνει γὰρ τὸ ὄνομα κρυπτῶν εὑρετήν. γαμεῖ δὲ καὶ γάμον ἀξιολογώτατον· ἄγεται γὰρ καὶ Πετεφροῦ θυγατέρα τῶν ἐν Ἡλιουπόλει ἱερέων συμπράξαντος αὐτῷ τοῦ βασιλέως ἔτι παρθένον Ἀσέννηθιν ὀνόματι."},{"number":92,"text":"ἐκ ταύτης δὲ καὶ παῖδες αὐτῷ γίνονται πρὸ τῆς ἀκαρπίας Μανασσῆς μὲν πρεσβύτερος, σημαίνει δʼ ἐπίληθον, διὰ τὸ εὐδαιμονήσαντα λήθην εὕρασθαι τῶν ἀτυχημάτων, ὁ δὲ νεώτερος Ἐφράδης, ἀποδιδοὺς δὲ τοῦτο σημαίνει, διὰ τὸ ἀποδοθῆναι αὐτὸν τῇ ἐλευθερίᾳ τῶν προγόνων."},{"number":93,"text":"τῆς δʼ Αἰγύπτου κατὰ τὴν Ἰωσήπου τῶν ὀνειράτων ἐξήγησιν μακαριστῶς ἔτη ἑπτὰ διαγούσης ὁ λιμὸς ἥπτετο τῷ ὀγδόῳ ἔτει καὶ διὰ τὸ μὴ προῃσθημένοις ἐπιπεσεῖν τὸ κακὸν πονούμενοι χαλεπῶς ὑπʼ αὐτοῦ πάντες ἐπὶ τὰς βασιλέως θύρας συνέρρεον."},{"number":94,"text":"ὁ δὲ Ἰώσηπον ἐκάλει, κἀκεῖνος τὸν σῖτον αὐτοῖς ἀπεδίδοτο γεγενημένος σωτὴρ ὁμολογουμένως τοῦ πλήθους, καὶ τὴν ἀγορὰν οὐ τοῖς ἐγχωρίοις προὐτίθει μόνον, ἀλλὰ καὶ τοῖς ξένοις ὠνεῖσθαι παρῆν πάντας ἀνθρώπους κατὰ συγγένειαν ἀξιοῦντος ἐπικουρίας τυγχάνειν Ἰωσήπου παρὰ τῶν εὐδαιμονίᾳ χρωμένων."},{"number":95,"text":"Πέμπει δὲ καὶ Ἰάκωβος τῆς Χαναναίας δεινῶς ἐκτετρυχωμένης, πάσης γὰρ ἥψατο τῆς ἠπείρου τὸ δεινόν, τοὺς υἱοὺς ἅπαντας εἰς τὴν Αἴγυπτον ὠνησομένους σῖτον πεπυσμένος ἐφεῖσθαι τὴν ἀγορὰν καὶ ξένοις· μόνον δὲ κατέσχε Βενιαμὶν ἐκ Ῥαχήλας αὐτῷ γεγονότα ὁμομήτριον δὲ Ἰωσήπῳ."},{"number":96,"text":"οἱ μὲν οὖν εἰς τὴν Αἴγυπτον ἐλθόντες ἐνετύγχανον τῷ Ἰωσήπῳ χρῄζοντες ἀγορᾶς· οὐδὲν γὰρ ἦν, ὃ μὴ μετὰ γνώμης ἐπράττετο τῆς ἐκείνου· καὶ γὰρ τὸ θεραπεῦσαι τὸν βασιλέα τότε χρήσιμον ἐγίνετο τοῖς ἀνθρώποις, ὅτε καὶ τῆς Ἰωσήπου τιμῆς ἐπιμεληθεῖεν."},{"number":97,"text":"ὁ δὲ γνωρίσας τοὺς ἀδελφοὺς οὐδὲν ἐνθυμουμένους περὶ αὐτοῦ διὰ τὸ μειράκιον μὲν αὐτὸς ἀπαλλαγῆναι, εἰς τοῦτο δὲ προελθεῖν τῆς ἡλικίας καὶ τῶν χαρακτήρων ἠλλαγμένων ἀγνώριστος αὐτοῖς εἶναι, τῷ δὲ μεγέθει τοῦ ἀξιώματος οὐδʼ εἰς ἐπίνοιαν ἐλθεῖν αὐτοῖς δυνάμενος διεπείραζεν, ὡς ἔχοιεν γνώμης περὶ τῶν ὅλων."},{"number":98,"text":"τόν τε γὰρ σῖτον αὐτοῖς οὐκ ἀπεδίδοτο κατασκόπους τε τῶν βασιλέως πραγμάτων ἔλεγεν ἥκειν καὶ πολλαχόθεν μὲν αὐτοὺς συνεληλυθέναι, προφασίζεσθαι δὲ συγγένειαν· οὐ γὰρ εἶναι δυνατὸν ἀνδρὶ ἰδιώτῃ τοιούτους παῖδας καὶ τὰς μορφὰς οὕτως ἐπιφανεῖς ἐκτραφῆναι, δυσκόλου καὶ βασιλεῦσιν οὔσης τοιαύτης παιδοτροφίας."},{"number":99,"text":"ὑπὲρ δὲ τοῦ γνῶναι τὰ κατὰ τὸν πατέρα καὶ τὰ συμβεβηκότα αὐτῷ μετὰ τὴν ἰδίαν ἀπαλλαγὴν ταῦτʼ ἔπραττε μαθεῖν τε βουλόμενος καὶ τὰ περὶ Βενιαμὶν τὸν ἀδελφόν· ἐδεδίει γάρ, μὴ κἀκεῖνον ὁμοίως οἷς εἰς αὐτὸν ἐτόλμησαν εἶεν ἀπεσκευασμένοι τοῦ γένους."},{"number":100,"text":"Οἱ δʼ ἦσαν ἐν ταραχῇ καὶ φόβῳ κίνδυνον τὸν μέγιστον αὐτοῖς ἐπηρτῆσθαι νομίζοντες καὶ μηδὲν περὶ τἀδελφοῦ κατὰ νοῦν λαμβάνοντες, καταστάντες τε πρὸς τὰς αἰτίας ἀπελογοῦντο Ῥουβήλου προηγοροῦντος, ὃς ἦν πρεσβύτατος αὐτῶν·"},{"number":101,"text":"ἡμεῖς γὰρ, εἶπεν, οὐ κατὰ ἀδικίαν δεῦρο ἤλθομεν οὐδὲ κακουργήσοντες τὰ βασιλέως πράγματα, σωθῆναι δὲ ζητοῦντες καὶ καταφυγὴν τῶν ἐπεχόντων τὴν χώραν ἡμῶν κακῶν τὴν ὑμετέραν φιλανθρωπίαν ὑπολαβόντες, οὓς οὐχὶ πολίταις μόνοις τοῖς αὐτῶν, ἀλλὰ καὶ ξένοις ἠκούομεν τὴν ἀγορὰν τοῦ σίτου προτεθεικέναι πᾶσι τὸ σώζεσθαι τοῖς δεομένοις παρέχειν διεγνωκότας."},{"number":102,"text":"ὅτι δʼ ἐσμὲν ἀδελφοὶ καὶ κοινὸν ἡμῖν αἷμα, φανερὸν μὲν καὶ τῆς μορφῆς τὸ οἰκεῖον καὶ μὴ πολὺ παρηλλαγμένον ποιεῖ, πατὴρ δʼ ἐστὶν ἡμῖν Ἰάκωβος ἀνὴρ Ἑβραῖος, ᾧ γινόμεθα δώδεκα παῖδες ἐκ γυναικῶν τεσσάρων, ὧν πάντων περιόντων ἦμεν εὐδαίμονες."},{"number":103,"text":"ἀποθανόντος δὲ ἑνὸς τῶν ἀδελφῶν Ἰωσήπου τὰ πράγματα ἡμῖν ἐπὶ τὸ χεῖρον μετέβαλεν· ὅ τε γὰρ πατὴρ μακρὸν ἐπʼ αὐτῷ πένθος ἦρται καὶ ἡμεῖς ὑπό τε τῆς ἐπὶ τῷ τεθνηκότι συμφορᾶς καὶ τῆς τοῦ πρεσβύτου ταλαιπωρίας κακοπαθοῦμεν."},{"number":104,"text":"ἥκομέν τε νῦν ἐπʼ ἀγορὰν σίτου τήν τε τοῦ πατρὸς ἐπιμέλειαν καὶ τὴν κατὰ τὸν οἶκον πρόνοιαν Βενιαμεῖ τῷ νεωτάτῳ τῶν ἀδελφῶν πεπιστευκότες· δύνασαι δὲ πέμψας εἰς τὸν ἡμέτερον οἶκον μαθεῖν, εἴ τι ψευδές ἐστι τῶν λεγομένων."},{"number":105,"text":"Καὶ Ῥουβῆλος μὲν τούτοις ἐπειρᾶτο πείθειν τὸν Ἰώσηπον περὶ αὐτῶν τὰ ἀμείνω φρονῆσαι, ὁ δὲ τὸν Ἰάκωβον ζῶντα μαθὼν καὶ τὸν ἀδελφὸν οὐκ ἀπολωλότα τότε μὲν εἰς τὴν εἱρκτὴν αὐτοὺς ὡς ἐπὶ σχολῆς βασανίσων ἐνέβαλε, τῇ δὲ τρίτῃ τῶν ἡμερῶν προαγαγὼν αὐτούς,"},{"number":106,"text":"ἐπεί, φησί, διισχυρίζεσθε μήτʼ ἐπὶ κακουργίᾳ τῶν βασιλέως ἥκειν πραγμάτων εἶναί τε ἀδελφοὶ καὶ πατρὸς οὗ λέγετε, πείσαιτʼ ἄν με ταῦθʼ οὕτως ἔχειν, εἰ καταλίποιτε μὲν ἐξ αὑτῶν ἕνα παρʼ ἐμοὶ μηδὲν ὑβριστικὸν πεισόμενον, ἀποκομίσαντες δὲ τὸν σῖτον πρὸς τὸν πατέρα πάλιν ἔλθοιτε πρὸς ἐμὲ τὸν ἀδελφόν, ὃν καταλιπεῖν ἐκεῖ φατε,"},{"number":107,"text":"μεθʼ ἑαυτῶν ἄγοντες· τοῦτο γὰρ ἔσται πίστωμα τῆς ἀληθείας. οἱ δʼ ἐν μείζοσι κακοῖς ἦσαν ἔκλαιόν τε καὶ συνεχῶς πρὸς ἀλλήλους ἀνωλοφύροντο τὴν Ἰωσήπου συμφοράν, ὡς διὰ τὰ κατʼ ἐκείνου βουλευθέντα τιμωροῦντος αὐτοὺς τοῦ θεοῦ τούτοις περιπέσοιεν, Ῥουβῆλος δὲ πολὺς ἦν ἐπιπλήττων αὐτοῖς τῆς μετανοίας, ἐξ ἧς ὄφελος οὐδὲν Ἰωσήπῳ γίνεται· φέρειν δʼ αὐτοὺς πᾶν ὅ τι καὶ πάθοιεν κατʼ ἐκδικίαν ἐκείνου δρῶντος αὐτὰ τοῦ θεοῦ καρτερῶς ἠξίου."},{"number":108,"text":"ταῦτα δʼ ἔλεγον πρὸς ἀλλήλους οὐχ ἡγούμενοι τὸν Ἰώσηπον γλώσσης τῆς αὐτῶν συνιέναι. κατήφεια δὲ πάντας εἶχε πρὸς τοὺς Ῥουβήλου λόγους καὶ τῶν πραγμάτων μετάμελος, ὥσπερ οὖν καὶ τῶν ταῦτα ψηφισαμένων, ἐφʼ οἷς δίκαιον ἔκρινον τὸν θεὸν κολαζόμενοι."},{"number":109,"text":"βλέπων δʼ οὕτως ἀμηχανοῦντας Ἰώσηπος ὑπὸ τοῦ πάθους εἰς δάκρυα προύπιπτε καὶ μὴ βουλόμενος τοῖς ἀδελφοῖς γενέσθαι καταφανὴς ὑπεχώρει καὶ διαλιπὼν πάλιν ἧκε πρὸς αὐτούς."},{"number":110,"text":"καὶ Σεμεῶνα κατασχὼν ὅμηρον τῆς ἐπανόδου τῶν ἀδελφῶν γενησόμενον ἐκείνους μεταλαβόντας τῆς ἀγορᾶς τοῦ σίτου προσέταξεν ἀπιέναι, κελεύσας τῷ ὑπηρέτῃ τἀργύριον, ὃ πρὸς τὴν ὠνὴν εἶεν τοῦ σίτου κεκομικότες, κρύφα τοῖς φορτίοις ἐνθέντι ἀπολύειν κἀκεῖνο κομίζοντας. καὶ ὁ μὲν τὰ ἐντεταλμένα ἔπραττεν."},{"number":111,"text":"Οἱ δὲ Ἰακώβου παῖδες ἐλθόντες εἰς τὴν Χαναναίαν ἀπήγγελλον τῷ πατρὶ τὰ κατὰ τὴν Αἴγυπτον αὐτοῖς συμπεσόντα, καὶ ὅτι κατάσκοποι δόξειαν ἀφῖχθαι τοῦ βασιλέως καὶ λέγοντες ἀδελφοί τε εἶναι καὶ τὸν ἑνδέκατον οἴκοι καταλιπεῖν παρὰ τῷ πατρὶ ἀπιστηθεῖεν, ὡς καταλίποιέν τε Σεμεῶνα παρὰ τῷ στρατηγῷ μέχρι Βενιαμὶς ὡς αὐτὸν ἀπιὼν πίστις αὐτοῖς τῶν εἰρημένων παρʼ αὐτῷ γένοιτο·"},{"number":112,"text":"ἠξίουν τε τὸν πατέρα μηδὲν φοβηθέντα πέμπειν σὺν αὐτοῖς τὸν νεανίσκον. Ἰακώβῳ δʼ οὐδὲν ἤρεσκε τῶν τοῖς υἱοῖς πεπραγμένων, καὶ πρὸς τὴν Σεμεῶνος δὲ κατοχὴν λυπηρῶς φέρων ἀνόητον ἡγεῖτο προστιθέναι καὶ τὸν Βενιαμίν."},{"number":113,"text":"καὶ ὁ μὲν οὐδὲ Ῥουβήλου δεομένου καὶ τοὺς αὑτοῦ παῖδας ἀντιδιδόντος, ἵνα εἴ τι πάθοι Βενιαμὶς κατὰ τὴν ἀποδημίαν ἀποκτείνειεν αὐτοὺς ὁ πάππος, πείθεται τοῖς λόγοις. οἱ δʼ ἠπόρουν ἐπὶ τοῖς κακοῖς καὶ μᾶλλον αὐτοὺς ἐτάραττε τἀργύριον ἐν τοῖς σακκίοις τοῦ σίτου κατακεκρυμμένον εὑρεθέν."},{"number":114,"text":"τοῦ δὲ σίτου τοῦ κομισθέντος ὑπʼ αὐτῶν ἐπιλιπόντος καὶ τοῦ λιμοῦ μᾶλλον ἁπτομένου βιαζομένης αὐτὸν τῆς ἀνάγκης ὁ Ἰάκωβος ἐκπέμπειν ἐγίνωσκε τὸν Βενιαμὶν μετὰ τῶν ἀδελφῶν·"},{"number":115,"text":"οὐ γὰρ ἦν αὐτοῖς εἰς Αἴγυπτον ἀπελθεῖν μὴ μετὰ τῶν ἐπαγγελιῶν ἀπερχομένοις, καὶ τοῦ πάθους οὖν χείρονος καθʼ ἑκάστην ἡμέραν γινομένου καὶ τῶν υἱῶν δεομένων οὐκ εἶχεν, ὅ τι χρήσαιτο τοῖς παροῦσιν."},{"number":116,"text":"Ἰούδα δὲ τολμηροῦ τἆλλα τὴν φύσιν ἀνδρὸς χρησαμένου πρὸς αὐτὸν παρρησίᾳ, ὡς οὐ προσῆκε μὲν αὐτὸν περὶ τἀδελφοῦ δεδιέναι οὐδὲ τὰ μὴ δεινὰ διʼ ὑποψίας λαμβάνειν, πραχθήσεται γὰρ οὐδὲν αὐτῶν περὶ τὸν ἀδελφόν, ᾧ μὴ παρέσται θεός, τοῦτο δὲ συμβήσεσθαι πάντως καὶ παρʼ αὐτῷ μένοντι·"},{"number":117,"text":"φανερὰν δʼ οὕτως αὐτῶν ἀπώλειαν μὴ καταδικάζειν μηδὲ τὴν ἐκ Φαραώθου τῆς τροφῆς αὐτῶν εὐπορίαν αὐτοὺς ἀφαιρεῖσθαι ἀλόγως περὶ τοῦ παιδὸς δεδιότα, φροντίζειν δὲ καὶ τῆς Σεμεῶνος σωτηρίας, μὴ φειδοῖ τῆς Βενιαμὶν ἀποδημίας ἐκεῖνος ἀπόληται· πιστεῦσαι δὲ περὶ αὐτοῦ τῷ θεῷ παραινοῦντος καὶ αὐτῷ, ὡς ἢ σῶον ἐπανάξοντος αὐτῷ τὸν υἱὸν ἢ συγκαταστρέψοντος ἅμα ἐκείνῳ τὸν βίον,"},{"number":118,"text":"πεισθεὶς Ἰάκωβος παρεδίδου τὸν Βενιαμὶν καὶ τὴν τιμὴν τοῦ σίτου διπλασίονα τῶν τε παρὰ τοῖς Χαναναίοις γεννωμένων τό τε τῆς βαλάνου μύρον καὶ στακτὴν τερέβινθόν τε καὶ μέλι δωρεὰς Ἰωσήπῳ κομίζειν. πολλὰ δὲ ἦν παρὰ τοῦ πατρὸς ἐπὶ τῇ τῶν παίδων ἐξόδῳ δάκρυα κἀκείνων αὐτῶν."},{"number":119,"text":"ὁ μὲν γὰρ τοὺς υἱοὺς εἰ κομιεῖται σώους ἐκ τῆς ἀποδημίας ἐφρόντιζεν, οἱ δʼ εἰ τὸν πατέρα καταλάβοιεν ἐρρωμένον καὶ μηδὲν ὑπὸ τῆς ἐπʼ αὐτοῖς λύπης κακωθέντα. ἡμερήσιον δὲ αὐτοῖς ἠνύσθη τὸ πένθος, καὶ ὁ μὲν πρεσβύτης κοπωθεὶς ὑπέμενεν, οἱ δὲ ἐχώρουν εἰς Αἴγυπτον μετὰ κρείττονος ἐλπίδος τὴν ἐπὶ τοῖς παροῦσι λύπην ἰώμενοι."},{"number":120,"text":"Ὡς δʼ ἦλθον εἰς τὴν Αἴγυπτον κατάγονται μὲν παρὰ τὸν Ἰώσηπον, φόβος δὲ αὐτοὺς οὐχ ὁ τυχὼν διετάραττε, μὴ περὶ τῆς τοῦ σίτου τιμῆς ἐγκλήματα λάβωσιν ὡς αὐτοί τι κεκακουργηκότες, καὶ πρὸς τὸν ταμίαν τοῦ Ἰωσήπου πολλὴν ἀπολογίαν ἐποιοῦντο κατʼ οἶκόν τε φάσκοντες εὑρεῖν ἐν τοῖς σάκκοις τὸ ἀργύριον καὶ νῦν ἥκειν ἐπανάγοντες αὐτό."},{"number":121,"text":"τοῦ δὲ μηδʼ ὅ τι λέγουσιν εἰδέναι φήσαντος ἀνείθησαν τοῦ δέους. λύσας τε τὸν Συμεῶνα ἐτημέλει συνεσόμενον τοῖς ἀδελφοῖς. ἐλθόντος δὲ ἐν τούτῳ καὶ Ἰωσήπου ἀπὸ τῆς θεραπείας τοῦ βασιλέως τά τε δῶρα παρῆγον αὐτῷ καὶ πυθομένου περὶ τοῦ πατρὸς ἔλεγον, ὅτι καταλάβοιεν αὐτὸν ἐρρωμένον."},{"number":122,"text":"ὁ δὲ μαθὼν περιόντα καὶ περὶ τοῦ Βενιαμὶν εἰ οὗτος ὁ νεώτερος ἀδελφὸς αὐτῶν εἴη, καὶ γὰρ ἦν αὐτὸν ἑωρακώς, ἀνέκρινε. τῶν δὲ φησάντων αὐτὸν εἶναι οἰκέτην αὐτοῦ θεὸν μὲν ἐπὶ πᾶσι προστάτην εἶπεν,"},{"number":123,"text":"ὑπὸ δὲ τοῦ πάθους προαγόμενος εἰς δάκρυα μεθίστατο μὴ βουλόμενος καταφανὴς εἶναι τοῖς ἀδελφοῖς, ἐπὶ δεῖπνόν τε αὐτοὺς παραλαμβάνει καὶ κατακλίνονται οὕτως ὡς καὶ παρὰ τῷ πατρί. πάντας δὲ αὐτοὺς ὁ Ἰώσηπος δεξιούμενος διπλασίοσι μοίραις τῶν αὐτῷ παρακειμένων τὸν Βενιαμὶν ἐτίμα."},{"number":124,"text":"Ἐπεὶ δὲ μετὰ τὸ δεῖπνον εἰς ὕπνον ἐτράποντο, κελεύει τῷ ταμίᾳ τόν τε σῖτον αὐτοῖς δοῦναι μεμετρημένον καὶ τὴν τιμὴν πάλιν ἐγκρύψαι τοῖς σακκίοις, εἰς δὲ τὸ τοῦ Βενιαμὶν φορτίον καὶ σκύφος ἀργυροῦν, ᾧ πίνων ἔχαιρε, βαλόντα καταλιπεῖν."},{"number":125,"text":"ἐποίει δὲ ταῦτα διάπειραν βουλόμενος τῶν ἀδελφῶν λαβεῖν, πότερόν ποτε βοηθήσουσι τῷ Βενιαμὶν κλοπῆς ἀγομένῳ καὶ δοκοῦντι κινδυνεύειν, ἢ καταλιπόντες ὡς οὐδὲν αὐτοὶ κεκακουργηκότες ἀπίασι πρὸς τὸν πατέρα."},{"number":126,"text":"ποιήσαντος δὲ τοῦ οἰκέτου τὰ ἐντεταλμένα μεθʼ ἡμέραν οὐδὲν τούτων εἰδότες οἱ τοῦ Ἰακώβου παῖδες ἀπῄεσαν ἀπειληφότες τὸν Σεμεῶνα καὶ διπλῆν χαρὰν χαίροντες ἐπί τε τούτῳ κἀπὶ τῷ Βενιαμὶν ἀποκομίζειν τῷ πατρί, καθὼς ὑπέσχοντο. περιελαύνουσι δʼ αὐτοὺς ἱππεῖς ἄγοντες τὸν οἰκέτην, ὃς ἐναπέθετο τῷ τοῦ Βενιαμὶν φορτίῳ τὸν σκύφον."},{"number":127,"text":"ταραχθέντας δὲ ὑπὸ τῆς ἀδοκήτου τῶν ἱππέων ἐφόδου καὶ τὴν αἰτίαν πυθομένους διʼ ἣν ἐπʼ ἄνδρας ἐληλύθασιν,"},{"number":128,"text":"οἳ μικρὸν ἔμπροσθεν τιμῆς καὶ ξενίας τετυχήκασιν αὐτῶν παρὰ τοῦ δεσπότου, κακίστους ἀπεκάλουν, οἳ μηδʼ αὐτὸ τοῦτο τὴν ξενίαν καὶ τὴν φιλοφροσύνην τὴν Ἰωσήπου διὰ μνήμης λαβόντες οὐκ ὤκνησαν εἰς αὐτὸν ἄδικοι γενέσθαι, σκύφον δὲ, ᾧ φιλοτησίας αὐτοῖς προύπιεν, ἀράμενοι φέροιεν κέρδους ἀδίκου τήν τε πρὸς Ἰώσηπον φιλίαν τόν τε ἑαυτῶν εἰ φωραθεῖεν κίνδυνον ἐν δευτέρῳ θέμενοι·"},{"number":129,"text":"τιμωρίαν τε αὐτοὺς ὑφέξειν ἠπείλουν οὐ λανθάνοντας τὸν θεὸν οὐδʼ ἀποδράντας μετὰ τῆς κλοπῆς, εἰ καὶ τὸν διακονούμενον οἰκέτην διέλαθον. πυνθάνεσθαί τε νῦν, τί παρόντες εἴημεν, ὡς οὐκ εἰδότας· γνώσεσθαι μέντοι κολαζομένους αὐτίκα. καὶ ταῦτα καὶ πέρα τούτων ὁ οἰκέτης εἰς αὐτοὺς λέγων ἐνύβριζεν."},{"number":130,"text":"οἱ δὲ ὑπὸ ἀγνοίας τῶν περὶ αὐτοὺς ἐχλεύαζον ἐπὶ τοῖς λεγομένοις καὶ τῆς κουφολογίας τὸν οἰκέτην ἐθαύμαζον τολμῶντα αἰτίαν ἐπιφέρειν ἀνδράσιν, οἳ μηδὲ τὴν τοῦ σίτου τιμὴν ἐν τοῖς σακκίοις αὐτῶν εὑρεθεῖσαν κατέσχον, ἀλλʼ ἐκόμισαν μηδενὸς εἰδότος τὸ πραχθέν· τοσοῦτον ἀποδεῖν τοῦ γνώμῃ κακουργῆσαι."},{"number":131,"text":"τῆς μέντοι γε ἀρνήσεως ἀξιοπιστοτέραν ὑπολαβόντες τὴν ἔρευναν ἐκέλευον ταύτῃ χρῆσθαι κἂν εὑρεθῇ τις ὑφῃρημένος ἅπαντας κολάζειν· οὐδὲν γὰρ αὑτοῖς συνειδότες ἦγον παρρησίαν, ὡς ἐδόκουν, ἀκίνδυνον. ὁ δὲ τὴν ἔρευναν μὲν ἠξίωσε ποιήσασθαι, τὴν μέντοι τιμωρίαν ἑνὸς ἔφασκεν εἶναι τοῦ τὴν κλοπὴν εὑρεθέντος πεποιημένου."},{"number":132,"text":"τὴν δὲ ζήτησιν ποιούμενοι καὶ πάντας τοὺς ἄλλους ἐκπεριελθόντες κατὰ τὴν ἔρευναν ἐπὶ τὸν τελευταῖον Βενιαμὶν ἧκον οὐκ ἀγνοοῦντες, ὅτι εἰς τὸ ἐκείνου σακκίον τὸν σκύφον εἶεν ἀποκεκρυφότες, ἀλλʼ ἀκριβῆ τὴν ζήτησιν βουλόμενοι ποιεῖσθαι δοκεῖν."},{"number":133,"text":"οἱ μὲν οὖν ἄλλοι τοῦ κατʼ αὐτοὺς ἀπηλλαγμένοι δέους ἐν τῇ περὶ τὸν Βενιαμὶν φροντίδι τὸ λοιπὸν ἦσαν, ἐθάρρουν δʼ ὡς οὐδʼ ἐν ἐκείνῳ τῆς κακουργίας εὑρεθησομένης ἐκάκιζόν τε τοὺς ἐπιδιώξαντας ὡς ἐμποδίσαντας αὐτοῖς τὴν ὁδὸν δυναμένοις ἤδη προκεκοφέναι."},{"number":134,"text":"ὡς δὲ τὸ τοῦ Βενιαμὶν φορτίον ἐρευνῶντες λαμβάνουσι τὸν σκύφον εἰς οἰμωγὰς καὶ θρήνους εὐθὺς ἐτράπησαν καὶ τὰς στολὰς ἐπικαταρρήξαντες ἔκλαιόν τε τὸν ἀδελφὸν ἐπὶ τῇ μελλούσῃ κολάσει τῆς κλοπῆς αὐτούς τε διαψευσομένους τὸν πατέρα περὶ τῆς Βενιαμὶν σωτηρίας."},{"number":135,"text":"ἐπέτεινε δὲ τὸ δεινὸν αὐτοῖς καὶ τὸ δόξαντας ἤδη διαφυγεῖν τὰ σκυθρωπὰ διαφθονηθῆναι, τῶν δὲ περὶ τὸν ἀδελφὸν κακῶν καὶ τῆς τοῦ πατρὸς ἐπʼ αὐτῷ λύπης ἐσομένους αὑτοὺς αἰτίους ἔλεγον βιασαμένους ἄκοντα τὸν πατέρα συναποστεῖλαι."},{"number":136,"text":"Οἱ μὲν οὖν ἱππεῖς παραλαβόντες τὸν Βενιαμὶν ἦγον πρὸς Ἰώσηπον καὶ τῶν ἀδελφῶν ἑπομένων, ὁ δὲ τὸν μὲν ἰδὼν ἐν φυλακῇ, τοὺς δʼ ἐν πενθίμοις σχήμασι, τί δή, φησίν, ὦ κάκιστοι, φρονήσαντες ἢ περὶ τῆς ἐμῆς φιλανθρωπίας ἢ περὶ τοῦ θεοῦ τῆς προνοίας τοιαῦτα πράττειν εἰς εὐεργέτην καὶ ξένον ἐτολμήσατε;"},{"number":137,"text":"τῶν δὲ παραδιδόντων αὑτοὺς εἰς κόλασιν ἐπὶ τῷ σώζεσθαι Βενιαμὶν καὶ πάλιν ἀναμιμνησκομένων τῶν εἰς Ἰώσηπον τετολμημένων κἀκεῖνον ἀποκαλούντων μακαριώτερον, εἰ μὲν τέθνηκεν ὅτι τῶν κατὰ τὸν βίον ἀπήλλακται σκυθρωπῶν, εἰ δὲ περίεστιν ὅτι τῆς παρὰ τοῦ θεοῦ κατʼ αὐτῶν ἐκδικίας τυγχάνει, λεγόντων δʼ αὑτοὺς ἀλιτηρίους τοῦ πατρός, ὅτι τῇ λύπῃ ἣν ἐπʼ ἐκείνῳ μέχρι νῦν ἔχει καὶ τὴν ἐπὶ Βενιαμὶν προσθήσουσι, πολὺς ἦν κἀνταῦθʼ ὁ Ῥουβῆλος αὐτῶν καθαπτόμενος."},{"number":138,"text":"Ἰωσήπου δὲ τοὺς μὲν ἀπολύοντος, οὐδὲν γὰρ αὐτὸν ἀδικεῖν, ἀρκεῖσθαι δὲ μόνῃ τῇ τοῦ παιδὸς τιμωρίᾳ λέγοντος, οὔτε γὰρ τοῦτον ἀπολύειν διὰ τοὺς οὐδὲν ἐξαμαρτόντας σῶφρον ἔλεγεν οὔτε συγκολάζειν ἐκείνους τῷ τὴν κλοπὴν εἰργασμένῳ, βαδιοῦσι δὲ παρέξειν ἀσφάλειαν ἐπαγγελλομένου,"},{"number":139,"text":"τοὺς μὲν ἄλλους ἔκπληξις ἔλαβε καὶ πρὸς τὸ πάθος ἀφωνία, Ἰούδας δὲ ὁ καὶ τὸν πατέρα πείσας ἐκπέμψαι τὸ μειράκιον καὶ τἆλλα δραστήριος ὢν ἀνὴρ ὑπὲρ τῆς τἀδελφοῦ σωτηρίας ἔκρινε παραβάλλεσθαι,"},{"number":140,"text":"καί δεινὰ μέν, εἶπεν, ὦ στρατηγέ, τετολμήκαμεν εἰς σὲ καὶ τιμωρίας ἄξια καὶ τοῦ κόλασιν ὑποσχεῖν ἅπαντας ἡμᾶς δικαίως, εἰ καὶ τὸ ἀδίκημα μὴ ἄλλου τινός, ἀλλʼ ἑνὸς τοῦ νεωτάτου γέγονεν. ὅμως δὲ ἀπεγνωκόσιν ἡμῖν τὴν διʼ αὐτοῦ σωτηρίαν ἐλπὶς ὑπολέλειπται παρὰ τῆς σῆς χρηστότητος ἐγγυωμένη τὴν τοῦ κινδύνου διαφυγήν."},{"number":141,"text":"καὶ νῦν μὴ πρὸς τὸ ἡμέτερον ἀφορῶν μηδὲ τὸ κακούργημα σκοπῶν, ἀλλὰ πρὸς τὴν σαυτοῦ φύσιν καὶ τὴν ἀρετὴν σύμβουλον ποιησάμενος ἀντὶ τῆς ὀργῆς, ἣν οἱ τἆλλα μικροὶ πρὸς ἰσχύος λαμβάνουσιν οὐκ ἐν τοῖς μεγάλοις μόνον ἀλλὰ καὶ ἐπὶ τοῖς τυχοῦσιν αὐτῇ χρώμενοι, γενοῦ πρὸς αὐτὴν μεγαλόφρων καὶ μὴ νικηθῇς ὑπʼ αὐτῆς, ὥστε ἀποκτεῖναι τοὺς οὐδʼ αὐτοὺς ὡς ἰδίας ἔτι τῆς σωτηρίας ἀντιποιουμένους, ἀλλὰ παρὰ σοῦ λαβεῖν αὐτὴν ἀξιοῦντας."},{"number":142,"text":"καὶ γὰρ οὐδὲ νῦν πρῶτον ἡμῖν αὐτὴν παρέξεις, ἀλλὰ τάχιον ἐλθοῦσιν ἐπὶ τὴν ἀγορὰν τοῦ σίτου καὶ τὴν εὐπορίαν τῆς τροφῆς ἐχαρίσω δοὺς ἀποκομίζειν καὶ τοῖς οἰκείοις ὅσα κινδυνεύοντας αὐτοὺς ὑπὸ τοῦ λιμοῦ διαφθαρῆναι περιέσωσε."},{"number":143,"text":"διαφέρει δʼ οὐδὲν ἢ μὴ περιιδεῖν ἀπολλυμένους ὑπʼ ἐνδείας τῶν ἀναγκαίων, ἢ μὴ κολάσαι δόξαντας ἁμαρτεῖν καὶ περὶ τὴν εὐεργεσίαν τὴν ἀπὸ σοῦ λαμπρὰν γενομένην φθονηθέντας, ἡ δʼ αὐτὴ χάρις ἄλλῳ μέντοι τρόπῳ διδομένη·"},{"number":144,"text":"σώσεις γὰρ οὓς εἰς τοῦτο καὶ ἔτρεφες καὶ ψυχάς, ἃς ὑπὸ λιμοῦ καμεῖν οὐκ εἴασας, τηρήσεις ταῖς σαυτοῦ δωρεαῖς, ὡς θαυμαστὸν ἅμα καὶ μέγα δοῦναί τε ψυχὰς ἡμῖν καὶ παρασχεῖν διʼ ὧν αὗται μενοῦσιν ἀπορουμένοις."},{"number":145,"text":"οἶμαί τε τὸν θεὸν αἰτίαν παρασκευάσαι βουλόμενον εἰς ἐπίδειξιν τοῦ κατὰ τὴν ἀρετὴν περιόντος ἡμᾶς εἰς τοῦτο περιστῆσαι συμφορᾶς, ἵνα καὶ τῶν εἰς αὑτὸν ἀδικημάτων συγγινώσκων φανῇς τοῖς ἐπταικόσιν, ἀλλὰ μὴ πρὸς μόνους τοὺς κατʼ ἄλλην πρόφασιν δεομένους ἐπικουρίας φιλάνθρωπος δοκοίης."},{"number":146,"text":"ὡς μέγα μὲν καὶ τὸ ποιῆσαί τινας εὖ καταστάντας εἰς χρείαν, ἡγεμονικώτερον δὲ σῶσαι τοὺς ὑπὲρ τῶν εἰς ἑαυτὸν τετολμημένων δίκην ὀφείλοντας· εἰ γὰρ τὸ περὶ μικρῶν ζημιωμάτων ἀφεῖναι τοὺς πλημμελήσαντας ἔπαινον ἤνεγκε τοῖς ὑπεριδοῦσι, τό γε περὶ τούτων ἀόργητον, ὑπὲρ ὧν τὸ ζῆν ὑπεύθυνον τῇ κολάσει γίνεται τῶν ἠδικηκότων, θεοῦ φύσει προσετέθη."},{"number":147,"text":"καὶ ἔγωγε, εἰ μὴ πατὴρ ἡμῖν ἦν πῶς ἐπὶ παίδων ἀποβολῇ ταλαιπωρεῖ διὰ τῆς ἐπὶ Ἰωσήπῳ λύπης ἐπιδεδειγμένος, οὐκ ἂν τοῦ γε καθʼ ἡμᾶς ἕνεκα περὶ τῆς σωτηρίας λόγους ἐποιησάμην, εἰ μὴ ὅσον τῷ σῷ χαριζόμενος ἤθει σώζειν αὐτῷ καλῶς ἔχοντι, καὶ τούτους οἳ λυπήσονται τεθνηκότων οὐκ ἔχοντες παρείχομεν ἂν αὑτοὺς πεισομένους ὅ τι καὶ θελήσειας·"},{"number":148,"text":"νῦν δʼ, οὐ γὰρ αὑτοὺς ἐλεοῦντες, εἰ καὶ νέοι καὶ μήπω τῶν κατὰ τὸν βίον ἀπολελαυκότες τεθνηξόμεθα, τὸ δὲ τοῦ πατρὸς λογιζόμενοι καὶ τὸ γῆρας οἰκτείροντες τὸ ἐκείνου ταύτας σοι τὰς δεήσεις προσφέρομεν καὶ παραιτούμεθα ψυχὰς τὰς αὑτῶν, ἅς σοι τὸ ἡμέτερον κακούργημα πρὸς τιμωρίαν παρέδωκεν,"},{"number":149,"text":"οὔτε πονηρὸς αὐτὸς οὔτε τοιούτους ἐσομένους ἐγέννησεν ἀλλὰ χρηστὸς ὢν καὶ πειραθῆναι τοιούτων οὐχὶ δίκαιος καὶ νῦν μὲν ἀποδημούντων ταῖς ὑπὲρ ἡμῶν φροντίσι κακοπαθεῖ, πυθόμενος δὲ ἀπολωλότας καὶ τὴν αἰτίαν οὐχ ὑπομενεῖ ἀλλὰ διὰ ταύτην πολὺ μᾶλλον τὸν βίον καταλείπει,"},{"number":150,"text":"καὶ τὸ ἄδοξον αὐτὸν τῆς ἡμετέρας καταστροφῆς φθήσεται διαχρησάμενον καὶ κακὴν αὐτῷ ποιήσει τὴν ἐκ τοῦ ζῆν ἀπαλλαγήν, πρὶν εἰς ἄλλους φοιτῆσαι τὰ καθʼ ἡμᾶς σπεύσαντος αὑτὸν εἰς ἀναισθησίαν μεταγαγεῖν."},{"number":151,"text":"γενόμενος οὖν ἐν τούτῳ τὸν λογισμόν, εἰ καὶ ἡ κακία σε παροξύνει νῦν ἡ ἡμετέρα, τὸ κατʼ αὐτῆς δίκαιον χάρισαι τῷ πατρὶ καὶ δυνηθήτω πλέον ὁ πρὸς ἐκεῖνον ἔλεος τῆς ἡμετέρας πονηρίας καὶ γῆρας ἐν ἐρημίᾳ βιωσόμενον καὶ τεθνηξόμενον ἡμῶν ἀπολομένων αἴδεσαι, τῷ πατέρων ὀνόματι ταύτην χαριζόμενος τὴν δωρεάν."},{"number":152,"text":"ἐν γὰρ τούτῳ καὶ τὸν σὲ φύσαντα τιμᾷς καὶ σαυτῷ δίδως, ἀπολαύων μὲν ἤδη τῆς προσηγορίας, ἀπαθὴς δʼ ἐπʼ αὐτῇ φυλαχθησόμενος ὑπὸ τοῦ θεοῦ τοῦ πάντων πατρός, εἰς ὃν κατὰ κοινωνίαν καὶ αὐτὸς τοῦ ὀνόματος εὐσεβεῖν δόξεις τοῦ ἡμετέρου πατρὸς οἶκτον λαβὼν ἐφʼ οἷς πείσεται τῶν παίδων στερούμενος."},{"number":153,"text":"σὸν οὖν, ἃ παρέσχεν ἡμῖν ὁ θεὸς ταῦτʼ ἔχοντʼ ἐξουσίαν ἀφελέσθαι δοῦναι καὶ μηδὲν ἐκείνου διενεγκεῖν τῇ χάριτι· τῆς γὰρ ἐπαμφότερον δυνάμεως τετυχηκότα καλὸν ταύτην ἐν τοῖς ἀγαθοῖς ἐπιδείκνυσθαι, καὶ παρὸν καὶ ἀπολλύειν τῆς μὲν κατὰ τοῦτο ἐξουσίας ὡς μηδʼ ὑπαρχούσης ἐπιλανθάνεσθαι, μόνον δʼ ἐπιτετράφθαι τὸ σώζειν ὑπολαμβάνειν, καὶ ὅσῳ τις πλείοσι τοῦτο παρέξει μᾶλλον αὐτῷ φαίνεσθαι διδόντα."},{"number":154,"text":"σὺ δὲ πάντας ἡμᾶς σώσεις τἀδελφῷ συγγνοὺς ὑπὲρ ὧν ἠτύχηκεν· οὐδὲ γὰρ ἡμῖν βιώσιμα τούτου κολασθέντος, οἷς γε πρὸς τὸν πατέρα μὴ ἔξεστιν ἀνασωθῆναι μόνοις, ἀλλʼ ἐνθάδε δεῖ κοινωνῆσαι τούτῳ τῆς αὐτῆς καταστροφῆς τοῦ βίου."},{"number":155,"text":"καὶ δεησόμεθά σου, στρατηγέ, κατακρίναντος τὸν ἀδελφὸν ἡμῶν ἀποθανεῖν συγκολάσαι καὶ ἡμᾶς ὡς τοῦ ἀδικήματος κεκοινωνηκότας· οὐ γὰρ ἀξιώσομεν ἡμεῖς ὡς ἐπὶ λύπῃ τεθνηκότος αὑτοὺς ἀνελεῖν, ἀλλʼ ὡς ὁμοίως αὐτῷ πονηροὶ γεγονότες οὕτως ἀποθανεῖν."},{"number":156,"text":"καὶ ὅτι μὲν καὶ νέος ὢν ἥμαρτε καὶ μήπω τὸ φρονεῖν ἐρηρεισμένος καὶ ὡς ἀνθρώπινον τοῖς τοιούτοις συγγνώμην νέμειν, σοὶ καταλιπὼν παύομαι περαιτέρω λέγειν, ἵνʼ εἰ μὲν κατακρίνειας ἡμῶν, τὰ μὴ λεχθέντα δόξῃ βεβλαφέναι πρὸς τὸ σκυθρωπότερον ἡμᾶς,"},{"number":157,"text":"εἰ δʼ ἀπολύσειας, κἀκεῖνα τῇ σαυτοῦ χρηστότητι συνιδὼν ἀπεψηφίσθαι νομισθῇς, οὐ σώσας μόνον ἡμᾶς ἀλλὰ καὶ διʼ οὗ δικαιότεροι μᾶλλον φανούμεθα τυχεῖν χαριζόμενος καὶ πλέον ἡμῶν αὐτῶν ὑπὲρ τῆς ἡμετέρας νοήσας σωτηρίας."},{"number":158,"text":"εἴτʼ οὖν κτείνειν αὐτὸν θέλεις, ἐμὲ τιμωρησάμενος ἀντὶ τούτου τῷ πατρὶ τοῦτον ἀπόπεμψον, εἴτε καὶ κατέχειν σοι δοκεῖ δοῦλον, ἐγὼ πρὸς τὰς χρείας σοι ὑπηρετικώτερος, ἀμείνων ὡς ὁρᾷς πρὸς ἑκάτερον τῶν παθῶν ὑπάρχων."},{"number":159,"text":"Ἰούδας μὲν οὖν πάντα ὑπομένειν ὑπὲρ τῆς τἀδελφοῦ σωτηρίας ἡδέως ἔχων ῥίπτει πρὸ τῶν Ἰωσήπου ποδῶν ἑαυτόν, εἴ πως ἐκμαλάξειε τὴν ὀργὴν αὐτοῦ καὶ καταπραΰνειεν ἀγωνιζόμενος, προύπεσον δὲ καὶ οἱ ἀδελφοὶ πάντες δακρύοντες καὶ παραδιδόντες ἑαυτοὺς ὑπὲρ τῆς Βενιαμὶν ψυχῆς ἀπολουμένους."},{"number":160,"text":"Ὁ δὲ Ἰώσηπος ἐλεγχόμενος ὑπὸ τοῦ πάθους καὶ μηκέτι δυνάμενος τὴν τῆς ὀργῆς φέρειν ὑπόκρισιν κελεύει μὲν ἀπελθεῖν τοὺς παρόντας, ἵνα μόνοις αὑτὸν τοῖς ἀδελφοῖς ποιήσῃ φανερόν, ἀναχωρησάντων δὲ ποιεῖ γνώριμον αὑτὸν τοῖς ἀδελφοῖς καί φησι·"},{"number":161,"text":"τῆς μὲν ἀρετῆς ὑμᾶς καὶ τῆς εὐνοίας τῆς περὶ τὸν ἀδελφὸν ἡμῶν ἐπαινῶ καὶ κρείττονας ἢ προσεδόκων ἐκ τῶν περὶ ἐμὲ βεβουλευμένων εὑρίσκω ταῦτα πάντα ποιήσας ἐπὶ πείρᾳ τῆς ὑμετέρας φιλαδελφίας· φύσει δὲ οὐδὲ περὶ ἐμὲ νομίζω πονηροὺς γεγονέναι, θεοῦ δὲ βουλήσει τήν τε νῦν πραγματευομένου τῶν ἀγαθῶν ἀπόλαυσιν καὶ τὴν ἐς ὕστερον, ἂν εὐμενὴς ἡμῖν παραμείνῃ."},{"number":162,"text":"πατρός τε οὖν σωτηρίαν ἐγνωκὼς οὐδʼ ἐλπισθεῖσαν καὶ τοιούτους ὑμᾶς ὁρῶν περὶ τὸν ἀδελφὸν οὐδʼ ὧν εἰς ἐμὲ δοκεῖτε ἁμαρτεῖν ἔτι μνημονεύω, παύσομαι δὲ τῆς ἐπʼ αὐτοῖς μισοπονηρίας καὶ ὡς συναιτίοις τῶν τῷ θεῷ βεβουλευμένων εἰς τὰ παρόντα χάριν ἔχειν ὁμολογῶ."},{"number":163,"text":"ὑμᾶς τε βούλομαι καὶ αὐτοὺς λήθην ἐκείνων λαβόντας ἥδεσθαι μᾶλλον τῆς τότε ἀβουλίας εἰς τοιοῦτον ἐπελθούσης τέλος ἢ δυσφορεῖν αἰσχυνομένους ἐπὶ τοῖς ἡμαρτημένοις. μὴ οὖν δόξῃ λυπεῖν ὑμᾶς τὸ κατʼ ἐμοῦ ψῆφον ἐνεγκεῖν πονηρὰν καὶ ἡ ἐπʼ αὐτῇ μετάνοια τῷ γε μὴ προχωρῆσαι τὰ βεβουλευμένα."},{"number":164,"text":"χαίροντες οὖν ἐπὶ τοῖς ἐκ θεοῦ γεγενημένοις ἄπιτε ταῦτα δηλώσοντες τῷ πατρί, μὴ καὶ ταῖς ὑπὲρ ὑμῶν φροντίσιν ἀναλωθεὶς ζημιώσῃ μου τὸ κάλλιστον τῆς εὐδαιμονίας πρὶν εἰς ὄψιν ἐλθεῖν τὴν ἐμὴν καὶ μεταλαβεῖν τῶν παρόντων ἀποθανών."},{"number":165,"text":"αὐτὸν δὲ τοῦτον καὶ γυναῖκας ὑμετέρας καὶ τὰ τέκνα καὶ πᾶσαν τὴν συγγένειαν ὑμῶν ἀναλαβόντες ἐνθάδε μετοικίζεσθε· οὐδὲ γὰρ ἀποδήμους εἶναι δεῖ τῶν ἀγαθῶν τῶν ἡμετέρων τοὺς ἐμοὶ φιλτάτους ἄλλως τε καὶ τοῦ λιμοῦ λοιπὴν ἔτι πενταετίαν περιμενοῦντος. ταῦτʼ εἰπὼν Ἰώσηπος περιβάλλει τοὺς ἀδελφούς·"},{"number":166,"text":"οἱ δʼ ἐν δάκρυσιν ἦσαν καὶ λύπῃ τῶν ἐπʼ αὐτῷ βεβουλευμένων τιμωρίας τʼ οὐδὲν αὐτοῖς ἀπολιπεῖν ἐδόκει τὸ εὔγνωμον τἀδελφοῦ. καὶ τότε μὲν ἦσαν ἐν εὐωχίᾳ·"},{"number":167,"text":"βασιλεὺς δʼ ἀκούσας ἥκοντας πρὸς τὸν Ἰώσηπον τοὺς ἀδελφοὺς ἥσθη τε μεγάλως καὶ ὡς ἐπʼ οἰκείῳ διατεθεὶς ἀγαθῷ παρεῖχεν αὐτοῖς ἁμάξας σίτου πλήρεις καὶ χρυσὸν καὶ ἄργυρον ἀποκομίζειν τῷ πατρί. λαβόντες δὲ πλείω παρὰ τἀδελφοῦ τὰ μὲν τῷ πατρὶ φέρειν τὰ δὲ αὐτοὶ δωρεὰς ἔχειν ἕκαστος ἰδίας, πλειόνων ἠξιωμένου Βενιαμὶν παρʼ αὐτούς, ἀπῄεσαν."}],"7":[{"number":168,"text":"Ὡς δʼ ἀφικομένων τῶν παίδων Ἰάκωβος τὰ περὶ τὸν Ἰώσηπον ἔμαθεν, ὅτι μὴ μόνον εἴη τὸν θάνατον διαπεφευγὼς ἐφʼ ᾧ πενθῶν διῆγεν, ἀλλὰ καὶ ζῇ μετὰ λαμπρᾶς εὐδαιμονίας βασιλεῖ συνδιέπων τὴν Αἴγυπτον καὶ τὴν ἅπασαν σχεδὸν ἐγκεχειρισμένος αὐτῆς ἐπιμέλειαν,"},{"number":169,"text":"ἄπιστον μὲν οὐδὲν ἐδόκει τῶν ἠγγελμένων λογιζόμενος τοῦ θεοῦ τὴν μεγαλουργίαν καὶ τὴν πρὸς αὐτὸν εὔνοιαν, εἰ καὶ τῷ μεταξὺ χρόνῳ διέλιπεν, ὥρμητο δʼ εὐθὺς πρὸς τὸν Ἰώσηπον."},{"number":170,"text":"Ὡς δὲ κατέσχεν ἐπὶ τὸ Ὅρκιον φρέαρ θύσας αὐτόθι τῷ θεῷ καὶ φοβούμενος διὰ τὴν εὐδαιμονίαν τὴν ἐν Αἰγύπτῳ τῶν παίδων ἐμφιλοχωρησάντων τῇ οἰκήσει τῇ ἐν αὐτῇ, μὴ οὐκέτʼ εἰς τὴν Χαναναίαν οἱ ἔγγονοι μετελθόντες κατάσχωσιν αὐτήν, ὡς ὁ θεὸς ἦν ὑπεισχημένος,"},{"number":171,"text":"ἅμα τε μὴ δίχα θεοῦ βουλήσεως γενομένης τῆς εἰς Αἴγυπτον ἀφόδου διαφθαρῇ τὸ γένος αὐτοῦ, πρὸς δὲ τούτοις δεδιώς, μὴ προεξέλθῃ τοῦ βίου πρὶν εἰς ὄψιν Ἰωσήπου παραγενέσθαι, καταφέρεται στρέφων ἐν ἑαυτῷ τοῦτον τὸν λογισμὸν εἰς ὕπνον."},{"number":172,"text":"Ἐπιστὰς δὲ ὁ θεὸς αὐτῷ καὶ δὶς ὀνομαστὶ καλέσας πυνθανομένῳ τίς ἐστιν, ἀλλʼ οὐ δίκαιον, εἶπεν, Ἰακώβῳ θεὸν ἀγνοεῖσθαι τὸν ἀεὶ παραστάτην καὶ βοηθὸν προγόνοις τε τοῖς σοῖς καὶ μετʼ αὐτοὺς σοὶ γενόμενον."},{"number":173,"text":"στερουμένῳ τε γάρ σοι τῆς ἀρχῆς ὑπὸ τοῦ πατρὸς ταύτην ἐγὼ παρέσχον, καὶ κατʼ ἐμὴν εὔνοιαν εἰς τὴν Μεσοποταμίαν μόνος σταλεὶς γάμων τε ἀγαθῶν ἔτυχες καὶ παίδων ἐπαγόμενος πλῆθος καὶ χρημάτων ἐνόστησας."},{"number":174,"text":"παρέμεινέ τέ σοι γενεὰ πᾶσα προνοίᾳ τῇ ἐμῇ, καὶ ὃν ἀπολωλέναι τῶν υἱῶν ἐδόκεις Ἰώσηπον εἰς ἀπόλαυσιν μειζόνων ἀγαθῶν ἤγαγον καὶ τῆς Αἰγύπτου κύριον, ὡς ὀλίγῳ διαφέρειν τοῦ βασιλέως, ἐποίησα."},{"number":175,"text":"ἥκω τε νῦν ὁδοῦ τε ταύτης ἡγεμὼν ἐσόμενος καὶ βίου σου τελευτὴν ἐν ταῖς Ἰωσήπου χερσὶ γενησομένην προδηλῶν καὶ μακρὸν αἰῶνα τῶν σῶν ἐγγόνων ἐν ἡγεμονίᾳ καὶ δόξῃ καταγγέλλων καταστήσων τε αὐτοὺς εἰς τὴν γῆν ἣν ὑπέσχημαι."},{"number":176,"text":"Τούτῳ θαρρήσας τῷ ὀνείρατι προθυμότερον εἰς τὴν Αἴγυπτον σὺν τοῖς υἱοῖς καὶ παισὶν τοῖς τούτων ἀπηλλάττετο. ἦσαν δʼ οἱ πάντες πέντε καὶ ἑβδομήκοντα. τὰ μὲν οὖν ὀνόματα δηλῶσαι τούτων οὐκ ἐδοκίμαζον καὶ μάλιστα διὰ τὴν δυσκολίαν αὐτῶν·"},{"number":177,"text":"ἵνα μέντοι παραστήσω τοῖς οὐχ ὑπολαμβάνουσιν ἡμᾶς ἐκ τῆς Μεσοποταμίας ἀλλʼ Αἰγυπτίους εἶναι, ἀναγκαῖον ἡγησάμην μνησθῆναι τῶν ὀνομάτων. Ἰακώβου μὲν οὖν παῖδες ἦσαν δώδεκα· τούτων Ἰώσηπος ἤδη προαφῖκτο· τοὺς οὖν μετʼ αὐτὸν καὶ τοὺς ἐκ τούτων γεγονότας δηλώσομεν."},{"number":178,"text":"Ῥουβήλου μὲν ἦσαν παῖδες τέσσαρες, Ἀνώχης Φαλοὺς Ἐσσαρὼν Χάρμισος· Σεμεῶνος δʼ ἕξ, Ἰούμηλος Ἰάμεινος Πούθοδος Ἰαχῖνος Σόαρος Σααρᾶς· τρεῖς δὲ Λευὶ γεγόνασιν υἱοί, Γολγόμης Κάαθος Μαράιρος· Ἰούδᾳ δὲ παῖδες ἦσαν τρεῖς, Σάλας Φάρεσος Ἐζελοός, υἱωνοὶ δὲ δύο γεγονότες ἐκ Φαρέσου, Ἐσρὼν καὶ Ἄμουρος. Ἰσακχάρου δὲ τέσσαρες, Θούλας Φρουρᾶς Ἴωβος Σαμάρων."},{"number":179,"text":"τρεῖς δὲ Ζαβουλὼν ἦγεν υἱούς, Σάραδον Ἥλωνα Ἰάνηλον. τοῦτο μὲν τὸ ἐκ Λείας γένος· καὶ αὐτῇ συνανῄει καὶ θυγάτηρ αὐτῆς Δεῖνα."},{"number":180,"text":"τρεῖς οὗτοι καὶ τριάκοντα. Ῥαχήλας δὲ παῖδες ἦσαν δύο· τούτων Ἰωσήπῳ μὲν γεγόνεισαν υἱοὶ Μανασσῆς καὶ Ἐφράνης. Βενιαμεῖ δὲ τῷ ἑτέρῳ δέκα, Βόλος Βάκχαρις Ἀσαβῆλος Γήλας Νεεμάνης Ἴης Ἄρως Νομφθὴς Ὀππαῖς Ἄροδος. οὗτοι τέσσαρες καὶ δέκα πρὸς τοῖς πρότερον κατειλεγμένοις εἰς ἑπτὰ καὶ τεσσαράκοντα γίνονται τὸν ἀριθμόν."},{"number":181,"text":"καὶ τὸ μὲν γνήσιον γένος τῷ Ἰακώβῳ τοῦτο ἦν, ἐκ Βάλλας δὲ αὐτῷ γίνονται τῆς Ῥαχήλας θεραπαινίδος Δάνος καὶ Νεφθαλίς, ᾧ τέσσαρες εἵποντο παῖδες, Ἐλιῆλος Γοῦνις Σάρης τε καὶ Σέλλιμος, Δάνῳ δὲ μονογενὲς ἦν παιδίον Οὖσις."},{"number":182,"text":"τούτων προσγινομένων τοῖς προειρημένοις πεντήκοντα καὶ τεσσάρων πληροῦσιν ἀριθμόν. Γάδης δὲ καὶ Ἀσῆρος ἐκ Ζελφᾶς μὲν ἦσαν, ἦν Λείας δὲ αὕτη θεραπαινίς, παῖδας δʼ ἐπήγοντο Γάδης μὲν ἑπτά, Ζοφωνίαν Οὔγιν Σοῦνιν Ζάβρωνα Εἰρήνην Ἐρωίδην Ἀριήλην·"},{"number":183,"text":"Ἀσήρωνός τε ἦν θυγάτηρ καὶ ἄρσενες ἀριθμὸν ἕξ, οἷς ὀνόματα Ἰώμνης Ἰσούσιος Ἠϊούβης Βάρης Ἀβαρός τε καὶ Μελχιῆλος. τούτων ἑκκαίδεκα ὄντων καὶ προστιθεμένων τοῖς πεντήκοντα τέσσαρσιν ὁ προειρημένος ἀριθμὸς πληροῦται μὴ συγκαταλεγέντος αὐτοῖς Ἰακώβου."},{"number":184,"text":"Μαθὼν δὲ Ἰώσηπος παραγινόμενον τὸν πατέρα, καὶ γὰρ προλαβὼν Ἰούδας ὁ ἀδελφὸς ἐδήλωσεν αὐτῷ τὴν ἄφιξιν, ἀπαντησόμενος ἔξεισι καὶ καθʼ Ἡρώων πόλιν αὐτῷ συνέβαλεν. ὁ δʼ ὑπὸ τῆς χαρᾶς ἀπροσδοκήτου τε καὶ μεγάλης γενομένης μικροῦ δεῖν ἐξέλιπεν, ἀλλὰ ἀνεζωπύρησεν αὐτὸν Ἰώσηπος οὐδʼ αὐτὸς μὲν κρατῆσαι δυνηθεὶς ὡς μὴ ταὐτὸ παθεῖν ὑφʼ ἡδονῆς, οὐ μέντοι τὸν αὐτὸν τρόπον τῷ πατρὶ γενόμενος ἥττων τοῦ πάθους."},{"number":185,"text":"ἔπειτα τὸν μὲν ἠρέμα κελεύσας ὁδεύειν αὐτὸς δὲ παραλαβὼν πέντε τῶν ἀδελφῶν ἠπείγετο πρὸς τὸν βασιλέα φράσων αὐτῷ παραγενόμενον μετὰ τοῦ γένους τὸν Ἰάκωβον. ὁ δὲ τοῦτο χαίρων ἤκουσε καὶ τὸν Ἰώσηπον ἐκέλευσεν αὐτῷ λέγειν τίνι βίῳ τερπόμενοι διατελοῦσιν ὡς αὐτοῖς τοῦτον ἐπιτρέψειε διάγειν."},{"number":186,"text":"ὁ δὲ ποιμένας ἀγαθοὺς αὐτοὺς ἔλεγε καὶ μηδενὶ τῶν ἄλλων ἢ τούτῳ μόνῳ προσανέχειν, τοῦ τε μὴ διαζευγνυμένους ἀλλʼ ἐν ταὐτῷ τυγχάνοντας ἐπιμελεῖσθαι τοῦ πατρὸς προνοούμενος τοῦ τε τοῖς Αἰγυπτίοις εἶναι προσφιλεῖς μηδὲν πράττοντας τῶν αὐτῶν ἐκείνοις· Αἰγυπτίοις γὰρ ἀπειρημένον ἦν περὶ νομὰς ἀναστρέφεσθαι."},{"number":187,"text":"Τοῦ δʼ Ἰακώβου παραγενομένου πρὸς τὸν βασιλέα καὶ ἀσπαζομένου τε καὶ κατευχομένου περὶ τῆς βασιλείας αὐτῷ ὁ Φαραώθης ἐπυνθάνετο, πόσον ἤδη βεβιωκὼς εἴη χρόνον."},{"number":188,"text":"τοῦ δʼ ἑκατὸν ἔτη καὶ τριάκοντα γεγονέναι φήσαντος ἐθαύμασε τοῦ μήκους τῆς ζωῆς τὸν Ἰάκωβον. εἰπόντος δʼ ὡς ἥττονα τῶν προγόνων εἴη βεβιωκὼς ἔτη συνεχώρησεν αὐτῷ ζῆν μετὰ τῶν τέκνων ἐν Ἡλιουπόλει· ἐν ἐκείνῃ γὰρ καὶ οἱ ποιμένες αὐτοῦ τὰς νομὰς εἶχον."},{"number":189,"text":"Ὁ δὲ λιμὸς τοῖς Αἰγυπτίοις ἐπετείνετο καὶ τὸ δεινὸν ἀπορώτερον ἔτι καὶ μᾶλλον αὐτοῖς ἐγίνετο μήτε τοῦ ποταμοῦ ἐπάρδοντος, οὐ γὰρ ηὔξανε, μήτε ὕοντος τοῦ θεοῦ πρόνοιάν τε μηδεμίαν αὐτῶν ὑπʼ ἀγνοίας πεποιημένων. καὶ τοῦ Ἰωσήπου τὸν σῖτον ἐπὶ χρήμασιν αὐτοῖς διδόντος, ὡς δὲ ταῦτʼ αὐτοῖς ἐπέλιπε, τῶν βοσκημάτων ἐωνοῦντο τὸν σῖτον καὶ τῶν ἀνδραπόδων·"},{"number":190,"text":"οἷς δὲ καὶ γῆς τις ἦν μοῖρα ταύτην παρεχώρουν ἐπὶ τιμῇ τροφῆς. οὕτως τε τοῦ βασιλέως πάσης αὐτῶν τῆς περιουσίας κυρίου γεγενημένου, μετῳκίσθησαν ἄλλος ἀλλαχοῦ, ὅπως βεβαία γένηται τῷ βασιλεῖ τῆς χώρας τούτων ἡ κτῆσις, πλὴν τῶν ἱερέων· τούτοις γὰρ ἔμενεν ἡ χώρα αὐτῶν."},{"number":191,"text":"ἐδούλου τʼ αὐτῶν οὐ τὰ σώματα μόνον τὸ δεινόν, ἀλλὰ καὶ τὰς διανοίας καὶ τὸ λοιπὸν εἰς ἀσχήμονα τῆς τροφῆς εὐπορίαν αὐτοὺς κατηνάγκαζε. λωφήσαντος δὲ τοῦ κακοῦ καὶ τοῦ τε ποταμοῦ τῆς γῆς ἐπιβάντος καὶ ταύτης τοὺς καρποὺς ἀφθόνως ἐκφερούσης,"},{"number":192,"text":"ὁ Ἰώσηπος εἰς ἑκάστην παραγενόμενος πόλιν καὶ συλλέγων ἐν αὐταῖς τὸ πλῆθος τήν τε γῆν αὐτοῖς, ἣν ἐκείνων παραχωρούντων βασιλεὺς ἔχειν ἠδύνατο καὶ καρποῦσθαι μόνος, εἰς ἅπαν ἐχαρίζετο καὶ κτῆμα ἴδιον ἡγουμένους φιλεργεῖν παρεκάλει τὴν πέμπτην τῶν καρπῶν τῷ βασιλεῖ τελοῦντας ὑπὲρ τῆς χώρας, ἣν δίδωσιν αὐτοῖς οὖσαν αὐτοῦ."},{"number":193,"text":"τοὺς δὲ παρʼ ἐλπίδας κυρίους τῆς γῆς καθισταμένους χαρά τε ἐλάμβανε καὶ ὑφίσταντο τὰ προστάγματα. καὶ τούτῳ τῷ τρόπῳ τό τε ἀξίωμα παρὰ τοῖς Αἰγυπτίοις αὐτοῦ μεῖζον Ἰώσηπος ἀπεργάζεται, καὶ πλείω γε τὴν εὔνοιαν τῷ βασιλεῖ παρʼ αὐτῶν, ὅ τε τοῦ τελεῖν τὴν πέμπτην τῶν καρπῶν νόμος ἔμεινε καὶ μέχρι τῶν ὕστερον βασιλέων."}],"8":[{"number":194,"text":"Ἰάκωβος δὲ ἑπτακαιδέκατον ἔτος ἐν Αἰγύπτῳ διατρίψας καὶ νόσῳ χρησάμενος παρόντων αὐτῷ τῶν υἱῶν ἀπέθανεν, ἐπευξάμενος τοῖς μὲν κτῆσιν ἀγαθῶν καὶ προειπὼν αὐτοῖς κατὰ προφητείαν, πῶς μέλλει τῶν ἐκ τῆς γενεᾶς αὐτῶν ἕκαστος κατοικεῖν τὴν Χαναναίαν· τοῦτο δὴ καὶ πολλοῖς ὕστερον χρόνοις ἐγένετο·"},{"number":195,"text":"Ἰωσήπου δʼ ἐγκώμιον διεξελθών, ὅτι μὴ μνησικακήσειε τοῖς ἀδελφοῖς, ἀλλὰ καὶ τούτου πλέον χρηστὸς εἰς αὐτοὺς ἐγένετο δωρησάμενος αὐτοὺς ἀγαθοῖς, οἷς οὐδὲ εὐεργέτας τινὲς ἠμείψαντο, προσέταξε τοῖς ἰδίοις παισίν, ἵνα τοὺς Ἰωσήπου παῖδας Ἐφρὴν καὶ Μανασσῆν εἰς τὸν αὐτῶν ἀριθμὸν προσῶνται διαιρούμενοι μετʼ αὐτῶν τὴν Χαναναίαν, περὶ ὧν ὕστερον ἐροῦμεν·"},{"number":196,"text":"ἠξίου μέντοι καὶ ταφῆς ἐν Νεβρῶνι τυγχάνειν· τελευτᾷ δὲ βιοὺς ἔτη τὰ πάντα τριῶν δέοντα πεντήκοντα καὶ ἑκατόν, μηδενὸς μὲν τῶν προγόνων ἀπολειφθεὶς ἐπʼ εὐσεβείᾳ τοῦ θεοῦ, τυχὼν δὲ ἀμοιβῆς ἧς δίκαιον ἦν τοὺς οὕτως ἀγαθοὺς γεγονότας. Ἰώσηπος δὲ συγχωρήσαντος αὐτῷ τοῦ βασιλέως τὸν τοῦ πατρὸς νεκρὸν εἰς Νεβρῶνα κομίσας ἐκεῖ θάπτει πολυτελῶς."},{"number":197,"text":"τῶν δʼ ἀδελφῶν οὐ βουλομένων αὐτῷ συνυποστρέφειν, δέος γὰρ αὐτοὺς εἶχε μὴ τεθνηκότος αὐτοῖς τοῦ πατρὸς τιμωρήσαιτο τῆς εἰς αὐτὸν ἐπιβουλῆς οὐκέτʼ ὄντος ᾧ χαρίζοιτο τὴν πρὸς αὐτοὺς μετριότητα, πείθει μηδὲν ὑφορᾶσθαι μηδʼ ἔχειν αὐτὸν διʼ ὑποψίας, ἀγαγὼν δὲ μετʼ αὐτοῦ κτῆσιν πολλὴν ἐχαρίσατο καὶ πάσῃ περὶ αὐτοὺς σπουδῇ χρώμενος οὐκ ἀπέλιπε."},{"number":198,"text":"Τελευτᾷ δὲ καὶ οὗτος ἔτη βιώσας ἑκατὸν καὶ δέκα θαυμάσιος τὴν ἀρετὴν γενόμενος καὶ λογισμῷ πάντα διοικῶν καὶ τὴν ἐξουσίαν ταμιευόμενος, ὃ δὴ καὶ τῆς τοιαύτης εὐδαιμονίας αἴτιον αὐτῷ παρὰ τοῖς Αἰγυπτίοις ἀλλαχόθεν ἥκοντι καὶ μετὰ τοιαύτης κακοπραγίας, μεθʼ ἧς προειρήκαμεν, ὑπῆρχε."},{"number":199,"text":"τελευτῶσι δʼ αὐτοῦ καὶ οἱ ἀδελφοὶ ζήσαντες εὐδαιμόνως ἐπὶ τῆς Αἰγύπτου. καὶ τούτων μὲν τὰ σώματα κομίσαντες μετὰ χρόνον οἱ ἀπόγονοι καὶ οἱ παῖδες ἔθαψαν ἐν Νεβρῶνι,"},{"number":200,"text":"τὰ δὲ Ἰωσήπου ὀστᾶ ὕστερον, ὅτε μετανέστησαν ἐκ τῆς Αἰγύπτου οἱ Ἑβραῖοι, εἰς τὴν Χαναναίαν ἐκόμισαν· οὕτως γὰρ αὐτοὺς ὁ Ἰώσηπος ἐξώρκισε. τούτων οὖν ἕκαστος ὡς ἔσχε καὶ τίσι πόνοις ἐκράτησαν τῆς Χαναναίας σημανῶ προδιηγησάμενος τὴν αἰτίαν διʼ ἣν τὴν Αἴγυπτον ἐξέλιπον."}],"9":[{"number":201,"text":"Αἰγυπτίοις τρυφεροῖς καὶ ῥᾳθύμοις πρὸς πόνους οὖσι καὶ τῶν τε ἄλλων ἡδονῶν ἥττοσι καὶ δὴ καὶ τῆς κατὰ φιλοκέρδειαν συνέβη δεινῶς πρὸς τοὺς Ἑβραίους διατεθῆναι κατὰ φθόνον τῆς εὐδαιμονίας."},{"number":202,"text":"ὁρῶντες γὰρ τὸ τῶν Ἰσραηλιτῶν γένος ἀκμάζον καὶ διʼ ἀρετὴν καὶ τὴν πρὸς τὸ πονεῖν εὐφυΐαν πλήθει χρημάτων ἤδη καὶ λαμπρούς, κατʼ αὐτῶν αὔξεσθαι τούτους ὑπελάμβανον, ὧν τʼ ἦσαν ὑπὸ Ἰωσήπου τετυχηκότες διὰ χρόνου μῆκος λήθην λαβόντες καὶ τῆς βασιλείας εἰς ἄλλον οἶκον μετεληλυθυίας δεινῶς ἐνύβριζόν τε τοῖς Ἰσραηλίταις καὶ ταλαιπωρίας αὐτοῖς ποικίλας ἐπενόουν."},{"number":203,"text":"τόν τε γὰρ ποταμὸν εἰς διώρυχας αὐτοῖς πολλὰς προσέταξαν διατεμεῖν τείχη τε οἰκοδομῆσαι ταῖς πόλεσι καὶ χώματα, ὅπως ἂν εἴργοι τὸν ποταμὸν μὴ λιμνάζειν ἐπεκβαίνοντα, πυραμίδας τε ἀνοικοδομοῦντες ἐξετρύχουν ἡμῶν τὸ γένος, ὡς τέχνας τε παντοίας ἀναδιδάσκεσθαι καὶ τοῖς πόνοις γενέσθαι συνήθεις."},{"number":204,"text":"καὶ τετρακοσίων μὲν ἐτῶν χρόνον διήνυσαν ταῖς ταλαιπωρίαις· ἀντεφιλονείκουν γὰρ οἱ μὲν Αἰγύπτιοι τοῖς πόνοις ἐξαπολέσαι τοὺς Ἰσραηλίτας θέλοντες, οἱ δʼ ἀεὶ κρείττους φαίνεσθαι τῶν ἐπιταγμάτων."},{"number":205,"text":"Ἐν τούτοις δʼ ὄντων αὐτῶν τοῖς πράγμασιν αἰτία τοῦ μᾶλλον σπουδάσαι περὶ τὸν ἀφανισμὸν τοῦ γένους ἡμῶν τοῖς Αἰγυπτίοις προσεγένετο τοιαύτη· τῶν ἱερογραμματέων τις, καὶ γάρ εἰσι δεινοὶ περὶ τῶν μελλόντων τὴν ἀλήθειαν εἰπεῖν, ἀγγέλλει τῷ βασιλεῖ τεχθήσεσθαί τινα κατʼ ἐκεῖνον τὸν καιρὸν τοῖς Ἰσραηλίταις, ὃς ταπεινώσει μὲν τὴν Αἰγυπτίων ἡγεμονίαν, αὐξήσει δὲ τοὺς Ἰσραηλίτας τραφεὶς ἀρετῇ τε πάντας ὑπερβαλεῖ καὶ δόξαν ἀείμνηστον κτήσεται."},{"number":206,"text":"δείσας δʼ ὁ βασιλεὺς κατὰ γνώμην τὴν ἐκείνου κελεύει πᾶν τὸ γεννηθὲν ἄρσεν ὑπὸ τῶν Ἰσραηλιτῶν εἰς τὸν ποταμὸν ῥιπτοῦντας διαφθείρειν, παραφυλάσσειν τε τὰς ὠδῖνας τῶν Ἑβραίων γυναικῶν καὶ τοὺς τοκετοὺς αὐτῶν παρατηρεῖν τὰς Αἰγυπτίων μαίας·"},{"number":207,"text":"ὑπὸ γὰρ τούτων αὐτὰς ἐκέλευε μαιοῦσθαι, αἳ διὰ συγγένειαν ἔμελλον μὴ παραβήσεσθαι τὴν τοῦ βασιλέως βούλησιν· τοὺς μέντοι καταφρονήσαντας τοῦ προστάγματος καὶ σώζειν λάθρα τολμήσαντας τὸ τεχθὲν αὐτοῖς ἀναιρεῖσθαι σὺν τῇ γενεᾷ προσέταξεν."},{"number":208,"text":"δεινὸν οὖν τοῖς ὑπομένουσι τὸ πάθος, οὐ καθὸ παίδων ἀπεστεροῦντο καὶ γονεῖς ὄντες αὐτοὶ πρὸς τὴν ἀπώλειαν ὑπούργουν τῶν γεννωμένων, ἀλλὰ καὶ ἡ ἐπίνοια τῆς τοῦ γένους αὐτῶν ἐπιλείψεως, φθειρομένων μὲν τῶν τικτομένων, αὐτῶν δὲ διαλυθησομένων, χαλεπὴν αὐτοῖς καὶ δυσπαραμύθητον ἐποίει τὴν συμφοράν."},{"number":209,"text":"καὶ οἱ μὲν ἦσαν ἐν τούτῳ τῷ κακῷ· κρατήσειε δʼ ἂν οὐδεὶς τῆς τοῦ θεοῦ γνώμης οὐδὲ μυρίας τέχνας ἐπὶ τούτῳ μηχανησάμενος· ὅ τε γὰρ παῖς, ὃν προεῖπεν ὁ ἱερογραμματεύς, τρέφεται λαθὼν τὴν τοῦ βασιλέως φυλακὴν καὶ ἀληθὴς ἐπὶ τοῖς ἐξ αὐτοῦ γενησομένοις ὁ προειπὼν εὑρέθη. γίνεται δʼ οὕτως."},{"number":210,"text":"Ἀμαράμης τῶν εὖ γεγονότων παρὰ τοῖς Ἑβραίοις, ὡς δεδιὼς ὑπὲρ τοῦ παντὸς ἔθνους, μὴ σπάνει τῆς ἐπιτραφησομένης νεότητος ἐπιλείπῃ, καὶ χαλεπῶς ἐπʼ αὐτῷ φέρων, ἐκύει γὰρ αὐτῷ τὸ γύναιον, ἐν ἀμηχάνοις ἦν,"},{"number":211,"text":"πρὸς ἱκετείαν τοῦ θεοῦ τρέπεται παρακαλῶν οἶκτον ἤδη τινὰ λαβεῖν αὐτὸν ἀνθρώπων μηδὲν τῆς εἰς αὐτὸν θρησκείας παραβεβηκότων δοῦναί τʼ ἀπαλλαγὴν αὐτοῖς ὧν παρʼ ἐκεῖνον ἐκακοπάθουν τὸν καιρὸν καὶ τῆς ἐπʼ ἀπωλείᾳ τοῦ γένους αὐτῶν ἐλπίδος."},{"number":212,"text":"ὁ δὲ θεὸς ἐλεήσας αὐτὸν καὶ πρὸς τὴν ἱκεσίαν ἐπικλασθεὶς ἐφίσταται κατὰ τοὺς ὕπνους αὐτῷ καὶ μήτε ἀπογινώσκειν αὐτὸν περὶ τῶν μελλόντων παρεκάλει τήν τε εὐσέβειαν αὐτῶν ἔλεγε διὰ μνήμης ἔχειν καὶ τὴν ὑπὲρ αὐτῆς ἀμοιβὴν ἀεὶ παρέξειν, ἤδη μὲν καὶ τοῖς προγόνοις αὐτῶν δωρησάμενος τὸ γενέσθαι τοσοῦτον πλῆθος αὐτοὺς ἐξ ὀλίγων."},{"number":213,"text":"καὶ Ἅβραμον μὲν μόνον ἐκ τῆς Μεσοποταμίας εἰς τὴν Χαναναίαν παραγενόμενον εὐδαιμονῆσαι τά τε ἄλλα καὶ τῆς γυναικὸς αὐτῷ πρὸς γονὴν ἀκάρπως ἐχούσης πρότερον ἔπειτα κατὰ τὴν αὐτοῦ βούλησιν ἀγαθῆς πρὸς τοῦτο γενομένης τεκνῶσαι παῖδας καὶ καταλιπεῖν μὲν Ἰσμαήλῳ καὶ τοῖς ἐξ αὐτοῦ τὴν Ἀράβων χώραν, τοῖς δʼ ἐκ Κατούρας τὴν Τρωγλοδῦτιν, Ἰσάκῳ δὲ τὴν Χαναναίαν."},{"number":214,"text":"ὅσα τε πολεμῶν κατὰ τὴν ἐμήν, φησί, συμμαχίαν ἠνδραγάθησε κἂν ἀσεβεῖς εἶναι δόξητε καὶ μὴ διὰ μνήμης ἔχοντες. Ἰάκωβον δὲ καὶ τοῖς οὐχ ὁμοφύλοις γνώριμον εἶναι συμβέβηκεν ἐπί τε μεγέθει τῆς εὐδαιμονίας μεθʼ ἧς ἐβίωσε καὶ παισὶ τοῖς αὐτοῦ κατέλιπεν, οὗ μετὰ ἑβδομήκοντα τῶν πάντων εἰς Αἴγυπτον ἀφικομένου ὑπὲρ ἑξήκοντά που μυριάδας ἤδη γεγόνατε."},{"number":215,"text":"νῦν δʼ ἐμὲ τοῦ κοινῇ συμφέροντος ὑμῶν ἴστε προνοούμενον καὶ τῆς σῆς εὐκλείας· ὁ παῖς γὰρ οὗτος, οὗ τὴν γένεσιν Αἰγύπτιοι δεδιότες κατέκριναν ἀπολλύναι τὰ ἐξ Ἰσραηλιτῶν τικτόμενα, σὸς ἔσται καὶ λήσεται μὲν τοὺς ἐπʼ ὀλέθρῳ παραφυλάσσοντας,"},{"number":216,"text":"τραφεὶς δὲ παραδόξως τὸ μὲν Ἑβραίων γένος τῆς παρʼ Αἰγυπτίοις ἀνάγκης ἀπολύσει, μνήμης δὲ ἐφʼ ὅσον μενεῖ χρόνον τὰ σύμπαντα τεύξεται παρʼ ἀνθρώποις οὐχ Ἑβραίοις μόνον ἀλλὰ καὶ παρὰ τοῖς ἀλλοφύλοις, ἐμοῦ τοῦτο χαριζομένου σοί τε καὶ τοῖς ἐκ σοῦ γενησομένοις. ἔσται δʼ αὐτῷ καὶ ὁ ἀδελφὸς τοιοῦτος, ὥστε τὴν ἐμὴν ἕξειν ἱερωσύνην αὐτόν τε καὶ τοὺς ἐγγόνους αὐτοῦ διὰ παντὸς τοῦ χρόνου."},{"number":217,"text":"Ταῦτα τῆς ὄψεως αὐτῷ δηλωσάσης περιεγερθεὶς ὁ Ἀμαράμης ἐδήλου τῇ Ἰωχαβέλῃ, γυνὴ δʼ ἦν αὐτοῦ, καὶ τὸ δέος ἔτι μεῖζον διὰ τὴν τοῦ ὀνείρου πρόρρησιν αὐτοῖς συνίστατο· οὐ γὰρ ὡς περὶ παιδὸς μόνον εὐλαβεῖς ἦσαν, ἀλλὰ καὶ ὡς ἐπὶ μεγέθει τοσαύτης εὐδαιμονίας ἐσομένου."},{"number":218,"text":"τοῖς μέντοι προκατηγγελμένοις ὑπὸ τοῦ θεοῦ πίστιν ὁ τοκετὸς τῆς γυναικὸς παρεῖχε λαθούσης τοὺς φύλακας διὰ τὴν τῶν ὠδίνων ἐπιείκειαν καὶ τῷ μὴ βιαίας αὐτῇ προσπεσεῖν τὰς ἀλγηδόνας. καὶ τρεῖς μὲν μῆνας παρʼ αὐτοῖς τρέφουσι λανθάνοντες·"},{"number":219,"text":"ἔπειτα δὲ δείσας Ἀμαράμης, μὴ κατάφωρος γένηται καὶ πεσὼν ὑπὸ τὴν τοῦ βασιλέως ὀργὴν αὐτός τε ἀπόληται μετὰ τοῦ παιδίου καὶ τοῦ θεοῦ τὴν ἐπαγγελίαν ἀφανίσειεν, ἔγνω μᾶλλον ἐπὶ τούτῳ ποιήσασθαι τὴν τοῦ παιδὸς σωτηρίαν καὶ πρόνοιαν ἢ τῷ λήσεσθαι πεπιστευκώς, τοῦτο δʼ ἦν ἄδηλον, ἐναποκινδυνεύειν οὐ τῷ παιδὶ μόνον κρυφαίως τρεφομένῳ ἀλλὰ καὶ αὐτῷ·"},{"number":220,"text":"τὸν δὲ θεὸν ἡγεῖτο πᾶσαν ἐκποριεῖν ἀσφάλειαν ὑπὲρ τοῦ μηδὲν ψευδὲς γενέσθαι τῶν εἰρημένων. ταῦτα κρίναντες μηχανῶνται πλέγμα βίβλινον ἐμφερὲς τῇ κατασκευῇ κοιτίδι μεγέθους αὐτὸ ποιήσαντες αὐτάρκους εἰς τὸ μετʼ εὐρυχωρίας ἐναποκεῖσθαι τὸ βρέφος, ἔπειτα χρίσαντες ἀσφάλτῳ,"},{"number":221,"text":"τῷ γὰρ ὕδατι τὴν διὰ τῶν πλεγμάτων ἀποφράττειν εἴσοδον ἡ ἄσφαλτος πέφυκεν, ἐντιθέασι τὸ παιδίον καὶ κατὰ τοῦ ποταμοῦ βαλόντες εἴασαν ἐπὶ τῷ θεῷ τὴν σωτηρίαν αὐτοῦ. καὶ τὸ μὲν ὁ ποταμὸς παραλαβὼν ἔφερε, Μαριάμη δὲ τοῦ παιδὸς ἀδελφὴ κελευσθεῖσα ὑπὸ τῆς μητρὸς ἀντιπαρεξῄει φερόμενον ὅποι χωρήσει ὀψομένη τὸ πλέγμα."},{"number":222,"text":"ἔνθα καὶ ἔδειξεν ὁ θεὸς μηδὲν μὲν τὴν ἀνθρωπίνην σύνεσιν, πᾶν δʼ ὅ τι καὶ βουληθείη πράττειν αὐτὸ τέλους ἀγαθοῦ τυγχάνον, καὶ διαμαρτάνοντας μὲν τοὺς ὑπὲρ οἰκείας ἀσφαλείας ἄλλων κατακρίνοντας ὄλεθρον καὶ πολλῇ περὶ τούτου χρησαμένους σπουδῇ,"},{"number":223,"text":"σωζομένους δʼ ἐκ παραδόξου καὶ σχεδὸν ἐκ μέσου τῶν κακῶν εὑρισκομένους τὴν εὐπραγίαν τοὺς κινδυνεύοντας τῇ τοῦ θεοῦ γνώμῃ. τοιοῦτον δέ τι καὶ περὶ τὸν παῖδα τοῦτον γενόμενον ἐμφανίζει τὴν ἰσχὺν τοῦ θεοῦ."},{"number":224,"text":"Θέρμουθις ἦν θυγάτηρ τοῦ βασιλέως. αὕτη παίζουσα παρὰ τὰς ᾐόνας τοῦ ποταμοῦ καὶ φερόμενον ὑπὸ τοῦ ῥεύματος θεασαμένη τὸ πλέγμα κολυμβητὰς ἐπιπέμπει κελεύσασα τὴν κοιτίδα πρὸς αὐτὴν ἐκκομίσαι. παραγενομένων δὲ τῶν ἐπὶ τούτῳ σταλέντων μετὰ τῆς κοιτίδος ἰδοῦσα τὸ παιδίον ὑπερηγάπησε μεγέθους τε ἕνεκα καὶ κάλλους·"},{"number":225,"text":"τοσαύτῃ γὰρ ὁ θεὸς περὶ Μωυσῆν ἐχρήσατο σπουδῇ, ὡς ὑπʼ αὐτῶν τῶν ψηφισαμένων διὰ τὴν αὐτοῦ γένεσιν καὶ τῶν ἄλλων τῶν ἐκ τοῦ Ἑβραίων γένους ἀπώλειαν ποιῆσαι τροφῆς καὶ ἐπιμελείας ἀξιωθῆναι. κελεύει τε γύναιον ἡ Θέρμουθις ἀχθῆναι παρέξον θηλὴν τῷ παιδίῳ."},{"number":226,"text":"μὴ προσεμένου δὲ αὐτοῦ τὴν θηλὴν ἀλλʼ ἀποστραφέντος καὶ τοῦτʼ ἐπὶ πολλῶν ποιήσαντος γυναικῶν ἡ Μαριάμη παρατυγχάνουσα τοῖς γινομένοις οὐχ ὥστε ἐκ παρασκευῆς δοκεῖν ἀλλὰ κατὰ θεωρίαν, μάτην, εἶπεν, ὦ βασίλισσα, ταύτας ἐπὶ τροφῇ τοῦ παιδὸς μετακαλῇ τὰς γυναῖκας, αἳ μηδὲν πρὸς αὐτὸ συγγενὲς ἔχουσιν. εἰ μέντοι τινὰ τῶν Ἑβραΐδων γυναικῶν ἀχθῆναι ποιήσειας, τάχα ἂν προσοῖτο θηλὴν ὁμοφύλου."},{"number":227,"text":"δόξασαν δὲ λέγειν εὖ κελεύει τοῦτʼ αὐτὴν ἐκπορίσαι καὶ τῶν γαλουχουσῶν τινα μεταθεῖν. ἡ δὲ τοιαύτης ἐξουσίας λαβομένη παρῆν ἄγουσα τὴν μητέρα μηδενὶ γινωσκομένην. καὶ τὸ παιδίον ἀσμενίσαν πως προσφύεται τῇ θηλῇ, καὶ δεηθείσης γε τῆς βασιλίδος πιστεύεται τὴν τροφὴν τοῦ παιδίου πρὸς τὸ πᾶν."},{"number":228,"text":"Κἀπʼ αὐτῶν τὴν ἐπίκλησιν ταύτην τῶν συμβεβηκότων ἔθετο εἰς τὸν ποταμὸν ἐμπεσόντι· τὸ γὰρ ὕδωρ μῶυ Αἰγύπτιοι καλοῦσιν, ἐσῆς δὲ τοὺς ἐξ ὕδατος σωθέντας. συνθέντες οὖν ἐξ ἀμφοτέρων τὴν προσηγορίαν αὐτῷ ταύτην τίθενται."},{"number":229,"text":"καὶ ἦν ὁμολογουμένως κατὰ τὴν τοῦ θεοῦ πρόρρησιν φρονήματός τε μεγέθει καὶ πόνων καταφρονήσει Ἑβραίων ἄριστος. Ἅβραμος γὰρ αὐτῷ πατὴρ ἕβδομος. Ἀμαράμου γὰρ αὐτὸς ἦν παῖς τοῦ Καάθου, Καάθου δὲ πατὴρ Λευὶς ὁ τοῦ Ἰακώβου, ὃς ἦν Ἰσάκῳ γενόμενος, Ἁβράμου δὲ οὗτος ἦν."},{"number":230,"text":"σύνεσις δὲ οὐ κατὰ τὴν ἡλικίαν ἐφύετʼ αὐτῷ τοῦ δὲ ταύτης μέτρου πολὺ κρείττων, καὶ πρεσβυτέραν διεδείκνυεν ταύτης τὴν περιουσίαν ἐν ταῖς παιδιαῖς, καὶ μειζόνων τῶν ὑπʼ ἀνδρὸς γενησομένων ἐπαγγελίαν εἶχε τὰ τότε πραττόμενα. καὶ τριετεῖ μὲν αὐτῷ γεγενημένῳ θαυμαστὸν ὁ θεὸς τὸ τῆς ἡλικίας ἐξῆρεν ἀνάστημα,"},{"number":231,"text":"πρὸς δὲ κάλλος οὐδεὶς ἀφιλότιμος ἦν οὕτως, ὡς Μωυσῆν θεασάμενος μὴ ἐκπλαγῆναι τῆς εὐμορφίας, πολλοῖς τε συνέβαινε καθʼ ὁδὸν φερομένῳ συντυγχάνουσιν ἐπιστρέφεσθαι μὲν ὑπὸ τῆς ὄψεως τοῦ παιδός, ἀφιέναι δὲ τὰ σπουδαζόμενα καὶ τῇ θεωρίᾳ προσευσχολεῖν αὐτοῦ· καὶ γὰρ ἡ χάρις ἡ παιδικὴ πολλὴ καὶ ἄκρατος περὶ αὐτὸν οὖσα κατεῖχε τοὺς ὁρῶντας."},{"number":232,"text":"Ὄντα δʼ αὐτὸν τοιοῦτον ἡ Θέρμουθις παῖδα ποιεῖται γονῆς γνησίας οὐ μεμοιραμένη, καί ποτε κομίσασα τὸν Μωυσῆν πρὸς τὸν πατέρα ἐπεδείκνυε τοῦτον καὶ ὡς φροντίσειε διαδοχῆς, εἰ καὶ βουλήσει θεοῦ μὴ τύχοι παιδὸς γνησίου, πρὸς αὐτόν τε ἔλεγεν, ἀναθρεψαμένη παῖδα μορφῇ τε θεῖον καὶ φρονήματι γενναῖον, θαυμασίως δὲ αὐτὸν καὶ παρὰ τῆς τοῦ ποταμοῦ λαβοῦσα χάριτος ἐμαυτῆς μὲν ἡγησάμην παῖδα ποιήσασθαι, τῆς δὲ σῆς βασιλείας διάδοχον."},{"number":233,"text":"ταῦτα λέγουσα ταῖς τοῦ πατρὸς χερσὶν ἐνετίθει τὸ βρέφος, ὁ δὲ λαβὼν καὶ προστερνισάμενος κατὰ φιλοφρόνησιν χάριν τῆς θυγατρὸς ἐπιτίθησιν αὐτῷ τὸ διάδημα· καταφέρει δʼ ὁ Μωυσῆς εἰς τὴν γῆν περιελόμενος αὐτὸ κατὰ νηπιότητα δῆθεν ἐπέβαινέ τε αὐτῷ τοῖς ποσί."},{"number":234,"text":"καὶ τοῦτο ἔδοξεν οἰωνὸν ἐπὶ τῇ βασιλείᾳ φέρειν. θεασάμενος δʼ ὁ ἱερογραμματεὺς ὁ καὶ τὴν γένεσιν αὐτοῦ προειπὼν ἐπὶ ταπεινώσει τῆς Αἰγυπτίων ἀρχῆς ἐσομένην ὥρμησεν ἀποκτεῖναι,"},{"number":235,"text":"καὶ δεινὸν ἀνακραγών, οὗτος, εἶπε, βασιλεῦ, ὁ παῖς ἐκεῖνος, ὃν κτείνασιν ἡμῖν ἐδήλωσεν ὁ θεὸς ἀφόβοις εἶναι, μαρτυρεῖ τῇ προαγορεύσει τοῦ γεγονότος ἐπιβεβηκὼς ἡγεμονίᾳ τῇ σῇ καὶ πατῶν τὸ διάδημα. τοῦτον οὖν ἀνελὼν Αἰγυπτίοις μὲν τὸ ἀπʼ αὐτοῦ δέος ἄνες, Ἑβραίοις δὲ τὴν ἐλπίδα τοῦ διʼ αὐτὸν θάρσους ἀφελοῦ. φθάνει δʼ αὐτὸν ἡ Θέρμουθις ἐξαρπάσασα,"},{"number":236,"text":"καὶ πρὸς τὸν φόνον ὀκνηρὸς ἦν ὁ βασιλεὺς τοιοῦτον αὐτὸν τοῦ θεοῦ παρασκευάσαντος, ᾧ πρόνοια τῆς Μωυσέος σωτηρίας ἦν. ἐτρέφετο οὖν πολλῆς ἐπιμελείας τυγχάνων, καὶ τοῖς μὲν Ἑβραίοις ἐπʼ αὐτῷ παρῆν ἐλπὶς περὶ τῶν ὅλων,"},{"number":237,"text":"διʼ ὑποψίας δʼ εἶχον Αἰγύπτιοι τὴν ἀνατροφὴν αὐτοῦ· μηδενὸς δʼ ὄντος φανεροῦ, διʼ ὃν κἂν ἀπέκτεινεν αὐτὸν ὁ βασιλεὺς μηδὲν ὄντα ἢ συγγενοὺς διὰ τῆς εἰσποιήσεως ἢ τῶν ἄλλων τινός, ᾧ πλέον ὑπὲρ ὠφελείας τῆς Αἰγυπτίων ἐκ τοῦ προειδέναι τὰ μέλλοντα θαρρεῖν παρῆν, ἀπείχοντο τῆς ἀναιρέσεως αὐτοῦ."}],"10":[{"number":238,"text":"Μωυσῆς μὲν τῷ προειρημένῳ τρόπῳ γεννηθείς τε καὶ τραφεὶς καὶ παρελθὼν εἰς ἡλικίαν φανερὰν τοῖς Αἰγυπτίοις τὴν ἀρετὴν ἐποίησε καὶ τὸ ἐπὶ ταπεινώσει μὲν τῇ ἐκείνων, ἐπʼ αὐξήσει δὲ τῶν Ἑβραίων γεγονέναι τοιαύτης ἀφορμῆς λαβόμενος·"},{"number":239,"text":"Αἰθίοπες, πρόσοικοι δʼ εἰσὶ τοῖς Αἰγυπτίοις, ἐμβαλόντες εἰς χώραν αὐτῶν ἔφερον καὶ ἦγον τὰ τῶν Αἰγυπτίων. οἱ δʼ ὑπʼ ὀργῆς στρατεύουσιν ἐπʼ αὐτοὺς ἀμυνούμενοι τῆς καταφρονήσεως, καὶ τῇ μάχῃ κρατηθέντες οἱ μὲν αὐτῶν ἔπεσον οἱ δʼ αἰσχρῶς εἰς τὴν οἰκείαν διεσώθησαν φυγόντες."},{"number":240,"text":"ἐπηκολούθησαν δὲ διώκοντες Αἰθίοπες καὶ μαλακίας ὑπολαβόντες τὸ μὴ κρατεῖν ἁπάσης τῆς Αἰγύπτου τῆς χώρας ἐπὶ πλεῖον ἥπτοντο καὶ γευσάμενοι τῶν ἀγαθῶν οὐκέτʼ αὐτῶν ἀπείχοντο, ὡς δὲ τὰ γειτνιῶντα μέρη πρῶτον αὐτοῖς ἐπερχομένων οὐκ ἐτόλμων ἀντιστρατεύειν, προύβησαν ἄχρι Μέμφεως καὶ τῆς θαλάσσης οὐδεμιᾶς τῶν πόλεων ἀντέχειν δυνηθείσης."},{"number":241,"text":"τῷ δὲ κακῷ πιεζόμενοι πρὸς χρησμοὺς Αἰγύπτιοι καὶ μαντείας τρέπονται· συμβουλεύσαντος δʼ αὐτοῖς τοῦ θεοῦ συμμάχῳ χρήσασθαι τῷ Ἑβραίῳ κελεύει ὁ βασιλεὺς τὴν θυγατέρα παρασχεῖν τὸν Μωυσῆν στρατηγὸν αὐτῷ γενησόμενον."},{"number":242,"text":"ἡ δὲ ὅρκους ποιησαμένῳ, ὥστε μηδὲν διαθεῖναι κακόν, παραδίδωσιν ἀντὶ μεγάλης μὲν εὐεργεσίας κρίνουσα τὴν συμμαχίαν, κακίζουσα δὲ τοὺς ἱερέας, εἰ κτεῖναι προαγορεύσαντες αὐτὸν ὡς πολέμιον οὐκ ᾐδοῦντο νῦν χρῄζοντες αὐτοῦ τῆς ἐπικουρίας."},{"number":243,"text":"Μωυσῆς δὲ ὑπό τε τῆς Θερμούθιδος παρακληθεὶς καὶ ὑπὸ τοῦ βασιλέως ἡδέως προσδέχεται τὸ ἔργον· ἔχαιρον δʼ οἱ ἱερογραμματεῖς ἀμφοτέρων τῶν ἐθνῶν, Αἰγυπτίων μὲν ὡς τούς τε πολεμίους τῇ ἐκείνου κρατήσοντες ἀρετῇ καὶ τὸν Μωυσῆν ταὐτῷ δόλῳ κατεργασόμενοι, οἱ δὲ τῶν Ἑβραίων ὡς φυγεῖν αὐτοῖς ἐσομένου τοὺς Αἰγυπτίους διὰ τὸ Μωυσῆν αὐτοῖς στρατηγεῖν."},{"number":244,"text":"ὁ δὲ φθάσας πρὶν ἢ καὶ πυθέσθαι τοὺς πολεμίους τὴν ἔφοδον αὐτοῦ τὸν στρατὸν ἀναλαβὼν ἦγεν οὐ διὰ τοῦ ποταμοῦ ποιησάμενος τὴν ἐλασίαν, ἀλλὰ διὰ γῆς. ἔνθα τῆς αὐτοῦ συνέσεως θαυμαστὴν ἐπίδειξιν ἐποιήσατο·"},{"number":245,"text":"τῆς γὰρ γῆς οὔσης χαλεπῆς ὁδευθῆναι διὰ πλῆθος ἑρπετῶν, παμφορωτάτη γάρ ἐστι τούτων, ὡς καὶ τὰ παρʼ ἄλλοις οὐκ ὄντα μόνη τρέφειν δυνάμει τε καὶ κακίᾳ καὶ τῷ τῆς ὄψεως ἀσυνήθει διαφέροντα, τινὰ δʼ αὐτῶν ἐστι καὶ πετεινὰ ὡς λανθάνοντα μὲν ἀπὸ γῆς κακουργεῖν καὶ μὴ προϊδομένους ἀδικεῖν ὑπερπετῆ γενόμενα, νοεῖ πρὸς ἀσφάλειαν καὶ ἀβλαβῆ πορείαν τοῦ στρατεύματος στρατήγημα θαυμαστόν·"},{"number":246,"text":"πλέγματα γὰρ ἐμφερῆ κιβωτοῖς ἐκ βίβλου κατασκευάσας καὶ πληρώσας ἴβεων ἐκόμιζε. πολεμιώτατον δʼ ἐστὶν ὄφεσι τοῦτο τὸ ζῷον· φεύγουσί τε γὰρ ἐπερχομένας καὶ ἐφιστάμενοι καθάπερ ὑπʼ ἐλάφων ἁρπαζόμενοι καταπίνονται· χειροήθεις δʼ εἰσὶν αἱ ἴβεις καὶ πρὸς μόνον τὸ τῶν ὄφεων γένος ἄγριοι."},{"number":247,"text":"καὶ περὶ μὲν τούτων παρίημι νῦν γράφειν οὐκ ἀγνοούντων τῶν Ἑλλήνων τῆς ἴβιδος τὸ εἶδος. ὡς οὖν εἰς τὴν γῆν ἐνέβαλε τὴν θηριοτρόφον, ταύταις ἀπεμάχετο τὴν τῶν ἑρπετῶν φύσιν ἐπαφεὶς αὐτοῖς καὶ προπολεμούσαις χρώμενος. τοῦτον οὖν ὁδεύσας τὸν τρόπον οὐδὲ προμαθοῦσι παρῆν τοῖς Αἰθίοψι,"},{"number":248,"text":"καὶ συμβαλὼν αὐτοῖς κρατεῖ τῇ μάχῃ καὶ τῶν ἐλπίδων, ἃς εἶχον ἐπὶ τοὺς Αἰγυπτίους, ἀφαιρεῖται τάς τε πόλεις αὐτῶν ἐπῄει καταστρεφόμενος, καὶ φόνος πολὺς τῶν Αἰθιόπων ἐπράττετο. καὶ τῆς διὰ Μωυσῆν εὐπραγίας γευσάμενον τὸ τῶν Αἰγυπτίων στράτευμα πονεῖν οὐκ ἔκαμνεν, ὡς περὶ ἀνδραποδισμοῦ καὶ παντελοῦς ἀναστάσεως τὸν κίνδυνον εἶναι τοῖς Αἰθίοψι·"},{"number":249,"text":"καὶ τέλος συνελαθέντες εἰς Σαβὰν πόλιν βασίλειον οὖσαν τῆς Αἰθιοπίας, ἣν ὕστερον Καμβύσης Μερόην ἐπωνόμασεν ἀδελφῆς ἰδίας τοῦτο καλουμένης, ἐπολιορκοῦντο. ἦν δὲ δυσπολιόρκητον σφόδρα τὸ χωρίον τοῦ τε Νείλου περιέχοντος αὐτὴν καὶ κυκλουμένου ποταμῶν τε ἄλλων Ἀστάπου καὶ Ἀσταβόρα δύσμαχον τοῖς πειρωμένοις διαβαίνειν τὸ ῥεῦμα ποιούντων·"},{"number":250,"text":"ἡ γὰρ πόλις ἐντὸς οὖσα νῆσος οἰκεῖται τείχους τε αὐτῇ καρτεροῦ περιηγμένου καὶ πρὸς μὲν τοὺς πολεμίους πρόβλημα τοὺς ποταμοὺς ἔχουσα χώματά τε μεγάλα μεταξὺ τοῦ τείχους, ὥστε ἀνεπίκλυστον εἶναι βιαιότερον ὑπὸ πληθώρας φερομένων, ἅπερ καὶ τοῖς περαιωσαμένοις τοὺς ποταμοὺς ἄπορον ἐποίει τῆς πόλεως τὴν ἅλωσιν."},{"number":251,"text":"φέροντι τοίνυν ἀηδῶς τῷ Μωυσεῖ τὴν τοῦ στρατεύματος ἀργίαν, εἰς χεῖρας γὰρ οὐκ ἐτόλμων ἀπαντᾶν οἱ πολέμιοι, συνέτυχέ τι τοιοῦτον."},{"number":252,"text":"Θάρβις θυγάτηρ ἦν τοῦ Αἰθιόπων βασιλέως. αὕτη τὸν Μωυσῆν πλησίον τοῖς τείχεσι προσάγοντα τὴν στρατιὰν καὶ μαχόμενον γενναίως ἀποσκοποῦσα καὶ τῆς ἐπινοίας τῶν ἐγχειρήσεων θαυμάζουσα, καὶ τοῖς τε Αἰγυπτίοις αἴτιον ἀπεγνωκόσιν ἤδη τὴν ἐλευθερίαν τῆς εὐπραγίας ὑπολαμβάνουσα καὶ τοῖς Αἰθίοψιν αὐχοῦσιν ἐπὶ τοῖς κατʼ αὐτῶν κατωρθωμένοις τοῦ περὶ τῶν ἐσχάτων κινδύνου, εἰς ἔρωτα δεινὸν ὤλισθεν αὐτοῦ καὶ περιόντος τοῦ πάθους πέμπει πρὸς αὐτὸν τῶν οἰκετῶν τοὺς πιστοτάτους διαλεγομένη περὶ γάμου."},{"number":253,"text":"προσδεξαμένου δὲ τὸν λόγον ἐπὶ τῷ παραδοῦναι τὴν πόλιν καὶ ποιησαμένου πίστεις ἐνόρκους ἦ μὴν ἄξεσθαι γυναῖκα καὶ κρατήσαντα τῆς πόλεως μὴ παραβήσεσθαι τὰς συνθήκας, φθάνει τὸ ἔργον τοὺς λόγους. καὶ μετὰ τὴν ἀναίρεσιν τῶν Αἰθιόπων εὐχαριστήσας τῷ θεῷ συνετέλει τὸν γάμον Μωυσῆς καὶ τοὺς Αἰγυπτίους ἀπήγαγεν εἰς τὴν ἑαυτῶν."}],"11":[{"number":254,"text":"Οἱ δʼ ἐξ ὧν ἐσώζοντο ὑπὸ Μωυσέος μῖσος ἐκ τούτων πρὸς αὐτὸν ἀνελάμβανον καὶ θερμότερον ἅπτεσθαι τῶν κατʼ αὐτοῦ βουλευμάτων ἠξίουν, ὑπονοοῦντες μὲν μὴ διὰ τὴν εὐπραγίαν νεωτερίσειε κατὰ τὴν Αἴγυπτον, διδάσκοντες δὲ τὸν βασιλέα περὶ τῆς σφαγῆς."},{"number":255,"text":"ὁ δὲ καὶ καθʼ αὑτὸν μὲν εἶχε τὴν τοῦ πράγματος ἐπίνοιαν ὑπό τε φθόνου τῆς Μωυσέος στρατηγίας καὶ ὑπὸ δέους ταπεινώσεως, ἐπειχθεὶς δʼ ὑπὸ τῶν ἱερογραμματέων οἷός τε ἦν ἐγχειρεῖν τῇ Μωυσέος ἀναιρέσει."},{"number":256,"text":"φθάσας δὲ τὴν ἐπιβουλὴν καταμαθεῖν λαθὼν ὑπέξεισι· καὶ τῶν ὁδῶν φυλαττομένων ποιεῖται διὰ τῆς ἐρήμου τὸν δρασμὸν καὶ ὅθεν ἦν ὑπόνοια μὴ λαβεῖν τοὺς ἐχθρούς, ἄπορός τε ὢν τροφῆς ἀπηλλάττετο τῇ καρτερίᾳ καταφρονῶν,"},{"number":257,"text":"εἴς τε πόλιν Μαδιανὴν ἀφικόμενος πρὸς μὲν τῇ Ἐρυθρᾷ θαλάσσῃ κειμένην ἐπώνυμον δʼ ἑνὸς τῶν Ἁβράμῳ γενομένων ἐκ Κατούρας υἱῶν, καθεσθεὶς ἐπί τινος φρέατος ἐκ τοῦ κόπου καὶ τῆς ταλαιπωρίας ἠρέμει μεσημβρίας οὔσης οὐ πόρρω τῆς πόλεως. ἐνταῦθʼ αὐτῷ συνέβη καὶ πρᾶξις ἐκ διαίτης τῶν αὐτόθι συστήσασα τὴν ἀρετὴν αὐτοῦ καὶ πρὸς τὸ κρεῖττον ἀφορμὴν παρασχοῦσα."},{"number":258,"text":"Τῶν γὰρ χωρίων δυσύδρων ὄντων προκατελάμβανον οἱ ποιμένες τὰ φρέατα, ὅπως μὴ προεξαναλωμένου τοῦ ὕδατος ὑπὸ τῶν ἄλλων σπανίζοι ποτοῦ τὰ θρέμματα. παραγίνονται οὖν ἐπὶ τὸ φρέαρ ἑπτὰ παρθένοι ἀδελφαὶ Ῥαγουήλου θυγατέρες ἱερέως καὶ πολλῆς ἠξιωμένου τιμῆς παρὰ τοῖς ἐπιχωρίοις,"},{"number":259,"text":"αἳ τῶν τοῦ πατρὸς ποιμνίων ἐπιμελούμεναι διὰ τὸ ταύτην ὑπουργίαν εἶναι καὶ γυναιξὶν ἐπιχώριον παρὰ τοῖς Τρωγλοδύταις φθάσασαι τὸ αὔταρκες ἐκ τοῦ φρέατος ἀνέσπασαν ὕδωρ τοῖς ποιμνίοις εἰς δεξαμενάς, αἳ πρὸς ἐκδοχὴν τοῦ ὕδατος ἐγεγόνεισαν."},{"number":260,"text":"ἐπιστάντων δὲ ποιμένων ταῖς παρθένοις, ὥστʼ αὐτοὶ τοῦ ὕδατος κρατεῖν, Μωυσῆς δεινὸν ἡγησάμενος εἶναι περιιδεῖν ἀδικουμένας τὰς κόρας καὶ τὴν βίαν τὴν τῶν ἀνδρῶν ἐᾶσαι κρείττονα γενέσθαι τοῦ τῶν παρθένων δικαίου, τοὺς μὲν εἶρξε πλεονεκτεῖν ἐθέλοντας, ταῖς δὲ παρέσχε τὴν πρέπουσαν βοήθειαν."},{"number":261,"text":"αἱ δʼ εὐεργετηθεῖσαι παρῆσαν πρὸς τὸν πατέρα τήν τε ὕβριν τῶν ποιμένων αὐτῷ διηγούμεναι καὶ τὴν ἐπικουρίαν τοῦ ξένου παρεκάλουν τε μὴ ματαίαν αὐτῷ γενέσθαι τὴν εὐποιίαν μηδʼ ἀμοιβῆς ὑστεροῦσαν. ὁ δὲ τάς τε παῖδας ἀπεδέξατο τῆς περὶ τὸν εὐεργετηκότα σπουδῆς καὶ τὸν Μωυσῆν εἰς ὄψιν ἐκέλευεν ἄγειν αὐτῷ τευξόμενον χάριτος δικαίας."},{"number":262,"text":"ὡς δʼ ἧκε, τήν τε τῶν θυγατέρων αὐτῷ ἀπεσήμαινε μαρτυρίαν ἐπὶ τῇ βοηθείᾳ καὶ τῆς ἀρετῆς αὐτὸν θαυμάζων οὐκ εἰς ἀναισθήτους εὐεργεσιῶν καταθέσθαι τὴν ἐπικουρίαν ἔλεγεν, ἀλλʼ ἱκανοὺς ἐκτῖσαι χάριν καὶ τῷ μεγέθει τῆς ἀμοιβῆς ὑπερβαλεῖν τὸ μέτρον τῆς εὐποιίας."},{"number":263,"text":"ποιεῖται δʼ αὐτὸν υἱὸν καὶ μίαν τῶν θυγατέρων πρὸς γάμον δίδωσι τῶν τε θρεμμάτων, ἐν τούτοις γὰρ ἡ πᾶσα κτῆσις τὸ παλαιὸν ἦν τοῖς βαρβάροις, ἀποδείκνυσιν ἐπιμελητὴν καὶ δεσπότην."}],"12":[{"number":264,"text":"Καὶ Μωυσῆς μὲν τοιούτων τυχὼν τῶν παρὰ τοῦ Ἰεθεγλαίου, τοῦτο γὰρ ἦν ἐπίκλημα τῷ Ῥαγουήλῳ, διῆγεν αὐτόθι ποιμαίνων τὰ βοσκήματα. χρόνῳ δʼ ὕστερον νέμων ἐπὶ τὸ Σιναῖον καλούμενον ὄρος ἄγει τὰ ποίμνια·"},{"number":265,"text":"τοῦτο δʼ ἐστὶν ὑψηλότατον τῶν ταύτῃ ὀρῶν καὶ πρὸς νομὰς ἄριστον ἀγαθῆς φυομένης πόας καὶ διὰ τὸ δόξαν ἔχειν ἐνδιατρίβειν αὐτῷ τὸν θεὸν οὐ κατανεμηθείσης πρότερον, οὐ τολμώντων ἐμβατεύειν εἰς αὐτὸ τῶν ποιμένων· ἔνθα δὴ καὶ τέρας αὐτῷ συντυγχάνει θαυμάσιον."},{"number":266,"text":"πῦρ γὰρ θάμνου βάτων νεμόμενον τὴν περὶ αὐτὸν χλόην τό τε ἄνθος αὐτοῦ παρῆλθεν ἀβλαβὲς καὶ τῶν ἐγκάρπων κλάδων οὐδὲν ἠφάνισε καὶ ταῦτα τῆς φλογὸς πολλῆς καὶ ὀξυτάτης ὑπαρχούσης."},{"number":267,"text":"ὁ δὲ καὶ αὐτὴν μὲν ἔδεισε τὴν ὄψιν παράδοξον γενομένην, κατεπλάγη δʼ ἔτι μᾶλλον φωνὴν τοῦ πυρὸς ἀφιέντος καὶ ὀνομαστὶ καλέσαντος αὐτὸν καὶ ποιησαμένου λόγους, οἷς τό τε θάρσος αὐτοῦ τολμήσαντος παρελθεῖν εἰς χωρίον, εἰς ὃ μηδεὶς ἀνθρώπων πρότερον ἀφῖκτο διὰ τὸ εἶναι θεῖον, ἐσήμαινε καὶ συνεβούλευε τῆς φλογὸς ὡς πορρωτάτω χωρεῖν καὶ ἀρκεῖσθαι μὲν οἷς ἑώρακεν ἀγαθὸν ὄντα καὶ μεγάλων ἀνδρῶν ἔγγονον, πολυπραγμονεῖν δὲ μηδέν·"},{"number":268,"text":"τούτοις προηγόρευε περισσότερον τὴν ἐσομένην αὐτῷ δόξαν καὶ τιμὴν παρʼ ἀνθρώπων τοῦ θεοῦ συμπαρόντος, καὶ θαρροῦντα ἐκέλευεν εἰς τὴν Αἴγυπτον ἀπιέναι στρατηγὸν καὶ ἡγεμόνα τῆς Ἑβραίων πληθύος ἐσόμενον καὶ τῆς ὕβρεως τῆς ἐκεῖ τοὺς συγγενεῖς ἀπαλλάξοντα·"},{"number":269,"text":"καὶ γὰρ γῆν οἰκήσουσι, φησί, ταύτην εὐδαίμονα, ἣν Ἅβραμος ᾤκησεν ὁ ὑμέτερος πρόγονος καὶ τῶν πάντων ἀπολαύσουσιν ἀγαθῶν, εἰς ταῦτα σοῦ καὶ τῆς σῆς συνέσεως αὐτοῖς ἡγουμένης. ἐξαγαγόντα μέντοι τοὺς Ἑβραίους ἐκ τῆς Αἰγύπτου θυσίας ἐκέλευε χαριστηρίους ἀφικόμενον εἰς ἐκεῖνον ἐκτελέσαι τὸν τόπον. τοσαῦτα μὲν ἐκ τοῦ πυρὸς θεοκλυτεῖται."},{"number":270,"text":"Μωυσῆς δʼ ἐκπεπληγμένος οἷς τʼ εἶδε καὶ πολὺ μᾶλλον οἷς ἤκουσε, δυνάμει μὲν ἀπιστεῖν, ἔφη, τῇ σῇ, δέσποτα, ἣν αὐτός τε θρησκεύω καὶ προγόνοις οἶδα φανερὰν γενομένην, μανιωδέστερον ἢ κατὰ τὴν ἐμαυτοῦ φρόνησιν ἡγοῦμαι."},{"number":271,"text":"πλὴν ἀπορῶ, πῶς ἂν ἰδιώτης ἀνὴρ καὶ μηδεμιᾶς ἰσχύος εὐπορῶν ἢ πείσω λόγοις τοὺς οἰκείους ἀφέντας ἣν ἄρτι κατοικοῦσι γῆν ἕπεσθαί μοι πρὸς ἣν αὐτὸς ἡγοῦμαι, ἢ κἂν ἐκεῖνοι πεισθῶσι, πῶς ἂν βιασαίμην Φαραώθην ἐπιτρέψαι τὴν ἔξοδον τούτοις, ὧν τοῖς πόνοις καὶ τοῖς ἔργοις τὴν οἰκείαν αὔξουσιν εὐδαιμονίαν."},{"number":272,"text":"Ὁ δὲ θεὸς αὐτῷ περὶ πάντων συνεβούλευε θαρρεῖν ὑπισχνούμενος αὐτὸς παρέσεσθαι καὶ οὗ μὲν ἂν δέῃ λόγων, πειθὼ παρέξειν, οὗ δʼ ἂν ἔργων, ἰσχὺν χορηγήσειν, ἐκέλευέ τε τὴν βακτηρίαν ἐπὶ τὴν γῆν ἀφέντα πίστιν ὧν ὑπισχνεῖται λαμβάνειν. καὶ ποιήσαντος δράκων εἷρπε καὶ συνειλούμενος σπειρηδὸν ὡς διώκουσιν ἐπʼ ἀμύνῃ τὴν κεφαλὴν ἐπανέτεινεν· εἶτα πάλιν βάκτρον ἦν."},{"number":273,"text":"μετὰ τοῦτο δὲ καθεῖναι τὴν δεξιὰν εἰς τὸν κόλπον προσέταξεν. ὑπακούσας δὲ λευκὴν καὶ τιτάνῳ τὴν χρόαν ὁμοίαν προεκόμισεν· εἶτα εἰς τὸ σύνηθες κατέστη. κελευσθεὶς δὲ καὶ τοῦ πλησίον ὕδατος λαβὼν ἐπὶ τὴν γῆν ἐκχέαι ὁρᾷ τὴν χρόαν αἱματώδη γενομένην."},{"number":274,"text":"θαυμάζοντα δʼ ἐπὶ τούτοις θαρρεῖν παρεκελεύετο καὶ βοηθὸν εἰδέναι μέγιστον αὐτῷ συνεσόμενον καὶ σημείοις πρὸς τὸ πιστεύεσθαι παρὰ πᾶσι χρῆσθαι, ὅτι πεμφθεὶς ὑπʼ ἐμοῦ πάντα κατὰ τὰς ἐμὰς ἐντολὰς ποιεῖς. κελεύω δὲ μηδὲν ἔτι μελλήσαντα σπεύδειν εἰς τὴν Αἴγυπτον καὶ νυκτὸς καὶ ἡμέρας ἐπειγόμενον καὶ μὴ τρίβοντα τὸν χρόνον πλείω ποιεῖν τοῦτον Ἑβραίοις ἐν δουλείᾳ κακοπαθοῦσι."},{"number":275,"text":"Μωυσῆς δʼ οὐκ ἔχων ἀπιστεῖν οἷς ἐπηγγέλλετο τὸ θεῖον θεατής γε τοιούτων βεβαιωμάτων καὶ ἀκροατὴς γενόμενος, εὐξάμενος αὐτῷ καὶ πειραθῆναι ταύτης τῆς δυνάμεως ἐν Αἰγύπτῳ δεηθεὶς ἠντιβόλει μηδὲ ὀνόματος αὐτῷ γνῶσιν τοῦ ἰδίου φθονῆσαι, φωνῆς δʼ αὐτῷ μετεσχηκότι καὶ ὄψεως ἔτι καὶ τὴν προσηγορίαν εἰπεῖν, ἵνα θύων ἐξ ὀνόματος αὐτὸν παρεῖναι τοῖς ἱεροῖς παρακαλῇ."},{"number":276,"text":"καὶ ὁ θεὸς αὐτῷ σημαίνει τὴν αὑτοῦ προσηγορίαν οὐ πρότερον εἰς ἀνθρώπους παρελθοῦσαν, περὶ ἧς οὔ μοι θεμιτὸν εἰπεῖν. Μωυσεῖ μέντοι τὰ σημεῖα ταῦτα οὐ τότε μόνον, διὰ παντὸς δὲ ὁπότε δεηθείη συνετύγχανεν· ἐξ ὧν ἁπάντων πλέον περὶ τῆς ἀληθείας τῷ πυρὶ νέμων καὶ τὸν θεὸν εὐμενῆ παραστάτην ἕξειν πιστεύων τούς τε οἰκείους σώσειν ἤλπιζε καὶ τοὺς Αἰγυπτίους κακοῖς περιβαλεῖν."}],"13":[{"number":277,"text":"Καὶ πυθόμενος τὸν τῶν Αἰγυπτίων τεθνάναι βασιλέα Φαραώθην, ἐφʼ οὗπερ αὐτὸς ἔφυγε, δεῖται Ῥαγουήλου συγχωρῆσαι κατὰ ὠφέλειαν αὐτῷ τῶν συγγενῶν εἰς Αἴγυπτον ἐλθεῖν, καὶ παραλαβὼν τὴν Σαπφώραν ἣν γεγαμήκει τοῦ Ῥαγουήλου θυγατέρα καὶ τοὺς ἐξ αὐτῆς παῖδας Γῆρσον καὶ Ἐλεάζαρον ὥρμησεν εἰς τὴν Αἴγυπτον·"},{"number":278,"text":"τῶν δʼ ὀνομάτων τούτων Γῆρσος μὲν σημαίνει κατὰ Ἑβραίων διάλεκτον, ὅτι εἰς ξένην γῆν, Ἐλεάζαρος δὲ συμμάχῳ τῷ πατρῴῳ θεῷ χρησάμενον αὐτὸν Αἰγυπτίους διαφυγεῖν."},{"number":279,"text":"γενομένῳ δʼ αὐτῷ πλησίον τῶν ὅρων ὁ ἀδελφὸς Ἀαρὼν ὑπήντησε τοῦ θεοῦ κελεύσαντος, πρὸς ὃν ἀποσημαίνει τὰ ἐν τῷ ὄρει συντυχόντα καὶ τοῦ θεοῦ τὰς ἐντολάς. προϊοῦσι δʼ αὐτοῖς ὑπηντίαζον Ἑβραίων οἱ ἀξιολογώτατοι τὴν παρουσίαν αὐτοῦ μεμαθηκότες,"},{"number":280,"text":"οἷς Μωυσῆς τὰ σημεῖα ἐπεὶ πιθανῶς οὐκ ἦν λέγειν παρέσχεν αὐτῶν τὴν ὄψιν. οἱ δʼ ὑπʼ ἐκπλήξεως τῶν παρὰ δόξαν αὐτοῖς ὁρωμένων ἀνεθάρσουν καὶ περὶ τῶν ὅλων ἦσαν εὐέλπιδες, ὡς θεοῦ προνοουμένου τῆς ἀσφαλείας αὐτῶν."},{"number":281,"text":"Ἐπεὶ δὲ καταπειθεῖς εἶχεν ἤδη τοὺς Ἑβραίους Μωυσῆς καὶ οἷς ἂν κελεύσῃ τούτοις ἀκολουθήσειν ὁμολογοῦντας καὶ τῆς ἐλευθερίας ἐρῶντας, παραγίνεται πρὸς τὸν βασιλέα τὴν ἡγεμονίαν νεωστὶ παρειληφότα,"},{"number":282,"text":"καὶ ὅσα τε ὠφελήσειεν Αἰγυπτίους ὑπὸ Αἰθιόπων καταφρονουμένους καὶ διαρπαζομένης αὐτῶν τῆς χώρας ἐδήλου στρατηγίᾳ καὶ πόνοις χρησάμενος ὡς περὶ οἰκείων ὁτιδὴ κινδυνεύσειεν ἐπὶ τούτοις ὑπὸ αὐτῶν ἀμοιβὰς οὐ δικαίας κομιζόμενος ἀνεδίδασκεν,"},{"number":283,"text":"τά τε κατὰ τὸ Σιναῖον ὄρος αὐτῷ συντυχόντα καὶ τὰς τοῦ θεοῦ φωνὰς καὶ τὰ πρὸς πίστιν ὧν οὗτος αὐτῷ προστάξειεν ὑπʼ αὐτοῦ δειχθέντα σημεῖα καθʼ ἕκαστον ἐξετίθετο, παρεκάλει τε μὴ ἀπιστοῦντα τούτοις ἐμποδὼν ἵστασθαι τῇ τοῦ θεοῦ γνώμῃ."},{"number":284,"text":"Χλευάσαντος δὲ τοῦ βασιλέως Μωυσῆς ἔργῳ παρεῖχεν αὐτῷ βλέπειν τὰ σημεῖα τὰ κατὰ τὸ Σιναῖον ὄρος γενόμενα· ὁ δʼ ἀγανακτήσας πονηρὸν μὲν αὐτὸν ἀπεκάλει καὶ πρότερον φυγόντα τὴν παρʼ Αἰγυπτίοις δουλείαν καὶ νῦν ἐξ ἀπάτης αὐτοῦ τὴν ἄφιξιν πεποιημένον καὶ τερατουργίαις καὶ μαγείαις καταπλήξειν ἐπικεχειρηκότα."},{"number":285,"text":"καὶ ταῦθʼ ἅμα λέγων κελεύει τοὺς ἱερεῖς τὰς αὐτὰς ὄψεις αὐτῷ παρασχεῖν ὁρᾶν, ὡς Αἰγυπτίων σοφῶν ὄντων καὶ περὶ τὴν τούτων ἐπιστήμην, καὶ ὅτι μὴ μόνος αὐτὸς ἔμπειρος ὢν εἰς θεὸν δύναται τὸ ἐν αὐτῇ παράδοξον ἀναφέρων πιθανὸς ὥσπερ ἀπαιδεύτοις ὑπάρχειν. καὶ μεθεμένων ἐκείνων τὰς βακτηρίας δράκοντες ἦσαν."},{"number":286,"text":"Μωυσῆς δʼ οὐ καταπλαγείς, οὐδʼ αὐτὸς μέν, εἶπεν, ὦ βασιλεῦ, τῆς Αἰγυπτίων σοφίας καταφρονῶ, τοσῷδε μέντοι κρείττονα τὰ ὑπʼ ἐμοῦ πραττόμενα τῆς τούτων μαγείας καὶ τέχνης φημί, ὅσῳ τὰ θεῖα τῶν ἀνθρωπίνων διαφέρει. δείξω δὲ οὐ κατὰ γοητείαν καὶ πλάνην τῆς ἀληθοῦς δόξης τἀμὰ, κατὰ δὲ θεοῦ πρόνοιαν καὶ δύναμιν φαινόμενα."},{"number":287,"text":"καὶ ταῦτʼ εἰπὼν μεθίησιν ἐπὶ τῆς γῆς τὴν βακτηρίαν κελεύσας αὐτὴν εἰς ὄφιν μεταβαλεῖν· ἡ δʼ ἐπείθετο καὶ τὰς τῶν Αἰγυπτίων βακτηρίας, οἳ δράκοντες ἐδόκουν, περιιοῦσα κατήσθιε μέχρι πάσας ἀνήλωσεν· εἶτʼ εἰς τὸ αὑτῆς σχῆμα μεταπεσοῦσαν κομίζεται Μωυσῆς."},{"number":288,"text":"Ὁ δὲ βασιλεὺς οὐδὲν τούτῳ μᾶλλον πραχθέντι καταπλήττεται, προσοργισθεὶς δὲ καὶ μηδὲν αὐτῷ προχωρήσειν εἰπὼν ἐκ τῆς κατʼ Αἰγυπτίων σοφίας καὶ δεινότητος κελεύει τὸν ἐπὶ τῶν Ἑβραίων τεταγμένον μηδεμίαν αὐτοῖς ἄνεσιν παρέχειν τοῦ πονεῖν, ἀλλὰ πλείοσι τῶν πρότερον κακοῖς αὐτοὺς καταναγκάζειν."},{"number":289,"text":"ὁ δὲ ἄχυρον αὐτοῖς παρέχων εἰς τὴν πλινθείαν πρότερον οὐκέτι παρεῖχεν, ἀλλʼ ἡμέρας μὲν ἐπὶ τοῖς ἔργοις ταλαιπωρεῖν ἐποίει, νυκτὸς δὲ συνάγειν τὸ ἄχυρον. καὶ τοῦ δεινοῦ διπλασίονος ὄντος αὐτοῖς ἐν αἰτίαις Μωυσῆν εἶχον, ὡς τῶν ἔργων αὐτοῖς καὶ τῆς ταλαιπωρίας διʼ ἐκεῖνον χαλεπωτέρας γεγενημένης."},{"number":290,"text":"ὁ δʼ οὔτε πρὸς τὰς τοῦ βασιλέως ἀπειλὰς ἔκαμνεν οὔτε πρὸς τὰς τῶν Ἑβραίων μέμψεις ἐνεδίδου, τήν τε ψυχὴν παραστησάμενος πρὸς ἑκάτερον ἐπὶ τῷ πονεῖν καὶ τοῖς οἰκείοις ἐκπορίζειν τὴν ἐλευθερίαν ὑπῆρχε."},{"number":291,"text":"καὶ παραγενόμενος πρὸς τὸν βασιλέα ἔπειθεν αὐτὸν ἀπολύειν τοὺς Ἑβραίους ἐπὶ τὸ Σιναῖον ὄρος ἐκεῖ θύσοντας τῷ θεῷ, τοῦτο γὰρ αὐτὸν κεκελευκέναι, καὶ μηδὲν ἀντιπράττειν οἷς ἐκεῖνος βούλεται, τὴν δʼ εὐμένειαν αὐτοῦ περὶ παντὸς ποιούμενον συγχωρεῖν αὐτοῖς τὴν ἔξοδον, μὴ καὶ λάθῃ τούτων κωλυτὴς γενόμενος αὑτὸν αἰτιάσασθαι πάσχων ὅσα παθεῖν εἰκὸς τὸν ἀντιπράττοντα θεοῦ προστάγμασι·"},{"number":292,"text":"τοῖς γὰρ χόλον ἐπʼ αὐτοὺς κινήσασι θεῖον ἐξ ἁπάντων φύεσθαι τὰ δεινὰ, καὶ οὔτε γῆ τούτοις οὔτε ἀὴρ φίλος οὔτε γοναὶ τέκνων κατὰ φύσιν, ἀλλʼ ἐχθρὰ πάντα καὶ πολέμια. πειραθήσεσθαί τε τούτων Αἰγυπτίους ἔφασκε μετὰ καὶ τοῦ τὸν Ἑβραίων λαὸν ἀπελθεῖν ἐκ τῆς χώρας αὐτῶν ἀκόντων ἐκείνων."}],"14":[{"number":293,"text":"Τοῦ δὲ βασιλέως ἐκφαυλίζοντος τοὺς Μωυσέος λόγους καὶ μηδεμίαν ἐπιστροφὴν ἔτι ποιουμένου πάθη δεινὰ τοὺς Αἰγυπτίους κατελάμβανεν, ὧν ἕκαστον ἐκθήσομαι διά τε τὸ μὴ πρότερόν τισι συμβάντα τοῖς Αἰγυπτίοις εἰς πεῖραν ἐλθεῖν καὶ διὰ τὸ βούλεσθαι Μωυσῆν μηδὲν ὧν προεῖπεν αὐτοῖς ψευσάμενον ἐπιδεῖξαι, καὶ ὅτι συμφέρει τοῖς ἀνθρώποις μαθοῦσι φυλάττεσθαι ταῦτα ποιεῖν, ἐφʼ οἷς μὴ δυσαρεστήσῃ τὸ θεῖον μηδʼ εἰς ὀργὴν τραπὲν ἀμύνηται τῆς ἀδικίας αὐτούς."},{"number":294,"text":"ὁ γὰρ ποταμὸς αὐτοῖς αἱματώδης θεοῦ κελεύσαντος ἐρρύη πίνεσθαι μὴ δυνάμενος, καὶ πηγὴν ἑτέραν ὑδάτων οὐκ ἔχουσιν οὐ τὴν χρόαν μόνον ἦν τοιοῦτος, ἀλλὰ καὶ τοῖς πειρωμένοις ἀλγήματα καὶ πικρὰν ὀδύνην προσέφερεν."},{"number":295,"text":"ἦν δὲ τοιοῦτος μὲν Αἰγυπτίοις, Ἑβραίοις δὲ γλυκὺς καὶ πότιμος καὶ μηδὲν τοῦ κατὰ φύσιν παρηλλαγμένος. πρὸς οὖν τὸ παράδοξον ἀμηχανήσας ὁ βασιλεὺς καὶ δείσας περὶ τῶν Αἰγυπτίων συνεχώρει τοῖς Ἑβραίοις ἀπιέναι· καὶ τοῦ κακοῦ λωφήσαντος πάλιν τὴν γνώμην μετέβαλεν οὐκ ἐπιτρέπων τὴν ἄφοδον αὐτοῖς."},{"number":296,"text":"Ὁ θεὸς δὲ ἀγνωμονοῦντος καὶ μετὰ τὴν ἀπαλλαγὴν τῆς συμφορᾶς οὐκέτι σωφρονεῖν θέλοντος ἄλλην τοῖς Αἰγυπτίοις ἐπιφέρει πληγήν· βατράχων πλῆθος ἄπειρον τὴν γῆν αὐτῶν ἐπεβόσκετο, μεστὸς δὲ τούτων καὶ ὁ ποταμὸς ἦν, ὡς διαμωμένους τὸ ποτὸν τῷ τῶν ζῴων ἰχῶρι κεκακωμένον λαμβάνειν ἐναποθνησκόντων καὶ συνδιαφθειρομένων τῷ ὕδατι,"},{"number":297,"text":"ἥ τε χώρα μεστὴ κακῆς ἦν ἰλύος γεννωμένων τε καὶ ἀποθνησκόντων, τάς τε κατʼ οἶκον αὐτῶν διαίτας ἠφάνιζον ἐν βρωτοῖς εὑρισκόμενοι καὶ ποτοῖς καὶ ταῖς εὐναῖς αὐτῶν ἐπιπολάζοντες, ὀσμή τε χαλεπὴ ἦν καὶ δυσώδης ἀποθνησκόντων τῶν βατράχων καὶ ζώντων καὶ διεφθαρμένων."},{"number":298,"text":"ὑπὸ δὲ τούτων τῶν κακῶν ἐλαυνομένων τῶν Αἰγυπτίων τὸν Μωυσῆν ἐκέλευσεν ὁ βασιλεὺς οἴχεσθαι τοὺς Ἑβραίους λαβόντα, καὶ παραχρῆμα τοῦτʼ εἰπόντος ἠφάνιστο τῶν βατράχων τὸ πλῆθος καὶ ἥ τε γῆ καὶ ὁ ποταμὸς εἰς τὴν ἰδίαν φύσιν κατέστησαν."},{"number":299,"text":"Φαραώθης δὲ ἅμα τοῦ τε πάθους ἀπήλλακτο ἡ γῆ καὶ τῆς αἰτίας ἐπελέληστο καὶ τοὺς Ἑβραίους κατεῖχε, καὶ ὥσπερ πλειόνων παθημάτων φύσεις βουλόμενος μαθεῖν οὐκέτʼ ἠφίει τοῖς περὶ τὸν Μωυσῆν ἐξιέναι φόβῳ μᾶλλον ἢ φρονήσει ταύτην αὐτοῖς ἐπιτρέπων."},{"number":300,"text":"Πάλιν οὖν ἄλλου κακοῦ προσβολῇ μετῄει τὸ θεῖον αὐτοῦ τὴν ἀπάτην· φθειρῶν γὰρ τοῖς Αἰγυπτίοις ἐξήνθησεν ἄπειρόν τι πλῆθος ἔνδοθεν ἀναδιδομένων, ὑφʼ ὧν κακοὶ κακῶς ἀπώλλυντο μήτε λουτροῖς μήτε χρίσεσι φαρμάκων διαφθεῖραι τὸ γένος αὐτῶν δυνάμενοι."},{"number":301,"text":"καὶ πρὸς τοῦτο τὸ δεινὸν ὁ τῶν Αἰγυπτίων βασιλεὺς ταραχθεὶς καὶ δείσας ὁμοῦ τὸν ὄλεθρον τοῦ λαοῦ καὶ τὴν αἰσχύνην δὲ τῆς ἀπωλείας λογισάμενος ἐξ ἡμίσους ὑπὸ φαυλότητος ἠναγκάζετο σωφρονεῖν·"},{"number":302,"text":"τοῖς μὲν γὰρ Ἑβραίοις αὐτοῖς ἐδίδου τὴν ἄφοδον, καὶ πρὸς τοῦτο λωφήσαντος τέκνα καὶ γυναῖκας ὅμηρα τῆς ὑποστροφῆς αὐτῶν καταλιπεῖν αὐτοὺς ἠξίου. προσεξαγριαίνει δὴ τὸν θεὸν νομίσας ἀπατήσειν αὐτοῦ τὴν πρόνοιαν, ὥσπερ Μωυσέος ἀλλʼ οὐκ ἐκείνου τιμωροῦντος τὴν Αἴγυπτον ὑπὲρ τῶν Ἑβραίων·"},{"number":303,"text":"θηρίων γὰρ παντοίων καὶ πολυτρόπων, ὧν εἰς ὄψιν οὐδεὶς ἀπηντήκει πρότερον, τὴν χώραν αὐτῶν ἐγέμισεν, ὑφʼ ὧν αὐτοί τε ἀπώλλυντο καὶ ἡ γῆ τῆς ἐπιμελείας τῆς παρὰ τῶν γεωργῶν ἀπεστερεῖτο, εἰ δέ τι καὶ διέφυγε τὴν ὑπʼ ἐκείνοις ἀπώλειαν, νόσῳ τοῦτο καὶ τῶν ἀνθρώπων ὑπομενόντων ἐδαπανᾶτο."},{"number":304,"text":"Τοῦ δὲ Φαραώθου μηδʼ οὕτως εἴκοντος τοῖς τοῦ θεοῦ βουλήμασιν, ἀλλὰ τὰς μὲν γυναῖκας συναπαίρειν τοῖς ἀνδράσιν ἀξιοῦντος καταλείπεσθαι δὲ τοὺς παῖδας, οὐκ ἠπόρει τὸ θεῖον τὴν πονηρίαν αὐτοῦ ποικίλοις κακοῖς καὶ μείζοσι τῶν προενδεδημηκότων μετερχόμενον βασανίσαι· ἀλλὰ γὰρ δεινῶς αὐτοῖς ἐξηλκοῦτο τὰ σώματα τῶν ἐντὸς διαφθειρομένων, καὶ τὸ πολὺ τῶν Αἰγυπτίων οὕτως ἀπώλλυτο."},{"number":305,"text":"μηδʼ ὑπὸ ταύτης δὲ τῆς πληγῆς σωφρονιζομένου τοῦ βασιλέως χάλαζα μήτε πρότερον τοῦ κατʼ Αἴγυπτον ἀέρος τοῦτο πεπονθότος μήθʼ ὁμοία τῇ παρʼ ἄλλοις ὥρᾳ χειμῶνος κατιούσῃ, μείζων δὲ τῆς παρὰ τοῖς τὰ βόρεια καὶ τὴν ἄρκτον νεμομένοις, ἔαρος ἀκμάζοντος κατενεχθεῖσα τοὺς καρποὺς αὐτῶν κατέκλασεν."},{"number":306,"text":"ἔπειτα φῦλον ἀκρίδων ἐπινέμεται τὴν ὑπὸ τῆς χαλάζης μὴ καταβλαβεῖσαν σποράν, ὥστε πρὸς ἀκριβὲς πάσας τοῖς Αἰγυπτίοις τὰς ἀπὸ τῆς γῆς τῶν καρπῶν ἐλπίδας διολέσαι."},{"number":307,"text":"Ἤρκει μὲν οὖν τὸν δίχα πονηρίας ἀνόητον καὶ τὰ προειρημένα τῶν κακῶν εἰς σύνεσιν καὶ τοῦ συμφέροντος τὴν ἐπίνοιαν ὠφελῆσαι, Φαραώθης δὲ οὐ τοσοῦτον ὑπὸ ἀφροσύνης ὅσον ὑπὸ κακίας ὅμως αἰσθόμενος γὰρ τῆς αἰτίας ἀντεφιλονείκει τῷ θεῷ καὶ τοῦ κρείττονος ἑκὼν προδότης ἐγένετο, καὶ κελεύει μὲν τὸν Μωυσῆν μετὰ γυναικῶν καὶ παίδων ἀπάγειν τοὺς Ἑβραίους, τὴν δὲ λείαν αὐτοῖς καταλιπεῖν ἐφθαρμένης αὐτοῖς τῆς οἰκείας."},{"number":308,"text":"τοῦ δὲ Μωυσέος οὐχὶ δίκαια φήσαντος αὐτὸν ἀξιοῦν, δεῖν γὰρ αὐτοὺς τῷ θεῷ τὰς θυσίας ἐκ τῆς λείας ἐπενεγκεῖν, καὶ τριβομένου διὰ ταύτην τὴν αἰτίαν τοῦ χρόνου σκότος βαθὺ καὶ φέγγους ἄμοιρον περιχεῖται τοῖς Αἰγυπτίοις, ὑφʼ οὗ τάς τε ὄψεις ἀποκλειομένοις καὶ τὰς ἀναπνοὰς ἐμφραττομένοις ὑπὸ παχύτητος οἰκτρῶς τε ἀποθνήσκειν συνέβαινε καὶ δεδιέναι μὴ καταποθῶσιν ὑπὸ τοῦ νέφους."},{"number":309,"text":"εἶτα τούτου διασκεδασθέντος μετὰ τρεῖς ἡμέρας καὶ τοσαύτας νύκτας, ὡς οὐ μετενόει πρὸς τὴν ἔξοδον τῶν Ἑβραίων ὁ Φαραώθης, προσελθὼν ὁ Μωυσῆς φησιν· ἄχρι πότε ἀπειθεῖς τῇ τοῦ θεοῦ γνώμῃ· κελεύει γὰρ οὗτος ἀπολύειν τοὺς Ἑβραίους. καὶ οὐκ ἔστιν ἑτέρως ἀπαλλαγῆναι τῶν κακῶν ὑμᾶς μὴ ταῦτα ποιήσαντας."},{"number":310,"text":"ὁ δὲ βασιλεὺς ὀργισθεὶς ἐπὶ τοῖς εἰρημένοις ἠπείλησεν αὐτοῦ τὴν κεφαλὴν ἀποτεμεῖν, εἰ πάλιν περὶ τούτων ἐνοχλῶν αὐτῷ προσέλθοι. Μωυσῆς δὲ αὐτὸς οὐκέτι ποιήσεσθαι περὶ τούτων λόγους ἔφησεν, αὐτὸν δὲ ἐκεῖνον σὺν καὶ τοῖς πρώτοις τῶν Αἰγυπτίων παρακαλέσειν τοὺς Ἑβραίους ἀπελθεῖν. καὶ ὁ μὲν ταῦτʼ εἰπὼν ἀπαλλάσσεται."},{"number":311,"text":"Ὁ δὲ θεὸς δηλώσας ἔτι μιᾷ πληγῇ τοὺς Αἰγυπτίους καταναγκάσειν ἀπολῦσαι τοὺς Ἑβραίους ἐκέλευε Μωυσῆν παραγγεῖλαι τῷ λαῷ θυσίαν ἑτοίμην ἔχειν παρασκευασαμένους τῇ δεκάτῃ τοῦ Ξανθικοῦ μηνὸς εἰς τὴν τεσσαρεσκαιδεκάτην, ὃς παρὰ μὲν Αἰγυπτίοις Φαρμουθὶ καλεῖται, Νισὰν δὲ παρʼ Ἑβραίοις, Μακεδόνες δʼ αὐτὸν Ξανθικὸν προσαγορεύουσιν, ἀπάγειν τε τοὺς Ἑβραίους πάντα ἐπικομιζομένους."},{"number":312,"text":"καὶ ὁ μὲν ἑτοίμους ἔχων ἤδη τοὺς Ἑβραίους πρὸς τὴν ἔξοδον καὶ διατάξας εἰς φατρίας ἐν ταὐτῷ συνεῖχεν, ἐνστάσης δὲ τῆς τεσσαρεσκαιδεκάτης πάντες πρὸς ἄφοδον ἔχοντες ἔθυον καὶ τῷ αἵματι τὰς οἰκίας ἥγνιζον ὑσσώπου κόμαις ἀναλαβόντες καὶ δειπνήσαντες τὰ λοιπὰ τῶν κρεῶν ἔκαυσαν ὡς ἐξελευσόμενοι."},{"number":313,"text":"ὅθεν νῦν ἔτι κατὰ τὸ ἔθος οὕτως θύομεν τὴν ἑορτὴν πάσχα καλοῦντες, σημαίνει δʼ ὑπερβάσια, διότι κατʼ ἐκείνην τὴν ἡμέραν ὁ θεὸς αὐτῶν ὑπερβὰς Αἰγυπτίοις ἐναπέσκηψε τὴν νόσον. ἡ γὰρ φθορὰ τῶν πρωτοτόκων κατʼ ἐκείνην ἔπεισι τὴν νύκτα τοῖς Αἰγυπτίοις, ὡς συνελθόντας πολλοὺς τῶν περὶ τὸ βασίλειον διαιτωμένων τῷ Φαραώθῃ συμβουλεύειν ἀπολύειν τοὺς Ἑβραίους."},{"number":314,"text":"καὶ Μωυσῆν καλέσας ἐκεῖνος ἀπιέναι προσέταξεν, εἰ τῆς χώρας ἐξέλθοιεν παύσεσθαι τὴν Αἴγυπτον κακοπαθοῦσαν ὑπολαβών, δώροις τε τοὺς Ἑβραίους ἐτίμων, οἱ μὲν ὑπὲρ τοῦ τάχιον ἐξελθεῖν, οἱ δὲ καὶ κατὰ γειτνιακὴν πρὸς αὐτοὺς συνήθειαν."}],"15":[{"number":315,"text":"Καὶ οἱ μὲν ἐξῄεσαν κλαιόντων καὶ μετανοούντων ὅτι χρήσαιντο χαλεπῶς αὐτοῖς τῶν Αἰγυπτίων, τὴν δὲ πορείαν ἐποιοῦντο κατὰ Λητοῦς πόλιν ἔρημον οὖσαν ἐν τοῖς τότε· Βαβυλὼν γὰρ ὕστερον ἐκεῖ κτίζεται Καμβύσου καταστρεφομένου τὴν Αἴγυπτον. συντόμως δὲ ποιούμενοι τὴν ἄφοδον εἰς Βεελσεφῶντα χωρίον τριταῖοι παραγίνονται τῆς Ἐρυθρᾶς θαλάσσης."},{"number":316,"text":"μηδενὸς δὲ τῶν ἀπὸ τῆς γῆς εὐποροῦντες διὰ τὴν ἐρημίαν πεφυραμένοις τοῖς ἀλεύροις καὶ πεπηγόσι μόνον ὑπὸ βραχείας θερμότητος τοῖς ἀπʼ αὐτῶν ἄρτοις διετρέφοντο, καὶ τούτοις ἐπὶ τριάκονθʼ ἡμέρας ἐχρήσαντο· πρὸς πλείονα γὰρ οὐκ ἐξήρκεσε χρόνον αὐτοῖς ὅσα ἐκ τῆς Αἰγύπτου ἐπεφέροντο καὶ ταῦτα τὴν τροφὴν ταμιευομένοις καὶ πρὸς ἀνάγκην ἀλλὰ μὴ πρὸς κόρον αὐτῇ χρωμένοις·"},{"number":317,"text":"ὅθεν εἰς μνήμην τῆς τότε ἐνδείας ἑορτὴν ἄγομεν ἐφʼ ἡμέρας ὀκτὼ τὴν τῶν ἀζύμων λεγομένην. τὸ μὲν οὖν πᾶν πλῆθος τῶν μετανισταμένων γυναιξὶν ἅμα καὶ τέκνοις σκοποῦσιν οὐκ εὐαρίθμητον ἦν, οἱ δὲ στρατεύσιμον ἔχοντες τὴν ἡλικίαν περὶ ἑξήκοντα μυριάδες ἦσαν."},{"number":318,"text":"Κατέλιπον δὲ τὴν Αἴγυπτον μηνὶ Ξανθικῷ πεντεκαιδεκάτῃ κατὰ σελήνην μετὰ ἔτη τριάκοντα καὶ τετρακόσια ἢ τὸν πρόγονον ἡμῶν Ἅβραμον εἰς τὴν Χαναναίαν ἐλθεῖν, τῆς δὲ Ἰακώβου μεταναστάσεως εἰς τὴν Αἴγυπτον γενομένης διακοσίοις πρὸς τοῖς δεκαπέντε ἐνιαυτοῖς ὕστερον."},{"number":319,"text":"Μωυσῆς δʼ ἐγεγόνει μὲν ἔτος ὀγδοηκοστὸν ἤδη, ὁ δὲ ἀδελφὸς αὐτοῦ Ἀαρὼν τρισὶ πλείοσιν. ἐπεκομίζοντο δὲ καὶ τὰ τοῦ Ἰωσήπου ὀστᾶ ταῦτʼ ἐκείνου τοῖς υἱοῖς αὐτοῦ κελεύσαντος."},{"number":320,"text":"Αἰγύπτιοι δʼ ἐπὶ τοῖς Ἑβραίοις ἐξελθοῦσι μετενόουν καὶ τοῦ βασιλέως δεινῶς φέροντος ὡς κατὰ γοητείαν τὴν Μωυσέος τούτων γεγονότων ἐπʼ αὐτοὺς ἐγνώκεσαν ἀπιέναι. καὶ λαβόντες ὅπλα καὶ παρασκευὴν ἐδίωκον ὡς ἐπανάξοντες αὐτοὺς εἰ καταλάβοιεν· καὶ γὰρ οὐκέτʼ αὐτοὺς ἐνέχεσθαι τῷ θεῷ· τὴν γὰρ ἔξοδον αὐτοῖς γεγονέναι·"},{"number":321,"text":"κρατήσειν δὲ ῥᾳδίως αὐτῶν ὑπέλαβον ἀνόπλων τε ὄντων καὶ ὑπὸ τῆς ὁδοιπορίας κεκοπωμένων. παρʼ ἑκάστων τε ἀναπυνθανόμενοι ᾗ χωρήσειαν ἐπέσπευδον τὴν δίωξιν, καίτοι χαλεπῆς οὔσης ὁδευθῆναι τῆς γῆς οὐ στρατοπέδοις μόνον ἀλλὰ καὶ καθʼ ἕνα."},{"number":322,"text":"Μωυσῆς δὲ ταύτῃ τοὺς Ἑβραίους ἀπήγαγεν, ἵνʼ εἰ μετανοήσαντες οἱ Αἰγύπτιοι διώκειν ἐθέλοιεν τιμωρίαν τῆς πονηρίας καὶ παραβάσεως τῶν ὡμολογημένων ὑπόσχοιεν, καὶ διὰ Παλαιστίνους, οὓς δυσμενῶς ἔχοντας κατὰ παλαιὰν ἀπέχθειαν οὖσαν ὁπωσοῦν ἐβούλετο λανθάνειν ἀπερχόμενος· ὅμορος γάρ ἐστι τῇ τῶν Αἰγυπτίων χώρᾳ·"},{"number":323,"text":"καὶ διὰ τοῦτο τὴν μὲν ἄγουσαν εἰς τὴν Παλαιστίνην οὐκ ἀνήγαγε τὸν λαὸν, ἀλλὰ διὰ τῆς ἐρήμου πολλὴν ἀνύσας ὁδὸν καὶ κακοπαθήσας ἠθέλησεν ἐμβαλεῖν εἰς τὴν Χαναναίαν· ἔτι τε καὶ διὰ τὰς ἐντολὰς τοῦ θεοῦ κελεύσαντος ἄγειν τὸν λαὸν εἰς τὸ Σιναῖον ὄρος ἐκεῖ ποιήσοντας τὰς θυσίας."},{"number":324,"text":"καταλαβόντες δὲ τοὺς Ἑβραίους οἱ Αἰγύπτιοι εἰς μάχην παρεσκευάζοντο καὶ συνελαύνουσιν αὐτοὺς ὑπὸ πολυχειρίας εἰς ὀλίγον χωρίον· ἑξακόσια γὰρ αὐτοῖς ἅρματα εἵπετο σὺν ἱππεῦσι πεντακισμυρίοις καὶ ὁπλιτῶν μυριάδες ἦσαν εἴκοσι. τὰς δὲ ὁδοὺς ἀπεφράγνυσαν, αἷς φεύξεσθαι τοὺς Ἑβραίους ὑπελάμβανον, μεταξὺ κρημνῶν αὐτοὺς ἀπροσβάτων καὶ τῆς θαλάττης ἀπολαμβάνοντες·"},{"number":325,"text":"τελευτᾷ γὰρ εἰς αὐτὴν ὄρος ὑπὸ τραχύτητος ὁδῶν ἄπορον καὶ φυγῆς ἀπολαμβανόμενον. τοιγαροῦν ἐν τῇ εἰσβολῇ τῇ πρὸς θάλατταν τοῦ ὄρους τοὺς Ἑβραίους ἀπέφραττον τῷ στρατοπέδῳ κατὰ στόμα τοῦτο ἱδρυσάμενοι, ὅπως τὴν εἰς τὸ πεδίον ἔξοδον ὦσιν αὐτοὺς ἀφῃρημένοι."},{"number":326,"text":"Μήτʼ οὖν ὑπομένειν πολιορκουμένων τρόπῳ διὰ τὴν ἔνδειαν τῶν ἐπιτηδείων δυνάμενοι μήτε φυγῆς εὐπορίαν ὁρῶντες, ὅπλων τε σπανίζοντες εἰ καὶ μάχεσθαι δόξειεν αὐτοῖς, ἐν ἐλπίδι τοῦ πάντως ἀπολεῖσθαι καθειστήκεσαν, εἰ μὴ παραδώσουσιν ἑαυτοὺς τοῖς Αἰγυπτίοις ἐθελουσίους."},{"number":327,"text":"καὶ τὸν Μωυσῆν ᾐτιῶντο πάντων ἐπιλελησμένοι τῶν ἐκ θεοῦ πρὸς τὴν ἐλευθερίαν αὐτοῖς σημείων γεγονότων, ὡς καὶ τὸν προφήτην παρορμῶντα καὶ τὴν σωτηρίαν αὐτοῖς ἐπαγγελλόμενον ὑπὸ ἀπιστίας λίθοις ἐθελῆσαι βαλεῖν παραδιδόναι τε σφᾶς τοῖς Αἰγυπτίοις διεγνωκέναι."},{"number":328,"text":"πένθος τε ἦν καὶ ὀδυρμοὶ γυναικῶν καὶ παίδων πρὸ ὀφθαλμῶν ἐχόντων τὸν ὄλεθρον ὄρεσι καὶ θαλάττῃ περικεκλεισμένων καὶ πολεμίοις καὶ φυγὴν οὐδαμόθεν ἐκ τούτων ἐπινοούντων."},{"number":329,"text":"Μωυσῆς δὲ καίπερ ἀγριαίνοντος πρὸς αὐτὸν τοῦ πλήθους οὔτʼ αὐτὸς ἐνέκαμνε τῇ περὶ αὐτοὺς προνοίᾳ καὶ τῷ θεῷ κατεφρόνει τά τε ἄλλα πρὸς τὴν ἐλευθερίαν αὐτοῖς ὅσα προεῖπε παρεσχηκότος καὶ μηδὲ τότʼ αὐτοὺς ἐάσοντος ὑπὸ τοῖς ἐχθροῖς γενομένους ἢ δουλεύειν ἢ ἀπολέσθαι,"},{"number":330,"text":"καὶ στὰς ἐν μέσοις οὐδὲ ἀνθρώποις, εἶπε, καλῶς τὰ παρόντα πεπολιτευμένοις πρὸς ἡμᾶς δίκαιον ἦν ἀπιστεῖν ὡς οὐχ ὁμοίοις ἐσομένοις πρὸς τὰ μέλλοντα, τῆς δὲ τοῦ θεοῦ νῦν ἀπογινώσκειν ὑμᾶς προνοίας μανίας ἔργον ἂν εἴη,"},{"number":331,"text":"παρʼ οὗ πάνθʼ ὑμῖν ἀπήντηκεν ὅσα διʼ ἐμοῦ πρὸς σωτηρίαν καὶ τὴν ἀπαλλαγὴν τῆς δουλείας οὐδὲ προσδοκῶσιν ὑπέσχετο. μᾶλλον δʼ ἐχρῆν ἀπόρους, ὡς δοκεῖτε, γεγενημένους βοηθὸν ἐλπίζειν τὸν θεόν, οὗ καὶ τὸ νῦν εἰς ταύτην ὑμᾶς περικεκλεῖσθαι τὴν δυσχωρίαν ἔργον,"},{"number":332,"text":"ἵνʼ ἐξ ἀμηχάνων ὅθεν οὔθʼ αὐτοὺς νομίζετε σωτηρίαν ἕξειν οὔθʼ οἱ πολέμιοι ἐκ τούτων ῥυσάμενος τήν τε ἰσχὺν ἐπιδείξηται τὴν ἑαυτοῦ καὶ τὴν περὶ ὑμᾶς πρόνοιαν. οὐ γὰρ ἐπὶ μικροῖς τὸ θεῖον τὴν ἑαυτοῦ συμμαχίαν οἷς ἂν εὔνουν ᾖ δίδωσιν, ἀλλʼ ἐφʼ οἷς ἀνθρωπίνην ἐλπίδα μὴ βλέποι πρὸς τὸ κρεῖττον παροῦσαν."},{"number":333,"text":"ὅθεν τοιούτῳ βοηθῷ πεπιστευκότες, ᾧ δύναμις καὶ τὰ μικρὰ ποιῆσαι μεγάλα καὶ τῶν τηλικούτων ἀσθένειαν καταψηφίσασθαι, μὴ καταπέπληχθε τὴν Αἰγυπτίων παρασκευήν, μηδʼ ὅτι θάλασσα καὶ κατόπιν ὑμῖν ὄρη φυγῆς ὁδὸν οὐ παρέχοντα διὰ τοῦτʼ ἀπογινώσκετε τὴν σωτηρίαν· γένοιτο γὰρ ἂν καὶ ταῦθʼ ὑμῖν πεδία τοῦ θεοῦ θελήσαντος καὶ γῆ τὸ πέλαγος."}],"16":[{"number":334,"text":"Τοσαῦτα εἰπὼν ἦγεν αὐτοὺς ἐπὶ τὴν θάλασσαν τῶν Αἰγυπτίων ὁρώντων· ἐν ὄψει γὰρ ἦσαν καὶ τῷ πόνῳ τεταλαιπωρημένοι τῆς διώξεως εἰς τὴν ὑστεραίαν τὴν μάχην ὑπερβαλέσθαι καλῶς ἔχειν ὑπελάμβανον. ἐπειδὴ δὲ πρὸς τῷ αἰγιαλῷ Μωυσῆς ἐγεγόνει, λαβὼν τὴν βακτηρίαν τὸν θεὸν ἱκέτευε καὶ σύμμαχον καὶ βοηθὸν ἐκάλει λέγων·"},{"number":335,"text":"οὐδʼ αὐτὸς μὲν ἀγνοεῖς, ὅτι φυγεῖν ἡμῖν ἐκ τῶν παρόντων οὔτε κατὰ ῥώμην οὔτε κατʼ ἐπίνοιάν ἐστιν ἀνθρωπίνην, ἀλλʼ εἰ δή τι πάντως σωτήριον στρατῷ τῷ κατὰ τὴν σὴν βούλησιν ἀφέντι τὴν Αἴγυπτον, σόν ἐστιν ἐκπορίζειν."},{"number":336,"text":"ἡμεῖς τε ἄλλην ἀπεγνωκότες ἐλπίδα καὶ μηχανὴν εἰς τὴν ἀπὸ σοῦ μόνου καταφεύγομεν, καὶ εἴ τι παρὰ τῆς σῆς ἔλθοι προνοίας ἐξαρπάσαι τῆς Αἰγυπτίων ὀργῆς ἡμᾶς δυνάμενον ἀφορῶμεν. ἀφίκοιτο δὲ τοῦτο ταχέως τὴν σὴν ἐμφανίσον ἡμῖν δύναμιν καὶ τὸν λαὸν ὑπὸ ἀνελπιστίας καταπεπτωκότα πρὸς τὸ χεῖρον ἀναστῆσον εἰς εὐθυμίαν καὶ τὸ περὶ τῆς σωτηρίας θάρσος."},{"number":337,"text":"ἐν οὐκ ἀλλοτρίοις δʼ ἐσμὲν τοῖς ἀπόροις, ἀλλὰ σὴ μὲν ἡ θάλασσα, σὸν δὲ τὸ περικλεῖον ἡμᾶς ὄρος, ὡς ἀνοιγῆναι μὲν τοῦτο σοῦ κελεύσαντος, ἠπειρωθῆναι δὲ καὶ τὸ πέλαγος, εἶναι δὲ ἡμῖν ἀποδρᾶναι καὶ διʼ ἀέρος δόξαν ἰσχύι τῇ σῇ τοῦτον ἡμᾶς σώζεσθαι τὸν τρόπον."},{"number":338,"text":"Τοσαῦτα ἐπιθειάσας τύπτει τῇ βακτηρίᾳ τὴν θάλατταν. ἡ δʼ ὑπὸ τῆς πληγῆς ἀνεκόπη καὶ εἰς αὑτὴν ὑποχωρήσασα γυμνὴν ἀφίησι τὴν γῆν ὁδὸν Ἑβραίοις εἶναι καὶ φυγήν."},{"number":339,"text":"Μωυσῆς δὲ ὁρῶν τὴν ἐπιφάνειαν τοῦ θεοῦ καὶ τὸ πέλαγος ἐκκεχωρηκὸς αὐτοῖς τῆς ἰδίας ἠπείρου πρῶτος ἐνέβαινεν αὐτῇ καὶ τοὺς Ἑβραίους ἐκέλευεν ἕπεσθαι διὰ θείας ὁδοῦ ποιουμένους τὴν πορείαν καὶ τῷ κινδύνῳ τῶν παρόντων πολεμίων ἡδομένους καὶ χάριν ἔχοντας διὰ τὴν παράλογον οὕτως ἐξ αὐτοῦ σωτηρίαν ἀναφανεῖσαν."},{"number":340,"text":"Τῶν δʼ οὐκέτʼ ὀκνούντων, ἀλλʼ ἱεμένων μετὰ σπουδῆς ὡς συμπαρόντος αὐτοῖς τοῦ θεοῦ, μαίνεσθαι μὲν αὐτοὺς τὸ πρῶτον Αἰγύπτιοι ἐδόκουν ὡς ἐπὶ πρόδηλον ὄλεθρον ὁρμωμένους, ἐπεὶ δὲ ἑώρων ἀβλαβεῖς ἐπὶ τὸ πολὺ προκεκοφότας καὶ μηδὲν αὐτοῖς ἐμπόδιον μηδὲ δυσχερὲς ἀπαντῆσαν, διώκειν ὡρμήκεσαν αὐτοὺς ὡς κἀκείνοις ἠρεμήσοντος τοῦ πελάγους, καὶ προτάξαντες τὴν ἵππον κατέβαινον."},{"number":341,"text":"Ἑβραῖοι δὲ καθοπλιζομένους καὶ τὸν χρόνον εἰς τοῦτο τρίβοντας ἔφθασαν εἰς τὴν ἀντιπέραν γῆν ἀπαθεῖς ἐκφυγόντες, ὅθεν καὶ θαρσαλεωτέροις συνέβαινε πρὸς τὴν δίωξιν ὡς οὐδὲν οὐδʼ αὐτῶν πεισομένων εἶναι."},{"number":342,"text":"Αἰγύπτιοι δʼ ἐλάνθανον ἰδίαν ὁδὸν Ἑβραίοις γεγενημένην, ἀλλʼ οὐχὶ κοινὴν ἐπεμβαίνοντες καὶ μέχρι σωτηρίας τῶν κεκινδυνευκότων πεποιημένην, ἀλλʼ οὐχὶ καὶ τοῖς ἐπʼ ἀπωλείᾳ τῇ τούτων ὡρμημένοις χρῆσθαι θέλουσιν."},{"number":343,"text":"ὡς οὖν ὁ τῶν Αἰγυπτίων στρατὸς ἅπας ἐντὸς ἦν, ἐπιχεῖται πάλιν ἡ θάλασσα καὶ περικαταλαμβάνει ῥοώδης ὑπὸ πνευμάτων κατιοῦσα τοὺς Αἰγυπτίους, ὄμβροι τʼ ἀπʼ οὐρανοῦ κατέβαινον καὶ βρονταὶ σκληραὶ προσεξαπτομένης ἀστραπῆς καὶ κεραυνοὶ δὲ κατηνέχθησαν."},{"number":344,"text":"ὅλως δʼ οὐδὲν ἦν τῶν ἐπʼ ἀπωλείᾳ κατὰ μῆνιν θεοῦ συμπιπτόντων ἀνθρώποις, ὃ μὴ τότε συνῆλθε· καὶ γὰρ νὺξ αὐτοὺς ζοφώδης καὶ σκοτεινὴ κατέλαβε. καὶ οἱ μὲν οὕτως ἀπώλοντο πάντες, ὡς μηδʼ ἄγγελον τῆς συμφορᾶς τοῖς ὑπολελειμμένοις ὑποστρέψαι."},{"number":345,"text":"Τοὺς δʼ Ἑβραίους οὐδὲ κατασχεῖν ἦν ἐπὶ τῇ χαρᾷ τῆς παραδόξου σωτηρίας καὶ τῇ τῶν πολεμίων ἀπωλείᾳ, βεβαίως νομίζοντας ἠλευθερῶσθαι τῶν ἀναγκαζόντων δουλεύειν διεφθαρμένων καὶ τὸν θεὸν οὕτως ἐναργῶς ἔχοντας βοηθοῦντα."},{"number":346,"text":"καὶ οἱ μὲν αὐτοί τε τὸν κίνδυνον οὕτως ἐκφυγόντες καὶ προσέτι τοὺς ἐχθροὺς ἐπιδόντες κεκολασμένους, ὡς οὐκ ἄλλοι τινὲς μνημονεύονται τῶν πρόσθεν ἀνθρώπων, ἐν ὕμνοις ἦσαν καὶ παιδιαῖς ὅλην τὴν νύκτα, καὶ Μωυσῆς ᾠδὴν εἰς τὸν θεὸν ἐγκώμιόν τε καὶ τῆς εὐμενείας εὐχαριστίαν περιέχουσαν ἐν ἑξαμέτρῳ τόνῳ συντίθησιν."},{"number":347,"text":"Ἐγὼ μὲν οὖν ὡς εὗρον ἐν ταῖς ἱεραῖς βίβλοις οὕτως ἕκαστον τούτων παραδέδωκα· θαυμάσῃ δὲ μηδεὶς τοῦ λόγου τὸ παράδοξον, εἰ ἀρχαίοις ἀνθρώποις καὶ πονηρίας ἀπείροις εὑρέθη σωτηρίας ὁδὸς καὶ διὰ θαλάσσης εἴτε κατὰ βούλησιν θεοῦ εἴτε κατὰ ταὐτόματον,"},{"number":348,"text":"ὁπότε καὶ τοῖς περὶ τὸν Ἀλέξανδρον τὸν βασιλέα τῆς Μακεδονίας χθὲς καὶ πρῴην γεγονόσιν ὑπεχώρησε τὸ Παμφύλιον πέλαγος καὶ ὁδὸν ἄλλην οὐκ ἔχουσι παρέσχε τὴν διʼ αὐτοῦ καταλῦσαι τὴν Περσῶν ἡγεμονίαν τοῦ θεοῦ θελήσαντος, καὶ τοῦτο πάντες ὁμολογοῦσιν οἱ τὰς Ἀλεξάνδρου πράξεις συγγραψάμενοι. περὶ μὲν οὖν τούτων ὡς ἑκάστῳ δοκεῖ διαλαμβανέτω."},{"number":349,"text":"Τῇ δʼ ὑστεραίᾳ τὰ ὅπλα τῶν Αἰγυπτίων προσενεχθέντα τῷ στρατοπέδῳ τῶν Ἑβραίων ὑπὸ τοῦ ῥοῦ καὶ τῆς βίας τοῦ πνεύματος ἐπʼ ἐκεῖνο ἐκδιδούσης ὁ Μωυσῆς καὶ τοῦτο εἰκάσας τῇ τοῦ θεοῦ προνοίᾳ γεγονέναι, ὅπως μηδὲ ὅπλων ὦσιν ἄποροι, συναγαγὼν καὶ τούτοις σκεπάσας τοὺς Ἑβραίους ἦγεν ἐπὶ τὸ Σιναῖον ὄρος θύσων ἐκεῖ τῷ θεῷ καὶ τὰ σῶστρα τῆς πληθύος ἀποδώσων, καθὼς αὐτῷ καὶ προείρητο."}]},"count":349};a[3]={"book":3,"title":"Τάδε ἔνεστιν ἐν τῇ τρίτῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"α. Ὡς Μωυσῆς τὸν λαὸν ἀπ' Αἰγύπτου ἀναλαβὼν ἤγαγεν ἐπὶ τὸ Σιναῖον ὄρος πολλὰ ταλαιπωρήσαντα ἐν τῇ ὁδοιπορίᾳ.\n\nβ. ὡς πολεμήσαντες Ἑβραίοις Ἀμαληκῖται καὶ οἱ πέριξ ἡττήθησαν καὶ πολλὴν τῆς στρατιᾶς ἀπέβαλον.\n\nγ. ὅτι τὸν πενθερὸν αὑτοῦ Ἰεθὴρ Μωυσῆς παραγενόμενον πρὸς αὐτὸν εἰς τὸ Σιναῖον ἀσμένως ὑπεδέξατο.\n\nδ. ὡς ὑπέθετο διατάξαι τὸν λαὸν αὐτῷ κατὰ χιλιάρχους καὶ ἑκατοντάρχους ἄτακτον ὄντα τὸ πρῶτον, καὶ ὡς ἕκαστα τούτων ἐποίησε Μωυσῆς κατὰ τὴν τοῦ πενθεροῦ παραίνεσιν.\n\nε. ὡς ἀναβὰς Μωυσῆς ἐπὶ τὸ Σιναῖον ὄρος καὶ λαβὼν παρὰ τοῦ θεοῦ τοὺς νόμους τοῖς Ἑβραίοις ἔδωκεν.\n\nϛ. περὶ τῆς σκηνῆς ἣν κατεσκεύασε Μωυσῆς ἐν τῇ ἐρημίᾳ εἰς τιμὴν τοῦ θεοῦ, ὥστε ναὸν εἶναι δοκεῖν.\n\nζ. τίνες τε τοῖς ἱερεῦσίν εἰσιν αἱ στολαὶ καὶ ἡ τοῦ ἀρχιερέως· καὶ τῶν ἁγνειῶν οἱ τρόποι καὶ περὶ τῶν ἑορτῶν καὶ ὡς ἑκάστη τῶν ἑορτῶν διατέτακται.\n\nη. ὡς ἐκεῖθεν ἄρας Μωυσῆς ἤγαγεν εἰς τοὺς ὅρους τῶν Χαναναίων καὶ τοὺς κατοψομένους αὐτῶν τὴν χώραν καὶ τῶν πόλεων τὸ μέγεθος ἐξαπέστειλεν.\n\nθ. ὅτι τῶν πεμφθέντων μετὰ τεσσαρακοστὴν ὑποστρεψάντων ἡμέραν καὶ λεγόντων οὐκ ἀξιομάχους αὐτοὺς ἀλλὰ τὴν τῶν Χαναναίων ὑπεξαιρόντων δύναμιν, τὸ πλῆθος ταραχθὲν καὶ πεσὸν εἰς ἀπόγνωσιν ὥρμησεν ὥστε καταλεῦσαι παρὰ μικρὸν τὸν Μωυσῆν καὶ πάλιν εἰς τὴν Αἴγυπτον ὑποστρέψαι δουλεύειν διεγνωκότες.\n\nι. καὶ ὡς ἐπὶ τούτῳ Μωυσῆς διαγανακτήσας τὸν θεὸν αὐτοῖς ἐπὶ ἔτη τεσσαράκοντα τὴν ἐπὶ τῆς ἐρημίας διατριβὴν προειπεῖν ὠργίσθαι, καὶ μήτ' εἰς Αἴγυπτον ὑποστρέφειν μήτε λαβεῖν τὴν Χαναναίαν.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν δύο."},"chapters":{"1":[{"number":1,"text":"Παραδόξου δὲ τῆς σωτηρίας τοῖς Ἑβραίοις οὕτως γενομένης δεινῶς ἐλύπει πάλιν αὐτοὺς ἀγομένους ἐπὶ τὸ Σιναῖον ὄρος ἡ χώρα τελέως οὖσα ἔρημος καὶ τῶν τε πρὸς τροφὴν αὐτοῖς ἄπορος, σπανίζουσα δὲ καὶ ὕδατος εἰς τὸ ἔσχατον, καὶ μὴ μόνον ἀνθρώποις τι παρασχεῖν ἐνδεής, ἀλλὰ καὶ μηδʼ ἄλλο τι τῶν ζῴων ἱκανὴ βόσκειν· ψαφαρὰ γάρ ἐστι καὶ νοτερὸν ἐξ αὐτῆς οὐδὲν ὅ τι καὶ φῦσαι καρπὸν δύναιτο. τοιαύτην δὲ οὖσαν τὴν χώραν ἐξ ἀνάγκης ὥδευον ἑτέραν ἀπελθεῖν οὐκ ἔχοντες."},{"number":2,"text":"ἐπεφέροντο δʼ ἐκ τῆς προωδοιπορημένης ὕδωρ τοῦ στρατηγοῦ κεκελευκότος, καὶ τούτου δαπανηθέντος ἐκ φρεάτων ἐποιοῦντο τὴν ὑδρείαν ἐπιπόνως διὰ σκληρότητα τῆς γῆς, καὶ τὸ εὑρισκόμενον δὲ πικρὸν ἀλλʼ οὐ πότιμον ἦν, καὶ τοῦτο δὲ σπάνιον."},{"number":3,"text":"ἀφικνοῦνται δὲ τοῦτον ὁδεύοντες τὸν τρόπον περὶ δείλην ὀψίαν εἰς Μὰρ τόπον οὕτως διὰ τὴν τοῦ ὕδατος κακίαν ὀνομάσαντες· μὰρ γὰρ ἡ πικρία λέγεται. καὶ αὐτόθι τεταλαιπωρημένοι τῷ τε συνεχεῖ τῆς ὁδοιπορίας καὶ τῇ τῆς τροφῆς ἀπορίᾳ, καὶ γὰρ τότʼ αὐτοὺς τελείως ἐπιλελοίπει, κατάγονται·"},{"number":4,"text":"φρέαρ γὰρ ἦν, διὸ καὶ μᾶλλον ἔμειναν, οὐδʼ αὐτὸ μὲν ἐξαρκεῖν δυνάμενον τοσούτῳ στρατῷ, βραχεῖαν μέντοι παρέχον αὐτοῖς εὐθυμίαν ἐν ἐκείνοις εὑρεθὲν τοῖς χωρίοις· καὶ γὰρ ἤκουον παρὰ τῶν ἐξερευνώντων μηδὲν ἔμπροσθεν βαδίζουσιν εἶναι. πικρὸν δὲ ἐκεῖνο τὸ ὕδωρ καὶ ἄποτον ἦν οὐκ ἀνθρώποις μόνον ἀλλὰ καὶ τοῖς ὑποζυγίοις ἀφόρητον."},{"number":5,"text":"Ὁρῶν δʼ ὁ Μωυσῆς ἀθύμως διακειμένους καὶ τοῦ πράγματος τὸ ἀναντίλεκτον, οὐ γὰρ καθαρὸς ἦν στρατὸς ὥστε τῷ βιαζομένῳ τῆς ἀνάγκης ἀντιτάξαι τὸ ἀνδρεῖον, ἀλλὰ διέφθειρε τὸ κατʼ ἐκείνους γενναῖον παίδων τε καὶ γυναικῶν ὄχλος ἀσθενέστερος τῆς ἐκ λόγων διδασκαλίας, ἐν χαλεπωτέροις ἦν τὴν συμφορὰν τὴν ἁπάντων ἰδίαν αὐτοῦ ποιούμενος·"},{"number":6,"text":"καὶ γὰρ οὐδʼ ἐπʼ ἄλλον τινὰ συνέτρεχον ἀλλʼ ἐπʼ αὐτόν, ἀντιβολοῦντες γύναια μὲν ὑπὲρ νηπίων οἱ δʼ ἄνδρες ὑπὲρ ἐκείνων μὴ περιορᾶν, ἀλλʼ ἐκπορίζειν αὐτοῖς ἀφορμήν τινα σωτηρίας. ἱκετεύειν οὖν τρέπεται τὸν θεὸν μεταβαλεῖν τὸ ὕδωρ ἐκ τῆς παρούσης κακίας καὶ πότιμον αὐτοῖς παρασχεῖν."},{"number":7,"text":"καὶ κατανεύσαντος τοῦ θεοῦ τὴν χάριν λαβὼν τομάδος τὸ ἄκρον ἐν ποσὶν ἐρριμμένης διαιρεῖ μέσην καὶ κατὰ τὸ μῆκος τὴν τομὴν ποιησάμενος, ἔπειτα μεθεὶς εἰς τὸ φρέαρ ἔπειθε τοὺς Ἑβραίους τὸν θεὸν ἐπήκοον αὐτοῦ τῶν εὐχῶν γεγονέναι καὶ ὑπεσχῆσθαι τὸ ὕδωρ αὐτοῖς παρέξειν οἷον ἐπιθυμοῦσιν, ἂν πρὸς τὰ ὑπʼ αὐτοῦ κελευόμενα μὴ ὀκνηρῶς ἀλλὰ προθύμως ὑπουργῶσιν."},{"number":8,"text":"ἐρομένων δʼ αὐτῶν, τί καὶ ποιούντων ἂν μεταβάλοι τὸ ὕδωρ ἐπὶ τὸ κρεῖττον, κελεύει τοὺς ἐν ἀκμῇ περιστάντας ἐξαντλεῖν λέγων τὸ ὑπολειπόμενον ἔσεσθαι πότιμον αὐτοῖς προεκκενωθέντος τοῦ πλείονος. καὶ οἱ μὲν ἐπόνουν, τὸ δʼ ὑπὸ τῶν συνεχῶν πληγῶν γεγυμνασμένον καὶ κεκαθαρμένον ἤδη πότιμον ἦν."},{"number":9,"text":"Ἄραντες δʼ ἐκεῖθεν εἰς Ἦλιν ἀφικνοῦνται πόρρωθεν μὲν ἀγαθὴν ὁραθῆναι, καὶ γὰρ φοινικόφυτος ἦν, πλησιάζουσα δʼ ἀπηλέγχετο πονηρά· καὶ γὰρ οἱ φοίνικες ὄντες οὐ πλείους ἑβδομήκοντα δυσαυξεῖς τε ἦσαν καὶ χαμαίζηλοι διʼ ὕδατος ἀπορίαν ψαφαροῦ τοῦ παντὸς ὄντος χωρίου·"},{"number":10,"text":"οὔτε γὰρ ἐκ τῶν πηγῶν δώδεκα οὐσῶν τὸν ἀριθμὸν νοτερόν τι προσαρδεῦον αὐτοῖς διʼ ἐλπίδα χρήσιμον, ἀλλὰ μὴ δυναμένων ἐκβλύσαι μηδʼ ἀνασχεῖν ἰκμάδες ἦσαν ὀλίγαι, καὶ διαμωμένοις τὴν ψάμμον οὐδὲν ἀπήντα, κἂν εἴ τι δὲ στάζον ἔλαβον εἰς χεῖρας, ἄχρηστον ηὕρισκον ὑπὸ τοῦ θολερὸν εἶναι·"},{"number":11,"text":"καρπόν τε φέρειν ἦν ἀσθενῆ τὰ δένδρα διὰ σπάνιν τῆς ἐξ ὕδατος εἰς τοῦτο ἀφορμῆς καὶ παρακλήσεως. εἶχον οὖν ἐν αἰτίᾳ τὸν στρατηγὸν καὶ κατεβόων αὐτοῦ τὴν ταλαιπωρίαν καὶ τὴν πεῖραν τῶν κακῶν διʼ αὐτὸν πάσχειν λέγοντες· τριακοστὴν γὰρ ἐκείνην ὁδεύοντες ἡμέραν ὅσα μὲν ἐπεφέροντο πάντʼ ἦσαν ἀναλωκότες, μηδενὶ δὲ περιτυγχάνοντες δυσέλπιδες ἦσαν περὶ τῶν ὅλων."},{"number":12,"text":"πρὸς δὲ τῷ παρόντι κακῷ τὴν διάνοιαν ὄντες καὶ ἐν μνήμῃ εἶναι τῶν ὑπηργμένων αὐτοῖς ἔκ τε τοῦ θεοῦ καὶ τῆς Μωυσέος ἀρετῆς καὶ συνέσεως κωλυόμενοι διʼ ὀργῆς τὸν στρατηγὸν εἶχον καὶ βάλλειν αὐτὸν ὡρμήκεσαν ὡς αἰτιώτατον τῆς ἐν ποσὶ συμφορᾶς."},{"number":13,"text":"Ὁ δʼ οὕτως ἀνηρεθισμένου τοῦ πλήθους καὶ πικρῶς ἐπʼ αὐτὸν κεκινημένου τῷ θεῷ θαρρῶν καὶ τῷ συνειδότι τῆς περὶ τοὺς ὁμοφύλους προνοίας πάρεισιν εἰς μέσους, καὶ καταβοώντων καὶ κατὰ χεῖρας ἔτι τοὺς λίθους ἐχόντων, ὁραθῆναί τε κεχαρισμένος ὢν καὶ πλήθεσιν ὁμιλεῖν πιθανώτατος, καταπαύειν ἤρξατο τῆς ὀργῆς,"},{"number":14,"text":"μὴ τῶν παρόντων αὐτοὺς δυσκόλων μεμνημένους λήθην ἔχειν τῶν ἔμπροσθεν εὐεργεσιῶν παρακαλῶν, μηδʼ ὅτι νῦν πονοῦσι τῆς διανοίας ἐκβάλλειν τὰς τοῦ θεοῦ χάριτας καὶ δωρεάς, ὧν μεγάλων καὶ ἐκ παραδόξου ἔτυχον γενομένων, προσδοκᾶν δὲ καὶ τῆς παρούσης ἀπαλλαγῆναι ἀμηχανίας ἐκ τῆς τοῦ θεοῦ κηδεμονίας,"},{"number":15,"text":"ὃν εἰκὸς δοκιμάζοντα τὴν ἀρετὴν αὐτῶν πῶς τε καρτερίας ἔχουσι καὶ μνήμης τῶν προϋπηργμένων, εἰ μὴ πρὸς ἐκεῖνα γίγνοιντο διὰ τὰ ἐν ποσὶ κακά, γυμνάζειν αὐτοὺς τοῖς ἄρτι χαλεποῖς."},{"number":16,"text":"ἐλέγχεσθαι δὲ αὐτοὺς οὐκ ἀγαθοὺς οὔτε περὶ τὴν ὑπομονὴν οὔτε περὶ τὴν μνήμην τῶν εὖ γεγονότων, οὕτως μὲν τοῦ θεοῦ καὶ τῆς ἐκείνου γνώμης, καθʼ ἣν ἐκλελοίπασι τὴν Αἴγυπτον, καταφρονοῦντας, οὕτως δὲ πρὸς αὐτὸν τὸν ὑπηρέτην αὐτοῦ διατεθέντας καὶ ταῦτα μηδὲν αὐτοὺς διαψευσάμενον περὶ ὧν εἴποι τε καὶ πράττειν κατʼ ἐντολὴν τοῦ θεοῦ κελεύσειε."},{"number":17,"text":"κατηρίθμει τε πάντα, πῶς τε φθαρεῖεν Αἰγύπτιοι κατέχειν αὐτοὺς παρὰ τὴν τοῦ θεοῦ γνώμην βιαζόμενοι, καὶ τίνα τρόπον ὁ αὐτὸς ποταμὸς ἐκείνοις μὲν αἷμα ἦν καὶ ἄποτος αὐτοῖς δὲ πότιμος καὶ γλυκύς,"},{"number":18,"text":"πῶς τε διὰ τῆς θαλάσσης ἀναφυγούσης αὐτοῖς πορρωτάτω καινὴν ὁδὸν ἀπελθόντες αὐτῇ ταύτῃ σωθείησαν μὲν αὐτοί, τοὺς δὲ ἐχθροὺς ἐπίδοιεν ἀπολωλότας, ὅτι τε σπανίζοντας ὅπλων εἰς εὐπορίαν ὁ θεὸς καὶ τούτων καταστήσειε, τά τε ἄλλα ὅσα πρὸς αὐτῷ τῷ διαφθαρήσεσθαι δόξαντας γεγονέναι καὶ σώσειεν ὁ θεὸς ἐκ παραλόγου καὶ ὡς δύναμις αὐτῷ·"},{"number":19,"text":"μὴ ἀπογινώσκειν δὲ μηδὲ νῦν αὐτοῦ τὴν πρόνοιαν, ἀλλʼ ἀοργήτως περιμένειν, λογιζομένους μὲν τὴν ἐπικουρίαν μηδὲ βραδεῖαν γίνεσθαι, εἰ μὴ παραυτίκα καὶ εἰ μὴ πρίν τινος πειραθῆναι δυσκόλου πάρεστιν, ἡγουμένους δὲ οὐ κατὰ ὀλιγωρίαν μέλλειν τὸν θεόν, ἀλλʼ ἐπὶ πείρᾳ τῆς ἀνδρείας αὐτῶν καὶ τῆς περὶ τὴν ἐλευθερίαν ἡδονῆς,"},{"number":20,"text":"ἵνα μάθοι πότερόν ποτε καὶ τροφῆς ἀπορίαν καὶ σπάνιν ὕδατος ὑπὲρ αὐτῆς ἐστε ἐνεγκεῖν γενναῖοι, ἢ δουλεύειν μᾶλλον ἀγαπᾶτε καθάπερ τὰ βοσκήματα τοῖς κρατοῦσι καὶ τοῖς πρὸς τὰς ἐκείνων ὑπηρεσίας ἀφθόνως τρεφομένοις·"},{"number":21,"text":"δεδιέναι δʼ εἰπὼν οὐχ οὕτως ὑπὲρ τῆς ἑαυτοῦ σωτηρίας, πείσεσθαι γὰρ οὐδὲν κακὸν ἀδίκως ἀποθανών, ἀλλʼ ὑπὲρ αὐτῶν, μὴ διʼ ὧνπερ αὐτὸν βάλλουσι λίθων τοῦ θεοῦ κατακρίνειν νομισθῶσιν,"},{"number":22,"text":"ἐπράυνεν αὐτοὺς καὶ τῆς μὲν τοῦ βάλλειν ὁρμῆς ἐπέσχε καὶ εἰς μετάνοιαν ὧν ἔμελλον δρᾶν ἔτρεψε. παθεῖν δʼ οὐκ ἀλόγως αὐτοὺς διὰ τὴν ἀνάγκην τοῦτο νομίσας ἔγνω δεῖν ἐφʼ ἱκετείαν τοῦ θεοῦ καὶ παράκλησιν ἐλθεῖν, καὶ ἀναβὰς ἐπί τινα σκοπὴν ᾔτει πόρον τινὰ τῷ λαῷ καὶ τῆς ἐνδείας ἀπαλλαγήν·"},{"number":23,"text":"ἐν αὐτῷ γὰρ εἶναι τὴν σωτηρίαν αὐτοῦ καὶ οὐκ ἐν ἄλλῳ· συγγινώσκειν δὲ τοῖς νῦν ὑπὸ τῆς ἀνάγκης ὑπὸ τοῦ λαοῦ πραττομένοις φύσει δυσαρέστου καὶ φιλαιτίου τοῦ τῶν ἀνθρώπων ἐν οἷς ἂν ἀτυχῇ γένους ὄντος. ὁ θεὸς δὲ προνοήσειν τε ἐπαγγέλλεται καὶ παρέξειν ἀφορμὴν ἣν ποθοῦσι."},{"number":24,"text":"Μωυσῆς δὲ τοῦ θεοῦ ταῦτʼ ἀκούσας καταβαίνει πρὸς τὸ πλῆθος· οἱ δʼ ὡς ἑώρων καὶ ταῖς ἐπαγγελίαις ταῖς παρὰ τοῦ θεοῦ γεγηθότα μετέβαλον ἐκ τῆς κατηφείας πρὸς τὸ ἱλαρώτερον, καὶ στὰς ἐκεῖνος ἐν μέσοις ἥκειν ἔλεγε φέρων αὐτοῖς παρὰ τοῦ θεοῦ τὴν περὶ τῶν ἐνεστηκότων ἀπόρων ἀπαλλαγήν."},{"number":25,"text":"καὶ μετʼ ὀλίγον ὀρτύγων πλῆθος, τρέφει δὲ τοῦτο τὸ ὄρνεον ὡς οὐδὲν ἕτερον ὁ Ἀράβιος κόλπος, ἐφίπταται τὴν μεταξὺ θάλατταν ὑπερελθὸν καὶ ὑπὸ κόπου τε ἅμα τῆς πτήσεως καὶ πρόσγαιον μᾶλλον τῶν ἄλλων ὂν καταφέρεται εἰς τοὺς Ἑβραίους· οἱ δὲ συλλαμβάνοντες ὡς τροφὴν αὐτοῖς τοῦ θεοῦ ταύτην μηχανησαμένου τὴν ἔνδειαν ἰῶνται, καὶ Μωυσῆς ἐπʼ εὐχὰς τρέπεται τοῦ θεοῦ ταχεῖαν καὶ παρὰ τὴν ὑπόσχεσιν ποιησαμένου τὴν ἐπικουρίαν."},{"number":26,"text":"Εὐθὺς δὲ μετὰ τὴν πρώτην ἀφορμὴν τῆς τροφῆς καὶ δευτέραν αὐτοῖς κατέπεμπεν ὁ θεός· ἀνέχοντος γὰρ τοῦ Μωυσέος τὰς χεῖρας ἐπὶ ταῖς εὐχαῖς δρόσος κατηνέχθη, καὶ περιπηγνυμένης ταῖς χερσὶ Μωυσῆς ὑπονοήσας καὶ ταύτην εἰς τροφὴν ἥκειν αὐτοῖς παρὰ τοῦ θεοῦ γεύεταί τε καὶ ἡσθείς,"},{"number":27,"text":"τοῦ πλήθους ἀγνοοῦντος καὶ νομίζοντος νίφεσθαι καὶ τῆς ὥρας εἶναι τοῦ ἔτους τὸ γινόμενον, ἀνεδίδασκεν οὐ κατὰ τὴν ἐκείνων ὑπόληψιν ἀπʼ οὐρανοῦ καταφέρεσθαι τὴν δρόσον, ἀλλʼ ἐπὶ σωτηρίᾳ τῇ αὐτῶν καὶ διατροφῇ, καὶ γευομένοις τοῦτο αὐτοῖς παρεῖχε πιστεύειν."},{"number":28,"text":"οἱ δὲ μιμούμενοι τὸν στρατηγὸν ἥδοντο τῷ βρώματι· μέλιτι γὰρ ἦν τὴν γλυκύτητα καὶ τὴν ἡδονὴν ἐμφερές, ὅμοιον δὲ τῇ τῶν ἀρωμάτων βδέλλῃ, τὸ δὲ μέγεθος τῷ κοριάννου σπέρματι· καὶ περὶ συλλογὴν λίαν αὐτοῦ ἐσπουδάκεσαν."},{"number":29,"text":"παρηγγέλλετο δʼ ἐξ ἴσου πᾶσιν ἀσσαρῶνα, τοῦτο δʼ ἐστὶ μέτρον, εἰς ἑκάστην ἡμέραν συλλέγειν ὡς οὐκ ἐπιλείψοντος αὐτοῖς τοῦ βρώματος, ἵνα μὴ τοῖς ἀδυνάτοις ἄπορον ᾖ τὸ λαμβάνειν διʼ ἀλκὴν τῶν δυνατωτέρων πλεονεκτούντων περὶ τὴν ἀναίρεσιν."},{"number":30,"text":"οἱ μέντοι πλέον τοῦ προστεταγμένου μέτρου συναγαγόντες οὐδὲν περισσότερον εἶχον τοῦ κακοπαθῆσαι· ἀσσαρῶνος γὰρ οὐδὲν πλέον εὕρισκον· τοῦ δʼ ὑπολειφθέντος εἰς τὴν ἐπιοῦσαν ὄνησις οὐδʼ ἥτις ἦν διεφθαρμένου ὑπό τε σκωλήκων καὶ πικρίας· οὕτω θεῖον ἦν τὸ βρῶμα καὶ παράδοξον."},{"number":31,"text":"ἀμύνει δὲ τοῖς ταύτην νεμομένοις τὴν ἐκ τῶν ἄλλων ἀπορίαν, ἔτι δὲ καὶ νῦν ὕεται πᾶς ἐκεῖνος ὁ τόπος, καθάπερ καὶ τότε Μωυσεῖ χαριζόμενον τὸ θεῖον κατέπεμψε τὴν διατροφήν."},{"number":32,"text":"καλοῦσι δὲ Ἑβραῖοι τὸ βρῶμα τοῦτο μάννα· τὸ γὰρ μάν ἐπερώτησις κατὰ τὴν ἡμετέραν διάλεκτον, τί τοῦτʼ ἔστιν ἀνακρίνουσα. καὶ οἱ μὲν χαίροντες ἐπὶ τοῖς ἀπʼ οὐρανοῦ καταπεμφθεῖσιν αὐτοῖς διετέλουν, τῇ δὲ τροφῇ ταύτῃ τεσσαράκοντα ἔτη ἐχρήσαντο ἐφʼ ὅσον χρόνον ἦσαν ἐν τῇ ἐρήμῳ."},{"number":33,"text":"Ὡς δʼ ἐκεῖθεν ἄραντες εἰς Ῥαφιδεὶν ἧκον ταλαιπωρηθέντες ὑπὸ δίψους εἰς ἔσχατον ἔν τε ταῖς πρότερον ἡμέραις πίδαξιν ὀλίγαις ἐντυγχάνοντες καὶ τότε παντάπασιν ἄνυδρον εὑρόντες τὴν γῆν, ἐν κακοῖς ἦσαν καὶ πάλιν διʼ ὀργῆς τὸν Μωυσῆν ἐποιοῦντο."},{"number":34,"text":"ὁ δὲ τὴν ὁρμὴν τοῦ πλήθους πρὸς μικρὸν ἐκκλίνας ἐπὶ λιτὰς τρέπεται τοῦ θεοῦ παρακαλῶν ὡς τροφὴν ἔδωκεν ἀπορουμένοις οὕτως καὶ ποτὸν παρασχεῖν, διαφθειρομένης καὶ τῆς ἐπὶ τροφῇ χάριτος ποτοῦ μὴ παρόντος."},{"number":35,"text":"ὁ δʼ οὐκ εἰς μακρὰν τὴν δωρεὰν ἀνεβάλλετο, τῷ δὲ Μωυσεῖ παρέξειν ὑπισχνεῖται πηγὴν καὶ πλῆθος ὕδατος ὅθεν οὐ προσδοκήσειαν, καὶ κελεύει τῷ βάκτρῳ πλήξαντα τὴν πέτραν, ἣν ἑώρων αὐτόθι παρακειμένην, παρʼ αὐτῆς λαμβάνειν τὴν εὐπορίαν ὧν δέονται· φροντίζει γὰρ καὶ τοῦ μὴ σὺν πόνῳ μηδʼ ἐργασίᾳ τὸ ποτὸν αὐτοῖς φανῆναι."},{"number":36,"text":"καὶ Μωυσῆς ταῦτα λαβὼν παρὰ τοῦ θεοῦ παραγίνεται πρὸς τὸν λαὸν περιμένοντα καὶ εἰς αὐτὸν ἀφορῶντα· καὶ γὰρ ἤδη καθεώρων αὐτὸν ἀπὸ τῆς σκοπῆς ὁρμώμενον. ὡς δʼ ἧκεν, ἀπολύειν αὐτοὺς καὶ ταύτης τῆς ἀνάγκης τὸν θεὸν ἔλεγε καὶ χαρίσασθαι σωτηρίαν οὐδʼ ἐλπισθεῖσαν ἐκ τῆς πέτρας ποταμὸν αὐτοῖς ῥυήσεσθαι λέγων."},{"number":37,"text":"τῶν δὲ πρὸς τὴν ἀκοὴν καταπλαγέντων, εἰ ὑπό τε τοῦ δίψους καὶ τῆς ὁδοιπορίας τεταλαιπωρημένοις ἀνάγκη γένοιτο κόπτειν τὴν πέτραν, ὁ Μωυσῆς πλήττει τῇ βακτηρίᾳ, καὶ χανούσης ἐξέβλυσεν ὕδωρ πολὺ καὶ διαυγέστατον."},{"number":38,"text":"οἱ δὲ τῷ παραδόξῳ τοῦ γεγονότος κατεπλάγησαν, καὶ πρὸς τὴν ὄψιν αὐτοῖς ἤδη τὸ δίψος ἔληγε, καὶ πίνουσιν ἡδὺ καὶ γλυκὺ τὸ νᾶμα καὶ οἷον ἂν εἴη θεοῦ τὸ δῶρον δόντος ἐφαίνετο· τόν τε οὖν Μωυσῆν ἐθαύμαζον οὕτως ὑπὸ τοῦ θεοῦ τετιμημένον, καὶ θυσίαις ἠμείβοντο τὴν τοῦ θεοῦ περὶ αὐτοὺς πρόνοιαν. δηλοῖ δὲ ἐν τῷ ἱερῷ ἀνακειμένη γραφὴ τὸν θεὸν προειπεῖν Μωυσεῖ οὕτως ἐκ τῆς πέτρας ἀναδοθήσεσθαι ὕδωρ."}],"2":[{"number":39,"text":"Τοῦ δὲ Ἑβραίων ὀνόματος ἤδη πολλοῦ κατὰ πάντας διαβοωμένου καὶ τοῦ περὶ αὐτῶν λόγου φοιτῶντος ἐν φόβῳ συνέβαινεν οὐ μικρῷ τοὺς ἐπιχωρίους εἶναι, καὶ πρεσβευόμενοι πρὸς ἀλλήλους παρεκάλουν ἀμύνειν καὶ πειρᾶσθαι τοὺς ἄνδρας διαφθείρειν."},{"number":40,"text":"ἐτύγχανον δὲ οἱ πρὸς τοῦτο ἐνάγοντες οἵ τε τὴν Γοβολῖτιν καὶ τὴν Πέτραν κατοικοῦντες, οἳ καλοῦνται μὲν Ἀμαληκῖται, μαχιμώτατοι δὲ τῶν ἐκεῖσε ἐθνῶν ὑπῆρχον, ὧν πέμποντες οἱ βασιλεῖς ἀλλήλους τε καὶ τοὺς περιοίκους ἐπὶ τὸν πρὸς Ἑβραίους πόλεμον παρεκάλουν, στρατὸν ἀλλότριον καὶ τῆς Αἰγυπτίων ἀποδράντα δουλείας ἐφεδρεύειν αὐτοῖς λέγοντες,"},{"number":41,"text":"ὃν οὐ καλῶς ἔχει περιορᾶν, ἀλλὰ πρὶν ἢ λαβεῖν ἰσχὺν καὶ παρελθεῖν εἰς εὐπορίαν καὶ αὐτὸν τῆς πρὸς ἡμᾶς κατάρξαι μάχης θαρρήσαντας τῷ μηδὲν αὐτοῖς παρʼ ἡμῶν ἀπαντᾶν καταλύειν ἀσφαλὲς καὶ σῶφρον δίκην αὐτοὺς καὶ περὶ τῆς ἐρήμου καὶ τῶν ἐν αὐτῇ πραχθέντων ἀπαιτοῦντας, ἀλλʼ οὐχ ὅταν ταῖς πόλεσιν ἡμῶν καὶ τοῖς ἀγαθοῖς ἐπιβάλωσι τὰς χεῖρας."},{"number":42,"text":"οἱ δὲ ἀρχομένην δύναμιν ἐχθρῶν πειρώμενοι καταλύειν ἀγαθοὶ συνεῖναι μᾶλλον, ἢ οἱ προκόψασαν μείζω κωλύοντες γενέσθαι· οἱ μὲν γὰρ τοῦ περισσοῦ δοκοῦσι νεμεσᾶν, οἱ δʼ οὐδεμίαν αὐτοῖς ἀφορμὴν κατʼ αὐτῶν ἐῶσι γενέσθαι. τοιαῦτα τοῖς τε πλησιοχώροις καὶ πρὸς ἀλλήλους πρεσβευόμενοι χωρεῖν τοῖς Ἑβραίοις ἐγνώκεσαν εἰς μάχην."},{"number":43,"text":"Μωυσεῖ δʼ οὐδὲν προσδοκῶντι πολέμιον ἀπορίαν καὶ ταραχὴν ἐνεποίει τὰ τῶν ἐπιχωρίων, καὶ παρόντων ἐπὶ τὴν μάχην ἤδη καὶ κινδυνεύειν δέον ἐθορύβει χαλεπῶς τὸ τῶν Ἑβραίων πλῆθος ἐν ἀπορίᾳ μὲν ὂν ἁπάντων, μέλλον δὲ πολεμεῖν πρὸς ἀνθρώπους τοῖς πᾶσι καλῶς ἐξηρτυμένους."},{"number":44,"text":"παραμυθίας οὖν ὁ Μωυσῆς ἤρχετο καὶ θαρρεῖν παρεκάλει τῇ τοῦ θεοῦ ψήφῳ πεπιστευκότας, ὑφʼ ἧς εἰς τὴν ἐλευθερίαν ἠρμένοι κατανικήσειαν τοὺς περὶ αὐτῆς εἰς μάχην αὐτοῖς καθισταμένους,"},{"number":45,"text":"ὑπολαμβάνειν δὲ τὸ μὲν αὐτῶν εἶναι στράτευμα πολὺ καὶ πάντων ἀπροσδεές, ὅπλων χρημάτων τροφῆς τῶν ἄλλων, ὧν παρόντων ἐκ πεποιθήσεως πολεμοῦσιν ἄνθρωποι, κρίνοντας ἐν τῇ παρὰ τοῦ θεοῦ συμμαχίᾳ ταῦτα αὐτοῖς παρεῖναι, τὸ δὲ τῶν ἐναντίων ὀλίγον ἄνοπλον ἀσθενές, οἷον καὶ μὴ ὑπὸ τοιούτων, οἵοις αὐτοῖς σύνοιδεν οὖσιν, νικᾶσθαι βουλομένου τοῦ θεοῦ."},{"number":46,"text":"εἰδέναι δʼ οἷος οὗτος ἐπίκουρος ἐκ πολλῶν πεπειραμένους καὶ δεινοτέρων τοῦ πολέμου· τοῦτον μὲν γὰρ εἶναι πρὸς ἀνθρώπους, ἃ δʼ ἦν αὐτοῖς πρὸς λιμὸν καὶ δίψος ἄπορα καὶ πρὸς ὄρη καὶ θάλασσαν ὁδὸν οὐκ ἔχουσι φυγῆς, ταῦτʼ αὐτοῖς διὰ τὴν εὐμένειαν τὴν παρὰ τοῦ θεοῦ νενικῆσθαι. νῦν δὲ γίνεσθαι παρεκάλει προθυμοτάτους, ὡς τῆς ἁπάντων εὐπορίας αὐτοῖς ἐν τῷ κρατῆσαι τῶν ἐχθρῶν κειμένης."},{"number":47,"text":"Καὶ Μωυσῆς μὲν τοιούτοις παρεθάρσυνε τὸ πλῆθος λόγοις συγκαλῶν τούς τε φυλάρχους καὶ τῶν ἐν τέλει καθʼ ἑκάστους τε καὶ σὺν ἀλλήλοις τοὺς μὲν νεωτέρους παρεκάλει πείθεσθαι τοῖς πρεσβυτέροις, τοὺς δὲ ἀκροᾶσθαι τοῦ στρατηγοῦ·"},{"number":48,"text":"οἱ δʼ ἦσαν ἐπὶ τὸν κίνδυνον τὰς ψυχὰς ἠρμένοι καὶ πρὸς τὸ δεινὸν ἑτοίμως ἔχοντες ἤλπιζον ἀπαλλαγήσεσθαί ποτε τῶν κακῶν, καὶ τὸν Μωυσῆν ἐκέλευον ἄγειν αὐτοὺς ἐπὶ τοὺς πολεμίους ἤδη καὶ μὴ μέλλειν, ὡς τῆς ἀναβολῆς ἐμποδιζούσης τὴν προθυμίαν αὐτῶν."},{"number":49,"text":"ὁ δὲ τῆς πληθύος ἀποκρίνας πᾶν τὸ μάχιμον Ἰησοῦν ἐφίστησιν αὐτῷ Ναυήκου μὲν υἱὸν φυλῆς τῆς Ἐφραιμίτιδος, ἀνδρειότατον δὲ καὶ πόνους ὑποστῆναι γενναῖον καὶ νοῆσαί τε καὶ εἰπεῖν ἱκανώτατον καὶ θρησκεύοντα τὸν θεὸν ἐκπρεπῶς καὶ Μωυσῆν διδάσκαλον τῆς πρὸς αὐτὸν εὐσεβείας πεποιημένον τιμώμενόν τε παρὰ τοῖς Ἑβραίοις."},{"number":50,"text":"βραχὺ δέ τι περὶ τὸ ὕδωρ ἔταξε τῶν ὁπλιτῶν ἐπὶ φυλακῇ παίδων καὶ γυναικῶν τοῦ τε παντὸς στρατοπέδου. καὶ νύκτα μὲν πᾶσαν ἐν παρασκευαῖς ἦσαν τῶν τε ὅπλων εἴ τι πεπονηκὸς ἦν ἀναλαμβάνοντες καὶ τοῖς στρατηγοῖς προσέχοντες, ὡς ὁρμήσοντες ἐπὶ τὴν μάχην ὁπότε κελεύσειεν αὐτοὺς Μωυσῆς. διηγρύπνει δὲ καὶ Μωυσῆς ἀναδιδάσκων τὸν Ἰησοῦν ὃν τρόπον ἐκτάξειε τὸ στρατόπεδον."},{"number":51,"text":"ἠργμένης δὲ ὑποφαίνειν τῆς ἡμέρας αὖθις τόν τε Ἰησοῦν παρεκάλει μηδὲν χείρονα φανῆναι κατὰ τὸ ἔργον τῆς οὔσης περὶ αὐτὸν ἐλπίδος δόξαν τε διὰ τῆς παρούσης κτήσασθαι στρατηγίας παρὰ τοῖς ἀρχομένοις ἐπὶ τοῖς γεγενημένοις, τῶν τε Ἑβραίων τοὺς ἀξιολογωτάτους ἰδίᾳ παρεκάλει καὶ σύμπαν ἤδη τὸ πλῆθος ὡπλισμένον παρώρμα."},{"number":52,"text":"καὶ ὁ μὲν οὕτως παραστησάμενος τὸν στρατὸν τοῖς τε λόγοις καὶ τῇ διὰ τῶν ἔργων παρασκευῇ ἀνεχώρει πρὸς τὸ ὄρος θεῷ τε καὶ Ἰησοῦ παραδιδοὺς τὸ στράτευμα."},{"number":53,"text":"Προσέμισγον δὲ οἱ πολέμιοι κἀν χερσὶν ἦν ἡ μάχη· προθυμίᾳ δὲ καὶ διακελευσμῷ τὰ πρὸς ἀλλήλους χρωμένων μέχρι μὲν οὖν Μωυσῆς αὖθις ἀνίσχει τὰς χεῖρας, καὶ τοὺς Ἀμαληκίτας κατεπόνουν οἱ Ἑβραῖοι. τὸν οὖν πόνον τῆς ἀνατάσεως τῶν χειρῶν ὁ Μωυσῆς οὐχ ὑπομένων, ὁσάκις γὰρ ἂν αὐτὰς καθίει τοσαυτάκις ἐλαττοῦσθαι τοὺς οἰκείους αὐτοῦ συνέβαινε,"},{"number":54,"text":"κελεύει τόν τε ἀδελφὸν Ἀαρῶνα καὶ τῆς ἀδελφῆς Μαριάμης τὸν ἄνδρα Οὖρον ὄνομα στάντας ἑκατέρωθεν αὐτοῦ διακρατεῖν τὰς χεῖρας καὶ μὴ ἐπιτρέπειν κάμνειν βοηθοῦντας. καὶ τούτου γενομένου κατὰ κράτος ἐνίκων τοὺς Ἀμαληκίτας οἱ Ἑβραῖοι, καὶ πάντες ἂν ἀπωλώλεισαν, εἰ μὴ νυκτὸς ἐπιγενομένης ἀπέσχοντο τοῦ κτείνειν."},{"number":55,"text":"νίκην καλλίστην καὶ καιριωτάτην νικῶσιν ἡμῶν οἱ πρόγονοι· καὶ γὰρ τῶν ἐπιστρατευσάντων ἐκράτησαν καὶ τοὺς περιοίκους ἐφόβησαν, μεγάλων τε καὶ λαμπρῶν ἐκ τοῦ πονεῖν ἐπέτυχον ἀγαθῶν ἑλόντες τὸ στρατόπεδον τῶν πολεμίων, πλούτους τε μεγάλους δημοσίᾳ καὶ κατʼ ἰδίαν ἔσχον οὐδὲ τῆς ἀναγκαίου τροφῆς πρότερον εὐποροῦντες."},{"number":56,"text":"ὑπῆρξε δʼ αὐτοῖς οὐκ εἰς τὸ παρὸν μόνον, ἀλλὰ καὶ εἰς τὸν αὖθις αἰῶνα τῶν ἀγαθῶν αἰτία κατορθωθεῖσα ἡ προειρημένη μάχη· οὐ γὰρ τὰ σώματα μόνον τῶν ἐπιστρατευσάντων ἐδούλωσαν ἀλλὰ καὶ τὰ φρονήματα, καὶ τοῖς περιοίκοις ἅπασι μετὰ τὴν ἐκείνων ἧτταν ἐγένοντο φοβεροί, αὐτοί τε πλούτου μεγάλου δύναμιν προσέλαβον·"},{"number":57,"text":"πολὺς γὰρ ὁ ἄργυρός τε καὶ χρυσὸς ἐγκατελήφθη ἐν τῷ στρατοπέδῳ καὶ σκεύη χαλκᾶ, οἷς ἐχρῶντο περὶ τὴν δίαιταν, πολὺ δὲ ἐπίσημον πλῆθος ἑκατέρων ὅσα τε ὑφαντὰ καὶ κόσμοι περὶ τὰς ὁπλίσεις ἥ τε ἄλλη θεραπεία καὶ κατασκευὴ ἐκείνων λεία τε παντοία κτηνῶν καὶ ὅσα φιλεῖ στρατοπέδοις ἐξωδευκόσιν ἕπεσθαι."},{"number":58,"text":"φρονήματός τε ὑπεπλήσθησαν ἐπʼ ἀνδρείᾳ Ἑβραῖοι καὶ πολλὴ μεταποίησις ἦν ἀρετῆς αὐτοῖς πρός τε τῷ πονεῖν ἦσαν ἀεὶ τούτῳ πάντα ληπτὰ νομίζοντες εἶναι. καὶ ταύτης μὲν τῆς μάχης τοῦτο τὸ πέρας."},{"number":59,"text":"Τῇ δʼ ὑστεραίᾳ Μωυσῆς νεκρούς τε ἐσκύλευε τῶν πολεμίων καὶ τὰς παντευχίας τῶν φυγόντων συνέλεγεν ἀριστεῦσί τε τιμὰς ἐδίδου καὶ τὸν στρατηγὸν Ἰησοῦν ἐνεκωμίαζε μαρτυρούμενον ἐφʼ οἷς ἔπραξεν ὑπὸ παντὸς τοῦ στρατοῦ. ἀπέθανεν δὲ Ἑβραίων μὲν οὐδείς, τῶν δὲ πολεμίων ὅσους οὐδʼ ἀριθμῷ γνῶναι δυνατὸν ἦν."},{"number":60,"text":"θύσας δὲ χαριστήρια βωμὸν ἱδρύεται νικαῖον ὀνομάσας τὸν θεὸν προεφήτευέ τε πανωλεθρὶ τοὺς Ἀμαληκίτας ἀπολουμένους καὶ μηδένα αὐτῶν ὑπολειφθησόμενον εἰς αὖθις διὰ τὸ Ἑβραίοις ἐπιστρατεύσασθαι καὶ ταῦτα ἐν ἐρήμῳ τε γῇ καὶ ταλαιπωρουμένοις, τόν τε στρατὸν εὐωχίαις ἀνελάμβανε."},{"number":61,"text":"καὶ ταύτην μὲν τὴν μάχην πρώτην μαχεσάμενοι πρὸς τοὺς κατατολμήσαντας αὐτῶν μετὰ τὴν ἐξ Αἰγύπτου γενομένην ἔξοδον οὕτως ἐπολέμησαν, ἐπεὶ δὲ τὴν τῶν ἐπινικίων ἑορτὴν ἤγαγον, ὁ Μωυσῆς ἀναπαύσας ἐπʼ ὀλίγας ἡμέρας τοὺς Ἑβραίους μετὰ τὴν μάχην προῆγε συντεταγμένους·"},{"number":62,"text":"πολὺ δʼ ἦν ἤδη τὸ ὁπλιτικὸν αὐτοῖς· καὶ προϊὼν κατʼ ὀλίγον ἐν τριμήνῳ μετὰ τὴν ἐξ Αἰγύπτου κίνησιν παρῆν ἐπὶ τὸ Σιναῖον ὄρος, ἐν ᾧ τά τε περὶ τὸν θάμνον αὐτῷ καὶ τὰ λοιπὰ φαντάσματα συντυχεῖν προειρήκαμεν."}],"3":[{"number":63,"text":"Καὶ Ῥαγουῆλος ὁ πενθερὸς αὐτοῦ πυνθανόμενος εὐπραξίαν ἀσμένως ἀπήντα τόν τε Μωυσῆν καὶ τὴν Σαπφώραν δεχόμενος καὶ τοὺς παῖδας αὐτῶν. ἥδεται δὲ Μωυσῆς ἐπὶ τῇ τοῦ πενθεροῦ ἀφίξει καὶ θύσας εὐωχεῖ τὸ πλῆθος τοῦ θάμνου πλησίον, ὃς διαπεφεύγει τοῦ πυρὸς τὴν φλόγωσιν·"},{"number":64,"text":"καὶ τὸ μὲν πλῆθος κατὰ συγγένειαν ὡς ἕκαστοι τῆς εὐωχίας μετελάμβανον, Ἀαρὼν δὲ σὺν τοῖς παροῦσι Ῥαγουῆλον προσλαβόμενος ὕμνους τε ᾖδον εἰς τὸν θεὸν ὡς τῆς σωτηρίας αὐτοῖς καὶ τῆς ἐλευθερίας αἴτιον καὶ ποριστὴν γεγενημένον,"},{"number":65,"text":"καὶ τὸν στρατηγὸν εὐφήμουν ὡς κατὰ ἀρετὴν ἐκείνου πάντων αὐτοῖς κατὰ νοῦν ἀπηντηκότων. καὶ Ῥαγουῆλος πολλὰ μὲν ἐγκώμια τοῦ πλήθους ἐπὶ τῇ πρὸς τὸν Μωυσῆν εὐχαριστίᾳ διεξῄει, ἐθαύμαζε δὲ καὶ τὸν Μωυσῆν τῆς ἐπὶ σωτηρίᾳ τῶν φίλων ἀνδραγαθίας."}],"4":[{"number":66,"text":"Τῇ δʼ ὑστεραίᾳ θεασάμενος ὁ Ῥαγουῆλος τὸν Μωυσῆν ἐν ὄχλῳ πραγμάτων ὄντα· διέλυε γὰρ τὰς δίκας τοῖς δεομένοις πάντων ἐπʼ αὐτὸν βαδιζόντων καὶ μόνως ἂν τοῦ δικαίου τυχεῖν ἡγουμένων, εἰ διαιτητὴς αὐτοῖς οὗτος γένοιτο·"},{"number":67,"text":"καὶ γὰρ τοῖς ἡττωμένοις κοῦφον ἐδόκει τὸ λείπεσθαι κατὰ δικαιοσύνην οὐ κατὰ πλεονεξίαν αὐτὸ πάσχειν νομίζουσι· τότε μὲν ἡσυχίαν ἦγε μὴ βουλόμενος ἐμποδίζειν τοῖς ἀρετῇ χρῆσθαι τοῦ στρατηγοῦ θέλουσι, παυσάμενον δὲ τοῦ θορύβου παραλαβὼν καὶ συμμονωθεὶς ἀνεδίδασκεν ἃ δεῖ ποιεῖν."},{"number":68,"text":"καὶ συνεβούλευε τῆς μὲν ἐπὶ τοῖς ἥττοσι ταλαιπωρίας ἑτέροις ἐκστῆναι, περὶ δὲ τῶν μειζόνων καὶ τῆς σωτηρίας τοῦ πλήθους ἔχειν τὴν πρόνοιαν αὐτόν· δικάσαι μὲν γὰρ ἀγαθοὺς κἂν ἄλλους Ἑβραίων εὑρεθῆναι, φροντίσαι δὲ τοσούτων μυριάδων σωτηρίας οὐκ ἄλλον τινὰ δύνασθαι μὴ Μωυσῆν γενόμενον."},{"number":69,"text":"αἰσθανόμενος οὖν τῆς ἀρετῆς, φησί, σαυτοῦ καὶ οἷος γέγονας ἐπὶ τῷ τὸν λαὸν ὑπουργῶν τῷ θεῷ σώζειν τὴν μὲν τῶν ἐγκλημάτων δίαιταν ἐπίτρεψον αὐτοῖς ποιεῖσθαι καὶ ἐπʼ ἄλλων, σὺ δὲ πρὸς μόνῃ τῇ τοῦ θεοῦ θεραπείᾳ κατέχων σεαυτὸν διατέλει ζητῶν οἷς ἂν τὸ πλῆθος ἀπαλλάξειας τῆς νῦν ἀπορίας."},{"number":70,"text":"ὑποθήκαις δὲ ταῖς ἐμαῖς περὶ τῶν ἀνθρωπίνων χρησάμενος τὸν στρατὸν ἐξετάσεις ἀκριβῶς καὶ κατὰ μυρίους τούτων κεκριμένους ἄρχοντας ἀποδείξεις, εἶτα κατὰ χιλίους, διαιρήσεις δὲ μετʼ αὐτοὺς εἰς πεντακοσίους, καὶ πάλιν εἰς ἑκατόν, εἶτʼ εἰς πεντήκοντα."},{"number":71,"text":"ἄρχοντάς τε ἐπὶ τούτοις τάξεις, οἳ κατὰ τριάκοντα μερισθέντας διακοσμήσουσι καὶ κατὰ εἴκοσι καὶ κατὰ δέκα συναριθμουμένους, ἔστω δέ τις ἐπὶ τούτοις εἷς τὴν προσηγορίαν ἀπὸ τοῦ τῶν ἀρχομένων ἀριθμοῦ λαμβάνων, δοκιμασθέντες ὑπὸ τοῦ πλήθους παντὸς εἶναι ἀγαθοὶ καὶ δίκαιοι,"},{"number":72,"text":"οἳ περί τε τῶν διαφόρων αὐτοῖς κρινοῦσι κἂν ᾖ τι μεῖζον ἐπὶ τοὺς ἐν ἀξιώματι τὴν περὶ τούτου διάγνωσιν ἐπανοίσουσιν, ἂν δὲ κἀκείνους διαφύγῃ τὸ περὶ τοῦ πράγματος δύσκολον, ἐπὶ σὲ τοῦτο ἀναπέμψουσιν· ἔσται γὰρ οὕτως ἀμφότερα· καὶ τῶν δικαίων Ἑβραῖοι τεύξονται καὶ σὺ τῷ θεῷ προσεδρεύων εὐμενέστερον ἂν ποιήσειας αὐτὸν τῷ στρατῷ."},{"number":73,"text":"Ταῦτα Ῥαγουήλου παραινέσαντος Μωυσῆς ἀσμένως προσήκατο τὴν συμβουλίαν καὶ ποιεῖ κατὰ τὴν ὑποθήκην τὴν ἐκείνου τοῦ τρόπου τὴν ἐπίνοιαν οὐκ ἀποκρυψάμενος οὐδὲ σφετερισάμενος αὐτήν, ἀλλὰ ποιήσας φανερὸν τὸν ἐξευρηκότα τῷ πλήθει."},{"number":74,"text":"κἀν τοῖς βιβλίοις δὲ Ῥαγουῆλον ἔγραψεν ὡς εὑρηκότα τὴν διάταξιν τὴν προειρημένην, καλῶς ἔχειν ἡγούμενος τἀληθῆ μαρτυρεῖν τοῖς ἀξίοις, εἰ καὶ δόξαν ἔμελλε φέρειν ἐπιγραφομένῳ τὰ ὑπὸ ἄλλων εὑρημένα, ὥστε τὴν Μωυσέος ἀρετὴν κἀκ τούτου καταμαθεῖν. ἀλλὰ περὶ μὲν ταύτης εὐκαίρως ἐν ἄλλοις τῆς γραφῆς δηλώσομεν."}],"5":[{"number":75,"text":"Μωυσῆς δὲ συγκαλέσας τὴν πληθὺν αὐτὸς μὲν εἰς τὸ ὄρος ἀπέρχεσθαι τὸ Σιναῖον ἔλεγεν ὡς συνεσόμενος τῷ θεῷ καί τι λαβὼν παρʼ αὐτοῦ χρήσιμον ἐπανήξων πρὸς αὐτούς, ἐκείνους δʼ ἐκέλευσε πλησίον μετασκηνῶσαι τῷ ὄρει τὴν γειτνίασιν τοῦ θεοῦ προτιμήσαντας."},{"number":76,"text":"ταῦτʼ εἰπὼν ἀνῄει πρὸς τὸ Σιναῖον ὑψηλότατον τῶν ἐν ἐκείνοις τοῖς χωρίοις ὀρῶν τυγχάνον καὶ διὰ τὴν ὑπερβολὴν τοῦ μεγέθους καὶ τῶν κρημνῶν τὸ ἀπότομον ἀνθρώποις οὐ μόνον οὐκ ἀναβατὸν ἀλλʼ οὐδὲ ὁραθῆναι δίχα πόνου τῆς ὄψεως δυνάμενον ἄλλως τε διὰ τὸ λόγον εἶναι περὶ τοῦ τὸν θεὸν ἐν αὐτῷ διατρίβειν φοβερὸν καὶ ἀπρόσιτον."},{"number":77,"text":"Ἑβραῖοι δὲ κατὰ τὰς Μωυσέος ἐντολὰς μετεσκήνουν καὶ τὰς ὑπωρείας τοῦ ὄρους κατελαμβάνοντο ἠρμένοι ταῖς διανοίαις ὡς μετὰ τῆς ἐπαγγελίας τῶν ἀγαθῶν, ἣν προύτεινεν αὐτοῖς, ἐπανήξοντος Μωυσέος παρὰ τοῦ θεοῦ."},{"number":78,"text":"ἑορτάζοντες δὲ τὸν στρατηγὸν περιέμενον ἁγνεύοντες τήν τε ἄλλην ἁγνείαν καὶ ἀπὸ συνουσίας τῆς γυναικῶν ἡμέρας τρεῖς, καθὼς ἐκεῖνος αὐτοῖς προεῖπε, καὶ παρακαλοῦντες τὸν θεὸν εὐμενῆ συμβάλλοντα Μωυσεῖ δοῦναι δωρεάν, ὑφʼ ἧς εὖ βιώσονται. ταῖς τʼ οὖν διαίταις ἐχρῶντο πολυτελεστέραις καὶ τῷ κόσμῳ γυναιξὶν ὁμοῦ καὶ τέκνοις ἐκπρεπῶς ἤσκηντο."},{"number":79,"text":"Ἐπὶ δύο μὲν οὖν ἡμέρας εὐωχούμενοι διῆγον, τῇ τρίτῃ δὲ πρὶν τὸν ἥλιον ἀνασχεῖν νεφέλη τε ὑπεράνω ἀνέσχε τοῦ παντὸς στρατοπέδου τῶν Ἑβραίων οὐ πρότερον τοῦτο ἰδόντων γενόμενον καὶ τὸ χωρίον οὗ τὰς σκηνὰς ἦσαν πεποιημένοι περιέγραφε,"},{"number":80,"text":"καὶ τοῦ λοιποῦ παντὸς ἐν αἰθρίᾳ τυγχάνοντος ἄνεμοί τε σφοδροὶ λάβρον κινοῦντες ὑετὸν κατῄγιζον, ἀστραπαί τε ἦσαν φοβεραὶ τοῖς ὁρῶσι, καὶ κεραυνοὶ κατενεχθέντες ἐδήλουν τὴν παρουσίαν τοῦ θεοῦ οἷς Μωυσῆς ἔχαιρεν εὐμενοῦς παρατυχόντος."},{"number":81,"text":"καὶ περὶ μὲν τούτων ὡς βούλεται φρονείτω ἕκαστος τῶν ἐντευξομένων, ἐμοὶ δὲ ἀνάγκη ταῦτα ἱστορεῖν καθάπερ ἐν ταῖς ἱεραῖς βίβλοις ἀναγέγραπται. τοὺς δὲ Ἑβραίους τά τε ὁρώμενα καὶ ὁ ταῖς ἀκοαῖς προσβάλλων ψόφος δεινῶς ἐτάραττεν,"},{"number":82,"text":"ἀήθεις τε γὰρ ἦσαν αὐτῶν, καὶ ὁ περὶ τοῦ ὄρους διαπεφοιτηκὼς λόγος ὡς εἰς αὐτὸ τοῦτο φοιτῶντος τοῦ θεοῦ σφόδρα τὴν διάνοιαν αὐτῶν ἐξέπληττε. κατεῖχον δʼ αὑτοὺς πρὸς ταῖς σκηναῖς ἀχθόμενοι καὶ τόν τε Μωυσῆν ἀπολωλέναι νομίζοντες ὑπʼ ὀργῆς τοῦ θεοῦ καὶ περὶ αὐτῶν ὅμοια προσδοκῶντες."},{"number":83,"text":"Οὕτως δʼ αὐτῶν διακειμένων ἐπιφαίνεται Μωυσῆς γαῦρός τε καὶ μέγα φρονῶν. ὀφθείς τε οὖν αὐτὸς ἀπαλλάσσει τοῦ δέους αὐτοὺς καὶ περὶ τῶν μελλόντων κρείττονας ὑπετίθετο τὰς ἐλπίδας, αἴθριός τε καὶ καθαρὸς ὁ ἀὴρ τῶν πρὸ ὀλίγου παθῶν ἦν Μωυσέος παραγεγονότος."},{"number":84,"text":"ἐπὶ τούτοις οὖν συγκαλεῖ τὸ πλῆθος εἰς ἐκκλησίαν ἀκουσόμενον ὧν ὁ θεὸς εἴποι πρὸς αὐτόν, καὶ συναθροισθέντων στὰς ἐπὶ ὑψηλοῦ τινος, ὅθεν ἔμελλον πάντες ἀκούσεσθαι, ὁ μὲν θεός, εἶπεν, ὦ Ἑβραῖοι, καθάπερ καὶ πρότερον εὐμενὴς προσεδέξατό με καὶ βίον τε ὑμῖν εὐδαίμονα καὶ πολιτείας κόσμον ὑπαγορεύσας πάρεστι καὶ αὐτὸς εἰς τὸ στρατόπεδον."},{"number":85,"text":"πρὸς γοῦν αὐτοῦ καὶ τῶν ἔργων, ἃ διʼ ἐκεῖνον ἡμῖν ἤδη πέπρακται, μὴ καταφρονήσητε τῶν λεγομένων εἰς ἐμὲ τὸν λέγοντα ἀφορῶντες μηδʼ ὅτι γλῶττα ἀνθρωπίνη πρὸς ὑμᾶς λέγει· τὴν δʼ ἀρετὴν αὐτῶν κατανοήσαντες ἐπιγνώσεσθε καὶ τὸ μέγεθος τοῦ νενοηκότος καὶ ἐπὶ συμφέροντι τῷ ὑμετέρῳ πρὸς ἐμὲ μὴ φθονήσαντος εἰπεῖν·"},{"number":86,"text":"οὐ γὰρ Μωυσῆς ὁ Ἀμαράμου καὶ Ἰωχαβάδης υἱός, ἀλλʼ ὁ τὸν Νεῖλον ἀναγκάσας ᾑματωμένον ὑπὲρ ὑμῶν ῥυῆναι καὶ ποικίλοις δαμάσας κακοῖς τὸ τῶν Αἰγυπτίων φρόνημα, ὁ διὰ θαλάσσης ὁδὸν ὑμῖν παρασχών, ὁ καὶ τροφὴν ἐξ οὐρανοῦ μηχανησάμενος ἐλθεῖν ἀπορουμένοις,"},{"number":87,"text":"ὁ ποτὸν ἐκ πέτρας ἀναβλύσας σπανίζουσι, διʼ ὃν Ἄδαμος τῶν ἀπὸ γῆς τε καρπῶν καὶ θαλάσσης μεταλαμβάνει, διʼ ὃν Νῶχος ἐκ τῆς ἐπομβρίας διέφυγε, διʼ ὃν Ἅβραμος ὁ ἡμέτερος πρόγονος ἐξ ἀλήτου τὴν Χαναναίαν κατέσχε γῆν, διʼ ὃν Ἴσακος γηραιοῖς ἐτέχθη γονεῦσι, διʼ ὃν Ἰάκωβος δώδεκα παίδων ἀρεταῖς ἐκοσμήθη, διʼ ὃν Ἰώσηπος ἐδεσπότευσε τῆς Αἰγυπτίων δυνάμεως, οὗτος ὑμῖν τούτους χαρίζεται τοὺς λόγους διʼ ἑρμηνέως ἐμοῦ."},{"number":88,"text":"σεβάσμιοι δʼ ὑμῖν γενέσθωσαν καὶ παίδων περιμαχητότεροι καὶ γυναικῶν· εὐδαίμονα γὰρ διάξετε βίον τούτοις ἑπόμενοι καὶ γῆς ἀπολαύοντες καρπίμου καὶ θαλάσσης ἀχειμάστου καὶ τέκνων γονῆς κατὰ φύσιν τικτομένων καὶ πολεμίοις ἔσεσθε φοβεροί· τῷ θεῷ γὰρ εἰς ὄψιν ἐλθὼν ἀκροατὴς ἀφθάρτου φωνῆς ἐγενόμην· οὕτως ἐκείνῳ τοῦ γένους ἡμῶν καὶ τῆς τούτου μέλει διαμονῆς."},{"number":89,"text":"Ταῦτʼ εἰπὼν προάγει τὸν λαὸν γυναιξὶν ὁμοῦ καὶ τέκνοις, ὡς ἀκούσαιεν τοῦ θεοῦ διαλεγομένου πρὸς αὐτοὺς περὶ τῶν πρακτέων, ἵνα μὴ βλαβείη τῶν λεγομένων ἡ ἀρετὴ ὑπὸ ἀνθρωπίνης γλώττης ἀσθενῶς εἰς γνῶσιν αὐτοῖς παραδιδομένη."},{"number":90,"text":"πάντες τε ἤκουον φωνῆς ὑψόθεν παραγενομένης εἰς ἅπαντας, ὡς διαφυγεῖν μηδένα καὶ λόγων οὓς Μωυσῆς ἐν ταῖς δύο πλαξὶ γεγραμμένους κατέλιπεν· οὓς οὐ θεμιτόν ἐστιν ἡμῖν λέγειν φανερῶς πρὸς λέξιν, τὰς δὲ δυνάμεις αὐτῶν δηλώσομεν."},{"number":91,"text":"Διδάσκει μὲν οὖν ἡμᾶς ὁ πρῶτος λόγος, ὅτι θεός ἐστιν εἷς καὶ τοῦτον δεῖ σέβεσθαι μόνον· ὁ δὲ δεύτερος κελεύει μηδενὸς εἰκόνα ζῴου ποιήσαντας προσκυνεῖν· ὁ τρίτος δὲ ἐπὶ μηδενὶ φαύλῳ τὸν θεὸν ὀμνύναι· ὁ δὲ τέταρτος παρατηρεῖν τὰς ἑβδομάδας ἀναπαυομένους ἀπὸ παντὸς ἔργου·"},{"number":92,"text":"ὁ δὲ πέμπτος γονεῖς τιμᾶν· ὁ δὲ ἕκτος ἀπέχεσθαι φόνου· ὁ δὲ ἕβδομος μὴ μοιχεύειν· ὁ δὲ ὄγδοος μὴ κλοπὴν δρᾶν· ὁ δὲ ἔνατος μὴ ψευδομαρτυρεῖν· ὁ δὲ δέκατος μηδενὸς ἀλλοτρίου ἐπιθυμίαν λαμβάνειν."},{"number":93,"text":"Καὶ τὸ μὲν πλῆθος ἀκροασάμενον αὐτοῦ τοῦ θεοῦ περὶ ὧν Μωυσῆς διελέχθη χαῖρον ἐπὶ τοῖς προειρημένοις τοῦ συλλόγου διελύθη, ταῖς δʼ ἐφεξῆς φοιτῶντες ἐπὶ τὴν σκηνὴν ἠξίουν αὐτὸν καὶ νόμους αὐτοῖς παρὰ τοῦ θεοῦ κομίζειν."},{"number":94,"text":"ὁ δὲ τούτους τε τίθεται καὶ περὶ τῶν ὅλων ὃν ἂν πραχθείη τρόπον ἐν τοῖς αὖθις ἀπεσήμαινε χρόνοις, ὧν μνησθήσομαι κατὰ καιρὸν οἰκεῖον. τοὺς δὲ πλείονας τῶν νόμων εἰς ἑτέραν ἀνατίθεμαι γραφὴν ἰδίαν περὶ αὐτῶν ποιησόμενος ἀφήγησιν."},{"number":95,"text":"Οὕτω δὲ τῶν πραγμάτων αὐτοῖς ἐχόντων ὁ Μωυσῆς πάλιν εἰς τὸ Σιναῖον ὄρος ἀνῄει προειπὼν τοῖς Ἑβραίοις, βλεπόντων δʼ αὐτῶν ἐποιεῖτο τὴν ἄνοδον. καὶ χρόνου τριβομένου, τεσσαράκοντα γὰρ ἡμέρας διήγαγεν ἀπʼ αὐτῶν, δέος εἶχε τοὺς Ἑβραίους, μή τι Μωυσῆς πάθοι, καὶ τῶν συντυχόντων δεινῶν οὐκ ἔστιν ὃ οὕτως ἐλύπησεν αὐτούς, ὡς τὸ νομίζειν Μωυσῆν ἀπολωλέναι."},{"number":96,"text":"ἦν γὰρ τοῖς ἀνθρώποις ἔρις τῶν μὲν ἀπολωλέναι λεγόντων θηρίοις περιπεσόντα, καὶ μάλιστα ὅσοι πρὸς αὐτὸν ἀπεχθῶς ἦσαν διακείμενοι ταύτην τὴν ψῆφον ἔφερον, τῶν δὲ πρὸς τὸ θεῖον ἀνακεχωρηκέναι."},{"number":97,"text":"τοὺς δὲ σώφρονας καὶ μηδέτερον τῶν λεγομένων εἰς ἡδονὴν λαμβάνοντας ἰδίαν, καὶ τὸ θηρίοις περιπεσόντα ἀποθανεῖν ἀνθρώπινον ἡγουμένους καὶ τὸ ὑπὸ τοῦ θεοῦ πρὸς αὐτὸν μεταστῆναι διὰ τὴν προσοῦσαν ἀρετὴν εἰκὸς νομίζοντας, πρᾴως ἔχειν οὗτος ὁ λογισμὸς ἐποίει."},{"number":98,"text":"προστάτου δὲ ἠρημῶσθαι καὶ κηδεμόνος ὑπολαμβάνοντες, οἵου τυχεῖν οὐκ ἂν ἄλλου δύναιντο, σφόδρα λυπούμενοι διετέλουν καὶ οὔτε ὑπονοεῖν αὐτοὺς εἴα τὸ προσδοκᾶν τι χρηστὸν περὶ τἀνδρὸς οὔτε μὴ λυπεῖσθαι καὶ κατηφεῖν ἠδύναντο. τὸ δὲ στρατόπεδον οὐκ ἐθάρρουν μετάγειν Μωυσέος αὐτοὺς ἐκεῖ παραμένειν προειρηκότος."},{"number":99,"text":"Ἤδη δὲ τεσσαράκοντα ἡμερῶν διεληλυθυιῶν καὶ τοσούτων νυκτῶν παρῆν οὐδενὸς σιτίου τῶν τοῖς ἀνθρώποις νενομισμένων γεγευμένος. χαρᾶς δʼ ἐνέπλησε τὴν στρατιὰν ἐπιφανείς, καὶ τὴν τοῦ θεοῦ πρόνοιαν ἣν εἶχε περὶ αὐτῶν ἀπεδήλου τόν τε τρόπον καθʼ ὃν εὐδαιμονήσουσι πολιτευόμενοι λέγων αὐτῷ κατὰ ταύτας ὑποθέσθαι τὰς ἡμέρας,"},{"number":100,"text":"καὶ σκηνὴν ὅτι βούλεται γενέσθαι αὐτῷ, εἰς ἣν κάτεισι πρὸς αὐτοὺς παραγινόμενος, ὅπως καὶ μεταβαίνοντες ἀλλαχοῦ ταύτην ἐπαγώμεθα καὶ μηκέτι δεώμεθα τῆς ἐπὶ τὸ Σιναῖον ἀνόδου, ἀλλʼ αὐτὸς ἐπιφοιτῶν τῇ σκηνῇ παρατυγχάνῃ ταῖς ἡμετέραις εὐχαῖς."},{"number":101,"text":"γενήσεται δὲ ἡ σκηνὴ μέτροις τε καὶ κατασκευῇ οἷς αὐτὸς ὑπέδειξεν ὑμῶν ἀόκνως ἐχόντων πρὸς τὸ ἔργον. ταῦτʼ εἰπὼν δύο πλάκας αὐτοῖς ἐπιδείκνυσιν ἐγγεγραμμένους ἐχούσας τοὺς δέκα λόγους, ἐν ἑκατέρᾳ πέντε. καὶ χεὶρ ἦν ἐπὶ τῇ γραφῇ τοῦ θεοῦ."}],"6":[{"number":102,"text":"Οἱ δὲ χαίροντες οἷς τε ἑώρων καὶ οἷς ἤκουον τοῦ στρατηγοῦ τῆς κατὰ δύναμιν αὐτῶν σπουδῆς οὐκ ἀπελείποντο, ἀλλʼ εἰσέφερον ἄργυρόν τε καὶ χρυσὸν καὶ χαλκὸν ξύλα τε τῆς καλλίστης ὕλης καὶ μηδὲν ὑπὸ τῆς σήψεως παθεῖν δυνάμενα, αἰγείους τε τρίχας καὶ δορὰς προβάτων τὰς μὲν ὑακίνθῳ βεβαμμένας τὰς δὲ φοίνικι· αἱ δὲ πορφύρας ἄνθος, ἕτεραι δὲ λευκὴν παρεῖχον τὴν χρόαν·"},{"number":103,"text":"ἔριά τε τοῖς προειρημένοις ἄνθεσι μεμολυσμένα καὶ λίνου βύσσον λίθους τε τούτοις ἐνδεδεμένους, οὓς χρυσίῳ καθειργνύντες ἄνθρωποι κόσμῳ χρῶνται πολυτελεῖ, θυμιαμάτων τε πλῆθος συνέφερον· ἐκ γὰρ τοιαύτης ὕλης κατεσκεύασε τὴν σκηνήν. ἡ δʼ οὐδὲν μεταφερομένου καὶ συμπερινοστοῦντος ναοῦ διέφερε."},{"number":104,"text":"τούτων οὖν κατὰ σπουδὴν συγκομισθέντων ἑκάστου καὶ παρὰ δύναμιν φιλοτιμησαμένου, ἀρχιτέκτονας τοῖς ἔργοις ἐφίστησι κατʼ ἐντολὴν τοῦ θεοῦ οὓς καὶ τὸ πλῆθος ἂν ἐπελέξατο τῆς ἐξουσίας ἐπʼ αὐτῷ γενομένης."},{"number":105,"text":"τὰ δὲ ὀνόματα αὐτῶν, καὶ γὰρ ἐν ταῖς ἱεραῖς βίβλοις ἀναγέγραπται, ταῦτʼ ἦν· Βασάηλος μὲν Οὐρὶ παῖς τῆς Ἰούδα φυλῆς, υἱὸς δὲ Μαριάμης τῆς ἀδελφῆς τοῦ στρατηγοῦ, Ἐλίβαζος δὲ Ἰσαμάχου Δανίδος φυλῆς."},{"number":106,"text":"τὸ δὲ πλῆθος οὕτως ὑπὸ προθυμίας τοῖς ἐγχειρουμένοις ἐπῆλθεν, ὥστε Μωυσῆς ἀνεῖρξεν αὐτοὺς ὑποκηρυξάμενος ἀρκεῖν τοὺς ὄντας· τοῦτο γὰρ οἱ δημιουργοὶ προειρήκεσαν· ἐχώρουν οὖν ἐπὶ τὴν τῆς σκηνῆς κατασκευήν,"},{"number":107,"text":"καὶ Μωυσῆς αὐτοὺς ἕκαστα περὶ τῶν μέτρων κατὰ τὴν ὑποθήκην τοῦ θεοῦ καὶ τοῦ μεγέθους ὅσα τε δεῖ σκεύη χωρεῖν αὐτὴν ἀνεδίδασκε πρὸς τὰς θυσίας ὑπηρετήσοντα. ἐφιλοτιμοῦντο δὲ καὶ γυναῖκες περί τε στολὰς ἱερατικὰς καὶ περὶ τὰ ἄλλα ὅσων ἔχρῃζε τὸ ἔργον κόσμου τε καὶ λειτουργίας ἕνεκα τοῦ θεοῦ."},{"number":108,"text":"Πάντων δʼ ἐν ἑτοίμῳ γεγενημένων χρυσίου τε καὶ χαλκοῦ καὶ τῶν ὑφαντῶν, προειπὼν ἑορτὴν Μωυσῆς καὶ θυσίας κατὰ τὴν ἑκάστου δύναμιν ἵστη τὴν σκηνήν, πρῶτον μὲν αἴθριον διαμετρησάμενος τὸ μὲν εὖρος πεντήκοντα πηχῶν ἑκατὸν δὲ τὸ μῆκος."},{"number":109,"text":"κάμακας δὲ ἔστησε χαλκέας πενταπήχεις τὸ ὕψος καθʼ ἑκατέραν πλευρὰν εἴκοσι τῶν ἐπιμηκεστέρων, δέκα δὲ τῶν ἐν πλάτει κειμένων τῆς κατόπιν, κρίκοι δὲ τῶν καμάκων ἑκάστῃ προσῆσαν· κιονόκρανα μὲν ἀργύρεα, βάσεις δὲ χρυσαῖ σαυρωτῆρσιν ἐμφερεῖς, χαλκαῖ δὲ ἦσαν, ἐπὶ τῆς γῆς ἐρηρεισμέναι."},{"number":110,"text":"ἐξήπτετο δὲ τῶν κρίκων καλώδια τὴν ἀρχὴν ἥλων χαλκέων πηχυαίων τὸ μέγεθος ἐκδεδεμένα, οἳ καθʼ ἑκάστην κάμακα παρέντες κατὰ τοῦ ἐδάφους ἀκίνητον ὑπὸ βίας ἀνέμων τὴν σκηνὴν ἔμελλον παρέξειν. σινδὼν δʼ ἐκ βύσσου ποικιλωτάτη διὰ πασῶν ἐπῄει ἀπὸ τοῦ κιονοκράνου κατιοῦσα μέχρι τῆς βάσεως πολλὴ κεχυμένη, περιφράττουσα ἅπαν κύκλῳ τὸ χωρίον, ὡς μηδὲν δοκεῖν τείχους διαφέρειν."},{"number":111,"text":"καὶ οὕτως μὲν εἶχον αἱ τρεῖς πλευραὶ τοῦ περιβόλου· τῆς δὲ τετάρτης πλευρᾶς, πεντήκοντα γὰρ οὖσα πήχεων ἡ ἑτέρα μέτωπον τοῦ παντὸς ἦν, εἴκοσι μὲν πήχεις ἀνεῴγεσαν κατὰ πύλας, ἐν αἷς ἀνὰ δύο κάμακες εἱστήκεσαν κατὰ μίμησιν πυλώνων."},{"number":112,"text":"ὅλαις δʼ αὐταῖς ἄργυρος ἦν ἐπικεχαλκωμένος πάρεξ τῶν βάσεων· χαλκαῖ γὰρ ἦσαν. ἑκατέρωθεν δὲ τοῦ πυλῶνος τρεῖς κάμακες ἦσαν ἑστῶσαι, αἳ τοῖς πυλούχοις ἐμβεβήκεσαν ἐρηρεισμέναι, καὶ κατʼ αὐτῶν δὲ βύσσινον ὕφος σινδόνος ἦν περιηγμένον."},{"number":113,"text":"τὸ δὲ κατὰ τὰς πύλας μήκους μὲν ὄντος πήχεων εἴκοσι πέντε δὲ βάθους ὕφος ἦν πορφύρας φοίνικος σὺν ὑακίνθῳ καὶ βύσσῳ πεποιημένον πολλῶν αὐτῷ συνανθούντων καὶ ποικίλων, ὁπόσα μὴ ζῴων ἐξετυποῦτο μορφάς."},{"number":114,"text":"ἐντὸς δὲ τῶν πυλῶν περιρραντήριον ἦν χάλκεον ὁμοίαν αὐτῷ καὶ τὴν κρηπῖδα παρεχόμενον, ἐξ οὗ τοῖς ἱερεῦσι τὰς χεῖρας ἀποπλύνειν καὶ τῶν ποδῶν καταχεῖν παρῆν. καὶ ὁ μὲν τοῦ αἰθρίου περίβολος τοῦτον τὸν τρόπον ἦν διακεκοσμημένος."},{"number":115,"text":"Τὴν δὲ σκηνὴν ἵστησιν αὐτοῦ κατὰ μέσον τετραμμένην πρὸς τὰς ἀνατολάς, ἵνα πρῶτον ὁ ἥλιος ἐπʼ αὐτὴν ἀνιὼν ἀφίῃ τὰς ἀκτῖνας. καὶ τὸ μὲν μῆκος αὐτῆς ἐπὶ πήχεις ἐγήγερτο τριάκοντα τὸ δὲ εὖρος ἐπὶ δέκα διειστήκει, καὶ ὁ μὲν ἕτερος τῶν τοίχων νότιος ἦν, ὁ δὲ ἕτερος κατὰ βορέαν ἐτέτραπτο, κατόπιν δʼ αὐτῆς ἡ δύσις κατελείπετο."},{"number":116,"text":"ἀνίστασθαι δʼ αὐτὴν ἐχρῆν ἐφʼ ὅσον προβαίνοι τὸ εὖρος. κίονες δʼ ἦσαν ξύλου πεποιημένοι κατὰ πλευρὰν ἑκατέραν εἴκοσι τετράγωνοι μὲν τὸ σχῆμα εἰργασμένοι, εἰς δὲ πλάτος διεστῶτες πήχεώς τε καὶ ἡμίσους, τὸ δὲ βάθος δακτύλων τεσσάρων."},{"number":117,"text":"λεπίδες δʼ αὐτοῖς ἦσαν ἐπικεχαλκευμέναι πανταχόθεν χρυσαῖ διά τε τῶν ἔνδοθεν καὶ τῶν ἐκτὸς μερῶν. δύο δʼ αὐτῶν ἑκάστῳ προσῆσαν στρόφιγγες ἐλαυνόμενοι κατὰ δύο βάσεων· αὗται δʼ ἀργυραῖ μὲν ἦσαν, πυλὶς δʼ ἑκατέρᾳ τούτων προσῆν δεχομένη τὴν στρόφιγγα."},{"number":118,"text":"τοῦ δὲ κατὰ δύσιν τοίχου κίονες μὲν ἓξ ἦσαν, συνῄεσαν δʼ ἀλλήλοις ἀκριβῶς ἅπαντες, ὥστε μεμυκότων τῶν ἁρμῶν ὡς ἕνα δοκεῖν εἶναι τοῖχον αὐτῶν τὴν συνέλευσιν χρύσειον τά τε ἔνδοθεν καὶ τὰ ἐκτός·"},{"number":119,"text":"ἀνηλόγει γὰρ ὁ τῶν κιόνων ἀριθμός· εἴκοσι γὰρ ἦσαν καὶ παρεῖχε πλάτος τρίτον σπιθαμῆς ἕκαστος αὐτῶν, ὥστε συμπληροῦσθαι τοὺς τριάκοντα πήχεις ὑπʼ αὐτῶν· κατὰ δὲ τὸν ὄπισθεν τοῖχον, ἐννέα γὰρ πήχεις οἱ ἓξ κίονες παρέχονται συνελθόντες, δύʼ ἑτέρους ποιοῦνται κίονας ἐκ πήχεως τετμημένους, οὓς ἐγγωνίους ἔθεσαν ἐπʼ ἴσης τοῖς μείζοσιν ἠσκημένους."},{"number":120,"text":"ἕκαστος δὲ τῶν κιόνων κρίκον εἶχε χρύσεον κατὰ τὸ ἔξω μέτωπον προσφυὴς ὥσπερ ῥίζαις τισὶν ἐμπεπλεγμένος κατὰ στίχον πρὸς ἀλλήλους τετραμμένοι τὴν περιφέρειαν, καὶ διʼ αὐτῶν ἐπίχρυσοι σκυταλίδες ἐλαυνόμεναι πέντε πήχεων ἑκάστη τὸ μέγεθος σύνδεσμος ἦσαν τῶν κιόνων, ἐμβαινούσης κατὰ κεφαλὴν σκυταλίδος ἑκάστης τῇ ἑτέρᾳ τεχνητῷ στρόφιγγι κοχλίου τρόπον δεδημιουργημένῳ."},{"number":121,"text":"κατὰ δὲ τὸν ὄπισθεν τοῖχον μία φάλαγξ ἦν διὰ πάντων ἰοῦσα τῶν κιόνων, εἰς ἣν ἐνέβαινον πλάγιαι αἱ τελευταῖαι τῶν σκυταλίδων ἐξ ἑκατέρου τοίχου τῶν ἐπιμηκεστέρων καὶ κρατεῖσθαι συνέβαινεν αὐταῖς γιγλύμοις τῷ θήλει τοῦ ἄρρενος συνελθόντος. τοῦτο μέντοι πρὸς τὸ μήθʼ ὑπὸ ἀνέμων κραδαίνεσθαι μήτʼ ἄλλης αἰτίας τὴν σκηνὴν συνεῖχεν, ἀλλʼ ἀκίνητον αὐτὴν ἐν ἠρεμίᾳ πολλῇ διαφυλάξειν ἔμελλεν."},{"number":122,"text":"Ἐντὸς δὲ διελὼν τὸ μῆκος αὐτῆς εἰς τρία μέρη μετὰ δέκα πήχεας ἡρμοσμένους ἐκ τοῦ μυχοῦ τέσσαρας ἵστησι κίονας ὁμοίως τοῖς ἄλλοις εἰργασμένους καὶ βάσεσιν ὁμοίαις ἐπικειμένους διαλείποντας ἀλλήλων κατʼ ὀλίγον. τὸ δʼ ἐνδοτέρω αὐτῶν ἄδυτον ἦν, τὸ δὲ λοιπὸν ἡ σκηνὴ τοῖς ἱερεῦσιν ἀνεῖτο."},{"number":123,"text":"τὴν μέντοι διαμέτρησιν τὴν τοιαύτην τῆς σκηνῆς καὶ μίμησιν τῆς τῶν ὅλων φύσεως συνέβαινεν εἶναι· τὸ μὲν γὰρ τρίτον αὐτῆς μέρος τὸ ἐντὸς τῶν τεσσάρων κιόνων, ὃ τοῖς ἱερεῦσιν ἦν ἄβατον, ὡς οὐρανὸς ἀνεῖτο τῷ θεῷ, οἱ δʼ εἴκοσι πήχεις, ὥσπερ γῆ καὶ θάλασσα βάσιμος ἀνθρώποις, οὕτως τοῖς ἱερεῦσι μόνοις ἐπετέτραπτο."},{"number":124,"text":"κατὰ μέτωπον δέ, ἐξ οὗ τὴν εἴσοδον ἦσαν πεποιημένοι, κίονες ἕστασαν χρύσεοι χαλκείαις βάσεσιν ἐφεστῶτες τὸν ἀριθμὸν πέντε. κατεπετάννυσαν δὲ τὴν σκηνὴν ὕφεσι βύσσου καὶ πορφύρας ὑακίνθου καὶ φοίνικος βαφῆς συγκεκραμένης."},{"number":125,"text":"καὶ πρῶτον μὲν ἦν πήχεων δέκα πανταχόθεν, ᾧ κατεπετάννυσαν τοὺς κίονας, οἳ διαιροῦντες τὸν νεὼν τὸ ἄδυτον ἔνδον αὑτῶν ἀπελάμβανον· καὶ τοῦτο ἦν τὸ ποιοῦν αὐτὸ μηδενὶ κάτοπτον. καὶ ὁ μὲν πᾶς ναὸς ἅγιον ἐκαλεῖτο, τὸ δʼ ἄβατον τὸ ἐντὸς τῶν τεσσάρων κιόνων τοῦ ἁγίου τὸ ἅγιον."},{"number":126,"text":"ὡραῖον δὲ τὸ φάρσος ἄνθεσι παντοίοις, ὅσα γῆθεν ἀνέρχεται, διαπεποικιλμένον τοῖς τε ἄλλοις ἅπασιν ἐνυφασμένον, ὅσα κόσμον οἴσειν ἔμελλε, πλὴν ζῴων μορφῆς."},{"number":127,"text":"ἕτερον δὲ τούτῳ καὶ τῷ μεγέθει καὶ τῇ ὑφῇ καὶ τῇ χρόᾳ παραπλήσιον τοὺς ἐπὶ ταῖς εἰσόδοις πέντε κίονας περιέβαλλε κατὰ γωνίαν ἑκάστου κίονος κρίκου κατέχοντος αὐτὸ ἀπὸ κορυφῆς ἄχρι ἡμίσους τοῦ κίονος. τὸ δὲ λοιπὸν εἴσοδος ἀνεῖτο τοῖς ἱερεῦσιν ὑποδυομένοις."},{"number":128,"text":"ὑπὲρ δὲ τούτου λίνεον ἦν ἰσομέγεθες φάρσος ἐφελκόμενον ἀπὸ κάλων ἐπὶ θάτερα, τῶν κρίκων τῷ τε ὕφει καὶ τῷ κάλῳ διακονούντων πρός τε τὸ ἐκπετάννυσθαι καὶ συνελκόμενον ἵστασθαι κατὰ γωνίαν ἐμποδὼν οὐκ ἐσόμενον πρὸς τὸ κατοπτεύεσθαι καὶ μάλιστα ἐν ταῖς ἐπισήμοις ἡμέραις."},{"number":129,"text":"κατὰ δὲ τὰς λοιπὰς καὶ μάλισθʼ ὅταν ᾖ νιφετώδης προπεταννύμενον στεγανὸν ἐποίει τὸ ἐκ τῶν βαμμάτων ὕφος· ὅθεν δὴ παρέμεινε τὸ ἔθος καὶ τὸν ναὸν οἰκοδομησαμένων ἡμῶν, ὥστε τὴν σινδόνα τοιουτότροπον περικεῖσθαι ταῖς εἰσόδοις."},{"number":130,"text":"δέκα δὲ ἄλλα φάρση πηχῶν τὸ πλάτος τεσσάρων τὸ δὲ μῆκος ὀκτὼ καὶ εἴκοσι, χρυσείους ἔχοντα γιγλύμους ἐπὶ συναφῇ θηλείας τε καὶ ἄρρενος συνείλεκτο, ὡς ἓν εἶναι δοκεῖν, εἶτα ὑπερτεινόμενα τοῦ ναοῦ τό τʼ ἐφύπερθεν ἐσκίαζε καὶ τῶν τοίχων τοὺς κατὰ πλευρὰν καὶ κατόπιν ἑστῶτας ἀπὸ τῆς γῆς ὅσον πῆχυν ἀνέχοντα."},{"number":131,"text":"ἴσαι δὲ τῷ πλάτει καὶ ἄλλαι σινδόνες μιᾷ πλείους τὸν ἀριθμὸν τὸ δὲ μῆκος ὑπερβάλλουσαι, τριακονταπήχεις γὰρ ἦσαν, ὑφασμέναι δʼ ἐκ τριχῶν ὁμοίως κατὰ λεπτουργίαν ταῖς ἐκ τῶν ἐρίων πεποιημέναι ἐτέταντο μέχρι τῆς γῆς κεχυμέναι κατὰ θύρας ἀετώματι παραπλήσιον καὶ παστάδι παρεῖχον, τοῦ ἑνδεκάτου φάρσους εἰς τοῦτο παρειλημμένου."},{"number":132,"text":"ἄλλαι δʼ ἐπάνω τούτων ἐκ διφθερῶν κατεσκευασμέναι ὑπερῄεσαν σκέπη καὶ βοήθεια ταῖς ὑφανταῖς ἔν τε τοῖς καύμασι καὶ ὁπότε ὑετὸς εἴη γεγενημέναι. πολλὴ δʼ ἔκπληξις ἐλάμβανε τοὺς πόρρωθεν θεωμένους· τὴν γὰρ χρόαν τοῖς κατὰ τὸν οὐρανὸν συμβαίνουσιν οὐδὲν ἐδόκουν διαφέρειν."},{"number":133,"text":"αἱ δʼ ἐκ τῆς τριχὸς καὶ τῶν διφθερῶν πεποιημέναι κατῄεσαν ὁμοίως τῷ περὶ τὰς πύλας ὑφάσματι τό τε καῦμα καὶ τὴν ἀπὸ τῶν ὄμβρων ὕβριν ἀπομαχόμεναι. καὶ ἡ μὲν σκηνὴ τοῦτον πήγνυται τὸν τρόπον."},{"number":134,"text":"Γίνεται δὲ καὶ κιβωτὸς τῷ θεῷ ξύλων ἰσχυρῶν τὴν φύσιν καὶ σῆψιν παθεῖν οὐ δυναμένων· ἡ δʼ ἐρὼν μὲν καλεῖται κατὰ τὴν ἡμετέραν γλῶτταν, ἡ δὲ κατασκευὴ τοιαύτη τις ἦν·"},{"number":135,"text":"μῆκος μὲν ἦν αὐτῇ πέντε σπιθαμῶν, τὸ δʼ εὖρος καὶ τὸ βάθος τριῶν σπιθαμῶν εἰς ἑκάτερον· χρυσῷ δὲ τά τʼ ἐντὸς καὶ τὰ ἔξωθεν περιελήλατο πᾶσα, ὡς ἀποκεκρύφθαι τὴν ξύλωσιν, στρόφιγξί τε χρυσοῖς τὸ ἐπίθεμα προσηνωμένον εἶχε θαυμαστῶς, ὃ πανταχόθεν ἴσον ἦν κατʼ οὐδέτερον μέρος ἐξοχαῖς τὴν εὐαρμοστίαν λυμαινόμενον."},{"number":136,"text":"καὶ καθʼ ἑκάτερον δὲ τοῖχον τῶν ἐπιμηκεστέρων κρίκοι προσῆσαν χρυσοῖ δύο τοῦ παντὸς διήκοντες ξύλου, καὶ διʼ αὐτῶν ἔνετοι σκυταλίδες ἐπίχρυσοι καθʼ ἑκάτερον τοῖχον, ὡς ἂν ὑπʼ αὐτῶν ὁπότε δεήσειεν ἄγοιτο κινουμένη· οὐ γὰρ ἐπὶ ζεύγους ἐκομίζετο, ἀλλʼ ὑπὸ τῶν ἱερέων ἐφέρετο."},{"number":137,"text":"τῷ δὲ ἐπιθέματι αὐτῆς ἦσαν πρόστυποι δύο, Χερουβεῖς μὲν αὐτοὺς Ἑβραῖοι καλοῦσι, ζῷα δέ ἐστι πετεινὰ μορφὴν δʼ οὐδενὶ τῶν ὑπʼ ἀνθρώπων ἑωραμένων παραπλήσια, Μωυσῆς δέ φησι τῷ θρόνῳ τοῦ θεοῦ προστυπεῖς ἑωρακέναι."},{"number":138,"text":"ταύτῃ τὰς δύο πλάκας, ἐν αἷς τοὺς δέκα λόγους συγγεγράφθαι συμβεβήκει ἀνὰ πέντε μὲν εἰς ἑκατέραν ἀνὰ δύο δὲ καὶ ἥμισυ κατὰ μέτωπον, ἐγκατέθετο. καὶ ταύτην ἐν τῷ ἀδύτῳ κατατίθησιν."},{"number":139,"text":"Ἐν δὲ τῷ ναῷ τράπεζαν ἱδρύεται Δελφικαῖς παραπλησίαν τὸ μῆκος μὲν δύο πηχῶν, τὸ δὲ πλάτος ἑνὸς πήχεως καὶ σπιθαμῶν τριῶν τὸ ὕψος. ἦσαν δʼ αὐτῇ πόδες τὰ μὲν ἐξ ἡμίσους ἕως τῶν κάτω τελέως ἐξηρτισμένοι οἷς Δωριεῖς προστιθέασι ταῖς κλίναις ἐμφερεῖς, τὸ δὲ πρὸς αὐτὴν ἀνατεῖνον τετράγωνοι τῇ ἐργασίᾳ."},{"number":140,"text":"κοιλαίνεται δὲ καθʼ ἕκαστον πλευρὸν κοιλαίνουσά πως κατὰ παλαιστὴν τὸ ἔδαφος ἕλικος περιθεούσης τό τε ἄνω καὶ τὸ κάτω μέρος τοῦ σώματος, καθʼ ἕκαστον δὲ τῶν ποδῶν καὶ ταύτῃ ἐλήλατο κρίκος οὐκ ἄπωθεν τοῦ ἐπιθέματος, διʼ ὧν ᾔεσαν στελεοὶ χρύσεοι ξύλου τἄνερθεν ὄντες, οὐκ ἐξαίρετοι·"},{"number":141,"text":"κοῖλον γὰρ εἶχεν ἐπʼ αὐτοῖς τὸ κατὰ τοὺς κρίκους κοινωθέντας· οὐδὲ γάρ εἰσι διηνεκεῖς, ἀλλὰ πρὶν συνελθεῖν εἰς τὸ ἄπειρον εἰς περονίδας τὴν ἀρχὴν τελευτῶντες, ὧν ἡ μὲν εἰς τὸ προανέχον ἐμβαίνει τῆς τραπέζης, ἡ δὲ εἰς τὸν πόδα· καὶ τούτοις κατὰ τὰς ὁδοὺς ἐκομίζετο."},{"number":142,"text":"ἐπὶ ταύτης, ἐτίθετο γὰρ ἐν τῷ ναῷ τετραμμένη πρὸς ἄρκτον οὐ πόρρω τοῦ μυχοῦ, διετίθεσαν ἄρτους τε δώδεκα ἀζύμους κατὰ ἓξ ἐπαλλήλους καθαροῦ πάνυ τοῦ ἀλεύρου ἐκ δύο ἀσσάρων, ὃ μέτρον Ἑβραίων ἑπτὰ κοτύλας Ἀττικὰς ἔχει."},{"number":143,"text":"ὑπὲρ δὲ τῶν ἄρτων ἐτίθεντο φιάλαι δύο χρύσεαι λιβάνου πλήρεις, μετὰ δὲ ἡμέρας ἑπτὰ πάλιν ἄλλοι ἐκομίζοντο ἄρτοι ἐν τῷ καλουμένῳ ὑφʼ ἡμῶν Σαββάτῳ· τὴν γὰρ ἑβδόμην ἡμέραν Σάββατα καλοῦμεν· τὴν δʼ αἰτίαν ἐξ ἧς ταῦτα ἐπενοήθησαν ἐν ἑτέροις ἐροῦμεν."},{"number":144,"text":"Κατὰ πρόσωπον δὲ τῆς τραπέζης τῷ πρὸς μεσημβρίαν τετραμμένῳ τοίχῳ πλησίον ἵσταται λυχνία ἐκ χρυσοῦ κεχωνευμένη διάκενος σταθμὸν ἔχουσα μνᾶς ἑκατόν· Ἑβραῖοι μὲν καλοῦσι κίγχαρες, εἰς δὲ τὴν Ἑλληνικὴν μεταβαλλόμενον γλῶτταν σημαίνει τάλαντον."},{"number":145,"text":"πεποίηται δὲ σφαιρία καὶ κρίνα σὺν ῥοΐσκοις καὶ κρατηριδίοις, ἑβδομήκοντα δʼ ἦν τὰ πάντα, ἐξ ὧν ἀπὸ μιᾶς βάσεως συνετέθη πρὸς ὕψος, ποιήσαντος αὐτὴν συγκειμένην εἰς μοίρας εἰς ὅσας τοὺς πλανήτας καὶ τὸν ἥλιον κατανέμουσιν."},{"number":146,"text":"ἀπαρτίζεται δὲ εἰς ἑπτὰ κεφαλὰς καταλλήλας ἐν στίχῳ διακειμένας. λύχνοι δʼ ἐπιφέρονται αὐταῖς ἑπτὰ κατὰ μίαν τῶν πλανητῶν τὸν ἀριθμὸν μεμιμημένοι, ὁρῶσι δὲ εἴς τε τὴν ἀνατολὴν καὶ τὴν μεσημβρίαν λοξῶς αὐτῆς κειμένης."},{"number":147,"text":"Μεταξὺ δὲ αὐτῆς καὶ τῆς τραπέζης ἔνδον, ὡς προεῖπον, θυμιατήριον ξύλινον μέν, ἐξ οὗ καὶ τὰ πρότερα ἦν σκεύη μὴ σηπόμενα, στερεὰ δὲ περιελήλατʼ αὐτῷ λεπίς, πηχυαῖον μὲν κατὰ πλευρὰν ἑκάστην τὸ πλάτος ὕψος δὲ διπλάσιον."},{"number":148,"text":"ἐπῆν τε ἐσχάρα χρυσεία ὑπερανεστῶσα ἔχουσα κατὰ γωνίαν ἑκάστην στέφανον καὶ τοῦτον δʼ ἐκπεριοδεύοντα χρύσεον, ᾗ καὶ κρίκοι καὶ σκυταλίδες προσῆσαν, αἷς κατὰ τὰς ὁδοὺς ὑπὸ τῶν ἱερέων ἐφέρετο."},{"number":149,"text":"ἵδρυτο δὲ καὶ πρὸ τῆς σκηνῆς βωμὸς χάλκεος ὑπόξυλος καὶ αὐτὸς ἑκάστην πλευρὰν πέντε πήχεσιν ἐκμεμετρημένος, τὸ δὲ ὕψος τρίπηχυς, ὁμοίως τῷ χρυσῷ κεκοσμημένος, χαλκείαις λεπίσιν ἐξησκημένος, δικτύῳ τὴν ἐσχάραν ἐμφερής· ἐξεδέχετο γὰρ ἡ γῆ τὸ ἀπὸ τῆς ἐσχάρας πῦρ καταφερόμενον τῆς βάσεως διὰ παντὸς οὐχ ὑποκειμένης."},{"number":150,"text":"ἀντικρὺ δʼ ἐτίθεντο τοῦ χρυσέου οἰνοχόαι τε καὶ φιάλαι σὺν θυΐσκαις καὶ κρατῆρσιν ἦσαν ὅσα τε ἄλλα πρὸς τὰς ἱερουργίας πεποίητο χρύσεα πάντα ὑπῆρχε. καὶ ἡ μὲν σκηνὴ τοιαύτη τε ἦν καὶ τὰ περὶ αὐτὴν σκεύη."}],"7":[{"number":151,"text":"Γίνονται δὲ καὶ τοῖς ἱερεῦσι στολαὶ πᾶσί τε τοῖς ἄλλοις, οὓς χαναναίας καλοῦσι, καὶ δὴ καὶ τῷ ἀρχιερεῖ, ὃν ἀραβάχην προσαγορεύουσι· σημαίνει δὲ ἀρχιερέα. τὴν μὲν οὖν τῶν ἄλλων στολὴν τοιαύτην εἶναι συμβέβηκεν."},{"number":152,"text":"ὅταν δὲ προσίῃ ταῖς ἱερουργίαις ὁ ἱερεὺς ἡγνευκὼς ἣν ὁ νόμος ἁγνείαν προαγορεύει, πρῶτον μὲν περιτίθεται τὸν μαναχάσην λεγόμενον· βούλεται δὲ τοῦτο συνακτῆρα μὲν δηλοῦν, διάζωμα δʼ ἐστὶ περὶ τὰ αἰδοῖα ῥαπτὸν ἐκ βύσσου κλωστῆς εἰργασμένον ἐμβαινόντων εἰς αὐτὸ τῶν ποδῶν ὥσπερ εἰς ἀναξυρίδας, ἀποτέμνεται δὲ ὑπὲρ ἥμισυ καὶ τελευτῆσαν ἄχρι τῆς λαγόνος περὶ αὐτὴν ἀποσφίγγεται."},{"number":153,"text":"Ἐπὶ δὲ τούτῳ λίνεον ἔνδυμα διπλῆς φορεῖ σινδόνος βυσσίνης, χεθομένη μὲν καλεῖται, λίνεον δὲ τοῦτο σημαίνει· χέθον γὰρ τὸ λίνον ἡμεῖς καλοῦμεν. ἔστι δὲ τοῦτο τὸ ἔνδυμα ποδήρης χιτὼν περιγεγραμμένος τῷ σώματι καὶ τὰς χειρῖδας περὶ τοῖς βραχίοσιν κατεσφιγμένος,"},{"number":154,"text":"ὃν ἐπιζώννυνται κατὰ στῆθος ὀλίγον τῆς μασχάλης ὑπεράνω τὴν ζώνην περιάγοντες πλατεῖαν μὲν ὡς εἰς τέσσαρας δακτύλους, διακένως δʼ ὑφασμένην ὥστε λεβηρίδα δοκεῖν ὄφεως· ἄνθη δʼ εἰς αὐτὴν ἐνύφανται φοίνικι καὶ πορφύρᾳ μετὰ ὑακίνθου καὶ βύσσου πεποικιλμένα, στήμων δʼ ἐστὶ μόνη βύσσος."},{"number":155,"text":"καὶ λαβοῦσα τὴν ἀρχὴν τῆς ἑλίξεως κατὰ στέρνον καὶ περιελθοῦσα πάλιν δεῖται, καὶ κέχυται μὲν πολλὴ μέχρι καὶ τῶν σφυρῶν ἕως οὗ μηδὲν ὁ ἱερεὺς ἐνεργεῖ, πρὸς γὰρ εὐπρέπειαν οὕτως ἔχει τοῖς ὁρῶσι καλῶς, ὅταν δὲ σπουδάζειν περὶ τὰς θυσίας δέῃ καὶ διακονεῖν, ὅπως μὴ κινουμένης ἐμποδίζηται πρὸς τὸ ἔργον, ἀναβαλόμενος ἐπὶ τὸν λαιὸν ὦμον φέρει."},{"number":156,"text":"Μωυσῆς μὲν οὖν ἀβαΐθ αὐτὴν ἐκάλεσεν, ἡμεῖς δὲ παρὰ Βαβυλωνίων μεμαθηκότες ἐμίαν αὐτὴν καλοῦμεν· οὕτως γὰρ προσαγορεύεται παρʼ αὐτοῖς. οὗτος ὁ χιτὼν κολποῦται μὲν οὐδαμόθεν, λαγαρὸν δὲ παρέχων τὸν βροχωτῆρα τοῦ αὐχένος ἁρπεδόσιν ἐκ τῆς ὤας καὶ τῶν κατὰ στέρνον καὶ μετάφρενον ἠρτημέναις ἀναδεῖται ὑπὲρ ἑκατέραν κατακλεῖδα· μασσαβάνης καλεῖται."},{"number":157,"text":"Ὑπὲρ δὲ τῆς κεφαλῆς φορεῖ πῖλον ἄκωνον οὐ διικνούμενον εἰς πᾶσαν αὐτὴν ἀλλʼ ἐπʼ ὀλίγον ὑπερβεβηκότα μέσης· καλεῖται μὲν μασναεφθῆς, τῇ δὲ κατασκευῇ τοιοῦτός ἐστιν ὡς στεφάνη δοκεῖν ἐξ ὑφάσματος λινέου ταινία πεποιημένη παχεῖα· καὶ γὰρ ἐπιπτυσσόμενον ῥάπτεται πολλάκις."},{"number":158,"text":"ἔπειτα σινδὼν ἄνωθεν αὐτὸν ἐκπεριέρχεται διήκουσα μέχρι μετώπου τήν τε ῥαφὴν τῆς ταινίας καὶ τὸ ἀπʼ αὐτῆς ἀπρεπὲς καλύπτουσα καὶ ὅλη δὲ τῷ κρανίῳ γιγνομένη ἐπίπεδον· ἥρμοσται δὲ ἀκριβῶς, ὡς ἂν μὴ περιρρυείη πονοῦντος περὶ τὴν ἱερουργίαν. καὶ ὁποία μέν ἐστιν ἡ τῶν πολλῶν ἱερέων στολὴ δεδηλώκαμεν."},{"number":159,"text":"Ὁ δὲ ἀρχιερεὺς κοσμεῖται μὲν καὶ ταύτῃ παραλιπὼν οὐδὲν τῶν προειρημένων, ἐπενδυσάμενος δʼ ἐξ ὑακίνθου πεποιημένον χιτῶνα, ποδήρης δʼ ἐστὶ καὶ οὗτος, μεεὶρ καλεῖται κατὰ τὴν ἡμετέραν γλῶσσαν, ζώνῃ περισφίγγεται βάμμασιν οἷς ἡ πρότερον ἤνθει διαπεποικιλμένῃ χρυσοῦ συνυφασμένου·"},{"number":160,"text":"κατὰ πέζαν δʼ αὐτῷ προσερραμμένοι θύσανοι ῥοῶν τρόπον ἐκ βαφῆς μεμιμημένοι ἀπήρτηντο καὶ κώδωνες χρύσεοι κατὰ πολλὴν ἐπιτήδευσιν τῆς εὐπρεπείας, ὥστε μέσον ἀπολαμβάνεσθαι δυοῖν τε κωδώνοιν ῥοΐσκον, καὶ ῥοῶν κωδώνιον."},{"number":161,"text":"ἔστι δʼ ὁ χιτὼν οὗτος οὐκ ἐκ δυοῖν περιτμημάτων, ὥστε ῥαπτὸς ἐπὶ τῶν ὤμων εἶναι καὶ τῶν παρὰ πλευράν, φάρσος δʼ ἓν ἐπίμηκες ὑφασμένον σχιστὸν ἔχει βροχωτῆρα πλάγιον, ἀλλὰ κατὰ μῆκος ἐρρωγότα πρός τε τὸ στέρνον καὶ μέσον τὸ μετάφρενον· πέζα δʼ αὐτῷ προσέρραπται ὑπὲρ τοῦ μὴ διελέγχεσθαι τῆς τομῆς τὴν δυσπρέπειαν· ὁμοίως δὲ καὶ ὅθεν αἱ χεῖρες διείργονται σχιστός ἐστιν."},{"number":162,"text":"Ἐπὶ δὲ τούτοις τρίτον ἐνδύεται τὸν λεγόμενον μὲν ἐφώδην, Ἑλληνικῇ δʼ ἐπωμίδι προσεοικότα· γίνεται γὰρ τοῦτον τὸν τρόπον. ὑφανθεὶς ἐπὶ βάθος πηχυαῖον ἔκ τε χρωμάτων παντοίων καὶ χρυσοῦ συμπεποικιλμένος ἀπερίπτυκτον τοῦ στέρνου τὸ μέσον καταλιμπάνει χειρῖσι τε ἠσκημένος καὶ τῷ παντὶ σχήματι χιτὼν εἶναι πεποιημένος."},{"number":163,"text":"τῷ δὲ διακένῳ τοῦ ἐνδύματος σύνεισι περίτμημα σπιθαμῆς τὸ μέγεθος χρυσῷ τε καὶ τοῖς αὐτοῖς τῷ ἐφώδῃ βάμμασι διηνθισμένον· ἐσσὴν μὲν καλεῖται, σημαίνει δὲ τοῦτο κατὰ τὴν Ἑλλήνων γλῶτταν λόγιον·"},{"number":164,"text":"πληροῖ δὲ ἀκριβῶς τοῦ ἐφώδου ὅπερ ὑφαίνοντες κατὰ στῆθος ἐξέλιπον, ἑνοῦται δʼ ὑπὸ κρίκων χρυσέων αὐτῷ τε κατὰ γωνίαν ἑκάστην κἀκείνῳ τῶν ἴσων προσκεκοινωμένων, ῥάμματος ὑακίνθου παραληφθέντος εἰς τὴν πρὸς ἀλλήλους κατάδεσιν τοῖς κρίκοις."},{"number":165,"text":"πρὸς δὲ τὸ μὴ χαλαρὸν εἶναι τὸ ἐν μέσῳ τῶν κρίκων καταλιμπανόμενον ῥαφὴν αὐτοῦ νήμασιν ὑακινθίνοις ἐπενόησαν. πορποῦσι δὲ τὴν ἐπωμίδα σαρδόνυχες δύο κατὰ τῶν ὤμων ἑκάτερον τέλος ἐπʼ αὐτοὺς ἐπιθέον χρύσεον ἔχοντες πρὸς τὸ ταῖς περονίσιν ἐπιτήδειον εἶναι."},{"number":166,"text":"ἐγγέγραπται δὲ τούτοις τῶν Ἰακώβου παίδων τὰ ὀνόματα γράμμασιν ἐπιχωρίοις γλώσσῃ τῇ ἡμετέρᾳ κατὰ ἓξ τῶν λίθων ἑκατέρῳ, οἱ πρεσβύτεροι δʼ εἰσὶ κατὰ ὦμον τὸν δεξιόν. ἐπίασι δὲ καὶ τὸν ἐσσήνην λίθοι δώδεκα μεγέθει καὶ κάλλει διαφέροντες οὐ κτητὸς ἀνθρώποις κόσμος διὰ τιμῆς ὑπερβολὴν ὄντες·"},{"number":167,"text":"οὗτοι μέντοι κατὰ στίχον τρεῖς ἐπὶ τεσσάρων διακείμενοι γραμμῶν ἐνήσκηνται τῷ ὕφει, χρυσὸς δʼ αὐτοὺς ἐκπεριέρχεται τὰς ἕλικας ἐντιθεὶς τῷ ὕφει πρὸς τὸ μὴ διαρρεῖν οὕτως πεποιημένος."},{"number":168,"text":"καὶ ἡ μὲν πρώτη τριάς ἐστι σαρδόνυξ τόπαζος σμάραγδος, ἡ δευτέρα δὲ ἄνθρακα παρέχεται καὶ ἴασπιν καὶ σάπφειρον, τῆς δὲ τρίτης λίγυρος μὲν ἄρχει εἶτα ἀμέθυσος ἀχάτης δὲ τρίτος ἔνατος ὢν τοῖς πᾶσι, τετάρτου δὲ στίχου χρυσόλιθος μὲν πρόκειται, μετὰ δὲ αὐτὸν ὄνυξ, εἶτα βήρυλλος, τελευταῖος οὗτος."},{"number":169,"text":"γράμματα δὲ ἐπετέτμητο πᾶσι τῶν Ἰακώβου υἱῶν, οὓς καὶ φυλάρχους νομίζομεν, ἑκάστου τῶν λίθων ὀνόματι τετιμημένου κατὰ τάξιν ἣν ἕκαστον αὐτῶν γενέσθαι συμβέβηκε."},{"number":170,"text":"τῶν οὖν κρίκων ἀσθενῶν ὄντων κατʼ αὐτοὺς ἐνεγκεῖν τὸ βάρος τῶν λίθων ἑτέρους δύο κρίκους μείζονας τῇ πέζῃ τοῦ ἐσσήνου ᾗπερ ἀνήκει πρὸς τὸν τράχηλον ἐμβεβηκότας τῷ ὑφάσματι ποιοῦσι, δεξομένους ἁλύσεις εἰργασμένας, αἳ συνῆσαν κατʼ ἄκρον τῶν ὤμων σειραῖς ἐκ χρυσοῦ πεπλεγμέναις συνάπτουσαι, ὧν τὸ ἄκρον ἀνεστραμμένον ἐνέβαινε κρίκῳ προέχοντι τῆς νωτιαίας πέζης τοῦ ἐφώδου."},{"number":171,"text":"καὶ τοῦτο ἦν ἀσφάλεια τῷ ἐσσήνῃ πρὸς τὸ μὴ περιρρεῖν, ζώνη δὲ τῷ ἐσσήνῃ προσέρραπτο βάμμασιν οἷς προεῖπον μετὰ χρυσίου προσφερής, ἣ περιοδεύσασα δεῖται πάλιν ἐπὶ τῇ ῥαφῇ καὶ κατακρεμνᾶται· τοὺς δὲ θυσάνους χρύσεαι σύριγγες καθʼ ἑκατέραν ἄκραν ἐκλαβοῦσαι πάντας ἐμπεριέχουσιν αὗται."},{"number":172,"text":"Πῖλον δὲ ἦν ὁ καὶ πρότερον αὐτῷ παραπλησίως εἰργασμένος τοῖς πᾶσιν ἱερεῦσιν, ὑπʼ αὐτὸν δὲ συνερραμμένος ἕτερος ἐξ ὑακίνθου πεποικιλμένος περιέρχεται στέφανος χρύσεος ἐπὶ τριστιχίαν κεχαλκευμένος. θάλλει δʼ ἐπʼ αὐτῷ κάλυξ χρύσεος τῇ σακχάρῳ βοτάνῃ παρʼ ἡμῖν λεγομένῃ ἀπομεμιμημένος, ὑὸς δὲ κύαμον Ἑλλήνων οἱ περὶ τομὰς ῥιζῶν ἐμπείρως ἔχοντες προσαγορεύουσιν."},{"number":173,"text":"εἰ δέ τις ἢ θεασάμενος τὴν βοτάνην ἀμαθίᾳ τούτου ἀγνοεῖ τὴν φύσιν αὐτῆς ἢ τὴν κλῆσιν ἐπιστάμενος οὐκ ἰδὼν δʼ ἀναγνωρίσειε, τοῖς οὕτω δὴ ἔχουσι σημανῶ τὸν τρόπον·"},{"number":174,"text":"βοτάνη μέν ἐστιν ὑπὲρ τρεῖς σπιθαμὰς πολλάκις αὐξανομένη τὸ ὕψος, τὴν δὲ ῥίζαν ἐμφερὴς βουνιάδι, ταύτῃ γὰρ οὐκ ἂν ἁμάρτοι τις εἰκάζων αὐτήν, τὰ δὲ φύλλα τοῖς εὐζώμων· ἐκ μέντοι τῶν κλάδων ἀνίησι κάλυκα προσεχῆ τῷ κλωνί, περίεισι δʼ αὐτὴν ἔλυτρον, ὅπερ ἀποκρίνεται κατʼ αὐτὸ πρὸς τὸν καρπὸν μεταβαλεῖν ἠργμένης· ὁ δὲ κάλυξ μεγέθους ἐστὶ σκυταλίδος τοῦ μικροῦ δακτύλου, κρατῆρι δʼ ἐμφερὴς τὴν περιγραφήν. σημανῶ δὲ καὶ τοῦτο τοῖς οὐ μεμαθηκόσι·"},{"number":175,"text":"σφαιρίδος εἰς δύο τετμημένης περὶ τῷ πυθμένι τὴν ἑτέραν τομὴν ἔχει φυόμενος ἀπὸ ῥίζης περιφερής· εἶτα συνιὼν κατʼ ὀλίγον ὑποκοιλαινούσης εὐπρεπῶς τῆς ὑποχωρήσεως ἀνευρύνεται πάλιν ἠρέμα κατὰ χεῖλος, ὁμοίως ὀμφαλῷ ῥοιᾶς τετμημένος."},{"number":176,"text":"ἐπίθεμα δʼ αὐτῷ ἡμισφαίριον προσπέφυκεν ἀκριβῶς ἂν εἴποι τις τετορνευμένον, ὑπερανεστώσας ἔχον τὰς ἐντομάς, ἃς εἶπον τῇ ῥοᾷ παραπλησίως βλαστάνειν, ἀκανθώδεις καὶ εἰς ὀξὺ παντελῶς ἀποληγούσας τὸ ἄκρον."},{"number":177,"text":"φυλάττει δʼ ἐπὶ τῷ ἐπιθέματι τὸν καρπὸν διὰ παντὸς τοῦ κάλυκος ὄντα βοτάνης σπέρματι τῆς σιδηρίτιδος ὅμοιον, ἀφίησι δʼ ἄνθος τῷ τῆς μήκωνος πλαταγωνίῳ δυνάμενον δοκεῖν ἐμφερὲς εἶναι."},{"number":178,"text":"ἐκ τούτου μὲν στέφανος ἐκκεχάλκευται ὅσον ἀπὸ τοῦ ἰνίου πρὸς ἑκάτερον τῶν κροτάφων. τὸ δὲ μέτωπον ἡ μὲν ἐφιελὶς οὐκ ἔπεισι, λεγέσθω γὰρ οὕτως ὁ κάλυξ, τελαμὼν δʼ ἐστὶ χρύσεος, ὃς ἱεροῖς γράμμασι τοῦ θεοῦ τὴν προσηγορίαν ἐπιτετμημένος ἐστί. καὶ τοιοῦτος μὲν ὁ τοῦ ἀρχιερέως κόσμος ἐστί."},{"number":179,"text":"Θαυμάσειε δʼ ἄν τις τῶν ἀνθρώπων τὴν πρὸς ἡμᾶς ἀπέχθειαν, ἣν ὡς ἐκφαυλιζόντων ἡμῶν τὸ θεῖον ὅπερ αὐτοὶ σέβειν προῄρηνται διατετελέκασιν ἐσχηκότες·"},{"number":180,"text":"εἰ γάρ τις τῆς σκηνῆς κατανοήσειε τὴν πῆξιν καὶ τοῦ ἱερέως ἴδοι τὴν στολὴν τά τε σκεύη, οἷς περὶ τὴν ἱερουργίαν χρώμεθα, τόν τε νομοθέτην εὑρήσει θεῖον ἄνδρα καὶ ματαίως ἡμᾶς ὑπὸ τῶν ἄλλων τὰς βλασφημίας ἀκούοντας· ἕκαστα γὰρ τούτων εἰς ἀπομίμησιν καὶ διατύπωσιν τῶν ὅλων, εἴ τις ἀφθόνως ἐθέλοι καὶ μετὰ συνέσεως σκοπεῖν, εὑρήσει γεγονότα·"},{"number":181,"text":"τήν τε γὰρ σκηνὴν τριάκοντα πηχῶν οὖσαν νείμας εἰς τρία καὶ δύο μέρη πᾶσιν ἀνεὶς τοῖς ἱερεῦσιν ὥσπερ βέβηλόν τινα καὶ κοινὸν τόπον, τὴν γῆν καὶ τὴν θάλασσαν ἀποσημαίνει· καὶ γὰρ ταῦτα πᾶσίν ἐστιν ἐπιβατά. τὴν δὲ τρίτην μοῖραν μόνῳ περιέγραψε τῷ θεῷ διὰ τὸ καὶ τὸν οὐρανὸν ἀνεπίβατον εἶναι ἀνθρώποις."},{"number":182,"text":"ἐπί τε τῇ τραπέζῃ τοὺς δώδεκα τιθεὶς ἄρτους ἀποσημαίνει τὸν ἐνιαυτὸν εἰς τοσούτους μῆνας διῃρημένον. τὴν δὲ λυχνίαν ἐξ ἑβδομήκοντα μορίων ποιήσας συγκειμένην τὰς τῶν πλανητῶν δεκαμοιρίας ᾐνίξατο· καὶ λύχνους ὑπὲρ αὐτῆς ἑπτά, τῶν πλανητῶν τὴν φοράν· τοσοῦτοι γάρ εἰσι τὸν ἀριθμόν."},{"number":183,"text":"τά τε φάρση ἐκ τεσσάρων ὑφανθέντα τὴν τῶν στοιχείων φύσιν δηλοῖ· ἥ τε γὰρ βύσσος τὴν γῆν ἀποσημαίνειν ἔοικε διὰ τὸ ἐξ αὐτῆς ἀνεῖσθαι τὸ λίνον, ἥ τε πορφύρα τὴν θάλασσαν τῷ πεφοινῖχθαι τῶν ἰχθύων τῷ αἵματι, τὸν δὲ ἀέρα βούλεται δηλοῦν ὁ ὑάκινθος, καὶ ὁ φοῖνιξ δʼ ἂν εἴη τεκμήριον τοῦ πυρός."},{"number":184,"text":"ἀποσημαίνει δὲ καὶ ὁ τοῦ ἀρχιερέως χιτὼν τὴν γῆν λίνεος ὤν, ὁ δὲ ὑάκινθος τὸν πόλον, ἀστραπαῖς μὲν κατὰ τοὺς ῥοΐσκους ἀπεικασμένος βρονταῖς δὲ κατὰ τὸν τῶν κωδώνων ψόφον. καὶ τὴν ἐφαπτίδα τοῦ παντὸς τὴν φύσιν ἐκ τεσσάρων δοχθεῖσαν γενέσθαι τῷ θεῷ χρυσῷ συνυφασμένην κατʼ ἐπίνοιαν οἶμαι τῆς προσούσης ἅπασιν αὐγῆς."},{"number":185,"text":"καὶ τὸν ἐσσῆνα μέσον ὄντα τῆς ἐφαπτίδος ἐν τρόπῳ γῆς ἔταξε· καὶ γὰρ αὕτη τὸν μεσαίτατον τόπον ἔχει· ζώνῃ τε περιοδεύσας τὸν ὠκεανὸν ἀποσημαίνει· καὶ γὰρ οὗτος ἐμπεριείληφε τὰ πάντα. δηλοῖ δὲ καὶ τὸν ἥλιον καὶ τὴν σελήνην τῶν σαρδονύχων ἑκάτερος, οἷς ἐνεπόρπωσε τὸν ἀρχιερέα."},{"number":186,"text":"τήν τε δωδεκάδα τῶν λίθων εἴτε τοὺς μῆνάς τις θέλοι νοεῖν, εἴτε τὸν οὕτως ἀριθμὸν τῶν ἀστέρων, ὃν ζωδιακὸν κύκλον Ἕλληνες καλοῦσι, τῆς κατʼ ἐκεῖνο γνώμης οὐκ ἂν ἁμάρτοι· καὶ ὁ πῖλος δέ μοι δοκεῖ τὸν οὐρανὸν τεκμηριοῦν ὑακίνθινος πεποιημένος,"},{"number":187,"text":"οὐ γὰρ ἂν ἄλλως ὑπερανετίθετο αὐτῷ τὸ ὄνομα τοῦ θεοῦ τῇ στεφάνῃ ἠγλαϊσμένον καὶ ταύτῃ χρυσέᾳ, διὰ τὴν αὐγήν, ᾗ μάλιστα χαίρει τὸ θεῖον. καὶ ταῦτα μὲν ἐπὶ τοσοῦτόν μοι δεδηλώσθω πολλάκις τε καὶ ἐν πολλοῖς τὴν ἀρετὴν τοῦ νομοθέτου παρεξόντων ἡμῖν διελθεῖν τῶν πραγμάτων."}],"8":[{"number":188,"text":"Ὡς δὲ τὸ προειρημένον πέρας εἶχε, τῶν ἀναθημάτων μήπω καθιερωμένων ἐπιστὰς ὁ θεὸς Μωυσεῖ τὴν ἱερωσύνην Ἀαρῶνι τἀδελφῷ προσέταξε δοῦναι ὡς ἁπάντων διʼ ἀρετὴν τῆς τιμῆς δικαιοτέρῳ τυχεῖν. καὶ συναγαγὼν εἰς ἐκκλησίαν τὸ πλῆθος τήν τε ἀρετὴν αὐτοῦ καὶ τὴν εὔνοιαν διεξῄει καὶ τοὺς κινδύνους οὓς ὑπομείνειεν ὑπὲρ αὐτῶν."},{"number":189,"text":"μαρτυρούντων δʼ ἐφʼ ἅπασιν αὐτῷ καὶ τὸ περὶ αὐτὸν πρόθυμον ἐνδεικνυμένων, ἄνδρες, εἶπεν, Ἰσραηλῖται, τὸ μὲν ἔργον ἤδη τέλος ἔχει οἷον αὐτῷ τε τῷ θεῷ ἥδιστον ἦν καὶ δυνατὸν ἡμῖν, ἐπεὶ δὲ δεῖ τοῦτον τῇ σκηνῇ καταδέχεσθαι, δεῖ πρῶτον ἡμῖν τοῦ ἱερατευσομένου καὶ ὑπηρετήσοντος ταῖς θυσίαις καὶ ταῖς ὑπὲρ ἡμῶν εὐχαῖς."},{"number":190,"text":"καὶ ἔγωγε ταύτης ἐμοὶ τῆς σκέψεως ἐπιτραπείσης ἐμαυτὸν ἂν τῆς τιμῆς ἄξιον ἔκρινα διά τε τὸ φύσει πάντας εἶναι φιλαύτους, καὶ ὅτι πολλὰ ἐμαυτῷ καμόντι περὶ σωτηρίας τῆς ὑμετέρας σύνοιδα· νῦν δʼ αὐτὸς ὁ θεὸς Ἀαρῶνα τῆς τιμῆς ἄξιον ἔκρινε καὶ τοῦτον ᾕρηται ἱερέα, τὸν δικαιότερον ἡμῶν μᾶλλον εἰδώς,"},{"number":191,"text":"ὡς οὗτος ἐνδύσεται στολὴν τῷ θεῷ καθωσιωμένην καὶ βωμῶν ἐπιμέλειαν ἕξει καὶ πρόνοιαν ἱερείων καὶ τὰς ὑπὲρ ἡμῶν εὐχὰς ποιήσεται πρὸς τὸν θεὸν ἡδέως ἀκουσόμενον, ὅτι τε κήδεται γένους τοῦ ἡμετέρου καὶ παρʼ ἀνδρὸς ὃν αὐτὸς ἐπελέξατο γινομένας προσδέχεται ταύτας."},{"number":192,"text":"Ἑβραῖοι δὲ ἠρέσκοντο τοῖς λεγομένοις καὶ συνῄνουν τῇ τοῦ θεοῦ χειροτονίᾳ· ἦν γὰρ Ἀαρὼν διά τε τὸ γένος καὶ τὴν προφητείαν καὶ τὴν ἀρετὴν τἀδελφοῦ πρὸς τιμὴν ἁπάντων ἀξιολογώτερος. ἦσαν δʼ αὐτῷ καὶ παῖδες κατʼ ἐκεῖνον τὸν χρόνον τέσσαρες Νάβαδος Ἀβιοῦς Ἐλεάζαρος Ἰθάμαρος."},{"number":193,"text":"Ὅσα δὲ τῶν πρὸς τὴν τῆς σκηνῆς κατασκευὴν παρεσκευασμένων ἦν περιττὰ ταῦτʼ ἐκέλευσεν εἰς φάρση σκεπαστήρια τῆς τε σκηνῆς αὐτῆς καὶ τῆς λυχνίας καὶ τοῦ θυμιατηρίου καὶ τῶν ἄλλων σκευῶν ἀναλῶσαι, ὅπως κατὰ τὴν ὁδοιπορίαν ταῦτα μήτʼ ἐξ ὑετοῦ μηδὲν μήτʼ ἐκ κονιορτοῦ βλάπτηται."},{"number":194,"text":"τό τε πλῆθος ἀθροίσας πάλιν εἰσφορὰν αὐτῷ προσέταξεν εἰσφέρειν σίκλου τὸ ἥμισυ καθʼ ἕκαστον,"},{"number":195,"text":"ὁ δὲ σίκλος νόμισμα Ἑβραίων ὢν Ἀττικὰς δέχεται δραχμὰς τέσσαρας·"},{"number":196,"text":"οἱ δʼ ἑτοίμως ὑπήκουον οἷς ἐκέλευσε Μωυσῆς καὶ τὸ πλῆθος τῶν εἰσφερόντων ἦν ἑξήκοντα μυριάδες καὶ πεντακισχίλιοι καὶ πεντακόσιοι καὶ πεντήκοντα. ἔφερον δὲ τὸ ἀργύριον τῶν ἐλευθέρων οἱ ἀπὸ εἴκοσι ἐτῶν ἄχρι πεντήκοντα γεγονότες. τὸ δὲ συγκομισθὲν εἰς τὰς περὶ τὴν σκηνὴν χρείας ἀναλοῦτο."},{"number":197,"text":"Ἥγνιζε δὲ καὶ τὴν σκηνὴν καὶ τοὺς ἱερέας τρόπῳ τοιούτῳ ποιούμενος αὐτῶν τὴν κάθαρσιν. σμύρνης ἐπιλέκτου σίκλους πεντακοσίους καὶ ἴρεως ἴσους, κινναμώμου δὲ καὶ καλάμου, ἔστι δὲ καὶ τοῦτο εἶδος θυμιάματος, ἡμίσειαν τῶν πρότερον ὁλκὴν κεκομμένα δεύειν ἐκέλευσεν, ἐλαίου τε ἐλαΐνου εἴν, μέτρον δʼ ἐστὶ τοῦτο ἐπιχώριον δύο χόας Ἀττικοὺς δεχόμενον, ἀναμίξαντας καὶ καθεψήσαντας σκευάσαι τέχνῃ μυρεψῶν χρῖσμα εὐωδέστατον."},{"number":198,"text":"κἄπειτα τοῦτο λαβὼν αὐτούς τε τοὺς ἱερέας καὶ πᾶσαν τὴν σκηνὴν χρίων κεκάθαρκε, τά τε θυμιώμενα, πολλὰ δʼ ἐστὶ ταῦτα καὶ ποικίλα, κατὰ τὴν σκηνὴν ἐπὶ τοῦ χρυσοῦ θυμιατηρίου μεγάλης πάνυ τιμῆς ὄντα συνεφέρετο, ὧν παραλείπω τὴν φύσιν ἐκδιηγεῖσθαι, μὴ διʼ ὄχλου γένηται τοῖς ἐντυγχάνουσι."},{"number":199,"text":"δὶς δὲ τῆς ἡμέρας πρίν τε ἀνασχεῖν τὸν ἥλιον καὶ πρὸς δυσμαῖς θυμιᾶν ἐχρῆν ἔλαιόν τε ἁγνίσαντας φυλάσσειν εἰς τοὺς λύχνους, ὧν τοὺς μὲν τρεῖς ἐπὶ τῇ ἱερᾷ λυχνίᾳ φέγγειν ἔδει τῷ θεῷ κατὰ πᾶσαν ἡμέραν, τοὺς δὲ λοιποὺς περὶ τὴν ἑσπέραν ἅπτοντας."},{"number":200,"text":"Ἁπάντων δʼ ἤδη πέρας εἰληφότων ἔδοξαν ἄριστοι τῶν δημιουργῶν Βεσέβηλος καὶ Ἐλίαβος, τῶν γὰρ ἐξευρημένων τοῖς προτέροις αὐτοὶ προεθυμήθησαν ἀμείνονα προσεξεργάσασθαι, λαβεῖν τε ἐπίνοιαν ὧν πρότερον ἠγνόουν τὴν κατασκευὴν ἱκανώτατοι·"},{"number":201,"text":"τούτων μέντοι Βεσέβηλον συνέβη κριθῆναι τὸν κράτιστον. ὁ δὲ πᾶς χρόνος εἰς τὸ ἔργον διῆλθε μηνῶν ἑπτὰ καὶ μετὰ τοῦτο ἀφʼ οὗ τὴν Αἴγυπτον ἐξέλιπον ἐνιαυτὸς αὐτοῖς πρῶτος ἐτελειοῦτο. ἀρχομένου δὲ τοῦ δευτέρου ἔτους μηνὶ Ξανθικῷ κατὰ Μακεδόνας Νισὰν δὲ κατὰ Ἑβραίους νουμηνίᾳ τὴν σκηνὴν ἀφιεροῦσι καὶ πάνθʼ ὅσα περὶ αὐτὴν σκεύη μοι δεδήλωται."},{"number":202,"text":"Ἐπέδειξε δὲ ὁ θεὸς αὑτὸν ἡσθέντα τῷ ἔργῳ τῶν Ἑβραίων καὶ μὴ μάτην αὐτοὺς πονήσαντας ὑπερηφανίᾳ τῆς χρήσεως, ἀλλʼ ἐπεξενώθη καὶ κατεσκήνωσε τῷ ναῷ τούτῳ. τὴν δὲ παρουσίαν οὕτως ἐποίησεν·"},{"number":203,"text":"ὁ μὲν οὐρανὸς καθαρὸς ἦν, ὑπὲρ δὲ τὴν σκηνὴν μόνην ἤχλυσεν οὔτε βαθεῖ πάνυ νέφει καὶ πυκνῷ περιλαβὼν αὐτήν, ὥστʼ εἶναι δόξαι χειμέριον, οὔτε μὴν λεπτὸν οὕτως, ὥστε τὴν ὄψιν ἰσχύσαι τι διʼ αὐτοῦ κατανοῆσαι· ἡδεῖα δὲ ἀπʼ αὐτοῦ δρόσος ἔρρει καὶ θεοῦ δηλοῦσα παρουσίαν τοῖς τοῦτο καὶ βουλομένοις καὶ πεπιστευκόσι."},{"number":204,"text":"Μωυσῆς δὲ τοὺς τέκτονας οἵαις εἰκὸς ἦν δωρεαῖς τοὺς τοιαῦτα ἐργασαμένους τιμήσας ἔθυεν ἐν τῷ τῆς σκηνῆς αἰθρίῳ κατὰ προσταγὴν θεοῦ ταῦρον καὶ κριὸν καὶ ἔριφον ὑπὲρ ἁμαρτάδων,"},{"number":205,"text":"καὶ δὴ, λέγειν γὰρ ἐν τοῖς περὶ θυσιῶν μέλλω τὰ πρασσόμενα περὶ τὰς ἱερουργίας ἐν ἐκείνοις δηλώσων περί τε ὧν ὁλοκαυτεῖν κελεύει καὶ ὧν μεταλαμβάνειν τῆς βρώσεως ἐφίησιν ὁ νόμος, κἀκ τοῦ αἵματος τῶν τεθυμένων τήν τε στολὴν τοῦ Ἀαρῶνος καὶ αὐτὸν σὺν τοῖς παισὶν ἔρραινεν ἀφαγνίσας πηγαίοις τε ὕδασι καὶ μύρῳ, ἵνα τοῦ θεοῦ γίγνοιντο."},{"number":206,"text":"ἐπὶ μὲν οὖν ἡμέρας ἑπτὰ τοῦτον τὸν τρόπον αὐτούς τε καὶ τὰς στολὰς ἐθεράπευε τήν τε σκηνὴν καὶ τὰ περὶ αὐτὴν σκεύη ἐλαίῳ τε προσχριομένῳ, καθὼς εἶπον, καὶ τῷ αἵματι τῶν ταύρων καὶ κριῶν σφαγέντων καθʼ ἑκάστην ἡμέραν ἑνὸς κατὰ γένος, τῇ δὲ ὀγδόῃ κατήγγειλεν ἑορτὴν τῷ λαῷ καὶ θύειν προσέταξε κατὰ δύναμιν."},{"number":207,"text":"οἱ δʼ ἀλλήλοις ἁμιλλώμενοι καὶ ὑπερβάλλειν φιλοτιμούμενοι τὰς θυσίας, ἃς ἕκαστος ἐπιφέροι, τοῖς λεγομένοις ὑπήκουον. ἐπικειμένων δὲ τῶν ἱερῶν τῷ βωμῷ αἰφνίδιον ἐξ αὐτοῦ πῦρ ἀνήφθη αὐτόματον, καὶ ὅμοιον ἀστραπῆς λαμπηδόνι ὁρώμενον τῇ φλογὶ πάντα ἐδαπάνα τὰ ἐπὶ τοῦ βωμοῦ."},{"number":208,"text":"Συνέβη δὲ καὶ Ἀαρῶνι συμφορά τις ἐκ τούτου λογιζομένῳ ὡς ἐπʼ ἀνθρώπῳ καὶ πατρί, γενναίως δʼ ὑπʼ αὐτοῦ καρτερηθεῖσα, ὅτι καὶ τὴν ψυχὴν πρὸς τὰ συμπίπτοντα στερρὸς ἦν καὶ κατὰ βούλησιν τοῦ θεοῦ ἡγεῖτο τὸ πάθος γεγονέναι·"},{"number":209,"text":"τῶν γὰρ υἱῶν αὐτοῦ τεσσάρων ὄντων, ὡς προεῖπον, δύο οἱ πρεσβύτεροι Νάβαδος καὶ Ἀβιοῦς κομίσαντες ἐπὶ τὸν βωμὸν οὐχ ὧν προεῖπε Μωυσῆς θυμάτων, ἀλλʼ οἷς ἐχρῶντο πρότερον, κατεκαύθησαν τοῦ πυρὸς ἐπʼ αὐτοὺς τὴν ὁρμὴν βαλόντος καὶ τὰ στέρνα καὶ τὰ πρόσωπα φλέγειν αὐτῶν ἀρξαμένου καὶ σβέσαι μηδενὸς δυναμένου."},{"number":210,"text":"καὶ οἱ μὲν οὕτως ἀπέθανον· Μωυσῆς δὲ κελεύει τὸν πατέρα αὐτῶν καὶ τοὺς ἀδελφοὺς βαστάξαντας τὰ σώματα καὶ κομίσαντας τῆς παρεμβολῆς ἔξω θάψαι μεγαλοπρεπῶς. πενθεῖ δὲ αὐτοὺς τὸ πλῆθος χαλεπῶς ἐπὶ τῷ θανάτῳ παρὰ δόξαν οὕτω γεγενημένῳ διατεθέν."},{"number":211,"text":"μόνους δὲ Μωυσῆς τοὺς ἀδελφοὺς αὐτῶν καὶ τὸν πατέρα μὴ φροντίζειν τῆς ἐπʼ αὐτοῖς λύπης ἠξίωσε προκρίναντας τὴν εἰς τὸν θεὸν τιμὴν τοῦ περὶ αὐτοὺς σκυθρωποῦ· ἤδη γὰρ Ἀαρὼν καὶ τὴν στολὴν τὴν ἱερὰν ἠμφίεστο."},{"number":212,"text":"Μωυσῆς δὲ πᾶσαν τιμὴν παραιτησάμενος, ἣν ἑώρα τὸ πλῆθος αὐτῷ παρασχεῖν ἕτοιμον, πρὸς μόνῃ τῇ τοῦ θεοῦ θεραπείᾳ διετέλει. καὶ τῶν μὲν εἰς τὸ Σιναῖον ἀνόδων ἀπείχετο, εἰς δὲ τὴν σκηνὴν εἰσιὼν ἐχρηματίζετο περὶ ὧν ἐδεῖτο παρὰ τοῦ θεοῦ ἰδιωτεύων καὶ τῇ στολῇ καὶ πᾶσι τοῖς ἄλλοις ἄγων ἑαυτὸν δημοτικώτερον καὶ μηδὲν βουλόμενος τῶν πολλῶν διαφέρειν δοκεῖν, ἢ μόνῳ τῷ προνοούμενος αὐτῶν βλέπεσθαι."},{"number":213,"text":"ἔτι δὲ τὴν πολιτείαν καὶ νόμους αὐτῶν ἔγραφε, καθʼ οὓς κεχαρισμένως τῷ θεῷ βιώσονται μηδὲν ἀλλήλοις ἐγκαλεῖν ἔχοντες· ταῦτα μέντοι κατὰ τὴν ὑπαγόρευσιν τοῦ θεοῦ συνετάττετο. διέξειμι μὲν οὖν περὶ τῆς πολιτείας καὶ τῶν νόμων."},{"number":214,"text":"Ὃ μέντοι περὶ τῆς τοῦ ἀρχιερέως στολῆς παρέλιπον διελθεῖν βούλομαι· οὐδαμόθεν γὰρ προφητῶν κακουργίαις κατέλιπεν ἀφορμήν, εἰ δέ τινες τοιοῦτοι γένοιντο παρεγχειρεῖν τῷ τοῦ θεοῦ ἀξιώματι, αὐτοκράτορα δʼ εἶναι τὸν θεὸν παρατυγχάνειν τοῖς ἱεροῖς κατέλιπεν ὁπότε θελήσειε καὶ μὴ παρεῖναι, καὶ τοῦτʼ οὐχ Ἑβραίοις δῆλον εἶναι μόνον ἠθέλησεν, ἀλλὰ καὶ τῶν ξένων τοῖς παρατυγχάνουσι."},{"number":215,"text":"τῶν γὰρ λίθων, οὓς ἐπὶ τοῖς ὤμοις φέρειν τὸν ἀρχιερέα προεῖπον, σαρδόνυχες δὲ ἦσαν καὶ σημαίνειν αὐτῶν τὴν φύσιν ἡγοῦμαι περισσὸν πᾶσιν εἰς γνῶσιν ἀφιγμένων, συνέβαινε λάμπειν, ὁπότε ταῖς ἱερουργίαις ὁ θεὸς παρείη, τὸν ἕτερον τὸν ἐπὶ τῷ δεξιῷ τῶν ὤμων πεπορπημένον αὐγῆς ἀποπηδώσης καὶ τοῖς πορρωτάτω φαινομένης, οὐ πρότερον ταύτης ὑπαρχούσης τῷ λίθῳ."},{"number":216,"text":"θαυμαστὸν μὲν οὖν καὶ τοῦτο τοῖς μὴ τὴν σοφίαν ἐπʼ ἐκφαυλισμῷ τῶν θείων ἠσκηκόσιν, ὃ δʼ ἐστὶ τούτου θαυμασιώτερον ἐρῶ· διὰ γὰρ τῶν δώδεκα λίθων, οὓς κατὰ στέρνον ὁ ἀρχιερεὺς ἐνερραμμένους τῷ ἐσσῆνι φορεῖ, νίκην μέλλουσι πολεμεῖν προεμήνυεν ὁ θεός·"},{"number":217,"text":"τοσαύτη γὰρ ἀπήστραπτεν ἀπʼ αὐτῶν αὐγὴ μήπω τῆς στρατιᾶς κεκινημένης, ὡς τῷ πλήθει παντὶ γνώριμον εἶναι τὸ παρεῖναι τὸν θεὸν εἰς τὴν ἐπικουρίαν, ὅθεν Ἕλληνες οἱ τὰ ἡμέτερα τιμῶντες ἔθη διὰ τὸ μηδὲν ἀντιλέγειν δύνασθαι τούτοις τὸν ἐσσῆνα λόγιον καλοῦσιν."},{"number":218,"text":"ἐπαύσατο μὲν οὖν ὅ τε ἐσσὴν καὶ ὁ σαρδόνυξ τοῦ λάμπειν ἔτεσι διακοσίοις πρότερον ἢ ταύτην ἐμὲ συνθεῖναι τὴν γραφὴν τοῦ θεοῦ δυσχεράναντος ἐπὶ τῇ παραβάσει τῶν νόμων, περὶ ὧν ἐροῦμεν εὐκαιρότερον. τρέψομαι δὲ νῦν ἐπὶ τὸν ἑξῆς λόγον."},{"number":219,"text":"Καθιερωμένης γὰρ δὴ τῆς σκηνῆς καὶ διακεκοσμημένων τῶν περὶ τοὺς ἱερέας τό τε πλῆθος ὁμόσκηνον αὐτῷ τὸν θεὸν ἔκρινεν εἶναι καὶ τρέπεται πρὸς θυσίας τε καὶ ἀνέσεις ὡς ἅπασαν ἤδη κακοῦ προσδοκίαν ἀπεωσμένον, καὶ περὶ τῶν μελλόντων ὡς ἀμεινόνων ἐπιθυμοῦντες δωρεάς τε τῷ θεῷ τὰς μὲν κοινῇ τὰς δὲ κατʼ ἰδίαν ἀνετίθεσαν κατὰ φυλάς·"},{"number":220,"text":"οἵ τε γὰρ φύλαρχοι κατὰ δύο συνελθόντες ἅμαξαν καὶ δύο βόας προσκομίζουσιν· ἓξ μὲν οὖν ἦσαν αὗται καὶ τὴν σκηνὴν ἐν ταῖς ὁδοιπορίαις παρεκόμιζον. πρὸς τούτοις ἕκαστος φιάλην τε κομίζει καὶ τρύβλιον καὶ θυΐσκην, τὴν μὲν δαρεικοὺς δέκα δυναμένην καὶ πλήρη θυμιαμάτων·"},{"number":221,"text":"τὸ δὲ τρύβλιον καὶ ἡ φιάλη, ἀργυρᾶ δὲ ἦν, σίκλους μὲν αἱ δύο διακοσίους εἷλκον, εἰς δὲ τὴν φιάλην ἑβδομήκοντα μόνοι δεδαπάνηντο, πλήρεις δὲ ἦσαν ἀλεύρων ἐλαίῳ πεφυραμένων, οἷς ἐπὶ τῷ βωμῷ χρῶνται πρὸς τὰς ἱερουργίας· μόσχον τε καὶ κριὸν σὺν ἀρνίῳ ἐτείῳ ὁλομελῆ καυθησόμενα καὶ σὺν αὐτοῖς χίμαρον ἐπὶ παραιτήσει ἁμαρτημάτων."},{"number":222,"text":"προσῆγε δὲ τῶν ἀρχόντων ἕκαστος καὶ ἑτέρας θυσίας σωτηρίους λεγομένας καθʼ ἑκάστην ἡμέραν δύο βόας καὶ πέντε κριοὺς σὺν ἀρνάσιν ἐτείοις καὶ ἐρίφοις. οὗτοι μὲν δὴ θύουσιν ἐπὶ ἡμέρας δώδεκα κατὰ πᾶσαν ἡμέραν εἷς· Μωυσῆς δὲ οὐκέτʼ ἀναβαίνων ἐπὶ τὸ Σιναῖον ἀλλʼ εἰς τὴν σκηνὴν εἰσιὼν ἀνεμάνθανε παρὰ θεοῦ περί τε τῶν πρακτέων καὶ τῶν νόμων τῆς συντάξεως·"},{"number":223,"text":"οὓς κρείττονας ἢ κατὰ σύνεσιν ἀνθρωπίνην ὄντας εἰς τὸν ἅπαντα βεβαίως αἰῶνα συνέβη φυλαχθῆναι δωρεὰν εἶναι δόξαντας τοῦ θεοῦ, ὡς μήτʼ ἐν εἰρήνῃ ὑπὸ τρυφῆς μήτʼ ἐν πολέμῳ κατʼ ἀνάγκην Ἑβραίους παραβῆναί τινα τῶν νόμων. ἀλλὰ περὶ μὲν τούτων παύομαι λέγων γραφὴν ἑτέραν ἠξιωκὼς συνθεῖναι περὶ τῶν νόμων."}],"9":[{"number":224,"text":"Νυνὶ δʼ ὀλίγων τινῶν ἐπιμνησθήσομαι τῶν ἐφʼ ἁγνείαις καὶ ἱερουργίαις κειμένων· καὶ γὰρ τὸν λόγον μοι περὶ τῶν θυσιῶν ἐνεστάναι συμβέβηκε. δύο μὲν γάρ εἰσιν ἱερουργίαι, τούτων δʼ ἡ μὲν ὑπὸ τῶν ἰδιωτῶν ἑτέρα δʼ ὑπὸ τοῦ δήμου συντελούμεναι κατὰ δύο γίνονται τρόπους·"},{"number":225,"text":"τῆς μὲν ὁλοκαυτεῖται πᾶν τὸ θυόμενον καὶ διὰ τοῦτο καὶ τὴν προσηγορίαν τοιαύτην ἔλαβεν, ἡ δὲ χαριστήριός τέ ἐστι καὶ κατʼ εὐωχίαν δρᾶται τῶν τεθυκότων· ἐρῶ δὲ περὶ τῆς προτέρας."},{"number":226,"text":"ἀνὴρ ἰδιώτης ὁλοκαυτῶν θύει μὲν βοῦν καὶ ἀρνίον καὶ ἔριφον· ταῦτα μὲν ἐπέτεια, τοὺς δὲ βοῦς ἐφεῖται θύειν καὶ προήκοντας· ἄρρενα δὲ ὁλοκαυτεῖται τὰ πάντα. σφαγέντων δὲ τούτων τὸν κύκλον τῷ αἵματι δεύουσι τοῦ βωμοῦ οἱ ἱερεῖς,"},{"number":227,"text":"εἶτα καθαρὰ ποιήσαντες διαμελίζουσι καὶ πάσαντες ἁλσὶν ἐπὶ τὸν βωμὸν ἀνατιθέασι σχιζῶν ἤδη πεπληρωμένον καὶ πυρὸς φλεγομένου. τοὺς δὲ πόδας τῶν ἱερείων καὶ τὰ κατὰ νηδὺν ἐκκαθάραντες ἀκριβῶς τοῖς ἄλλοις καθαγνισθησόμενα προσεπιφέρουσι, τὰς δορὰς τῶν ἱερέων λαμβανόντων. καὶ ὁ μὲν τῆς ὁλοκαυτώσεως τρόπος ἐστὶν οὗτος."},{"number":228,"text":"Τὰς δὲ χαριστηρίους θυσίας ἐπιτελοῦντες τὰ αὐτὰ μὲν ζῷα θύουσιν, ὁλόκληρα δὲ ταῦτα καὶ τῶν ἐπετείων πρεσβύτερα, ἄρρενα μέντοι θήλεσι συνδυαζόμενα. θύσαντες δὲ ταῦτα φοινίσσουσι μὲν αἵματι τὸν βωμόν, τοὺς δὲ νεφροὺς καὶ τὸν ἐπίπλουν καὶ πάντα τὰ πιμελῆ σὺν τῷ λοβῷ τοῦ ἥπατος καὶ σὺν αὐτοῖς τὴν οὐρὰν τοῦ ἀρνὸς ἐπιφέρουσι τῷ βωμῷ."},{"number":229,"text":"τὸ δὲ στῆθος καὶ τὴν κνήμην τὴν δεξιὰν τοῖς ἱερεῦσι παρασχόντες ἐπὶ δύο ἡμέρας εὐωχοῦνται τοῖς καταλειπομένοις τῶν κρεῶν, ἃ δʼ ἂν περισσεύσῃ κατακαίουσι."},{"number":230,"text":"Θύουσι δὲ καὶ ὑπὲρ ἁμαρτάδων καὶ ὁμοίως τῷ προειρημένῳ τὸ περὶ τῶν ἁμαρτάδων τῆς ἱερουργίας τρόπῳ γίνεται. οἱ δὲ ἀδύνατοι πορίζειν τὰ τέλεια θύματα περιστερὰς ἢ τρυγόνας δύο, ὧν τὸ μὲν ὁλοκαυτεῖται τῷ θεῷ, τὸ δὲ τοῖς ἱερεῦσιν εἰς βρῶσιν διδόασιν. ἀκριβέστερον δὲ περὶ τῆς θυσίας τῶνδε τῶν ζῴων ἐν τοῖς περὶ θυσιῶν ἐροῦμεν."},{"number":231,"text":"ὁ μὲν γὰρ κατὰ ἄγνοιαν εἰς τοῦτο προπεσὼν ἄρνα καὶ ἔριφον θήλειαν τῶν αὐτοετῶν προσφέρει, καὶ τῷ μὲν αἵματι δεύει τὸν βωμὸν ὁ ἱερεὺς οὐχ ὡς τὸ πρῶτον ἀλλὰ τῶν γωνιῶν τὰς ἐξοχάς, καὶ τούς τε νεφροὺς καὶ τὴν ἄλλην πιμελὴν σὺν τῷ λοβῷ τοῦ ἥπατος ἐπιφέρουσι τῷ βωμῷ, οἱ δὲ ἱερεῖς τάς τε δορὰς ἀποφέρονται καὶ τὰ κρέα ἐπʼ ἐκείνης δαπανήσοντες τῆς ἡμέρας ἐν τῷ ἱερῷ· ὁ γὰρ νόμος εἰς τὴν αὔριον ἀπολιπεῖν οὐκ ἐᾷ."},{"number":232,"text":"ὁ δὲ ἁμαρτὼν μὲν αὑτῷ δὲ συνειδὼς καὶ μηδένα ἔχων τὸν ἐξελέγχοντα κριὸν θύει τοῦ νόμου τοῦτο κελεύοντος, οὗ τὰ κρέα κατὰ τὸ ἱερὸν ὁμοίως οἱ ἱερεῖς αὐθημερὸν σιτοῦνται. οἱ δὲ ἄρχοντες ἐφʼ οἷς ἡμάρτανον ἐκθυόμενοι ταὐτὰ μὲν κομίζουσι τοῖς ἰδιώταις, διαλλάσσουσι δὲ τῷ προσάγειν θύματα ταῦρον ἔριφον ἄρσενας."},{"number":233,"text":"Νόμος δὲ ταῖς ἰδιωτικαῖς καὶ ταῖς δημοσίαις θυσίαις καὶ ἄλευρον ἐπιφέρεσθαι καθαρώτατον, ἀρνὶ μὲν ἀσσαρῶνος μέτρον κριῷ δὲ δυοῖν ταύρῳ δὲ τριῶν. τοῦτο καθαγνίζουσιν ἐπὶ τῷ βωμῷ μεμαγμένον ἐλαίῳ·"},{"number":234,"text":"κομίζεται γὰρ δὴ καὶ ἔλαιον ὑπὸ τῶν τεθυκότων ἐπὶ μὲν βοῒ ἰνὸς ἥμισυ, ἐπὶ δὲ κριῷ μέρος τούτου τρίτον τοῦ μέτρου, καὶ τετάρτη μερὶς ἐπʼ ἀρνί· ὁ δὲ ἲν μέτρον ἀρχαῖον Ἑβραίων δύναται δύο χόας Ἀττικούς. τὸ δʼ αὐτὸ μέτρον τῷ ἐλαίῳ καὶ οἴνου παρῆγον, σπένδουσι δὲ περὶ τὸν βωμὸν τὸν οἶνον."},{"number":235,"text":"εἰ δέ τις θυσίαν οὐκ ἐπιτελῶν ἐπήνεγκε κατʼ εὐχὴν σεμίδαλιν, ταύτης ἀπαρχὴν μίαν ἐπιβάλλει τῷ βωμῷ δράκα, τὴν δὲ λοιπὴν οἱ ἱερεῖς πρὸς τροφὴν λαμβάνουσιν ἢ ἑψηθεῖσαν, ἐλαίῳ γὰρ συμπεφύραται, ἢ γενομένων ἄρτων. ἱερέως δὲ κομίσαντος καὶ ὁποσονοῦν ὁλοκαυτεῖν ἀναγκαῖον."},{"number":236,"text":"κωλύει δὲ ὁ νόμος θύειν ζῷον αὐθημερὸν μετὰ τοῦ γεγεννηκότος ἐπὶ ταὐτό, οὐδʼ ἄλλως δὲ πρὶν ὀγδόην ἡμέραν γεννηθέντι διελθεῖν. γίνονται δὲ ἄλλαι θυσίαι ὑπὲρ τοῦ τὰς νόσους διαφυγεῖν ἢ κατʼ ἄλλας αἰτίας, εἰς ἃς πέμματα σὺν ἱερείοις ἀναλίσκεται, ὧν εἰς τὴν ὑστέραν οὐδὲν ὑπολιπεῖν ἐστι νόμιμον, τῶν ἱερέων μέρος ἴδιον λαβόντων."}],"10":[{"number":237,"text":"Ἐκ δὲ τοῦ δημοσίου ἀναλώματος νόμος ἐστὶν ἄρνα καθʼ ἑκάστην ἡμέραν σφάζεσθαι τῶν αὐτοετῶν ἀρχομένης τε ἡμέρας καὶ ληγούσης, κατὰ δὲ ἑβδόμην ἡμέραν, ἥτις σάββατα καλεῖται, δύο σφάττουσι τὸν αὐτὸν τρόπον ἱερουργοῦντες."},{"number":238,"text":"τῇ δὲ νουμηνίᾳ τάς τε καθημερινὰς θυσίας ἐπιτελοῦσι καὶ δύο βόας σὺν ἀρνάσιν ἐνιαυσιαίοις ἑπτὰ καὶ κριόν, ἔριφον δὲ ἐπὶ παραιτήσεσιν ἁμαρτάδων, εἴ τι κατὰ λήθην γένοιτο."},{"number":239,"text":"Τῷ δʼ ἑβδόμῳ μηνί, ὃν Μακεδόνες Ὑπερβερεταῖον καλοῦσι, προσθέντες τοῖς εἰρημένοις ταῦρον καὶ κριὸν καὶ ἄρνας ἑπτὰ θύουσι καὶ ἔριφον ὑπὲρ ἁμαρτάδων."},{"number":240,"text":"Δεκάτῃ δὲ τοῦ αὐτοῦ μηνὸς κατὰ σελήνην διανηστεύοντες ἕως ἑσπέρας θύουσι δʼ ἐν ταύτῃ τῇ ἡμέρᾳ ταῦρόν τε καὶ κριοὺς δύο καὶ ἄρνας ἑπτὰ καὶ ὑπὲρ ἁμαρτάδων ἔριφον."},{"number":241,"text":"προσάγουσι δὲ δύο πρὸς τούτοις ἐρίφους, ὧν ὁ μὲν ζῶν εἰς τὴν ὑπερόριον ἐρημίαν πέμπεται ἀποτροπιασμὸς καὶ παραίτησις τοῦ πλήθους παντὸς ὑπὲρ ἁμαρτημάτων ἐσόμενος, τὸν δʼ ἐν τοῖς προαστείοις εἰς καθαρώτατον ἄγοντες χωρίον αὐτόθι σὺν αὐτῇ καίουσι τῇ δορᾷ μηδὲν ὅλως καθάραντες."},{"number":242,"text":"συγκατακαίεται δὲ ταῦρος οὐχ ὑπὸ τοῦ δήμου προσαχθείς, ἀλλʼ ἐκ τῶν ἰδίων ἀναλωμάτων τοῦ ἀρχιερέως παρασχόντος· οὗ δὴ σφαγέντος εἰσκομίσας εἰς τὸν ναὸν τοῦ αἵματος ἅμα καὶ τοῦ ἐρίφου ῥαίνει τῷ δακτύλῳ τὸν ὄροφον ἑπτάκις,"},{"number":243,"text":"τοῦ δʼ αὐτοῦ καὶ τὸ ἔδαφος καὶ τοσαυτάκις εἰς τὸν ναὸν καὶ περὶ τὸν χρύσεον βωμὸν καὶ τὸ λοιπὸν περὶ τῷ μείζονι κομίσας εἰς τὸ αἴθριον· πρὸς τούτοις τὰς ἐξοχὰς καὶ τοὺς νεφροὺς καὶ τὴν πιμελὴν σὺν τῷ λοβῷ τοῦ ἥπατος ἐπιφέρουσι τῷ βωμῷ. παρέχεται δὲ καὶ κριὸν ὁ ἀρχιερεὺς ὁλοκαύτωσιν τῷ θεῷ."},{"number":244,"text":"Τῇ δὲ πέμπτῃ τοῦ αὐτοῦ μηνὸς καὶ δεκάτῃ τρεπομένου τὸ λοιπὸν τοῦ καιροῦ πρὸς τὴν χειμερινὴν ὥραν σκηνὰς πήγνυσθαι κελεύει κατὰ οἰκίαν ἕκαστον, τό τε κρύος ὑφορωμένους ἐπὶ φυλακῇ τοῦ ἔτους,"},{"number":245,"text":"ὅταν πατρίδων ἐπιτύχοιεν, παραγινομένους εἰς ἐκείνην τὴν πόλιν, ἣν διὰ τὸν ναὸν μητρόπολιν ἕξουσιν, ἐφʼ ἡμέρας ὀκτὼ ἑορτὴν ἄγοντας ὁλοκαυτεῖν τε καὶ θύειν τῷ θεῷ τότε χαριστήρια, φέροντας ἐν ταῖς χερσὶν εἰρεσιώνην μυρσίνης καὶ ἰτέας σὺν κράδῃ φοίνικος πεποιημένην τοῦ μήλου τοῦ τῆς περσέας προσόντος."},{"number":246,"text":"εἶναι δὲ τῇ πρώτῃ τῶν ἡμερῶν τὴν τῆς ὁλοκαυτώσεως θυσίαν ἐκ τριῶν καὶ δέκα βοῶν καὶ ἀρνῶν ἑνὶ πλειόνων καὶ κριῶν δύο κατὰ παραίτησιν ἁμαρτιῶν ἐρίφου προστιθεμένου. ταῖς δʼ ἑξῆς ἡμέραις ὁ μὲν αὐτὸς ἀριθμὸς τῶν ἀρνῶν καὶ τῶν κριῶν σὺν τῷ ἐρίφῳ θύεται, ὑφαιροῦντες δὲ ἑκάστης ἡμέρας ἕνα τῶν βοῶν εἰς ἑπτὰ καταντῶσιν."},{"number":247,"text":"ἀνίενται δὲ ἀπὸ παντὸς ἔργου κατὰ τὴν ὀγδόην ἡμέραν καὶ τῷ θεῷ, καθάπερ εἰρήκαμεν, μόσχον τε θύομεν καὶ κριὸν καὶ ἄρνας ἑπτά, ὑπὲρ δὲ ἁμαρτημάτων παραιτήσεως ἔριφον. καὶ ταῦτα μὲν Ἑβραίοις τὰς σκηνὰς πηγνύουσιν ἐπιτελεῖν ἐστι πάτριον."},{"number":248,"text":"Τῷ δὲ μηνὶ τῷ Ξανθικῷ, ὃς Νισὰν παρʼ ἡμῖν καλεῖται καὶ τοῦ ἔτους ἐστὶν ἀρχή, τεσσαρεσκαιδεκάτῃ κατὰ σελήνην ἐν κριῷ τοῦ ἡλίου καθεστῶτος, τούτῳ γὰρ τῷ μηνὶ τῆς ὑπʼ Αἰγυπτίους δουλείας ἠλευθερώθημεν, καὶ τὴν θυσίαν, ἣν τότʼ ἐξιόντας ἀπʼ Αἰγύπτου θῦσαι προεῖπον ἡμᾶς πάσχα λεγομένην, διʼ ἔτους ἑκάστου θύειν ἐνόμισεν, καὶ δὴ τελοῦμεν αὐτὴν κατὰ φατρίας μηδενὸς τῶν τεθυμένων εἰς τὴν ἐπιοῦσαν τηρουμένου."},{"number":249,"text":"πέμπτῃ δὲ καὶ δεκάτῃ διαδέχεται τὴν πάσχα ἡ τῶν ἀζύμων ἑορτὴ ἑπτὰ ἡμέρας οὖσα, καθʼ ἣν ἀζύμοις τρέφονται καὶ καθʼ ἑκάστην ἡμέραν ταῦροι σφάζονται δύο καὶ κριὸς μὲν εἷς ἑπτὰ δὲ ἄρνες. καὶ ταῦτα μὲν ὁλοκαυτεῖται προστιθεμένου τοῖς πᾶσι καὶ ἐρίφου ὑπὲρ ἁμαρτάδων εἰς εὐωχίαν κατὰ ἡμέραν ἑκάστην τοῖς ἱερεῦσιν."},{"number":250,"text":"τῇ δὲ δευτέρᾳ τῶν ἀζύμων ἡμέρᾳ, ἕκτη δʼ ἐστὶν αὕτη καὶ δεκάτη, τῶν καρπῶν οὓς ἐθέρισαν, οὐ γὰρ ἥψαντο πρότερον αὐτῶν, μεταλαμβάνουσι καὶ τὸν θεὸν ἡγούμενοι τιμᾶν δίκαιον εἶναι πρῶτον, παρʼ οὗ τῆς εὐπορίας τούτων ἔτυχον, τὰς ἀπαρχὰς αὐτῷ τῆς κριθῆς ἐπιφέρουσι τρόπον τοιοῦτον."},{"number":251,"text":"φρύξαντες τῶν ἀσταχύων τὸ δράγμα καὶ πτίσαντες καὶ καθαρὰς πρὸς ἄλεστον τὰς κριθὰς ποιήσαντες τῷ βωμῷ ἀσσαρῶνα προσφέρουσι τῷ θεῷ, καὶ μίαν ἐξ αὐτοῦ δράκα ἐπιβαλόντες τὸ λοιπὸν ἀφιᾶσιν εἰς χρῆσιν τοῖς ἱερεῦσι· καὶ τότε λοιπὸν δημοσίᾳ ἔξεστι πᾶσι καὶ ἰδίᾳ θερίζειν. θύουσι δʼ ἐπὶ ταῖς ἀπαρχαῖς τῶν καρπῶν ἀρνίον εἰς ὁλοκαύτωσιν τῷ θεῷ."},{"number":252,"text":"Ἑβδόμης ἑβδομάδος διαγεγενημένης μετὰ ταύτην τὴν θυσίαν, αὗται δʼ εἰσὶν αἱ τῶν ἑβδομάδων ἡμέραι τεσσαράκοντα καὶ ἐννέα, τῇ πεντηκοστῇ, ἣν Ἑβραῖοι ἀσαρθὰ καλοῦσι, σημαίνει δὲ τοῦτο πεντηκοστήν, καθʼ ἣν προσάγουσι τῷ θεῷ ἄρτον ἀλφίτων μὲν πυρίνων ἀσσαρῶνας δύο μετὰ ζύμης γεγονότων, θυμάτων δὲ ἄρνας δύο·"},{"number":253,"text":"ταῦτα μὲν γὰρ τῷ θεῷ προσάγειν νόμιμον μόνον, εἰς δὲ δεῖπνον τοῖς ἱερεῦσι σκευάζεται καὶ καταλιπεῖν οὐδέν ἐστιν ἐξ αὐτῶν εἰς τὴν ἐπιοῦσαν συγκεχωρημένον· ὁλοκαυτωθησομένους μόσχους τε θύουσι τρεῖς καὶ κριοὺς δύο καὶ ἄρνας τεσσαρεσκαίδεκα, ἐρίφους δὲ δύο ὑπὲρ ἁμαρτημάτων."},{"number":254,"text":"ἔστι δʼ οὐδεμία τῶν ἑορτῶν, καθʼ ἣν οὐχ ὁλοκαυτοῦσιν οὐδὲ τῶν πόνων τῶν ἐπὶ τοῖς ἔργοις ἄνεσιν οὐ διδόασιν, ἀλλʼ ἐν πάσαις νόμιμον τό τε τῆς θυσίας εἶδος καὶ τὸ τῆς ἀργίας ἀταλαίπωρον καὶ πρὸς εὐωχίαις εἰσὶ τεθυκότες."},{"number":255,"text":"Ἐκ μέντοι τοῦ κοινοῦ σῖτος ὀπτὸς ζύμης ἄμοιρος, ἀσσαρῶνες δʼ εἴκοσι καὶ τέσσαρες εἰς τοῦτο ἀναλοῦνται. ὀπτῶνται δὲ ἀνὰ δύο διαιρεθέντες μὲν τῇ πρὸ τοῦ σαββάτου, τῷ δὲ σαββάτῳ πρωῒ κομισθέντες ἐπὶ τῆς ἱερᾶς τραπέζης τίθενται κατὰ ἓξ εἰς ἀλλήλους τετραμμένοι."},{"number":256,"text":"δύο δὲ χρυσέων ὑπερκειμένων πινάκων λιβανωτοῦ γεμόντων διαμένουσιν ἕως τοῦ ἑτέρου σαββάτου· καὶ τότε μὲν ἀντʼ ἐκείνων ἄλλοι κομίζονται, οἱ δὲ τοῖς ἱερεῦσι πρὸς τροφὴν δίδονται, καὶ τοῦ λιβανωτοῦ θυμιωμένου ἐπὶ τῷ ἱερῷ πυρί, ἐφʼ ᾧ καὶ ὁλοκαυτοῦσι τὰ πάντα, λιβανωτὸς ὑπὲρ ἐκείνου ἄλλος ὑπὲρ τῶν ἄρτων προστίθεται."},{"number":257,"text":"θύει δʼ ὁ ἱερεὺς ἐκ τῶν ἰδίων ἀναλωμάτων, καὶ δὶς ἑκάστης ἡμέρας τοῦτο ποιεῖ, ἄλευρον ἐλαίῳ μεμαγμένον καὶ πεπηγὸς ὀπτήσει βραχείᾳ, καὶ εἷς μέν ἐστιν ἀσσάρων τοῦ ἀλεύρου, τούτου δὲ τὸ μὲν ἥμισυ τὸ πρωΐ, τὸ δʼ ἕτερον δείλης ἐπιφέρει τῷ πυρί. τὸν μὲν οὖν περὶ τούτων λόγον ἀκριβέστερον αὖθις δηλώσομεν, ἱκανὰ δέ μοι δοκεῖ καὶ νῦν περὶ αὐτῶν προειρῆσθαι."}],"11":[{"number":258,"text":"Μωυσῆς δὲ τοῦ Λευὶ τὴν φυλὴν τῆς πρὸς τὸν λαὸν κοινωνίας ὑπεξελόμενος ἱερὰν ἐσομένην ἥγνιζε πηγαίοις ὕδασι καὶ ἀενάοις καὶ θυσίαις, ἃς ἐπὶ τοῖς τοιούτοις νομίμους παρέχονται τῷ θεῷ, τήν τε σκηνὴν αὐτοῖς καὶ τὰ σκεύη τὰ ἱερὰ καὶ τὰ ἄλλʼ ὅσα πρὸς σκέπην τῆς σκηνῆς ἐπεποίητο παρέδωκεν, ὅπως ὑφηγουμένων τῶν ἱερέων ὑπηρετήσωσιν· ἤδη γὰρ τῷ θεῷ καθιέρωτο."},{"number":259,"text":"Καὶ περὶ τῶν ζῴων δὲ διέκρινεν ἕκαστον, ὅτι τρέφοιντο καὶ οὗ πάλιν ἀπεχόμενοι διατελοῖεν, περὶ ὧν ἐν οἷς ἂν ἡμῖν ἀφορμὴ τῆς γραφῆς γένηται διελευσόμεθα τὰς αἰτίας προστιθέντες, ἀφʼ ὧν κινηθεὶς τὰ μὲν αὐτῶν βρωτὰ ἡμῖν ἐκέλευσεν εἶναι, τῶν δὲ προσέταξεν ἀπέχεσθαι."},{"number":260,"text":"αἵματος μέντοι παντὸς εἰς τροφὴν ἀπηγόρευσε τὴν χρῆσιν ψυχὴν αὐτὸ καὶ πνεῦμα νομίζων, καὶ κρέως τοῦ τεθνηκότος αὐτομάτως ζῴου τὴν βρῶσιν διεκώλυσεν, ἐπίπλου τε καὶ στέατος αἰγείου καὶ προβατείου καὶ τοῦ τῶν βοῶν ἀπέχεσθαι προεῖπεν."},{"number":261,"text":"Ἀπήλασε δὲ τῆς πόλεως καὶ τοὺς λέπρᾳ τὰ σώματα κακωθέντας καὶ τοὺς περὶ τὴν γονὴν ῥεομένους καὶ τὰς γυναῖκας δʼ αἷς ἡ τῶν κατὰ φύσιν ἔκκρισις ἔπεισι μετέστησε πρὸς ἡμέραν ἑβδόμην, μεθʼ ἣν ὡς ἤδη καθαραῖς ἐνδημεῖν ἐφίησιν."},{"number":262,"text":"ὁμοίως δὲ καὶ τοῖς κηδεύσασι νεκρὸν μετὰ τοσαύτας ἡμέρας νόμιμον τὸ ἐνδημεῖν· τὸν δʼ ὑπὲρ τὸν ἀριθμὸν τούτων τῶν ἡμερῶν ἐνεχόμενον ἐν τῷ μιάσματι θύειν νόμιμον ἀμνάδας δύο, ὧν τὴν μὲν ἑτέραν καθαγνίζειν δεῖ, τὴν δʼ ἑτέραν οἱ ἱερεῖς λαμβάνουσιν."},{"number":263,"text":"ὁμοίως δὲ θύουσι καὶ περὶ τοῦ τὴν γονὴν ῥεομένου. ὃς δʼ ἂν κατὰ τοὺς ὕπνους ἀποκρίνῃ γονήν, καθεὶς αὑτὸν εἰς ὕδωρ ψυχρὸν ὁμοίως τοῖς κατὰ νόμον γυναικὶ πλησιάζουσιν ἐξουσίαν ἔχει."},{"number":264,"text":"τοὺς δὲ λεπροὺς εἰς τὸ παντελὲς ἐξήλασε τῆς πόλεως μηδενὶ συνδιαιτωμένους καὶ νεκροῦ μηδὲν διαφέροντας· ἂν δέ τις ἐξικετεύσας τὸν θεὸν ἀπολυθῇ τῆς νόσου καὶ τὴν ἐρρωμένην κομίσηται χρόαν, ὁ δὴ τοιοῦτος ποικίλαις ἀμείβεται θυσίαις τὸν θεόν, περὶ ὧν ὕστερον ἐροῦμεν."},{"number":265,"text":"Ὅθεν καὶ καταγελάσειεν ἄν τις τῶν λεγόντων Μωυσῆν λέπρᾳ κεκακωμένον αὐτόν τε ἀπʼ Αἰγύπτου φυγεῖν καὶ τῶν ἐκπεσόντων διὰ ταύτην τὴν αἰτίαν ἡγησάμενον εἰς τὴν Χαναναίαν ἀγαγεῖν αὐτούς."},{"number":266,"text":"εἰ γὰρ τοῦτʼ ἦν ἀληθές, οὐκ ἂν ἐπὶ τῇ αὑτοῦ Μωυσῆς ἀτιμίᾳ τοιαῦτʼ ἐνομοθέτησεν, οἷς εὔλογον ἦν αὐτὸν καὶ ἑτέρων εἰσηγουμένων ἀντειρηκέναι, καὶ ταῦτα παρὰ πολλοῖς ὄντων λεπρῶν ἔθνεσι καὶ τιμῆς ἀπολαυόντων, οὐ μόνον ὕβρεως καὶ φυγῆς ἀπηλλαγμένων, ἀλλὰ καὶ τὰς ἐπισημοτάτας στρατείας στρατευομένων καὶ τὰς πολιτικὰς ἀρχὰς πιστευομένων καὶ εἰς ἱερὰ καὶ ναοὺς ἐχόντων ἐξουσίαν εἰσιέναι·"},{"number":267,"text":"ὥστʼ οὐδὲν ἐκώλυε καὶ Μωυσῆν, εἰ τοιούτῳ τινὶ συμπτώματι περὶ τὴν χρόαν ἢ τὸ σὺν αὐτῷ πλῆθος ἠλάττωτο, νομοθετῆσαι περὶ αὐτῶν τὰ κάλλιστα καὶ μηδεμίαν τοιαύτην ὁρίσαι ζημίαν."},{"number":268,"text":"ἀλλὰ δῆλον μέν, ὡς ταῦτα περὶ ἡμῶν λέγουσιν ὑπὸ βασκανίας προαγόμενοι, Μωυσῆς δὲ τούτων καθαρὸς ὢν ἐν καθαροῖς τοῖς ὁμοφύλοις περὶ τῶν νενοσηκότων ἐνομοθέτει κατὰ τιμὴν τοῦ θεοῦ τοῦτο ποιῶν. ἀλλὰ περὶ μὲν τούτων ἕκαστος ὡς αὐτῷ δοκεῖ σκοπείτω."},{"number":269,"text":"Τὰς δὲ γυναῖκας ἐπειδὰν τέκωσιν εἰς τὸ ἱερὸν εἰσιέναι κεκώλυκε καὶ θυσιῶν ἅπτεσθαι μέχρι τεσσαράκοντα ἡμερῶν, ἂν ἄρρεν τὸ τεχθὲν ᾖ· διπλασίονας γὰρ εἶναι τὰς ἡμέρας ἐπὶ θηλυτοκίαις συμβέβηκεν. εἰσιοῦσαι μέντοι μετὰ τὴν προειρημένην προθεσμίαν θυσίας ἐπιτελοῦσιν, ἃς οἱ ἱερεῖς πρὸς τὸν θεὸν διανέμονται."},{"number":270,"text":"Ἂν δʼ ὑπονοήσῃ μεμοιχεῦσθαί τις αὐτῷ τὴν γυναῖκα, κομίζει κριθῆς ἀληλεσμένης ἀσσάρωνα, καὶ μίαν αὐτῆς δράκα ἐπιβαλόντες τῷ θεῷ τὸ λοιπὸν τοῖς ἱερεῦσι διδόασιν εἰς τροφήν. τὴν δὲ γυναῖκα στήσας τις τῶν ἱερέων κατὰ τὰς πύλας, αἱ δʼ εἰσὶ τετραμμέναι πρὸς τὸν νεών, καὶ τῆς κεφαλῆς τὸ ἱμάτιον ἀφελὼν ἐπιγράφει μὲν τοῦ θεοῦ τὴν προσηγορίαν διφθέρᾳ,"},{"number":271,"text":"κελεύει δὲ ὀμνύειν μηδὲν ἠδικηκέναι τὸν ἄνδρα, παραβᾶσαν δὲ τὸ σῶφρον τοῦ δεξιοῦ σκέλους ἔξαρθρον γενέσθαι καὶ τὴν γαστέρα πρησθεῖσαν οὕτως ἀποθανεῖν· ἂν δʼ ὑπὸ πολλοῦ τοῦ ἔρωτος καὶ τῆς διὰ τοῦτον ζηλοτυπίας προπετῶς ὁ ἀνὴρ διὰ τὴν ὑπόνοιαν εἴη κεκινημένος, μηνὶ δεκάτῳ γενέσθαι παιδίον ἄρρεν αὐτῇ."},{"number":272,"text":"τῶν δʼ ὅρκων τελειωθέντων τῆς διφθέρας ἀπαλείψας τοὔνομα εἰς φιάλην ἐκπιέζει, προκομίσας τε ἐκ τοῦ ἱεροῦ γῆς εἴ τι προστύχοι καὶ καταπάσας ἐκπιεῖν δίδωσιν· ἡ δʼ εἰ μὲν ἀδίκως ἐνεκλήθη, ἐγκύμων τε γίνεται καὶ τελεσφορεῖται κατὰ τὴν γαστέρα·"},{"number":273,"text":"ψευσαμένη δὲ τὸν ἄνδρα ἐπὶ τοῖς γάμοις καὶ τὸν θεὸν ἐπὶ τοῖς ὅρκοις μετʼ αἰσχύνης καταστρέφει τὸν βίον τοῦ τε σκέλους ἐκπεσόντος αὐτῇ καὶ τὴν κοιλίαν ὑδέρου καταλαβόντος. καὶ περὶ μὲν τῶν θυσιῶν καὶ τῆς ἁγνείας τῆς ἐπʼ αὐταῖς ταῦτα Μωυσῆς τοῖς ὁμοφύλοις προενόησε, νόμους δὲ αὐτοῖς τοιούτους ἔθετο."}],"12":[{"number":274,"text":"Μοιχείαν μὲν εἰς τὸ παντελὲς ἀπεῖπε νομίσας εὔδαιμον τὸ περὶ τοὺς γάμους ὑγιαίνειν τοὺς ἄνδρας, καὶ ταῖς τε πόλεσι καὶ τοῖς οἴκοις συμφέρειν τὸ τοὺς παῖδας εἶναι γνησίους. καὶ μίσγεσθαι δὲ μητράσι κακὸν μέγιστον ὁ νόμος ἀπεῖπεν, ὁμοίως δὲ καὶ πατρὸς συνεῖναι γαμετῇ καὶ τηθίσι καὶ ἀδελφαῖς καὶ παίδων γυναιξὶν ὡς ἔκφυλον ἔχον τὴν ἀδικίαν μεμίσηκεν."},{"number":275,"text":"ἐκώλυσε δὲ καὶ γυναικὶ μεμιασμένῃ τοῖς κατὰ φύσιν πλησιάζειν μηδὲ κτήνεσιν εἰς συνουσίαν φοιτᾶν μηδὲ τὴν πρὸς τὰ ἄρρενα μῖξιν τιμᾶν διὰ τὴν ἐπʼ αὐτοῖς ὥραν ἡδονὴν θηρωμένους παράνομον. κατὰ δὲ τῶν εἰς ταῦτʼ ἐξυβρισάντων θάνατον ὥρισε τὴν τιμωρίαν."},{"number":276,"text":"Τῶν δʼ ἱερέων καὶ διπλασίονα τὴν ἁγνείαν ἐποίησε· τούτων τε γὰρ αὐτοὺς ὁμοίως τοῖς ἄλλοις εἴργει καὶ προσέτι γαμεῖν τὰς ἡταιρηκυίας ἐκώλυσε, μήτε δούλην μήτʼ αἰχμάλωτον γαμεῖν αὐτοὺς κεκώλυκε καὶ τὰς ἐκ καπηλείας καὶ τοῦ πανδοκεύειν πεπορισμένας τὸν βίον μηδὲ τὰς τῶν προτέρων ἀνδρῶν ἐφʼ αἱσδηποτοῦν αἰτίαις ἀπηλλαγμένας."},{"number":277,"text":"τὸν ἀρχιερέα μέντοι οὐδὲ τεθνηκότος ἀνδρὸς ἠξίωσε γυναῖκα τοῦτο τοῖς ἄλλοις ἱερεῦσι συγχωρῶν, μόνην δʼ αὐτῷ δέδωκε γαμεῖν παρθένον καὶ ταύτην φυλάττειν· ὅθεν οὐδὲ νεκρῷ πρόσεισιν ὁ ἀρχιερεὺς τῶν λοιπῶν οὐ κεκωλυμένων ἀδελφοῖς καὶ γονεῦσι καὶ παισὶ τοῖς αὑτῶν προσιέναι μεταστᾶσιν."},{"number":278,"text":"ἀφελεῖς δὲ εἶναι πᾶσαν ἀφέλειαν· τὸν δὲ μὴ ὁλόκληρον τῶν ἱερέων νέμεσθαι πρὸς τοὺς ἱερεῖς ἐκέλευσε τὰ γέρα, ἀναβαίνειν δὲ ἐπὶ τὸν βωμὸν καὶ εἰσιέναι εἰς τὸν ναὸν ἐκώλυσε· μὴ μόνον δὲ περὶ τὰς ἱερουργίας καθαροὺς εἶναι, σπουδάζειν δὲ καὶ περὶ τὴν αὐτῶν δίαιταν, ὥστʼ αὐτὴν ἄμεμπτον εἶναι."},{"number":279,"text":"καὶ διὰ ταύτην τὴν αἰτίαν οἱ τὴν ἱερατικὴν στολὴν φοροῦντες ἄμωμοί τέ εἰσι καὶ περὶ πάντα καθαροὶ καὶ νηφάλιοι, πίνειν οἶνον ἕως οὗ τὴν στολὴν ἔχουσι κεκωλυμένοι· ἔτι δὲ καὶ τὰ ἱερεῖα θύουσιν ὁλόκληρα καὶ κατὰ μηδὲν λελωβημένα."},{"number":280,"text":"Ταῦτα μὲν οὖν ἤδη καὶ κατὰ τὸν ζωῆς χρόνον τῆς αὐτοῦ γινόμενα παρέδωκε Μωυσῆς, τῶν δὲ αὖθις καίπερ ἐπὶ τῆς ἐρημίας διαιτώμενος προενόησεν, ὅπως ἐπειδὰν τὴν Χαναναίαν λάβωσι τάδε ποιῶσι·"},{"number":281,"text":"διʼ ἑβδόμου ἔτους ἄνεσιν δίδωσι τῇ γῇ ἀπό τε ἀρότρου καὶ φυτείας, ὥσπερ καὶ αὐτοῖς διʼ ἑβδόμης ἡμέρας τὴν ἀπὸ τῶν ἔργων προεῖπεν ἀνάπαυσιν. καὶ τῶν αὐτομάτως ἀναδοθέντων ἀπὸ τῆς γῆς κοινὴν εἶναι τοῖς θέλουσι τὴν χρῆσιν τῶν τε ὁμοφύλων καὶ τῶν ἀλλοτριοχώρων, μηδὲν ἐξ αὐτῶν φυλάττοντας· ποιεῖν δὲ τοῦτο καὶ μεθʼ ἑβδόμην ἐτῶν ἑβδομάδα."},{"number":282,"text":"ταῦτα πεντήκοντα μέν ἐστιν ἔτη τὰ πάντα, καλεῖται δὲ ὑπὸ Ἑβραίων ὁ πεντηκοστὸς ἐνιαυτὸς ἰώβηλος, ἐν ᾧ οἵ τε χρεῶσται τῶν δανείων ἀπολύονται καὶ οἱ δουλεύοντες ἐλεύθεροι ἀφίενται, οὓς ὄντας ὁμοφύλους καὶ παραβάντας τι τῶν νομίμων τῷ σχήματι τῆς δουλείας ἐκόλασε θάνατον οὐκ ἐκδεχομένους."},{"number":283,"text":"ἀποδίδωσι δὲ καὶ τοὺς ἀγροὺς τοῖς ἀρχῆθεν αὐτῶν δεσπόταις τοῦτον τὸν τρόπον· ἐνστάντος τοῦ ἰωβήλου, ἐλευθερίαν σημαίνει τοὔνομα, συνέρχονται ὅ τε ἀποδόμενος τὸ χωρίον καὶ ὁ πριάμενος, καὶ λογισάμενοι τοὺς καρποὺς καὶ τὰς εἰς τὸ χωρίον δαπάνας γεγενημένας τῶν μὲν καρπῶν πλεονάζειν εὑρεθέντων προσδέχεται τὸν ἀγρὸν ὁ ἀποδόμενος,"},{"number":284,"text":"τοῦ δʼ ἀναλώματος ὑπερβάλλοντος ὑπὲρ τοῦ λείποντος καταβαλὼν τὸ ἱκνούμενον ἐξέχεται τῆς κτήσεως, ἴσων δὲ συναριθμουμένων τῶν τε καρπῶν καὶ τῶν ἀναλωμάτων ἀποδίδωσι τοῖς καὶ πρότερον νεμηθεῖσι."},{"number":285,"text":"τὸ αὐτὸ δὲ καὶ ἐπὶ ταῖς οἰκίαις νόμιμον ἰσχύειν ἠθέλησε ταῖς κατὰ κώμας πεπραμέναις· περὶ γὰρ τῶν ἐν τῇ πόλει πεπραμένων ἔγνωκεν ἑτέρως. εἰ μὲν γὰρ πρὸ τοῦ τελειωθῆναι τὸν ἐνιαυτὸν καταβάλοι τὸ ἀργύριον, ἀναγκάζει τὸν πριάμενον ἀποδοῦναι, εἰ δὲ πλῆρες γένοιτο τὸ ἔτος, βεβαιοῖ τὴν κτῆσιν τῷ πριαμένῳ."},{"number":286,"text":"ταύτην Μωυσῆς τὴν διάταξιν τῶν νόμων, ὅθʼ ὑπὸ τὸ Σιναῖον καθιδρύκει τὴν στρατιάν, ἐξέμαθε παρὰ τοῦ θεοῦ καὶ τοῖς Ἑβραίοις γεγραμμένην παραδίδωσιν."},{"number":287,"text":"Ἐπειδὴ δὲ καλῶς αὐτῷ τὰ περὶ τὴν νομοθεσίαν ἔχειν ἐδόκει, πρὸς ἐξέτασιν τοῦ στρατοῦ τὸ λοιπὸν ἐτράπη τῶν πολεμικῶν ἤδη κατὰ νοῦν ἔχων ἅπτεσθαι, προστάσσει τε τοῖς φυλάρχοις πλὴν τῆς Λευίτιδος φυλῆς ἀκριβῶς τὸν ἀριθμὸν ἐκμαθεῖν τῶν στρατεύεσθαι δυναμένων· ἱεροὶ γὰρ ἦσαν οἱ Λευῖται καὶ πάντων ἀτελεῖς."},{"number":288,"text":"γενομένης δὲ τῆς ἐξετάσεως εὑρέθησαν μυριάδες ἑξήκοντα τῶν ὁπλιτεύειν δυναμένων ὄντων ἀπὸ εἴκοσι ἐτῶν ἕως πεντήκοντα καὶ τρισχίλιοι πρὸς ἑξακοσίοις καὶ πεντήκοντα. ἀντὶ δὲ Λευὶ κατέλεξεν εἰς τοὺς φυλάρχους Μανασσῆν τὸν Ἰωσήπου παῖδα καὶ Ἐφράην ἀντὶ τοῦ Ἰωσήπου· δέησις δὲ ἦν αὕτη Ἰακώβου πρὸς Ἰώσηπον ποιητοὺς αὐτῷ παρασχεῖν τοὺς παῖδας, ὡς καὶ προεῖπον."},{"number":289,"text":"Πηγνύντες δὲ τὴν σκηνὴν μέσην ἀπελάμβανον τριῶν φυλῶν κατὰ πλευρὰν ἑκάστην παρασκηνουμένων· ὁδοὶ δὲ διὰ μέσων ἐτέτμηντο, καὶ κόσμος ἦν ἀγορᾶς, καὶ τῶν πωλουμένων ἕκαστον ἐν τάξει διέκειτο, καὶ δημιουργοὶ τέχνης ἁπάσης ἐν τοῖς ἐργαστηρίοις ἦσαν, οὐδενί τε ἄλλῳ ἢ πόλει μετανισταμένῃ καὶ καθιδρυμένῃ ἐῴκει."},{"number":290,"text":"τὰ δὲ περὶ τὴν σκηνὴν πρῶτοι μὲν οἱ ἱερεῖς κατεῖχον, ἔπειτα δὲ οἱ Λευῖται πάντες ὄντες τὸ πλῆθος, ἐξητάσθησαν γὰρ καὶ αὐτοὶ τοῦ μὲν ἄρρενος ὅσον τριακοστὴν εἶχεν ἡμέραν γενόμενον, δισμύριοι καὶ δισχίλιοι πρὸς τοῖς ὀκτακοσίοις ὀγδοήκοντα. καὶ ἐφʼ ὅσον μὲν ὑπὲρ τὴν σκηνὴν συνέβαινεν ἑστάναι τὴν νεφέλην, μένειν αὐτοῖς ὡς ἐπιδημοῦντος ἐδόκει τοῦ θεοῦ, τρεπομένης δὲ ταύτης μετανίστασθαι."},{"number":291,"text":"Εὗρε δὲ καὶ βυκάνης τρόπον ἐξ ἀργύρου ποιησάμενος, ἔστι δὲ τοιαύτη· μῆκος μὲν ἔχει πηχυαῖον ὀλίγῳ λεῖπον, στενὴ δʼ ἐστὶ σύριγξ αὐλοῦ βραχεῖ παχυτέρα, παρέχουσα δὲ εὖρος ἀρκοῦν ἐπὶ τῷ στόματι πρὸς ὑποδοχὴν πνεύματος εἰς κώδωνα ταῖς σάλπιγξι παραπλησίως τελοῦντα· ἀσώσρα καλεῖται κατὰ τὴν Ἑβραίων γλῶσσαν."},{"number":292,"text":"γίνονται δὲ δύο, καὶ τῇ μὲν ἑτέρᾳ πρὸς παρακέλευσιν καὶ συλλογὴν ἐχρῶντο τοῦ πλήθους εἰς τὰς ἐκκλησίας· καὶ μιᾷ μὲν ἀποσημάναντος ἔδει τὰς ἀρχὰς συνελθεῖν σκεψομένας περὶ τῶν οἰκείων, ἀμφοτέραις δὲ συνῆγε τὸ πλῆθος."},{"number":293,"text":"τῆς δὲ σκηνῆς μετακινουμένης ταῦτα ἐγίνετο· ἀποσημήναντος γὰρ τὸ πρῶτον οἱ παρὰ ταῖς ἀνατολαῖς ἐσκηνωκότες ἀνίσταντο, καὶ πρὸς τὴν δευτέραν οἱ πρὸς τὸν νότον αὖθις καθεστῶτες. εἶθʼ ἡ σκηνὴ λυομένη μέση τῶν προϊουσῶν ἓξ φυλῶν ἐκομίζετο καὶ τῶν ἑπομένων ἕξ, Λευῖται δὲ περὶ τὴν σκηνὴν πάντες ἦσαν."},{"number":294,"text":"τρίτον δὲ σημήναντος τὸ κατὰ λίβα τετραμμένον τῶν ἐσκηνωκότων μέρος ἐκινεῖτο, καὶ τέταρτον τὸ κατὰ βορρᾶν. ταῖς δὲ βυκάναις ἐχρῶντο καὶ ἐπὶ ταῖς ἱερουργίαις προσάγοντες τὰς θυσίας καὶ τοῖς σαββάτοις καὶ ταῖς λοιπαῖς ἡμέραις. θύει δὲ τότε πρῶτον μετὰ τὴν ἀναχώρησιν τὴν ἐξ Αἰγύπτου τὴν πάσχα λεγομένην ἐπὶ τῆς ἐρήμου."}],"13":[{"number":295,"text":"Καὶ βραχὺ διαλιπὼν ἀπανίσταται τοῦ Σιναίου ὄρους καὶ τόπους τινὰς ἀμείψας, περὶ ὧν δηλώσομεν, εἴς τι χωρίον Ἐσερμὼθ λεγόμενον παρῆν, κἀκεῖ τὸ πλῆθος πάλιν στασιάζειν ἄρχεται, καὶ τὸν Μωυσῆν αἰτιᾶσθαι τῶν τε κατὰ τὴν ἀποδημίαν αὐτῷ πεπειραμένων,"},{"number":296,"text":"καὶ ὅτι γῆς ἀγαθῆς αὐτοὺς πείσαντος ἀπαναστῆναι τὴν μὲν ἀπολέσειαν, ἀντὶ δὲ ἧς ὑπέσχετο παρέξειν εὐδαιμονίας ἐν ταύταις ἀλῶνται ταῖς ταλαιπωρίαις, ὕδατος μὲν σπανίζοντες, εἰ δὲ καὶ τὴν μάνναν ἐπιλιπεῖν συμβαίη τέλεον ἀπολούμενοι."},{"number":297,"text":"πολλὰ δὲ εἰς τὸν ἄνδρα καὶ δεινὰ λεγόντων, εἷς δέ τις αὐτοῖς παρῄνει, μήτε Μωυσέος καὶ τῶν πεπονημένων αὐτῷ περὶ τῆς κοινῆς σωτηρίας ἀμνημονεῖν μήτʼ ἀπογινώσκειν τῆς τοῦ θεοῦ βοηθείας. τὸ δὲ πλῆθος πρὸς τοῦτο μᾶλλον ἐκινήθη καὶ θορυβῆσαν ἔτι μᾶλλον πρὸς τὸν Μωυσῆν ἐπετείνετο."},{"number":298,"text":"Μωυσῆς δὲ παραθαρσύνων αὐτοὺς οὕτως ἀπεγνωκότας ὑπέσχετο καίπερ αἰσχρῶς ὑπʼ αὐτῶν περιυβρισμένος πλῆθος αὐτοῖς παρέξειν κρεῶν οὐκ εἰς μίαν ἡμέραν ἀλλʼ εἰς πλείονας. ἀπιστούντων δʼ ἐπὶ τούτῳ καί τινος ἐρομένου, πόθεν ἂν τοσαύταις εὐπορήσειε μυριάσι τῶν προειρημένων, ὁ θεός, εἶπε, κἀγὼ καί τοι κακῶς ἀκούοντες πρὸς ὑμῶν οὐκ ἂν ἀποσταίημεν κάμνοντες ὑπὲρ ὑμῶν, καὶ ταῦτα οὐκ εἰς μακρὰν ἔσται."},{"number":299,"text":"ἅμα ταῦτʼ ἔλεγε καὶ πίμπλαται τὸ στρατόπεδον ὀρτύγων ἅπαν καὶ ἤθροιζον αὐτοὺς περιστάντες. ὁ μέντοι θεὸς οὐκ εἰς μακρὰν μετέρχεται τοὺς Ἑβραίους τῆς εἰς αὐτὸν θρασύτητος καὶ λοιδορίας· ἀπέθανε γὰρ οὐκ ὀλίγον πλῆθος αὐτῶν, καὶ νῦν ἔτι κατʼ ἐπωνυμίαν ὁ χῶρος ὀνομάζεται Καβρωθαβά, ἐπιθυμίας μνημεῖα λέγοιτο ἄν."}],"14":[{"number":300,"text":"Ἀναγαγὼν δὲ αὐτοὺς ἐκεῖθεν ὁ Μωυσῆς εἰς τὴν καλουμένην Φάραγγα πλησίον οὖσαν τοῖς Χαναναίων ὁρίοις καὶ χαλεπὴν ἐνδιαιτᾶσθαι εἰς ἐκκλησίαν ἀθροίζει τὸ πλῆθος καὶ καταστάς, δύο, φησί, τοῦ θεοῦ κρίναντος ἡμῖν παρασχεῖν ἀγαθά, ἐλευθερίαν καὶ γῆς κτῆσιν εὐδαίμονος, τὴν μὲν ἤδη δόντος ἔχετε, τὴν δὲ ἤδη λήψεσθε."},{"number":301,"text":"Χαναναίων γὰρ ἐπὶ τοῖς ὅροις καθήμεθα, καὶ κωλύσει τὸ λοιπὸν ἐπιόντας οὐ μόνον οὐ βασιλεὺς οὐ πόλις ἡμᾶς, ἀλλʼ οὐδὲ τὸ πᾶν ἀθροισθέντων ἔθνος. παρασκευαζώμεθα οὖν πρὸς τὸ ἔργον· οὐ γὰρ ἀμαχητὶ παραχωρήσουσιν ἡμῖν τῆς γῆς, ἀλλὰ μεγάλοις αὐτὴν ἀγῶσιν ἀφαιρεθέντες."},{"number":302,"text":"πέμψωμεν δὲ κατασκόπους, οἳ τῆσδε τῆς γῆς ἀρετὴν κατανοήσουσι καὶ πόση δύναμις αὐτοῖς. πρὸ δὲ πάντων ὁμονοῶμεν καὶ τὸν θεόν, ὅς ἐστιν ἐπὶ πᾶσιν ἡμῖν βοηθὸς καὶ σύμμαχος, διὰ τιμῆς ἔχωμεν."},{"number":303,"text":"Μωυσέος δὲ ταῦτʼ εἰπόντος τὸ πλῆθος αὐτὸν τιμαῖς ἀμείβεται, καὶ κατασκόπους αἱρεῖται δώδεκα τῶν γνωριμωτάτων ἐξ ἑκάστης φυλῆς ἕνα, οἳ διεξελθόντες ἀπὸ τῶν πρὸς Αἰγύπτῳ τὴν Χαναναίαν ἅπασαν ἐπί τε Ἀμάθην πόλιν καὶ Λίβανον ἀφικνοῦνται τὸ ὄρος, καὶ τήν τε τῆς γῆς φύσιν καὶ τὴν τῶν ἐνοικούντων ἀνθρώπων ἐξιστορήσαντες παρῆσαν τεσσαράκοντα ἡμέραις εἰς πᾶν καταχρησάμενοι τὸ ἔργον,"},{"number":304,"text":"ἔτι τε καρποὺς ὧν ἔφερεν ἡ γῆ κομίζοντες τῇ τε τούτων εὐπρεπείᾳ καὶ τῷ πλήθει τῶν ἀγαθῶν, ἃ τὴν γῆν ἔχειν διηγοῦντο, πολεμεῖν ἐπαίροντες τὸ πλῆθος, φοβοῦντες δὲ πάλιν αὐτὸ τῷ τῆς κτήσεως ἀπόρῳ ποταμούς τε διαβῆναι λέγοντες ἀδυνάτους ὑπὸ μεγέθους ἅμα καὶ βάθους καὶ ὄρη ἀμήχανα τοῖς ὁδεύουσι καὶ πόλεις καρτερὰς τείχεσι καὶ περιβόλων ὀχυρότητι·"},{"number":305,"text":"ἐν δʼ Ἐβρῶνι καὶ τῶν γιγάντων ἔφασκον τοὺς ἀπογόνους καταλαβεῖν. καὶ οἱ μὲν κατάσκοποι τεθεαμένοι πάντων οἷς μετὰ τὴν ἔξοδον τὴν ἀπʼ Αἰγύπτου ἐνέτυχον μείζω τὰ κατὰ τὴν Χαναναίαν αὐτοί τε κατεπλάγησαν καὶ τὸ πλῆθος οὕτως ἔχειν ἐπειρῶντο."},{"number":306,"text":"Οἱ δὲ ἄπορον ἐξ ὧν ἠκροάσαντο τὴν κτῆσιν τῆς γῆς ὑπελάμβανον καὶ διαλυθέντες ἐκ τῆς ἐκκλησίας σὺν γυναιξὶ καὶ παισὶν ὀλοφυρόμενοι διῆγον, ὡς οὐδὲν ἔργῳ τοῦ θεοῦ βοηθοῦντος λόγῳ δὲ μόνον ὑπισχνουμένου."},{"number":307,"text":"καὶ τὸν Μωυσῆν πάλιν ᾐτιῶντο καὶ κατεβόων αὐτοῦ καὶ τοῦ ἀδελφοῦ Ἀαρῶνος τοῦ ἀρχιερέως καὶ πονηρὰν μὲν καὶ μετὰ τῶν εἰς τοὺς ἄνδρας βλασφημιῶν διάγουσι τὴν νύκτα. πρωῒ δʼ εἰς τὴν ἐκκλησίαν συντρέχουσι, διʼ ἐννοίας ἔχοντες καταλεύσαντες τόν τε Μωυσῆν καὶ τὸν Ἀαρῶνα ἐπὶ τὴν Αἴγυπτον ὑποστρέφειν."},{"number":308,"text":"Τῶν δὲ κατασκόπων Ἰησοῦς τε ὁ Ναυήχου παῖς φυλῆς Ἐφραιμίτιδος καὶ Χάλεβος τῆς Ἰούδα φυλῆς φοβηθέντες χωροῦσιν εἰς μέσους καὶ τὸ πλῆθος κατεῖχον θαρσεῖν δεόμενοι καὶ μήτε ψευδολογίαν κατακρίνειν τοῦ θεοῦ μήτε πιστεύειν τοῖς ἐκ τοῦ μὴ τἀληθῆ περὶ τῶν Χαναναίων εἰρηκέναι καταπληξαμένοις, ἀλλὰ τοῖς ἐπὶ τὴν εὐδαιμονίαν καὶ τὴν κτῆσιν αὐτοὺς τῶν ἀγαθῶν παρορμῶσιν·"},{"number":309,"text":"οὔτε γὰρ τῶν ὀρῶν τὸ μέγεθος οὔτε τῶν ποταμῶν τὸ βάθος τοῖς ἀρετὴν ἠσκηκόσιν ἐμποδὼν στήσεσθαι πρὸς τὰ ἔργα καὶ ταῦτα τοῦ θεοῦ συμπροθυμουμένου καὶ ὑπερμαχοῦντος αὐτῶν. ἴωμεν οὖν, ἔφασαν, ἐπὶ τοὺς πολεμίους μηδὲν ἔχοντες διʼ ὑποψίας ἡγεμόνι τε τῷ θεῷ πεπιστευκότες καὶ ὁδηγοῦσιν ἡμῖν ἑπόμενοι."},{"number":310,"text":"καὶ οἱ μὲν ταῦτα λέγοντες ἐπεχείρουν τὴν ὀργὴν καταπραΰνειν τοῦ πλήθους, Μωυσῆς δὲ καὶ Ἀαρὼν πεσόντες ἐπὶ τὴν γῆν τὸν θεὸν ἱκέτευον οὐχ ὑπὲρ τῆς ἑαυτῶν σωτηρίας, ἀλλʼ ὅπως τῆς ἀμαθίας παύσῃ τὸ πλῆθος καὶ καταστήσῃ τὴν διάνοιαν αὐτῶν ὑπὸ τῆς ἀμηχανίας τοῦ παραστάντος αὐτοῖς πάθους τεταραγμένην, παρῆν δʼ ἡ νεφέλη καὶ στᾶσα ὑπὲρ τὴν σκηνὴν ἐσήμαινε τὴν ἐπιφάνειαν τοῦ θεοῦ."}],"15":[{"number":311,"text":"Μωυσῆς δὲ θαρρήσας πάρεισιν εἰς τὸ πλῆθος καὶ τὸν θεὸν ἐδήλου κινηθέντα ὑπὸ τῆς ὕβρεως αὑτῷ λήψεσθαι τιμωρίαν, οὐκ ἀξίαν μὲν τῶν ἁμαρτημάτων, οἵαν δὲ οἱ πατέρες ἐπὶ νουθεσίᾳ τοῖς τέκνοις ἐπιφέρουσι."},{"number":312,"text":"παρελθόντι γὰρ εἰς τὴν σκηνὴν αὐτῷ καὶ περὶ τῆς μελλούσης ὑπʼ αὐτῶν ἀπωλείας ἀποκλαιομένῳ τὸν θεὸν ὑπομνῆσαι μέν, ὅσα παθόντες ἐξ αὐτοῦ καὶ πηλίκων εὐεργεσιῶν μεταλαβόντες ἀχάριστοι πρὸς αὐτὸν γένοιντο, ὅτι τε τῇ νῦν τῶν κατασκόπων ὑπαχθέντες δειλίᾳ τοὺς ἐκείνων λόγους ἀληθεστέρους τῆς ὑποσχέσεως ἡγήσαντο τῆς αὐτοῦ."},{"number":313,"text":"καὶ διὰ ταύτην τὴν αἰτίαν οὐκ ἀπολεῖ μὲν ἅπαντας οὐδʼ ἐξαφανίσει τὸ γένος αὐτῶν, ὃ πάντων μᾶλλον ἀνθρώπων ἔσχε διὰ τιμῆς, τὴν μέντοι Χαναναίαν οὐ παρέξειν γῆν αὐτοῖς λαβεῖν οὐδὲ τὴν ἀπʼ αὐτῆς εὐδαιμονίαν,"},{"number":314,"text":"ἀνεστίους δὲ ποιήσειν καὶ ἀπόλιδας ἐπὶ τῆς ἐρημίας ἐπʼ ἔτη τεσσαράκοντα καταβιῶναι τῆς παρανομίας ποινὴν ταύτην ἐκτίνοντας· παισὶ μέντοι τοῖς ὑμετέροις παραδώσειν τὴν γῆν ὑπέσχετο κἀκείνους τῶν ἀγαθῶν, ὧν ἑαυτοῖς ὑπὸ ἀκρασίας ἐφθονήσατε μετασχεῖν, ποιήσειν δεσπότας."},{"number":315,"text":"Ταῦτα δὲ Μωυσέος κατὰ τὴν τοῦ θεοῦ γνώμην διαλεχθέντος ἐν λύπῃ καὶ συμφορᾷ τὸ πλῆθος ἐγένετο, καὶ τὸν Μωυσῆν παρεκάλει καταλλάκτην αὐτῶν γενέσθαι πρὸς τὸν θεὸν καὶ τῆς ἄλης τῆς κατὰ τὴν ἐρημίαν ἀπαλλάξαντα πόλεις αὐτοῖς παρασχεῖν. ὁ δʼ οὐκ ἔφασκε τὸν θεὸν τοιαύτην πεῖραν προσήσεσθαι, μὴ γὰρ κατὰ κουφότητα προαχθῆναι τὸν θεὸν ἀνθρωπίνην εἰς τὴν ὀργὴν τὴν πρὸς αὐτοὺς ἀλλὰ γνώμῃ καταψηφισάμενον αὐτῶν."},{"number":316,"text":"οὐ δεῖ δὲ ἀπιστεῖν, εἰ Μωυσῆς εἷς ἀνὴρ ὢν τοσαύτας μυριάδας ὀργιζομένας ἐπράυνε καὶ μετήγαγε πρὸς τὸ ἥμερον· ὁ γὰρ θεὸς αὐτῷ συμπαρὼν ἡττᾶσθαι τοῖς λόγοις αὐτοῦ τὸ πλῆθος παρεσκεύαζε, καὶ πολλάκις παρακούσαντες ἀσύμφορον ἑαυτοῖς τὴν ἀπείθειαν ἐπέγνωσαν ἐκ τοῦ συμφορᾷ περιπεσεῖν."},{"number":317,"text":"Θαυμαστὸς δὲ τῆς ἀρετῆς ὁ ἀνὴρ καὶ τῆς ἰσχύος τῆς τοῦ πιστεύεσθαι περὶ ὧν ἂν εἴπῃ οὐ παρʼ ὃν ἔζη χρόνον ὑπῆρξε μόνον, ἀλλὰ καὶ νῦν· ἔστι γοῦν οὐδεὶς Ἑβραίων, ὃς οὐχὶ καθάπερ παρόντος αὐτοῦ καὶ κολάσοντος ἂν ἀκοσμῇ πειθαρχεῖ τοῖς ὑπʼ αὐτοῦ νομοθετηθεῖσι, κἂν λαθεῖν δύνηται."},{"number":318,"text":"καὶ πολλὰ μὲν καὶ ἄλλα τεκμήρια τῆς ὑπὲρ ἄνθρωπόν ἐστι δυνάμεως αὐτοῦ, ἤδη δέ τινες καὶ τῶν ὑπὲρ Εὐφράτην μηνῶν ὁδὸν τεσσάρων ἐλθόντες κατὰ τιμὴν τοῦ παρʼ ἡμῖν ἱεροῦ μετὰ πολλῶν κινδύνων καὶ ἀναλωμάτων καὶ θύσαντες οὐκ ἴσχυσαν τῶν ἱερῶν μεταλαβεῖν Μωυσέος ἀπηγορευκότος ἐπί τινι τῶν οὐ νομιζομένων οὐδʼ ἐκ τῶν πατρίων ἡμῖν αὐτοῖς συντυχόντων."},{"number":319,"text":"καὶ οἱ μὲν μηδὲ θύσαντες, οἱ δὲ ἡμιέργους τὰς θυσίας καταλιπόντες, πολλοὶ δʼ οὐδʼ ἀρχὴν εἰσελθεῖν εἰς τὸ ἱερὸν δυνηθέντες ἀπίασιν ὑπακούειν τοῖς Μωυσέος προστάγμασι μᾶλλον ἢ ποιεῖν τὰ κατὰ βούλησιν τὴν ἑαυτῶν προτιμῶντες, καὶ τὸν ἐλέγξοντα περὶ τούτων αὐτοὺς οὐ δεδιότες, ἀλλὰ μόνον τὸ συνειδὸς ὑφορώμενοι."},{"number":320,"text":"οὕτως ἡ νομοθεσία τοῦ θεοῦ δοκοῦσα τὸν ἄνδρα πεποίηκε τῆς αὐτοῦ φύσεως κρείττονα νομίζεσθαι. οὐ μὴν ἀλλὰ καὶ τοῦδε τοῦ πολέμου μικρὸν ἔμπροσθεν Κλαυδίου Ῥωμαίων ἄρχοντος Ἰσμαήλου δὲ παρʼ ἡμῖν ἀρχιερέως ὄντος, καὶ λιμοῦ τὴν χώραν ἡμῶν καταλαβόντος, ὡς τεσσάρων δραχμῶν πωλεῖσθαι τὸν ἀσσάρωνα,"},{"number":321,"text":"κομισθέντος ἀλεύρου κατὰ τὴν ἑορτὴν τῶν ἀζύμων εἰς κόρους ἑβδομήκοντα, μέδιμνοι δὲ οὗτοι Σικελοὶ μέν εἰσιν εἷς καὶ τριακόσιοι Ἀττικοὶ δὲ τεσσαράκοντα εἷς, οὐδεὶς ἐτόλμησε τῶν ἱερέων κρίμνον ἓν φαγεῖν τοσαύτης ἀπορίας τὴν γῆν κατεχούσης, δεδιὼς τὸν νόμον καὶ τὴν ὀργήν, ἣν καὶ ἐπὶ ἀνεξελέγκτοις ἀεὶ τὸ θεῖον τοῖς ἀδικήμασιν ἔχει."},{"number":322,"text":"ὥστʼ οὐ δεῖ θαυμάζειν περὶ τῶν τότε πεπραγμένων, ὁπότε καὶ μέχρι τοῦ νῦν τὰ καταλειφθέντα ὑπὸ Μωυσέος γράμματα τηλικαύτην ἰσχὺν ἔχει, ὥστε καὶ τοὺς μισοῦντας ἡμᾶς ὁμολογεῖν, ὅτι καὶ τὴν πολιτείαν ἡμῖν ὁ καταστησάμενός ἐστι θεὸς διὰ Μωυσέος καὶ τῆς ἀρετῆς τῆς ἐκείνου. ἀλλὰ περὶ μὲν τούτων ὡς αὐτῷ τινι δοκεῖ διαλήψεται."}]},"count":322};a[4]={"book":4,"title":"Τάδε ἔνεστιν ἐν τῇ τετάρτῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"α. Ἑβραίων δίχα τῆς Μωυσέος γνώμης μάχη πρὸς Χαναναίους καὶ ἧττα.\n\nβ. στάσις Κορέου καὶ τοῦ πλήθους πρὸς Μωυσῆν καὶ τὸν ἀδελφὸν αὐτοῦ περὶ τῆς ἱερωσύνης.\n\nγ. τὰ συμβάντα τοῖς Ἑβραίοις ἐν τῇ ἐρήμῳ ἔτεσιν ὀκτὼ καὶ τριάκοντα.\n\nδ. ὡς Σηχῶνα καὶ Ὤγην τοὺς Ἀμορραίων βασιλεῖς νικήσας Μωυσῆς καὶ τὴν στρατιὰν ἅπασαν αὐτῶν διαφθείρας κατεκλήρωσεν αὐτῶν τὴν χώραν δυσὶ φυλαῖς καὶ ἡμισείᾳ τῶν Ἑβραίων.\n\nε. Μωυσέος πολιτεία καὶ πῶς ἐξ ἀνθρώπων ἠφανίσθη.\n\nπεριέχει ἡ βίβλος αὕτη χρόνον ἐτῶν τριάκοντα καὶ ὀκτώ."},"chapters":{"1":[{"number":1,"text":"Ἑβραίους δʼ ὁ κατὰ τὴν ἐρημίαν βίος ἀηδὴς καὶ χαλεπὸς ὢν ἐπόνει καὶ κωλύοντος τοῦ θεοῦ τῶν Χαναναίων πεῖραν λαμβάνειν· οὐ γὰρ ἠξίουν τοῖς Μωυσέος πειθαρχοῦντες λόγοις ἠρεμεῖν, ἀλλὰ καὶ δίχα τῆς παρʼ ἐκείνου προθυμίας κρατήσειν αὐτοὶ τῶν πολεμίων νομίζοντες κατηγόρουν μὲν αὐτοῦ καὶ πραγματεύεσθαι μένειν αὐτοὺς ἀπόρους ὑπενόουν, ἵνʼ ἀεὶ τῆς ἐξ αὐτοῦ βοηθείας δέωνται,"},{"number":2,"text":"πολεμεῖν δὲ τοῖς Χαναναίοις ὡρμήκεσαν λέγοντες τὸν θεὸν οὐχὶ Μωυσεῖ χαριζόμενον ἐπικουρεῖν αὐτοῖς, ἀλλὰ καὶ κοινῇ κηδόμενον αὐτῶν τοῦ ἔθνους διὰ τοὺς προγόνους ὧν ἐπετρόπευσε καὶ διὰ τὴν αὐτῶν ἀρετὴν πρότερόν τε παρασχεῖν τὴν ἐλευθερίαν καὶ νῦν βουλομένοις πονεῖν ἀεὶ παρέσεσθαι σύμμαχον·"},{"number":3,"text":"εἶναί τε καὶ κατʼ αὐτοὺς ἱκανοὶ κρατεῖν τῶν ἐθνῶν ἔφασκον, κἂν ἀπαλλοτριοῦν αὐτῶν Μωυσῆς ἐθελήσῃ τὸν θεόν· ὅλως τε συμφέρειν αὐτοῖς τὸ αὐτοκράτορσιν εἶναι, καὶ μὴ χαίροντας ἐπὶ τῷ τῆς παρʼ Αἰγυπτίων ἐξελθεῖν ὕβρεως Μωυσῆν τύραννον ἀνέχεσθαι καὶ ζῆν πρὸς τὴν τούτου βούλησιν ἐξαπατωμένους,"},{"number":4,"text":"ὅτι μόνῳ τὸ θεῖον αὐτῷ προδηλοῖ περὶ τῶν ἡμετέρων κατὰ τὴν πρὸς αὐτὸν εὔνοιαν, ὡς οὐχ ἁπάντων ἐκ τῆς Ἁβράμου γενεᾶς ὄντων, ἀλλʼ αἴτιον ἕνα τούτων τοῦ θεοῦ παρεσχηκότος εἰς τὸ πάντʼ αὐτὸν εἰδέναι τὰ μέλλοντα παρʼ αὐτοῦ μανθάνοντα·"},{"number":5,"text":"δόξειν τε συνετοὺς εἶναι τῆς ἀλαζονείας αὐτοῦ καταγνόντες καὶ τῷ θεῷ πιστεύσαντες κτήσασθαι γῆν ἣν αὐτοῖς ὑπέσχηται θελήσασιν, ἀλλὰ μὴ τῷ διὰ τὴν αἰτίαν ταύτην ἐπʼ ὀνόματι τοῦ θεοῦ κωλύοντι προσσχοῖεν."},{"number":6,"text":"τὴν ἀπορίαν οὖν λογιζόμενοι καὶ τὴν ἐρημίαν, ὑφʼ ἧς ἔτι ταύτην αὐτοῖς χείρω συνέβαινεν εἶναι δοκεῖν, ἐπὶ τὴν πρὸς τοὺς Χαναναίους μάχην ἦσαν ὡρμημένοι, τὸν θεὸν προστησάμενοι στρατηγὸν ἀλλʼ οὐχὶ τὴν παρὰ τοῦ νομοθέτου συνεργίαν περιμένοντες."},{"number":7,"text":"Ὡς οὖν ταῦτʼ ἄμεινον αὐτοῖς ἕξειν ἔκριναν καὶ τοῖς πολεμίοις ἐπῆλθον, οἱ μὲν οὐ καταπλαγέντες αὐτῶν τὴν ἔφοδον οὐδὲ τὴν πληθὺν γενναίως αὐτοὺς ἐδέξαντο, τῶν δὲ Ἑβραίων ἀποθνήσκουσί τε πολλοὶ καὶ τὸ λοιπὸν στράτευμα τῆς φάλαγγος αὐτῶν διαλυθείσης ἀκόσμως διωκόμενον εἰς τὴν παρεμβολὴν συνέφυγε,"},{"number":8,"text":"καὶ τῷ παρʼ ἐλπίδας ἀτυχῆσαι παντάπασιν ἀθυμοῦν οὐδὲν ἔτι χρηστὸν προσεδόκα λογιζόμενον, ὅτι καὶ ταῦτα κατὰ μῆνιν θεοῦ πάθοιεν προεξορμήσαντες ἐπὶ τὸν πόλεμον τῆς ἐκείνου βουλήσεως."},{"number":9,"text":"Μωυσῆς δὲ τοὺς μὲν οἰκείους ὁρῶν ὑπὸ τῆς ἥττης καταπεπληγότας, φοβούμενος δὲ μὴ θαρσήσαντες ἐπὶ τῇ νίκῃ οἱ πολέμιοι καὶ μειζόνων ὀρεχθέντες ἐπʼ αὐτοὺς ἔλθοιεν, ἔγνω δεῖν τὴν στρατιὰν ἀπαγαγεῖν πορρωτέρω τῶν Χαναναίων εἰς τὴν ἔρημον."},{"number":10,"text":"καὶ τοῦ πλήθους ἐπιτρέψαντος ἑαυτὸ πάλιν ἐκείνῳ, συνῆκε γὰρ δίχα τῆς αὐτοῦ προνοίας οὐ δυνησόμενον ἐρρῶσθαι τοῖς πράγμασιν, ἀναστήσας τὸ στράτευμα προῆλθεν εἰς τὴν ἔρημον, ἐνταῦθα νομίζων ἡσυχάσειν αὐτοὺς καὶ μὴ πρότερον τοῖς Χαναναίοις εἰς χεῖρας ἥξειν πρὶν ἢ παρὰ τοῦ θεοῦ τὸν εἰς τοῦτο καιρὸν λάβωσιν."}],"2":[{"number":11,"text":"Ὅπερ δὲ τοῖς μεγάλοις συμβαίνει στρατοπέδοις καὶ μάλιστα παρὰ τὰς κακοπραγίας δυσάρκτοις εἶναι καὶ δυσπειθέσι, τοῦτο καὶ τοῖς Ἰουδαίοις συνέπεσεν· ἑξήκοντα γὰρ ὄντες μυριάδες καὶ διὰ τὸ πλῆθος ἴσως ἂν μηδʼ ἐν ἀγαθοῖς ὑποταγέντες τοῖς κρείττοσι, τότε μᾶλλον ὑπὸ τῆς ἀπορίας καὶ συμφορᾶς ἐξηγανάκτουν καὶ πρὸς ἀλλήλους καὶ πρὸς τὸν ἡγεμόνα."},{"number":12,"text":"στάσις οὖν αὐτοὺς οἵαν ἴσμεν οὔτε παρʼ Ἕλλησιν οὔτε παρὰ βαρβάροις γενομένην κατέλαβεν, ὑφʼ ἧς ἅπαντας ἀπολέσθαι κινδυνεύσαντας ἔσωσε Μωυσῆς οὐ μνησικακῶν, ὅτι παρʼ ὀλίγον ἦλθε καταλευσθεὶς ὑπʼ αὐτῶν ἀποθανεῖν."},{"number":13,"text":"οὐδʼ ὁ θεὸς δὲ ἠμέλησε τοῦ μηδὲν αὐτοὺς παθεῖν τῶν δεινῶν, ἀλλὰ καίπερ εἰς τὸν νομοθέτην αὐτῶν ἐξυβρισάντων καὶ τὰς ἐντολάς, ἃς αὐτὸς διὰ Μωυσέος αὐτοῖς ἐπέστειλεν, ἐρρύσατο τῶν ἐκ τοῦ στασιάζειν αὐτοῖς ἂν γενομένων δεινῶν, εἰ μὴ προενόησε. τήν τε οὖν στάσιν καὶ ὅσα μετʼ αὐτὴν Μωυσῆς ἐπολιτεύσατο διηγήσομαι προδιελθὼν τὴν αἰτίαν ἀφʼ ἧς ἐγένετο."},{"number":14,"text":"Κορῆς τις Ἑβραίων ἐν τοῖς μάλιστα καὶ γένει καὶ πλούτῳ διαφόρων ἱκανὸς δʼ εἰπεῖν καὶ δήμοις ὁμιλεῖν πιθανώτατος, ὁρῶν ἐν ὑπερβαλλούσῃ τιμῇ τὸν Μωυσῆν καθεστῶτα χαλεπῶς εἶχεν ὑπὸ φθόνου, καὶ γὰρ φυλέτης ὢν ἐτύγχανεν αὐτοῦ καὶ συγγενής, ἀχθόμενος ὅτι ταύτης τῆς δόξης δικαιότερον ἂν τῷ πλουτεῖν ἐκείνου μᾶλλον μὴ χείρων ὢν κατὰ γένος αὐτὸς ἀπέλαυε."},{"number":15,"text":"παρά τε τοῖς Λευίταις, φυλέται δʼ ἦσαν, καὶ μάλιστα παρὰ τοῖς συγγενέσι κατεβόα δεινὸν εἶναι λέγων Μωυσῆν δόξαν αὑτῷ θηρώμενον κατασκευάσαι καὶ κακουργοῦντα κτήσασθαι ταύτην ἐπὶ προφάσει τοῦ θεοῦ περιορᾶν, παρὰ τοὺς νόμους μὲν τἀδελφῷ τὴν ἱερωσύνην Ἀαρῶνι δόντα, μὴ τῷ κοινῷ δόγματι τοῦ πλήθους ἀλλʼ αὐτοῦ ψηφισαμένου,"},{"number":16,"text":"τυράννων δὲ τρόπῳ καταχαριζομένου τὰς τιμὰς οἷς ἂν ἐθελήσῃ χαλεπώτερον ἤδη τυγχάνειν τοῦ βιάζεσθαι τό τε λεληθότως ἐξυβρίζειν, ὅτι μὴ μόνον ἄκοντας μηδὲ συνιέντας τῆς ἐπιβουλῆς τὴν ἰσχὺν ἀφαιρεῖται·"},{"number":17,"text":"ὅστις γὰρ αὐτῷ σύνοιδεν ὄντι λαβεῖν ἀξίῳ πείθει τυγχάνειν αὐτὸν καὶ τότε βιάσασθαι μὴ θρασυνόμενος, οἷς δὲ ἄπορον ἐκ τοῦ δικαίου τιμᾶσθαι, βίαν μὲν ἀγαθοὶ βουλόμενοι δοκεῖν οὐ προσφέρουσι, τέχνῃ δʼ εἶναι κακουργοῦσι δυνατοί."},{"number":18,"text":"συμφέρειν δὲ τῷ πλήθει τοὺς τοιούτους ἔτι λανθάνειν οἰομένους κολάζειν καὶ μὴ παρελθεῖν εἰς δύναμιν ἐάσαντας φανεροὺς ἔχειν πολεμίους. τίνα γὰρ καὶ λόγον ἀποδοῦναι δυνάμενος Μωυσῆς Ἀαρῶνι καὶ τοῖς υἱέσιν αὐτοῦ τὴν ἱερωσύνην παρέδωκεν;"},{"number":19,"text":"εἰ μὲν γὰρ ἐκ τῆς Λευίτιδος φυλῆς τὴν τιμὴν ὁ θεός τινι παρασχεῖν ἔκρινεν, ἐγὼ ταύτης δικαιότερος τυγχάνειν γένει μὲν ὁ αὐτὸς ὢν Μωυσεῖ, πλούτῳ δὲ καὶ ἡλικίᾳ διαφέρων· εἰ δὲ τῇ πρεσβυτάτῃ τῶν φυλῶν, εἰκότως ἂν ἡ Ῥουβήλου τὴν τιμὴν ἔχοι λαμβανόντων αὐτὴν Δαθάμου καὶ Ἀβιράμου καὶ Φαλαοῦς· πρεσβύτατοι γὰρ οὗτοι τῶν ταύτην τὴν φυλὴν νεμομένων καὶ δυνατοὶ χρημάτων περιουσίᾳ."},{"number":20,"text":"Ἐβούλετο μὲν οὖν ταῦτα λέγων ὁ Κορῆς τοῦ κοινοῦ προνοεῖσθαι δοκεῖν, ἔργῳ δὲ εἰς ἑαυτὸν ἐπραγματεύετο τὴν παρὰ τοῦ πλήθους τιμὴν μεταστῆσαι. καὶ ὁ μὲν ταῦτα κακοήθως μετʼ εὐπρεπείας πρὸς τοὺς φυλέτας ἔλεγε."},{"number":21,"text":"προϊόντος δʼ εἰς τοὺς πλείονας κατʼ ὀλίγον τοῦ λόγου καὶ τῶν ἀκροωμένων προστιθεμένων ταῖς κατὰ Ἀαρῶνος διαβολαῖς ἀναπίμπλαται τούτων ἅπας ὁ στρατός. ἦσαν δὲ οἱ συντεταγμένοι τῷ Κορῇ πεντήκοντα καὶ διακόσιοι τῶν πρώτων ἄνδρες σπεύδοντες ἀφελέσθαι τὴν ἱερωσύνην τὸν Μωυσέος ἀδελφὸν καὶ τοῦτον αὐτὸν ἀτιμοῦν."},{"number":22,"text":"ἀνηρέθιστο δὲ καὶ τὸ πλῆθος καὶ βάλλειν τὸν Μωυσῆν ὡρμήκεσαν, εἴς τε ἐκκλησίαν ἀκόσμως μετὰ θορύβου καὶ ταραχῆς συνελέγοντο, καὶ πρὸ τῆς σκηνῆς τοῦ θεοῦ στάντες ἐβόων ἥκειν τὸν τύραννον καὶ τῆς ἀπʼ αὐτοῦ δουλείας ἀπηλλάχθαι τὸ πλῆθος, τῇ τοῦ θεοῦ προφάσει βίαια προστάγματα κελεύοντος·"},{"number":23,"text":"τὸν γὰρ θεόν, εἴπερ αὐτὸς ἦν ὁ τὸν ἱερωσόμενον ἐκλεγόμενος, τὸν ἄξιον ἂν εἰς τὴν τιμὴν παράγειν, οὐχὶ τοῖς πολλῶν ὑποδεεστέροις ταύτην φέροντα προσνεῖμαι, κρίνοντά τε παρασχεῖν Ἀαρῶνι ταύτην ἐπὶ τῷ πλήθει ποιήσασθαι τὴν δόσιν, ἀλλʼ οὐκ ἐπὶ τἀδελφῷ καταλιπεῖν."},{"number":24,"text":"Μωυσῆς δὲ τὴν Κορέου διαβολὴν ἐκ πολλοῦ προειδὼς καὶ τὸν λαὸν παροξυνόμενον ἰδὼν οὐκ ἔδεισεν, ἀλλὰ θαρρῶν οἷς περὶ τῶν πραγμάτων καλῶς ἐβουλεύετο καὶ τὸν ἀδελφὸν εἰδὼς κατὰ τὴν τοῦ θεοῦ προαίρεσιν τῆς ἱερωσύνης τυχεῖν, ἀλλʼ οὐ κατὰ τὴν αὐτοῦ χάριν, ἧκεν εἰς τὴν ἐκκλησίαν."},{"number":25,"text":"καὶ πρὸς μὲν τὸ πλῆθος οὐδένα ἐποιήσατο λόγον, πρὸς δὲ τὸν Κορῆ βοῶν ἐφʼ ὅσον ἐδύνατο, δεξιὸς ὢν καὶ κατὰ τἆλλα καὶ πλήθεσιν ὁμιλεῖν εὐφυής, ἐμοί, φησίν, ὦ Κορῆ, καὶ σὺ καὶ τούτων ἕκαστος, ἀπεδήλου δὲ τοὺς πεντήκοντα καὶ διακοσίους ἄνδρας, τιμῆς ἄξιοι δοκεῖτε, καὶ τὸν ὅμιλον δὲ πάντα τῆς ὁμοίας οὐκ ἀποστερῶ τιμῆς, κἂν ὑστερῶσιν ὧν ὑμῖν ἐκ πλούτου καὶ τῆς ἄλλης ἀξιώσεως ὑπάρχει."},{"number":26,"text":"καὶ νῦν Ἀαρῶνι τὴν ἱερωσύνην οὐκ ἐπειδὴ πλούτῳ προεῖχε, σὺ γὰρ καὶ ἀμφοτέρους ἡμᾶς μεγέθει χρημάτων ὑπερβάλλεις, οὐ μὴν οὐδʼ εὐγενείᾳ, κοινὸν γὰρ ἡμῖν τοῦτο ἐποίησεν ὁ θεὸς τὸν αὐτὸν δοὺς προπάτορα, οὐδὲ διὰ φιλαδελφίαν ὃ δικαίως ἂν ἕτερος εἶχε τοῦτο φέρων ἔδωκα τἀδελφῷ·"},{"number":27,"text":"καὶ γὰρ εἰ μὴ φροντίζων τοῦ θεοῦ καὶ τῶν νόμων τὴν τιμὴν ἐχαριζόμην, οὐκ ἂν ἐμαυτῷ παρεὶς δοῦναι παρέσχον ἑτέρῳ συγγενέστερος ὢν ἐμαυτῷ τἀδελφοῦ, καὶ πρὸς ἐμαυτὸν οἰκειότερον ἢ πρὸς ἐκεῖνον διακείμενος· καὶ γὰρ οὐδὲ συνετὸν ἦν τοῖς κινδύνοις ἐμαυτὸν ὑποτιθέντα τοῖς ἐκ τοῦ παρανομεῖν ἄλλῳ τὴν διὰ τούτου εὐδαιμονίαν χαρίζεσθαι."},{"number":28,"text":"ἀλλʼ ἐγώ τε κρείττων ἢ κακουργεῖν ὅ τε θεὸς οὐκ ἂν περιεῖδεν ἑαυτὸν καταφρονούμενον οὐδʼ ὑμᾶς ἀγνοοῦντας ὅτι καὶ ποιοῦντες αὐτῷ χαρίζεσθε, ἀλλʼ αὐτὸς ἐπιλεξάμενος τὸν ἱερωσόμενον αὐτῷ τῆς κατὰ τοῦτʼ αἰτίας ἡμᾶς ἠλευθέρωσεν."},{"number":29,"text":"οὐ μὴν ἐξ ἐμῆς χάριτος λαβεῖν ἀλλὰ μὴ κατὰ κρίσιν θεοῦ, κατατίθησιν αὐτὴν εἰς μέσον ἐπιδικάσιμον τοῖς βουλομένοις, οὐκ ἐκ τοῦ προκριθεὶς ἤδη τυχεῖν αὐτῆς ἀξιῶν ἐπιτραπῆναι καὶ τοῦτο νῦν αὐτῷ συγχωρηθῆναι περὶ αὐτῆς σπουδάσαι,"},{"number":30,"text":"προτιμῶν τοῦ τὸ γέρας ἔχειν τὸ μὴ στασιάζοντας ὑμᾶς ὁρᾶν καί τοι κατὰ τὴν ὑμετέραν γνώμην αὐτοῦ τυγχάνων· ὃ γὰρ ἔδωκεν ὁ θεὸς οὐχ ἡμάρτομεν τοῦτο καὶ μὴ βουλομένων ὑμῶν λαμβάνοντες."},{"number":31,"text":"ἦν δὲ καὶ τὸ μὴ προσέσθαι παρέχοντος ἐκείνου τὴν τιμὴν ἀσεβές, καὶ πάλιν ἀξιοῦντʼ ἔχειν εἰς ἅπαντα χρόνον μὴ τὴν ἀσφάλειαν τὴν ἐπʼ αὐτῇ βεβαιοῦντος ἡμῖν τοῦ θεοῦ παντάπασιν ἀλόγιστον. κρινεῖ τοίνυν πάλιν αὐτός, τίνας βούλεται τὰς ὑπὲρ ἡμῶν αὐτῷ θυσίας ἐπιτελεῖν καὶ προεστάναι τῆς εὐσεβείας·"},{"number":32,"text":"ἄτοπον γὰρ Κορῆν ἐφιέμενον τῆς τιμῆς τὴν ἐξουσίαν τοῦ τίνι παράσχῃ ταύτην ἀφελέσθαι τὸν θεόν. τῆς οὖν στάσεως καὶ τῆς διὰ τοῦτο ταραχῆς παύσασθε, πρωῒ δὲ ὅσοι τῆς ἱερωσύνης ἀντιποιεῖσθε κομίζων ἕκαστος θυμιατήριον οἴκοθεν σὺν θυμιάμασι καὶ πῦρ πάριτε."},{"number":33,"text":"καὶ σὺ δέ, Κορῆ, παραχώρησον τὴν κρίσιν τῷ θεῷ καὶ τὴν ἐπὶ τούτοις αὐτοῦ μένε ψηφοφορίαν, ἀλλὰ μὴ σαυτὸν ποίει τοῦ θεοῦ κρείττονα, παραγίνου δὲ κριθησόμενος οὕτως περὶ τοῦ γέρως. ἀνεμέσητον δʼ οἶμαι καὶ Ἀαρῶνα προσδέξασθαι συγκριθησόμενον, γένους μὲν ὄντα τοῦ αὐτοῦ μηδὲν δὲ μεμφθῆναι τοῖς παρὰ τὴν ἱερωσύνην πεπραγμένοις δυνάμενον."},{"number":34,"text":"θυμιάσετε οὖν συνελθόντες ἐν φανερῷ παντὶ τῷ λαῷ, καὶ θυμιωμένων ὑμῶν οὗπερ ἂν τὴν θυσίαν ἡδίω κρίνῃ ὁ θεός, οὗτος ὑμῖν ἱερεὺς κεχειροτονήσεται, τῆς ἐπὶ τἀδελφῷ διαβολῆς ὡς κεχαρισμένου τὴν τιμὴν αὐτῷ ῥυόμενος."}],"3":[{"number":35,"text":"Ταῦτα Μωυσέος εἰπόντος παύεται καὶ τῆς ταραχῆς τὸ πλῆθος καὶ τῆς εἰς Μωυσῆν ὑποψίας, ἐπένευσαν δὲ τοῖς εἰρημένοις· καὶ γὰρ ἦν καὶ ἐδόκει χρηστὰ τῷ λαῷ. τότε μὲν οὖν διαλύουσι τὸν σύλλογον, τῇ δʼ ἐπιούσῃ συνῆλθον εἰς τὴν ἐκκλησίαν παρατευξόμενοι τῇ θυσίᾳ καὶ τῇ διʼ αὐτῆς κρίσει τῶν περὶ τῆς ἱερωσύνης ἀγωνιζομένων."},{"number":36,"text":"συνέβαινε δʼ εἶναι θορυβώδη τὴν ἐκκλησίαν μετεώρου τοῦ πλήθους ὄντος ἐπʼ ἐλπίδι τῶν ἐσομένων, καὶ τῶν μὲν εἰς ἡδονὴν λαμβανόντων, εἰ Μωυσῆς ἐλεγχθείη κακουργῶν, τῶν δὲ φρονίμων, εἰ πραγμάτων ἀπαλλαγείησαν καὶ ταραχῆς· ἐδεδίεσαν γάρ, μὴ τῆς στάσεως προϊούσης ἀφανισθῇ μᾶλλον αὐτοῖς ὁ κόσμος τῆς καταστάσεως."},{"number":37,"text":"ὁ δὲ πᾶς ὅμιλος φύσει χαίρων τῷ καταβοᾶν τῶν ἐν τέλει καὶ πρὸς ὅ τις εἴποι πρὸς τοῦτο τὴν γνώμην τρέπων ἐθορύβει. πέμψας δὲ καὶ Μωυσῆς πρὸς Ἀβίραμον καὶ Δαθάμην ὑπηρέτας ἐκέλευσεν ἥκειν κατὰ τὰ συγκείμενα καὶ περιμένειν τὴν ἱερουργίαν."},{"number":38,"text":"ὡς δʼ οὔτε ὑπακούσεσθαι τοῖς ἀγγέλοις ἔφασαν καὶ Μωυσῆν οὐ περιόψεσθαι κατὰ τοῦ λαοῦ παντὸς ἐκ κακουργίας αὐξανόμενον, ἀκούσας τὰ παρʼ αὐτῶν ὁ Μωυσῆς ἀκολουθεῖν αὐτῷ τοὺς προβούλους ἀξιώσας ἀπῄει πρὸς τοὺς περὶ Δαθάμην, οὐχ ἡγούμενος εἶναι δεινὸν βαδίζειν πρὸς τοὺς ὑπερηφανήσαντας· οἱ δʼ οὐδὲν ἀντειπόντες ἠκολούθουν."},{"number":39,"text":"οἱ δὲ περὶ Δαθάμην πυθόμενοι τὸν Μωυσῆν μετὰ τῶν ἀξιολόγων τῆς πληθύος πρὸς αὐτοὺς παραγινόμενον προελθόντες γυναιξὶν ἅμα καὶ τέκνοις πρὸ τῶν σκηνῶν ἀπέβλεπον, τί καὶ μέλλοι ποιεῖν ὁ Μωυσῆς· ἔτι τε θεράποντες ἦσαν περὶ αὐτούς, ὡς εἰ βίαν τινὰ προσφέροι Μωυσῆς ἀμυνούμενοι."},{"number":40,"text":"Ὁ δὲ πλησίον γενόμενος τὰς χεῖρας εἰς τὸν οὐρανὸν ἀνασχὼν γεγωνότερον ἐκβοήσας, ὡς ἀκουστὸν πάσῃ τῇ πληθύι γενέσθαι, δέσποτα, φησί, τῶν ἐπʼ οὐρανοῦ τε καὶ γῆς καὶ θαλάσσης· σὺ γὰρ ἐμοὶ τῶν ὑπʼ ἐμοῦ πεπραγμένων μάρτυς ἀξιολογώτατος, ὡς γνώμῃ τε σῇ γίνεται πάντα καὶ δρωμένοις μηχανὴν ἐξεπόρισας οἶκτον ἐν πᾶσι δεινοῖς Ἑβραίων ποιησάμενος, ἐλθέ μοι τούτων ἀκροατὴς τῶν λόγων·"},{"number":41,"text":"σὲ γὰρ οὔτε πραττόμενον οὔτε νοηθὲν λανθάνει, ὥστʼ οὐδὲ φθονήσεις μοι τῆς ἀληθείας τὴν τούτων ἀχαριστίαν ἐπίπροσθεν θέμενος. τὰ μὲν οὖν πρεσβύτερα τῆς ἐμῆς γενέσεως αὐτὸς οἶσθʼ ἀκριβέστερον οὐκ ἀκοῇ μαθὼν ὄψει δὲ τότʼ αὐτοῖς παρὼν γινομένοις, ἃ δὲ ἐπὶ τούτοις καίπερ ἐπιστάμενοι σαφῶς ἀδίκως ὑπονοοῦσι τούτων μοι γενοῦ μάρτυς."},{"number":42,"text":"ἐγὼ βίον ἀπράγμονα καταστησάμενος ἀνδραγαθίᾳ μὲν ἐμῇ σῇ δὲ βουλῇ, καὶ τοῦτον Ῥαγουήλου μοι τοῦ πενθεροῦ καταλιπόντος ἀφεὶς τὴν ἐκείνων ἀπόλαυσιν τῶν ἀγαθῶν ἐμαυτὸν ἐπέδωκα ταῖς ὑπὲρ τούτων ταλαιπωρίαις. καὶ πρότερον μὲν ὑπὲρ τῆς ἐλευθερίας αὐτῶν, νῦν δʼ ὑπὲρ τῆς σωτηρίας μεγάλους ὑπέστην πόνους καὶ παντὶ δεινῷ τοὐμὸν ἀντιτάξας πρόθυμον."},{"number":43,"text":"νῦν οὖν ἐπεὶ κακουργεῖν ὑποπτεύομαι παρʼ ἀνδράσιν, οἷς ἐκ τῶν ἐμῶν καμάτων ὑπῆρχε τὸ περιεῖναι, εἰκότως ἂν αὐτός, ὁ τὸ πῦρ ἐκεῖνό μοι φήνας κατὰ τὸ Σιναῖον καὶ τῆς σαυτοῦ φωνῆς ἀκροατὴν τότε καταστήσας καὶ θεατὴν τεράτων ὅσα μοι παρέσχεν ἰδεῖν ἐκεῖνος ὁ τόπος ποιήσας, ὁ κελεύσας ἐπʼ Αἰγύπτου σταλῆναι καὶ τὴν σὴν γνώμην τούτοις ἐμφανίσαι,"},{"number":44,"text":"ὁ τὴν Αἰγυπτίων εὐδαιμονίαν σείσας καὶ τῆς ὑπʼ αὐτοὺς δουλείας δρασμὸν ἡμῖν παρασχὼν καὶ μικροτέραν ἐμοῦ τὴν Φαραώθου ποιήσας ἡγεμονίαν, ὁ γῆν ἡμῖν ἀμαθῶς ἔχουσι τῶν ὁδῶν ποιήσας τὸ πέλαγος καὶ τὴν ἀνακεκομμένην θάλασσαν τοῖς Αἰγυπτίων ἐπικυμήνας ὀλέθροις, ὁ γυμνοῖς οὖσι τὴν ἐξ ὅπλων ἀσφάλειαν χαρισάμενος,"},{"number":45,"text":"ὁ ποτίμους ἡμῖν διεφθαρμένας πηγὰς ῥεῦσαι παρασκευάσας καὶ τελέως ἀποροῦσιν ἐκ πετρῶν ἐλθεῖν ἡμῖν ποτὸν μηχανησάμενος, ὁ τῶν γῆθεν ἀπορουμένους εἰς τροφὴν διασώσας τοῖς ἀπὸ θαλάσσης, ὁ καὶ ἀπʼ οὐρανοῦ τροφὴν καταπέμψας οὐ πρότερον ἱστορηθεῖσαν, ὁ νόμων ἡμῖν ἐπίνοιαν ὑποθέμενος καὶ διάταξιν πολιτείας·"},{"number":46,"text":"ἐλθέ, δέσποτα τῶν ὅλων, δικαστής μου καὶ μάρτυς ἀδωροδόκητος, ὡς οὔτε δωρεὰν ἐγὼ παρʼ Ἑβραίων τινὸς κατὰ τοῦ δικαίου προσηκάμην οὔτε πλούτῳ κατέκρινα πενίαν νικᾶν δυναμένην οὔτε ἐπὶ βλάβῃ τοῦ κοινοῦ πολιτευσάμενος εἰς ἀλλοτριωτάτας τῶν ἐμῶν ἐπιτηδευμάτων ἐπινοίας πάρειμι, ὡς οὐχὶ σοῦ κελεύσαντος Ἀαρῶνι δοὺς τὴν ἱερωσύνην ἀλλὰ κατʼ ἐμὴν χάριν."},{"number":47,"text":"παράστησον δὲ καὶ νῦν, ὅτι πάντα σῇ προνοίᾳ διοικεῖται καὶ μηδὲν αὐτομάτως ἀλλὰ κατὰ βούλησιν βραβευόμενον τὴν σὴν εἰς τέλος ἔρχεται, ὅτι δὲ φροντίζεις τῶν Ἑβραίους ὀνησόντων, μετελθὼν Ἀβίραμον καὶ Δαθάμην, οἵ σου καταδικάζουσιν ἀναισθησίαν ὡς ὑπʼ ἐμῆς τέχνης νικωμένου."},{"number":48,"text":"ποιήσεις δὲ φανερὰν τὴν ἐπʼ αὐτοῖς δίκην οὕτως μεμηνότων κατὰ τῆς σῆς δόξης, μὴ κοινῶς ἐκ τοῦ ζῆν αὐτοὺς μεταστήσας μηδʼ ὡς ἀποθανόντας κατʼ ἀνθρώπινον ἐξεληλυθότας τοῦ βίου φανέντας νόμον, ἀλλὰ χάνοι περὶ αὐτοὺς ἅμα τῇ γενεᾷ καὶ τοῖς ὑπάρχουσιν ἣν πατοῦσι γῆν·"},{"number":49,"text":"τοῦτο γὰρ σῆς ἐπίδειξις ἂν ἰσχύος ἅπασι γένοιτο καὶ διδασκαλία σωφροσύνης δὲ εἰς τοὺς ταῦτα πείσεσθαι περὶ σοῦ δοξάζοντας οὐχ ὅσια· εὑρεθείην γὰρ ἂν οὕτως ἀγαθὸς ὑπηρέτης ὧν σὺ προστάσσεις."},{"number":50,"text":"εἰ δʼ ἀληθεῖς πεποίηνται τὰς κατʼ ἐμοῦ διαβολάς, τοὺς μὲν ἀπαθεῖς ἀπὸ παντὸς φυλάξεις κακοῦ, ὃν δʼ ἐπηρασάμην ὄλεθρον αὐτοῖς τοῦτον ποιήσεις ἐμόν, καὶ δίκην εἰσπραξάμενος παρὰ τοῦ τὸν σὸν ἀδικῆσαι θελήσαντος λαὸν τοῦ λοιποῦ βραβεύων ὁμόνοιαν καὶ εἰρήνην σῶζε τὴν πληθὺν ἑπομένην τοῖς σοῖς προστάγμασιν, ἀπαθῆ τηρῶν αὐτὴν καὶ ἀκοινώνητον τῆς τῶν ἡμαρτηκότων κολάσεως· σὺ γὰρ αὐτὸς οἶσθα, ὡς οὐ δίκαιον ὑπὲρ τῆς ἐκείνων κακίας κοινῇ πάντας Ἰσραηλίτας τιμωρίαν ἐκτίνειν."},{"number":51,"text":"Ταῦτʼ εἰπόντος καὶ δακρύοντος σείεται μὲν αἰφνίδιον ἡ γῆ, σάλου δʼ ἐπʼ αὐτῆς κινηθέντος ὥσπερ ἐξ ἀνέμου βίας σαλευομένου κύματος πᾶς μὲν ἔδεισεν ὁ λαός, πατάγου δὲ καὶ σκληροῦ ῥαγέντος ἤχου κατὰ τὰς ἐκείνων σκηνὰς συνίζησεν ἡ γῆ καὶ πάνθʼ ὅσα φίλα τούτοις ἦν ὑπήνεγκεν εἰς αὑτήν."},{"number":52,"text":"ἠφανισμένων δʼ οὕτως, ὡς μηδὲ φανῆναί τινας γνῶναι, συνῄει τε πάλιν τῆς γῆς τὸ περὶ ἐκείνοις κεχηνὸς καὶ καθίστατο, ὡς μηδʼ εἰ πάθοι τι τῶν προειρημένων φανερὸν εἶναι τοῖς ὁρῶσι. καὶ οἱ μὲν οὕτως ἀπώλοντο ἐπίδειξις τοῦ θεοῦ τῆς ἰσχύος γενόμενοι·"},{"number":53,"text":"ὀδύραιτο δʼ ἄν τις οὐ μόνον τῆς συμφορᾶς αὐτοὺς καὶ καθʼ ἑαυτὴν οὔσης ἀξίας οἴκτου, ἀλλʼ ὅτι καὶ τοιαῦτα παθόντων ἐφήσθησαν οἱ συγγενεῖς· τῶν γὰρ συντεταγμένων ἐκλαθόμενοι πρὸς τὴν ὄψιν τοῦ συμβεβηκότος ἐβεβαίουν τὴν κρίσιν, καὶ νομίζοντες ὡς ἀλιτηρίους ἀπολωλέναι τοὺς περὶ Δαθάμην οὐδʼ ἐλυποῦντο."},{"number":54,"text":"Μωυσῆς δʼ ἐκάλει τοὺς περὶ τῆς ἱερωσύνης ἁμιλλωμένους διὰ τὴν τῶν ἱερέων δοκιμασίαν, ἵνʼ οὗ προσδέξηται τὴν θυσίαν ὁ θεὸς ἥδιον εἴη κεχειροτονημένος. συνελθόντων δὲ πεντήκοντα καὶ διακοσίων ἀνδρῶν, οἳ καὶ διὰ πατέρων ἀρετὴν ἐτιμῶντο παρὰ τῷ λαῷ καὶ διὰ τὴν αὐτῶν, ᾗ κἀκείνους ὑπερεβάλλοντο, προῆλθον καὶ Ἀαρὼν καὶ Κορῆς, καὶ πρὸ τῆς σκηνῆς πάντες καθήγνισαν ἐπὶ τοῖς θυμιατηρίοις ὁπόσα κομίζοντες ἔτυχον."},{"number":55,"text":"ἐξέλαμψε δὲ πῦρ τοσοῦτον ὅσον οὔτε χειροποίητον ἱστόρησέ τις οὔτε γῆθεν ἀναδοθὲν κατὰ ὑποδρομὴν καύματος οὔτε κατὰ βίαν πνευμάτων ὕλης πρὸς αὐτὸ παρατριβείσης αὐτομάτως ἐξεκρούσθη, ἀλλʼ ὁποῖον θεοῦ κελεύσαντος ἁφθείη λαμπρὸν καὶ φλογωδέστατον·"},{"number":56,"text":"ὑφʼ οὗ πάντες, οἵ τε διακόσιοι καὶ πεντήκοντα καὶ Κορῆς, ᾄξαντος ἐπʼ αὐτοὺς ἐφθάρησαν, ὡς καὶ τὰ σώματα αὐτῶν ἀφανῆ γεγονέναι. περισώζεται δὲ μόνος Ἀαρὼν μηδὲν ὑπὸ τοῦ πυρὸς βλαβεὶς τῷ τὸν θεὸν εἶναι τὸν οὓς ἔδει καίειν ἀπεσταλκότα."},{"number":57,"text":"Μωυσῆς δὲ τούτων ἀπολομένων βουλόμενος τὴν τιμωρίαν αὐτῶν μνήμῃ παραδοθῆναι καὶ τοὺς αὖθις ἐσομένους αὐτὴν μαθεῖν, ἐκέλευσεν Ἐλεάζαρον τὸν Ἀαρῶνος υἱὸν τὰ θυμιατήρια αὐτῶν παρὰ τὸν χάλκεον καταθέσθαι βωμόν,"},{"number":58,"text":"ὡς ἂν ὑπόμνησις εἴη τοῖς αὖθις ὧν ἔπαθον καὶ ὅτι τὴν ἰσχὺν τοῦ θεοῦ νομίσειαν ἀπατᾶσθαι δύνασθαι. καὶ Ἀαρὼν μὲν οὐκέτι τῇ Μωυσέος χάριτι τὴν ἀρχιερωσύνην ἔχειν δοκῶν, ἀλλὰ τῇ τοῦ θεοῦ κρίσει φανερᾷ γενομένῃ, μετὰ τῶν υἱῶν ἤδη βεβαίως ἀπέλαυε τῆς τιμῆς."}],"4":[{"number":59,"text":"Τὴν μέντοι στάσιν οὐδʼ οὕτως συνέβη παύσασθαι, πολλῷ δὲ μᾶλλον αὔξειν καὶ φύεσθαι· χαλεπωτέραν ἐλάμβανε τῆς ἐπὶ τὸ χεῖρον προκοπῆς αἰτίαν, ὑφʼ ἧς οὐδέποτε λήξειν τὸ δεινὸν ἦν εἰκὸς ἀλλʼ εἰς χρόνον παραμενεῖν."},{"number":60,"text":"οἱ γὰρ ἄνθρωποι πεπιστευκότες ἤδη μηδὲν γίνεσθαι δίχα τῆς τοῦ θεοῦ προνοίας οὐκ ἐβούλοντο ταῦτα χωρὶς τῆς εἰς Μωυσῆν χάριτος τοῦ θεοῦ πεπρᾶχθαι, κατηγόρουν δʼ αὐτοῦ τὴν ὀργὴν τοῦ θεοῦ γίνεσθαι τοσαύτην οὐχ οὕτω διὰ τὴν τῶν κολασθέντων ἀδικίαν, ὡς Μωυσέος πραγματευσαμένου·"},{"number":61,"text":"καὶ τοὺς μὲν διεφθάρθαι μηδὲν ἐξαμαρτόντας ἢ ὅτι περὶ τὴν τοῦ θεοῦ θρησκείαν ἐσπουδάκεσαν, τὸν δὲ τοιούτων ἀνδρῶν ὀλέθρῳ καὶ πάντων ἀρίστων ἐζημιωκότα τὸν λαὸν πρὸς τῷ μηδεμίαν ὑποσχεῖν δίκην ἔτι καὶ τὴν ἱερωσύνην ἀναμφίλεκτον τἀδελφῷ παρασχεῖν·"},{"number":62,"text":"οὐδένα γὰρ ἔτι αὐτῆς ἄλλον ἀντιποιήσεσθαι καὶ τοὺς πρώτους ὁρῶντα κακῶς ἀπολωλότας. ἔτι γε μὴν καὶ παρὰ τῶν οἰκείων τοῖς διεφθαρμένοις δέησις ἐγένετο πολλὴ τοῦ πλήθους μειῶσαί τι τῆς Μωυσέος μεγαλαυχίας· ἀσφαλὲς γὰρ αὐτοῖς τοῦτʼ εἶναι."},{"number":63,"text":"Μωυσῆς δέ, καὶ γὰρ ἐκ πολλοῦ συνιστάμενον ἠκροᾶτο τὸν θόρυβον, δείσας μή τι νεωτερίσωσι πάλιν καὶ γένηταί τι μέγα καὶ χαλεπὸν συνήγαγε τὸ πλῆθος εἰς ἐκκλησίαν, καὶ περὶ μὲν ὧν ἠκροᾶτο εἰς ἀπολογίαν οὐ καθιστάμενος, ἵνα μὴ παροξύνῃ τὸ πλῆθος, αὐτὸ δὲ μόνον τοῖς φυλάρχοις προειπὼν κομίζειν τὰ τῶν φυλῶν ὀνόματα βακτηρίαις ἐπιγεγραμμένα·"},{"number":64,"text":"λήψεσθαι γὰρ ἐκεῖνον τὴν ἱερωσύνην, οὗπερ ἂν ὁ θεὸς ἐπισημήνῃ τῇ βακτηρίᾳ. δόξαν οὖν κομίζουσιν οἵ τε ἄλλοι καὶ Ἀαρὼν ἐπιγράψας Λευῖτιν ἐν τῇ βακτηρίᾳ, καὶ ταύτας Μωυσῆς ἐν τῇ σκηνῇ τοῦ θεοῦ κατατίθησι. τῇ δὲ ἐπιούσῃ προεκόμισε τὰς βακτηρίας· γνώριμοι δʼ ἦσαν κατασημηναμένων αὐτὰς τῶν τε ἀνδρῶν οἵπερ ἐκόμιζον καὶ τοῦ πλήθους."},{"number":65,"text":"καὶ τὰς μὲν ἄλλας ἐφʼ οὗπερ αὐτὰς σχήματος Μωυσῆς παρέλαβεν ἐπὶ τούτου μεμενηκυίας ἔβλεπον, ἐκ δὲ τῆς Ἀαρῶνος βλαστούς τε καὶ κλάδους ἀναφύντας ἑώρων καὶ καρπὸν ὡραῖον, ἀμύγδαλα δʼ ἦν, ἐκ τοιούτου ξύλου τῆς βακτηρίας κατεσκευασμένης."},{"number":66,"text":"ἐκπλαγέντες δʼ ἐπὶ τῷ παραλόγῳ τῆς θέας, εἰ καί τισι διὰ μίσους ἦν ὁ Μωυσῆς καὶ Ἀαρών, ἀφέντες τοῦτο θαυμάζειν ἤρξαντο τὴν τοῦ θεοῦ περὶ αὐτῶν κρίσιν καὶ τὸ λοιπὸν ἐπευφημοῦντες τοῖς δεδογμένοις τῷ θεῷ συνεχώρουν Ἀαρῶνι καλῶς ἔχειν τὴν ἀρχιερωσύνην. καὶ ὁ μὲν τρὶς αὐτὸν τοῦ θεοῦ χειροτονήσαντος βεβαίως εἶχε τὴν τιμήν, ἡ δὲ τῶν Ἑβραίων στάσις πολὺν ἀκμάσασα χρόνον τοῦτον ἐπαύθη τὸν τρόπον."},{"number":67,"text":"Μωυσῆς δʼ ἐπεὶ πολέμου καὶ στρατείας ἡ τῶν Λευιτῶν ἀφεῖτο φυλὴ θεραπεύουσα τὸν θεόν, ἵνα μὴ διʼ ἀπορίαν μηδὲ ζήτησιν τῶν εἰς τὸν βίον ἀναγκαίων ἀμελοῖεν τοῦ ἱεροῦ, κατὰ βούλησιν τοῦ θεοῦ τὴν Χαναναίαν κτησαμένους τοὺς Ἑβραίους ἐκέλευε κατανεῖμαι τοῖς Λευίταις ὀκτὼ καὶ τεσσαράκοντα πόλεις ἀγαθὰς καὶ καλὰς τῆς τε πρὸ αὐτῶν γῆς περιγράψαντας εἰς δισχιλίους πήχεις ἀπὸ τῶν τειχῶν αὐτοῖς ἀνεῖναι."},{"number":68,"text":"πρὸς τούτοις δὲ καὶ τὸν λαὸν ἐξέταξε τῶν ἐπετείων καρπῶν δεκάτην αὐτοῖς τε τοῖς Λευίταις καὶ ἱερεῦσι τελεῖν. καὶ ἃ μὲν ἡ φυλὴ παρὰ τοῦ πλήθους λαμβάνει ταῦτʼ ἐστίν· ἀναγκαῖον δʼ ἡγησάμην ἃ τοῖς ἱερεῦσιν ἰδίᾳ παρὰ πάντων γίνεται δηλῶσαι."},{"number":69,"text":"Τῶν μὲν τεσσαράκοντα καὶ ὀκτὼ πόλεων τρισκαίδεκα παραχωρῆσαι τοὺς Λευίτας αὐτοῖς προσέταξε καὶ τῆς δεκάτης, ἧς παρὰ τοῦ λαοῦ κατʼ ἔτος λαμβάνουσι, δεκάτην αὐτοῖς ἀπομερίζειν."},{"number":70,"text":"ἔτι δὲ ἀπαρχὰς τὸν λαὸν δίκαιον τῷ θεῷ πάντων τῶν ἐκ τῆς γῆς φυομένων καρπῶν ἐπιφέρειν, καὶ τῶν τετραπόδων δὲ τῶν εἰς τὰς θυσίας νενομισμένων τὸ γεννηθὲν πρῶτον, ἂν ἄρσεν ᾖ, καταθῦσαι παρασχεῖν τοῖς ἱερεῦσιν, ὥστε αὐτοὺς πανοικὶ σιτεῖσθαι ἐν τῇ ἱερᾷ πόλει."},{"number":71,"text":"τῶν δʼ οὐ νενομισμένων ἐσθίειν παρʼ αὐτοῖς κατὰ τοὺς πατρίους νόμους τοὺς δεσπότας σίκλον καὶ ἥμισυ αὐτοῖς ἀναφέρειν, ἀνθρώπου δὲ πρωτοτόκου πέντε σίκλους, εἶναι δὲ ἀπαρχὰς αὐτοῖς καὶ τῆς τῶν προβάτων κουρᾶς, τούς τε πέττοντας τὸν σῖτον καὶ ἀρτοποιουμένους τῶν πεμμάτων αὐτοῖς τινα χορηγεῖν."},{"number":72,"text":"ὅσοι δʼ ἂν αὑτοὺς καθιερῶσιν εὐχὴν πεποιημένοι, ναζιραῖοι δὲ οὗτοι καλοῦνται, κομῶντες καὶ οἶνον οὐ προσφερόμενοι, τούτους δὲ ὅταν τὰς τρίχας ἀφιερῶσιν ἐπὶ θυσίᾳ τε δρῶσι τὰς κουρὰς νέμεσθαι πρὸς τοὺς ἱερέας."},{"number":73,"text":"καὶ οἱ κορβᾶν αὑτοὺς ὀνομάσαντες τῷ θεῷ, δῶρον δὲ τοῦτο σημαίνει κατὰ Ἑλλήνων γλῶτταν, βουλομένους ἀφίεσθαι τῆς λειτουργίας τοῖς ἱερεῦσι καταβάλλειν ἀργύριον, γυναῖκα μὲν τριάκοντα σίκλους ἄνδρα δὲ πεντήκοντα. ὅσοι δὲ ἂν ἐνδεέστερα τῶν ὡρισμένων ἔχωσι χρήματα τοῖς ἱερεῦσιν ἐξεῖναι περὶ τούτων ὡς βούλονται δοκιμάσαι."},{"number":74,"text":"εἶναι δὲ καὶ τοῖς κατʼ οἶκον θύουσιν εὐωχίας ἕνεκα τῆς αὑτῶν ἀλλὰ μὴ θρησκείας ἀνάγκην κομίζειν τοῖς ἱερεῦσιν ἔνυστρόν τε καὶ χελύνιον καὶ τὸν δεξιὸν βραχίονα τοῦ θύματος. καὶ τοῖς μὲν ἱερεῦσι Μωυσῆς τοσαύτην, πάρεξ ὧν ὑπὲρ ἁμαρτημάτων θύων ὁ λαὸς δίδωσιν αὐτοῖς, ὡς ἐν τῇ πρὸ ταύτης βίβλῳ δεδηλώκαμεν, εὐπορίαν ἐπενόησε."},{"number":75,"text":"πάντων δὲ τῶν τοῖς ἱερεῦσι τελουμένων κοινωνεῖν διέταξε καὶ τοὺς οἰκέτας καὶ θυγατέρας καὶ γυναῖκας ἔξω τῶν ὑπὲρ ἁμαρτημάτων ἐπιφερομένων θυσιῶν· ταύτας γὰρ ἐν τῷ ἱερῷ μόνοι δαπανῶσιν οἱ ἄρρενες τῶν ἱερέων αὐθημερόν."},{"number":76,"text":"Ὡς δὲ ταῦτα μετὰ τὴν στάσιν Μωυσῆς διέταξεν, ἄρας μετὰ πάσης τῆς στρατιᾶς ἐπὶ τοὺς τῆς Ἰδουμαίας ὅρους ἦλθε καὶ πρέσβεις πρὸς τὸν βασιλέα τῶν Ἰδουμαίων πέμψας ἠξίου δίοδον αὐτῷ παρασχεῖν, πίστεις ἃς αὐτὸς ἐθέλοι λαβεῖν ὑπὲρ τοῦ μηδὲν ἀδικηθήσεσθαι δώσειν ὁμολογῶν, ἀγοράν τε τῷ στρατῷ χορηγῆσαι καὶ τιμὴν τοῦ ὕδατος αὐτοὺς κελεῦσαι καταβαλεῖν."},{"number":77,"text":"ὁ δʼ οἷς ἐπρεσβεύσατο Μωυσῆς οὐκ ἀρεσκόμενος οὐδὲ συγχωρῶν τὴν δίοδον ἔνοπλον τὴν στρατιὰν ἀγαγὼν προαπήντα τῷ Μωυσεῖ, κωλύσων αὐτοὺς εἰ τολμήσαιεν βίᾳ περαιοῦσθαι. καὶ Μωυσῆς, ἄρχειν γὰρ μάχης οὐ συνεβούλευσεν ὁ θεὸς χρωμένῳ, τὴν δύναμιν ὑπανῆγε διὰ τῆς ἐρήμου ἐκπεριιών."},{"number":78,"text":"Τότε δὴ καὶ τὴν ἀδελφὴν αὐτοῦ Μαριάμην τελευτὴ τοῦ βίου καταλαμβάνει τεσσαρακοστὸν ἔτος πεπληρωκυῖαν ἀφʼ οὗ τὴν Αἴγυπτον κατέλιπε μηνὸς δὲ Ξανθικοῦ νουμηνίᾳ κατὰ σελήνην. θάπτουσι δʼ αὐτὴν δημοσίᾳ πολυτελῶς ὑπέρ τινος ὄρους, ὃ καλοῦσι Σίν, καὶ πενθήσαντα ἐπὶ τριάκοντα ἡμέρας τὸν λαὸν ἐκάθηρε Μωυσῆς τούτῳ τῷ τρόπῳ·"},{"number":79,"text":"μόσχον θήλειαν, ἀρότρου μὲν καὶ γεωργίας ἄπειρον ὁλόκληρον δέ, ξανθὴν πᾶσαν, μικρὸν ἄπωθεν τοῦ στρατοπέδου προαγαγὼν εἰς χωρίον καθαρώτατον ὁ ἀρχιερεὺς ἔθυέ τε καὶ τοῦ αἵματος ἑπτάκις ἔρρανε τῷ δακτύλῳ ἀντικρὺ τῆς σκηνῆς τοῦ θεοῦ."},{"number":80,"text":"ἔπειτα καιομένης ὡς εἶχεν ὅλης τῆς δαμάλιδος σὺν τῇ δορᾷ καὶ τοῖς ἐντὸς ξύλον κέδρινον εἰς μέσον ἐμβάλλουσι τὸ πῦρ καὶ ὕσσωπον καὶ φοινικτὸν ἔριον· συναγαγὼν δʼ αὐτῆς ἅπασαν τὴν τέφραν ἁγνὸς ἀνὴρ κατατίθησιν εἰς χωρίον καθαρώτατον."},{"number":81,"text":"τοὺς οὖν ἀπὸ νεκροῦ μεμιασμένους τῆς τέφρας ὀλίγον εἰς πηγὴν ἐνιέντες καὶ ὕσσωπον βαπτίσαντές τε καὶ τῆς τέφρας ταύτης εἰς πηγὴν ἔρραινον τρίτῃ τε καὶ ἑβδόμῃ τῶν ἡμερῶν καὶ καθαροὶ τὸ λοιπὸν ἦσαν. τοῦτο δὲ καὶ κατελθοῦσιν εἰς τὰς κληρουχίας προσέταξε ποιεῖν."},{"number":82,"text":"Μετὰ δὲ τὴν ἐπὶ τῷ πένθει τῆς ἀδελφῆς τοῦ στρατηγοῦ κάθαρσιν τοιαύτην γενομένην ἀπῆγε τὴν δύναμιν διὰ τῆς ἐρήμου καὶ τῆς Ἀραβίας ἐλθὼν εἰς χωρίον, ὃ μητρόπολιν αὑτῶν Ἄραβες νενομίκασι, πρότερον μὲν Ἄρκην λεγομένην Πέτραν δὲ νῦν ὀνομαζομένην."},{"number":83,"text":"ἐνταῦθα ὑψηλοῦ περιέχοντος ὄρους αὐτὸ ἀναβὰς Ἀαρὼν ἐπʼ αὐτὸ Μωυσέος αὐτῷ δεδηλωκότος, ὅτι μέλλοι τελευτᾶν, παντὸς τοῦ στρατεύματος ὁρῶντος, κάταντες γὰρ ἦν τὸ χωρίον, ἀποδύεται τὴν ἀρχιερατικὴν στολὴν καὶ παραδοὺς αὐτὴν Ἐλεαζάρῳ τῷ παιδί, πρὸς ὃν διὰ τὴν ἡλικίαν ἡ ἀρχιερωσύνη παραγίνεται, θνήσκει τοῦ πλήθους εἰς αὐτὸν ἀφορῶντος,"},{"number":84,"text":"τῷ μὲν αὐτῷ τελευτήσας ἔτει, ᾧ καὶ τὴν ἀδελφὴν ἀπέβαλε, βιοὺς δὲ ἔτη τὰ πάντα τρία πρὸς τοῖς εἴκοσι καὶ ἑκατόν. ἀποθνήσκει δὲ κατὰ σελήνην νουμηνίᾳ μηνὸς ὄντος τοῦ παρὰ μὲν Ἀθηναίοις Ἑκατομβαιῶνος καλουμένου Λώου δὲ παρὰ Μακεδόσι Σαβὰ δὲ παρὰ Ἑβραίοις."}],"5":[{"number":85,"text":"Πένθος δὲ ἐπʼ αὐτῷ τοῦ λαοῦ τριακονθήμερον ἄγοντος, ἐπεὶ τοῦτʼ ἐλώφησεν, ἀναλαβὼν ἐκεῖθεν Μωυσῆς τὸν στρατὸν παρῆν ἐπὶ τὸν ποταμὸν Ἀρνῶνʼ, ὃς ἐκ τῶν τῆς Ἀραβίας ὀρῶν ὡρμημένος καὶ διὰ πάσης ἐρήμου ῥέων εἰς τὴν Ἀσφαλτῖτιν λίμνην ἐκδίδωσιν ὁρίζων τήν τε Μωαβῖτιν καὶ Ἀμωρῖτιν. γῆ δʼ αὕτη καρποφόρος καὶ πλῆθος ἀνθρώπων τοῖς παρʼ αὐτῆς ἀγαθοῖς ἱκανὴ τρέφειν."},{"number":86,"text":"πρὸς οὖν Σιχῶνα τὸν βασιλεύοντα τῆς χώρας ταύτης ἀπέστειλε Μωυσῆς τῷ στρατῷ δίοδον αἰτῶν ἐφʼ αἷς ἂν θελήσειε πίστεσιν, ὥστε μηδὲν ἀδικηθῆναι μήτε τὴν γῆν μήτε τοὺς ἐνοικοῦντας, ὧν Σιχὼν ἐκράτει, τοῖς τε κατὰ τὴν ἀγορὰν χρῆσθαι πρὸς τὸ ἐκείνων λυσιτελές, εἰ καὶ τὸ ὕδωρ αὐτοῖς πιπράσκειν ἐθέλοιεν. Σιχὼν δʼ ἀρνούμενος ὁπλίζει τὸν οἰκεῖον στρατὸν καὶ τοὺς Ἑβραίους διαβαίνειν τὸν Ἀρνῶνα κωλύειν ἑτοιμότατος ἦν."},{"number":87,"text":"Μωυσῆς δὲ ὁρῶν πολεμίως αὐτοῖς τὸν Ἀμοραῖον διακείμενον οὔτε περιφρονούμενος ἀνέχεσθαι δεῖν ἔγνω καὶ τοὺς Ἑβραίους τῆς ἀπραξίας καὶ τῆς διʼ αὐτὴν ἀπορίας, ὑφʼ ἧς στασιάσαι τε πρότερον αὐτοῖς συνέπεσε καὶ τότε δυσκόλως εἶχον, ἀπαλλάξαι διαγνοὺς ἤρετο τὸν θεόν, εἰ πολεμεῖν αὐτῷ δίδωσι."},{"number":88,"text":"τοῦ δὲ θεοῦ καὶ νίκην ἐπισημήναντος αὐτὸς θαρσαλέως εἶχε πρὸς τὸν ἀγῶνα καὶ τοὺς στρατιώτας παρώρμα, νῦν αὐτοὺς ἀξιῶν τῆς τοῦ πολεμεῖν ἡδονῆς ἀπολαύειν, ὅτʼ αὐτῇ συγχωρεῖ χρῆσθαι τὸ θεῖον. οἱ δʼ ἧς ἐπόθουν ἐξουσίας λαβόμενοι καὶ τὰς πανοπλίας ἀναλαβόντες εὐθέως ἐχώρουν εἰς τὸ ἔργον."},{"number":89,"text":"ὁ δὲ Ἀμορραῖος οὐκέτʼ ἦν ἐπιόντων ὅμοιος αὑτῷ, ἀλλʼ αὐτός τε κατεπλάγη τοὺς Ἑβραίους καὶ ἡ δύναμις αὐτοῦ παρέχουσα θᾶττον αὑτὴν εὔψυχον εἶναι δοκεῖν τότʼ ἀπηλέγχθη πεφοβημένη. τὴν πρώτην οὖν σύνοδον οὐχ ὑπομείναντες ἀντιστῆναι καὶ δέξασθαι τοὺς Ἑβραίους τρέπονται, τοῦτο ἑαυτοῖς σωτηρίαν ὑπολαβόντες ἢ τὸ μάχεσθαι παρέξειν·"},{"number":90,"text":"ἐθάρρουν γὰρ ταῖς πόλεσιν οὔσαις ὀχυραῖς. παρʼ ὧν οὐδὲν αὐτοῖς ὄφελος ἦν εἰς ταύτας συνδιωχθεῖσιν· Ἑβραῖοι γὰρ ὡς ἐνδόντας αὐτοὺς εὐθὺς εἶδον, ἐνέκειντο καὶ παραλύσαντες αὐτῶν τὸν κόσμον εἰς φόβον κατέστησαν."},{"number":91,"text":"καὶ οἱ μὲν ἀπορραγέντες ἔφευγον ἐπὶ τῶν πόλεων, οἱ δὲ πρὸς τὴν δίωξιν οὐκ ἔκαμνον, ἀλλʼ οἷς προπεπονήκεσαν προσεπιταλαιπωρῆσαι προθέμενοι, καὶ σφενδονᾶν τε ἄριστοι τυγχάνοντες καὶ πᾶσι τοῖς ἑκηβόλοις δεξιοὶ χρῆσθαι, καὶ διὰ τὴν ὅπλισιν οὖσαν εὐσταλῆ κοῦφοι πρὸς τὸ διώκειν ὄντες μετέθεον τοὺς πολεμίους καὶ τοὺς πορρωτάτω συλληφθῆναι γεγονότας ταῖς σφενδόναις καὶ τοῖς τοξεύμασι κατελάμβανον."},{"number":92,"text":"φόνος τε οὖν γίνεται πολὺς καὶ τραύμασιν ἐπόνουν οἱ διαφεύγοντες, ἔκαμνόν τε ἐπὶ δίψει μᾶλλον ἤ τινι τῶν πολεμικῶν, καὶ γὰρ ὥρα θέρους ἦν, καὶ ἐπιθυμίᾳ τοῦ πιεῖν. ἐπὶ ποταμὸν οὖν τοὺς πλείους καταραχθέντας, καὶ ὅσον συνεστραμμένον ἔφευγε, περιστάντες ἔβαλλον καὶ πάντας αὐτοὺς ἀκοντίζοντες ἅμα καὶ τοξεύοντες διέφθειραν."},{"number":93,"text":"ἀποθνήσκει δʼ αὐτῶν καὶ Σιχὼν ὁ βασιλεύς. Ἑβραῖοι δὲ νεκροὺς ἐσκύλευον καὶ λείαν ἔλαβον καὶ πολλὴν ἀφθονίαν τῶν ἐκ τῆς γῆς εἶχον μεστῆς ἔτι τῶν καρπῶν ὑπαρχούσης,"},{"number":94,"text":"καὶ διεξῄει πᾶσιν ἀδεῶς τὸ στράτευμα προνομῇ χρώμενον ἁλισκομένων καὶ τῶν πόλεων· οὐδὲν γὰρ παρὰ τούτων ἦν ἐμπόδιον τοῦ μαχίμου παντὸς ἀπολωλότος. Ἀμορραίους μὲν οὖν τοιοῦτο πάθος κατέλαβεν οὔτε φρονῆσαι δεινοὺς οὔτε ἀγαθοὺς κατὰ τὸ ἔργον γεγονότας, Ἑβραῖοι δὲ τὴν ἐκείνων παρελάμβανον."},{"number":95,"text":"ἔστι δὲ χωρίον, ὃ τριῶν μεταξὺ ποταμῶν κείμενον ὅμοιόν τι νήσῳ τὴν φύσιν ὑπάρχει, τοῦ μὲν Ἀρνῶνος ἀπὸ μεσημβρίας ὁρίζοντος αὐτό, Ἰοβάκου δὲ τὴν ἀρκτῴαν αὐτοῦ πλευρὰν περιγράφοντος, ὃς εἰς τὸν Ἰόρδανον ποταμὸν ἐκβάλλων ἐκείνῳ καὶ τοῦ ὀνόματος μεταδίδωσι, τὰ μέντοι γε πρὸς τῇ δύσει τοῦ χωρίου περίεισιν αὐτὴν Ἰόρδανος."},{"number":96,"text":"Οὕτως οὖν ἐχόντων τῶν πραγμάτων ἐπιτίθεται τοῖς Ἰσραηλίταις Ὤγης ὁ τῆς Γαλαδηνῆς καὶ Γαυλανίτιδος βασιλεὺς στρατὸν ἄγων, καὶ σπεύδων μὲν ὡς ἐπὶ συμμαχίαν τὴν Σιχῶνος φίλου τυγχάνοντος εὑρὼν δὲ ἐκεῖνον ἤδη προαπολωλότα καὶ οὕτως ἔγνω τοῖς Ἑβραίοις εἰς μάχην ἐλθεῖν περιέσεσθαί τε νομίζων καὶ τῆς ἀρετῆς αὐτῶν διάπειραν βουλόμενος λαβεῖν·"},{"number":97,"text":"διαμαρτὼν δὲ τῆς ἐλπίδος αὐτός τε ἀποθνήσκει κατὰ τὴν μάχην καὶ σύμπας ὁ στρατὸς αὐτοῦ διαφθείρεται. Μωυσῆς δὲ τὸν ποταμὸν Ἰόβακον περαιωσάμενος διεξῄει τῆς Ὤγου βασιλείας τάς τε πόλεις καταστρεφόμενος καὶ κτείνων πάντας τοὺς ἐνοικοῦντας, οἳ καὶ πλούτῳ διέφερον πάντων τῶν ἐκείνῃ ἠπειρωτῶν διʼ ἀρετὴν γῆς καὶ πλῆθος χρημάτων."},{"number":98,"text":"Ὤγης δὲ μέγεθός τε καὶ κάλλος ἦν οἷος ὀλίγοι σφόδρα, ἦν δὲ καὶ κατὰ χεῖρα γενναῖος ἀνήρ, ὡς ἴσα τὰ τῶν ἔργων εἶναι τοῖς τοῦ μεγέθους καὶ τῆς εὐπρεπείας πλεονεκτήμασι. τὴν δʼ ἰσχὺν αὐτοῦ καὶ τὸ μέγεθος ἐτεκμηριώσαντο κλίνην αὐτοῦ λαβόντες ἐν Ῥαβαθᾶ πόλει τῶν βασιλείων τῆς Ἀμμανίτιδος, τῇ μὲν κατασκευῇ σιδηρέαν, τεσσάρων δὲ πηχῶν τὸ εὖρος, μήκει δὲ τοῦ διπλασίονος ἑνὶ πήχει μείζονα."},{"number":99,"text":"τούτου τοίνυν πταίσαντος οὐκ εἰς τὸ παρὸν μόνον τοῖς Ἑβραίοις ἐπέδωκε τὰ πράγματα, ἀλλὰ καὶ πρὸς τὸ μέλλον ἀγαθῶν αὐτοῖς αἴτιος ἀποθανὼν ὑπῆρξε· καὶ γὰρ πόλεις ἑξήκοντα λαμπρῶς πάνυ τετειχισμένας ὑποτελεῖς ἐκείνῳ παρέλαβον καὶ λείαν πολλὴν ἰδίᾳ τε καὶ δημοσίᾳ πάντες εὐπόρησαν."}],"6":[{"number":100,"text":"Μωυσῆς μὲν οὖν στρατοπεδεύει καὶ ἀγαγὼν τὴν δύναμιν ἐπὶ τῷ Ἰορδάνῳ κατὰ τὸ μέγα πεδίον Ἱεριχοῦντος ἀντικρύ, πόλις δʼ ἐστὶν εὐδαίμων αὕτη φοίνικά τε φέρειν ἀγαθὴ καὶ βάλσαμον νεμομένη. ἤρχοντο δὲ φρονεῖν ἐφʼ ἑαυτοῖς μέγα Ἰσραηλῖται καὶ τὴν πρὸς τοὺς πολέμους ἐπιθυμίαν ὑπερέτεινον."},{"number":101,"text":"καὶ Μωυσῆς ὀλίγων ἡμερῶν θύσας χαριστήρια πρῶτον τῷ θεῷ καὶ τὸν λαὸν εὐωχήσας μέρος τι τῶν ὁπλιτῶν ἐξέπεμψε δῃῶσον τὴν Μαδιηνιτῶν γῆν καὶ τὰς πατρίδας αὐτῶν ἐκπολιορκῆσον. τοῦ δʼ ἐκπολεμηθῆναι πρὸς αὐτοὺς αἰτίαν ἔλαβε τοιαύτην."},{"number":102,"text":"Βάλακος ὁ τῶν Μωαβιτῶν βασιλεὺς φιλίας αὐτῷ πατρῴας οὔσης καὶ συμμαχίας πρὸς Μαδιηνίτας, ἐπεὶ τοὺς Ἰσραηλίτας τοσοῦτον φυομένους ἑώρα καὶ περὶ τῶν αὐτοῦ πραγμάτων λίαν εὐλαβεῖτο, καὶ γὰρ οὐδὲν πέπυστο γῆν ἄλλω πολυπραγμονεῖν τοὺς Ἑβραίους ἀπηγορευκότος τοῦ θεοῦ κτησαμένους τὴν Χαναναίων, θᾶττον ἢ φρονιμώτερον ἐγχειρεῖν ἔγνω τοῖς λόγοις."},{"number":103,"text":"καὶ πολεμεῖν μὲν ἐπὶ ταῖς εὐπραγίαις θρασύτερον ὑπὸ τῆς κακοπραγίας κατειλημμένοις οὐκ ἔκρινε, κωλῦσαι δʼ εἰ δύναιτο γενέσθαι μεγάλους λογιζόμενος πρεσβεῦσαι πρὸς Μαδιηνίτας ὑπὲρ αὐτῶν."},{"number":104,"text":"οἱ δέ, ἦν γάρ τις ἀπὸ Εὐφράτου Βάλαμος μάντις ἄριστος τῶν τότε καὶ πρὸς αὐτοὺς ἐπιτηδείως ἔχων, πέμπουσι μετὰ τῶν Βαλάκου πρέσβεων ἄνδρας τῶν παρʼ αὐτοῖς ἀξιολόγων παρακαλέσοντας τὸν μάντιν ἐλθεῖν, ὅπως ἐπʼ ἐξωλείᾳ τῶν Ἰσραηλιτῶν ἀρὰς ποιήσηται."},{"number":105,"text":"παραγενομένους δὲ τοὺς πρέσβεις δέχεται ξενίᾳ φιλοφρόνως καὶ δειπνίσας ἀνέκρινε τὴν τοῦ θεοῦ διάνοιαν, τίς αὕτη ἐστὶν ἐφʼ οἷς Μαδιηνῖται παρακαλοῦσι. τοῦ δʼ ἐμποδὼν στάντος ἀφικνεῖται πρὸς τοὺς πρέσβεις, προθυμίαν μὲν καὶ σπουδὴν τὴν ἰδίαν ἐμφανίζων αὐτοῖς εἰς ἃ δέονται τυχεῖν, τὸν δὲ θεὸν ἀντιλέγειν αὐτοῦ τῇ προαιρέσει δηλῶν, ὃς αὐτὸν ἐπὶ τοσοῦτον κλέος διʼ ἀλήθειαν καὶ τὴν ταύτης πρόρρησιν ἀγάγοι·"},{"number":106,"text":"τὸν γὰρ στρατόν, ᾧ καταρασόμενον αὐτὸν ἐλθεῖν παρακαλοῦσι, διʼ εὐνοίας εἶναι τῷ θεῷ· συνεβούλευέ τε διὰ ταύτην τὴν αἰτίαν χωρεῖν παρʼ αὐτοὺς τὴν ἔχθραν τὴν πρὸς τοὺς Ἰσραηλίτας καταλυσαμένους. καὶ τοὺς μὲν πρέσβεις ταῦτα εἰπὼν ἀπέλυσε."},{"number":107,"text":"Μαδιηνῖται δὲ Βαλάκου σφόδρα ἐγκειμένου καὶ δέησιν λιπαρὰν προσφέροντος πάλιν πέμπουσι πρὸς τὸν Βάλαμον. κἀκεῖνος βουλόμενος χαρίζεσθαί τι τοῖς ἀνδράσιν ἀνήρετο τὸν θεόν, ὁ δὲ καὶ τῆς πείρας δυσχεράνας κελεύει μηδὲν ἀντιλέγειν τοῖς πρέσβεσιν. ὁ δʼ οὐχ ὑπολαβὼν ἀπάτῃ ταῦτα τὸν θεὸν κεκελευκέναι συναπῄει τοῖς πρέσβεσι."},{"number":108,"text":"κατὰ δὲ τὴν ὁδὸν ἀγγέλου θείου προσβαλόντος αὐτῷ κατά τι στενὸν χωρίον περιειλημμένον αἱμασιαῖς διπλαῖς ἡ ὄνος, ἐφʼ ἧς ὁ Βάλαμος ὠχεῖτο, συνεῖσα τοῦ θείου πνεύματος ὑπαντῶντος ἀπέκλινε τὸν Βάλαμον πρὸς τὸν ἕτερον τῶν τριγχῶν ἀναισθήτως ἔχουσα τῶν πληγῶν, ἃς ὁ Βάλαμος ἐπέφερεν αὐτῇ κακοπαθῶν τῇ θλίψει τῇ πρὸς τὸν τριγχόν."},{"number":109,"text":"ὡς δʼ ἐγκειμένου τοῦ ἀγγέλου ἡ ὄνος τυπτομένη ὤκλασε, κατὰ βούλησιν θεοῦ φωνὴν ἀνθρωπίνην ἀφεῖσα κατεμέμφετο τὸν Βάλαμον ὡς ἄδικον ἐπὶ ταῖς πρότερον διακονίαις μηδὲν ἔχοντα ἐγκαλεῖν αὐτῇ πληγὰς ἐπιφέρειν μὴ συνιείς, ὅτι νῦν κατὰ θεοῦ προαίρεσιν οἷς αὐτὸς ἔσπευσεν ὑπηρετεῖν εἴργεται."},{"number":110,"text":"ταραττομένου δὲ αὐτοῦ διὰ τὴν τῆς ὄνου φωνὴν ἀνθρωπίνην οὖσαν ἐπιφανεὶς καὶ ὁ ἄγγελος ἐναργὴς ἐνεκάλει τῶν πληγῶν, ὡς οὐχὶ τοῦ κτήνους ὄντος αἰτίου, τὴν δὲ ὁδὸν αὐτοῦ διακωλύοντος παρὰ γνώμην τοῦ θεοῦ γενομένην."},{"number":111,"text":"καταδείσας δʼ ὁ Βάλαμος οἷός τε ἦν ἀναστρέφειν, ἀλλʼ ὁ θεὸς αὐτὸν χωρεῖν τὴν προκειμένην παρώρμησε προστάξας ὅτιπερ ἂν αὐτὸς κατὰ νοῦν αὐτῷ ποιήσειε τοῦτο σημαίνειν."},{"number":112,"text":"Καὶ ὁ μὲν ταῦτα τοῦ θεοῦ κελεύσαντος ἥκει πρὸς Βάλακον. δεξαμένου δὲ αὐτὸν τοῦ βασιλέως ἐκπρεπῶς ἠξίου προαχθεὶς ἐπί τι τῶν ὀρῶν σκέψασθαι, πῶς τὸ τῶν Ἑβραίων ἔχοι στρατόπεδον. Βάλακος δʼ αὐτὸς ἀφικνεῖται τὸν μάντιν σὺν βασιλικῇ θεραπείᾳ φιλοτίμως ἀγόμενος εἰς ὄρος, ὅπερ ὑπὲρ κεφαλῆς αὐτῶν ἔκειτο τοῦ στρατοπέδου σταδίους ἀπέχον ἑξήκοντα."},{"number":113,"text":"κατιδὼν δʼ αὐτοὺς ἐκεῖνος βωμούς τε ἐκέλευσεν ἑπτὰ δείμασθαι τὸν βασιλέα καὶ τοσούτους ταύρους καὶ κριοὺς παραστῆσαι· ὑπουργήσαντος δὲ διὰ ταχέων τοῦ βασιλέως ὁλοκαυτεῖ τυθέντας,"},{"number":114,"text":"ὡς τρόπον εἶδε σημαινομένην, ὁ λεώς, φησίν, οὗτος εὐδαίμων, ᾧ ὁ θεὸς δίδωσι μυρίων κτῆσιν ἀγαθῶν καὶ σύμμαχον εἰς ἅπαντα καὶ ἡγεμόνα τὴν ἑαυτοῦ πρόνοιαν ἐπένευσεν. ὡς οὐδέν ἐστιν ἀνθρώπινον γένος, οὗ μὴ κατʼ ἀρετὴν καὶ ζήλωσιν ἐπιτηδευμάτων ἀρίστων καὶ καθαρῶν πονηρίας ὑμεῖς ἀμείνους κριθήσεσθε καὶ παισὶ βελτίοσιν αὐτῶν ταῦτα καταλείψετε, θεοῦ μόνους ὑμᾶς ἀνθρώπους ἐφορῶντος καὶ ὅθεν ἂν γένοισθε πάντων εὐδαιμονέστεροι τῶν ὑπὸ τὸν ἥλιον ἐκπορίζοντος."},{"number":115,"text":"γῆν τε οὖν ἐφʼ ἣν ὑμᾶς αὐτὸς ἔστειλε καθέξετε δουλεύσουσαν αἰεὶ παισὶν ὑμετέροις καὶ τοῦ περὶ αὐτῶν κλέους ἐμπλησθήσεται πᾶσα ἡ γῆ καὶ θάλασσα, ἀρκέσετε δὲ τῷ κόσμῳ παρασχεῖν ἑκάστῃ γῇ τῶν ἀφʼ ὑμετέρου γένους οἰκήτορας."},{"number":116,"text":"θαυμάζετε οὖν, ὦ μακάριος στρατός, ὅτι τοσοῦτος ἐξ ἑνὸς πατρὸς γεγόνατε. ἀλλὰ τὸν νῦν ὑμῶν ὀλίγον ἡ Χαναναίων χωρήσει γῆ, τὴν δʼ οἰκουμένην οἰκητήριον διʼ αἰῶνος ἴστε προκειμένην ὑμῖν, καὶ τὸ πλῆθος ὑμῶν ἔν τε νήσοις καὶ κατʼ ἤπειρον βιοτεύσετε ὅσον ἐστὶν οὐδʼ ἀστέρων ἀριθμὸς ἐν οὐρανῷ. τοσούτοις δὲ οὖσιν οὐκ ἀπαγορεύσει τὸ θεῖον ἀφθονίαν μὲν παντοίων ἀγαθῶν ἐν εἰρήνῃ χορηγοῦν, νίκην δὲ καὶ κράτος ἐν πολέμῳ."},{"number":117,"text":"παῖδας ἐχθρῶν ἔρως τοῦ πρὸς ὑμᾶς πολέμου λάβοι καὶ θρασυνθεῖεν ὥστε εἰς ὅπλα καὶ τὰς ὑμετέρας χεῖρας ἐλθεῖν· οὐ γὰρ ἂν ὑποστρέψειέ τις νικηφόρος οὐδʼ ὥστε παῖδας εὐφρᾶναι καὶ γυναῖκας. τοσοῦτον ὑμῖν ἀνδρείας τὸ περιὸν ἐκ θεοῦ προνοίας ἀνῄρηται, ᾧ καὶ τὰ περιττὰ μειοῦν ἰσχὺς καὶ τὰ λείποντα διδόναι."},{"number":118,"text":"Καὶ ὁ μὲν τοιαῦτα ἐπεθείαζεν οὐκ ὢν ἐν ἑαυτῷ τῷ δὲ θείῳ πνεύματι πρὸς αὐτὰ νενικημένος. τοῦ δὲ Βαλάκου δυσχεραίνοντος καὶ παραβαίνειν αὐτὸν τὰς συνθήκας ἐφʼ αἷς αὐτὸν ἀντὶ μεγάλων λάβοι δωρεῶν παρὰ τῶν συμμάχων ἐπικαλοῦντος, ἐλθόντα γὰρ ἐπὶ κατάρᾳ τῶν πολεμίων ὑμνεῖν αὐτοὺς ἐκείνους καὶ μακαριωτάτους ἀποφαίνειν ἀνθρώπων,"},{"number":119,"text":"ὦ Βάλακε, φησί, περὶ τῶν ὅλων λογίζῃ καὶ δοκεῖς ἐφʼ ἡμῖν εἶναί τι περὶ τῶν τοιούτων σιγᾶν ἢ λέγειν, ὅταν ἡμᾶς τὸ τοῦ θεοῦ λάβῃ πνεῦμα; φωνὰς γὰρ ἃς βούλεται τοῦτο καὶ λόγους οὐδὲν ἡμῶν εἰδότων ἀφίησιν."},{"number":120,"text":"ἐγὼ δὲ μέμνημαι μὲν ὧντε καὶ σὺ καὶ Μαδιηνῖται δεηθέντες ἐνταυθοῖ με προθύμως ἠγάγετε καὶ διʼ ἃ τὴν ἄφιξιν ἐποιησάμην, ἦν τέ μοι διʼ εὐχῆς μηδὲν ἀδικῆσαί σου τὴν ἐπιθυμίαν."},{"number":121,"text":"κρείττων δὲ ὁ θεὸς ὧν ἐγὼ χαρίζεσθαι διεγνώκειν· καὶ παντελῶς ἀσθενεῖς οἱ προγινώσκειν περὶ τῶν ἀνθρωπίνων παρʼ ἑαυτῶν ὑπολαμβάνοντες, ὡς μὴ ταῦθʼ ἅπερ ὑπαγορεύει τὸ θεῖον λέγειν, βιάζεσθαι δὲ τὴν ἐκείνου βούλησιν·"},{"number":122,"text":"οὐδὲν γὰρ ἐν ἡμῖν ἔτι φθάσαντος εἰσελθεῖν ἐκείνου ἡμέτερον. ἔγωγʼ οὖν τὸν στρατὸν τοῦτον οὔτʼ ἐπαινέσαι προεθέμην οὔτʼ ἐφʼ οἷς τὸ γένος αὐτῶν ὁ θεὸς ἀγαθοῖς ἐμηχανήσατο διελθεῖν, ἀλλʼ εὐμενὴς αὐτοῖς οὗτος ὢν καὶ σπεύδων αὐτοῖς εὐδαίμονα βίον καὶ κλέος αἰώνιον παρασχεῖν ἐμοὶ τοιούτων ἀπαγγελίαν λόγων ὑπέθετο."},{"number":123,"text":"νῦν δέ, χαρίζεσθαί τε γὰρ αὐτῷ σοὶ διὰ σπουδῆς ἐστί μοι καὶ Μαδιηνίταις, ὧν ἀπώσασθαί μοι τὴν ἀξίωσιν οὐκ εὐπρεπές, φέρε βωμούς τε ἑτέρους αὖθις ἐγείρωμεν καὶ θυσίας ταῖς πρὶν παραπλησίας ἐπιτελέσωμεν, εἰ πεῖσαι τὸν θεὸν δυνηθείην ἐπιτρέψαι μοι τοὺς ἀνθρώπους ἀραῖς ἐνδῆσαι."},{"number":124,"text":"συγχωρήσαντος δὲ τοῦ Βαλάκου δὶς μὲν τεθυκότι τὸ θεῖον οὐκ ἐπένευσε τὰς κατὰ τῶν Ἰσραηλιτῶν ἀράς, θύσας δὲ καὶ τρίτον ἄλλων πάλιν ἀνασταθέντων βωμῶν οὐδὲ τότε μὲν κατηράσατο τοῖς Ἰσραηλίταις,"},{"number":125,"text":"πεσὼν δʼ ἐπὶ στόμα πάθη προύλεγεν ὅσα τε βασιλεῦσιν ἔσται καὶ ὅσα πόλεσι ταῖς ἀξιολογωτάταις, ὧν ἐνίαις οὐδʼ οἰκεῖσθαί πω συνέβαινε τὴν ἀρχήν, ἅ τε καὶ προϋπῆρξεν ἐν τοῖς ἔμπροσθεν χρόνοις γενόμενα τοῖς ἀνθρώποις διὰ γῆς ἢ θαλάσσης εἰς μνήμην τὴν ἐμήν. ἐξ ὧν ἁπάντων λαβόντων τέλος ὁποῖον ἐκεῖνος προεῖπε τεκμαίροιτʼ ἄν τις, ὅ τι καὶ ἔσοιτο πρὸς τὸ μέλλον."},{"number":126,"text":"Βάλακος δὲ ἀγανακτήσας ἐπὶ τῷ μὴ καταράτους γενέσθαι τοὺς Ἰσραηλίτας ἀποπέμπει τὸν Βάλαμον μηδεμιᾶς τιμῆς ἀξιώσας· ὁ δὲ ἀπιὼν ἤδη κἀπὶ τῷ περαιοῦν τὸν Εὐφράτην γενόμενος τόν τε Βάλακον μεταπεμψάμενος καὶ τοὺς ἄρχοντας τῶν Μαδιηνιτῶν"},{"number":127,"text":"Βάλακε, φησί, καὶ Μαδιηνιτῶν οἱ παρόντες, χρὴ γὰρ καὶ παρὰ βούλησιν τοῦ θεοῦ χαρίσασθαι ὑμῖν, τὸ μὲν Ἑβραίων γένος οὐκ ἂν ὄλεθρος παντελὴς καταλάβοι οὔτʼ ἐν πολέμῳ οὔτʼ ἐν λοιμῷ καὶ σπάνει τῶν ἀπὸ γῆς καρπῶν, οὔτʼ ἄλλη τις αἰτία παράλογος διαφθείρειεν."},{"number":128,"text":"πρόνοια γάρ ἐστιν αὐτῶν τῷ θεῷ σώζειν ἀπὸ παντὸς κακοῦ καὶ μηδὲν ἐπʼ αὐτοὺς ἐᾶσαι τοιοῦτον πάθος ἐλθεῖν, ὑφʼ οὗ κἂν ἀπόλοιντο πάντες· συμπέσοι δʼ αὐτοῖς ὀλίγα τε καὶ πρὸς ὀλίγον, ὑφʼ ὧν ταπεινοῦσθαι δοκοῦντες εἶτʼ ἀνθήσουσιν ἐπὶ φόβῳ τῶν ἐπαγαγόντων αὐτοῖς τὰς βλάβας."},{"number":129,"text":"ὑμεῖς δʼ εἰ νίκην τινὰ πρὸς βραχὺν καιρὸν κατʼ αὐτῶν κερδᾶναι ποθεῖτε, τύχοιτʼ ἂν αὐτῆς ταῦτα ποιήσαντες· τῶν θυγατέρων τὰς μάλιστα εὐπρεπεῖς καὶ βιάσασθαι καὶ νικῆσαι τὴν τῶν ὁρώντων σωφροσύνην ἱκανὰς διὰ τὸ κάλλος ἀσκήσαντες τὴν εὐμορφίαν αὐτῶν ἐπὶ τὸ μᾶλλον εὐπρεπὲς πέμψατε πλησίον ἐσομένας τοῦ ἐκείνων στρατοπέδου, καὶ δεομένοις συνεῖναι τοῖς νεανίαις αὐτῶν προστάξατε."},{"number":130,"text":"ἐπειδὰν δὲ κεχειρωμένους ὁρῶσι ταῖς ἐπιθυμίαις, καταλιπέτωσαν καὶ παρακαλούντων μένειν μὴ πρότερον ἐπινευέτωσαν, πρὶν ἂν πείσωσιν αὐτοὺς ἀφέντας τοὺς πατρίους νόμους καὶ τὸν τούτους αὐτοῖς θέμενον τιμᾶν θεὸν τοὺς Μαδιηνιτῶν καὶ Μωαβιτῶν σέβωσιν· οὕτως γὰρ αὐτοῖς τὸν θεὸν ὀργισθήσεσθαι. καὶ ὁ μὲν τοῦθʼ ὑποθέμενος αὐτοῖς ᾤχετο."},{"number":131,"text":"Τῶν δὲ Μαδιηνιτῶν πεμψάντων τὰς θυγατέρας κατὰ τὴν ἐκείνου παραίνεσιν οἱ τῶν Ἑβραίων ἁλίσκονται νέοι τῆς εὐπρεπείας αὐτῶν καὶ παραγενόμενοι εἰς λόγους αὐταῖς παρεκάλουν μὴ φθονεῖν αὐτοῖς τῆς τοῦ κάλλους αὐτῶν ἀπολαύσεως μηδὲ τῆς τοῦ πλησιάζειν συνηθείας· αἱ δʼ ἀσμένως δεξάμεναι τοὺς λόγους συνῄεσαν αὐτοῖς."},{"number":132,"text":"ἐνδησάμεναι δʼ αὐτοὺς τῷ πρὸς αὐτὰς ἔρωτι καὶ τῆς ἐπιθυμίας ἀκμαζούσης περὶ ἀπαλλαγὴν ἐγίνοντο. τοὺς δʼ ἀθυμία πολλὴ πρὸς τὴν ἀναχώρησιν τῶν γυναικῶν κατέλαβε καὶ λιπαροῦντες ἐνέκειντο, μὴ σφᾶς καταλιπεῖν, ἀλλὰ γαμετὰς αὐτῶν ἐσομένας αὐτόθι μένειν καὶ δεσποίνας ἀποδειχθησομένας πάντων ὧν ὑπῆρχεν αὐτοῖς."},{"number":133,"text":"ταῦτα δὲ ὀμνύντες ἔλεγον καὶ θεὸν μεσίτην ὧν ὑπισχνοῦντο ποιούμενοι δακρύοντές τε καὶ πανταχόθεν αὑτοὺς ἐλεεινοὺς ταῖς γυναιξὶ κατασκευάζοντες εἶναι. αἱ δʼ ὡς δεδουλωμένους αὐτοὺς κατενόησαν καὶ τελέως ὑπὸ τῆς συνηθείας ἐχομένους, ἤρξαντο πρὸς αὐτοὺς λέγειν·"},{"number":134,"text":"Ἡμῖν, ὦ κράτιστοι νέων, οἶκοί τέ εἰσι πατρῷοι καὶ κτῆσις ἀγαθῶν ἄφθονος καὶ ἡ παρὰ τῶν γονέων καὶ τῶν οἰκείων εὔνοια καὶ στοργή, καὶ κατʼ οὐδενὸς τούτων πόρον ἐνθάδʼ ἥκουσαι ἡμεῖς εἰς ὁμιλίαν ἥκομεν, οὐδʼ ἐμπορευσόμεναι τὴν ὥραν τοῦ σώματος προσηκάμεθα τὴν ὑμετέραν ἀξίωσιν, ἀλλʼ ἄνδρας ἀγαθοὺς καὶ δικαίους ὑπολαβοῦσαι τοιούτοις ὑμᾶς τιμῆσαι ξενίοις δεομένους ἐπείσθημεν."},{"number":135,"text":"καὶ νῦν, ἐπεί φατε πρὸς ἡμᾶς φιλοστόργως ἔχειν καὶ λυπεῖσθε μελλουσῶν ἀναχωρεῖν, οὐδʼ αὐταὶ τὴν δέησιν ὑμῶν ἀποστρεφόμεθα, πίστιν δʼ εὐνοίας λαβοῦσαι τὴν μόνην ἡμῖν ἀξιόλογον νομισθεῖσαν ἀγαπήσομεν τὸν μεθʼ ὑμῶν βίον ὡς γαμεταὶ διανύσαι."},{"number":136,"text":"δέος γάρ, μὴ καὶ κόρον τῆς ἡμετέρας ὁμιλίας λαβόντες ἔπειθʼ ὑβρίσητε καὶ ἀτίμους ἀποπέμψητε πρὸς τοὺς γονεῖς. συγγινώσκειν τε ταῦτα φυλαττομέναις ἠξίουν. τῶν δὲ ἣν βούλονται πίστιν δώσειν ὁμολογούντων καὶ πρὸς τὸ μηδὲν ἀντιλεγόντων ὑπὸ τοῦ πρὸς αὐτὰς πάθους ἐπεὶ ταῦτα ὑμῖν,"},{"number":137,"text":"ἔφασαν, δέδοκται, τοῖς δʼ ἔθεσι καὶ τῷ βίῳ πρὸς ἅπαντας ἀλλοτριώτατα χρῆσθε, ὡς καὶ τὰς τροφὰς ὑμῖν ἰδιοτρόπους εἶναι καὶ τὰ ποτὰ μὴ κοινὰ τοῖς ἄλλοις, ἀνάγκη βουλομένους ἡμῖν συνοικεῖν καὶ θεοὺς τοὺς ἡμετέρους σέβειν, καὶ οὐκ ἂν ἄλλο γένοιτο τεκμήριον ἧς ἔχειν τε νῦν φατε πρὸς ἡμᾶς εὐνοίας καὶ τῆς ἐσομένης ἢ τὸ τοὺς αὐτοὺς ἡμῖν θεοὺς προσκυνεῖν."},{"number":138,"text":"μέμψαιτο δʼ ἂν οὐδείς, εἰ γῆς εἰς ἣν ἀφῖχθε τοὺς ἰδίους αὐτῆς θεοὺς προστρέποισθε καὶ ταῦτα τῶν μὲν ἡμετέρων κοινῶν ὄντων πρὸς ἅπαντας, τοῦ δʼ ὑμετέρου πρὸς μηδένα τοιούτου τυγχάνοντος. δεῖν οὖν αὐτοῖς ἔλεγον ἢ ταὐτὰ πᾶσιν ἡγητέον ἢ ζητεῖν ἄλλην οἰκουμένην, ἐν ᾗ βιώσονται μόνοι κατὰ τοὺς ἰδίους νόμους."},{"number":139,"text":"Οἱ δʼ ὑπὸ τοῦ πρὸς αὐτὰς ἔρωτος κάλλιστα λέγεσθαι ταῦτα ὑπολαβόντες καὶ παραδόντες αὑτοὺς εἰς ἃ προεκαλοῦντο παρέβησαν τὰ πάτρια, θεούς τε πλείονας εἶναι νομίσαντες καὶ θύειν αὐτοῖς κατὰ νόμον τὸν ἐπιχώριον τοῖς καθιδρυσαμένοις προθέμενοι ξενικοῖς τε βρώμασιν ἔχαιρον καὶ πάντʼ εἰς ἡδονὴν τῶν γυναικῶν ἐπὶ τοὐναντίον οἷς ὁ νόμος αὐτῶν ἐκέλευε ποιοῦντες διετέλουν,"},{"number":140,"text":"ὡς διὰ παντὸς ἤδη τοῦ στρατοῦ τὴν παρανομίαν χωρεῖν τῶν νέων καὶ στάσιν αὐτοῖς πολὺ χείρω τῆς προτέρας ἐμπεσεῖν καὶ κίνδυνον παντελοῦς τῶν ἰδίων ἐθισμῶν ἀπωλείας. ἅπαξ γὰρ τὸ νέον γευσάμενον ξενικῶν ἐθισμῶν ἀπλήστως ἐνεφορεῖτο, καὶ εἴ τινες τῶν πρώτων ἀνδρῶν διὰ πατέρων ἀρετὰς ἐπιφανεῖς ἦσαν συνδιεφθείροντο,"},{"number":141,"text":"καὶ Ζαμβρίας ὁ τῆς Σεμεωνίδος ἡγούμενος φυλῆς Χοσβίᾳ συνὼν Μαδιανίτιδι Οὔρου θυγατρὶ τῶν ἐκείνῃ δυναστεύοντος ἀνδρὸς κελευσθεὶς ὑπὸ τῆς γυναικὸς πρὸ τῶν Μωυσεῖ δοχθέντων τὸ πρὸς ἡδονὴν αὐτῇ γενησόμενον ἐθεράπευεν."},{"number":142,"text":"ἐν τούτοις δʼ ὄντων τῶν πραγμάτων δείσας Μωυσῆς, μὴ γένηταί τι χεῖρον, συναγαγὼν εἰς ἐκκλησίαν τὸν λαὸν οὐδενὸς μὲν κατηγόρει πρὸς ὄνομα μὴ βουλόμενος εἰς ἀπόνοιαν περιστῆσαι τοὺς ἐκ τοῦ λανθάνειν μετανοῆσαι δυναμένους,"},{"number":143,"text":"ἔλεγε δʼ ὡς οὐκ ἄξια δρῷεν οὔτʼ αὐτῶν οὔτε πατέρων τὴν ἡδονὴν προτιμήσαντες τοῦ θεοῦ καὶ τοῦ κατὰ τοῦτον βίου. προσήκειν δʼ ἕως ἔτι καὶ καλῶς αὐτοῖς ἂν ἔχοι μεταβαλέσθαι, τὴν ἀνδρείαν ὑπολαμβάνουσιν οὐκ ἐν τῷ βιάζεσθαι τοὺς νόμους ἀλλʼ ἐν τῷ μὴ εἴκειν ταῖς ἐπιθυμίαις εἶναι."},{"number":144,"text":"πρὸς τούτοις δʼ οὐδʼ εὔλογον ἔφασκε σωφρονήσαντας αὐτοὺς ἐπὶ τῆς ἐρήμου νῦν ἐν τοῖς ἀγαθοῖς ὄντας παροινεῖν, μηδὲ τὰ κτηθέντα ὑπὸ τῆς ἐνδείας διʼ εὐπορίαν αὐτῶν ἀπολέσθαι. καὶ ὁ μὲν ταῦτα λέγων ἐπειρᾶτο τοὺς νέους ἐπανορθοῦν καὶ εἰς μετάνοιαν ἄγειν ὧν ἔπραττον."},{"number":145,"text":"Ἀναστὰς δὲ μετʼ αὐτὸν Ζαμβρίας ἀλλὰ σὺ μέν, εἶπεν, ὦ Μωυσῆ, χρῶ νόμοις οἷς αὐτὸς ἐσπούδακας ἐκ τῆς τούτων εὐηθείας τὸ βέβαιον αὐτοῖς παρεσχημένος· ἐπεὶ μὴ τοῦτον αὐτῶν ἐχόντων τὸν τρόπον πολλάκις ἂν ἤδη κεκολασμένος ἔγνως ἂν οὐκ εὐπαραλογίστους Ἑβραίους."},{"number":146,"text":"ἐμὲ δʼ οὐκ ἂν ἀκόλουθον οἷς σὺ προστάττεις τυραννικῶς λάβοις· οὐ γὰρ ἄλλο τι μέχρι νῦν ἢ προσχήματι νόμων καὶ τοῦ θεοῦ δουλείαν μὲν ἡμῖν ἀρχὴν δὲ σαυτῷ κακουργεῖς ἀφαιρούμενος ἡμᾶς τὸ ἡδὺ καὶ τὸ κατὰ τὸν βίον αὐτεξούσιον, ὃ τῶν ἐλευθέρων ἐστὶ καὶ δεσπότην οὐκ ἐχόντων."},{"number":147,"text":"χαλεπώτερος δʼ ἂν οὕτως Αἰγυπτίων Ἑβραίοις γένοιο τιμωρεῖν ἀξιῶν κατὰ τοὺς νόμους τὴν ἑκάστου πρὸς τὸ κεχαρισμένον αὐτῷ βούλησιν. πολὺ δʼ ἂν δικαιότερον αὐτὸς τιμωρίαν ὑπομένοις τὰ παρʼ ἑκάστοις ὁμολογούμενα καλῶς ἔχειν ἀφανίσαι προῃρημένος καὶ κατὰ τῆς ἁπάντων δόξης ἰσχυρὰν τὴν σεαυτοῦ κατεσκευακὼς ἀτοπίαν·"},{"number":148,"text":"ἐγὼ δʼ ἂν στεροίμην εἰκότως ὧν πράττω νυνὶ κρίνας ἀγαθὰ ταῦτʼ ἔπειτα περὶ αὐτῶν ὁμολογεῖν ἐν τούτοις οὐκ ὀκνήσαιμι. γύναιόν τε ξενικόν, ὡς φῄς, ἦγμαι· παρʼ ἐμαυτοῦ γὰρ ἀκούσῃ τὰς ἐμὰς πράξεις ὡς παρὰ ἐλευθέρου, καὶ γὰρ οὐδὲ λαθεῖν προεθέμην·"},{"number":149,"text":"θύω τε θεοῖς οἷς θύειν μοι νομίζεται δίκαιον ἡγούμενος παρὰ πολλῶν ἐμαυτῷ πραγματεύεσθαι τὴν ἀλήθειαν, καὶ οὐχ ὥσπερ ἐν τυραννίδι ζῆν τὴν ὅλην ἐξ ἑνὸς ἐλπίδα τοῦ βίου παντὸς ἀνηρτηκότα· χαρείη τʼ ἂν οὐδεὶς κυριώτερον αὑτὸν περὶ ὧν πράξαιμι γνώμης τῆς ἐμῆς ἀποφαινόμενος."},{"number":150,"text":"Τοῦ δὲ Ζαμβρίου ταῦτα περὶ ὧν αὐτός τε ἠδίκει καὶ τῶν ἄλλων τινὲς εἰπόντος ὁ μὲν λαὸς ἡσύχαζε φόβῳ τε τοῦ μέλλοντος καὶ τὸν νομοθέτην δὲ ὁρῶν μὴ περαιτέρω τὴν ἀπόνοιαν αὐτοῦ προαγαγεῖν ἐκ τῆς ἄντικρυς διαμάχης θελήσαντα·"},{"number":151,"text":"περιίστατο γάρ, μὴ πολλοὶ τῆς τῶν λόγων ἀσελγείας αὐτοῦ μιμηταὶ γενόμενοι ταράξωσι τὸ πλῆθος. καὶ διαλύεται μὲν ἐπὶ τούτοις ὁ σύλλογος. προεληλύθει δʼ ἂν ἐπὶ πλεῖον ἡ τοῦ κακοῦ πεῖρα μὴ φθάσαντος Ζαμβρία τελευτῆσαι ἐκ τοιαύτης αἰτίας."},{"number":152,"text":"Φινεὲς ἀνὴρ τά τε ἄλλα τῶν νεωτέρων κρείττων καὶ τοῦ πατρὸς ἀξιώματι τοὺς ἡλικιώτας ὑπερέχων, Ἐλεαζάρου γὰρ τοῦ ἀρχιερέως ἦν, περιαλγήσας τοῖς πεπραγμένοις ὑπὸ τοῦ Ζαμβρίου, καὶ πρὶν ἰσχυροτέραν γενέσθαι τὴν ὕβριν ὑπὸ τῆς ἀδείας ἔργῳ τὴν δίκην αὐτὸν εἰσπράξασθαι διαγνοὺς καὶ κωλῦσαι διαβῆναι τὴν παρανομίαν εἰς πλείονας τῶν ἀρξαμένων οὐ κολαζομένων,"},{"number":153,"text":"τόλμῃ δὲ καὶ ψυχῆς καὶ σώματος ἀνδρείᾳ τοσοῦτον προύχων, ὡς μὴ πρότερον εἴ τινι συσταίη τῶν δεινῶν ἀπαλλάττεσθαι, πρὶν ἢ καταγωνίσασθαι καὶ νίκην τὴν ἐπʼ αὐτῷ λαβεῖν, ἐπὶ τὴν τοῦ Ζαμβρίου σκηνὴν παραγενόμενος αὐτόν τε παίων τῇ ῥομφαίᾳ καὶ τὴν Χοσβίαν ἀπέκτεινεν."},{"number":154,"text":"οἱ δὲ νέοι πάντες, οἷς ἀρετῆς ἀντιποίησις ἦν καὶ τοῦ φιλοκαλεῖν, μιμηταὶ γενόμενοι τῆς Φινεέσσου τόλμης ἀνῄρουν τοὺς ἐπὶ τοῖς ὁμοίοις Ζαμβρίᾳ τὴν αἰτίαν εἰληφότας. ἀπόλλυνται μὲν οὖν καὶ ὑπὸ τῆς τούτων ἀνδραγαθίας πολλοὶ τῶν παρανομησάντων,"},{"number":155,"text":"ἐφθάρησαν δὲ πάντες καὶ λοιμῷ ταύτην ἐνσκήψαντος αὐτοῖς τοῦ θεοῦ τὴν νόσον ὅσοι τε συγγενεῖς ὄντες κωλύειν δέον ἐξώτρυνον αὐτοὺς ἐπὶ ταῦτα ἀδικεῖν τῷ θεῷ δοκοῦντες ἀπέθνησκον. ἀπόλλυνται μὲν οὖν ἐκ τῶν τάξεων ἄνδρες οὐκ ἐλάττους τετρακισχιλίων καὶ μυρίων."},{"number":156,"text":"Ὑπὸ δὲ ταύτης παροξυνθεὶς τῆς αἰτίας Μωυσῆς ἐπὶ τὸν Μαδιανιτῶν ὄλεθρον τὴν στρατιὰν ἐξέπεμπε, περὶ ὧν τῆς ἐπʼ αὐτοὺς ἐξόδου μετὰ μικρὸν ἀπαγγελοῦμεν προδιηγησάμενοι πρῶτον ὃ παρελίπομεν· δίκαιον γὰρ ἐπὶ τούτου τὴν τοῦ νομοθέτου γνώμην μὴ παρελθεῖν ἀνεγκωμίαστον."},{"number":157,"text":"τὸν γὰρ Βάλαμον παραληφθέντα ὑπὸ τῶν Μαδιηνιτῶν, ὅπως ἐπαράσηται τοῖς Ἑβραίοις, καὶ τοῦτο μὲν οὐ δυνηθέντα θείᾳ προνοίᾳ, γνώμην δὲ ὑποθέμενον, ᾗ χρησαμένων τῶν πολεμίων ὀλίγου τὸ τῶν Ἑβραίων πλῆθος διεφθάρη τοῖς ἐπιτηδεύμασι νοσησάντων δή τινων περὶ ταῦτα, μεγάλως ἐτίμησεν ἀναγράψας αὐτοῦ τὰς μαντείας,"},{"number":158,"text":"καὶ παρὸν αὐτῷ σφετερίσασθαι τὴν ἐπʼ αὐτοῖς δόξαν καὶ ἐξιδιώσασθαι μηδενὸς ἂν γενομένου μάρτυρος τοῦ διελέγξοντος, ἐκείνῳ τὴν μαρτυρίαν ἔδωκε καὶ τῆς ἐπʼ αὐτῷ μνήμης ἠξίωσε. καὶ ταῦτα μὲν ὡς ἂν αὐτοῖς τισι δοκῇ οὕτω σκοπείτωσαν."}],"7":[{"number":159,"text":"Μωυσῆς δὲ ὑπὲρ ὧν καὶ προεῖπον ἐπὶ τὴν Μαδιηνιτῶν γῆν ἔπεμψεν στρατιὰν τοὺς πάντας εἰς δισχιλίους καὶ μυρίους ἐξ ἑκάστης φυλῆς τὸν ἴσον ἀριθμὸν ἐπιλεξάμενος, στρατηγὸν δʼ αὐτῶν ἀπέδειξε Φινεές, οὗ μικρῷ πρότερον ἐμνήσθημεν φυλάξαντος τοῖς Ἑβραίοις τοὺς νόμους καὶ τὸν παρανομοῦντα τούτους Ζαμβρίαν τιμωρησαμένου."},{"number":160,"text":"Μαδιηνῖται δὲ προπυθόμενοι τὸν στρατὸν ἐπὶ σφᾶς ἐλαύνοντα καὶ ὅσον οὐδέπω παρεσόμενον ἠθροίζοντό τε καὶ τὰς εἰσβολὰς τῆς χώρας, ᾗ προσεδέχοντο τοὺς πολεμίους, ἀσφαλισάμενοι περιέμενον αὐτούς."},{"number":161,"text":"ἐλθόντων δὲ καὶ συμβολῆς γενομένης πίπτει τῶν Μαδιηνιτῶν πλῆθος ἀσυλλόγιστον καὶ ἀριθμοῦ κρεῖττον οἵ τε βασιλεῖς αὐτῶν ἅπαντες· πέντε δὲ ἦσαν, Ὦχός τε καὶ Σούρης ἔτι δὲ Ῥοβέης καὶ Οὔρης, πέμπτος δὲ Ῥέκεμος, οὗ πόλις ἐπώνυμος τὸ πᾶν ἀξίωμα τῆς Ἀράβων ἔχουσα γῆς καὶ μέχρι νῦν ὑπὸ παντὸς τοῦ Ἀραβίου τοῦ κτίσαντος βασιλέως τὸ ὄνομα Ῥεκέμης καλεῖται, Πέτρα παρʼ Ἕλλησι λεγομένη."},{"number":162,"text":"τραπέντων δὲ τῶν πολεμίων οἱ Ἑβραῖοι διήρπασαν αὐτῶν τὴν χώραν καὶ πολλὴν λείαν λαβόντες καὶ τοὺς οἰκήτορας γυναιξὶν ἅμα διαφθείραντες μόνας τὰς παρθένους κατέλιπον, τοῦτο Μωυσέος Φινέει κελεύσαντος."},{"number":163,"text":"ὃς ἧκεν ἄγων τὸν στρατὸν ἀπαθῆ καὶ λείαν ἄφθονον, βόας μὲν γὰρ δισχιλίους καὶ πεντακισμυρίους, ὄις δὲ πεντακισχιλίας πρὸς μυριάσιν ἑπτὰ καὶ ἑξήκοντα, ὄνους δὲ ἑξακισμυρίας, χρυσοῦ δὲ καὶ ἀργύρου ἄπειρόν τι πλῆθος κατασκευῆς, ᾗ κατʼ οἶκον ἐχρῶντο· ὑπὸ γὰρ εὐδαιμονίας καὶ ἁβροδίαιτοι σφόδρα ἐτύγχανον. ἤχθησαν δὲ καὶ αἱ παρθένοι περὶ δισχιλίας καὶ τρισμυρίας."},{"number":164,"text":"Μωυσῆς δὲ μερίσας τὴν λείαν τῆς μὲν ἑτέρας τὸ πεντηκοστὸν Ἐλεαζάρῳ δίδωσι καὶ τοῖς ἱερεῦσι, Λευίταις δὲ τῆς ἑτέρας τὸ πεντηκοστὸν μέρος, τὴν δὲ λοιπὴν νέμει τῷ λαῷ. καὶ διῆγον τὸ λοιπὸν εὐδαιμόνως, ἀφθονίας μὲν ἀγαθῶν αὐτοῖς ὑπʼ ἀρετῆς γεγενημένης, ὑπὸ μηδενὸς δὲ σκυθρωποῦ ταύτης ἀπολαύειν ἐμποδιζόμενοι."},{"number":165,"text":"Μωυσῆς δὲ γηραιὸς ἤδη τυγχάνων διάδοχον ἑαυτοῦ Ἰησοῦν καθίστησιν ἐπί τε ταῖς προφητείαις καὶ στρατηγὸν εἴ που δεήσειε γενησόμενον, κελεύσαντος καὶ τοῦ θεοῦ τούτῳ τὴν προστασίαν ἐπιτρέψαι τῶν πραγμάτων. ὁ δὲ Ἰησοῦς πᾶσαν ἐπεπαίδευτο τὴν περὶ τοὺς νόμους παιδείαν καὶ τὸ θεῖον Μωυσέος ἐκδιδάξαντος."},{"number":166,"text":"Κἀν τούτῳ δύο φυλαὶ Γαδίς τε καὶ Ῥουβήλου καὶ τῆς Μανασσίτιδος ἡμίσεια πλήθει τετραπόδων εὐδαιμονοῦντες καὶ τοῖς ἄλλοις ἅπασι, κοινολογησάμενοι παρεκάλουν τὸν Μωυσῆν ἐξαίρετον αὐτοῖς τὴν Ἀμορῖτιν παρασχεῖν δορίκτητον οὖσαν· ἀγαθὴν γὰρ εἶναι βοσκήματα τρέφειν."},{"number":167,"text":"ὁ δʼ ὑπολαβὼν αὐτοὺς δείσαντας τὴν πρὸς Χαναναίους μάχην πρόφασιν εὐπρεπῆ τὴν τῶν βοσκημάτων ἐπιμέλειαν εὑρῆσθαι κακίστους τε ἀπεκάλει καὶ δειλίας εὐσχήμονα πρόφασιν ἐπινοήσαντας αὐτοὺς μὲν βούλεσθαι τρυφᾶν ἀπόνως διάγοντας πάντων τεταλαιπωρηκότων ὑπὲρ τοῦ κτήσασθαι τὴν αἰτουμένην ὑπʼ αὐτῶν γῆν,"},{"number":168,"text":"μὴ θέλειν δὲ συναραμένους τῶν ἐπιλοίπων ἀγώνων γῆν ἣν διαβᾶσιν αὐτοῖς τὸν Ἰορδάνην ὁ θεὸς παραδώσειν ὑπέσχηται ταύτην λαβεῖν καταστρεψαμένους οὓς ἐκεῖνος ἀπέδειξεν ἡμῖν πολεμίους."},{"number":169,"text":"οἱ δʼ ὁρῶντες ὀργιζόμενον αὐτὸν καὶ δικαίως ἠρεθίσθαι πρὸς τὴν ἀξίωσιν αὐτῶν ὑπολαβόντες ἀπελογοῦντο μὴ διὰ φόβον κινδύνων μηδὲ διὰ τὴν πρὸς τὸ πονεῖν μαλακίαν πεποιῆσθαι τὴν αἴτησιν,"},{"number":170,"text":"ἀλλʼ ὅπως τὴν λείαν ἐν ἐπιτηδείοις καταλιπόντες εὔζωνοι πρὸς τοὺς ἀγῶνας καὶ τὰς μάχας χωρεῖν δύναιντο, ἑτοίμους τε ἔλεγον ἑαυτοὺς κτίσαντας πόλεις εἰς φυλακὴν τέκνων καὶ γυναικῶν καὶ κτήσεως αὐτοῦ διδόντος συναπιέναι τῷ στρατῷ."},{"number":171,"text":"καὶ Μωυσῆς ἀρεσθεὶς τῷ λόγῳ καλέσας Ἐλεάζαρον τὸν ἀρχιερέα καὶ Ἰησοῦν καὶ τοὺς ἐν τέλει πάντας συνεχώρει τὴν Ἀμορρῖτιν αὐτοῖς ἐπὶ τῷ συμμαχῆσαι τοῖς συγγενέσιν, ἕως ἂν καταστήσωνται τὰ πάντα. λαβόντες οὖν ἐπὶ τούτοις τὴν χώραν καὶ κτίσαντες πόλεις καρτερὰς τέκνα τε καὶ γυναῖκας καὶ τἆλλα ὅσα συμπεριάγειν μέλλουσιν αὐτοῖς ἂν ἦν ἐμπόδια τοῦ πονεῖν ἀπέθεντο εἰς αὐτάς."},{"number":172,"text":"Οἰκοδομεῖ δὲ καὶ Μωυσῆς τὰς δέκα πόλεις τὰς εἰς τὸν ἀριθμὸν τῶν ὀκτὼ καὶ τεσσαράκοντα γενησομένας, ὧν τρεῖς ἀπέδειξε τοῖς ἐπʼ ἀκουσίῳ φόνῳ φευξομένοις, καὶ χρόνον ἔταξεν εἶναι τῆς φυγῆς τὸν αὐτὸν τῷ ἀρχιερεῖ, ἐφʼ οὗ δράσας τις τὸν φόνον ἔφυγε. μεθʼ ὃν συνεχώρει τελευτήσαντα κάθοδον, ἐχόντων ἐξουσίαν τῶν τοῦ πεφονευμένου συγγενῶν κτείνειν, εἰ λάβοιεν ἔξω τῶν ὅρων τῆς πόλεως εἰς ἣν ἔφυγε τὸν πεφονευκότα· ἑτέρῳ δὲ οὐκ ἐπετέτραπτο."},{"number":173,"text":"αἱ δὲ πόλεις αἱ πρὸς τὰς φυγὰς ἀποδεδειγμέναι ἦσαν αἵδε· Βοσάρα μὲν ἐπὶ τοῖς ὁρίοις τῆς Ἀραβίας, Ἀρίμανον δὲ τῆς Γαλαδηνῶν γῆς, καὶ Γαυλανὰν δʼ ἐν τῇ Βατανίδι. κτησαμένων δʼ αὐτῶν καὶ τὴν Χαναναίων γῆν τρεῖς ἕτεραι πόλεις ἔμελλον ἀνατεθήσεσθαι τῶν Λευίτιδων πόλεων τοῖς φυγάσιν εἰς κατοικισμὸν Μωυσέος ἐπιστείλαντος."},{"number":174,"text":"Μωυσῆς δὲ προσελθόντων αὐτῷ τῶν πρώτων τῆς Μανασσίτιδος φυλῆς καὶ δηλούντων μὲν ὡς τεθνήκοι τις τῶν φυλετῶν ἐπίσημος ἀνὴρ Σωλοφάντης ὄνομα, παῖδας μὲν οὐ καταλιπὼν ἄρσενας θυγατέρας δέ τοι, καὶ πυθομένων εἰ τούτων ὁ κλῆρος ἔσοιτο, φησίν,"},{"number":175,"text":"εἰ μὲν μέλλουσί τινι συνοικεῖν τῶν φυλετῶν, μετὰ τοῦ κλήρου πρὸς αὐτοὺς ἀπιέναι, εἰ δʼ ἐξ ἄλλης γαμοῖντό τισι φυλῆς, τὸν κλῆρον ἐν τῇ πατρῴᾳ φυλῇ καταλιπεῖν. καὶ τότε μένειν ἑκάστου τὸν κλῆρον ἐν τῇ φυλῇ διετάξατο."}],"8":[{"number":176,"text":"Τῶν δὲ τεσσαράκοντα ἐτῶν παρὰ τριάκοντα ἡμέρας συμπεπληρωμένων Μωυσῆς ἐκκλησίαν ἐπὶ τῷ Ἰορδάνῃ συναγαγών, ὅπου νῦν πόλις ἐστὶν Ἀβίλη, φοινικόφυτον δʼ ἐστὶ τὸ χωρίον, συνελθόντος τοῦ λαοῦ παντὸς λέγει τοιάδε·"},{"number":177,"text":"Ἄνδρες συστρατιῶται καὶ τῆς μακρᾶς κοινωνοὶ ταλαιπωρίας, ἐπεὶ τῷ θεῷ δοκοῦν ἤδη καὶ τῷ γήρᾳ χρόνον ἐτῶν εἴκοσι καὶ ἑκατὸν ἠνυσμένον δεῖ με τοῦ ζῆν ἀπελθεῖν καὶ τῶν πέρα τοῦ Ἰορδάνου πραχθησομένων οὐ μέλλω βοηθὸς ὑμῖν ἔσεσθαι καὶ σύμμαχος κωλυόμενος ὑπὸ τοῦ θεοῦ,"},{"number":178,"text":"δίκαιον ἡγησάμην μηδὲ νῦν ἐγκαταλιπεῖν τοὐμὸν ὑπὲρ τῆς ὑμετέρας εὐδαιμονίας πρόθυμον, ἀλλʼ ἀίδιόν τε ὑμῖν πραγματεύσασθαι τὴν τῶν ἀγαθῶν ἀπόλαυσιν, καὶ μνήμην ἐμαυτῷ γενομένων ὑμῶν ἐν ἀφθονίᾳ τῶν κρειττόνων."},{"number":179,"text":"φέρε οὖν ὑποθέμενος ὃν τρόπον ὑμεῖς τʼ ἂν εὐδαιμονήσαιτε καὶ παισὶ τοῖς αὑτῶν καταλίποιτε κτῆσιν ἀγαθῶν ἀίδιον παραθέμενος οὕτως ἀπέλθω τοῦ βίου. πιστεύεσθαι δὲ ἄξιός εἰμι διά τε τὰς πρότερον ὑπὲρ ὑμῶν φιλοτιμίας καὶ διὰ τὸ τὰς ψυχὰς ἐπὶ τελευτῇ γιγνομένας μετʼ ἀρετῆς πάσης ὁμιλεῖν."},{"number":180,"text":"ὦ παῖδες Ἰσραήλου, μία πᾶσιν ἀνθρώποις ἀγαθῶν κτήσεως αἰτία ὁ θεὸς εὐμενής· μόνος γὰρ οὗτος δοῦναί τε ταῦτα τοῖς ἀξίοις καὶ ἀφελέσθαι τῶν ἁμαρτανόντων εἰς αὐτὸν ἱκανός, ᾧ παρέχοντες ἑαυτοὺς οἵους αὐτός τε βούλεται κἀγὼ τὴν διάνοιαν αὐτοῦ σαφῶς ἐξεπιστάμενος παραινῶ, οὐκ ἂν ὄντες μακαριστοὶ καὶ ζηλωτοὶ πᾶσιν ἀτυχήσαιτέ ποτʼ ἢ παύσαισθε, ἀλλʼ ὧν τε νῦν ὑμῖν ἐστιν ἀγαθῶν ἡ κτῆσις βεβαία μενεῖ τῶν τε ἀπόντων ταχεῖαν ἕξετε τὴν παρουσίαν."},{"number":181,"text":"μόνον οἷς ὁ θεὸς ὑμᾶς ἕπεσθαι βούλεται, τούτοις πειθαρχεῖτε, καὶ μήτε νομίμων τῶν παρόντων ἄλλην προτιμήσητε διάταξιν μήτʼ εὐσεβείας ἧς νῦν περὶ τὸν θεὸν ἔχοντες καταφρονήσαντες εἰς ἄλλον μεταστήσησθε τρόπον. ταῦτα δὲ πράττοντες ἀλκιμώτατοι μάχας διενεγκεῖν ἁπάντων ἔσεσθε καὶ μηδενὶ τῶν ἐχθρῶν εὐάλωτοι."},{"number":182,"text":"θεοῦ γὰρ παρόντος ὑμῖν βοηθοῦ πάντων περιφρονεῖν εὔλογον. τῆς δʼ ἀρετῆς ἔπαθλα ὑμῖν μεγάλα κεῖται πρὸς ἅπαντα τὸν βίον κτησαμένοις· αὐτή γε τὸ πρῶτον ἀγαθῶν τὸ πρέσβιστόν ἐστιν, ἔπειτα καὶ τὴν τῶν ἄλλων χαρίζεται περιουσίαν,"},{"number":183,"text":"ὡς καὶ πρὸς ἀλλήλους ὑμῖν χρωμένοις αὐτῇ μακαριστὸν ποιῆσαι τὸν βίον καὶ τῶν ἀλλοφύλων πλέον δοξαζομένους ἀδήριτον καὶ παρὰ τοῖς αὖθις τὴν εὔκλειαν ὑμῖν ὑπάρξαι. τούτων δʼ ἂν ἐφικέσθαι δυνηθείητε, εἰ τῶν νόμων οὓς ὑπαγορεύσαντός μοι τοῦ θεοῦ συνεταξάμην κατήκοοι καὶ φύλακες γένοισθε καὶ μελετῴητε τὴν σύνεσιν αὐτῶν."},{"number":184,"text":"ἄπειμι δʼ αὐτὸς χαίρων ἐπὶ τοῖς ὑμετέροις ἀγαθοῖς παρατιθέμενος ὑμᾶς νόμων τε σωφροσύνῃ καὶ κόσμῳ τῆς πολιτείας καὶ ταῖς τῶν στρατηγῶν ἀρεταῖς, οἳ πρόνοιαν ἕξουσιν ὑμῶν τοῦ συμφέροντος."},{"number":185,"text":"θεός τε ὁ μέχρι νῦν ἡγεμονεύσας ἡμῖν, καθʼ οὗ βούλησιν κἀγὼ χρήσιμος ὑμῖν ἐγενόμην, οὐ μέχρι τοῦ δεῦρο στήσει τὴν αὑτοῦ πρόνοιαν, ἀλλʼ ἐφʼ ὃν αὐτοὶ βούλεσθε χρόνον τοῦτον ἔχειν προστάτην ἐν τοῖς τῆς ἀρετῆς ἐπιτηδεύμασι μένοντες, ἐπὶ τοσοῦτον αὐτοῦ χρήσεσθε τῇ προμηθείᾳ."},{"number":186,"text":"γνώμας τε ὑμῖν εἰσηγήσονται τὰς ἀρίστας, αἷς ἑπόμενοι τὴν εὐδαιμονίαν ἕξετε, ὁ ἀρχιερεὺς Ἐλεάζαρος καὶ Ἰησοῦς ἥ τε γερουσία καὶ τὰ τέλη τῶν φυλῶν, ὧν ἀκροᾶσθε μὴ χαλεπῶς, γινώσκοντες ὅτι πάντες οἱ ἄρχεσθαι καλῶς εἰδότες καὶ ἄρχειν εἴσονται παρελθόντες εἰς ἐξουσίαν αὐτοῦ,"},{"number":187,"text":"τήν τʼ ἐλευθερίαν ἡγεῖσθε μὴ τὸ προσαγανακτεῖν οἷς ἂν ὑμᾶς οἱ ἡγεμόνες πράττειν ἀξιῶσι· νῦν μὲν γὰρ ἐν τῷ τοὺς εὐεργέτας ὑβρίζειν ἐν τούτῳ τὴν παρρησίαν τίθεσθε, ὃ δὴ τοῦ λοιποῦ φυλαττομένοις ὑμῖν ἄμεινον ἕξει τὰ πράγματα·"},{"number":188,"text":"μηδὲ τὴν ἴσην ἐπὶ τούτοις ὀργήν ποτε λαμβάνετε, ᾗ κατʼ ἐμοῦ πολλάκις ἐτολμήσατε χρῆσθαι· γινώσκετε γὰρ ὡς πλεονάκις ἐκινδύνευσα ὑφʼ ὑμῶν ἀποθανεῖν ἢ ὑπὸ τῶν πολεμίων."},{"number":189,"text":"ταῦτα δʼ οὐκ ὀνειδίζειν ὑμᾶς προεθέμην, οὐ γὰρ ἐπʼ ἐξόδου τοῦ ζῆν δυσχεραίνοντας καταλιπεῖν ἠξίουν εἰς τὴν ἀνάμνησιν φέρων μηδὲ παρʼ ὃν ἔπασχον αὐτὰ καιρὸν ἐν ὀργῇ γενόμενος, ἀλλʼ ὥστε τοῦ σωφρονήσειν ὑμᾶς εἰς τὸ μέλλον κατʼ αὐτό γε τοῦτʼ ἀσφαλὲς εἶναι, καὶ μηδὲν εἰς τοὺς προεστηκότας ἐξυβρίσαι διὰ πλοῦτον, ὃς ὑμῖν πολὺς διαβᾶσι τὸν Ἰορδάνην καὶ τὴν Χαναναίαν κτησαμέναις περιστήσεται."},{"number":190,"text":"ἐπεὶ προαχθέντες εἰς καταφρόνησιν ὑπʼ αὐτοῦ καὶ τῆς ἀρετῆς ὀλιγωρίαν ἀπολεῖτε καὶ τὴν εὔνοιαν τὴν παρὰ τοῦ θεοῦ, ποιήσαντες δὲ τοῦτον ἐχθρὸν τήν τε γῆν, ἣν κτήσεσθε, κρατηθέντες ὅπλοις ὑπὸ τῶν αὖθις ἀφαιρεθήσεσθε μετὰ μεγίστων ὀνειδῶν καὶ σκεδασθέντες διὰ τῆς οἰκουμένης πᾶσαν ἐμπλήσετε καὶ γῆν καὶ θάλασσαν τῆς αὑτῶν δουλείας."},{"number":191,"text":"ἔσται δʼ ὑμῖν τούτων πεῖραν λαμβάνουσιν ἀνωφελὴς ἡ μετάνοια καὶ ἡ τῶν οὐ φυλαχθέντων νόμων ἀνάμνησις. ὅθεν εἰ βούλοισθε τούτους ὑμῖν μένειν, τῶν πολεμίων μηδένα ὑπολείπησθε κρατήσαντες αὐτῶν, ἀλλʼ ἀπολλύναι πάντας κρίνατε συμφέρειν, ἵνα μή τινων παραγευσάμενοι τῆς ἐκείνων ἐπιτηδεύσεως διαφθείρητε τὴν πάτριον πολιτείαν."},{"number":192,"text":"ἔτι δὲ καὶ βωμοὺς καὶ ἄλση καὶ νεὼς ὁπόσους ἂν ἔχοιεν κατερείπειν παραινῶ καὶ δαπανᾶν πυρὶ τὸ γένος αὐτῶν καὶ τὴν μνήμην· βεβαία γὰρ ἂν οὕτως ὑμῖν μόνον ὑπάρξειεν ἡ τῶν οἰκείων ἀγαθῶν ἀσφάλεια."},{"number":193,"text":"ἵνα δὲ μὴ διʼ ἀμαθίαν τοῦ κρείττονος ἡ φύσις ὑμῶν πρὸς τὸ χεῖρον ἀπονεύσῃ, συνέθηκα ὑμῖν καὶ νόμους ὑπαγορεύσαντός μοι τοῦ θεοῦ καὶ πολιτείαν, ἧς τὸν κόσμον φυλάξαντες πάντων ἂν εὐδαιμονέστατοι κριθείητε."},{"number":194,"text":"Ταῦτα εἰπὼν δίδωσιν αὐτοῖς ἐν βιβλίῳ τοὺς νόμους καὶ τὴν διάταξιν τῆς πολιτείας ἀναγεγραμμένην. οἱ δὲ ἐδάκρυόν τε καὶ πολλὴν ἐπιζήτησιν ἐποιοῦντο τοῦ στρατηγοῦ μεμνημένοι τε ὧν κινδυνεύσειε καὶ προθυμηθείη τῆς περὶ αὐτῶν σωτηρίας καὶ δυσελπιστοῦντες περὶ τῶν μελλόντων ὡς οὐκ ἐσομένης ἄλλης ἀρχῆς τοιαύτης, ἧττόν τε τοῦ θεοῦ προνοησομένου διὰ τὸ Μωυσῆν εἶναι τὸν παρακαλοῦντα."},{"number":195,"text":"ὧν τε ἐπὶ τῆς ἐρήμου μετʼ ὀργῆς ὁμιλήσειαν αὐτῷ μετανοοῦντες ἤλγουν, ὡς ἅπαντα τὸν λαὸν εἰς δάκρυα προπεσόντα κρεῖττον καὶ τῆς ἐκ λόγου παρηγορίας τὸ ἐπʼ αὐτῷ ποιῆσαι πάθος. Μωυσῆς δʼ αὐτοὺς παρηγόρει, καὶ τοῦ δακρύων αὐτὸν ἄξιον ὑπολαμβάνειν ἀπάγων αὐτοὺς χρῆσθαι τῇ πολιτείᾳ παρεκάλει. καὶ τότε μὲν οὕτω διελύθησαν."},{"number":196,"text":"Βούλομαι δὲ τὴν πολιτείαν πρότερον εἰπὼν τῷ τε Μωυσέος ἀξιώματι τῆς ἀρετῆς ἀναλογοῦσαν καὶ μαθεῖν παρέξων διʼ αὐτῆς τοῖς ἐντευξομένοις. οἷα τὰ καθʼ ἡμᾶς ἀρχῆθεν ἦν, ἐπὶ τὴν τῶν ἄλλων τραπέσθαι διήγησιν. γέγραπται δὲ πάνθʼ ὡς ἐκεῖνος κατέλιπεν οὐδὲν ἡμῶν ἐπὶ καλλωπισμῷ προσθέντων οὐδʼ ὅτι μὴ κατελέλοιπε Μωυσῆς."},{"number":197,"text":"νενεωτέρισται δʼ ἡμῖν τὸ κατὰ γένος ἕκαστα τάξαι· σποράδην γὰρ ὑπʼ ἐκείνου κατελείφθη γραφέντα καὶ ὡς ἕκαστόν τι παρὰ τοῦ θεοῦ πύθοιτο. τούτου χάριν ἀναγκαῖον ἡγησάμην προδιαστείλασθαι, μὴ καί τις ἡμῖν παρὰ τῶν ὁμοφύλων ἐντυχόντων τῇ γραφῇ μέμψις ὡς διημαρτηκόσι γένηται."},{"number":198,"text":"ἔχει δὲ οὕτως ἡ διάταξις ἡμῶν τῶν νόμων τῶν ἀνηκόντων εἰς τὴν πολιτείαν. οὓς δὲ κοινοὺς ἡμῖν καὶ πρὸς ἀλλήλους κατέλιπε τούτους ὑπερεθέμην εἰς τὴν περὶ ἐθῶν καὶ αἰτιῶν ἀπόδοσιν, ἣν συλλαμβανομένου τοῦ θεοῦ μετὰ ταύτην ἡμῖν τὴν πραγματείαν συντάξασθαι πρόκειται."},{"number":199,"text":"Ἐπειδὰν τὴν Χαναναίων γῆν κτησάμενοι καὶ σχολὴν ἐν χρήσει τῶν ἀγαθῶν ἔχοντες πόλεις τὸ λοιπὸν ἤδη κτίζειν προαιρῆσθε, ταῦτα ποιοῦντες τῷ θεῷ φίλα πράξετε καὶ τὴν εὐδαιμονίαν βεβαίαν ἕξετε·"},{"number":200,"text":"ἱερὰ πόλις ἔστω μία τῆς Χαναναίων γῆς ἐν τῷ καλλίστῳ καὶ διʼ ἀρετὴν ἐπιφανεῖ, ἣν ἂν ὁ θεὸς ἑαυτῷ διὰ προφητείας ἕληται, καὶ νεὼς εἷς ἐν ταύτῃ ἔστω, καὶ βωμὸς εἷς ἐκ λίθων μὴ κατειργασμένων, ἀλλὰ λογάδην συγκειμένων, οἳ κονιάματι χρισθέντες εὐπρεπεῖς τε εἶεν καὶ καθάριοι πρὸς τὴν θέαν."},{"number":201,"text":"ἡ δʼ ἐπὶ τοῦτον πρόσβασις ἔστω μὴ διὰ βαθμίδων, ἀλλὰ προσχώσεως αὐτῷ καταπρανοῦς γενομένης. ἐν ἑτέρᾳ δὲ πόλει μήτε βωμὸς μήτε νεὼς ἔστω· θεὸς γὰρ εἷς καὶ τὸ Ἑβραίων γένος ἕν."},{"number":202,"text":"Ὁ δὲ βλασφημήσας θεὸν καταλευσθεὶς κρεμάσθω διʼ ἡμέρας καὶ ἀτίμως καὶ ἀφανῶς θαπτέσθω."},{"number":203,"text":"Συνερχέσθωσαν δὲ εἰς ἣν ἀποφήνωσι πόλιν τὸν νεὼν τρὶς τοῦ ἔτους οἱ ἐκ τῶν περάτων τῆς γῆς, ἧς ἂν Ἑβραῖοι κρατῶσιν, ὅπως τῷ θεῷ τῶν μὲν ὑπηργμένων εὐχαριστῶσι καὶ περὶ τῶν εἰς τὸ μέλλον παρακαλῶσι καὶ συνιόντες ἀλλήλοις καὶ συνευωχούμενοι προσφιλεῖς ὦσι·"},{"number":204,"text":"καλὸν γὰρ εἶναι μὴ ἀγνοεῖν ἀλλήλους ὁμοφύλους τε ὄντας καὶ τῶν αὐτῶν κοινωνοῦντας ἐπιτηδευμάτων, τοῦτο δὲ ἐκ μὲν τῆς αὐτῆς ἐπιμιξίας αὐτοῖς ὑπάρξειν, τῇ τε ὄψει καὶ τῇ ὁμιλίᾳ μνήμην αὐτῶν ἐντιθέντας· ἀνεπιμίκτους γὰρ ἀλλήλοις μένοντας ἀλλοτριωτάτους αὑτοῖς νομισθήσεσθαι."},{"number":205,"text":"Ἔστω δὲ καὶ δεκάτη τῶν καρπῶν ἐξαίρεσις ὑμῖν χωρὶς ἧς διετάξατε τοῖς ἱερεῦσι καὶ Λευίταις δεδόσθαι, ἣ πιπρασκέσθω μὲν ἐπὶ τῶν πατρίδων, εἰς δὲ τὰς εὐωχίας ὑπηρετείτω καὶ τὰς θυσίας τὰς ἐν τῇ ἱερᾷ πόλει· δίκαιον γὰρ εἶναι τῶν ἐκ τῆς γῆς ἀναδιδομένων, ἣν ὁ θεὸς αὐτοῖς κτήσασθαι παρέσχεν, ἐπὶ τιμῇ τοῦ δεδωκότος ἀπολαύειν."},{"number":206,"text":"Ἐκ μισθοῦ γυναικὸς ἡταιρημένης θυσίας μὴ τελεῖν· ἥδεσθαι γὰρ μηδενὶ τῶν ἀφʼ ὕβρεως τὸ θεῖον, χείρων δʼ οὐκ ἂν εἴη τῆς ἐπὶ τοῖς σώμασιν αἰσχύνης· ὁμοίως μηδʼ ἂν ἐπʼ ὀχεύσει κυνὸς ἤτοι θηρευτικοῦ ἢ ποιμνίων φύλακος λάβῃ τις μισθόν, ἐκ τούτου θύειν τῷ θεῷ."},{"number":207,"text":"Βλασφημείτω δὲ μηδεὶς θεοὺς οὓς πόλεις ἄλλαι νομίζουσι. μηδὲ συλᾶν ἱερὰ ξενικά, μηδʼ ἂν ἐπωνομασμένον ᾖ τινι θεῷ κειμήλιον λαμβάνειν."},{"number":208,"text":"Μηδεὶς δʼ ἐξ ὑμῶν κλωστὴν ἐξ ἐρίου καὶ λίνου στολὴν φορείτω· τοῖς γὰρ ἱερεῦσι μόνοις ταύτην ἀποδεδεῖχθαι."},{"number":209,"text":"Συνελθόντος δὲ τοῦ πλήθους εἰς τὴν ἱερὰν πόλιν ἐπὶ ταῖς θυσίαις διʼ ἐτῶν ἑπτὰ τῆς σκηνοπηγίας ἑορτῆς ἐνστάσης ὁ ἀρχιερεὺς ἐπὶ βήματος ὑψηλοῦ σταθείς, ἀφʼ οὗ γένοιτο ἐξάκουστος, ἀναγινωσκέτω τοὺς νόμους ἅπασι, καὶ μήτε γυνὴ μήτε παῖδες εἰργέσθωσαν τοῦ ἀκούειν, ἀλλὰ μηδὲ οἱ δοῦλοι·"},{"number":210,"text":"καλὸν γὰρ ταῖς ψυχαῖς ἐγγραφέντας καὶ τῇ μνήμῃ φυλαχθῆναι μηδέποτε ἐξαλειφθῆναι δυναμένους. οὕτως γὰρ οὐδὲν ἁμαρτήσονται μὴ δυνάμενοι λέγειν ἄγνοιαν τῶν ἐν τοῖς νόμοις διωρισμένων, οἵ τε νόμοι πολλὴν πρὸς ἁμαρτάνοντας ἕξουσι παρρησίαν, ὡς προλεγόντων αὐτοῖς ἃ πείσονται καὶ ταῖς ψυχαῖς ἐγγραψάντων διὰ τῆς ἀκοῆς ἃ κελεύουσιν,"},{"number":211,"text":"ὥστʼ εἶναι διὰ παντὸς ἔνδον αὐτοῖς τὴν προαίρεσιν αὐτῶν ἧς ὀλιγωρήσαντες ἠδίκησαν καὶ τῆς ζημίας αὑτοῖς αἴτιοι γεγόνασι. μανθανέτωσαν δὲ καὶ οἱ παῖδες πρῶτον τοὺς νόμους μάθημα κάλλιστον καὶ τῆς εὐδαιμονίας αἴτιον."},{"number":212,"text":"Δίς τε ἑκάστης ἡμέρας ἀρχομένης τε αὐτῆς καὶ ὁπότε πρὸς ὕπνον ὥρα τρέπεσθαι μαρτυρεῖν τῷ θεῷ τὰς δωρεάς, ἃς ἀπαλλαγεῖσιν αὐτοῖς ἐκ τῆς Αἰγυπτίων γῆς παρέσχε, δικαίας οὔσης φύσει τῆς εὐχαριστίας καὶ γενομένης ἐπʼ ἀμοιβῇ μὲν τῶν ἤδη γεγονότων ἐπὶ δὲ προτροπῇ τῶν ἐσομένων·"},{"number":213,"text":"ἐπιγράφειν δὲ καὶ τοῖς θυρώμασιν αὐτῶν τὰ μέγιστα ὧν εὐεργέτησεν αὐτοὺς ὁ θεὸς ἔν τε βραχίοσιν ἕκαστον διαφαίνειν, ὅσα τε τὴν ἰσχὺν ἀποσημαίνειν δύναται τοῦ θεοῦ καὶ τὴν πρὸς αὐτοὺς εὔνοιαν φέρειν ἐγγεγραμμένα ἐπὶ τῆς κεφαλῆς καὶ τοῦ βραχίονος, ὡς περίβλεπτον πανταχόθεν τὸ περὶ αὐτοὺς πρόθυμον τοῦ θεοῦ."},{"number":214,"text":"Ἀρχέτωσαν δὲ καθʼ ἑκάστην πόλιν ἄνδρες ἑπτὰ οἱ καὶ τὴν ἀρετὴν καὶ τὴν περὶ τὸ δίκαιον σπουδὴν προησκηκότες· ἑκάστῃ δὲ ἀρχῇ δύο ἄνδρες ὑπηρέται διδόσθωσαν ἐκ τῆς τῶν Λευιτῶν φυλῆς."},{"number":215,"text":"ἔστωσαν δὲ καὶ οἱ δικάζειν λαχόντες ταῖς πόλεσιν ἐν πάσῃ τιμῇ, ὡς μήτε βλασφημεῖν ἐκείνων παρόντων μήτε θρασύνεσθαί τισιν ἐξεῖναι τῆς πρὸς τοὺς ἐν ἀξιώματι τῶν ἀνθρώπων αἰδοῦς αὐτῶν εὐλαβεστέρους, ὥστε τοῦ θεοῦ μὴ καταφρονεῖν, ἀπεργαζομένης."},{"number":216,"text":"οἱ δὲ δικασταὶ ἀποφήνασθαι κύριοι περὶ τοῦ δόξαντος αὐτοῖς ἔστωσαν, πλὴν εἰ μή τι χρήματα λαβόντας τις αὐτοὺς ἐπὶ διαφθορᾷ τοῦ δικαίου ἐνδείξαιτʼ ἢ ἄλλην τινὰ αἰτίαν προφέροι, καθʼ ἣν οὐ καλῶς ἐλέγχει αὐτοὺς ἀποφηναμένους· οὔτε γὰρ κέρδει χαριζομένους οὔτʼ ἀξιώματι προσῆκε φανερὰς ποιεῖσθαι τὰς κρίσεις, ἀλλὰ τὸ δίκαιον ἐπάνω πάντων τιθεμένους."},{"number":217,"text":"ὁ γὰρ θεὸς ἂν οὕτως δόξειε καταφρονεῖσθαι καὶ ἀσθενέστερος ἐκείνων οἷς ἄν τις κατὰ φόβον ἰσχύος προσνέμοι τὴν ψῆφον κεκρίσθαι· τοῦ θεοῦ γὰρ ἰσχύς ἐστι τὸ δίκαιον. ὃ τοῖς ἐν ἀξιώμασι τυγχάνουσι καταχαριζόμενός τις ἐκείνους τοῦ θεοῦ δυνατωτέρους ποιεῖ."},{"number":218,"text":"ἂν δʼ οἱ δικασταὶ μὴ νοῶσι περὶ τῶν ἐπʼ αὐτοὺς παρατεταγμένων ἀποφήνασθαι, συμβαίνει δὲ πολλὰ τοιαῦτα τοῖς ἀνθρώποις, ἀναπεμπέτωσαν τὴν δίκην εἰς τὴν ἱερὰν πόλιν, καὶ συνελθόντες ὅ τε ἀρχιερεὺς καὶ ὁ προφήτης καὶ ἡ γερουσία τὸ δοκοῦν ἀποφαινέσθωσαν."},{"number":219,"text":"Εἷς δὲ μὴ πιστευέσθω μάρτυς, ἀλλὰ τρεῖς ἢ τὸ τελευταῖον δύο, ὧν τὴν μαρτυρίαν ἀληθῆ ποιήσει τὰ προβεβιωμένα. γυναικῶν δὲ μὴ ἔστω μαρτυρία διὰ κουφότητα καὶ θράσος τοῦ γένους αὐτῶν· μαρτυρείτωσαν δὲ μηδὲ δοῦλοι διὰ τὴν τῆς ψυχῆς ἀγένειαν, οὓς ἢ διὰ κέρδος εἰκὸς ἢ διὰ φόβον μὴ τἀληθῆ μαρτυρῆσαι. ἂν δέ τις ψευδομαρτυρήσας πιστευθῇ, πασχέτω ταῦτʼ ἐλεγχθεὶς ὅσα ὁ καταμαρτυρηθεὶς πάσχειν ἔμελλεν."},{"number":220,"text":"Ἂν δὲ πραχθέντος φόνου ἔν τινι χώρᾳ μὴ εὑρίσκηται ὁ δράσας μηδʼ ὑπονοῆταί τις ὡς διὰ μῖσος ἀπεκτονηκώς, ζητείτωσαν μὲν αὐτὸν μετὰ πολλῆς σπουδῆς μήνυτρα προθέμενοι· μηδενὸς δὲ μηνύοντος αἱ ἀρχαὶ τῶν πόλεων τῶν πλησίον τῇ χώρᾳ, ἐν ᾗ ὁ φόνος ἐπράχθη, καὶ ἡ γερουσία συνελθόντες μετρείτωσαν ἀπὸ τοῦ τόπου ὅπου κεῖται ὁ νεκρὸς τὴν χώραν."},{"number":221,"text":"ἣ δʼ ἂν ᾖ πλησιαιτάτη πόλις, οἱ ἐν αὐτῇ δημόσιοι πριάμενοι δάμαλιν καὶ κομίσαντες εἰς φάραγγα καὶ ἀνεπιτήδειον ἀρότρῳ καὶ φυτοῖς χωρίον τοὺς τένοντας κοψάτωσαν τῆς βοός,"},{"number":222,"text":"καὶ χέρνιβας ἑλόμενοι ὑπὲρ κεφαλῆς τῆς βοὸς οἱ ἱερεῖς καὶ οἱ Λευῖται καὶ ἡ γερουσία τῆς πόλεως ἐκείνης καθαρὰς ἀναβοησάτωσαν τὰς χεῖρας ἔχειν ἀπὸ τοῦ φόνου καὶ μήτε δρᾶσαι μήτε δρωμένῳ παρατυχεῖν, ἐπικαλεῖσθαι δὲ ἵλεω τὸν θεὸν καὶ μηκέτι τοιοῦτον δεινὸν συμβῆναι τῇ γῇ πάθος."},{"number":223,"text":"Ἀριστοκρατία μὲν οὖν κράτιστον καὶ ὁ κατʼ αὐτὴν βίος, καὶ μὴ λάβῃ πόθος ὑμᾶς ἄλλης πολιτείας, ἀλλὰ ταύτην στέργοιτε καὶ τοὺς νόμους ἔχοντες δεσπότας κατʼ αὐτοὺς ἕκαστα πράττετε· ἀρκεῖ γὰρ ὁ θεὸς ἡγεμὼν εἶναι. βασιλέως δʼ εἰ γένοιτο ἔρως ὑμῖν, ἔστω μὲν οὗτος ὁμόφυλος, πρόνοια δʼ αὐτῷ δικαιοσύνης καὶ τῆς ἄλλης ἀρετῆς διὰ παντὸς ἔστω."},{"number":224,"text":"παραχωροίη δὲ οὗτος τοῖς μὲν νόμοις καὶ τῷ θεῷ τὰ πλείονα τοῦ φρονεῖν, πρασσέτω δὲ μηδὲν δίχα τοῦ ἀρχιερέως καὶ τῆς τῶν γερουσιαστῶν γνώμης γάμοις τε μὴ πολλοῖς χρώμενος μηδὲ πλῆθος διώκων χρημάτων μηδʼ ἵππων, ὧν αὐτῷ παραγενομένων ὑπερήφανος ἂν τῶν νόμων ἔσοιτο. κωλυέσθω δʼ, εἰ τούτων τι διὰ σπουδῆς ἔχοι, γίγνεσθαι τοῦ συμφέροντος ὑμῖν δυνατώτερος."},{"number":225,"text":"Ὅρους γῆς μὴ ἐξέστω κινεῖν μήτε οἰκείας μήτʼ ἀλλοτρίας πρὸς οὕς ἐστιν ὑμῖν εἰρήνη, φυλαττέσθω δʼ ὥσπερ θεοῦ ψῆφον βεβαίαν εἰς αἰῶνα κειμένην ἀναιρεῖν, ὡς πολέμων ἐντεῦθεν καὶ στάσεων γινομένων ἐκ τοῦ πλεονεκτοῦντας προσωτέρω χωρεῖν βούλεσθαι τῶν ὅρων· μὴ γὰρ μακρὰν εἶναι τοῦ καὶ τοὺς νόμους ὑπερβαίνειν τοὺς τὸν ὅρον μετακινοῦντας."},{"number":226,"text":"Γῆν ὁ φυτεύσας, πρὸ ἐτῶν τεσσάρων ἂν καρπὸν προβάλῃ τὰ φυτά, μήτε τῷ θεῷ ἀπαρχὰς ἐντεῦθεν ἀποφερέτω μήτʼ αὐτὸς χρήσθω· οὐ γὰρ κατὰ καιρὸν τοῦτον ὑπʼ αὐτῶν ἐνεχθῆναι, βιασαμένης δὲ τῆς φύσεως ἀώρως μήτε τῷ θεῷ ἁρμόζειν μήτʼ αὐτῷ τῷ δεσπότῃ χρῆσθαι."},{"number":227,"text":"τῷ δὲ τετάρτῳ τρυγάτω πᾶν τὸ γενόμενον, τότε γὰρ ὥριον εἶναι, καὶ συναγαγὼν εἰς τὴν ἱερὰν πόλιν κομιζέτω, καὶ σὺν τῇ δεκάτῃ τοῦ ἄλλου καρποῦ μετὰ τῶν φίλων εὐωχούμενος ἀναλισκέτω καὶ μετʼ ὀρφανῶν καὶ χηρευουσῶν γυναικῶν. πέμπτου δὲ ἔτους κύριος ἔστω τὰ φυτὰ καρποῦσθαι."},{"number":228,"text":"Τὴν ἀμπέλοις κατάφυτον γῆν μὴ σπείρειν· ἀρκεῖσθαι γὰρ αὐτὴν τρέφειν τοῦτο τὸ φυτὸν καὶ τῶν ἐξ ἀρότρου πόνων ἀπηλλάχθαι. βουσὶν ἀροῦν τὴν γῆν, καὶ μηδὲν τῶν ἑτέρων ζῴων σὺν αὐτοῖς ὑπὸ ζεύγλην ἄγοντας, ἀλλὰ κατʼ οἰκεῖα γένη κἀκείνοις ποιεῖσθαι τὸν ἄροτον. εἶναι δὲ καθαρὰ τὰ σπέρματα καὶ ἀνεπίμικτα, καὶ μὴ σύνδυο καὶ τρία σπείρειν· οὐ γὰρ τῇ τῶν ἀνομοίων κοινωνίᾳ χαίρειν τὴν φύσιν."},{"number":229,"text":"μηδὲ κτήνεσιν ἐπάγειν ὅσα μὴ συγγενῆ· δέος γὰρ ἐκ τούτου μὴ διαβῇ καὶ μέχρι τῶν ἀνθρωπείων ἡ πρὸς τὸ ὁμόφυλον ἀτιμία τὴν ἀρχὴν ἀπὸ τῶν περὶ τὰ μικρὰ καὶ τὰ φαῦλα πρότερον λαβοῦσα."},{"number":230,"text":"δεῖ δὲ μηδὲν εἶναι τοιοῦτον συγκεχωρημένον, ἐξ οὗ κατὰ μίμησιν παρατροπή τις τῶν κατὰ τὴν πολιτείαν ἔσοιτο, ἀλλʼ ὡς οὐδὲ περὶ τῶν τυχόντων ἠμέληται τοῖς νόμοις εἰδόσι προνοεῖσθαι τοῦ κατʼ αὐτοὺς ἀμέμπτου."},{"number":231,"text":"Ἀμῶντας δὲ καὶ συναιροῦντας τὰ θέρη μὴ καλαμᾶσθαι, καταλιπεῖν δέ τινα καὶ τῶν δραγμάτων τοῖς βίου σπανίζουσιν ἕρμαιον εἶναι τούτοις πρὸς διατροφήν· ὁμοίως δὲ καὶ τῆς τρύγης ἀπολιπεῖν τὰς ἐπιφυλλίδας τοῖς πένησι καὶ τῶν ἐλαιῶν παρεῖναί τι τοῦ καρποῦ πρὸς συλλογὴν τοῖς ἐξ ἰδίων οὐκ ἔχουσι μεταλαβεῖν·"},{"number":232,"text":"οὐ τοσαύτη γὰρ ἂν ἐκ τῆς ἐπʼ ἀκριβὲς αὐτῶν συλλογῆς εὐπορία τοῖς δεσπόταις γένοιτο, ὅση χάρις ἐκ τῶν δεομένων ἔλθοι, τό τε θεῖον τὴν γῆν προθυμοτέραν εἰς τὴν ἐκτροφὴν τῶν καρπῶν ἀπεργάσεται μὴ τοῦ κατʼ αὐτοὺς προνοουμένων λυσιτελοῦς, ἀλλὰ καὶ τῆς τῶν ἄλλων διατροφῆς λόγον ἐχόντων."},{"number":233,"text":"μηδὲ βοῶν ὁπότε τρίβοιεν τοὺς στάχυας ἀποδεῖν τὰ στόματα ἐπὶ τῆς ἅλωος· οὐ γὰρ εἶναι δίκαιον εἴργειν τοὺς συνειργασμένους τοῦ καρποῦ καὶ περὶ τὴν γένεσιν αὐτοῦ πονήσαντας."},{"number":234,"text":"μηδὲ ὀπώρας ἀκμαζούσης κωλύειν ἅπτεσθαι τοὺς ὁδῷ βαδίζοντας, ἀλλʼ ὡς ἐξ οἰκείων αὐτοῖς ἐπιτρέπειν ἐμπίπλασθαι, κἂν ἐγχώριοι τυγχάνωσι κἂν ξένοι, χαίροντας ἐπὶ τῷ παρέχειν αὐτοῖς τῶν ὡραίων μεταλαμβάνειν· ἀποφέρεσθαι δʼ αὐτοῖς μηδὲν ἐξέστω."},{"number":235,"text":"μηδὲ τρυγῶντες ὧν ἂν εἰς τὰς ληνοὺς κομίζωσιν εἰργέτωσαν τοὺς ὑπαντιάζοντας ἐπεσθίειν· ἄδικον γὰρ ἀγαθῶν, ἃ κατὰ βούλησιν θεοῦ παρῆλθεν εἰς τὸν βίον, φθονεῖν τοῖς ἐπιθυμοῦσιν αὐτῶν μεταλαμβάνειν τῆς ὥρας ἐν ἀκμῇ τε οὔσης καὶ σπευδούσης ἀπελθεῖν·"},{"number":236,"text":"ὡς τῷ θεῷ κεχαρισμένον ἂν εἴη, κἂν ὑπʼ αἰσχύνης τινὰς ὀκνοῦντας ἅψασθαι λαβεῖν παρακαλῶσιν, ὄντας μὲν Ἰσραηλίτας ὡς κοινωνοὺς καὶ δεσπότας διὰ τὴν συγγένειαν, ἀφιγμένους δʼ ἀλλαχόθεν ἀνθρώπους ξενίων τυχεῖν ἀξιοῦντας ὧν ὁ θεὸς καθʼ ὥραν αὐτοῖς παρέσχεν."},{"number":237,"text":"ἀναλώματα γὰρ οὐχ ἡγητέον ὅσα τις κατὰ χρηστότητα παρίησιν ἀνθρώποις λαμβάνειν, τοῦ θεοῦ τὴν ἀφθονίαν τῶν ἀγαθῶν χορηγοῦντος οὐκ ἐπὶ τῷ καρποῦσθαι μόνοις, ἀλλὰ καὶ τῷ τοῖς ἄλλοις μεταδιδόναι φιλοτίμως, καὶ βουλομένου τῷ τρόπῳ τούτῳ τὴν ἰδίαν περὶ τὸν Ἰσραηλιτῶν λαὸν εὔνοιαν καὶ τὴν χορηγίαν τῆς εὐδαιμονίας καὶ τοῖς ἄλλοις ἐμφανίζεσθαι ἐκ πολλοῦ τοῦ περιόντος αὐτοῖς κἀκείνοις μεταδιδόντων."},{"number":238,"text":"ὁ δὲ παρὰ ταῦτα ποιήσας πληγὰς μιᾷ λειπούσας τεσσαράκοντα τῷ δημοσίῳ σκύτει λαβὼν τιμωρίαν ταύτην αἰσχίστην ἐλεύθερος ὑπομενέτω, ὅτι τῷ κέρδει δουλεύσας ὕβρισε τὸ ἀξίωμα·"},{"number":239,"text":"καλῶς γὰρ ὑμῖν ἔχει πεπειραμένοις ἐν Αἰγύπτῳ συμφορῶν καὶ κατὰ τὴν ἐρημίαν πρόνοιαν τῶν ἐν τοῖς ὁμοίοις ὑπαρχόντων ποιεῖσθαι, καὶ τυχόντας εὐπορίας ἐξ ἐλέου καὶ προνοίας τοῦ θεοῦ τὴν αὐτὴν ταύτην ἐξ ὁμοίου πάθους ἀπομερίζειν τοῖς δεομένοις."},{"number":240,"text":"Ταῖς δὲ δεκάταις ταῖς δυσίν, ἃς ἔτους ἑκάστου προεῖπον τελεῖν, τὴν μὲν τοῖς Λευίταις, τὴν δʼ ἑτέραν πρὸς τὰς εὐωχίας, τρίτην πρὸς αὐταῖς κατὰ τὸ ἔτος τρίτον συμφέρειν εἰς διανέμησιν τῶν σπανιζόντων γυναιξί τε χήραις καὶ παισὶν ὀρφανοῖς·"},{"number":241,"text":"τῶν δʼ ὡραίων ὅ τι καὶ πρῶτον ἑκάστῳ τύχῃ γενόμενον εἰς τὸ ἱερὸν κομιζέτωσαν, καὶ τὸν θεὸν ὑπὲρ τῆς ἐνεγκαμένης αὐτὸ γῆς, ἣν αὐτοῖς κτήσασθαι παρέσχεν, εὐλογήσαντες θυσίας ἃς ὁ νόμος αὐτοῖς ἐπιφέρειν κελεύει ἐπιτελέσαντες τούτων τὰ προτέλεια τοῖς ἱερεῦσι διδότωσαν."},{"number":242,"text":"ἐπειδὰν δὲ ταῦτά τις ποιήσας καὶ πάντων τὰς δεκάτας ἅμα ταῖς εἰς τοὺς Λευίτας καὶ τὰς εὐωχίας ἀπενηνοχὼς ἀπιέναι μέλλῃ πρὸς αὑτὸν οἴκαδε, στὰς ἀντικρὺ τοῦ τεμενίσματος εὐχαριστησάτω μὲν τῷ θεῷ, ὅτι τῆς ἀπʼ Αἰγυπτίων αὐτοὺς ὕβρεως ἀπαλλάξας γῆν αὐτοῖς ἀγαθὴν καὶ πολλὴν ἔδωκε καρποῦσθαι,"},{"number":243,"text":"μαρτυράμενος δὲ ὡς τάς τε δεκάτας κατὰ τοὺς Μωυσέος τελέσειε νόμους αἰτησάσθω τὸν θεὸν εὐμενῆ καὶ ἵλεων αὐτῷ διὰ παντὸς εἶναι καὶ κοινῇ πᾶσιν Ἑβραίοις διαμένειν, φυλάττοντα μὲν ἃ δέδωκεν αὐτοῖς ἀγαθὰ προσκτήσασθαι δὲ ὅσα δύναται χαρίζεσθαι."},{"number":244,"text":"Γαμείτωσαν δὲ ἐν ὥρᾳ γάμου γενόμενοι παρθένους ἐλευθέρας γονέων ἀγαθῶν, ὁ δὲ μὴ μέλλων ἄγεσθαι παρθένον μὴ ζευγνύσθω συνοικοῦσαν ἄλλῳ νοθεύσας μηδὲ λυπῶν τὸν πρότερον αὐτῆς ἄνδρα· δούλας δὲ μὴ γαμεῖσθαι τοῖς ἐλευθέροις, μηδʼ ἂν ὑπʼ ἔρωτος πρὸς τοῦτό τινες ἐκβιάζωνται, κρατεῖν δὲ τῆς ἐπιθυμίας τὸ εὐπρεπὲς καὶ τοῖς ἀξιώμασι πρόσφορον."},{"number":245,"text":"ἔτι μηδὲ ἡταιρημένης εἶναι γάμον, ἧς διʼ ὕβριν τοῦ σώματος τὰς ἐπὶ τῷ γάμῳ θυσίας ὁ θεὸς οὐκ ἂν προσοῖτο· γένοιτο γὰρ ἂν οὕτω τῶν παίδων τὰ φρονήματα ἐλευθέρια καὶ πρὸς ἀρετὴν ὄρθια, εἰ μὴ τύχοιεν ἐκ γάμων φύντες αἰσχρῶν, μηδʼ ἐξ ἐπιθυμίας οὐκ ἐλευθερίας συνελθόντων."},{"number":246,"text":"εἴ τις ὡς παρθένον μνηστευσάμενος ἔπειτα μὴ τοιαύτην εὕροι, δίκην λαχὼν αὐτὸς μὲν κατηγορείτω χρώμενος εἰς ἀπόδειξιν οἷς ἂν ἔχῃ τεκμηρίοις, ἀπολογείσθω δὲ ὁ τῆς κόρης πατὴρ ἢ ἀδελφὸς ἢ ὃς ἂν μετὰ τούτους ἐγγυτέρω δοκῇ τοῦ γένους."},{"number":247,"text":"καὶ κριθεῖσα μὲν ἡ κόρη μὴ ἀδικεῖν συνοικείτω τῷ κατηγορήσαντι μηδεμίαν ἐξουσίαν ἔχοντος ἐκείνου ἀποπέμπεσθαι αὐτήν, πλὴν εἰ μὴ μεγάλας αἰτίας αὐτῷ παράσχοι καὶ πρὸς ἃς οὐδʼ ἀντειπεῖν δυνηθείη."},{"number":248,"text":"τοῦ δὲ τολμηρῶς καὶ προπετῶς ἐπενεγκεῖν αἰτίαν καὶ διαβολὴν πρόστιμον ἐκτινύτω πληγὰς τεσσαράκοντα μιᾷ λειπούσας λαμβάνων καὶ πεντήκοντα σίκλους ἀποτινύτω τῷ πατρί. ἂν δʼ ἐξελέγξῃ τὴν παιδίσκην ἐφθαρμένην, δημότις μὲν οὖσα τοῦ μὴ σωφρόνως προστῆναι τῆς παρθενίας ἄχρι νομίμων γάμων καταλευέσθω, ἂν δʼ ἐξ ἱερέων ᾖ γεγενημένη, καιέσθω ζῶσα."},{"number":249,"text":"δύο γυναικῶν οὐσῶν τινι, καὶ τῆς μὲν ἑτέρας ἐν τιμῇ σφόδρα καὶ εὐνοίᾳ κειμένης ἢ διʼ ἔρωτα καὶ κάλλος ἢ κατʼ ἄλλην αἰτίαν, τῆς δʼ ἑτέρας ἐν ἐλάττονι μοίρᾳ τυγχανούσης, ἂν ὁ ἐκ τῆς ἀγαπωμένης παῖς γενόμενος νεώτερος ὢν τοῦ ἐκ τῆς ἑτέρας φύντος ἀξιοῖ διὰ τὴν πρὸς τὴν μητέρα τοῦ πατρὸς εὔνοιαν τῶν πρεσβείων τυγχάνειν, ὥστε διπλοῦν τὸ μέρος τῆς πατρῴας οὐσίας ἐκλαμβάνειν, τοῦτο γὰρ ἐν τοῖς νόμοις διεταξάμην, μὴ συγκεχωρήσθω·"},{"number":250,"text":"ἄδικον γὰρ τὸν τῇ γενέσει πρεσβύτερον, ὅτι τὰ τῆς μητρὸς αὐτῷ ἥττονα παρὰ τῇ διαθέσει τοῦ πατρός, τῶν ὀφειλομένων αὐτῷ στερεῖσθαι."},{"number":251,"text":"ὁ κόρην ἄλλῳ κατηγγυημένην φθείρας, εἰ μὲν πείσας καὶ πρὸς τὴν φθορὰν συγκάταινον λαβών, ἀποθνησκέτω σὺν αὐτῇ· πονηροὶ γὰρ ὁμοίως ἑκάτεροι, ὁ μὲν τὸ αἴσχιστον πείσας ἑκουσίως ὑπομεῖναι καὶ προτιμῆσαι τοῦτο τοῦ ἐλευθέρου γάμου τὴν κόρην, ἡ δὲ παρασχεῖν ἑαυτὴν πεισθεῖσα διʼ ἡδονὴν ἢ διὰ κέρδος πρὸς τὴν ὕβριν·"},{"number":252,"text":"ἐὰν δέ που μόνῃ περιπεσὼν βιάσηται μηδενὸς βοηθοῦ παρόντος, μόνος ἀποθνησκέτω. ὁ φθείρας παρθένον μήπω κατηγγυημένην αὐτὸς γαμείτω· ἢν δὲ τῷ πατρὶ τῆς κόρης μὴ δόξῃ συνοικίζειν αὐτῷ, πεντήκοντα σίκλους τιμὴν τῆς ὕβρεως καταβαλλέτω."},{"number":253,"text":"γυναικὸς δὲ τῆς συνοικούσης βουλόμενος διαζευχθῆναι καθʼ ἁσδηποτοῦν αἰτίας, πολλαὶ δʼ ἂν τοῖς ἀνθρώποις τοιαῦται γίγνοιντο, γράμμασι μὲν περὶ τοῦ μηδέποτε συνελθεῖν ἰσχυριζέσθω· λάβοι γὰρ ἂν οὕτως ἐξουσίαν συνοικεῖν ἑτέρῳ, πρότερον γὰρ οὐκ ἐφετέον· εἰ δὲ καὶ πρὸς ἐκεῖνον κακωθείη καὶ τελευτήσαντος αὐτοῦ θελήσειε γαμεῖν ὁ πρότερος, μὴ ἐξεῖναι αὐτῇ ἐπανιέναι."},{"number":254,"text":"τὴν ἄτεκνον τἀνδρὸς αὐτῇ τετελευτηκότος ὁ ἀδελφὸς ἐκείνου γαμείτω καὶ τὸν παῖδα τὸν γενόμενον τῷ τοῦ τεθνεῶτος καλέσας ὀνόματι τρεφέτω τοῦ κλήρου διάδοχον· τοῦτο γὰρ καὶ τοῖς δημοσίοις λυσιτελήσει γιγνόμενον τῶν οἴκων οὐκ ἐκλειπόντων καὶ τῶν χρημάτων τοῖς συγγενέσι μενόντων, καὶ ταῖς γυναιξὶ κουφισμὸν οἴσει τῆς συμφορᾶς τοῖς ἔγγιστα τῶν προτέρων ἀνδρῶν συνοικούσαις."},{"number":255,"text":"ἐὰν δὲ μὴ βούληται γαμεῖν ὁ ἀδελφός, ἐπὶ τὴν γερουσίαν ἐλθοῦσα ἡ γυνὴ μαρτυράσθω τοῦθʼ, ὅτι βουλομένην αὐτὴν ἐπὶ τοῦ οἴκου μένειν καὶ τεκνοῦν ἐξ αὐτοῦ μὴ προσδέχοιτο ὑβρίζων τὴν τοῦ τεθνηκότος ἀδελφοῦ μνήμην. ἐρομένης δὲ τῆς γερουσίας, διὰ ποίαν αἰτίαν ἀλλοτρίως ἔχοι πρὸς τὸν γάμον, ἄν τε μικρὰν ἄν τε μείζω λέγῃ, πρὸς ταῦτα ῥεπέτω·"},{"number":256,"text":"ὑπολύσασα δʼ αὐτὸν ἡ γυνὴ τἀδελφοῦ τὰ σάνδαλα, καὶ πτύουσα αὐτοῦ εἰς τὸ πρόσωπον τούτων αὐτὸν ἄξιον εἶναι παρʼ αὐτῆς λεγέτω τυγχάνειν ὑβρίσαντα τὴν τοῦ κατοιχομένου μνήμην. καὶ ὁ μὲν ἐκ τῆς γερουσίας ἀπίτω τοῦτʼ ἔχων ὄνειδος πρὸς ἅπαντα τὸν βίον, ἡ δʼ ᾧπερ ἂν βουληθῇ τινι τῶν δεομένων γαμείσθω."},{"number":257,"text":"ἂν δʼ αἰχμάλωτόν τις λάβῃ παρθένον ἄν τε καὶ γεγαμημένην, βουλομένῳ συνοικεῖν μὴ πρότερον ἐξέστω εὐνῆς ἅψασθαι καὶ κοινωνίας, πρὶν ἢ ξυραμένην αὐτὴν καὶ πένθιμον σχῆμα ἀναλαβοῦσαν ἀποθρηνῆσαι συγγενεῖς καὶ φίλους τοὺς ἀπολωλότας ἐν τῇ μάχῃ,"},{"number":258,"text":"ὅπως τὸ ἐπʼ αὐτοῖς κορέσασα λυπηρὸν ἔπειθʼ οὕτως ἐπʼ εὐωχίας τράπηται καὶ γάμους· καλὸν γὰρ εἶναι καὶ δίκαιον παιδοποιὸν παραλαμβάνοντα θεραπεύειν αὐτῆς τὸ βουλητὸν, ἀλλὰ μὴ τὴν ἰδίαν ἡδονὴν διώκοντα μόνον τοῦ κατʼ αὐτὴν ἀμελεῖν κεχαρισμένου."},{"number":259,"text":"τριάκοντα δʼ ἡμερῶν τῷ πένθει διελθουσῶν, αὐτάρκεις γὰρ ἐπὶ τοῖς δακρύοις αὗται τῶν φιλτάτων ταῖς φρονίμοις, τότε χωρεῖν ἐπὶ τὸν γάμον. εἰ δʼ ἐμπλησθεὶς τῆς ἐπιθυμίας ὑπερηφανεύσειεν αὐτὴν γαμετὴν ἔχειν, μηκέτʼ ἐξουσίαν ἐχέτω καταδουλοῦν αὐτήν, ἀλλʼ ὅπη βούλεται χωρεῖν ἀπίτω τοῦτο ἐλεύθερον ἔχουσα."},{"number":260,"text":"Ὅσοι δʼ ἂν τῶν νέων περιφρονῶσι τοὺς γονεῖς καὶ τὴν τιμὴν αὐτοῖς μὴ νέμωσιν ἢ διʼ αἰσχύνην ἢ διὰ σύνεσιν ἐξυβρίζοντες εἰς αὐτούς, πρῶτον μὲν λόγοις αὐτοὺς νουθετείτωσαν οἱ πατέρες, αὐτάρκεις γὰρ ἐφʼ υἱάσιν οὗτοι δικασταί,"},{"number":261,"text":"συνελθεῖν μὲν ἀλλήλοις οὐχ ἡδονῆς ἕνεκα λέγοντες οὐδὲ τῆς τῶν χρημάτων αὐξήσεως κοινῶν τῶν ἑκατέροις ὑπαρχόντων γενομένων, ἀλλʼ ὅπως παίδων τύχωσιν, οἳ γηρωκομήσουσιν αὐτοὺς καὶ ὧν ἂν δέωνται παρʼ αὐτῶν ἕξουσι, γενόμενόν τε μετὰ χαρᾶς καὶ τοῦ τῷ θεῷ χάριν εἰδέναι τὴν μεγίστην ἀράμενοι διὰ σπουδῆς ἀνεθρέψαμεν μηδενὸς φειδὼ ποιούμενοι τοῦ καὶ δόξαντος εἰς σωτηρίαν τὴν σὴν καὶ παιδείαν τῶν ἀρίστων εἶναι χρησίμου."},{"number":262,"text":"νῦν δέ, συγγνώμην γὰρ χρὴ νέμειν ἐφʼ ἁμαρτήμασι νέων, ἀπόχρη σοι ὅσα τῆς εἰς ἡμᾶς τιμῆς ὠλιγώρησας, καὶ μεταβαλοῦ πρὸς τὸ σωφρονέστερον λογισάμενος καὶ τὸν θεὸν ἐπὶ τοῖς εἰς πατέρας τολμωμένοις χαλεπῶς ἔχειν, ὅτι καὶ αὐτὸς πατὴρ τοῦ παντὸς ἀνθρώπων γένους ἐστὶ καὶ συνατιμοῦσθαι δοκεῖ τοῖς τὴν αὐτὴν αὐτῷ προσηγορίαν ἔχουσιν οὐχ ὧν προσῆκεν αὐτοῖς παρὰ τῶν παίδων τυγχανόντων, καὶ νόμος κολαστὴς γίνεται τῶν τοιούτων ἀπαραίτητος, οὗ σὺ μὴ πειραθείης."},{"number":263,"text":"κἂν μὲν τούτοις θεραπεύηται τὸ τῶν νέων αὔθαδες, ἀπαλλαττέσθωσαν τῶν ἐπὶ τοῖς ἠγνοημένοις ὀνειδῶν. οὕτως γὰρ ἂν ὅ τε νομοθέτης ἀγαθὸς εἴη καὶ οἱ πατέρες εὐτυχεῖς οὐκ ἐπιδόντες οὔτε υἱὸν κολαζόμενον οὔτε θυγατέρα."},{"number":264,"text":"οὐδʼ ἂν οἱ λόγοι καὶ ἡ παρʼ αὐτῶν διδασκαλία τοῦ σωφρονεῖν τὸ μηδὲν εἶναι φανῶσιν, ἐχθροὺς δʼ ἀσπόνδους αὑτῷ ποιῇ τοὺς νόμους τοῖς συνεχέσι κατὰ τῶν γονέων τολμήμασι, προαχθεὶς ὑπʼ αὐτῶν τούτων ἔξω τῆς πόλεως τοῦ πλήθους ἑπομένου καταλευέσθω καὶ μείνας διʼ ὅλης τῆς ἡμέρας εἰς θέαν τὴν ἁπάντων θαπτέσθω νυκτός."},{"number":265,"text":"οὕτως δὲ καὶ οἱ ὁπωσοῦν ὑπὸ τῶν νόμων ἀναιρεθῆναι κατακριθέντες. θαπτέσθωσαν δὲ καὶ οἱ πολέμιοι καὶ νεκρὸς μηδὲ εἷς ἄμοιρος γῆς κείσθω περαιτέρω τοῦ δικαίου τιμωρίαν ἐκτίνων."},{"number":266,"text":"Δανείζειν δʼ Ἑβραίων ἐπὶ τόκοις ἐξέστω μηδενὶ μήτε βρωτὸν μήτε ποτόν· οὐ γὰρ δίκαιον προσοδεύεσθαι τοῦ ὁμοφύλου τὰς τύχας, ἀλλὰ βοηθήσαντας ταῖς χρείαις αὐτοῦ κέρδος εἶναι νομίζειν τήν τʼ ἐκείνων εὐχαριστίαν καὶ τὴν ἀμοιβὴν τὴν παρὰ τοῦ θεοῦ γενησομένην ἐπὶ τῇ χρηστότητι."},{"number":267,"text":"Οἱ δὲ λαβόντες εἴτε ἀργύρια εἴτε τινὰ τῶν καρπῶν ὑγρὸν ἢ ξηρόν, κατὰ νοῦν αὐτοῖς τῶν παρὰ τοῦ θεοῦ χωρησάντων κομίζοντες μεθʼ ἡδονῆς ἀποδιδότωσαν τοῖς δοῦσιν ὥσπερ ἀποθέμενοι εἰς τὰ αὑτῶν καὶ πάλιν εἰ δεηθεῖεν ἕξοντες."},{"number":268,"text":"ἂν δὲ ἀναισχυντῶσι περὶ τὴν ἀπόδοσιν, μὴ περὶ τὴν οἰκίαν βαδίσαντας ἐνεχυριάζειν πρὶν ἢ δίκη περὶ τούτου γένηται· τὸ δʼ ἐνέχυρον αἰτεῖν ἔξω καὶ τὸν ὀφείλοντα κομίζειν διʼ αὐτοῦ μηδὲν ἀντιλέγοντα τῷ μετὰ νόμου βοηθείας ἐπʼ αὐτὸν ἥκοντι."},{"number":269,"text":"κἂν μὲν εὔπορος ᾖ ὁ ἐνεχυρασμένος, κατεχέτω τοῦτο μέχρι τῆς ἀποδόσεως ὁ δεδανεικώς, ἂν δὲ πένης, ἀποτιθέτω πρὶν ἡλίου δυσμῶν, καὶ μάλιστʼ ἂν ἱμάτιον ᾖ τὸ ἐνέχυρον, ὅπως εἰς ὕπνον ἔχῃ τοῦτο, φύσει τοῦ θεοῦ τοῖς πενομένοις ἔλεον νέμοντος."},{"number":270,"text":"μύλην δὲ καὶ τὰ περὶ ταύτην σκεύη μὴ ἐξεῖναι λαμβάνειν ἐνέχυρον, ὅπως μὴ στερῶνται καὶ τῶν πρὸς τὰ σιτία ὀργάνων μηδʼ ὑπʼ ἐνδείας πάθωσί τι τῶν χειρόνων."},{"number":271,"text":"Ἐπʼ ἀνθρώπου μὲν κλοπῇ θάνατος ἔστω ζημία, ὁ δὲ χρυσὸν ἢ ἄργυρον ὑφελόμενος τὸ διπλοῦν ἀποτινέτω. κτείνας δʼ ἐπὶ τοῖς κατʼ οἶκον κλεπτομένοις τις ἀθῷος ἔστω κἂν εἰ πρὸς διορύγματι τειχίου."},{"number":272,"text":"βόσκημα δὲ ὁ κλέψας τετραπλῆν τὴν ζημίαν ἀποτινέτω πλὴν βοός, πενταπλῆν δʼ ὑπὲρ τούτου καταβαλλέτω. ὁ δὲ τὸ ἐπιτίμιον ἄπορος διαλύσασθαι δοῦλος ἔστω τοῖς καταδεδικασμένοις."},{"number":273,"text":"Πραθεὶς δὲ ὁμοφύλῳ τις ἓξ ἔτη δουλευέτω, τῷ δʼ ἑβδόμῳ ἐλεύθερος ἀφείσθω· ἐὰν δὲ τέκνων αὐτῷ γενομένων ἐκ δούλης παρὰ τῷ πριαμένῳ διὰ τὴν εὔνοιαν καὶ τὴν πρὸς τὰ οἰκεῖα φιλοστοργίαν βούληται δουλεύειν, ἐνιαυτοῦ ἐνστάντος τοῦ ἰοβήλου, πεντηκοστὸς δὲ ἐνιαυτός ἐστιν, ἐλευθερούσθω καὶ τὰ τέκνα καὶ τὴν γυναῖκα ἐλευθέραν ἐπαγόμενος."},{"number":274,"text":"Ἐὰν δέ τις ἢ χρυσίον ἢ ἀργύριον εὕρῃ καθʼ ὁδόν, ἐπιζητήσας τὸν ἀπολωλεκότα καὶ κηρύξας τὸν τόπον ἐν ᾧ εὗρεν ἀποδότω, τὴν ἐκ τῆς ἑτέρου ζημίας ὠφέλειαν οὐκ ἀγαθὴν ὑπολαμβάνων. ὁμοίως καὶ περὶ βοσκημάτων οἷς ἂν ἐντύχῃ τις κατʼ ἐρημίαν πλανωμένοις, μὴ εὑρεθέντος τοῦ κυρίου παραχρῆμα παρʼ αὑτῷ φυλαττέτω μαρτυράμενος τὸν θεὸν μὴ νοσφίζεσθαι ἀλλότρια."},{"number":275,"text":"Μὴ ἐξεῖναι δὲ παριέναι κτηνῶν τινι κακοπαθούντων ὑπὸ χειμῶνος πεπτωκότων ἐν πηλῷ, συνδιασώζειν δὲ καὶ τὸν πόνον οἰκεῖον ἡγησάμενον βοηθεῖν."},{"number":276,"text":"Μηνύειν δὲ καὶ τὰς ὁδοὺς τοῖς ἀγνοοῦσι, καὶ μὴ γέλωτα θηρωμένους αὑτοῖς ἐμποδίζειν πλάνῃ τὴν ἑτέρου χρείαν.\n\nὉμοίως μηδὲ βλασφημείτω τις τὸν ἀπόντα καὶ τὸν ἐνεόν."},{"number":277,"text":"Ἐν μάχῃ τις ὅπου μὴ σίδηρος πληγεὶς παραχρῆμα μὲν ἀποθανὼν ἐκδικείσθω ταὐτὸν παθόντος τοῦ πεπληχότος. ἂν δὲ κομισθεὶς παρʼ ἑαυτὸν καὶ νοσήσας ἐπὶ πλείονας ἡμέρας ἔπειτʼ ἀποθάνῃ, ἀθῷος ἔστω ὁ πλήξας, σωθέντος δὲ καὶ πολλὰ δαπανήσαντος εἰς τὴν νοσηλείαν ἀποτινέτω πάνθʼ ὅσα παρὰ τὸν χρόνον τῆς κατακλίσεως ἀνάλωσε καὶ ὅσα τοῖς ἰατροῖς ἔδωκεν."},{"number":278,"text":"ὁ γυναῖκα λακτίσας ἔγκυον, ἂν μὲν ἐξαμβλώσῃ ἡ γυνὴ ζημιούσθω χρήμασιν ὑπὸ τῶν δικαστῶν ὡς παρὰ τὸ διαφθαρὲν ἐν τῇ γαστρὶ μειώσας τὸ πλῆθος, διδόσθω δὲ καὶ τῷ ἀνδρὶ τῆς γυναικὸς παρʼ αὐτοῦ χρήματα· θνησκούσης δʼ ἐκ τῆς πληγῆς καὶ αὐτὸς ἀποθνησκέτω ψυχὴν ἀντὶ ψυχῆς καταθέσθαι δικαιοῦντος τοῦ νόμου."},{"number":279,"text":"Φάρμακον μήτε θανάσιμον μήτε τῶν εἰς ἄλλας βλάβας πεποιημένων Ἰσραηλιτῶν ἐχέτω μηδὲ εἷς· ἐὰν δὲ κεκτημένος φωραθῇ τεθνάτω, τοῦτο πάσχων ὃ διέθηκεν ἂν ἐκείνους καθʼ ὧν τὸ φάρμακον ἦν παρεσκευασμένον."},{"number":280,"text":"Πηρώσας πασχέτω τὰ ὅμοια στερούμενος οὗπερ ἄλλον ἐστέρησε, πλὴν εἰ μήτι χρήματα λαβεῖν ἐθελήσειεν ὁ πεπηρωμένος, αὐτὸν τὸν πεπονθότα κύριον τοῦ νόμου ποιοῦντος τιμήσασθαι τὸ συμβεβηκὸς αὐτῷ πάθος καὶ συγχωροῦντος, εἰ μὴ βούλεται γενέσθαι πικρότερος."},{"number":281,"text":"Βοῦν τοῖς κέρασι πλήττοντα ὁ δεσπότης ἀποσφαττέτω· εἰ δʼ ἐφʼ ἅλωος κτείνειέ τινα πλήξας, αὐτὸς μὲν καταλευσθεὶς ἀποθνησκέτω μηδʼ εἰς τροφὴν εὔχρηστος εἶναι κατηξιωμένος, ἐὰν δὲ καὶ ὁ δεσπότης ἐλέγχηται προειδὼς αὐτοῦ τὴν φύσιν καὶ μὴ φυλαξάμενος, ἀποθνησκέτω ὡς αἴτιος τῷ ὑπὸ τοῦ βοὸς ἀνῃρημένῳ γεγενημένος."},{"number":282,"text":"ἐὰν δὲ δοῦλον ἢ θεράπαιναν ἀποκτείνῃ βοῦς, αὐτὸς μὲν καταλιθούσθω, τριάκοντα δὲ σίκλους ὁ κύριος τοῦ βοὸς ἀποτινέτω τῷ δεσπότῃ τοῦ ἀνῃρημένου. βοῦς δὲ ἐὰν οὕτως πληγεὶς ἀποθάνῃ, πωλείσθωσαν καὶ ὁ τεθνεὼς καὶ ὁ πλήξας καὶ τὴν τιμὴν τὴν ἀμφοτέρων οἱ δεσπόται αὐτῶν διανεμέσθωσαν."},{"number":283,"text":"Οἱ φρέαρ ἢ λάκκον ὀρύξαντες ἐπιμελὲς ποιείσθωσαν ὥστε σανίδων ἐπιβολαῖς ἔχειν κεκλεισμένα, οὐχ ὅπως τινὲς εἴργοιντο ὑδρείας, ἀλλʼ ἵνα μηδεὶς κίνδυνος ὡς ἐμπεσουμένοις ᾖ."},{"number":284,"text":"οὗ δʼ ἂν εἰς ὄρυγμα τοιοῦτον μὴ κλειστὸν ἐμπεσὸν βόσκημά τινος διαφθαρῇ, τὴν τιμὴν αὐτοῦ τῷ δεσπότῃ καταβαλλέτω. περιβαλλέσθω δὲ καὶ τοῖς στέγεσιν ἅπερ ὡς ἀντὶ τείχους ὄντα οὐκ ἐάσει τινὰς ἀποκυλισθέντας ἀπολέσθαι."},{"number":285,"text":"Παρακαταθήκην δὲ ὥσπερ ἱερόν τι καὶ θεῖον χρῆμα ὁ παραλαβὼν φυλακῆς ἀξιούτω, καὶ μηδεὶς ἀποστερῆσαι θρασυνθείη τὸν πεπιστευκότα μήτʼ ἀνὴρ μήτε γυνή, μηδʼ εἰ χρυσὸν ἄπειρον μέλλοι κερδαίνειν, καταφρονῶν τῷ μηδένα εἶναι τὸν ἐξελέγξοντα."},{"number":286,"text":"καθόλου μὲν γὰρ τὸ συνειδὸς ἐπιστάμενον τὸ αὐτοῦ προσῆκεν ἕκαστον εὖ πράττειν, καὶ μάρτυρι ἀρκούμενος αὐτῷ πάντα ποιείτω ἃ παρʼ ἄλλων ἔπαινον αὐτῷ παρέξει, μάλιστα δὲ τὸν θεόν, ὃν οὐδεὶς πονηρὸς ὢν λανθάνει."},{"number":287,"text":"εἰ δὲ μηδὲν ἐπίβουλον δρῶν ὁ πιστευθεὶς ἀπολέσειεν, ἀφικόμενος ἐπὶ τοὺς ἑπτὰ κριτὰς ὀμνύτω τὸν θεόν, ὅτι μηδὲν παρὰ τὴν αὐτοῦ βούλησιν ἀπόλοιτο καὶ κακίαν οὐδὲ χρησαμένου τινὶ μέρει αὐτῆς, καὶ οὕτως ἀνεπαιτίατος ἀπίτω. χρησάμενος δὲ κἂν ἐλαχίστῳ μέρει τῶν πεπιστευμένων ἂν ἀπολέσας τύχῃ τὰ λοιπὰ πάντα ἃ ἔλαβεν ἀποδοῦναι κατεγνώσθω."},{"number":288,"text":"ὁμοίως δὲ τῷ περὶ παρακαταθηκῶν κἂν μισθόν τις ἀποστερήσῃ τῶν ἐπὶ σώμασι τοῖς αὐτῶν ἐργαζομένων, μεμισήσθω. ὅθεν οὐκ ἀποστερητέον ἀνδρὸς πένητος μισθὸν εἰδότας, ὡς ἀντὶ γῆς καὶ τῶν ἄλλων κτημάτων ὁ θεὸς αὐτῷ τοῦτον εἴη παρεσχηκώς· ἀλλὰ μηδὲ ἀναβάλλεσθαι τὴν ἀπόδοσιν, ἀλλʼ αὐθημερὸν ἐκτίνειν ὡς οὐ βουλομένου τοῦ θεοῦ τῆς ἐξ ὧν πεπόνηκε χρήσεως ὑστερεῖν τὸν ἐργασάμενον."},{"number":289,"text":"Παῖδας ὑπὲρ ἀδικίας πατέρων μὴ κολάζειν, ἀλλὰ διὰ τὴν ἐκείνων αὐτῶν ἀρετὴν οἴκτου μᾶλλον ἀξιοῦν, ὅτι μοχθηρῶν ἐγένοντο πατέρων, ἢ μίσους φύντας ἐκ φαύλων. οὐ μὴν οὐδὲ πατράσιν υἱῶν ἁμαρτίαν λογιστέον τῶν νέων πολλὰ παρὰ τὴν ἡμετέραν διδασκαλίαν αὐτοῖς ἐπιτρεπόντων ὑπερηφανίᾳ τοῦ διδάσκεσθαι."},{"number":290,"text":"Γάλλους ἐκτρέπεσθαι καὶ σύνοδον φεύγειν τὴν μετʼ αὐτῶν ἀφελομένων αὑτοὺς τὸ ἄρρεν καὶ τὸν τῆς παιδοποιίας καρπόν, ὃν ἀνθρώποις ἐπʼ αὐξήσει τοῦ γένους ἡμῖν ὁ θεὸς παρέσχεν, ἐλαύνειν δὲ οὕτως ὡς ἐπὶ τέκνων σφαγῇ καὶ πρὸς τούτῳ ἀπολλύντας τὸ ἐκείνων αἴτιον·"},{"number":291,"text":"δῆλον γάρ, ὡς τῆς ψυχῆς αὐτοῖς τεθηλυσμένης μετεκοσμήσαντο πρὸς τοῦτο καὶ τὸ σῶμα· ὁμοίως δὲ καὶ πᾶν τὸ νομιζόμενον τέρας τοῖς ὁρῶσι. μὴ ἐξεῖναι δὲ ποιεῖν ἐκτομίας μήτε ἀνθρώπους μήτε τῶν ἄλλων ζῴων."},{"number":292,"text":"Αὕτη μὲν οὖν ὑμῖν εἰρηνικὴ τῶν νόμων κατὰ τὴν πολιτείαν διάταξις ἔστω· καὶ ὁ θεὸς εὐμενὴς ἀστασίαστον αὐτῆς τὸν κόσμον παρέξεται, γένοιτο δὲ χρόνος μηδὲ εἷς, ὃς καινίσει τι τούτων καὶ πρὸς τὸ ἐναντίον μεταβαλεῖ."},{"number":293,"text":"ἐπεὶ δὲ ἀνάγκη τὸ ἀνθρώπειον καὶ εἰς ἀβουλήτους ἢ κατὰ προαίρεσιν ταραχὰς καὶ κινδύνους ἐμπεσεῖν, φέρε καὶ περὶ τούτων βραχέα προσδιατάξωμεν, ὡς ἂν προειδότες ἃ χρὴ ποιεῖν ἐν τῇ χρείᾳ τῶν σωτηρίων εὐπορῆτε καὶ μὴ τότε ἃ δεῖ ποιεῖν ἐπιζητοῦντες ἀπαρασκεύαστοι τοῖς καιροῖς περιπέσητε."},{"number":294,"text":"Γῆν ὑμῖν ἣν ὁ θεὸς ἔδωκε πόνων καταφρονοῦσι καὶ ψυχὰς πρὸς ἀρετὴν ἠσκημένοις ἀπόλεμον μὲν νέμεσθαι παράσχοι τε κεκτημένοις αὐτὴν μήτε ἀλλοτρίων εἰς αὐτὴν ἐπὶ κακώσει στρατευσάντων μήτε στάσεως ἐμφυλίου κατασχούσης ὑμᾶς,"},{"number":295,"text":"ὑφʼ ἧς τἀναντία πατράσι τοῖς ἑαυτῶν πράττοντες ἀπολεῖτε τὰ ἐκείνοις νομισθέντα, χρώμενοί τε νόμοις οὓς ἀγαθοὺς δοκιμάσας ὁ θεὸς παραδίδωσι διατελοίητε· ἔργον δʼ ὅτι ἂν πολεμικὸν ἢ νῦν ὑφʼ ὑμῶν ἢ ὕστερον ἐπὶ παίδων ὑμετέρων γένηται τοῦθʼ ὑπερόριον πραχθείη."},{"number":296,"text":"μέλλοντας δὲ πολεμεῖν πρεσβείαν καὶ κήρυκας πέμπειν παρὰ τοὺς ἑκουσίως πολεμίους· πρὸ γὰρ τῶν ὅπλων καλὸν εἶναι χρῆσθαι λόγοις πρὸς αὐτοὺς δηλοῦντας, ὅτι καὶ στρατιὰν πολλὴν ἔχοντες καὶ ἵππους καὶ ὅπλα καὶ πρὸ τούτων εὐμενῆ τὸν θεὸν καὶ σύμμαχον, ὅμως ἀξιοῦτε μὴ ἀναγκάζεσθαι πολεμεῖν αὐτοῖς μηδὲ τὰ ἐκείνων ἀφαιρουμένους ἀβούλητον αὑτοῖς κέρδος προσλαμβάνειν."},{"number":297,"text":"καὶ πειθομένων μὲν καλῶς ὑμᾶς ἔχειν τὴν εἰρήνην φυλάττειν, εἰ δὲ φρονοῦντες ἐφʼ ἑαυτοῖς ὡς ἰσχύι διαφέρουσιν ἀδικεῖν ἐθέλοιεν, στρατὸν ἐπʼ αὐτοὺς ἀγάγοιτε, στρατηγῷ μὲν αὐτοκράτορι χρώμενοι τῷ θεῷ, ὑποστράτηγον δὲ χειροτονήσαντες ἕνα τὸν ἀρετῇ προύχοντα· πολυαρχία γὰρ πρὸς τῷ τοῖς ὀξέως τι πράττειν ἀνάγκην ἔχουσιν ἐμπόδιον εἶναι καὶ βλάπτειν πέφυκε τοὺς χρωμένους."},{"number":298,"text":"στρατὸν δʼ ἄγειν καθαρὸν ἐκ πάντων τῶν ῥώμῃ σωμάτων καὶ ψυχῆς εὐτολμίᾳ διαφερόντων τὸ δειλὸν ἀποκρίναντας, μὴ τοὺς πολεμίους παρὰ τὸ ἔργον τραπὲν εἰς φυγὴν ὠφελήσῃ. τούς τε νεωστὶ δειμαμένους οἰκίας, οἷς οὔπω χρόνος ἀπολαύσεως αὐτῶν ἐνιαύσιος, καὶ φυτεύσαντας οὔπω δὲ καρπῶν μετεσχηκότας, ἐᾶν κατὰ χώραν, καὶ τοὺς μνηστευσαμένους δὲ καὶ νεωστὶ γεγαμηκότας, μὴ πόθῳ τούτων φειδόμενοι τοῦ ζῆν καὶ τηροῦντες αὑτοὺς εἰς τὴν τούτων ἀπόλαυσιν ἐθελοκακήσωσι περὶ τὰς γυναῖκας."},{"number":299,"text":"Στρατοπεδευσάμενοι δὲ προνοεῖσθε, μή τι τῶν δυσχερεστέρων ἐργάσησθε. πολιορκοῦντας δὲ καὶ ξύλων ἀπορουμένους εἰς ποίησιν μηχανημάτων μὴ κείρειν τὴν γῆν ἥμερα δένδρα κόπτοντας ἀλλὰ φείδεσθαι, λογιζομένους ἐπʼ ὠφελείᾳ ταῦτα τῶν ἀνθρώπων γεγονέναι, καὶ φωνῆς ἂν εὐπορήσαντα δικαιολογήσασθαι πρὸς ὑμᾶς, ὡς οὐδὲν αἴτια τοῦ πολέμου γεγονότα πάσχοι κακῶς παρὰ δίκην, εἰ δύναμις αὐτοῖς ἦν καὶ μετοικήσαντα ἂν καὶ πρὸς ἄλλην μεταβάντα γῆν."},{"number":300,"text":"κρατήσαντες δὲ τῇ μάχῃ τοὺς ἀντιταξαμένους κτείνατε, τοὺς δʼ ἄλλους εἰς τὸ τελεῖν ὑμῖν φόρους σώζετε πλὴν τοῦ Χαναναίων ἔθνους τούτους γὰρ πανοικὶ χρῆναι ἀφανίσαι."},{"number":301,"text":"Φυλάσσειν δὲ μάλιστα ἐν ταῖς μάχαις, ὡς μήτε γυναῖκα ἀνδρικῇ σκευῇ χρῆσθαι μήτʼ ἄνδρα στολῇ γυναικείᾳ."},{"number":302,"text":"Πολιτείαν μὲν οὖν τοιάνδε Μωυσῆς κατέλιπε, νόμους δʼ ἔτι πρότερον τεσσαρακοστῷ ἔτει γεγραμμένους παραδίδωσι, περὶ ὧν ἐν ἑτέρᾳ γραφῇ λέξομεν. ταῖς δʼ ἑξῆς ἡμέραις, συνεχὲς γὰρ ἐκκλησίασεν, εὐλογίας αὐτοῖς δίδωσι καὶ κατάρας ἐπὶ τοὺς μὴ κατὰ τοὺς νόμους ζησομένους ἀλλὰ παραβησομένους τὰ ἐν αὐτοῖς διωρισμένα."},{"number":303,"text":"ἔπειτα ποίησιν ἑξάμετρον αὐτοῖς ἀνέγνω, ἣν καὶ καταλέλοιπεν ἐν βίβλῳ ἐν τῷ ἱερῷ πρόρρησιν περιέχουσαν τῶν ἐσομένων, καθʼ ἣν καὶ γέγονε τὰ πάντα καὶ γίνεται, μηδὲν ἐκείνου διημαρτηκότος τῆς ἀληθείας."},{"number":304,"text":"ταῦτʼ οὖν τὰ βιβλία παραδίδωσι τοῖς ἱερεῦσι καὶ τὴν κιβωτόν, εἰς ἣν καὶ τοὺς δέκα λόγους γεγραμμένους ἐν δυσὶ πλαξὶ κατέθετο, καὶ τὴν σκηνήν· τῷ τε λαῷ παρῄνεσε κρατήσαντι τῆς γῆς καὶ ἱδρυθέντι μὴ λήθην λαβεῖν τῆς Ἀμαληκιτῶν ὕβρεως, ἀλλὰ στρατεύσαντας ἐπʼ αὐτοὺς τιμωρίαν ἀπολαβεῖν ὧν ἐπὶ τῆς ἐρήμου τυγχάνοντας ἐποίησαν κακῶς,"},{"number":305,"text":"ἐξελόντας δὲ τὴν Χαναναίων γῆν καὶ πᾶσαν διαφθείραντας τὴν ἐν αὐτῇ πληθὺν καθὰ πρέπει, τὸν βωμόν τε ἀναστῆσαι πρὸς ἥλιον ἀνίσχοντα τετραμμένον οὐ πόρρω τῆς Σικιμίων πόλεως ἐμπεριάγειν μεταξὺ δυοῖν ὀροῖν, Γριζαίου μὲν τοῦ ἐκ δεξιῶν κειμένου, τοῦ δʼ ἐκ λαιῶν Βουλῆ προσαγορευομένου, μερισθεῖσαν δὲ τὴν στρατιὰν καθʼ ἓξ φυλὰς ἐπὶ τοῖν δυοῖν ὀροῖν ἀναστῆναι καὶ σὺν αὐτοῖς Λευίτας τε καὶ ἱερέας."},{"number":306,"text":"καὶ πρώτους μὲν τοὺς ἐπὶ τῷ Γρίζειν γενομένους εὔχεσθαι τὰ κάλλιστα τοῖς περὶ τὴν θρησκείαν τοῦ θεοῦ καὶ τὴν τῶν νόμων φυλακὴν σπουδάσασιν ὧν τε Μωυσῆς εἶπε μὴ παρακουσαμένοις, εὐφημεῖν δὲ τὰς ἑτέρας, καὶ τούτων πάλιν εὐχομένων τὰς προηγμένας ἐπαινεῖν·"},{"number":307,"text":"ἔπειτα κατὰ ταὐτὰ τοῖς παραβησομένοις κατάρας τίθεσθαι ὑποφωνούσας ἀλλήλαις ἐπὶ τῇ κυρώσει τῶν λεγομένων. ἀνέγραψε δὲ τὰς εὐλογίας καὶ τὰς κατάρας αὐτός, ὡς μηδέποτε ἐκλιπεῖν τὴν μάθησιν αὐτῶν ὑπὸ τοῦ χρόνου,"},{"number":308,"text":"ἃς δὴ καὶ τῷ βωμῷ τελευτῶν ἐνέγραψε κατὰ πλευρὰν ἑκατέραν, ᾗ καὶ στάντα φησὶ τὸν λαὸν θῦσαί τε καὶ ὁλοκαυτῶσαι καὶ μετʼ ἐκείνην τὴν ἡμέραν οὐκ ἐπενεγκεῖν ἱερεῖον ἕτερον, οὐ γὰρ εἶναι νόμιμον. ταῦτʼ οὖν Μωυσῆς διέταξε καὶ τὸ Ἑβραίων ἔθνος ἀκόλουθα τούτοις ποιοῦν διατελεῖ."},{"number":309,"text":"Τῇ δʼ ὑστεραίᾳ τὸν λαὸν σὺν γυναιξὶν ἅμα καὶ τέκνοις εἰς ἐκκλησίαν συναγαγών, ὡς παρεῖναι καὶ τὰ ἀνδράποδα, ὥρκου τῶν νόμων αὐτοὺς φυλακὴν ποιήσασθαι καὶ τῆς τοῦ θεοῦ διανοίας ἀκριβεῖς λογιστὰς γινομένους εἰ μηδὲν εἰς αὐτοὺς μήτε συγγενείᾳ χαριζομένους μήτε εἴκοντας φόβῳ μήτε ἄλλην καθάπαξ αἰτίαν κυριωτέραν τῆς τῶν νόμων φυλακῆς ὑπολαμβάνοντας παραβῆναι τούτους,"},{"number":310,"text":"ἀλλʼ ἄν τέ τις τῶν ἐξ αἵματος συγχεῖν καὶ καταλύειν ἐπιχειρῇ τὴν κατʼ αὐτοὺς πολιτείαν ἄν τε πόλις, ἀμύνειν αὐτοῖς καὶ κοινῇ καὶ κατʼ ἰδίαν, καὶ κρατήσαντας μὲν ἐξ αὐτῶν ἀνασπᾶν θεμελίων καὶ μηδὲ τὸ ἔδαφος τῶν ἀπονοηθέντων εἰ δυνατὸν καταλιπεῖν, εἰ δʼ ἀσθενοῖεν λαβεῖν τὴν τιμωρίαν, αὐτὸ τὸ μὴ κατὰ βούλησιν ἰδίαν ταῦτα γίνεσθαι δεικνύναι. καὶ τὸ μὲν πλῆθος ὤμνυεν."},{"number":311,"text":"Ἐδίδασκε δὲ αὐτούς, ὡς ἂν αἱ θυσίαι τῷ θεῷ μᾶλλον κεχαρισμέναι γένοιντο καὶ ὅπως ἂν οἱ στρατεύοντες ἐξίοιεν τεκμηρίῳ χρώμενοι τοῖς λίθοις, ὡς καὶ πρότερον δεδήλωκα. προεφήτευσε δὲ καὶ Ἰησοῦς Μωυσέος παρόντος."},{"number":312,"text":"ἔπειτα πάνθʼ ὅσα ποιήσειεν ὑπὲρ τῆς τοῦ λαοῦ σωτηρίας ἔν τε πολέμοις καὶ κατʼ εἰρήνην νόμους τε συντιθεὶς καὶ τὸν τῆς πολιτείας κόσμον συμπορίζων ἀναλογιζόμενος προεῖπεν, ὡς δηλώσειεν αὐτῷ τὸ θεῖον, ὅτι παραβάντες τὴν πρὸς αὐτὸν θρησκείαν πειραθήσονται κακῶν,"},{"number":313,"text":"ὡς ὅπλων τε αὐτοῖς πολεμίων πληρωθῆναι τὴν γῆν καὶ κατασκαφῆναι πόλεις καὶ τὸν νεὼν καταπρησθῆναι καὶ πραθέντας δουλεύειν ἀνδράσιν οὐδένα ληψομένοις οἶκτον ἐπὶ ταῖς συμφοραῖς αὐτῶν, μετανοήσειν δʼ αὐτοὺς ἐπὶ μηδενὶ χρησίμῳ ταῦτα πάσχοντας."},{"number":314,"text":"ὁ μέντοι θεὸς ὁ κτίσας ὑμᾶς πόλεις τε πολίταις ὑμετέροις ἀποδώσει καὶ τὸν ναόν· ἔσεσθαι δὲ τὴν τούτων ἀποβολὴν οὐχ ἅπαξ, ἀλλὰ πολλάκις."},{"number":315,"text":"Παρορμήσας οὖν τὸν Ἰησοῦν ἐπὶ τοὺς Χαναναίους στρατιὰν ἐξάγειν, ὡς τοῦ θεοῦ συνεργοῦντος οἷς ἂν ἐπιχειρήσειε, καὶ πᾶσαν ἐπευφημήσας τὴν πληθύν, ἐπεί, φησί, πρὸς τοὺς ἡμετέρους ἄπειμι προγόνους καὶ θεὸς τήνδε μοι τὴν ἡμέραν τῆς πρὸς ἐκείνους ἀφίξεως ὥρισε,"},{"number":316,"text":"χάριν μὲν αὐτῷ ζῶν ἔτι καὶ παρὼν ὑμῖν ἔχειν ὁμολογῶ προνοίας τε τῆς ὑπὲρ ὑμῶν, ἣν οὐχ ὑπὲρ ἀπαλλαγῆς μόνον τῶν ὑμετέρων ἐποιήσατο κακῶν, ἀλλὰ καὶ δωρεᾶς τῶν κρειττόνων, ὅτι τε πονοῦντί μοι καὶ κατὰ πᾶσαν ἐπὶ νοῦν τῆς ἐπὶ τὸ βέλτιον ὑμῶν μεταβολῆς φροντίδα λαμβάνοντι συνηγωνίσατο καὶ παρέσχεν ἐν ἅπασιν αὑτὸν ὑμῖν εὐμενῆ."},{"number":317,"text":"μᾶλλον δʼ αὐτὸς ἦν ὁ καὶ τὴν ἀφήγησιν αὐτῶν διδοὺς καὶ τὰ τέλη χαριζόμενος, ὑποστρατήγῳ χρώμενος ἐμοὶ καὶ ὑπηρέτῃ ὧν τὸν ἡμέτερον λαὸν εὐεργετεῖν ἠθέλησεν."},{"number":318,"text":"ἀνθʼ ὧν προευλογῆσαι τὴν τοῦ θεοῦ δύναμιν, ᾧ μελήσει καὶ πρὸς τὸ μέλλον ὑμῶν, ἀπαλλασσόμενος καλῶς ἔχειν ἡγησάμην, αὐτός τε ταύτην ὀφειλομένην ἀμοιβὴν ἀποδιδοὺς καὶ καταλείπων εἰς μνήμην ὑμῖν τὸ σέβειν τε καὶ τιμᾶν προσήκειν τοῦτον ὑμῖν καὶ τοὺς νόμους πάντων ὧν τε παρέσχηκε καὶ μένων εὐμενὴς ἔτι παρέξει δώρημα κάλλιστον φυλάττειν."},{"number":319,"text":"ὡς δεινὸς μὲν ἐχθρὸς καὶ ἄνθρωπος νομοθέτης ὑβριζομένων αὐτῷ τῶν νόμων καὶ μάτην κειμένων, θεοῦ δὲ μὴ πειραθείητε χαλεπαίνοντος ὑπὲρ ἀμελουμένων νόμων, οὓς αὐτὸς γεννήσας ὑμῖν ἔδωκε."},{"number":320,"text":"Μωυσέος δὲ ταῦτα πρὸς τελευτῇ τοῦ βίου φήσαντος καὶ μετʼ εὐλογίας ἑκάστῃ τῶν φυλῶν προφητεύσαντος τὰ καὶ γενόμενα τὸ πλῆθος εἰς δάκρυα προύπεσεν, ὡς καὶ τὰς γυναῖκας στερνοτυπουμένας ἐμφανίζειν τὸ ἐπʼ αὐτῷ τεθνηξομένῳ πάθος. καὶ οἱ παῖδες δὲ θρηνοῦντες ἔτι μᾶλλον ὡς ἀσθενέστεροι κρατεῖν λύπης ἐδήλουν, ὅτι τῆς ἀρετῆς αὐτοῦ καὶ μεγαλουργίας παρʼ αὐτὴν τὴν ἡλικίαν συνίεσαν."},{"number":321,"text":"ἦν δὲ κατʼ ἐπίνοιαν τοῖς τε νέοις καὶ προηβηκόσιν ἡ ἅμιλλα τῆς λύπης· οἱ μὲν γὰρ εἰδότες οἵου ἐστέρηνται κηδεμόνος περὶ τοῦ μέλλοντος ἀπεθρήνουν, τοῖς δὲ καὶ περὶ τούτου τὸ πένθος ἦν καὶ ὅτι μήπω καλῶς τῆς ἀρετῆς αὐτοῦ γεγευμένοις ἀπολείπεσθαι συνέβαινεν αὐτοῦ."},{"number":322,"text":"τὴν δʼ ὑπερβολὴν τῆς τοῦ πλήθους οἰμωγῆς καὶ τῶν ὀδυρμῶν τεκμαίροιτο ἄν τις ἐκ τοῦ συμβάντος τῷ νομοθέτῃ· καὶ γὰρ πεπεισμένος ἅπαντι τῷ χρόνῳ μὴ δεῖν ἐπὶ μελλούσῃ τελευτῇ κατηφεῖν, ὡς κατὰ βούλησιν αὐτὸ πάσχοντας θεοῦ καὶ φύσεως νόμῳ, ἐπὶ τοῖς ὑπὸ τοῦ λαοῦ πραττομένοις ἐνικήθη δακρῦσαι."},{"number":323,"text":"πορευομένῳ δʼ ἔνθεν οὗ ἔμελλεν ἀφανισθήσεσθαι πάντες εἵποντο δεδακρυμένοι, καὶ Μωυσῆς τοὺς μὲν πόρρω τῇ χειρὶ κατασείων μένειν ἠρεμοῦντας ἐκέλευε, τὸ δʼ ἔγγιον λόγοις παρεκάλει μὴ ποιεῖν αὐτῷ δακρυτὴν τὴν ἀπαλλαγὴν ἑπομένους."},{"number":324,"text":"οἱ δὲ καὶ τοῦτʼ αὐτῷ χαρίζεσθαι κρίνοντες τὸ κατὰ βούλησιν ἀπελθεῖν αὐτῷ τὴν ἰδίαν ἐφεῖναι κατέχουσιν ἑαυτοὺς ἐν ἀλλήλοις δακρύοντες. μόνη δʼ ἡ γερουσία προύπεμψεν αὐτὸν καὶ ὁ ἀρχιερεὺς Ἐλεάζαρος καὶ ὁ στρατηγὸς Ἰησοῦς."},{"number":325,"text":"ὡς δʼ ἐπὶ τῷ ὄρει τῷ Ἀβαρεῖ καλουμένῳ ἐγένετο, τοῦτο δὲ ὑψηλὸν Ἱεριχοῦντος ἀντικρὺ κεῖται γῆν ἀρίστην τῶν Χαναναίων καὶ πλείστην παρέχον τοῖς ἐπʼ αὐτοῦ κατοπτεύειν, ἀπέπεμπε τὴν γερουσίαν."},{"number":326,"text":"ἀσπαζομένου δὲ καὶ τὸν Ἐλεάζαρον αὐτοῦ καὶ τὸν Ἰησοῦν καὶ προσομιλοῦντος ἔτι, νέφους αἰφνίδιον ὑπὲρ αὐτὸν στάντος ἀφανίζεται κατά τινος φάραγγος. γέγραφε δʼ αὑτὸν ἐν ταῖς ἱεραῖς βίβλοις τεθνεῶτα, δείσας μὴ διʼ ὑπερβολὴν τῆς περὶ αὐτὸν ἀρετῆς πρὸς τὸ θεῖον αὐτὸν ἀναχωρῆσαι τολμήσωσιν εἰπεῖν."},{"number":327,"text":"Ἐβίωσε δὲ τὸν πάντα χρόνον ἐτῶν εἴκοσι καὶ ἑκατόν, ὧν ἦρξε τὸ τρίτον μέρος ἑνὶ λείποντι μηνί. ἐτελεύτησε δὲ τῷ ὑστάτῳ μηνὶ τοῦ ἔτους, ὑπὸ μὲν Μακεδόνων Δύστρου καλουμένου Ἀδάρου δʼ ὑφʼ ἡμῶν νουμηνίᾳ,"},{"number":328,"text":"συνέσει τε τοὺς πώποτʼ ἀνθρώπους ὑπερβαλὼν καὶ χρησάμενος ἄριστα τοῖς νοηθεῖσιν, εἰπεῖν τε καὶ πλήθεσιν ὁμιλῆσαι κεχαρισμένος τά τε ἄλλα καὶ τῶν παθῶν αὐτοκράτωρ ,"},{"number":329,"text":"ὡς μηδὲ ἐνεῖναι τούτων τῇ ψυχῇ δοκεῖν αὐτοῦ καὶ γινώσκειν μόνον αὐτῶν τὴν προσηγορίαν ἐκ τοῦ παρʼ ἄλλοις αὐτὰ βλέπειν μᾶλλον ἢ παρʼ αὑτῷ. καὶ στρατηγὸς μὲν ἐν ὀλίγοις, προφήτης δὲ οἷος οὐκ ἄλλος, ὥσθʼ ὅ τι ἂν φθέγξαιτο δοκεῖν αὐτοῦ λέγοντος ἀκροᾶσθαι τοῦ θεοῦ."},{"number":330,"text":"πενθεῖ μὲν οὖν αὐτὸν ὁ λαὸς ἐφʼ ἡμέρας τριάκοντα, λύπη δὲ οὐκ ἄλλη κατέσχεν Ἑβραίους τοσαύτη τὸ μέγεθος, ὅση τότε Μωυσέος ἀποθανόντος."},{"number":331,"text":"ἐπόθουν δʼ αὐτὸν οὐχ οἱ πειραθέντες αὐτοῦ μόνον, ἀλλὰ καὶ οἱ τοῖς νόμοις ἐντυγχάνοντες αὐτοῦ δεινὴν ἐποιοῦντο τὴν ἐπιζήτησιν, τὸ περιὸν αὐτοῦ τῆς ἀρετῆς ἐκ τούτων λογιζόμενοι. καὶ τὸ μὲν κατὰ Μωυσῆν τέλος τοιοῦτον ἡμῖν δεδηλώσθω."}]},"count":331};})();
